# KO / EN visible UI and result text
# The language preference is local-only in no_more_manual_retime_ui.json.
# Stable node/knob names, paths, filenames and editable user text never pass
# through the automatic visible-widget translator.
_UI_LANGUAGE = None
_LANGUAGE_UNSET = object()


def _normalize_ui_language(value):
    """Return the supported language token (ko/en), or None for an unknown value."""
    value = str(value or '').strip().lower().replace('-', '_')
    if value in ('ko', 'kor', 'korean') or value.startswith('ko_'):
        return 'ko'
    if value in ('en', 'eng', 'english') or value.startswith('en_'):
        return 'en'
    return None


def _system_ui_language(locale_name=None, environ=None):
    """First run follows a Korean OS locale; every other locale safely falls back to EN."""
    env = os.environ if environ is None else environ
    requested = _normalize_ui_language(env.get('NMMR_LANGUAGE'))
    if requested:
        return requested
    if locale_name is None:
        locale_name = env.get('LC_ALL') or env.get('LC_MESSAGES') or env.get('LANG')
        if not locale_name:
            try:
                import locale
                locale_name = locale.getlocale()[0] or locale.getdefaultlocale()[0]
            except Exception:
                locale_name = ''
    return 'ko' if _normalize_ui_language(locale_name) == 'ko' else 'en'


def ui_language(saved=_LANGUAGE_UNSET, locale_name=None, environ=None):
    """Current language. A saved local preference wins over the first-run OS choice."""
    global _UI_LANGUAGE
    if saved is not _LANGUAGE_UNSET:
        return _normalize_ui_language(saved) or _system_ui_language(locale_name, environ)
    if _UI_LANGUAGE is None:
        stored = _normalize_ui_language(_ui_get('language'))
        _UI_LANGUAGE = stored or _system_ui_language(locale_name, environ)
    return _UI_LANGUAGE


def set_ui_language(value, persist=True):
    """Set KO/EN immediately and optionally remember it in the existing local UI prefs."""
    global _UI_LANGUAGE
    language = _normalize_ui_language(value)
    if language is None:
        raise ValueError('Unsupported UI language: %s' % value)
    _UI_LANGUAGE = language
    if persist:
        _ui_set('language', language)
    return language


def _t(ko, en=None):
    """Explicit translation boundary for authored visible text only."""
    if ui_language() == 'ko':
        return str(ko)
    return str(en if en is not None else ko)


def _contains_hangul(text):
    return bool(re.search(r'[\uac00-\ud7a3]', str(text or '')))


def tc_agreement(res):
    """(matched, total) of confident burn-in TC frames against the final path when TC was adopted, else None.
    Vetoed and unkept TC frames count as not matched. No new computation of the path."""
    plan = res.get('tc_plan') or {}
    info = res.get('tc') or {}
    if plan.get('mode') != 'first' or info.get('mode') != 'first':
        return None
    total = int(info.get('candidates') or 0)
    if total <= 0:
        return None
    return max(0, int(info.get('used') or 0) - len(info.get('missed') or [])), total


def frame_accuracy_text(res, korean=None):
    """One line: measured TC agreement, or a plain statement that frame accuracy is unknown.
    True frame accuracy needs ground truth, so no number is shown without adopted TC."""
    ko = ui_language() != 'en' if korean is None else korean
    pair = tc_agreement(res)
    if pair:
        pct = int(100.0 * pair[0] / pair[1])  # floor: never shows 100% with a miss
        return (('TC 대조 일치 %d/%d프레임 (%d%%)' if ko else 'TC check matched %d/%d frames (%d%%)') % (pair[0], pair[1], pct))
    if res.get('tc_plan'):
        return '프레임 정확도: TC 미채택, QC로 확인' if ko else 'Frame accuracy: TC not adopted, check QC'
    return '프레임 정확도: 번인 TC 없음, QC로 확인' if ko else 'Frame accuracy: no burn-in TC, check QC'


