def _english_ui_text(text):
    """Translate authored widget copy. Call only for non-editable UI properties."""
    text = str(text or '')
    exact = _UI_TEXT_EN.get(text)
    if exact is not None:
        return exact
    translated = text
    for ko, en in _UI_DYNAMIC_FRAGMENT_EN:
        translated = translated.replace(ko, en)
    for ko, en in _UI_FRAGMENT_EN:
        translated = translated.replace(ko, en)
    return translated


def _english_authored_text(text):
    """Translate exact copy and safe UI phrases while preserving path/name lines."""
    text = str(text or '')
    exact = _UI_TEXT_EN.get(text)
    if exact is not None:
        return exact
    out = []
    for line in text.split('\n'):
        if re.search(r'(^|[/\\]).*\.(exr|dpx|tiff?|png|jpe?g|mov|mp4|mxf|nk)(\b|$)', line, re.I):
            out.append(line)
            continue
        for ko, en in _UI_DYNAMIC_FRAGMENT_EN:
            line = line.replace(ko, en)
        line = re.sub(r'(\d+)프레임\b', r'\1 frames', line)
        out.append(line)
    return '\n'.join(out)


def _visible_ui_text(text):
    text = str(text or '')
    if ui_language() == 'en':
        return _english_ui_text(text)
    reverse = dict((en, ko) for ko, en in _UI_TEXT_EN.items())
    return reverse.get(text, reverse.get(_english_ui_text(text), text))


def batch_display_status(status):
    """Localize authored batch copy without changing the stored state or error data."""
    text = str(status or '')
    if ui_language() != 'en':
        return text
    exact = {
        '대기': 'Waiting', '진행 중': 'In progress', '취소': 'Cancelled',
        '경로 설정 없음': 'Path setup not configured',
        '샷 경로 인식 실패': 'Shot path not recognized',
        '편집본 없음': 'Edit not found',
        '대기 (선택 편집본)': 'Ready (selected edit)',
        '대기 (선택 편집본 · 위치 기준)': 'Ready (selected edit · node-row pairing)',
        '편집본 선택 필요 (같은 이름의 후보 여러 개)': 'Choose an edit (multiple matching names)',
        '편집본 선택 필요 (같은 샷의 후보 여러 개)': 'Choose an edit (multiple shot matches)',
    }
    if text in exact:
        return exact[text]
    for ko, en in (('실패 — ', 'Failed — '), ('건너뜀 — ', 'Skipped — '),
                   ('편집본 찾기 중단 (', 'Edit search stopped (')):
        if text.startswith(ko):
            return en + text[len(ko):]
    if text == '건너뜀':
        return 'Skipped'
    if text.startswith('완료'):
        text = 'Complete' + text[len('완료'):]
        for ko, en in (('일치도 ', 'Similarity '), ('신뢰도 낮음(', 'Low confidence ('),
                       ('TC 불일치 ', 'TC mismatch '), ('분절컷 의심 EDIT ', 'Possible cut EDIT '),
                       ('Beta 출력 보류', 'Beta output held'), ('Beta 출력 검토 필요', 'Beta output needs review'),
                       ('TC 우선 · 고정점 일부 해제 · ', 'TC priority · some anchors released · '),
                       ('TC 우선 · 이미지 약함 · ', 'TC priority · weak image evidence · '),
                       ('TC 우선 · ', 'TC priority · '), ('TC 힌트 · ', 'TC hints · '),
                       ('TC 미사용 · ', 'TC unused · '), ('TC 증가폭 불일치 · 약한 힌트', 'TC increment mismatch · weak hints'),
                       ('TC-그림 불일치 · 미사용', 'TC-image mismatch · unused'),
                       ('프레임 구분 불가 OUT ', 'Indistinguishable frames OUT '),
                       ('정지 구간 근거 부족 OUT ', 'Insufficient hold evidence OUT '),
                       ('정지 구간 근거 약함 ', 'Weak hold evidence: '),
                       ('정지 TC 확정', 'Hold confirmed by TC'), ('정지 고정점 확정', 'Hold confirmed by pins'),
                       ('(확인 필요)', '(review required)'), ('(좋음)', '(Good)'), ('(보통)', '(Fair)'), ('(낮음)', '(Low)')):
            text = text.replace(ko, en)
        text = re.sub(r'TC 오프셋 ([+-]?\d+) 의심 · 미사용', r'Possible TC offset \1 · unused', text)
        text = re.sub(r'TC 대조 일치 (\d+)/(\d+)프레임', r'TC check matched \1/\2 frames', text)
        text = text.replace('프레임 정확도: TC 미채택, QC로 확인', 'Frame accuracy: TC not adopted, check QC')
        text = text.replace('프레임 정확도: 번인 TC 없음, QC로 확인', 'Frame accuracy: no burn-in TC, check QC')
        text = re.sub(r' 외 (\d+)구간', r' +\1 ranges', text)
        text = re.sub(r' 외 (\d+)', r' +\1 more', text)
        text = re.sub(r'확인 (\d+)프레임', r'Review \1 frames', text)
        text = re.sub(r'(?:모호 프레임|품질 낮은 프레임|상하 절반 합의) \d+%|'
                      r'스케일 범위 밖\(필러/레터박스 의심, 탐색 [\d.]+~[\d.]+\)|'
                      r'시간-이동 모호\(플레이트 팬/틸트 \+ 리포지션 이동 애니메이션 — 경로 확인 권장\)',
                      lambda match: _report_detail_text(match.group(0)), text)
    return text


def _retime_unavailable_text(reason):
    """The availability cache stays language-neutral; translate only its display copy."""
    if ui_language() != 'en':
        return reason
    fixed = {
        'Nuke 밖에서는 확인할 수 없습니다': 'Cannot check outside Nuke',
        'NukeX 라이선스가 아니라 Kronos 를 설정할 수 없습니다 (노드는 생기지만 knob 이 읽기 전용).\n'
        '같은 움직임 보간은 OFlow 로 고르세요 — 이 라이선스에서 두 결과가 같습니다':
        'Kronos cannot be configured without a NukeX licence (its knobs are read-only).\n'
        'Choose OFlow for motion interpolation; both produce the same result with this licence.',
    }
    if reason in fixed:
        return fixed[reason]
    match = re.fullmatch(r'이 Nuke 에 (\S+) 플러그인이 없습니다', reason)
    if match:
        return 'This Nuke has no %s plugin' % match.group(1)
    return ('Check failed: ' + reason[len('확인 실패: '):]) if reason.startswith('확인 실패: ') else reason


# numpy bootstrap - install without a terminal (inlined in this file; pure functions are verified by the core tests)
# Lookup: same folder rule as init.py, ~/.nuke_pylibs/py<major><minor> (NMMR_PYLIBS_ROOT changes the root)
# shared folders from NMMR_NUMPY_PATH (os.pathsep separated), and shared folders saved from the window
# Install: (A) unpack an offline numpy wheel from vendor/ with zipfile (B) online: Nuke's bundled python -m pip install --target
# (C) point to a shared folder. After installing, retry the import without restarting. UI is show_numpy_installer
np = None
_NP_ERR = ''


def _pylibs_root(environ=None, home=None):
    env = os.environ if environ is None else environ
    r = env.get('NMMR_PYLIBS_ROOT')
    if r:
        return os.path.expanduser(r)
    return os.path.join(home or os.path.expanduser('~'), '.nuke_pylibs')


def _pylibs_dir(root=None, version_info=None):
    """same rule as init.py: <root>/py311 (Nuke 15 = py310, Nuke 16 = py311)"""
    vi = version_info or sys.version_info
    return os.path.join(root or _pylibs_root(), 'py%d%d' % (vi[0], vi[1]))


def _split_paths(value):
    return [p.strip() for p in (value or '').split(os.pathsep) if p.strip()]


def _np_extra_paths(environ=None, saved=None):
    """folders to search for numpy (existing ones only, order kept): user pylibs -> NMMR_NUMPY_PATH -> saved shared folders"""
    env = os.environ if environ is None else environ
    out = []
    for p in [_pylibs_dir(_pylibs_root(env))] + _split_paths(env.get('NMMR_NUMPY_PATH')) + _split_paths(saved):
        p = os.path.expanduser(p)
        if p not in out and os.path.isdir(p):
            out.append(p)
    return out


def _np_add_paths(paths):
    added = []
    for p in paths:
        if p and p not in sys.path:
            sys.path.append(p)
            added.append(p)
    return added


def _np_import():
    """(Re)import numpy into the module-global np. On failure np = None and the reason is in _NP_ERR"""
    global np, _NP_ERR
    try:
        import importlib
        importlib.invalidate_caches()
        import numpy
        np = numpy
        _NP_ERR = ''
        return True
    except Exception as e:  # ImportError / binary mismatch (OSError) / architecture mismatch, etc.
        for k in [k for k in sys.modules if k == 'numpy' or k.startswith('numpy.')]:
            del sys.modules[k]  # keep a half-imported package from blocking the next retry
        np = None
        _NP_ERR = '%s: %s' % (type(e).__name__, e)
        return False


def _np_activate(target_dir):
    """Put the installed folder on sys.path and retry the import -> (success, error text)"""
    _np_add_paths([target_dir])
    ok = _np_import()
    return ok, ('' if ok else _NP_ERR)


def _norm_arch(machine):
    m = (machine or '').lower()
    if m in ('arm64', 'aarch64', 'armv8', 'armv8l'):
        return 'arm64'
    if m in ('x86_64', 'amd64', 'x64'):
        return 'x86_64'
    return m


def _host_info(system=None, machine=None, mac_ver=None, glibc=None, py=None):
    """-> {'os': macos|windows|linux, 'arch': arm64|x86_64, 'mac': (maj, min), 'glibc': (maj, min), 'py': (3, 11)}"""
    import platform
    sysname = (system or platform.system()).lower()
    osname = {'darwin': 'macos', 'windows': 'windows', 'linux': 'linux'}.get(sysname, sysname)
    mac = (0, 0)
    if osname == 'macos':
        mv = mac_ver if mac_ver is not None else platform.mac_ver()[0]
        nums = [int(x) for x in re.findall(r'\d+', mv or '')][:2]
        mac = (nums + [0, 0])[:2] if nums else (10, 9)
    gl = glibc
    if osname == 'linux' and gl is None:
        try:
            lv = platform.libc_ver()
            nums = [int(x) for x in re.findall(r'\d+', lv[1] or '')][:2]
            gl = tuple((nums + [0, 0])[:2]) if nums else (2, 17)
        except Exception:
            gl = (2, 17)
    vi = py or sys.version_info
    return {'os': osname, 'arch': _norm_arch(machine or platform.machine()), 'mac': tuple(mac),
            'glibc': tuple(gl or (2, 17)), 'py': (vi[0], vi[1])}


_MANYLINUX_LEGACY = {'manylinux1': (2, 5), 'manylinux2010': (2, 12), 'manylinux2014': (2, 17)}


def _whl_parse(filename):
    """numpy-2.4.6-cp311-cp311-macosx_14_0_arm64.whl -> dict, or None if it is not a wheel"""
    base = os.path.basename(filename or '')
    if not base.lower().endswith('.whl'):
        return None
    parts = base[:-4].split('-')
    if len(parts) < 5:
        return None
    return {'file': base, 'name': parts[0].lower().replace('_', '-'), 'version': parts[1],
            'py': parts[-3].split('.'), 'abi': parts[-2].split('.'), 'plat': parts[-1].split('.')}


def _ver_tuple(v):
    """'2.4.6' -> (2, 4, 6). None for a prerelease (rc/dev/a/b), which is never chosen"""
    if not re.match(r'^\d+(\.\d+)*$', v or ''):
        return None
    return tuple(int(x) for x in v.split('.'))


def _plat_score(tag, host):
    """Score if the platform tag is usable on this host (higher is better), otherwise None"""
    if tag == 'any':
        return 1.0
    o, arch = host['os'], host['arch']
    if o == 'macos':
        m = re.match(r'^macosx_(\d+)_(\d+)_(\w+)$', tag)
        if not m:
            return None
        ver, a = (int(m.group(1)), int(m.group(2))), m.group(3)
        if ver > host['mac']:
            return None
        if a == arch:
            base = 100.0
        elif a == 'universal2' or (a == 'intel' and arch == 'x86_64'):
            base = 50.0
        else:
            return None
        return base + (ver[0] * 100 + ver[1]) / 10000.0
    if o == 'windows':
        want = {'x86_64': 'win_amd64', 'arm64': 'win_arm64'}.get(arch)
        return 100.0 if tag == want else None
    if o == 'linux':
        m = re.match(r'^(manylinux_(\d+)_(\d+)|manylinux(?:1|2010|2014))_(\w+)$', tag)
        if not m or m.group(4) != {'x86_64': 'x86_64', 'arm64': 'aarch64'}.get(arch):
            return None
        if m.group(2):
            need = (int(m.group(2)), int(m.group(3)))
        else:
            need = _MANYLINUX_LEGACY.get(m.group(1))
        if need is None or need > host['glibc']:
            return None
        return 100.0 + (need[0] * 100 + need[1]) / 10000.0
    return None


def _whl_score(w, host):
    """parsed wheel -> score when python/ABI/platform all match, otherwise None"""
    cp = 'cp%d%d' % host['py']
    py_ok = cp in w['py'] and any(a in (cp, 'abi3', 'none') for a in w['abi'])
    pure = ('py3' in w['py'] or 'py2.py3' in w['py']) and 'none' in w['abi']
    if not (py_ok or pure):
        return None
    best = None
    for t in w['plat']:
        sc = _plat_score(t, host)
        if sc is not None and (best is None or sc > best):
            best = sc
    return best


def _whl_pick(filenames, host=None, name='numpy'):
    """One numpy wheel that fits this host from a list of file names (newest version -> more specific platform tag). None if there is none"""
    host = host or _host_info()
    best, best_key = None, None
    for f in filenames:
        w = _whl_parse(f)
        if not w or w['name'] != name:
            continue
        vt = _ver_tuple(w['version'])
        sc = _whl_score(w, host)
        if vt is None or sc is None:
            continue
        key = (vt, sc)
        if best_key is None or key > best_key:
            best, best_key = f, key
    return best


def _vendor_dirs(extra=None, environ=None, module_file=None):
    """Folders to search for wheels: user-specified -> NMMR_VENDOR -> <install folder>/vendor -> <parent of install folder>/vendor"""
    env = os.environ if environ is None else environ
    out = []
    for p in _split_paths(extra) + _split_paths(env.get('NMMR_VENDOR')):
        out.append(os.path.expanduser(p))
    mf = module_file if module_file is not None else globals().get('__file__')
    if mf:
        here = os.path.dirname(os.path.abspath(mf))
        out += [os.path.join(here, 'vendor'), os.path.join(os.path.dirname(here), 'vendor')]
    seen, res = set(), []
    for p in out:
        if p not in seen:
            seen.add(p)
            res.append(p)
    return res


def _find_wheels(dirs, depth=2):
    """List of folders (or .whl file paths) -> full .whl paths (folders are searched down to depth levels)"""
    found = []
    for d in dirs:
        if os.path.isfile(d) and d.lower().endswith('.whl'):
            found.append(d)
            continue
        if not os.path.isdir(d):
            continue
        base_depth = d.rstrip(os.sep).count(os.sep)
        for root, subdirs, files in os.walk(d):
            if root.rstrip(os.sep).count(os.sep) - base_depth >= depth:
                subdirs[:] = []
            for f in sorted(files):
                if f.lower().endswith('.whl'):
                    found.append(os.path.join(root, f))
    return found


def _wheel_for_host(dirs, host=None):
    """wheel path candidates -> (full path of the numpy wheel for this host or None, list of numpy wheel file names found)"""
    paths = _find_wheels(dirs)
    by_name = {}
    for p in paths:
        by_name.setdefault(os.path.basename(p), p)
    pick = _whl_pick(list(by_name), host)
    seen = [f for f in by_name if (_whl_parse(f) or {}).get('name') == 'numpy']
    return (by_name[pick] if pick else None), seen


def _whl_extract_iter(whl_path, target_dir):
    """Unpack a wheel (zip) into target_dir. A generator that yields (index, total, name) per file (the UI advances on each tick).
    Entries that escape upward (zip-slip) and corrupt wheels are rejected before unpacking."""
    import zipfile
    root = os.path.realpath(target_dir)
    with zipfile.ZipFile(whl_path) as z:
        bad = z.testzip()
        if bad:
            raise ValueError(_t('휠이 손상됐습니다 (%s)', 'Wheel is damaged (%s)') % bad)
        infos = z.infolist()
        for info in infos:
            dest = os.path.realpath(os.path.join(root, info.filename))
            if dest != root and not dest.startswith(root + os.sep):
                raise ValueError(_t('휠 안에 폴더 밖으로 나가는 경로가 있습니다: %s', 'Wheel contains a path outside the destination folder: %s') % info.filename)
        if not os.path.isdir(root):
            os.makedirs(root)
        total = len(infos)
        for i, info in enumerate(infos):
            z.extract(info, root)
            mode = (info.external_attr >> 16) & 0o777
            if mode & 0o111 and not info.filename.endswith('/'):
                try:
                    os.chmod(os.path.join(root, info.filename), mode)
                except OSError:
                    pass
            yield i + 1, total, info.filename


def _whl_extract(whl_path, target_dir):
    n = 0
    for n, _total, _name in _whl_extract_iter(whl_path, target_dir):
        pass
    return n


def _find_nuke_python(exe=None, system=None):
    """The first existing candidate for the python executable bundled with Nuke (sys.executable is Nuke itself and cannot be used)"""
    exe = exe or sys.executable or ''
    here = os.path.dirname(os.path.abspath(exe)) if exe else ''
    osname = _host_info(system=system)['os']
    names = ['python.exe', 'python3.exe'] if osname == 'windows' else ['python3', 'python3.%d' % sys.version_info[1], 'python']
    dirs = [here, os.path.join(sys.exec_prefix, 'bin'), sys.exec_prefix, os.path.join(sys.base_prefix, 'bin')]
    for d in dirs:
        for n in names:
            p = os.path.join(d, n)
            if d and os.path.isfile(p):
                return p
    return None


def _pip_args(target_dir, spec='numpy'):
    """pip arguments appended after the python executable (--only-binary prevents source builds, --upgrade overwrites the target folder)"""
    return ['-m', 'pip', 'install', '--target', target_dir, '--upgrade', '--only-binary=:all:',
            '--no-input', '--disable-pip-version-check', spec]


def _np_manual_text(host, target_dir):
    """Manual install text used when Qt is unavailable too (or as failure guidance)"""
    return (_t('numpy 가 필요합니다 (Python %d.%d / %s %s).\n'
            '설치 위치: %s\n'
            '- 오프라인: 배포 폴더 vendor/ 의 numpy 휠을 같은 위치에 두거나 환경변수 NMMR_VENDOR 로 지정\n'
            '- 공용: numpy 가 있는 폴더를 환경변수 NMMR_NUMPY_PATH 로 지정',
            'numpy is required (Python %d.%d / %s %s).\n'
            'Installation folder: %s\n'
            '- Offline: place a compatible numpy wheel in vendor/ beside the distribution, or set NMMR_VENDOR\n'
            '- Shared: set NMMR_NUMPY_PATH to the folder containing numpy')
            % (host['py'][0], host['py'][1], host['os'], host['arch'], target_dir))


