# Settings
_CONSOLE_PROBLEM = re.compile(
    r'fail|error|cannot|could not|not found|warn|cancel|ignored|\bheld\b(?!-)|needs review|not saved|'
    r'possible cut|unavailable|\[!\]|No (EDIT|plate|burn-in) TC|without TC|'
    r'\uc2e4\ud328|\uc624\ub958|\uacbd\uace0|\ucde8\uc18c|\ubb34\uc2dc|\ubcf4\ub958|'
    r'\ud655\uc778 \ud544\uc694|\uc758\uc2ec|\ucc3e\uc9c0 \ubabb|\uc800\uc7a5 \uc0dd\ub7b5|'
    r'TC \uc5c6|\uba54\ud0c0\ub370\uc774\ud130 \uc5c6|TC \uc5c6\uc774', re.I)
_CONSOLE_KEEP = re.compile(
    r'^(run v|=+ |QC review saved|Path settings saved|TC calibration saved|'
    r'QC \ub9ac\ubdf0 \uc800\uc7a5|\uacbd\ub85c \uc124\uc815 \uc800\uc7a5|TC \ubcf4\uc815 \uc800\uc7a5)')
_CONSOLE_DIAG = re.compile(
    r'^(\s{2}|\[\d\]|\[[^\]]+\] |EDIT \d+ frames|plate range|render |cache |TC OCR:|\$ |'
    r'host progress|Active image area|QC review setup nodes|custom OCIO|Burn-in TC read|\ub809TC|\ucea1\uc2dc|QC TC layout)')


def _console_wanted(text):
    text = str(text)
    if _CONSOLE_KEEP.match(text) or _CONSOLE_PROBLEM.search(text):
        return True
    return not _CONSOLE_DIAG.match(text)


def _console(text):
    if _console_wanted(text):
        print('[No More Manual Retime] ' + str(text))


