TRACK_WIN_FRAC = 0.8  # optical animation acceptance: minimum fraction of verification frames that gained
TRACK_DEV = 0.01  # secondary acceptance (track_accept_dev): only look at verification frames whose animated scale differs from the static solution by at least this ratio
TRACK_DEV_SHARE = 0.5
TRACK_DEV_GAIN = 0.008  # minimum mean NCC gain on those frames (small zoom 1.0 -> 1.08 gives 0.011; static edits <= 0.002 / cuts excluded)
TRACK_TRIAL_SRNG = 0.05  # trial acceptance of a track: minimum key curve scale range (noise keys of static edits < 0.03)
