# EXR reader (scanline, NONE / ZIPS / ZIP)
_PT_SIZE = {0: 4, 1: 2, 2: 4}
_PT_DTYPE = {0: '<u4', 1: '<f2', 2: '<f4'}
_LINES_PER_CHUNK = {0: 1, 2: 1, 3: 16}


def _exr_unzip(raw, expected):
    t = np.frombuffer(zlib.decompress(raw), np.uint8).astype(np.int64)
    d = t.copy()
    d[1:] -= 128
    t = (np.cumsum(d) & 0xFF).astype(np.uint8)
    half = (len(t) + 1) // 2
    out = np.empty_like(t)
    out[0::2] = t[:half]
    out[1::2] = t[half:]
    return out.tobytes()


def read_exr(path):
    """ -> dict{channel: float32 (H,W)} in displayWindow, row0 = top
    """
    with open(path, 'rb') as f:
        data = f.read()
    magic, ver = struct.unpack('<ii', data[:8])
    if magic != 20000630:
        raise IOError('not exr: %s' % path)
    if ver & 0x200:
        raise IOError('tiled exr unsupported: %s' % path)
    pos = 8
    attrs = {}
    while True:
        e = data.index(b'\0', pos)
        name = data[pos:e].decode('latin-1')
        pos = e + 1
        if not name:
            break
        e = data.index(b'\0', pos)
        typ = data[pos:e].decode('latin-1')
        pos = e + 1
        size = struct.unpack('<i', data[pos:pos + 4])[0]
        pos += 4
        attrs[name] = (typ, data[pos:pos + size])
        pos += size

    chs = []
    cd = attrs['channels'][1]
    p = 0
    while cd[p:p + 1] != b'\0':
        e = cd.index(b'\0', p)
        n = cd[p:e].decode('latin-1')
        p = e + 1
        pt = struct.unpack('<i', cd[p:p + 4])[0]
        p += 16
        chs.append((n, pt))

    comp = attrs['compression'][1][0]
    if comp not in _LINES_PER_CHUNK:
        raise IOError('exr compression %d unsupported (none/zip only)' % comp)
    x0, y0, x1, y1 = struct.unpack('<4i', attrs['dataWindow'][1])
    dx0, dy0, dx1, dy1 = struct.unpack('<4i', attrs['displayWindow'][1])
    w, h = x1 - x0 + 1, y1 - y0 + 1
    lpc = _LINES_PER_CHUNK[comp]
    nchunks = (h + lpc - 1) // lpc
    offsets = np.frombuffer(data, dtype='<u8', count=nchunks, offset=pos)
    line_bytes = w * sum(_PT_SIZE[pt] for _, pt in chs)

    planes = dict((n, np.zeros((h, w), np.float32)) for n, _ in chs)
    for off in offsets:
        off = int(off)
        y, sz = struct.unpack('<ii', data[off:off + 8])
        raw = data[off + 8:off + 8 + sz]
        nl = min(lpc, y1 - y + 1)
        if comp != 0 and sz < nl * line_bytes:
            raw = _exr_unzip(raw, nl * line_bytes)
        q = 0
        for li in range(nl):
            row = y - y0 + li
            for n, pt in chs:
                planes[n][row] = np.frombuffer(raw, dtype=_PT_DTYPE[pt], count=w, offset=q)
                q += w * _PT_SIZE[pt]

    dw, dh = dx1 - dx0 + 1, dy1 - dy0 + 1
    out = {}
    for n, arr in planes.items():
        canvas = np.zeros((dh, dw), np.float32)
        ys0, xs0 = max(y0, dy0), max(x0, dx0)
        ys1, xs1 = min(y1, dy1), min(x1, dx1)
        if ys1 >= ys0 and xs1 >= xs0:
            canvas[ys0 - dy0:ys1 - dy0 + 1, xs0 - dx0:xs1 - dx0 + 1] = \
                arr[ys0 - y0:ys1 - y0 + 1, xs0 - x0:xs1 - x0 + 1]
        out[n] = canvas
    return out


def exr_luma(path):
    """"""
    ch = read_exr(path)
    keys = dict((k.split('.')[-1].upper(), k) for k in ch)
    if all(c in keys for c in ('R', 'G', 'B')):
        y = 0.2126 * ch[keys['R']] + 0.7152 * ch[keys['G']] + 0.0722 * ch[keys['B']]
    else:
        y = ch[list(ch.keys())[0]]
    y = np.nan_to_num(y, nan=0.0, posinf=0.0, neginf=0.0)
    return np.clip(y, 0.0, 64.0).astype(np.float32)


# Image utilities
def to_display(y):
    """ luminance -> approximate display gamma (for blend detection)
    """
    return np.power(np.clip(y, 0, None), 1.0 / 2.2).astype(np.float32)


def blur121(a):
    """(..., H, W) separable [1 2 1]/4"""
    p = np.pad(a, [(0, 0)] * (a.ndim - 2) + [(1, 1), (1, 1)], mode='edge')
    v = (p[..., :-2, :] + 2 * p[..., 1:-1, :] + p[..., 2:, :]) * 0.25
    return (v[..., :, :-2] + 2 * v[..., :, 1:-1] + v[..., :, 2:]) * 0.25


def down2(a):
    H, W = a.shape[-2] // 2 * 2, a.shape[-1] // 2 * 2
    a = a[..., :H, :W]
    return 0.25 * (a[..., 0::2, 0::2] + a[..., 1::2, 0::2] + a[..., 0::2, 1::2] + a[..., 1::2, 1::2])


def rank_rows(X):
    """ per-row mean-rank normalization -> [-1, 1]. Invariant to monotonic tone curves (gamma/level/gain) (ties get the mean rank)
    per-row Python loop -> batched argsort (3-4x faster)
    """
    X = np.asarray(X, np.float32)
    single = X.ndim == 1
    if single:
        X = X[None]
    F, N = X.shape
    if N < 2:
        out = np.zeros((F, N), np.float32)
        return out[0] if single else out
    order = np.argsort(X, axis=1)
    S = np.take_along_axis(X, order, 1)
    idx = np.broadcast_to(np.arange(N), (F, N))
    newg = np.ones((F, N), bool)
    newg[:, 1:] = S[:, 1:] != S[:, :-1]
    start = np.maximum.accumulate(np.where(newg, idx, 0), axis=1)
    endf = np.ones((F, N), bool)
    endf[:, :-1] = newg[:, 1:]
    end = np.minimum.accumulate(np.where(endf, idx, N - 1)[:, ::-1], axis=1)[:, ::-1]
    r = ((start + end) * (1.0 / (N - 1)) - 1.0).astype(np.float32)
    out = np.empty((F, N), np.float32)
    np.put_along_axis(out, order, r, 1)
    return out[0] if single else out


def warp_coords(Ht, Wt, Hp, Wp, s, tx, ty, flop, x_off=0, y_off=0, Wc=None, Hc=None):
    """
    target (EDIT) grid -> PLATE thumbnail coordinates.
    Normalized coordinates: width units, centered origin, y pointing down.
    edit_uc = s * plate_uc + tx  (plate_uc sign is flipped for flop)
    x_off/y_off: canvas extension (for search)
    """
    Wc = Wt if Wc is None else Wc
    Hc = Ht if Hc is None else Hc
    xs = (np.arange(Wc) - x_off + 0.5) / Wt - 0.5
    ys = (np.arange(Hc) - y_off + 0.5) / Wt - Ht / (2.0 * Wt)
    uc, vc = np.meshgrid(xs, ys)
    pu = (uc - tx) / s
    pv = (vc - ty) / s
    if flop:
        pu = -pu
    xp = (pu + 0.5) * Wp - 0.5
    yp = (pv + Hp / (2.0 * Wp)) * Wp - 0.5
    return xp.astype(np.float32), yp.astype(np.float32)


def bilinear(imgs, xp, yp):
    """ imgs (..., Hp, Wp) -> (..., Ht, Wt), valid mask
    """
    Hp, Wp = imgs.shape[-2:]
    valid = (xp >= 0) & (xp <= Wp - 1) & (yp >= 0) & (yp <= Hp - 1)
    x0 = np.clip(np.floor(xp).astype(np.int64), 0, Wp - 2)
    y0 = np.clip(np.floor(yp).astype(np.int64), 0, Hp - 2)
    fx = np.clip(xp - x0, 0, 1).astype(np.float32)
    fy = np.clip(yp - y0, 0, 1).astype(np.float32)
    a = imgs[..., y0, x0]
    b = imgs[..., y0, x0 + 1]
    c = imgs[..., y0 + 1, x0]
    d = imgs[..., y0 + 1, x0 + 1]
    top = a + (b - a) * fx
    bot = c + (d - c) * fx
    return top + (bot - top) * fy, valid


# Mask / valid frames
def edit_static_mask(E_lum):
    """ exclude always-black areas such as letterbox + exclude 1px at the edges
    """
    disp = to_display(E_lum)
    mx = disp.max(axis=0)
    ref = np.percentile(mx, 99) + 1e-6
    m = mx > 0.03 * ref
    m[0, :] = m[-1, :] = False
    m[:, 0] = m[:, -1] = False
    return m


def overlay_mask(E_lum, mask):
    """ find burn-in / overlay candidates from EDIT alone before matching -> pixels to exclude (bool HxW), info dict
    Up to  the burn-in mask only arose after matching from the residual (stage 6), so stage 1 optical / candidate search / first-pass cost
    were contaminated by bars and watermarks (real-footage degraded set: burn-ins alone collapsed 3 of 4 clips).
      1) static edges (watermark / label / bar boundary): temporal mean of the high-pass |mu| > OVL_K x temporal deviation, and
         |mu| is meaningful relative to the frame texture. The high-pass of a moving picture has a temporal mean near 0
      2) translucent bars: row bands touching the top / bottom edge whose brightness and temporal change are clearly lower than the middle rows
    If static pixels exceed OVL_MAX_FRAC of the frame (locked-off camera / hold shot: the picture itself is static), exclude only those inside the top/bottom bands
    (OVL_BAND). Bars are always excluded. If too few pixels remain after exclusion, nothing is removed
    """
    E, H, W = E_lum.shape
    none = np.zeros((H, W), bool)
    info = dict(frac=0.0, bars=(0, 0), static=0.0)
    if E < 8 or mask.sum() < 64:
        return none, info
    sel = np.linspace(0, E - 1, min(E, 64)).astype(int)
    D = to_display(E_lum[sel])
    sm = D
    for _ in range(3):
        sm = blur121(sm)
    hp = D - sm
    mu = hp.mean(axis=0)
    sd = hp.std(axis=0)
    tex = float(np.median(np.sqrt((hp * hp).mean(axis=0))[mask])) + 1e-6
    stat = mask & (np.abs(mu) > OVL_K * sd) & (np.abs(mu) > 0.5 * tex)
    # 2) bars: row brightness / row temporal change profile
    rmean = np.median(np.median(D, axis=2), axis=0)  # (H,) row median (not pulled by burned-in text)
    ract = np.median(D.std(axis=0), axis=1)  # (H,)
    c0, c1 = int(H * 0.3), int(H * 0.7)
    ref_m = float(np.median(rmean[c0:c1])) + 1e-6
    ref_a = float(np.median(ract[c0:c1])) + 1e-6
    barrow = (rmean < OVL_BAR_RATIO * ref_m) & (ract < OVL_BAR_RATIO * ref_a)
    lim = int(round(H * 0.15))
    top = 0
    while top < lim and (barrow[top] or (top < 2 and np.all(~mask[top]))):
        top += 1
    bot = 0
    while bot < lim and (barrow[H - 1 - bot] or (bot < 2 and np.all(~mask[H - 1 - bot]))):
        bot += 1
    top = top if top >= 2 and np.any(barrow[:top]) else 0
    bot = bot if bot >= 2 and np.any(barrow[H - bot:]) else 0
    bars = np.zeros((H, W), bool)
    if top:
        bars[:min(H, top + 1)] = True  # one row of margin at the boundary
    if bot:
        bars[max(0, H - bot - 1):] = True
    sfrac = stat.sum() / float(mask.sum())
    if sfrac > OVL_MAX_FRAC:
        yy = (np.arange(H) + 0.5)[:, None] / H
        stat &= (yy < OVL_BAND) | (yy > 1 - OVL_BAND)
    ex = (_dilate(stat, 1) | bars) & mask
    frac = ex.sum() / float(mask.sum())
    if frac > 0.6:
        return none, dict(info, static=sfrac)
    return ex, dict(frac=frac, bars=(top, bot), static=sfrac)


def identical_thumbs(lum, ok=None):
    """ whether the thumbnails are all the same picture - if first/last of a script-made Movie Read stays at 1,
    every frame becomes frame 1 and a wrong result silently comes out (precision measurement 1.6). Judged only with 3 or more frames"""
    idx = np.arange(len(lum)) if ok is None else np.where(np.asarray(ok, bool))[0]
    if len(idx) < 3:
        return False
    a = lum[idx].reshape(len(idx), -1)
    d = np.abs(a - a[:1]).max()
    return bool(d <= 1e-6 + 1e-4 * float(np.abs(a[0]).mean()))


def isolated_edit_duplicates(lum, ok=None):
    """Position (second frame index) where the same EDIT thumbnail repeats once more even though the frames before and after move.

    Long holds are excluded because the same pair repeats consecutively, and so are
    segments where the same pair repeats densely, like an integer repeated slow. If any of the four frames to judge failed to render, it is silently skipped.
    """
    a = np.asarray(lum)
    n = len(a)
    valid = np.ones(n, bool) if ok is None else np.asarray(ok, bool)
    if n < 4 or len(valid) != n:
        return []
    same = np.zeros(n, bool)  # same[t]: t-1 and t are effectively the same thumbnail
    for t in range(1, n):
        if not (valid[t - 1] and valid[t]):
            continue
        d = float(np.abs(a[t] - a[t - 1]).max())
        level = max(float(np.abs(a[t - 1]).mean()), float(np.abs(a[t]).mean()))
        same[t] = d <= 1e-6 + 1e-4 * level
    candidates = [t for t in range(2, n - 1)
                  if valid[t - 2:t + 2].all() and same[t] and not same[t - 1] and not same[t + 1]]
    # If the same pair continues 3 or more times at 2-3 frame intervals, like 0.5x, the whole cadence is a repeated slow.
    # Both ends of the cluster are excluded too, but an error with only two short occurrences stays a warning target.
    repeated = np.where(same)[0].tolist()
    cadence = set()
    cluster = []
    for t in repeated:
        if cluster and t - cluster[-1] > 3:
            if len(cluster) >= 3:
                cadence.update(cluster)
            cluster = []
        cluster.append(t)
    if len(cluster) >= 3:
        cadence.update(cluster)
    return [t for t in candidates if t not in cadence]


def active_bbox(E_lum):
    """ active picture column range of a fit-inside (pillarbox) edit. If the always-black columns on the left and right are at least
    1 - BOX_MAX_W of the frame width, (x0, y0, x1, y1) in normalized coordinates (top-left origin), otherwise None.
    With a narrow active width the scale relative to the edit width falls outside SCALE_MIN (vertical plate fit-inside s~0.32) -> re-render and match only inside it"""
    disp = to_display(E_lum)
    mx = disp.max(axis=0)
    He, We = mx.shape
    ref = np.percentile(mx, 99) + 1e-6
    # when black pillars are lifted by a look (LUT) (L1 log look: 0.038), the absolute-zero reference (0.03 x ref) treats pillars as 'active' too ->
    # use the 1st percentile of the middle-row temporal maximum as the black reference (for true black it is 0, same as )
    blk = float(np.percentile(mx[int(He * 0.2):int(He * 0.8)], 1))
    act = mx > blk + 0.03 * (ref - blk)
    # Columns are judged from the middle rows only (20-80%): text from the top/bottom burn-in bars (TC / file name / watermark) is also stamped over the black pillars
    cols = np.where(act[int(He * 0.2):int(He * 0.8)].mean(axis=0) > 0.05)[0]
    rows = np.where(act.mean(axis=1) > 0.05)[0]
    if not len(cols) or not len(rows):
        return None
    x0, x1 = cols[0], cols[-1] + 1
    if (x1 - x0) > BOX_MAX_W * We or (x1 - x0) < 0.1 * We:
        return None
    return (x0 / float(We), rows[0] / float(He), x1 / float(We), (rows[-1] + 1) / float(He))


def uncrop_result(res, bb, aspect, full_shape):
    """ convert a result solved inside the active area (bb) to full edit coordinates: u = wb*u' + c (width units, centered origin, y down)
    aspect = edit H/W. Converts optical / track / mask (at edit thumbnail resolution)"""
    x0, y0, x1, y1 = bb
    wb = x1 - x0
    cx = (x0 + x1) * 0.5 - 0.5
    cy = ((y0 + y1) * 0.5 - 0.5) * aspect

    def conv(o):
        o = dict(o)
        o['s'] = wb * np.asarray(o['s']) if np.ndim(o['s']) else wb * float(o['s'])
        o['tx'] = wb * np.asarray(o['tx']) + cx if np.ndim(o['tx']) else wb * float(o['tx']) + cx
        o['ty'] = wb * np.asarray(o['ty']) + cy if np.ndim(o['ty']) else wb * float(o['ty']) + cy
        return o
    opt = conv(res['optical'])
    opt.pop('note', None)  # even if identity (uncorrected), it is shrink + shift in full coordinates
    opt['rmask'] = None
    res['optical'] = opt
    if res.get('track') is not None and res['track'].get('animated'):
        res['track'] = conv(res['track'])
    He, We = full_shape
    m = res['mask']
    full = np.zeros((He, We), bool)
    X0, X1 = int(round(x0 * We)), max(int(round(x1 * We)), int(round(x0 * We)) + 1)
    Y0, Y1 = int(round(y0 * He)), max(int(round(y1 * He)), int(round(y0 * He)) + 1)
    yi = np.clip(((np.arange(Y1 - Y0) + 0.5) / (Y1 - Y0) * m.shape[0]).astype(int), 0, m.shape[0] - 1)
    xi = np.clip(((np.arange(X1 - X0) + 0.5) / (X1 - X0) * m.shape[1]).astype(int), 0, m.shape[1] - 1)
    full[Y0:Y1, X0:X1] = m[yi][:, xi]
    res['mask'] = full
    res['boxed'] = bb
    return res


def valid_frames(lum, mask):
    """ detect black/slate (textureless) frames
    """
    disp = to_display(lum)[:, mask]
    sd = disp.std(axis=1)
    med = np.median(sd[sd > 0]) if np.any(sd > 0) else 1.0
    return sd > 0.08 * med


def texture_energy(img):
    gx = np.diff(img, axis=1)
    gy = np.diff(img, axis=0)
    return float(np.abs(gx).mean() + np.abs(gy).mean())


# Optical estimation
def _ncc_maps(T, M, I_stack, FT, FM, nT):
    """FFT masked NCC. I_stack (C,Hc,Wc) -> (C, Hc-He+1, Wc-We+1)"""
    He, We = T.shape
    C, Hc, Wc = I_stack.shape
    FI = np.fft.rfft2(I_stack)
    FI2 = np.fft.rfft2(I_stack * I_stack)
    num = np.fft.irfft2(FT[None] * FI, s=(Hc, Wc))
    s1 = np.fft.irfft2(FM[None] * FI, s=(Hc, Wc))
    s2 = np.fft.irfft2(FM[None] * FI2, s=(Hc, Wc))
    n = M.sum()
    var = s2 - s1 * s1 / n
    ncc = num / (np.sqrt(np.maximum(var, 1e-6)) * nT)
    return ncc[:, :Hc - He + 1, :Wc - We + 1]


def _score_pairs(E_imgs, E_mask, P_imgs, s, tx, ty, flop):
    """Mean masked NCC (in rank space) over several (edit, plate) pairs"""
    Ht, Wt = E_imgs.shape[-2:]
    Hp, Wp = P_imgs.shape[-2:]
    xp, yp = warp_coords(Ht, Wt, Hp, Wp, s, tx, ty, flop)
    W, valid = bilinear(P_imgs, xp, yp)
    m = E_mask & valid
    if m.sum() < 0.3 * E_mask.sum():
        return -1.0
    a = rank_rows(E_imgs[:, m])
    b = rank_rows(W[:, m])
    a -= a.mean(axis=1, keepdims=True)
    b -= b.mean(axis=1, keepdims=True)
    ncc = (a * b).sum(1) / (np.sqrt((a * a).sum(1) * (b * b).sum(1)) + 1e-9)
    return float(ncc.mean())


def _template(img, mask):
    """"""
    T = np.zeros(img.shape, np.float32)
    tv = rank_rows(img[mask])
    T[mask] = tv - tv.mean()
    return T


def _search_level(Ts, masks, Pr, scales, flops, topk=4, allow=None):
    """
    per-template masks (partial regions)
    FFT masked NCC scale/shift search. Warp/plate FFTs are shared between templates.
    Ts: [(key, template, mask_id)], masks: {mask_id: bool mask}
    Pr: (C,Hp,Wp) rank-normalized plates
    allow {key: (C,) bool}: plate candidates to examine per key (optical key tracking = only around the path)
    Returns: [(ncc, key, cand_idx, s, flop, tx, ty)] top-k per key
    """
    any_m = next(iter(masks.values()))
    Hs, Ws = any_m.shape
    C, Hps, Wps = Pr.shape
    mx = max(2, int(round(SEARCH_MARGIN * Ws)))
    my = mx
    Hc, Wc = Hs + 2 * my, Ws + 2 * mx
    oh, ow = Hc - Hs + 1, Wc - Ws + 1
    FMs = {}
    for mid, M in masks.items():
        Mf = M.astype(np.float32)
        FMs[mid] = (np.conj(np.fft.rfft2(Mf, s=(Hc, Wc))), max(Mf.sum(), 1.0))
    FTs = [(key, np.conj(np.fft.rfft2(T, s=(Hc, Wc))), np.sqrt((T * T).sum()) + 1e-9, mid)
           for key, T, mid in Ts]
    res = dict((key, []) for key, _, _ in Ts)
    for fl in flops:
        for s in scales:
            xp, yp = warp_coords(Hs, Ws, Hps, Wps, s, 0.0, 0.0, fl,
                                 x_off=mx, y_off=my, Wc=Wc, Hc=Hc)
            I, valid = bilinear(Pr, xp, yp)
            I = np.where(valid[None], I, 0.0).astype(np.float32)
            FI = np.fft.rfft2(I)
            FI2 = np.fft.rfft2(I * I)
            dens = {}
            for mid, (FM, n) in FMs.items():
                s1 = np.fft.irfft2(FM[None] * FI, s=(Hc, Wc))[:, :oh, :ow]
                s2 = np.fft.irfft2(FM[None] * FI2, s=(Hc, Wc))[:, :oh, :ow]
                dens[mid] = np.sqrt(np.maximum(s2 - s1 * s1 / n, 1e-6))
            for key, FT, nT, mid in FTs:
                num = np.fft.irfft2(FT[None] * FI, s=(Hc, Wc))[:, :oh, :ow]
                flat = (num / (dens[mid] * nT)).reshape(C, -1)
                k = flat.argmax(axis=1)
                v = flat[np.arange(C), k]
                if allow is not None and key in allow:
                    v = np.where(allow[key], v, -2.0)
                dy, dx = np.unravel_index(k, (oh, ow))
                for ci in np.argsort(-v)[:topk]:
                    if v[ci] <= -2.0:
                        continue
                    res[key].append((float(v[ci]), key, int(ci), float(s), fl,
                                     -(dx[ci] - mx) / float(Ws), -(dy[ci] - my) / float(Ws)))
    out = []
    for key in res:
        out += sorted(res[key], key=lambda r: -r[0])[:topk]
    return out


_SUBREGIONS = (('L50', 'x', 0.0, 0.5), ('R50', 'x', 0.5, 1.0), ('T50', 'y', 0.0, 0.5),
               ('B50', 'y', 0.5, 1.0), ('L33', 'x', 0.0, 0.34), ('R33', 'x', 0.66, 1.0),
               ('T33', 'y', 0.0, 0.34), ('B33', 'y', 0.66, 1.0),
               ('L20', 'x', 0.0, 0.2), ('R20', 'x', 0.8, 1.0))
SUBREGION_PENALTY = 0.04


def _region_masks(mask, use_sub=True):
    """ [(name, mask)]: full + partial regions for split-composite comparison
    """
    H, W = mask.shape
    out = [('full', mask)]
    if not use_sub:
        return out
    xx = (np.arange(W) + 0.5)[None, :] / W
    yy = (np.arange(H) + 0.5)[:, None] / H
    for name, ax, a, b in _SUBREGIONS:
        c = xx if ax == 'x' else yy
        m = mask & np.broadcast_to((c >= a) & (c < b), mask.shape)
        if m.sum() > 0.08 * mask.sum():
            out.append((name, m))
    return out


def roi_display_rect(canvas_size, image_size, image_dpr=1.0, pixel_aspect=1.0):
    """Displayed-image rectangle in logical widget coordinates (KeepAspectRatio)."""
    cw, ch = (float(canvas_size[0]), float(canvas_size[1]))
    iw, ih = (float(image_size[0]), float(image_size[1]))
    dpr = float(image_dpr or 1.0)
    par = float(pixel_aspect or 1.0)
    if min(cw, ch, iw, ih, dpr, par) <= 0:
        return (0.0, 0.0, 0.0, 0.0)
    logical_w, logical_h = iw / dpr * par, ih / dpr
    scale = min(cw / logical_w, ch / logical_h)
    dw, dh = logical_w * scale, logical_h * scale
    return ((cw - dw) * .5, (ch - dh) * .5, dw, dh)


def roi_point_normalized(point, display_rect):
    """Map a widget point to top-left normalized image coordinates, clamped to the image."""
    px, py = float(point[0]), float(point[1])
    x, y, w, h = [float(v) for v in display_rect]
    if w <= 0 or h <= 0:
        return (0.0, 0.0)
    return (min(1.0, max(0.0, (px - x) / w)),
            min(1.0, max(0.0, (py - y) / h)))


def normalize_manual_roi(rect, min_extent=.01, min_area=.001):
    """Validate and sort a normalized top-left ROI without silently rescuing off-screen input."""
    if rect is None or len(rect) != 4 or not np.isfinite(rect).all():
        raise ValueError('ROI is invalid')
    ax, ay, bx, by = [float(v) for v in rect]
    if max(ax, bx) <= 0 or min(ax, bx) >= 1 or max(ay, by) <= 0 or min(ay, by) >= 1:
        raise ValueError('ROI is outside the displayed image')
    x0, x1 = max(0.0, min(ax, bx)), min(1.0, max(ax, bx))
    y0, y1 = max(0.0, min(ay, by)), min(1.0, max(ay, by))
    if x1 - x0 < min_extent or y1 - y0 < min_extent or (x1 - x0) * (y1 - y0) < min_area:
        raise ValueError('ROI is too small')
    return (x0, y0, x1, y1)


def manual_roi_mask(shape, rect):
    """Full-frame boolean mask selected by normalized ROI pixel centres."""
    H, W = int(shape[0]), int(shape[1])
    x0, y0, x1, y1 = normalize_manual_roi(rect)
    xx = (np.arange(W, dtype=np.float64) + .5) / max(W, 1)
    yy = (np.arange(H, dtype=np.float64) + .5) / max(H, 1)
    mask = (yy[:, None] >= y0) & (yy[:, None] < y1) & (xx[None, :] >= x0) & (xx[None, :] < x1)
    if mask.sum() < max(16, int(.001 * H * W)):
        raise ValueError('ROI is too small at analysis resolution')
    return mask


def plate_analysis_inputs(full_edit, cropped_edit, active_box, roi_rect):
    """Choose one plate's analysis coordinates; manual ROI always stays in full EDIT space."""
    if roi_rect is not None:
        return full_edit, manual_roi_mask(full_edit.shape[1:], roi_rect), None
    return cropped_edit, None, active_box


def node_stable_name(node):
    """Full Nuke node path, with a lightweight fake-node fallback for headless contracts."""
    try:
        return node.fullName()
    except AttributeError:
        return node.name()


def estimate_optical(E_lum, E_mask, E_valid, P_lum, P_valid, allow_flop=True,
                     detect=True, log=print, subregions=False):
    """
    two-stage search: exhaustive at 32px -> top candidates at 64px
    partial-region templates (split composite)
    E_lum (E,He,We) @W_EDIT, P_lum (P,Hp,Wp) @W_PLATE
    subregions: also search cases where only part of the frame (left/right/top/bottom half, 1/3) matches (split composite)
    -> dict(s, tx, ty, flop, score, score_identity, region, rmask)
    """
    E, He, We = E_lum.shape
    P, Hp, Wp = P_lum.shape
    ident = dict(s=1.0, tx=0.0, ty=0.0, flop=False)

    # anchors: maximum texture per third of the valid frames
    vidx = np.where(E_valid)[0]
    if len(vidx) == 0:
        raise RuntimeError(_t('EDIT 에 유효한 프레임이 없습니다 (전부 블랙인지 확인해 주세요)', 'No valid EDIT frames (check whether all frames are black)'))
    anchors = []
    for part in np.array_split(vidx, min(3, len(vidx))):
        if len(part):
            en = [texture_energy(to_display(E_lum[i])) for i in part]
            anchors.append(int(part[int(np.argmax(en))]))

    pv = np.where(P_valid)[0]
    stride = max(1, int(math.ceil(len(pv) / 150.0)))
    cand = pv[::stride]

    if not detect:
        return dict(ident, score=None, score_identity=None, anchors=anchors,
                    region='full', rmask=None)

    # resolution pyramid (128 / 64 / 32)
    regs = _region_masks(E_mask, subregions)
    E_s = down2(E_lum)
    E_a = down2(E_s)
    m_s = dict((n, down2(m.astype(np.float32)) > 0.99) for n, m in regs)
    m_a = dict((n, down2(m_s[n].astype(np.float32)) > 0.99) for n, _ in regs)
    P_s = blur121(down2(P_lum))
    Hps, Wps = P_s.shape[-2:]
    P_s_r = rank_rows(P_s[cand].reshape(len(cand), -1)).reshape(len(cand), Hps, Wps)
    P_a = blur121(down2(P_s[cand]))
    P_a_r = rank_rows(P_a.reshape(len(cand), -1)).reshape(P_a.shape)
    flops = [False, True] if allow_flop else [False]

    def eff(v, rname):
        return v - (0.0 if rname == 'full' else SUBREGION_PENALTY)

    # level A (32px): all candidates x coarse scales x (anchor, region)
    scales_a = np.exp(np.linspace(np.log(SCALE_MIN), np.log(SCALE_MAX), 17))
    step_a = np.log(scales_a[1] / scales_a[0])
    Ts = []
    for ai in anchors:
        for n, _ in regs:
            if m_a[n].sum() >= 20:
                Ts.append(((ai, n), _template(E_a[ai], m_a[n]), n))
    top = _search_level(Ts, m_a, P_a_r, scales_a, flops, topk=2)
    top = sorted(top, key=lambda r: -eff(r[0], r[1][1]))[:12]

    # level B (64px): fine scales only around the top candidates
    best = (-2.0, None)
    for v, key, ci, s0, fl, _, _ in top:
        ai, n = key
        cis = list(range(max(0, ci - 1), min(len(cand), ci + 2)))
        sc_b = s0 * np.exp(np.linspace(-1.5, 1.5, 9) * step_a)
        r = _search_level([(key, _template(E_s[ai], m_s[n]), n)], {n: m_s[n]},
                          P_s_r[cis], sc_b, [fl], topk=1)
        for v2, _, cj, s2, _, tx, ty in r:
            if eff(v2, n) > best[0]:
                best = (eff(v2, n), dict(s=s2, tx=tx, ty=ty, flop=fl, anchor=ai, region=n,
                                         plate=int(cand[cis[cj]]), ncc=v2))

    b = best[1]
    if b is None:
        # No usable template or candidate: the masked area is empty at 32 px after the two 2x
        # reductions, or every NCC is non-finite. Same result as detect=False (identity, no region).
        log('  coarse optical: no usable template, identity')
        return dict(ident, score=None, score_identity=None, anchors=anchors,
                    region='full', rmask=None, note='identity', identity_fallback=True)
    rname = b['region']
    R = dict(regs)[rname]
    log('  coarse optical: s=%.3f tx=%.4f ty=%.4f flop=%s ncc=%.3f region=%s'
        % (b['s'], b['tx'], b['ty'], b['flop'], b['ncc'], rname))

    # local refinement @W_EDIT: frames near plate candidates + pattern search
    P_m = blur121(P_lum)
    ai = b['anchor']
    lo, hi = max(0, b['plate'] - stride - 1), min(P - 1, b['plate'] + stride + 1)
    params = [b['s'], b['tx'], b['ty']]
    fl = b['flop']

    def sc(pidx, prm):
        return _score_pairs(E_lum[ai:ai + 1], R, P_m[pidx:pidx + 1],
                            prm[0], prm[1], prm[2], fl)

    pbest = max(range(lo, hi + 1), key=lambda q: sc(q, params))
    cur = sc(pbest, params)
    steps = [0.01, 1.0 / We, 1.0 / We]
    mins = [0.0005, 0.05 / We, 0.05 / We]
    for _ in range(200):
        improved = False
        for i in range(3):
            for sgn in (1, -1):
                trial = list(params)
                trial[i] += sgn * steps[i]
                v = sc(pbest, trial)
                if v > cur + 1e-6:
                    cur, params, improved = v, trial, True
        if not improved:
            if all(steps[i] <= mins[i] for i in range(3)):
                break
            steps = [max(steps[i] * 0.5, mins[i]) for i in range(3)]

    # uncorrected comparison (best of nearby frames)
    idn = max(_score_pairs(E_lum[ai:ai + 1], R, P_m[q:q + 1], 1.0, 0.0, 0.0, False)
              for q in range(max(0, pbest - 2), min(P, pbest + 3)))
    res = dict(s=params[0], tx=params[1], ty=params[2], flop=fl,
               score=cur, score_identity=idn, anchors=anchors, anchor_plate=pbest, anchor=ai,
               region=rname, rmask=None if rname == 'full' else R)
    if cur - idn < IDENTITY_TOL:
        res.update(ident)
        res['note'] = 'identity'
    log('  refined optical: s=%.4f tx=%.4f ty=%.4f flop=%s ncc=%.3f (identity %.3f)'
        % (res['s'], res['tx'], res['ty'], res['flop'], cur, idn))
    return res


def refine_optical_pairs(E_lum, E_mask, P_lum, pairs, opt, log=print, limits=None):
    """ re-refine the optical result with many matched pairs
    """
    if opt.get('note') == 'identity' or not pairs:
        return opt
    P_m = blur121(P_lum)
    ei = np.array([p[0] for p in pairs])
    pi = np.array([p[1] for p in pairs])
    Ei, Pi = E_lum[ei], P_m[pi]
    params = [opt['s'], opt['tx'], opt['ty']]
    origin = list(params)
    fl = opt['flop']
    We = E_lum.shape[-1]

    def sc(prm):
        return _score_pairs(Ei, E_mask, Pi, prm[0], prm[1], prm[2], fl)

    cur = sc(params)
    steps = [0.004, 0.5 / We, 0.5 / We]
    mins = [0.0003, 0.03 / We, 0.03 / We]
    for _ in range(200):
        improved = False
        for i in range(3):
            for sgn in (1, -1):
                trial = list(params)
                trial[i] += sgn * steps[i]
                if limits is not None and abs(trial[i] - origin[i]) > limits[i]:
                    continue
                v = sc(trial)
                if v > cur + 1e-6:
                    cur, params, improved = v, trial, True
        if not improved:
            if all(steps[i] <= mins[i] for i in range(3)):
                break
            steps = [max(steps[i] * 0.5, mins[i]) for i in range(3)]
    out = dict(opt)
    out.update(s=params[0], tx=params[1], ty=params[2], score_multi=cur)
    log('  multi-pair optical: s=%.4f tx=%.4f ty=%.4f ncc=%.3f'
        % (out['s'], out['tx'], out['ty'], cur))
    return out


def optical_identity_fullrate(E_lum, E_mask, P_lum, P_valid, opt, log=print, win=3):
    """[t06-rca prototype] Repeat estimate_optical's identity veto on the full-rate plate.

    The first-stage search sees only every S-th plate frame, so the refined geometry can absorb
    the anchor's missing temporal offset (scale/translation that mimic one frame of motion), and
    the identity comparison runs on the same sparse frames. Here the anchor's best full-rate frame
    under the estimated geometry is found, and identity wins when it scores within IDENTITY_TOL
    on any full-rate frame near it.
    """
    ai = opt.get('anchor')
    if ai is None or opt.get('note') == 'identity' or opt.get('rmask') is not None \
            or opt.get('region', 'full') != 'full':
        return opt
    P_m = blur121(P_lum)
    E1 = E_lum[ai:ai + 1]
    qs = [q for q in range(len(P_m)) if P_valid[q]]
    if not qs:
        return opt
    sc = [_score_pairs(E1, E_mask, P_m[q:q + 1], opt['s'], opt['tx'], opt['ty'], opt['flop']) for q in qs]
    qb = qs[int(np.argmax(sc))]
    cur = float(max(sc))
    idn = max(_score_pairs(E1, E_mask, P_m[q:q + 1], 1.0, 0.0, 0.0, False)
              for q in range(max(0, qb - win), min(len(P_m), qb + win + 1)) if P_valid[q])
    log('  optical identity check (full-rate plate): ncc=%.3f identity %.3f' % (cur, idn))
    if cur - idn < IDENTITY_TOL:
        out = dict(opt, s=1.0, tx=0.0, ty=0.0, flop=False, note='identity')
        log('  optical -> identity (full-rate)')
        return out
    return opt


TC_OPTICAL_RETRY_COVER = 0.80
TC_OPTICAL_RETRY_TEXTURE = 0.01
TC_OPTICAL_RETRY_NCC = 0.90
TC_OPTICAL_RETRY_GAIN = 0.02


def tc_optical_retry_allowed(tc, tc_info, opt, track, split, user_pins, E_valid):
    """Narrow gate for correcting a static optical solve that wrongly vetoed strong TC."""
    if not tc or not tc.get('pins') or tc.get('mode') == 'hint':
        return False
    if (tc_info or {}).get('mode') != 'mismatch' or user_pins:
        return False
    if track is not None and track.get('animated'):
        return False
    if (split or {}).get('split') or opt.get('rmask') is not None or opt.get('region', 'full') != 'full':
        return False
    if opt.get('note') == 'identity':
        return False
    valid_n = int(np.asarray(E_valid, bool).sum())
    covered = sum(1 for t in tc['pins'] if 0 <= int(t) < len(E_valid) and E_valid[int(t)])
    return valid_n > 0 and covered >= TC_OPTICAL_RETRY_COVER * valid_n


def tc_increment_retry_allowed(tc, tc_info, opt, track, split, user_pins,
                               E_valid, P_valid, hints, exclude, region, cuts,
                               max_speed=16):
    """Late constant-rate recovery only; never weaken the integer TC jitter veto."""
    if ((tc_info or {}).get('mode') != 'increment_mismatch' or not tc or
            tc.get('force') or tc.get('interp') or hints or cuts or region is not None or
            np.asarray(exclude, bool).any()):
        return False
    if not tc_optical_retry_allowed(tc, {'mode': 'mismatch'}, opt, track, split,
                                    user_pins, E_valid):
        return False
    points = sorted((int(t), int(q)) for t, q in (tc.get('pins') or {}).items())
    if len(points) < 8 or any(not (0 <= t < len(E_valid) and E_valid[t] and
                                  0 <= q < len(P_valid) and P_valid[q]) for t, q in points):
        return False
    dt, dq = points[1][0] - points[0][0], points[1][1] - points[0][1]
    # Candidate 3: exact affine TC excludes the measured 1f/2f periodic-lag regression.
    # This is not proof of identity; adoption also requires an unanchored image path.
    return bool(dt > 0 and dq != 0 and abs(dq) <= max_speed * dt and all(
        (b - a) * dq == (qb - qa) * dt
        for (a, qa), (b, qb) in zip(points, points[1:])))


def tc_optical_retry_adopted(tc_info, retry_pins, E_valid, user_pins=None,
                             min_cover=TC_OPTICAL_RETRY_COVER):
    """Require dense agreement on valid frames; invalid TC cannot inflate ``info.used``."""
    if (tc_info or {}).get('mode') != 'first':
        return False
    valid = np.asarray(E_valid, bool)
    user = set((user_pins or {}).keys())
    used_valid = sum(1 for t in retry_pins
                     if t not in user and 0 <= int(t) < len(valid) and valid[int(t)])
    valid_n = int(valid.sum())
    return valid_n > 0 and used_valid >= min_cover * valid_n


def _tc_optical_spread_pairs(pool, count):
    """Pick high-texture pairs across time, not a cluster from one part of the edit."""
    if not pool or count <= 0:
        return []
    out = []
    for part in np.array_split(np.arange(len(pool)), min(int(count), len(pool))):
        if len(part):
            out.append(pool[int(part[np.argmax([pool[i][2] for i in part])])])
    return out


def tc_optical_retry_candidate(E_lum, E_mask, E_valid, P_lum, P_valid, tc, opt,
                               user_pins=None, log=print, min_cover=TC_OPTICAL_RETRY_COVER,
                               min_texture=TC_OPTICAL_RETRY_TEXTURE,
                               min_ncc=TC_OPTICAL_RETRY_NCC, min_gain=TC_OPTICAL_RETRY_GAIN):
    """Fit a static optical candidate on TC pairs and accept it only on disjoint TC pairs.

    TC supplies candidate correspondences, never a result by itself.  Five to eight spread pairs
    fit scale/translation; separate held-out pairs must independently show both high absolute NCC
    and a material gain.  Flat, sparse, out-of-range and user-anchored cases return ``None``.
    """
    E_lum, P_lum = np.asarray(E_lum), np.asarray(P_lum)
    E_valid, P_valid = np.asarray(E_valid, bool), np.asarray(P_valid, bool)
    mask = np.asarray(E_mask, bool)
    pins = {} if not tc else tc.get('pins') or {}
    if user_pins or opt.get('note') == 'identity' or mask.shape != E_lum.shape[1:] or mask.sum() < 64:
        return None
    valid_n = int(E_valid.sum())
    in_range = [(int(t), int(q)) for t, q in sorted(pins.items())
                if 0 <= int(t) < len(E_lum) and E_valid[int(t)] and
                0 <= int(q) < len(P_lum) and P_valid[int(q)]]
    if valid_n <= 0 or len(in_range) < min_cover * valid_n:
        return None

    # A repeated source frame or a textureless picture cannot constrain static geometry.
    by_plate = {}
    for t, q in in_range:
        tex = min(texture_energy(to_display(E_lum[t])), texture_energy(to_display(P_lum[q])))
        if not np.isfinite(tex) or tex < min_texture:
            continue
        if q not in by_plate or tex > by_plate[q][2]:
            by_plate[q] = (t, q, float(tex))
    pool = sorted(by_plate.values())
    if len(pool) < 8:
        return None
    selected = _tc_optical_spread_pairs(pool, min(16, len(pool)))
    fit = selected[::2][:8]
    hold = selected[1::2][:8]
    if len(fit) < 5 or len(hold) < 3:
        return None

    fit_pairs = [(t, q) for t, q, _ in fit]
    hold_pairs = [(t, q) for t, q, _ in hold]
    P_m = blur121(P_lum)

    def score(pairs, prm):
        ei = np.asarray([t for t, _ in pairs], int)
        pi = np.asarray([q for _, q in pairs], int)
        return _score_pairs(E_lum[ei], mask, P_m[pi], prm['s'], prm['tx'], prm['ty'], prm['flop'])

    fit_before = score(fit_pairs, opt)
    hold_before = score(hold_pairs, opt)
    candidate = refine_optical_pairs(E_lum, mask, P_lum, fit_pairs, opt, log=lambda *a: None,
                                     limits=(0.12, 0.08, 0.08))
    fit_after = score(fit_pairs, candidate)
    hold_after = score(hold_pairs, candidate)
    gain = hold_after - hold_before
    if not all(np.isfinite(v) for v in (fit_before, hold_before, fit_after, hold_after)):
        return None
    if not (SCALE_MIN <= float(candidate['s']) <= SCALE_MAX):
        return None
    if fit_after < min_ncc or hold_after < min_ncc or gain < min_gain:
        log('  TC optical retry rejected: held-out NCC %.3f -> %.3f (gain %.3f)' %
            (hold_before, hold_after, gain))
        return None
    out = dict(candidate)
    out['tc_optical_retry'] = dict(fit_pairs=len(fit), holdout_pairs=len(hold),
                                   fit_before=float(fit_before), fit_after=float(fit_after),
                                   holdout_before=float(hold_before), holdout_after=float(hold_after),
                                   holdout_gain=float(gain), coverage=float(len(in_range)) / valid_n)
    log('  TC optical retry candidate: %d fit + %d held-out, NCC %.3f -> %.3f (gain %.3f)' %
        (len(fit), len(hold), hold_before, hold_after, gain))
    return out


def _qc_grade_identity():
    return dict(multiply=[1.0] * 3, add=[0.0] * 3, gamma=[1.0] * 3)


def apply_qc_grade_rgb(rgb, params):
    """RGB last axis. Clamp/reverse disabled; gamma extends linearly above one."""
    x = np.asarray(rgb, dtype=np.float64)
    if x.ndim < 1 or x.shape[-1] != 3:
        raise ValueError('RGB last axis must have length three')
    values = [np.asarray(params[key], dtype=np.float64) for key in ('multiply', 'add', 'gamma')]
    if any(v.shape != (3,) or not np.isfinite(v).all() for v in values) or np.any(values[2] <= 0):
        raise ValueError('Grade requires three finite parameters per knob and positive gamma')
    multiply, add, gamma = values
    u = x * multiply + add
    g = np.broadcast_to(gamma, u.shape)
    out = u.copy()
    mid, high = (u >= 0) & (u < 1), u >= 1
    out[mid] = np.power(u[mid], 1.0 / g[mid])
    out[high] = 1.0 + (u[high] - 1.0) / g[high]
    return out


def _qc_grade_inverse_gamma(y, gamma):
    out = y.copy()
    mid, high = (y >= 0) & (y < 1), y >= 1
    out[mid] = np.power(y[mid], gamma)
    out[high] = 1.0 + (y[high] - 1.0) * gamma
    return out


def _qc_grade_affine(x, y):
    """Huber IRLS without a matrix solver; fixed deterministic iterations."""
    weights = np.ones_like(x)
    for _ in range(6):
        total = weights.sum()
        mx, my = np.sum(weights * x) / total, np.sum(weights * y) / total
        denom = np.sum(weights * (x - mx) ** 2)
        if denom < 1e-10:
            return None
        mul = np.sum(weights * (x - mx) * (y - my)) / denom
        add = my - mul * mx
        residual = y - (x * mul + add)
        scale = max(1e-7, 1.4826 * np.median(np.abs(residual - np.median(residual))))
        weights = np.minimum(1.0, 1.5 * scale / np.maximum(np.abs(residual), 1e-12))
    return float(mul), float(add)


def _qc_grade_trimmed_error(delta):
    """Trim largest 20% per channel, limiting influence of sparse overlays."""
    absolute = np.sort(np.abs(delta), axis=0)
    return np.mean(absolute[:max(1, int(len(absolute) * .8))], axis=0)


def _qc_grade_full_residuals(x, y, mask, span, params):
    """All valid pixels, no sample cap or trimming; local errors remain visible."""
    rows = []
    for i in range(len(x)):
        px, py = x[i][mask[i]], y[i][mask[i]]
        row = dict(index=i, valid_pixels=len(px))
        for key, prediction in (('before', px), ('after', apply_qc_grade_rgb(px, params))):
            error = np.abs((prediction - py) / span)
            worst_channel = error.max(axis=1)
            row[key] = dict(normalized_mae=float(error.mean(axis=0).max()),
                            normalized_p95=float(np.percentile(worst_channel, 95)),
                            outlier_fraction=float(np.mean(worst_channel > .035)))
        rows.append(row)
    return rows


def fit_qc_grade(plate_rgb, edit_rgb, valid_mask=None):
    """Fit only training frames; independent heldout frames can accept or reject.

    Input: matching F,H,W,3 arrays and optional boolean F,H,W or H,W mask.
    Caller must certify frame/spatial correspondences and input color management.
    Return params is always identity on held; candidate_params exposes rejected
    fit for audit. Residuals are normalized color errors, not frame accuracy.
    """
    result = dict(status='held', params=_qc_grade_identity(), reason='invalid_input',
                  fit_indices=[], holdout_indices=[], before=None, after=None,
                  frame_residuals=[], full_residuals=[], candidate_params=None)
    try:
        x, y = np.asarray(plate_rgb, dtype=float), np.asarray(edit_rgb, dtype=float)
    except (TypeError, ValueError):
        return result
    if x.ndim != 4 or x.shape != y.shape or x.shape[-1] != 3 or not x.size:
        return result
    if not np.isfinite(x).all() or not np.isfinite(y).all() or max(np.max(np.abs(x)), np.max(np.abs(y))) > 1e4:
        result['reason'] = 'nonfinite_or_extreme_input'
        return result
    count, height, width, _ = x.shape
    if count < 6:
        result['reason'] = 'insufficient_frames'
        return result
    if valid_mask is None:
        mask = np.ones(x.shape[:-1], dtype=bool)
    else:
        mask = np.asarray(valid_mask)
        if mask.dtype != np.bool_ or mask.shape not in (x.shape[:-1], (height, width)):
            result['reason'] = 'invalid_mask'
            return result
        mask = np.broadcast_to(mask, x.shape[:-1])
    hold = [i for i in range(count) if i % 3 == 2]
    fit = [i for i in range(count) if i not in hold]
    result.update(fit_indices=fit, holdout_indices=hold)
    samples = [np.flatnonzero(mask[i].ravel()) for i in range(count)]
    fit_n = min(512, min(len(samples[i]) for i in fit))
    hold_n = min(512, min(len(samples[i]) for i in hold))
    if min(fit_n, hold_n) < 64:
        result['reason'] = 'insufficient_pixels'
        return result
    pairs = []
    for i, indices in enumerate(samples):
        n = hold_n if i in hold else fit_n
        indices = indices[np.linspace(0, len(indices) - 1, n).astype(int)]
        px, py = x[i].reshape(-1, 3)[indices], y[i].reshape(-1, 3)[indices]
        if np.any(np.percentile(px, 95, axis=0) - np.percentile(px, 5, axis=0) < .02):
            result['reason'] = 'flat_input'
            return result
        pairs.append((px, py))
    train_x = np.concatenate([pairs[i][0] for i in fit])
    train_y = np.concatenate([pairs[i][1] for i in fit])
    span = np.percentile(train_y, 95, axis=0) - np.percentile(train_y, 5, axis=0)
    if np.any(span < .02):
        result['reason'] = 'flat_target'
        return result
    before = [float(np.max(_qc_grade_trimmed_error((px - py) / span))) for px, py in pairs]
    result['before'] = dict(fit=float(np.mean([before[i] for i in fit])),
                            holdout=float(np.mean([before[i] for i in hold])))
    if max(before) <= .004:
        result.update(reason='already_matched', after=dict(result['before']),
                      full_residuals=_qc_grade_full_residuals(x, y, mask, span, _qc_grade_identity()),
                      frame_residuals=[dict(index=i, before=v, after=v) for i, v in enumerate(before)])
        return result
    params = _qc_grade_identity()
    gamma1_out_of_range = False
    for channel in range(3):
        tx, ty = train_x[:, channel], train_y[:, channel]

        def evaluate(gamma):
            affine = _qc_grade_affine(tx, _qc_grade_inverse_gamma(ty, gamma))
            if affine is None:
                return None
            mul, add = affine
            if not (.25 <= mul <= 4 and abs(add) <= max(.5, .5 * span[channel])):
                return None
            u = tx * mul + add
            predicted = u.copy()
            mid, high = (u >= 0) & (u < 1), u >= 1
            predicted[mid] = np.power(u[mid], 1.0 / gamma)
            predicted[high] = 1 + (u[high] - 1) / gamma
            error = float(_qc_grade_trimmed_error((predicted - ty)[:, None] / span[channel])[0])
            return error, mul, add, gamma

        candidates = [evaluate(g) for g in [1.0] + [float(v) for v in np.round(np.arange(.5, 2.001, .05), 8)
                                                    if abs(v - 1) > 1e-6]]
        candidates = [c for c in candidates if c is not None]
        affine = next((c for c in candidates if c[3] == 1), None)
        # gamma=1 out of range no longer holds by itself: dark/crushed
        # plates push the gamma=1 slope to the bound (test11 L2 R mul .22-.38)
        # while an in-range gamma candidate (R g.60 mul 1.14) fits and passes all
        # gates (holdout .476->.009). Hold only when no in-range candidate exists.
        if not candidates:
            result['reason'] = 'extreme_or_unstable_fit'
            return result
        gamma1_out_of_range |= affine is None
        best = min(candidates)
        # Parameter selection sees training data only. Refine the coarse winner
        # before applying the same affine-preference threshold as before.
        for radius, step in ((.025, .005), (.005, .001), (.001, .0002)):
            refined = [evaluate(float(g)) for g in np.arange(best[3] - radius,
                        best[3] + radius + step * .5, step) if .5 <= g <= 2]
            best = min([best] + [c for c in refined if c is not None])
        chosen = best if affine is None or (best[0] <= affine[0] * .8 and affine[0] - best[0] >= .002) else affine
        for key, value in zip(('multiply', 'add', 'gamma'), chosen[1:]):
            params[key][channel] = value
    result['candidate_params'] = params
    result['normalization_span'] = span.tolist()
    result['full_residuals'] = _qc_grade_full_residuals(x, y, mask, span, params)
    after = [float(np.max(_qc_grade_trimmed_error((apply_qc_grade_rgb(px, params) - py) / span))) for px, py in pairs]
    result['after'] = dict(fit=float(np.mean([after[i] for i in fit])),
                           holdout=float(np.mean([after[i] for i in hold])))
    result['frame_residuals'] = [dict(index=i, before=before[i], after=after[i],
                                     role='holdout' if i in hold else 'fit') for i in range(count)]
    if any(after[i] > .035 for i in range(count)):
        result['reason'] = 'residual_or_unstable_look'
        return result
    # The relaxed (gamma=1 out of range) path also needs every valid pixel to agree
    # test11 L2 full-frame MAE <= .027, while wrong frame pairings (test16 shifted +-3/5) fit the
    # sampled pixels yet reach .22-.31.
    if gamma1_out_of_range and any(f['after']['normalized_mae'] > .08 for f in result['full_residuals']):
        result['reason'] = 'residual_or_unstable_look'
        return result
    if any(after[i] > before[i] * .8 or before[i] - after[i] < .003 for i in hold):
        result['reason'] = 'heldout_improvement_insufficient'
        return result
    result.update(status='applied', params=params, reason='validated_constant_grade')
    return result


def qc_look_anchor_pairs(E_lum, res, max_samples=12):
    """Conservative, distinct image anchors for a QC-only constant Grade."""
    tc = res.get('tc') or {}
    if (tc.get('forced') or tc.get('lowq_released') or
            tc.get('mode') in ('offset', 'mismatch', 'increment_mismatch') or
            res.get('confidence_warn') or res.get('region') is not None or (res.get('split') or {}).get('split') or
            (res.get('optical') or {}).get('region', 'full') != 'full'):
        return []
    try:
        quality = float(res.get('quality', float('inf')))
        lum = np.asarray(E_lum, dtype=float)
        path = np.asarray(res['path'], dtype=float)
        valid = np.asarray(res['E_valid'], dtype=bool).copy()
        n = len(path)
        if (not np.isfinite(quality) or quality > WARN_QUALITY or lum.ndim != 3 or
                path.shape != (n,) or valid.shape != (n,) or len(lum) != n or
                min(lum.shape[1:]) < 2 or max_samples < 6):
            return []
        valid &= np.isfinite(path) & (path >= 0) & (path == np.rint(path))
        valid &= np.isfinite(lum).all(axis=(1, 2))
        lookup = (timewarp_output_lookup(res) if (res.get('out_node') or 'timewarp') == 'timewarp'
                  else res.get('lookup'))
        if lookup is not None:
            lookup = np.asarray(lookup, dtype=float)
            if lookup.shape != path.shape:
                return []
            valid &= np.isfinite(lookup) & (lookup == path)
        blended = res.get('blended')
        if blended is not None:
            blended = np.asarray(blended, dtype=bool)
            if blended.shape != path.shape:
                return []
            valid &= ~blended
        for key in ('lowq', 'excluded'):
            for t in res.get(key, ()):
                if 0 <= int(t) < n:
                    valid[int(t)] = False
        intervals = list(res.get('sub_spans') or [])
        intervals += [(int(c['t']) - 2, int(c['t']) + 2) for c in res.get('cuts') or []]
        intervals += [(int(s['t0']), int(s['t1'])) for s in res.get('near_hold') or []
                      if _span_state(s) not in ('tc', 'pin')]
        for a, b in intervals:
            valid[max(0, int(a)):min(n, int(b) + 1)] = False
        by_plate = {}
        for t in np.flatnonzero(valid):
            span = float(np.percentile(lum[t], 95) - np.percentile(lum[t], 5))
            if span < 1e-6:
                continue
            energy = texture_energy(lum[t]) / span
            if energy < .01:
                continue
            p = int(path[t])
            if p not in by_plate or energy > by_plate[p][1]:
                by_plate[p] = (int(t), energy)
        pool = sorted((t, p, energy) for p, (t, energy) in by_plate.items())
        if len(pool) < 6:
            return []
        chunks = np.array_split(np.arange(len(pool)), min(int(max_samples), 12, len(pool)))
        selected = [pool[int(part[np.argmax([pool[i][2] for i in part])])] for part in chunks]
        return [(t, p) for t, p, _energy in selected]
    except (KeyError, ValueError, TypeError, OverflowError):
        return []


def qc_refine_anchor_pairs(E_lum, path, E_valid, lowq=(), max_samples=8):
    """Pick 5-8 (EDIT index, PLATE index) pairs over the whole time axis for QC refinement."""
    path = np.asarray(path)
    valid = np.asarray(E_valid, bool).copy()
    if len(path) != len(E_lum) or len(valid) != len(E_lum):
        return []
    if lowq:
        valid[np.asarray([t for t in lowq if 0 <= int(t) < len(valid)], int)] = False
    # Even if a hold occupies one source frame several times, the anchor weight is given only once.
    by_plate = {}
    for t in np.where(valid)[0]:
        p = int(path[t])
        en = texture_energy(E_lum[t])
        if p not in by_plate or en > by_plate[p][1]:
            by_plate[p] = (int(t), en)
    pool = sorted((t, p, en) for p, (t, en) in by_plate.items())
    if len(pool) < 5:
        return []
    parts = np.array_split(np.arange(len(pool)), min(max(5, int(max_samples)), 8, len(pool)))
    picked = []
    for part in parts:
        if len(part):
            picked.append(pool[int(part[np.argmax([pool[i][2] for i in part])])])
    return [(t, p) for t, p, _ in sorted(picked)]


def qc_refine_optical_anchors(E_lum, P_lum, opt, mask=None, min_gain=2e-4, log=print):
    """Refine only the static scale/translate with local NCC using 5-8 high-resolution correspondence pairs.

    It never moves more than 0.006 in scale or 2 render pixels from the existing values, and returns the original opt unchanged if the NCC improvement is small or
    the input is insufficient.
    """
    E_lum, P_lum = np.asarray(E_lum), np.asarray(P_lum)
    n = len(E_lum)
    if n < 5 or n > 8 or len(P_lum) != n or E_lum.ndim != 3 or P_lum.ndim != 3:
        return opt
    if opt.get('note') == 'identity':
        return opt
    if mask is None:
        mask = edit_static_mask(E_lum)
        mask &= ~overlay_mask(E_lum, mask)[0]
    mask = np.asarray(mask, bool)
    if mask.shape != E_lum.shape[1:] or mask.sum() < 64:
        return opt
    pairs = [(i, i) for i in range(n)]
    P_m = blur121(P_lum)
    before = _score_pairs(E_lum, mask, P_m, opt['s'], opt['tx'], opt['ty'], opt['flop'])
    We = E_lum.shape[-1]
    refined = refine_optical_pairs(E_lum, mask, P_lum, pairs, opt, log=lambda *a: None,
                                   limits=(0.006, 2.0 / We, 2.0 / We))
    after = float(refined.get('score_multi', before))
    gain = after - before
    if not np.isfinite(gain) or gain < min_gain:
        log(_t('  QC optical refine: NCC 개선 %.6f — 기존 값 유지', '  QC optical refine: NCC improvement %.6f — keep existing values') % gain)
        return opt
    refined.update(qc_refined=True, qc_refine_gain=float(gain), qc_refine_anchors=n)
    log('  QC optical refine: %d anchors, NCC %.4f -> %.4f, s %.5f tx %.5f ty %.5f'
        % (n, before, after, refined['s'], refined['tx'], refined['ty']))
    return refined


def qc_refine_rendered_anchors(edit, plate, E_lum, res, edit_first, plate_first, log=print, cancelled=None):
    """Render only 5-8 frames of the final path at 512px and refine the static optical values."""
    opt = res.get('optical') or {}
    trk = res.get('track')
    if opt.get('note') == 'identity' or (trk is not None and trk.get('animated')):
        return res
    if (res.get('split') or {}).get('split'):
        return res
    W = 512
    _, _, edit_h = _thumb_size(edit, W)
    if abs(E_lum.shape[-2] / float(E_lum.shape[-1]) - edit_h / float(W)) > 0.01:
        log(_t('  QC optical refine: 크롭/필러박스 매칭은 고해상도 정밀화 생략', '  QC optical refine: skip high-resolution refinement for crop/pillarbox matching'))
        return res
    path = np.asarray(res['path'])
    eligible = np.asarray(res['E_valid'], bool).copy()
    lookup = res.get('lookup')
    if lookup is not None:
        lookup = np.asarray(lookup, np.float64)
        if len(lookup) != len(path):
            return res
        rounded = np.rint(lookup)
        eligible &= np.isfinite(lookup) & (np.abs(lookup - rounded) < 0.03) & (rounded == path)
    blended = res.get('blended')
    if blended is not None and len(blended) == len(path):
        eligible &= ~np.asarray(blended, bool)
    for a, b in res.get('sub_spans') or []:
        a, b = max(0, int(a)), min(len(eligible) - 1, int(b))
        if a <= b:
            eligible[a:b + 1] = False
    pairs = qc_refine_anchor_pairs(E_lum, path, eligible, res.get('lowq') or [], max_samples=8)
    if len(pairs) < 5:
        log(_t('  QC optical refine: 유효 앵커 %d개 — 기존 값 유지', '  QC optical refine: %d valid anchors — keep existing values') % len(pairs))
        return res
    edit_frames = [edit_first + t for t, _ in pairs]
    plate_frames = [plate_first + p for _, p in pairs]

    def check_cancel():
        if cancelled is not None and cancelled():
            raise Cancelled()

    for edit_frame, plate_frame in zip(edit_frames, plate_frames):
        check_cancel()
        ensure_thumbs(edit, edit_frame, edit_frame, 1, W, True, log)
        check_cancel()
        ensure_thumbs(plate, plate_frame, plate_frame, 1, W, True, log)
    check_cancel()
    E_hi, E_ok = load_thumbs(edit, edit_frames, W, log)
    P_hi, P_ok = load_thumbs(plate, plate_frames, W, log)
    keep = E_ok & P_ok
    if int(keep.sum()) < 5:
        log(_t('  QC optical refine: 고해상도 렌더 성공 %d개 — 기존 값 유지', '  QC optical refine: %d successful high-resolution renders — keep existing values') % int(keep.sum()))
        return res
    refined = qc_refine_optical_anchors(E_hi[keep], P_hi[keep], opt, log=log)
    check_cancel()
    if refined is opt:
        return res
    out = dict(res)
    out['optical'] = refined
    out['qc_refine'] = dict(anchors=int(keep.sum()), width=W, gain=refined['qc_refine_gain'])
    return out


# Matching
def warp_plate_stack(P_lum, opt, Ht, Wt):
    """"""
    Hp, Wp = P_lum.shape[-2:]
    xp, yp = warp_coords(Ht, Wt, Hp, Wp, opt['s'], opt['tx'], opt['ty'], opt['flop'])
    return bilinear(blur121(P_lum), xp, yp)


def _coverage(opt, Ht, Wt, Hp, Wp):
    """"""
    xp, yp = warp_coords(Ht, Wt, Hp, Wp, opt['s'], opt['tx'], opt['ty'], opt['flop'])
    return (xp >= 0) & (xp <= Wp - 1) & (yp >= 0) & (yp <= Hp - 1)


def _cells(mask):
    H, W = mask.shape
    yy, xx = np.nonzero(mask)
    cid = (yy // CELL) * ((W + CELL - 1) // CELL) + (xx // CELL)
    order = np.argsort(cid, kind='stable')
    cs = cid[order]
    starts = np.r_[0, np.nonzero(np.diff(cs))[0] + 1]
    counts = np.diff(np.r_[starts, len(cs)])
    keep = counts >= max(4, CELL * CELL // 4)
    return order, starts, counts, keep


def cost_matrix(E_feat, P_feat, mask_cells, E_valid, progress=None, cand=None):
    """
    when cand is given, compute only the candidate columns
    E_feat (E,N), P_feat (P,N) rank features -> U (E,P) cell-trimmed L1
    cand (E,P) bool: when given, compute only those columns, the rest are inf
    """
    order, starts, counts, keep = mask_cells
    Ef = E_feat[:, order]
    Pf = P_feat[:, order]
    E = Ef.shape[0]
    P = Pf.shape[0]
    U = np.zeros((E, P), np.float32) if cand is None else np.full((E, P), np.inf, np.float32)
    kc = keep.sum()
    ntrim = max(1, int(round(kc * (1.0 - TRIM))))
    for t in range(E):
        if not E_valid[t]:
            if cand is not None:
                U[t] = 0.0
            continue
        cols = slice(None) if cand is None else np.where(cand[t])[0]
        d = np.abs(Pf[cols] - Ef[t][None])
        cm = np.add.reduceat(d, starts, axis=1) / counts[None]
        cm = cm[:, keep]
        if ntrim < kc:
            cm = np.partition(cm, ntrim - 1, axis=1)[:, :ntrim]
        U[t, cols] = cm.mean(axis=1)
        if progress and t % 10 == 0:
            if progress(t, E):
                raise RuntimeError('cancelled')
    return U


def coarse_candidates(E_img, P_img, mask, E_valid, P_valid):
    """ low-resolution exhaustive comparison -> per-frame candidate columns (E,P) bool
    """
    E, P = E_img.shape[0], P_img.shape[0]
    m2 = down2(mask.astype(np.float32)) > 0.99
    Ef = rank_rows(down2(E_img)[:, m2])
    Pf = rank_rows(down2(P_img)[:, m2])
    cand = np.zeros((E, P), bool)
    k = min(CAND_TOPK, P)
    for t in range(E):
        if not E_valid[t]:
            continue
        u = np.abs(Pf - Ef[t][None]).mean(axis=1)
        u[~P_valid] = np.inf
        for q in np.argpartition(u, k - 1)[:k]:
            cand[t, max(0, q - CAND_WIN):q + CAND_WIN + 1] = True
    # for DP continuity: union of the neighbor frame candidates (+-1)
    c2 = cand.copy()
    c2[1:] |= cand[:-1]
    c2[:-1] |= cand[1:]
    return c2 & P_valid[None]


def _dp_norm(U, E_valid, P_valid, pins=None, hints=None):
    """ (formerly the first half of dp_path) cost -> normalized cost Un (E,P) + info frames (E,)
    Unit = noise floor of a correct match (median of row minima). Each row's minimum is 0
    Outside the candidate columns (uncomputed inf) = the worst cost of that row, a frame without a file = worst + DP_NOFILE (still passable)
    pins {t: p} pins (forced), hints {t: p} lagging-TC hints (weight TC_HINT_W, capped at 4 frames)
    """
    E, P = U.shape
    BIG = 1e3
    Un = np.zeros((E, P), np.float32)
    rowmin = []
    for t in range(E):
        if E_valid[t]:
            r = U[t][P_valid & np.isfinite(U[t])]
            if len(r):
                rowmin.append(float(r.min()))
    base = (float(np.median(rowmin)) if rowmin else 1.0) + 1e-6
    for t in range(E):
        if not E_valid[t]:
            Un[t] = np.where(P_valid, 0.0, DP_NOFILE)
            continue
        r = U[t].astype(np.float64)
        fin = np.isfinite(r) & P_valid
        if not fin.any():
            Un[t] = np.where(P_valid, 0.0, DP_NOFILE)
            continue
        mn, mx = r[fin].min(), r[fin].max()
        r = (np.where(fin, r, mx) - mn) / base
        r[~P_valid] = (mx - mn) / base + DP_NOFILE
        Un[t] = r

    info = np.asarray(E_valid, bool).copy()
    idx_all = np.arange(P)
    for t, q in (hints or {}).items():
        w = 1.0
        if isinstance(q, tuple):  # (p, weight) - a weak hint from TC-first mode
            q, w = q
        if 0 <= t < E and 0 <= q < P:
            Un[t] = Un[t] + TC_HINT_W * w * np.minimum(np.abs(idx_all - q), 4)
            info[t] = True
    for t, q in (pins or {}).items():
        if 0 <= t < E and 0 <= q < P:
            row = np.full(P, BIG, Un.dtype)
            row[q] = 0.0
            Un[t] = row
            info[t] = True
    if not info.any():
        raise RuntimeError(_t('EDIT 에 유효한 프레임이 없습니다', 'No valid EDIT frames'))
    return Un, info


def _dp_domain(Un, info):
    """For long plates (>2500), narrow the DP range to the per-frame minimum position +/-150"""
    P = Un.shape[1]
    if P <= 2500:
        return 0, P - 1
    a0 = np.argmin(Un, axis=1)[info]
    return int(max(0, a0.min() - 150)), int(min(P - 1, a0.max() + 150))


def _dp_jump(Un, info):
    """ (dp_path up to ) first-order speed prior + jump-allowing (DP_CAP) Viterbi.
    no longer used as the path - only to compare 'how much better it fits if jumps are allowed' when judging suspected split cuts
    """
    E, P = Un.shape
    a0 = np.argmin(Un, axis=1).astype(np.float64)
    vi = np.where(info)[0]
    a0 = np.interp(np.arange(E), vi, a0[vi])
    d = np.diff(a0)
    v = np.zeros(E)
    for t in range(1, E):
        w = d[max(0, t - 3):min(E - 1, t + 2)]
        v[t] = np.clip(np.median(w), -8, 8) if len(w) else 1.0
    lo, hi = _dp_domain(Un, info)
    idx = np.arange(lo, hi + 1)
    Pn = len(idx)
    delta = (idx[:, None] - idx[None, :]).astype(np.float32)  # p - q
    D = Un[0, lo:hi + 1].astype(np.float32)
    back = np.zeros((E, Pn), np.int32)
    cap = np.float32(DP_CAP)
    for t in range(1, E):
        _watch_tick(t, E, 'analysis')
        trans = np.minimum(DP_LAMBDA * np.abs(delta - np.float32(v[t])), cap)
        tot = trans + D[None, :]
        q = np.argmin(tot, axis=1)
        D = tot[np.arange(Pn), q] + Un[t, lo:hi + 1]
        back[t] = q
    path = np.zeros(E, np.int64)
    path[-1] = int(np.argmin(D))
    for t in range(E - 1, 0, -1):
        path[t - 1] = back[t, path[t]]
    return path + lo


def _acc_cost(d_new, d_old):
    """ speed-change cost: a change of up to 1 in integer movement per frame is almost free
    (changes that express a fractional speed with integer frames, e.g. 0.5x = 0,1,0,1 / 1.25x = 1,1,1,2 / hold start 1->0)"""
    dd = np.abs(d_new - d_old)
    return DP_ACC * np.maximum(dd - 1, 0) + DP_SMOOTH * dd


def _dp_speed(Un, info, jumps=None, speed_max=SPEED_MAX, direction=0, speed_caps=None):
    """ speed-only Viterbi. State = (plate frame p, previous movement d), d in [-SPEED_MAX, SPEED_MAX]
    * Transition: p_t = p_{t-1} + d (constant speed / ramp / hold d=0 / reverse d<0). Any other jump is forbidden
    * Cost: match Un + speed-change _acc_cost (DP_ACC for the part of the per-frame change above 1)
    * jumps (E,) bool: a discontinuous link is allowed only when entering frames the user excluded / pinned (DP_JUMP_USER)
    Returns: integer plate indices (E,)
    """
    E, P = Un.shape
    lo, hi = _dp_domain(Un, info)
    Uw = Un[:, lo:hi + 1].astype(np.float32)
    Pn = hi - lo + 1
    speed_max = min(max(1, int(speed_max)), max(1, Pn - 1), 16)
    ds = np.arange(0 if direction > 0 else -speed_max, 1 if direction < 0 else speed_max + 1)
    K = len(ds)
    acc = _acc_cost(ds[:, None], ds[None, :]).astype(np.float32)  # (k new, k' previous)
    INF = np.float32(1e9)
    D = np.repeat(Uw[0][None, :], K, axis=0)  # first frame: speed is free
    back = np.zeros((E, K, Pn), np.int8)
    jflag, jsrc = {}, {}
    for t in range(1, E):
        M = D[None, :, :] + acc[:, :, None]  # (k, k', q)
        kb = np.argmin(M, axis=1)  # (k, q)
        Mm = np.take_along_axis(M, kb[:, None, :], axis=1)[:, 0, :]
        N = np.full((K, Pn), INF, np.float32)
        B = np.zeros((K, Pn), np.int8)
        for k, d in enumerate(ds):
            if abs(d) >= Pn or (speed_caps is not None and abs(d) > speed_caps[t]):
                continue
            if d >= 0:
                N[k, d:] = Mm[k, :Pn - d]
                B[k, d:] = kb[k, :Pn - d]
            else:
                N[k, :Pn + d] = Mm[k, -d:]
                B[k, :Pn + d] = kb[k, -d:]
        if jumps is not None and jumps[t]:
            qj = np.argmin(D, axis=1)  # best starting point per speed state
            jv = D[np.arange(K), qj] + np.float32(DP_JUMP_USER)
            use = jv[:, None] < N
            N = np.where(use, jv[:, None], N)
            jflag[t], jsrc[t] = use, qj
        D = N + Uw[t][None, :]
        back[t] = B
    k, p = np.unravel_index(int(np.argmin(D)), D.shape)
    path = np.zeros(E, np.int64)
    path[-1] = p
    for t in range(E - 1, 0, -1):
        if t in jflag and jflag[t][k, p]:
            p = int(jsrc[t][k])
        else:
            k, p = int(back[t, k, p]), int(p - ds[k])
        path[t - 1] = p
    return path + lo


def snap_constant_rate(U, path, E_valid, P_valid=None, max_res=2.5, dr=0.02, tie=None):
    """ integer-rounding alignment for constant-speed edits (pure function). The DP's small speed-change penalty (DP_SMOOTH x |movement change|)
    is also charged every frame for the regular alternation of fractional speeds such as 0.5x(0,1,0,1) / 1.5x(1,2,1,2), so in weakly informative segments the path
    swings between runs of 1,1,1 / 0,0 (test06_const0p5x image only: the image cost is lower on the correct side yet exact is 78 %).
    If the path is a straight line (residual <= max_res), search a grid of slope +/-dr / phase +/-1.5 for the round(a + r t) line path with the smallest summed image cost,
    and replace the path only when that sum is lower than the DP path's summed image cost (a pure image comparison with no penalty). Returns the new path or None"""
    E, P = U.shape
    vt = np.where(np.asarray(E_valid, bool))[0]
    if len(vt) < 12:
        return None
    path = np.asarray(path)
    A = np.vstack([np.ones(len(vt)), vt.astype(float)]).T
    a, r = np.linalg.lstsq(A, path[vt].astype(float), rcond=None)[0]
    if np.abs(path[vt] - (a + r * vt)).max() > max_res or abs(r) > SPEED_MAX:
        return None
    Pv = np.ones(P, bool) if P_valid is None else np.asarray(P_valid, bool)
    cur = U[vt, path[vt]]
    if not np.all(np.isfinite(cur)):
        return None
    cur = float(cur.sum())
    best = None
    tt = np.arange(E, dtype=float)
    phases = np.arange(-1.5, 1.5001, 0.05)
    for rr in np.arange(r - dr, r + dr + 1e-9, dr / 10.0):
        C = np.round(a + phases[:, None] + rr * tt[None, :]).astype(np.int64)  # (phases, E)
        ok = (C.min(axis=1) >= 0) & (C.max(axis=1) < P)
        for i in np.where(ok)[0]:
            c = C[i]
            if not Pv[c[vt]].all():
                continue
            v = U[vt, c[vt]]
            if not np.all(np.isfinite(v)):
                continue
            s = float(v.sum())
            if best is None or s < best[0]:
                best = (s, c)
    # tie tolerance: even if the line's summed image cost is higher than the DP path by up to SNAP_TIE per frame, use the line (a difference at x264 noise level
    # misaligned 1.5x rounding by 4 frames: 2.35495 vs 2.35350, 0.000015 per frame). Two orders of magnitude smaller than the cost difference of a one-frame offset (median 0.02)
    tie = SNAP_TIE if tie is None else tie
    if best is None or best[0] >= cur + tie * len(vt) - 1e-9 or np.array_equal(best[1], path):
        return None
    return best[1]


# near-hold (still) segments: detection and handling (pure functions)
# Decision (frame t, path frame p = path[t])
# picture difference d_t = the larger of the display mean absolute differences (%) of plate p versus p+/-1 (plate_diff_table)
# cost margin m_t = (min(U[t, p+/-1]) - U[t, p]) / U[t, p]: how much worse the neighbor frames match than the path frame
# 'still' frame = d_t <= NH_PIX and m_t <= NH_MARGIN - a segment when it lasts NH_MIN_RUN or more (breaks of NH_GAP or less are bridged)
# Grades: 'ambiguous' indistinguishable = segment m median <= NH_AMBIG, ambiguous frames >= NH_AMB_SHARE, and not near a reposition-move animation / split cut
# > constant-speed line (line_fit_span) + warning window / warning badge / hatching. 'weak' weak evidence = everything else -> keep the image path, info badge
# If confident TC covers the segment and agrees with the path, it is 'confirmed by TC' (info); user pins inside the segment are anchors
def plate_diff_table(Pd, q0, q1, K=NH_K):
    """Plate picture difference table D[q - q0, k + K] = mean |Pd[q + k] - Pd[q]| x 100 (display %, k = -K..K, nan outside).
    Pd (P, ...) = display-gamma thumbnails"""
    P = Pd.shape[0]
    Pf = Pd.reshape(P, -1).astype(np.float32)
    q0, q1 = max(0, int(q0)), min(P - 1, int(q1))
    out = np.full((max(q1 - q0 + 1, 0), 2 * K + 1), np.nan, np.float32)
    for q in range(q0, q1 + 1):
        ks = [k for k in range(-K, K + 1) if 0 <= q + k < P]
        out[q - q0, [k + K for k in ks]] = 100.0 * np.abs(Pf[[q + k for k in ks]] - Pf[q][None]).mean(axis=1)
    return out


def _nh_runs(mask):
    out, a = [], None
    for i, v in enumerate(list(mask) + [False]):
        if v and a is None:
            a = i
        elif not v and a is not None:
            out.append((a, i - 1))
            a = None
    return out


def near_hold_frames(U, path, E_valid, D, q0, K=NH_K, pix=NH_PIX, margin=NH_MARGIN):
    """Per-frame decision -> dict(flag (E,) bool, width (E,) int, f (E,) matching cost, diff (E,) neighbor picture difference %, rel (E,) cost margin)
    Uncertainty width = the largest N for which picture difference <= pix and cost margin <= margin hold on both sides for j = 1..N"""
    E = len(path)
    P = U.shape[1]
    flag = np.zeros(E, bool)
    width = np.zeros(E, int)
    f = np.full(E, np.nan)
    diff = np.full(E, np.nan)
    rel = np.full(E, np.nan)
    for t in range(E):
        if not E_valid[t]:
            continue
        p = int(path[t])
        if not (0 <= p - q0 < len(D)) or not np.isfinite(U[t, p]) or U[t, p] <= 0:
            continue
        ft = float(U[t, p])
        row = D[p - q0]

        def side(j):
            dd = [row[K + s * j] for s in (-1, 1) if np.isfinite(row[K + s * j])]
            uu = [U[t, p + s * j] for s in (-1, 1) if 0 <= p + s * j < P and np.isfinite(U[t, p + s * j])]
            if not dd or not uu:
                return None, None
            return max(dd), (min(uu) - ft) / ft
        d1, r1 = side(1)
        if d1 is None:
            continue
        f[t], diff[t], rel[t] = ft, d1, r1
        if d1 > pix or r1 > margin:
            continue
        flag[t] = True
        w = 0
        for j in range(1, K + 1):
            dj, rj = side(j)
            if dj is None or dj > pix or rj > margin:
                break
            w = j
        width[t] = w
    return dict(flag=flag, width=width, f=f, diff=diff, rel=rel)


def span_uncertainty(U, path, E_valid, t0, t1, K=NH_K, z=NH_Z):
    """Uncertainty width of segment [t0, t1]: z = mean / (std / sqrt n) of the per-frame cost increase when the whole segment path is shifted by +/-k.
    Up to just before the first k that is ruled out on both sides with z > NH_Z (at least +/-1). Returns (unc, capped, zs) - zs = [(k, z-, z+)]"""
    E, P = U.shape
    ts = [t for t in range(t0, t1 + 1) if E_valid[t] and np.isfinite(U[t, int(path[t])])]
    zs, unc = [], 0
    for k in range(1, K + 1):
        zz = []
        for sgn in (-1, 1):
            d = [float(U[t, int(path[t]) + sgn * k] - U[t, int(path[t])]) for t in ts
                 if 0 <= int(path[t]) + sgn * k < P and np.isfinite(U[t, int(path[t]) + sgn * k])]
            if len(d) < 4:
                zz.append(np.inf)  # end of plate: cannot go that way
                continue
            d = np.asarray(d)
            zz.append(float(d.mean() / (d.std() / np.sqrt(len(d)) + 1e-9)))
        zs.append((k, round(zz[0], 1), round(zz[1], 1)))
        if min(zz) > z:
            break
        unc = k
    return max(1, unc), bool(unc >= K), zs


def near_hold_spans(U, path, E_valid, D, q0, K=NH_K, pix=NH_PIX, margin=NH_MARGIN, min_run=NH_MIN_RUN, gap=NH_GAP,
                    anchor=NH_ANCHOR, animated=False, cuts=()):
    """Still segments -> [dict(t0, t1, n, unc, unc_capped, left, right, anchor, diff_max, resid, margin, amb, tier, near_cut)]
    left / right = confirmed anchor EDIT indices outside the segment (None if absent). anchor = 'both' | 'start' | 'end' | 'none'
    diff_max = largest neighbor-frame picture difference of the plate inside the segment (display %), resid = median matching cost (match-quality scale %),
    margin = median cost margin"""
    fr = near_hold_frames(U, path, E_valid, D, q0, K, pix, margin)
    flag, E = fr['flag'].copy(), len(path)
    ev = np.asarray(E_valid, bool)
    runs = _nh_runs(flag | ~ev)  # bridge short breaks (gap or less, invalid frames included)
    spans = []
    for a, b in runs:
        core = np.where(flag[a:b + 1])[0]
        if not len(core):
            continue
        spans.append([a + int(core[0]), a + int(core[-1])])
    merged = []
    for a, b in spans:
        if merged and a - merged[-1][1] - 1 <= gap:
            merged[-1][1] = b
        else:
            merged.append([a, b])
    out = []
    good = ev & ~flag
    for a, b in merged:
        n = b - a + 1
        if fr['flag'][a:b + 1].sum() < min_run:
            continue
        left = right = None
        if a - anchor >= 0 and good[a - anchor:a].all():
            left = a - 1
        if b + anchor < E and good[b + 1:b + 1 + anchor].all():
            right = b + 1
        unc, capped, zs = span_uncertainty(U, path, E_valid, a, b, K)
        stp = fr['diff'][a:b + 1]
        ff = fr['f'][a:b + 1]
        rr = fr['rel'][a:b + 1]
        sp = dict(t0=a, t1=b, n=n, unc=unc, unc_capped=capped, zs=zs, left=left, right=right,
                  anchor='both' if left is not None and right is not None else
                  ('start' if left is not None else ('end' if right is not None else 'none')),
                  diff_max=float(np.nanmax(stp)), resid=float(100 * np.nanmedian(ff) / COST_RANDOM),
                  margin=float(np.nanmedian(rr)), flagged=int(fr['flag'][a:b + 1].sum()))
        amb = []
        for t in range(a, b + 1):
            if not ev[t] or not np.isfinite(U[t, int(path[t])]):
                continue
            far = (np.abs(np.arange(U.shape[1]) - int(path[t])) > 2) & np.isfinite(U[t])
            amb.append(bool(far.any() and U[t, far].min() < U[t, int(path[t])] * 1.03))
        sp['amb'] = float(np.mean(amb)) if amb else 0.0
        # Reposition-move animations have per-frame warps in cost, so the margin comes out small -> left to the 'time-movement ambiguity' warning
        # if a suspected split cut is inside the segment / within 3 frames, the path may not have followed past the cut -> left to the cut warning (not covered with a line)
        near_cut = any(a - 3 <= int(c) <= b + 3 for c in cuts)
        sp['near_cut'] = near_cut
        sp['tier'] = 'ambiguous' if (sp['margin'] <= NH_AMBIG and sp['amb'] >= NH_AMB_SHARE and not animated
                                     and not near_cut) else 'weak'
        # rule E: weak evidence + confirmed frames on only one side or none + edit difference >= NH_UNSURE_RESID -> 'insufficient evidence (needs checking)'
        sp['unsure'] = bool(sp['tier'] == 'weak' and sp['anchor'] != 'both' and sp['resid'] >= NH_UNSURE_RESID)
        if sp['tier'] == 'ambiguous':  # the path follows noise: a phase-shift check is meaningless -> use the picture difference width
            w = fr['width'][a:b + 1][fr['flag'][a:b + 1]]
            sp['unc'] = int(max(1, np.max(w))) if len(w) else 1
            sp['unc_capped'] = bool(sp['unc'] >= K)
        out.append(sp)
    return out


def bridge_near_hold(path, spans, pins=None):
    """Pin handling: connect anchors outside the segment + pins inside it as knots with a constant-speed line (the tail beyond the end knots is extended at the speed of the two nearest knots,
    with one knot, the least-squares slope through that point). Returns the new path"""
    path = np.asarray(path).copy()
    pins = dict(pins or {})
    for s in spans:
        a, b = s['t0'], s['t1']
        knots = []
        if s['left'] is not None:
            knots.append((s['left'], int(path[s['left']])))
        knots += [(t, int(q)) for t, q in sorted(pins.items()) if a <= t <= b]
        if s['right'] is not None:
            knots.append((s['right'], int(path[s['right']])))
        seg_t = np.arange(a, b + 1)
        if len(knots) >= 2:
            kt = np.array([k[0] for k in knots], float)
            kq = np.array([k[1] for k in knots], float)
            inner = (seg_t >= kt[0]) & (seg_t <= kt[-1])
            path[seg_t[inner]] = np.round(np.interp(seg_t[inner], kt, kq)).astype(int)
            rest = seg_t[~inner]
            if len(rest):
                i0, i1 = (0, 1) if rest[0] < kt[0] else (-2, -1)
                r = (kq[i1] - kq[i0]) / max(kt[i1] - kt[i0], 1.0)
                ref_t, ref_q = (kt[0], kq[0]) if rest[0] < kt[0] else (kt[-1], kq[-1])
                path[rest] = np.round(ref_q + r * (rest - ref_t)).astype(int)
            continue
        x = seg_t.astype(float)
        y = path[seg_t].astype(float)
        if len(knots) == 1:
            t1, q1 = knots[0]
            dx = x - t1
            r = float((dx * (y - q1)).sum() / max((dx * dx).sum(), 1e-9))
            path[seg_t] = np.round(q1 + r * dx).astype(int)
        else:
            A = np.vstack([np.ones(len(x)), x]).T
            c0, r = np.linalg.lstsq(A, y, rcond=None)[0]
            path[seg_t] = np.round(c0 + r * x).astype(int)
    return np.maximum(path, 0)


def line_fit_span(U, path, E_valid, t0, t1, left=None, right=None, dr=0.02):
    """Handling of 'indistinguishable' segments: make the path inside the segment a constant-speed line. If anchors exist on both sides, a line straight between the two anchors.
    Otherwise take phase (+/-NH_PHASE) and slope (+/-dr) around the least-squares line of the image path inside the segment, choosing the smallest pure image cost sum
    (same grid as snap_constant_rate but without requiring it to be lower than the DP path - the DP path that followed noise is always lower).
    Returns the new path piece (t0..t1)"""
    E, P = U.shape
    tt = np.arange(t0, t1 + 1)
    vt = np.array([t for t in tt if E_valid[t]])
    if len(vt) < 4:
        return np.asarray(path)[tt].copy()
    if left is not None and right is not None:
        r0 = (float(path[right]) - float(path[left])) / float(right - left)
        c = np.floor(float(path[left]) + r0 * (tt - left) + 0.5).astype(int)
        return np.clip(c, 0, P - 1)
    A = np.vstack([np.ones(len(vt)), vt.astype(float)]).T
    a0, r0 = np.linalg.lstsq(A, np.asarray(path)[vt].astype(float), rcond=None)[0]
    phases = np.arange(-NH_PHASE, NH_PHASE + 1e-3, 0.05)
    best = None
    for rr in np.arange(r0 - dr, r0 + dr + 1e-9, dr / 5.0):
        for ph in phases:
            c = np.floor(a0 + ph + rr * tt + 0.5).astype(int)
            if c.min() < 0 or c.max() >= P:
                continue
            v = U[vt, c[vt - t0]]
            if not np.all(np.isfinite(v)):
                continue
            sc = float(v.sum())
            if best is None or sc < best[0]:
                best = (sc, c)
    return np.asarray(path)[tt].copy() if best is None else best[1]


def _near_hold_curve_shape(path, E_valid):
    """Return direction changes, longest true repeat, and largest adjacent step."""
    path = np.asarray(path, int)
    valid = np.asarray(E_valid, bool)
    signs = []
    longest = current = 1
    max_step = 0
    for t in range(1, len(path)):
        if not (valid[t - 1] and valid[t]):
            current = 1
            continue
        step = int(path[t]) - int(path[t - 1])
        max_step = max(max_step, abs(step))
        if step == 0:
            current += 1
            longest = max(longest, current)
        else:
            current = 1
            signs.append(1 if step > 0 else -1)
    changes = sum(a != b for a, b in zip(signs, signs[1:]))
    return changes, longest, max_step


def _near_hold_curve_span(spans):
    eligible = [s for s in (spans or ())
                if s.get('tier') == 'ambiguous' and s.get('anchor') == 'both']
    if len(eligible) != 1 or len(spans or ()) != 1:
        return None
    span = eligible[0]
    if (span.get('tc') or span.get('pinned') or
            span.get('tc_endpoint') == 'mismatch'):
        return None
    return span


def near_hold_curve_retry_allowed(path, E_valid, spans, pins=None, hints=None,
                                  tc_pins=None, tc_hints=None, cuts=(), track=None,
                                  split=None, exclude=None):
    """Narrow gate for a GT-blind smooth-ramp retry inside one NH span."""
    if pins or hints or tc_pins or tc_hints or cuts or track is not None:
        return False
    if split and split.get('split'):
        return False
    if exclude is not None and np.asarray(exclude, bool).any():
        return False
    span = _near_hold_curve_span(spans)
    valid = np.asarray(E_valid, bool)
    if span is None or int(valid.sum()) < 32:
        return False
    changes, longest, unused_step = _near_hold_curve_shape(path, valid)
    return changes == 0 and longest < 4


def near_hold_curve_candidate(U, path, E_valid, spans, pins=None, max_speed=16):
    """Fit a monotone quadratic from strong exterior rows and validate inside.

    Two of every three rows in the NH span tune the coefficient grid. The third
    row is reserved for validation and excluded from coefficient search. The
    initial path still uses all rows. Only the NH span is replaced; the accepted
    image path outside remains byte-for-byte identical.
    """
    path = np.asarray(path, int)
    valid = np.asarray(E_valid, bool)
    span = _near_hold_curve_span(spans)
    if pins:
        return None, dict(reason='pins', accepted=False)
    if span is None:
        return None, dict(reason='not_one_both_anchored_ambiguous_span', accepted=False)
    times = np.where(valid)[0]
    if len(times) < 32:
        return None, dict(reason='few_valid', accepted=False)
    changes, longest, raw_step_max = _near_hold_curve_shape(path, valid)
    if changes:
        return None, dict(reason='direction_change', accepted=False)
    if longest >= 4:
        return None, dict(reason='hold_or_heavy_repeat', accepted=False)

    t0, t1 = int(span['t0']), int(span['t1'])
    clock = np.arange(len(path))
    inside = valid & (clock >= t0) & (clock <= t1)
    outside = valid & ~inside
    holdout = inside & ((clock - t0) % 3 == 1)
    fit = inside & ~holdout
    if int(outside.sum()) < 8 or int(fit.sum()) < 8 or int(holdout.sum()) < 8:
        return None, dict(reason='few_independent_samples', accepted=False)

    seed_t = np.where(outside)[0]
    # Center the time basis on the replaced interval. Prefix padding and the
    # absolute edit frame number must not change the candidate family.
    clock_f = clock.astype(np.float64) - .5 * (t0 + t1)
    coefficients = np.polyfit(clock_f[seed_t], path[seed_t].astype(float), 2)
    residual = np.abs(path[times] - np.polyval(coefficients, clock_f[times]))
    if float(np.max(residual)) > 3.0:
        return None, dict(reason='not_single_smooth_curve', accepted=False,
                          seed_residual_max=float(np.max(residual)))

    # Search order remains stable: dc, db, then phase. Equal image costs prefer
    # the smallest departure from the exterior seed; fully equal ranks keep the
    # first candidate in that stable order.
    phase_grid = np.arange(-2.0, 2.001, 0.05)
    fit_t = np.where(fit)[0]
    def search(dc_grid, db_grid, phase_values):
        best_local = None
        for dc in dc_grid:
            for db in db_grid:
                base = ((coefficients[0] + dc) * clock_f * clock_f +
                        (coefficients[1] + db) * clock_f + coefficients[2])
                rows = np.floor(base[None] + phase_values[:, None] + 0.5).astype(int)
                span_rows = rows[:, t0:t1 + 1]
                usable = ((span_rows.min(axis=1) >= 0) &
                          (span_rows.max(axis=1) < U.shape[1]))
                indexes = np.where(usable)[0]
                if not len(indexes):
                    continue
                values = U[fit_t[None, :], rows[indexes][:, fit_t]]
                finite = np.isfinite(values).all(axis=1)
                if not finite.any():
                    continue
                scores = np.where(finite, values.mean(axis=1), np.inf)
                tied = np.flatnonzero(np.abs(scores - scores.min()) <= 1e-12)
                local = int(tied[np.argmin(np.abs(phase_values[indexes[tied]]))])
                score = float(scores[local])
                index = int(indexes[local])
                regularizer = ((float(dc) / 0.0015) ** 2 +
                               (float(db) / 0.08) ** 2 +
                               (float(phase_values[index]) / 2.0) ** 2)
                better = (best_local is None or score < best_local[0] - 1e-12 or
                          (abs(score - best_local[0]) <= 1e-12 and
                           regularizer < best_local[5] - 1e-12))
                if better:
                    best_local = (score, rows[index].copy(), float(dc), float(db),
                                  float(phase_values[index]), float(regularizer))
        return best_local

    best = search(np.arange(-0.0015, 0.001501, 0.0001),
                  np.arange(-0.08, 0.0801, 0.004), phase_grid)
    if best is not None:
        # A bounded second pass only uses the same fit rows. The holdout remains
        # untouched until the final accept/reject decision.
        fine = search(np.arange(best[2] - 0.0001, best[2] + 0.0001001, 0.00002),
                      np.arange(best[3] - 0.004, best[3] + 0.00401, 0.0008),
                      np.arange(best[4] - 0.05, best[4] + 0.0501, 0.01))
        if fine is not None and (fine[0] < best[0] - 1e-12 or
                                 (abs(fine[0] - best[0]) <= 1e-12 and
                                  fine[5] < best[5] - 1e-12)):
            best = fine
    if best is None:
        return None, dict(reason='no_candidate', accepted=False)

    candidate = path.copy()
    candidate[t0:t1 + 1] = best[1][t0:t1 + 1]
    candidate_changes, unused_longest, candidate_step_max = _near_hold_curve_shape(candidate, valid)
    if candidate_changes:
        return None, dict(reason='candidate_direction_change', accepted=False)
    if candidate_step_max > max_speed:
        return None, dict(reason='configured_max_speed', accepted=False)
    if candidate_step_max > raw_step_max + 1:
        return None, dict(reason='candidate_step_growth', accepted=False,
                          raw_step_max=int(raw_step_max), candidate_step_max=int(candidate_step_max))

    boundary = {}
    for label, before, after in (('left', t0 - 1, t0), ('right', t1, t1 + 1)):
        if before < 0 or after >= len(path) or not (valid[before] and valid[after]):
            continue
        raw_step = abs(int(path[after]) - int(path[before]))
        candidate_step = abs(int(candidate[after]) - int(candidate[before]))
        if label == 'left':
            outer_before, outer_after = before - 1, before
        else:
            outer_before, outer_after = after, after + 1
        exterior_step = 0
        if (0 <= outer_before < len(path) and 0 <= outer_after < len(path) and
                valid[outer_before] and valid[outer_after]):
            exterior_step = abs(int(path[outer_after]) - int(path[outer_before]))
        limit = max(int(raw_step), int(exterior_step)) + 1
        boundary[label] = dict(raw=int(raw_step), candidate=int(candidate_step), limit=int(limit))
        if candidate_step > limit:
            return None, dict(reason='boundary_step_discontinuity', accepted=False,
                              boundary=boundary)
    if np.max(np.abs(candidate - path)) > max(3, int(span.get('unc') or 0)):
        return None, dict(reason='outside_uncertainty', accepted=False)

    def cost(candidate_path, mask):
        tt = np.where(mask)[0]
        values = U[tt, np.asarray(candidate_path, int)[tt]]
        return float(values.mean())

    costs = {}
    # "full" deliberately means every valid row in the replaced span. Unchanged
    # exterior rows cannot dilute either a small gain or a local regression.
    for label, mask in (('fit', fit), ('holdout', holdout), ('full', inside)):
        before = cost(path, mask)
        after = cost(candidate, mask)
        costs[label] = dict(before=before, after=after,
                            gain=(before - after) / max(before, 1e-12),
                            absolute_gain=before - after)
    info = dict(reason='accepted', accepted=True, span=[t0, t1],
                score_scope='span_local_valid',
                seed_coefficients=[float(value) for value in coefficients],
                delta=[best[2], best[3], best[4]], coefficient_regularizer=best[5],
                seed_residual_max=float(np.max(residual)),
                max_change_from_raw=int(np.max(np.abs(candidate - path))),
                raw_step_max=int(raw_step_max), candidate_step_max=int(candidate_step_max),
                boundary=boundary, costs=costs)
    guards = (costs['fit']['gain'] >= 0.0015,
              costs['holdout']['gain'] >= 0.0030,
              costs['full']['gain'] >= 0.0020,
              costs['fit']['absolute_gain'] >= 2e-5,
              costs['holdout']['absolute_gain'] >= 2e-5)
    if not all(guards):
        info.update(reason='insufficient_independent_gain', accepted=False)
        return None, info
    return candidate, info


def respond_near_hold(U, path, E_valid, spans, pins=None):
    """Handling of the adopted plan: only 'ambiguous' segments get a constant-speed line (line_fit_span); 'weak' and TC-confirmed segments keep the image path.
    If a segment holds 2 or more user pins (or 1 pin + an anchor), connect between those pins with a line (bridge_near_hold). Returns the new path"""
    out = np.asarray(path).copy()
    pins = dict(pins or {})
    for s in spans:
        if s.get('tc'):
            continue
        inside = dict((t, q) for t, q in pins.items() if s['t0'] <= t <= s['t1'])
        if len(inside) >= 2 or (inside and (s['left'] is not None or s['right'] is not None)):
            out = bridge_near_hold(out, [s], inside)
            for t, q in inside.items():
                out[t] = q
            s['bridged'] = True
            continue
        if s.get('tier') != 'ambiguous' or s.get('tc_endpoint') == 'mismatch':
            continue
        out[s['t0']:s['t1'] + 1] = line_fit_span(U, out, E_valid, s['t0'], s['t1'], s['left'], s['right'])
        s['bridged'] = True
    return out


def tc_fill_near_hold(path, spans, tc_knots, cuts=(), dev_min=2):
    """ interpolation between confident TCs inside a still segment: when TC is sparse (coverage 20 %, max gap 13) and the path between pins follows noise
    (test06_zoom_drift_ramp: all 18 TC frames are right but in between it is -2 to -4). Between two neighboring TC knots inside the segment,
    if the path deviates from the line of the two knots by dev_min frames or more, replace that stretch with a (rounded) line - differences within 1 frame (fractional-speed rounding) are
    left alone. Gaps with a 'confirmed by TC' segment / suspected split cut in between are untouched. Returns the new path (span['tc_fill'] = number of frames changed)"""
    out = np.asarray(path).copy()
    for s in spans:
        if s.get('tc'):
            continue
        ks = sorted(t for t in tc_knots if s['t0'] - 1 <= t <= s['t1'] + 1)
        n = 0
        for ta, tb in zip(ks[:-1], ks[1:]):
            if tb - ta < 2 or any(ta < int(c) <= tb for c in cuts):
                continue
            qa, qb = float(tc_knots[ta]), float(tc_knots[tb])
            tt = np.arange(ta + 1, tb)
            line = np.floor(qa + (qb - qa) * (tt - ta) / float(tb - ta) + 0.5).astype(int)
            if np.abs(out[tt] - line).max() >= dev_min:
                n += int((out[tt] != line).sum())
                out[tt] = line
        if n:
            s['tc_fill'] = n
    return out


def tc_confirm(spans, path, tc_pins, cover=NH_TC_COVER, image_path=None, interp_frames=()):
    """If the confident TC pins {t: p} cover at least cover of the segment and the path equals that TC, span['tc'] = True (confirmed by TC)"""
    out = []
    for s in spans:
        hit = [t for t in range(s['t0'], s['t1'] + 1) if t in tc_pins]
        agree = [t for t in hit if int(path[t]) == int(tc_pins[t])]
        endpoint = 'unchecked'
        if hit and image_path is not None:
            endpoint = 'agree'
            for t, anchor in ((hit[0], s.get('left')), (hit[-1], s.get('right'))):
                tolerance = 1 if t in interp_frames or anchor in interp_frames else 0
                if abs(int(tc_pins[t]) - int(image_path[t])) > tolerance:
                    endpoint = 'mismatch'
                if anchor is not None and 0 <= anchor < len(path):
                    # Compare the entrance/exit increment with an independently solved path.
                    if abs(int(path[anchor]) - int(image_path[anchor])) > tolerance:
                        endpoint = 'mismatch'
        covered = bool(len(hit) >= cover * s['n'] and len(agree) == len(hit))
        out.append(dict(s, tc=covered and endpoint != 'mismatch', tc_path_agree=covered,
                        tc_n=len(hit), tc_endpoint=endpoint,
                        unsure=bool(s.get('unsure') or endpoint == 'mismatch')))
    return out


def pin_confirm(spans, user_pins):
    """If a user pin is inside the segment, span['pinned'] = number of pins"""
    return [dict(s, pinned=len([t for t in (user_pins or {}) if s['t0'] <= t <= s['t1']])) for s in spans]


def near_hold_subframe_block(spans, length, image_blend_spans=()):
    """Keep TC endpoint warnings separate from independently supported interpolation."""
    block = np.zeros(length, bool)
    for span in spans:
        a, b = int(span['t0']), int(span['t1']) + 1
        if _span_state(span) in ('ambiguous', 'unsure', 'weak'):
            block[a:b] = True
            if span.get('tc_path_agree'):
                for x, y in image_blend_spans:
                    block[max(a, int(x)):min(b, int(y) + 1)] = False
    return block


def _path_energy(Un, path, jumps=None):
    value = float(Un[np.arange(len(path)), path].sum())
    if len(path) > 2:
        steps = np.diff(path)
        terms = _acc_cost(steps[1:], steps[:-1])
        if jumps is not None:
            terms = np.where(np.asarray(jumps)[2:] | np.asarray(jumps)[1:-1], 0, terms)
        value += float(terms.sum())
    return value


def _continuous_path(Un, info, jumps=None, max_speed=16, direction_policy=True):
    """ Local speed expansion, then an evidence-gated direction choice."""
    limit = min(16, max(SPEED_MAX, int(max_speed)))
    path = _dp_speed(Un, info, jumps)
    E = len(path)
    caps = np.full(E, SPEED_MAX, int)
    if limit > SPEED_MAX and E >= 5:
        amin = np.argmin(Un, axis=1)
        velocity = np.r_[0, np.diff(amin)]
        evidence_velocity = velocity.astype(float).copy()
        for t in range(1, E):
            a, b = max(1, t - 2), min(E, t + 3)
            local = velocity[a:b]
            if np.all(info[a - 1:b]) and (np.all(local >= 0) or np.all(local <= 0)):
                evidence_velocity[t] = np.median(local)
        saturated = np.r_[False, np.abs(np.diff(path)) >= SPEED_MAX]
        isolated = {}
        for t in range(4, E - 3):
            nb = np.r_[velocity[t-3:t], velocity[t+1:t+4]]
            typical = float(np.median(nb))
            if (np.all(info[t-3:t+4]) and np.max(np.abs(nb - typical)) <= 1 and
                    abs(float(velocity[t]) - typical) >= CUT_MIN_JUMP):
                isolated[t] = max(SPEED_MAX, int(np.ceil(abs(typical))))
        # Single jumps remain cuts. Require a sustained, coherent high-speed run.
        for sign in (-1, 1):
            fast = info & (sign * evidence_velocity > SPEED_MAX) & (sign * evidence_velocity <= limit)
            for t in isolated:
                fast[t] = False
            for a, b in _nh_runs(fast):
                if b - a + 1 < 3 or not saturated[max(0, a-4):min(E, b+5)].any():
                    continue
                cap = min(limit, 8 if np.max(np.abs(velocity[a:b+1])) <= 8 else 16)
                caps[max(1, a-4):min(E, b+5)] = cap
        for t, cap in isolated.items():
            caps[t] = min(caps[t], cap)
        if caps.max() > SPEED_MAX:
            candidate = _dp_speed(Un, info, jumps, speed_max=int(caps.max()), speed_caps=caps)
            if _path_energy(Un, candidate, jumps) < _path_energy(Un, path, jumps):
                path = candidate
    # A one-direction path already meets the default. The DP preserves explicit user jumps locally.
    if not direction_policy:
        return path
    steps = np.diff(path)
    if not (np.any(steps > 0) and np.any(steps < 0)):
        return path
    candidates = [_dp_speed(Un, info, jumps, speed_max=int(caps.max()), direction=d, speed_caps=caps)
                  for d in (1, -1)]
    scores = [_path_energy(Un, p, jumps) for p in candidates]
    mono = candidates[int(np.argmin(scores))]
    best = min(scores)
    gain = best - _path_energy(Un, path, jumps)
    # Real boomerangs have a substantial image advantage over either monotonic explanation.
    return path if gain > max(.1 * abs(best), .02 * max(int(np.sum(info)), 1)) else mono


def dp_path(U, E_valid, P_valid, pins=None, hints=None, jumps=None, max_speed=16, direction_policy=True):
    """ speed-continuity Viterbi. Returns: integer plate indices (E,)
    pins {t: p} pins (forced), hints {t: p} lagging-TC hints (weight TC_HINT_W, capped at 4 frames)
    only speed changes are allowed (_dp_speed). Jump cuts are not accepted as a path, they are warned about separately via cut_suspects
    """
    Un, info = _dp_norm(U, E_valid, P_valid, pins, hints)
    return _continuous_path(Un, info, jumps, max_speed=max_speed, direction_policy=direction_policy)


def cut_suspects(U, E_valid, P_valid, pins=None, hints=None, jumps=None, max_speed=16):
    """ suspected split-cut points. Returns [dict(t, jump, excess, mismatch, span)]  (t = first EDIT index after the cut)
    Solve and compare the speed-only path (pc) and the jump-allowing path (pu, the  method) on the same cost matrix:
      e[t] = Un[t,pc] - Un[t,pu] + the speed-change cost of pc
    If the shot is explained by speed changes alone, the two paths are equal and e ~ 0.
    Suspect when the sum over a group of frames with e > CUT_FRAME_EXCESS (gap 3 or less) is at least CUT_MIN_EXCESS,
    the position is the frame near the group where pu jumps the most relative to pc (the group start if the jump is below CUT_MIN_JUMP)
    """
    Un, info = _dp_norm(U, E_valid, P_valid, pins, hints)
    E = Un.shape[0]
    if E < 4:
        return []
    pc = _continuous_path(Un, info, jumps, max_speed=max_speed)
    pu = _dp_jump(Un, info)
    ar = np.arange(E)
    # Unit = cost separation sep (median of row median - row minimum: the difference between 'the right picture' and 'any picture').
    # The noise-floor (base) unit grows with heavy grain / compression, so the same jump would look smaller
    cost_row = np.full(E, np.nan)
    seps = []
    for t in range(E):
        r = U[t][np.isfinite(U[t]) & P_valid]
        if E_valid[t] and len(r):
            cost_row[t] = float(r.min())
            seps.append(float(np.median(r)) - cost_row[t])
    ok = np.isfinite(cost_row)
    if not ok.any():
        return []
    base = float(np.median(cost_row[ok])) + 1e-6  # same normalization unit as _dp_norm
    sep = max(float(np.median(seps)), 1e-6)
    e = (Un[ar, pc] - Un[ar, pu]).astype(np.float64)
    dc = np.diff(pc)
    e[2:] += _acc_cost(dc[1:], dc[:-1]) - DP_SMOOTH * np.abs(dc[1:] - dc[:-1])
    e[~info] = 0.0
    e *= base / sep
    du = np.r_[0, np.diff(pu)]
    dcc = np.r_[0, dc]
    rel = np.abs(du - dcc)

    def isolated_jump(a, b):
        """The frame where pu jumps at once by CUT_MIN_JUMP or more over the surrounding speed (median) (None if none)"""
        best = None
        for t in range(max(1, a), min(E - 1, b) + 1):
            nb = np.r_[du[max(1, t - 6):t], du[t + 1:min(E, t + 7)]]
            if not len(nb):
                continue
            j = abs(du[t] - np.median(nb))
            if j >= CUT_MIN_JUMP and (best is None or j > best[1]):
                best = (t, j)
        return None if best is None else best[0]

    def user_fixed(t):
        return jumps is not None and bool(np.any(jumps[max(0, t - 2):min(E, t + 3)]))

    out = []
    bad = np.where(e > CUT_FRAME_EXCESS)[0]
    groups = []
    for t in bad:
        if groups and t - groups[-1][-1] <= 3:
            groups[-1].append(t)
        else:
            groups.append([t])
    for g in groups:
        g0, g1 = int(g[0]), int(g[-1])
        S = float(e[g0:g1 + 1].sum())
        tj = isolated_jump(g0 - 3, g1 + 1)
        # Strong evidence (large excess cost) or medium evidence + an isolated jump of the jump-allowing path (+4~8 small jump cut)
        if S < CUT_MIN_EXCESS and not (S >= CUT_JUMP_EXCESS and tj is not None):
            continue
        if tj is None:
            a, b = max(1, g0 - 3), min(E - 1, g1 + 1)
            tj = a + int(np.argmax(rel[a:b + 1]))
            if rel[tj] < CUT_MIN_JUMP:
                tj = g0
        out.append(dict(t=int(tj), excess=round(S, 1), span=(g0, g1)))

    # A stretch after the cut that matches nowhere in the plate suddenly starts / ends -> suspect a cut to another source
    hi_thr = np.inf
    if ok.sum() >= 8:
        good_lvl = float(np.percentile(cost_row[ok], 25))
        hi_thr = good_lvl + CUT_MISMATCH_SEP * sep
        hiq = ok & (cost_row > hi_thr)
        t = 0
        while t < E:
            if not hiq[t]:
                t += 1
                continue
            a = t
            while t < E and (hiq[t] or not ok[t]):
                t += 1
            b = t - 1
            n = int(hiq[a:b + 1].sum())
            if n >= CUT_MISMATCH_RUN or (b == E - 1 and n >= 4):
                for tc in ([a] if a > 0 else []) + ([b + 1] if b + 1 < E else []):
                    side = cost_row[max(0, tc - 6):tc] if tc == a else cost_row[tc:tc + 6]
                    side = side[np.isfinite(side)]
                    if len(side) and np.median(side) <= good_lvl + 0.2 * sep:
                        out.append(dict(t=int(tc), excess=float(n), span=(a, b), mismatch=True))

    res = []
    for c in sorted(out, key=lambda c: c['t']):
        if user_fixed(c['t']):
            continue  # a point the user has already resolved by exclusion / pin
        t = c['t']  # jump size = that frame's movement on the jump path - surrounding speed
        nb = np.r_[du[max(1, t - 6):t], du[t + 1:min(E, t + 7)]]
        c['jump'] = int(round(du[t] - np.median(nb))) if t >= 1 and len(nb) else 0
        if 'mismatch' not in c:
            post = cost_row[c['t']:c['t'] + 12]
            post = post[np.isfinite(post)]
            c['mismatch'] = bool(len(post) and np.median(post) > hi_thr)
        # Deduplicate near the same point (8 frames) - prefer other-source decisions / larger excess cost
        if res and c['t'] - res[-1]['t'] <= 8:
            if (c['mismatch'], c['excess']) > (res[-1]['mismatch'], res[-1]['excess']):
                res[-1] = c
            continue
        res.append(c)
    return res


def direction_changes(path, valid):
    """ EDIT indices where the playback direction (forward/reverse) changes (holds are skipped). For report information"""
    d = np.diff(np.asarray(path, np.int64))
    out, last = [], 0
    for t in range(1, len(path)):
        if not (valid[t] and valid[t - 1]):
            continue
        s = int(np.sign(d[t - 1]))
        if s == 0:
            continue
        if last and s != last:
            out.append(t)
        last = s
    return out


def residual_mask(E_feat, P_feat, path, E_valid, mask):
    """ burn-in/logo/matte: remove pixels that still consistently fail to match after matching
    """
    vt = np.where(E_valid)[0]
    if len(vt) < 3:
        return mask, 0.0
    r = np.median(np.abs(E_feat[vt] - P_feat[path[vt]]), axis=0)
    med = np.median(r)
    mad = np.median(np.abs(r - med)) * 1.4826 + 1e-6
    bad = (r > med + 5 * mad) & (r > 0.25)
    yy, xx = np.nonzero(mask)
    newmask = mask.copy()
    newmask[yy[bad], xx[bad]] = False
    # small dilation (text outline)
    m2 = newmask.copy()
    m2[1:, :] &= newmask[:-1, :]
    m2[:-1, :] &= newmask[1:, :]
    m2[:, 1:] &= newmask[:, :-1]
    m2[:, :-1] &= newmask[:, 1:]
    frac = 1.0 - m2.sum() / float(mask.sum())
    if frac > 0.5:
        return mask, 0.0
    return m2, frac


# Slow (interpolated) detection
def fit_tone_lut(Ex, Py, nbins=64):
    """ estimate a monotonic EDIT->PLATE tone curve from matched pairs (Ex, Py: same shape)
    """
    x = Ex.ravel()
    y = Py.ravel()
    if len(x) > 400000:
        sel = np.random.default_rng(0).choice(len(x), 400000, replace=False)
        x, y = x[sel], y[sel]
    edges = np.unique(np.quantile(x, np.linspace(0, 1, nbins + 1)))
    if len(edges) < 3:
        return lambda a: a
    b = np.clip(np.searchsorted(edges, x, 'right') - 1, 0, len(edges) - 2)
    cx, cy = [], []
    for i in range(len(edges) - 1):
        mm = b == i
        if mm.sum() > 10:
            cx.append(np.median(x[mm]))
            cy.append(np.median(y[mm]))
    if len(cx) < 2:
        return lambda a: a
    cx = np.array(cx)
    cy = np.maximum.accumulate(np.array(cy))
    return lambda a: np.interp(a, cx, cy).astype(np.float32)


def _z(X):
    X = X - X.mean(axis=-1, keepdims=True)
    return X / (X.std(axis=-1, keepdims=True) + 1e-6)


def slow_evidence_mask(candidates, verified, max_gap=6):
    """Require blend evidence across a slow stretch, retaining its integer endpoints."""
    out = np.zeros(len(candidates), bool)
    idx = np.flatnonzero(candidates)
    if not len(idx):
        return out
    for group in np.split(idx, np.flatnonzero(np.diff(idx) > max_gap) + 1):
        if np.count_nonzero(np.asarray(verified)[group]) >= max(1, int(np.ceil(.2 * len(group)))):
            out[group] = True
    return out


def detect_slow(E_disp, plate_disp, path, E_valid, P):
    """
    plate_disp(t, plist) callback - shared by static / animated warps
    E_disp (E,N) tone-curve-corrected EDIT, plate_disp(t, [p..]) -> (k,N) warped PLATE
    Key to the decision: when the same plate frame repeats (hold) on the integer path
      - plain frame repetition -> two consecutive EDIT frames are effectively identical
      - interpolation (blend/flow) -> two consecutive EDIT frames differ from each other
    """
    E = len(path)
    zE = _z(E_disp)
    frac = path.astype(np.float64).copy()
    interp = np.zeros(E, bool)

    loc = np.zeros(E)
    for t in np.where(E_valid)[0]:
        p = int(path[t])
        pl = [q for q in (p - 1, p, p + 1) if 0 <= q < P]
        if len(pl) < 2:
            continue
        zp = _z(plate_disp(t, pl))
        loc[t] = np.mean((zp[1:] - zp[:-1]) ** 2, axis=1).max()
    mv = loc[E_valid & (loc > 0)]
    med_pp = np.median(mv) if len(mv) else 0.0

    for t in range(E - 1):
        if not (E_valid[t] and E_valid[t + 1]) or path[t] != path[t + 1]:
            continue
        if loc[t] < 0.15 * med_pp or loc[t] <= 0:
            continue  # still content: hold/slow distinction is meaningless
        d_ee = np.mean((zE[t + 1] - zE[t]) ** 2)
        if d_ee > 0.06 * loc[t]:
            interp[t] = interp[t + 1] = True

    alphas = np.linspace(0, 1, 21)
    candidates = interp.copy()
    verified = np.zeros(E, bool)
    for t in np.where(interp)[0]:
        p = int(path[t])
        pl = [q for q in (p - 1, p, p + 1) if 0 <= q < P]
        X = plate_disp(t, pl)
        ip = pl.index(p)
        integer_cost = float(np.mean((_z(X[ip]) - zE[t]) ** 2))
        best = (integer_cost, float(p))
        for ia, ib in ((ip, ip + 1), (ip - 1, ip)):
            if ia < 0 or ib >= len(pl):
                continue
            B = (1 - alphas[:, None]) * X[ia][None] + alphas[:, None] * X[ib][None]
            c = np.mean((_z(B) - zE[t][None]) ** 2, axis=1)
            k = int(np.argmin(c))
            if c[k] < best[0]:
                best = (c[k], pl[ia] + alphas[k])
        gain = (integer_cost - float(best[0])) / max(integer_cost, 1e-9)
        verified[t] = gain >= SLOW_BLEND_GAIN and abs(best[1] - round(best[1])) >= .05
        frac[t] = best[1]
    interp = slow_evidence_mask(candidates, verified)
    frac[~interp] = np.asarray(path)[~interp]
    return frac, interp


def slow_segments(frac, interp, E_valid, path, max_gap=6):
    """ interpolated hold groups -> [(t0, t1, v0, v1), ...] linear stretch segments
    refit after extending boundaries + pin integer boundaries, re-filter still / normal-speed segments
    """
    E = len(frac)
    idx = np.where(interp)[0]
    if len(idx) < 3:
        return []
    groups = []
    g = [idx[0]]
    for i in idx[1:]:
        if i - g[-1] <= max_gap:
            g.append(i)
        else:
            groups.append(g)
            g = [i]
    groups.append(g)

    segs = []

    def fit(t0, t1, depth=0):
        ts = np.arange(t0, t1 + 1)
        ok = E_valid[ts]
        if ok.sum() < 3:
            return
        A = np.vstack([ts[ok], np.ones(ok.sum())]).T
        sl, ic = np.linalg.lstsq(A, frac[ts[ok]], rcond=None)[0]
        res = np.abs(frac[ts[ok]] - (sl * ts[ok] + ic))
        if res.max() > 0.6 and (t1 - t0) >= 8 and depth < 6:
            k = int(ts[ok][int(np.argmax(res))])
            k = min(max(k, t0 + 4), t1 - 4)
            fit(t0, k, depth + 1)
            fit(k, t1, depth + 1)
            return
        if 0.02 < abs(sl) < 0.97:
            segs.append((int(t0), int(t1), float(sl * t0 + ic), float(sl * t1 + ic)))

    for g in groups:
        if len(g) < 3:
            continue
        fit(g[0], g[-1])

    # absorb the integer frames at segment boundaries (extend up to 2 frames if on the line) and refit
    ext = []
    for t0, t1, v0, v1 in sorted(segs):
        sl = (v1 - v0) / float(max(t1 - t0, 1))
        line = lambda t: v0 + sl * (t - t0)
        a, b = t0, t1
        for _ in range(2):
            if a - 1 >= 0 and E_valid[a - 1] and abs(frac[a - 1] - line(a - 1)) < 0.2 \
                    and not any(s0 <= a - 1 <= s1 for s0, s1, _, _ in ext):
                a -= 1
        for _ in range(2):
            if b + 1 < E and E_valid[b + 1] and abs(frac[b + 1] - line(b + 1)) < 0.2:
                b += 1
        ts = np.arange(a, b + 1)
        ok = E_valid[ts]
        sl2, ic2 = np.linalg.lstsq(np.vstack([ts[ok], np.ones(ok.sum())]).T,
                                   frac[ts[ok]], rcond=None)[0]
        va, vb = sl2 * a + ic2, sl2 * b + ic2
        if not interp[a]:
            va = float(frac[a])  # integer boundary frames stay fixed
        if not interp[b]:
            vb = float(frac[b])
        ext.append((a, b, va, vb))
    segs = ext

    out = []
    for t0, t1, v0, v1 in segs:
        sp = abs(v1 - v0) / float(max(t1 - t0, 1))
        if not (0.02 < sp < 0.97):
            continue
        if abs(v0 - round(v0)) < 0.25:
            v0 = float(round(v0))
        if abs(v1 - round(v1)) < 0.25:
            v1 = float(round(v1))
        out.append((t0, t1, round(v0, 3), round(v1, 3)))
    # if boundary extension (up to 2 frames) makes neighboring segments overlap, TimeWarp keys drop out: the start / end key inside the overlap is treated as 'inner'
    # and skipped, so one straight line runs from the start of the earlier segment to the end of the later one (lookup -2.6 f with interpolated-ramp TC first).
    # If they overlap, cut the earlier segment at the later segment's start frame, and the boundary key value is that of the longer segment's line (the short segment's end value can be
    # 0.5 f off because of integer snapping - test04_mci_0p5x 87.0 vs 87.53)
    out.sort()
    for i in range(len(out) - 1):
        t0, t1, v0, v1 = out[i]
        n0, n1, w0, w1 = out[i + 1]
        if t0 < n0 < t1:
            if (t1 - t0) >= (n1 - n0):
                b = round(v0 + (v1 - v0) * (n0 - t0) / float(t1 - t0), 3)
            else:
                b = w0
            out[i] = (t0, n0, v0, b)
            out[i + 1] = (n0, n1, b, w1)
    return [s for s in out if s[1] > s[0]]


def time_normalize(U, path, E_valid, P_valid):
    """ re-solve a slow + zoom (time-movement ambiguity) path as a monotonic path inside a band of robust line +/-TN_BAND -> (new path, info) or (None, reason)
    Line = Theil-Sen + Tukey biweight IRLS (the scattered end of the path gets weight 0). Inside the band, 0~2 progress per frame, a small penalty for progress away from the line slope"""
    E, P = U.shape
    vt = np.where(E_valid)[0]
    if len(vt) < 20:
        return None, 'few'
    tt = vt.astype(np.float64)
    yy = np.asarray(path, np.float64)[vt]
    st = max(1, len(tt) // 150)  # Theil-Sen slope (limited number of pairs) -> Tukey biweight IRLS
    ts_, ys_ = tt[::st], yy[::st]
    dt = ts_[None, :] - ts_[:, None]
    iu = np.triu_indices(len(ts_), 1)
    sl = float(np.median((ys_[None, :] - ys_[:, None])[iu] / dt[iu]))
    ic = float(np.median(yy - sl * tt))
    A = np.vstack([tt, np.ones(len(tt))]).T
    for _ in range(12):
        r = yy - (sl * tt + ic)
        sc = 1.4826 * float(np.median(np.abs(r))) + 0.5
        u = r / (4.685 * sc)
        w = np.where(np.abs(u) < 1, (1 - u ** 2) ** 2, 0.0)
        if w.sum() < 10:
            break
        sl, ic = np.linalg.lstsq(A * w[:, None], yy * w, rcond=None)[0]
    if not (0.05 < sl < TN_SLOPE):
        return None, 'slope %.2f' % sl
    line = sl * np.arange(E) + ic
    K = 2 * TN_BAND + 1
    base = np.round(line).astype(int) - TN_BAND
    Uf = np.where(np.isfinite(U), U, np.nan)
    med = float(np.nanmedian(Uf[vt, np.clip(np.asarray(path)[vt], 0, P - 1)]))
    big = 10.0 * max(med, 1e-3)
    C = np.full((E, K), big)
    for t in range(E):
        q = base[t] + np.arange(K)
        okq = (q >= 0) & (q < P)
        if not E_valid[t]:
            C[t, okq] = 0.0
            continue
        c = np.full(K, big)
        c[okq] = np.where(np.isfinite(U[t, q[okq]]) & P_valid[q[okq]], U[t, q[okq]], big)
        C[t] = c
    lam = TN_LAM * med
    D = C[0].copy()
    back = np.zeros((E, K), int)
    for t in range(1, E):
        nd = np.full(K, np.inf)
        for k in range(K):
            q = base[t] + k
            for j in range(K):
                st = q - (base[t - 1] + j)
                if 0 <= st <= 2:
                    v = D[j] + lam * abs(st - sl)
                    if v < nd[k]:
                        nd[k], back[t, k] = v, j
        D = nd + C[t]
    k = int(np.argmin(D))
    out = np.zeros(E, int)
    for t in range(E - 1, -1, -1):
        out[t] = base[t] + k
        k = back[t, k]
    out = np.clip(out, 0, P - 1)
    new_med = float(np.nanmedian(Uf[vt, out[vt]]))
    info = dict(slope=float(sl), cost=new_med / max(med, 1e-9), changed=int((out != np.asarray(path)).sum()))
    if new_med > TN_COST * med:
        return None, info
    return out, info


def subframe_estimates(E_disp, plate_disp, path, E_valid, P, frac, interp):
    """ for every valid frame: fit the blend weight of the two neighboring plates + the vertex of the cost parabola
    Returns (est, gain, vtx) - est = best blend position (interpolated hold pairs keep the detect_slow value), gain = cost reduction ratio versus the integer frame,
    vtx = parabola vertex position through the three costs at integer path p-1, p, p+1 (to confirm the blend side)"""
    E = len(path)
    zE = _z(E_disp)
    est = np.asarray(frac, np.float64).copy()
    gain = np.zeros(E)
    vtx = np.asarray(path, np.float64).copy()
    alphas = np.linspace(0, 1, 21)
    for t in np.where(E_valid)[0]:
        p = int(path[t])
        pl = [q for q in (p - 1, p, p + 1) if 0 <= q < P]
        if len(pl) < 2:
            continue
        X = plate_disp(t, pl)
        ip = pl.index(p)
        zX = _z(X)
        c = np.mean((zX - zE[t][None]) ** 2, axis=1)
        c0 = float(c[ip])
        if len(pl) == 3:
            den = c[0] - 2 * c[1] + c[2]
            if den > 1e-9:
                vtx[t] = p + float(np.clip(0.5 * (c[0] - c[2]) / den, -0.5, 0.5))
        best = (c0, float(p))
        for ia, ib in ((ip, ip + 1), (ip - 1, ip)):
            if ia < 0 or ib >= len(pl):
                continue
            B = (1 - alphas[:, None]) * X[ia][None] + alphas[:, None] * X[ib][None]
            cb = np.mean((_z(B) - zE[t][None]) ** 2, axis=1)
            k = int(np.argmin(cb))
            if cb[k] < best[0]:
                best = (float(cb[k]), pl[ia] + alphas[k])
        gain[t] = (c0 - best[0]) / max(c0, 1e-6)
        if not interp[t]:
            est[t] = best[1]
    return est, gain, vtx


def _local_linear(ts, ys, ws, h):
    """ local linear regression (tricube weights) - the value at each ts"""
    out = np.empty(len(ts))
    for i, t in enumerate(ts):
        d = np.abs(ts - t) / float(h + 1)
        k = np.clip(1 - d ** 3, 0, None) ** 3 * ws
        sw = k.sum()
        if sw <= 0:
            out[i] = ys[i]
            continue
        mt = (k * ts).sum() / sw
        my = (k * ys).sum() / sw
        vt = (k * (ts - mt) ** 2).sum()
        b = (k * (ts - mt) * (ys - my)).sum() / vt if vt > 1e-9 else 0.0
        out[i] = my + b * (t - mt)
    return out


def _isotonic(y, w):
    """ weighted monotonic increasing regression (PAV)"""
    v, ww, n = [], [], []
    for yi, wi in zip(y, w):
        v.append(float(yi)); ww.append(float(wi)); n.append(1)
        while len(v) > 1 and v[-2] > v[-1]:
            w2 = ww[-2] + ww[-1]
            m = (v[-2] * ww[-2] + v[-1] * ww[-1]) / max(w2, 1e-9)
            c = n[-2] + n[-1]
            v[-2:], ww[-2:], n[-2:] = [m], [w2], [c]
    out = []
    for vi, ci in zip(v, n):
        out += [vi] * ci
    return np.array(out)


def subframe_blend_votes(path, est, gain, vtx):
    """Per-picture blend evidence, before the minimum segment length filter."""
    pth = np.asarray(path, np.float64)
    off = np.asarray(est) - pth
    side_ok = (np.abs(vtx - pth) < 0.05) | (np.sign(vtx - pth) == np.sign(off))
    return (gain >= SUB_GAIN) & (np.abs(off - np.round(off)) >= SUB_FRAC) & side_ok


def subframe_lookup(path, E_valid, est, gain, vtx, interp, slow, max_gap=6, block=None, plate_count=None):
    """ sub-frame lookup: fractional values only for segments with interpolation evidence, the rest keep the integer path
    Evidence = an existing interpolated hold pair (interp), or blend cost reduction >= SUB_GAIN with the weight at least SUB_FRAC away from an integer and on the same side as the parabola vertex.
    Evidence frames are grouped within max_gap and merged with existing slow segments, then a curve is fitted inside each segment with local linear regression + monotonic regression
    (ramp, 0.75x). If the line residual RMS is at or below SUB_LINE_RES, use a straight line. The curve is clipped to within +/-1 of the integer path.
    block (E,) bool = still-segment frames: blend cost evidence (gain) is used only when it agrees with the parabola vertex, |vertex - blend position| <= NH_SUB_VTX
    (the blend estimate of a still plate is noise and disagrees with the vertex). For still frames without evidence, as in  only the integer path or the existing slow segment's
    straight stretch is output (curve-fitted values are not used).
    If plate_count is given, the final values are limited to the actual plate range (different from the min/max of the observed path).
    Returns (lookup, spans)"""
    E = len(path)
    pth = np.asarray(path, np.float64)
    look = pth.copy()
    off = est - pth
    blend_ok = subframe_blend_votes(pth, est, gain, vtx)
    if block is not None:  # still segment: evidence only when the cost parabola vertex points the same way as the blend position (noise does not agree)
        blend_ok &= ~(np.asarray(block, bool) & (np.abs(vtx - est) > NH_SUB_VTX))
    supported = (gain >= SLOW_BLEND_GAIN) & (np.abs(off) <= 1.0)
    interp = slow_evidence_mask(np.asarray(interp, bool) & (np.abs(off) <= 1.0), supported, max_gap)
    ev = E_valid & (interp | blend_ok)
    marks = np.zeros(E, bool)
    marks[ev] = True
    for t0, t1, _, _ in slow:
        marks[int(t0):int(t1) + 1] |= ev[int(t0):int(t1) + 1] | interp[int(t0):int(t1) + 1]
    idx = np.where(marks)[0]
    groups = []
    if len(idx) >= SUB_MIN:
        g = [idx[0]]
        for i in idx[1:]:
            if i - g[-1] <= max_gap:
                g.append(i)
            else:
                groups.append(g)
                g = [i]
        groups.append(g)
    spans = []
    for g in groups:
        a, b = int(g[0]), int(g[-1])
        for s0, s1, _, _ in slow:  # if it overlaps an existing slow segment, extend to that segment
            if s0 <= b and s1 >= a:
                a, b = min(a, int(s0)), max(b, int(s1))
        nev = int((ev[a:b + 1] | interp[a:b + 1]).sum())
        if nev < SUB_MIN:
            continue
        a2, b2 = max(0, a - 2), min(E - 1, b + 2)
        ts = np.arange(a2, b2 + 1)
        ok = E_valid[ts]
        if ok.sum() < 4:
            continue
        tsv = ts[ok].astype(np.float64)
        ys = np.where(ev[ts[ok]] | interp[ts[ok]], est[ts[ok]], pth[ts[ok]])
        ws = np.where(ev[ts[ok]] | interp[ts[ok]], 1.0, 0.5)
        A = np.vstack([tsv, np.ones(len(tsv))]).T
        sl, ic = np.linalg.lstsq(A * ws[:, None], ys * ws, rcond=None)[0]
        if not (0.02 < sl < 0.97):
            continue
        res = ys - (sl * tsv + ic)
        if np.sqrt(np.average(res ** 2, weights=ws)) <= SUB_LINE_RES:
            fit = sl * tsv + ic
        else:
            fit = _isotonic(_local_linear(tsv, ys, ws, SUB_H), ws)
        fit = np.clip(fit, pth[ts[ok]] - 1.0, pth[ts[ok]] + 1.0)
        sn = np.abs(fit - np.round(fit)) < 0.03
        fit[sn] = np.round(fit[sn])
        # The 2 frames at each end extended beyond the segment stay integer unless they are evidence frames (boundary keys fixed)
        for i, t in enumerate(ts[ok]):
            if a <= t <= b or ev[t] or interp[t]:
                look[t] = round(float(fit[i]), 3)
        spans.append((a, b))
    if block is not None:  # inside a still segment the values are those of : integer path + straight stretch of existing slow segments
        bl = np.asarray(block, bool) & ~ev & ~interp
        look[bl] = pth[bl]
        for t0, t1, v0, v1 in slow:
            for t in range(int(t0), int(t1) + 1):
                if bl[t]:
                    look[t] = round(float(v0 + (v1 - v0) * (t - t0) / float(max(t1 - t0, 1))), 3)
    # Fitted curves take priority, then the first fallback stretch.
    # A shared endpoint must not suppress an otherwise uncovered slow segment.
    covered = np.zeros(E, bool)
    for a, b in spans:
        covered[a:b + 1] = True
    for t0, t1, v0, v1 in slow:  # existing slow segments not covered by a curve segment keep the straight stretch as before
        t0, t1 = int(t0), int(t1)
        if covered[t0:t1 + 1].all():
            continue
        run_start = None
        for t in range(t0, t1 + 1):
            if not covered[t]:
                if run_start is None:
                    run_start = t
                look[t] = round(float(v0 + (v1 - v0) * (t - t0) / float(max(t1 - t0, 1))), 3)
                covered[t] = True
            elif run_start is not None:
                spans.append((run_start, t - 1))
                run_start = None
        if run_start is not None:
            spans.append((run_start, t1))
    if plate_count is not None:  # Never extrapolate outside the actual plate.
        look = np.clip(look, 0.0, float(max(0, int(plate_count) - 1)))
    return look, sorted(spans)


# Shared cost / connected components / EXR writing
def _cell_cost(Pf, ef, mask_cells):
    """ Pf (K,N), ef (N,) -> (K,) cell-trimmed L1
    """
    order, starts, counts, keep = mask_cells
    d = np.abs(Pf[:, order] - ef[order][None])
    cm = np.add.reduceat(d, starts, axis=1) / counts[None]
    cm = cm[:, keep]
    kc = cm.shape[1]
    ntrim = max(1, int(round(kc * (1.0 - TRIM))))
    if ntrim < kc:
        cm = np.partition(cm, ntrim - 1, axis=1)[:, :ntrim]
    return cm.mean(axis=1)


def _label(mask):
    """ 4-neighbor connected components -> (labels, sizes)
    """
    H, W = mask.shape
    lab = np.zeros((H, W), np.int32)
    sizes = [0]
    cur = 0
    ys, xs = np.nonzero(mask)
    for y0, x0 in zip(ys, xs):
        if lab[y0, x0]:
            continue
        cur += 1
        lab[y0, x0] = cur
        stack = [(y0, x0)]
        n = 0
        while stack:
            y, x = stack.pop()
            n += 1
            for yy, xx in ((y - 1, x), (y + 1, x), (y, x - 1), (y, x + 1)):
                if 0 <= yy < H and 0 <= xx < W and mask[yy, xx] and not lab[yy, xx]:
                    lab[yy, xx] = cur
                    stack.append((yy, xx))
        sizes.append(n)
    return lab, np.array(sizes)


def _dilate(m, r=1):
    out = m.copy()
    for _ in range(r):
        o = out.copy()
        o[1:] |= out[:-1]
        o[:-1] |= out[1:]
        o[:, 1:] |= out[:, :-1]
        o[:, :-1] |= out[:, 1:]
        out = o
    return out


def _erode(m, r=1):
    return ~_dilate(~m, r)


def _otsu(v, bins=64):
    """"""
    hist, edges = np.histogram(v, bins)
    c = 0.5 * (edges[1:] + edges[:-1])
    w0 = np.cumsum(hist).astype(np.float64)
    w1 = w0[-1] - w0
    s0 = np.cumsum(hist * c)
    mu0 = s0 / np.maximum(w0, 1)
    mu1 = (s0[-1] - s0) / np.maximum(w1, 1)
    var = w0 * w1 * (mu0 - mu1) ** 2
    return float(edges[int(np.argmax(var[:-1])) + 1])


def write_exr_alpha(path, arr):
    """ single-channel (A) float32 uncompressed scanline EXR
    """
    arr = np.ascontiguousarray(arr, dtype='<f4')
    H, W = arr.shape

    def attr(name, typ, data):
        return name.encode() + b'\0' + typ.encode() + b'\0' + struct.pack('<i', len(data)) + data
    hdr = struct.pack('<ii', 20000630, 2)
    hdr += attr('channels', 'chlist', b'A\0' + struct.pack('<iBBBBii', 2, 0, 0, 0, 0, 1, 1) + b'\0')
    hdr += attr('compression', 'compression', b'\0')
    hdr += attr('dataWindow', 'box2i', struct.pack('<4i', 0, 0, W - 1, H - 1))
    hdr += attr('displayWindow', 'box2i', struct.pack('<4i', 0, 0, W - 1, H - 1))
    hdr += attr('lineOrder', 'lineOrder', b'\0')
    hdr += attr('pixelAspectRatio', 'float', struct.pack('<f', 1.0))
    hdr += attr('screenWindowCenter', 'v2f', struct.pack('<ff', 0.0, 0.0))
    hdr += attr('screenWindowWidth', 'float', struct.pack('<f', 1.0))
    hdr += b'\0'
    line = 8 + W * 4
    start = len(hdr) + 8 * H
    offs = struct.pack('<%dQ' % H, *[start + i * line for i in range(H)])
    body = b''.join(struct.pack('<ii', y, W * 4) + arr[y].tobytes() for y in range(H))
    with open(path, 'wb') as f:
        f.write(hdr + offs + body)


# Split composite / temp composite detection
def detect_split_region(Ef, Pf, path, E_valid, m):
    """
    Pixel residual map after matching -> if there is a large area this plate cannot explain, judge it a split.
    Returns: region (bool HxW), info dict
    """
    vt = np.where(E_valid)[0]
    info = dict(split=False, frac=1.0, where='')
    if len(vt) < 3:
        return m.copy(), info
    rp = np.median(np.abs(Ef[vt] - Pf[path[vt]]), axis=0)
    R = np.zeros(m.shape, np.float32)
    R[m] = rp
    Wm = m.astype(np.float32)
    Rs, Ws_ = R * Wm, Wm.copy()
    for _ in range(3):
        Rs, Ws_ = blur121(Rs), blur121(Ws_)
    Rs = Rs / np.maximum(Ws_, 1e-3)
    vals = Rs[m]
    thr = _otsu(vals)
    bad = (Rs > thr) & m
    good = m & ~bad
    if good.sum() < 0.15 * m.sum() or bad.sum() == 0:
        return m.copy(), info
    mg = float(np.mean(R[good]))
    mb = float(np.mean(R[bad]))
    lab, sizes = _label(bad)
    big = sizes[1:].max() / float(m.sum()) if len(sizes) > 1 else 0.0
    info.update(ratio=mb / (mg + 1e-6), big=big)
    if big > 0.15 and mb > 2.5 * mg:
        keep_bad = np.isin(lab, np.where(sizes > 0.02 * m.sum())[0]) & (lab > 0)
        g_ref = float(np.percentile(vals, 8))  # noise floor of the correct area
        thr_r = g_ref + 0.5 * (thr - g_ref)  # boundary/ambiguous areas are excluded conservatively
        region = m & (Rs <= thr_r) & ~_dilate(keep_bad, 1)
        # After removing thin connections by opening (erode 2 -> dilate 2), keep only the blobs with low residual
        region = _dilate(_erode(region, 2), 2) & m
        lab2, s2 = _label(region)
        comps = [i for i in range(1, len(s2)) if s2[i] > 0.03 * m.sum()]
        if comps:
            cm = dict((i, float(R[lab2 == i].mean())) for i in comps)
            b0 = min(cm.values())
            lim = b0 + 0.35 * (mb - b0)
            region = np.isin(lab2, [i for i in comps if cm[i] <= lim])
        else:
            region = np.zeros_like(m)
        if region.sum() < 0.05 * m.sum():
            return m.copy(), info
        info.update(split=True, frac=region.sum() / float(m.sum()), where=_where(region))
        return region, info
    return m.copy(), info


def _where(region):
    """"""
    H, W = region.shape
    ys, xs = np.nonzero(region)
    if not len(xs):
        return '-'
    cx, cy = xs.mean() / W, ys.mean() / H
    h = '좌측' if cx < 0.4 else ('우측' if cx > 0.6 else '')
    v = '상단' if cy < 0.4 else ('하단' if cy > 0.6 else '')
    return (v + ' ' + h).strip() or '중앙'


# Optical animation tracking (scale/reposition keys)
def _robust_poly(x, y, xe, deg=3, floor=0.002, iters=12):
    """ Tukey-weighted polynomial fit (key frames x -> values y), evaluated at xe. The degree is lowered when there are few keys"""
    x = np.asarray(x, np.float64)
    y = np.asarray(y, np.float64)
    deg = int(min(deg, max(0, len(x) // 3 - 1)))
    c, sc_ = x.mean(), max(np.ptp(x) / 2.0, 1.0)
    X = np.vander((x - c) / sc_, deg + 1)
    w = np.ones(len(x))
    coef = np.zeros(deg + 1)
    for _ in range(iters):
        sw = np.sqrt(w)
        coef = np.linalg.lstsq(X * sw[:, None], y * sw, rcond=None)[0]
        r = y - X.dot(coef)
        sig = max(1.4826 * float(np.median(np.abs(r))), floor)
        u = r / (4.685 * sig)
        w = np.where(np.abs(u) < 1, (1 - u * u) ** 2, 0.0)
        if w.sum() < deg + 2:
            w = np.ones(len(x))
            break
    return np.vander((np.asarray(xe, np.float64) - c) / sc_, deg + 1).dot(coef)


def _key_search(E_s, M_s, keys, P_s, P_valid, path, fl, win=None):
    """ independent optical search per key frame (variable-scale initial values)
    Full scale range (32px grid) x plates around the path (+/-win) x FFT shift -> fine scale at 64px.
    If only local refinement continues from the previous key, in segments where the first-pass path is wrong the shift (tx/ty) absorbs the time error
    (e.g. in a scene where two layers move in different directions, time -11 frames = tx -0.08). Plate candidates are searched together to cut this off.
    E_s (E,He/2,We/2), P_s (P,Hp/2,Wp/2) blur121 -> {t: [(ncc, [s,tx,ty], plate)]} (ncc descending)
    """
    win = TRACK_WIN if win is None else win
    P = P_s.shape[0]
    E_a = down2(E_s)
    m_a = down2(M_s.astype(np.float32)) > 0.99
    if m_a.sum() < 20 or not keys:
        return {}
    lo = max(0, int(min(path[t] for t in keys)) - win)
    hi = min(P - 1, int(max(path[t] for t in keys)) + win)
    cidx = np.arange(lo, hi + 1)
    cidx = cidx[P_valid[cidx]]
    if not len(cidx):
        return {}
    Hs, Ws = P_s.shape[-2:]
    P_s_r = rank_rows(P_s[cidx].reshape(len(cidx), -1)).reshape(len(cidx), Hs, Ws)
    P_a = blur121(down2(P_s[cidx]))
    P_a_r = rank_rows(P_a.reshape(len(cidx), -1)).reshape(P_a.shape)
    scales_a = np.exp(np.linspace(np.log(SCALE_MIN), np.log(SCALE_MAX), 17))
    step_a = np.log(scales_a[1] / scales_a[0])
    Ts = [(t, _template(E_a[t], m_a), 'm') for t in keys]
    allow = dict((t, np.abs(cidx - path[t]) <= win) for t in keys)
    top = _search_level(Ts, {'m': m_a}, P_a_r, scales_a, [fl], topk=2, allow=allow)
    out = {}
    for v, t, ci, s0, _, _, _ in top:
        cis = list(range(max(0, ci - 1), min(len(cidx), ci + 2)))
        sc_b = s0 * np.exp(np.linspace(-1.5, 1.5, 9) * step_a)
        r = _search_level([(t, _template(E_s[t], M_s), 'm')], {'m': M_s}, P_s_r[cis], sc_b, [fl], topk=1)
        for v2, _, cj, s2, _, tx, ty in r:
            out.setdefault(t, []).append((float(v2), np.array([s2, tx, ty], np.float64), int(cidx[cis[cj]])))
    for t in out:
        out[t].sort(key=lambda r: -r[0])
    return out


def track_accept_dev(sa, sb, s_hold, s0):
    """ secondary animation acceptance decision (pure function). The  guard looks at the gain / gained fraction over all verification frames, so it
    solved as static: ease after a hold (partial zoom: the hold part equals the static solution so gain is 0), small changes (1.0 -> 1.08), and zooms starting outside the frame
    (8 variable-zoom clips, ). Here only verification frames whose animated scale differs from the static solution by TRACK_DEV or more are examined:
      * such frames are at least TRACK_DEV_SHARE of the verification frames (noise keys of static edits are only a few)
      * the mean NCC gain of those frames > TRACK_DEV_GAIN, and the gained fraction >= TRACK_WIN_FRAC
      * the animation NCC of those frames is not lower than the remaining (static-equal) frames by TRACK_DEV_GAP or more - a real zoom matches evenly
        across the whole frame, while a stretch with a wrong path (after a hard cut / another source) fitted 'less badly' by scale is still low (0.27~0.63 difference)
    sa / sb: animated / static NCC of the verification frames, s_hold: animated scale of those frames, s0: static scale"""
    sa, sb, sh = np.asarray(sa, float), np.asarray(sb, float), np.asarray(s_hold, float)
    n_all = len(sh)
    out = dict(ok=False, n=0, n_all=n_all, gain=0.0, win=0.0, gap=0.0)
    if n_all < 6 or len(sa) != n_all or len(sb) != n_all or s0 <= 0:
        return out
    d = np.abs(sh - s0) / s0 > TRACK_DEV
    out['n'] = int(d.sum())
    if out['n'] < max(6, TRACK_DEV_SHARE * n_all):
        return out
    g = sa[d] - sb[d]
    out['gain'] = float(g.mean())
    out['win'] = float(np.mean(g > TRACK_EPS))
    rest = sa[~d] if (~d).sum() >= 3 else sa
    out['gap'] = float(np.median(rest) - sa[d].mean())
    out['ok'] = out['gain'] > TRACK_DEV_GAIN and out['win'] >= TRACK_WIN_FRAC and out['gap'] <= TRACK_DEV_GAP
    return out


def track_trial_ok(t1):
    """ is a trial acceptance of the track worth attempting (pure function): the guard was not passed but the scale moves a lot and the gain is positive on
    at least half of the verification frames. Noise keys of static edits (scale range < 0.012~0.03) are filtered out here and cost no extra time"""
    return (t1.get('curve') is not None and float(t1.get('s_rng') or 0.0) >= TRACK_TRIAL_SRNG
            and float(t1.get('gain') or 0.0) > TRACK_TRIAL_GAIN and float(t1.get('win') or 0.0) >= TRACK_TRIAL_WIN)


def track_trial_accept(ta, c_static, c_anim):
    """ trial acceptance decision (pure function): the re-track passes the normal guard and the path cost is at most TRACK_TRIAL_COST times,
    or the re-track misses the guard (mid-zoom resembles the static solution, gained fraction 58 %) but moves a lot, gain > TRACK_GAIN, and
    the path cost is at most TRACK_TRIAL_STRONG times (0.9 -> 1.6 ramp: 0.143 -> 0.077)"""
    if not np.isfinite(c_anim) or not np.isfinite(c_static) or c_static <= 0:
        return False
    r = c_anim / c_static
    if ta.get('animated'):
        return r < TRACK_TRIAL_COST
    # Accepting below the guard only when it is not noise fitting after a cut: reject if the NCC of the frames that differ from static is lower than the rest by more than TRACK_DEV_GAP
    # (test03_cut_hard_back: cost 0.465 -> 0.323, gap 0.25 / test01_zoom_ramp_0p9_1p6: gap 0.033)
    dev = ta.get('dev') or {}
    return (ta.get('curve') is not None and float(ta.get('s_rng') or 0.0) >= TRACK_TRIAL_SRNG
            and float(ta.get('gain') or 0.0) > TRACK_GAIN and r < TRACK_TRIAL_STRONG
            and float(dev.get('gap', 1.0)) <= TRACK_DEV_GAP)


def optical_same(a, b, ds=0.01, dt=0.005):
    """ whether two static optical solutions are the same (pure function): same flop and relative scale difference < ds, shift difference < dt (width units)"""
    try:
        return (bool(a['flop']) == bool(b['flop']) and abs(float(a['s']) - float(b['s'])) < ds * float(b['s'])
                and abs(float(a['tx']) - float(b['tx'])) < dt and abs(float(a['ty']) - float(b['ty'])) < dt)
    except (KeyError, TypeError, ValueError):
        return False


def _path_cost_median(U, path, E_valid):
    """ median cost along the path (finite cells only)"""
    E = U.shape[0]
    c = U[np.arange(E), np.asarray(path, int)]
    c = c[np.asarray(E_valid, bool) & np.isfinite(c)]
    return float(np.median(c)) if len(c) else np.inf


def static_refine_evidence(before, after, animated):
    """Offer a static hypothesis from consistent non-key image gains.

    This does not accept an animated track or replace a result. The complete
    static re-solve must still pass the separate image/curve acceptance gate.
    """
    before, after = np.asarray(before, float), np.asarray(after, float)
    if animated or before.ndim != 1 or before.shape != after.shape or len(before) < 8:
        return False
    if not np.isfinite([before, after]).all():
        return False
    gain = after - before
    return bool(gain.mean() > .004 and np.mean(gain > TRACK_EPS) >= .8)


def track_optical(E_lum, mask, E_valid, P_lum, P_valid, path, opt, stride=4, log=print, win=None):
    """
    Locally refine (s, tx, ty) at each key frame (stride), propagate forward/backward, then smooth.
    variable scale: independent search per key (_key_search: full scale range x plates around the path) for initial values ->
            local refinement. Acceptance guard = adopt only when the animation smoothed on verification frames (not keys) is clearly better than the static solution
            (mean NCC gain > TRACK_GAIN, gained-frame fraction >= TRACK_WIN_FRAC). The gain measured at keys is a value optimized per key,
            so it is always positive even in static shots -> up to , 9 of 21 static edits were misjudged as ANIMATED
    Returns: dict(s, tx, ty arrays (E,), flop, animated, gain, plates (E,) key-search plate interpolation)
    """
    E = E_lum.shape[0]
    fl = opt['flop']
    E_s = down2(E_lum)
    M_s = down2(mask.astype(np.float32)) > 0.99
    P_s = blur121(down2(P_lum))
    Ws = E_s.shape[-1]
    P = P_lum.shape[0]
    vt = np.where(E_valid)[0]
    static = np.array([opt['s'], opt['tx'], opt['ty']], np.float64)
    out = dict(s=np.full(E, static[0]), tx=np.full(E, static[1]), ty=np.full(E, static[2]),
               flop=fl, animated=False, gain=0.0, plates=None)
    if len(vt) < 6:
        return out
    keys = list(vt[::stride])
    if keys[-1] != vt[-1]:
        keys.append(int(vt[-1]))
    keyset = set(int(t) for t in keys)

    def sc(t, prm, p):
        return _score_pairs(E_s[t:t + 1], M_s, P_s[p:p + 1], prm[0], prm[1], prm[2], fl)

    def near(c, r=1):
        c = int(round(c))
        return [q for q in range(c - r, c + r + 1) if 0 <= q < P and P_valid[q]]

    def refine(t, init, ps):
        prm = list(init)
        p = max(ps, key=lambda q: sc(t, prm, q))
        cur = sc(t, prm, p)
        steps = [0.006, 0.6 / Ws, 0.6 / Ws]
        mins = [0.0008, 0.08 / Ws, 0.08 / Ws]
        for _ in range(30):
            improved = False
            for i in range(3):
                for sgn in (1, -1):
                    tr = list(prm)
                    tr[i] += sgn * steps[i]
                    if not (SCALE_MIN * 0.9 < tr[0] < SCALE_MAX * 1.1):
                        continue
                    v = sc(t, tr, p)
                    if v > cur + 1e-6:
                        cur, prm, improved = v, tr, True
            if not improved:
                if all(steps[i] <= mins[i] for i in range(3)):
                    break
                steps = [max(steps[i] * 0.5, mins[i]) for i in range(3)]
        return np.array(prm), cur, p

    ks = _key_search(E_s, M_s, keys, P_s, P_valid, path, fl, win=win)
    res = {}
    for t in keys:
        inits = [(static, near(path[t]))]
        if ks.get(t):
            inits.insert(0, (ks[t][0][1], near(ks[t][0][2])))
        best = None
        for init, ps in inits:
            if not ps:
                continue
            prm, v, p = refine(t, init, ps)
            if best is None or v > best[1]:
                best = (prm, v, p)
        if best is None:
            best = (static, -1.0, int(path[t]))
        res[t] = best

    K = np.array(keys)
    A = np.array([res[t][0] for t in keys])
    kpl = np.array([res[t][2] for t in keys], np.float64)
    # median(3) -> interpolation -> box(5)
    Am = A.copy()
    for i in range(1, len(keys) - 1):
        Am[i] = np.median(A[i - 1:i + 2], axis=0)
    full = np.stack([np.interp(np.arange(E), K, Am[:, j]) for j in range(3)], 1)
    ker = np.ones(5) / 5.0
    pad = np.pad(full, ((2, 2), (0, 0)), mode='edge')
    full = np.stack([np.convolve(pad[:, j], ker, mode='valid') for j in range(3)], 1)
    # movement (tx/ty) as a robust cubic curve: in scenes with weak temporal information (tilts / pans where the background hardly changes)
    # a solution that shifts plate time by a few frames and compensates with movement has almost the same NCC, so per-key movement bends
    # locally along the time error (real-footage drifting zoom: ty 0.02 = 38px bend -> path +26f). Real reposition movement is smooth
    for j in (1, 2):
        full[:, j] = _robust_poly(K, A[:, j], np.arange(E))
    kp_full = np.interp(np.arange(E), K, kpl)

    s_rng = full[:, 0].max() - full[:, 0].min()
    t_rng = max(full[:, 1].max() - full[:, 1].min(), full[:, 2].max() - full[:, 2].min())
    # acceptance guard: warp smoothed on verification frames (not keys) vs static warp (plates for both are the best of path / key interpolation +/-2)
    hold = np.array([t for t in vt if int(t) not in keyset])
    if len(hold) > 24:
        hold = hold[np.linspace(0, len(hold) - 1, 24).astype(int)]
    # Two static solution candidates: stage 1 static (static) / key-search median (static_k - when stage 1 static is wrong, precision measurement fillcrop)
    static_k = np.median(A, axis=0)
    sa, ss, sk, sh = [], [], [], []
    for h in hold:
        ps = sorted(set(near(path[h], 2)) | set(near(kp_full[h], 2)))
        if not ps:
            continue
        sa.append(max(sc(h, full[h], q) for q in ps))
        ss.append(max(sc(h, static, q) for q in ps))
        sk.append(max(sc(h, static_k, q) for q in ps))
        sh.append(float(full[h, 0]))
    sa, ss, sk = (np.array(v) if v else np.zeros(1) for v in (sa, ss, sk))
    gk = sk - ss
    use_k = sk.mean() > ss.mean()
    ga = sa - (sk if use_k else ss)  # compare against the better static solution (overall mean)
    gain = float(np.mean(ga))
    win = float(np.mean(ga > TRACK_EPS))
    moving = s_rng > 0.012 or t_rng > 0.005
    animated = moving and ((gain > TRACK_GAIN and win >= TRACK_WIN_FRAC) or (gain > TRACK_GAIN_STRONG and win >= 0.6))
    dev = track_accept_dev(sa, sk if use_k else ss, sh, float((static_k if use_k else static)[0]))
    if moving and not animated and dev['ok']:
        animated = True
        log(_t('  optical track: 정적과 다른 프레임 %d/%d 에서 gain %.4f (better %.0f%%), NCC 차 %.3f -> ANIMATED', '  optical track: %d/%d frames differ from static, gain %.4f (better %.0f%%), NCC difference %.3f -> ANIMATED')
            % (dev['n'], dev['n_all'], dev['gain'], 100 * dev['win'], dev['gap']))
    if static_refine_evidence(ss, sk, animated):
        out['static_candidate'] = static_k.copy()
        out['static_candidate_used_times'] = sorted(keyset | set(map(int, hold)))
    if not animated and float(np.mean(gk)) > TRACK_GAIN and float(np.mean(gk > TRACK_EPS)) >= 0.6:
        out['static_opt'] = static_k  # not an animation, but the stage 1 static optical was wrong -> replace it and match again
        log(_t('  optical track: 1단계 정적 해보다 키 중앙값이 나음 (gain %.4f) -> s=%.4f tx=%.4f ty=%.4f', '  optical track: median keys outperform the first-stage static solution (gain %.4f) -> s=%.4f tx=%.4f ty=%.4f')
            % (float(np.mean(gk)), static_k[0], static_k[1], static_k[2]))
    log('  optical track: scale %.3f~%.3f, move %.4f, held-out gain %.4f (better %.0f%%), key-median vs static %.4f (%.0f%%) -> %s'
        % (full[:, 0].min(), full[:, 0].max(), t_rng, gain, 100 * win, float(np.mean(gk)),
           100 * float(np.mean(gk > TRACK_EPS)), 'ANIMATED' if animated else 'static'))
    out.update(gain=gain, win=win, plates=kp_full)
    out['dev'] = dev  # secondary acceptance decision values (for log / report)
    out.update(curve=full, s_rng=float(s_rng))  # smoothed curve for trial acceptance (track_trial_ok)
    if animated:
        out.update(s=full[:, 0], tx=full[:, 1], ty=full[:, 2], animated=True)
    return out


def refine_track_cost(E_lum, P_lum, trk, mask, E_valid, P_valid, path, stride=4, win=6, log=print):
    """ re-refine the animated movement (tx/ty) per key with the final matching cost (cell-trimmed L1 @W_EDIT) -> robust cubic curve.
    In some scenes 64px NCC can barely tell a 'few frames of time + few px of movement' solution from the correct one (real-footage drifting zoom:
    NCC 0.9937 vs 0.9933) - in the same scene the matching cost is distinct, +40% for a 4px offset. Per key, plates on the path +/-win x
    (tx, ty, s) pattern search. Returns a copy of trk (tx, ty replaced, refined=True)"""
    E, He, We = E_lum.shape
    P, Hp, Wp = P_lum.shape
    Pb = blur121(P_lum)
    vt = np.where(E_valid)[0]
    if len(vt) < 6:
        return trk
    keys = list(vt[::stride])
    if keys[-1] != vt[-1]:
        keys.append(int(vt[-1]))
    s_, fl = np.asarray(trk['s']), trk['flop']
    n_mask = mask.sum()
    memo = {}  # (t, mask) -> (EDIT rank, cell): the pattern search calls this hundreds of times with the same mask (same result, time -40 %)

    def cost(t, q, tx, ty, sc_):
        xp, yp = warp_coords(He, We, Hp, Wp, sc_, tx, ty, fl)
        Wimg, val = bilinear(Pb[q:q + 1], xp, yp)
        m = mask & val
        if m.sum() < 0.5 * n_mask:
            return np.inf
        key = (t, m.tobytes())
        ec = memo.get(key)
        if ec is None:
            if len(memo) > 256:  # keeps memory from growing in a zoom-out where the edge mask keeps changing
                memo.clear()
            ec = memo[key] = (rank_rows(E_lum[t][m]), _cells(m))
        return float(_cell_cost(rank_rows(Wimg[:, m]), ec[0], ec[1])[0])

    K, TX, TY, SS = [], [], [], []
    for t in keys:
        best = None
        for q in range(max(0, int(path[t]) - win), min(P - 1, int(path[t]) + win) + 1):
            if not P_valid[q]:
                continue
            prm = [float(trk['tx'][t]), float(trk['ty'][t]), float(s_[t])]
            cur = cost(t, q, prm[0], prm[1], prm[2])
            step = 2.0 / We
            while step >= 0.12 / We:
                improved = False
                for i in (0, 1, 2):
                    for sg in (1, -1):
                        tr = list(prm)
                        tr[i] += sg * step * (1.0 if i < 2 else 2.0)  # scale step = movement step x2 (width units)
                        v = cost(t, q, tr[0], tr[1], tr[2])
                        if v < cur - 1e-6:
                            cur, prm, improved = v, tr, True
                if not improved:
                    step *= 0.5
            if best is None or cur < best[0]:
                best = (cur, prm)
        if best is not None and np.isfinite(best[0]):
            K.append(t)
            TX.append(best[1][0])
            TY.append(best[1][1])
            SS.append(best[1][2])
    if len(K) < 4:
        return trk
    out = dict(trk)
    ar_ = np.arange(E)
    out['tx'] = _robust_poly(K, TX, ar_)
    out['ty'] = _robust_poly(K, TY, ar_)
    # Scale: key value median(3) -> interpolation -> box(5) (so the polynomial does not smear the hold-ease of a partial zoom)
    SSm = np.array(SS)
    for i in range(1, len(SS) - 1):
        SSm[i] = np.median(SS[i - 1:i + 2])
    sf = np.interp(ar_, K, SSm)
    out['s'] = np.convolve(np.pad(sf, 2, mode='edge'), np.ones(5) / 5.0, mode='valid')
    out['refined'] = True
    log('  track cost refine: tx %.4f~%.4f, ty %.4f~%.4f (was %.4f~%.4f, %.4f~%.4f)' % (
        out['tx'].min(), out['tx'].max(), out['ty'].min(), out['ty'].max(),
        np.min(trk['tx']), np.max(trk['tx']), np.min(trk['ty']), np.max(trk['ty'])))
    return out


def match_animated(E_lum, P_lum, trk, mask, E_valid, P_valid, path0, win=25, progress=None,
                   pins=None, hints=None, jumps=None, max_speed=16):
    """ warp with per-frame optical and compute the cost only for candidates around path0
    jumps: frames where an exclusion / pin discontinuity is allowed (dp_path)
    candidates also around the key-search plates (trk['plates']) (even if the static-warp first-pass path goes wrong in a variable-scale segment)
    """
    alt = trk.get('plates')
    E, He, We = E_lum.shape
    P, Hp, Wp = P_lum.shape
    Pb = blur121(P_lum)
    coords = []
    m = mask.copy()
    for t in range(E):
        xp, yp = warp_coords(He, We, Hp, Wp, trk['s'][t], trk['tx'][t], trk['ty'][t], trk['flop'])
        coords.append((xp, yp))
        if E_valid[t]:
            m &= (xp >= 0) & (xp <= Wp - 1) & (yp >= 0) & (yp <= Hp - 1)
    cells = _cells(m)
    Ef = rank_rows(E_lum[:, m])
    U = np.full((E, P), np.inf, np.float32)
    for t in range(E):
        if not E_valid[t]:
            U[t] = 0.0
            continue
        c0 = c1 = int(path0[t])
        if alt is not None:
            c0, c1 = min(c0, int(round(alt[t]))), max(c1, int(round(alt[t])))
        lo, hi = max(0, c0 - win), min(P - 1, c1 + win)
        idx = np.arange(lo, hi + 1)
        idx = idx[P_valid[idx]]
        if not len(idx):
            continue
        Wimg, _ = bilinear(Pb[idx], *coords[t])
        U[t, idx] = _cell_cost(rank_rows(Wimg[:, m]), Ef[t], cells)
        if progress and t % 10 == 0 and progress(t, E):
            raise RuntimeError('cancelled')
    path = dp_path(U, E_valid, P_valid, pins, hints, jumps, max_speed=SPEED_MAX, direction_policy=False)
    return U, path, m, coords


# lagging-TC burn-in recognition - nmmr_tc_ocr 1.0.0 inlined (numpy only without external OCR, single file for pasting into the Script Editor)
# tco_ / TCO_ prefixes, built-in font dictionary included.
# Flow: fixed cell split -> grayscale cell features -> font dictionary + nearest clip-trained examples + LDA -> hard digit-range constraints ->
# temporal decoding (Viterbi, no +1-per-frame assumption: hold / ramp / reverse / jump) -> confidence (max-marginal margin + constant-digit gate)
# > 2 rounds of self-calibration with the changing digits. Confident values must not be wrong (zero misreads first), the rest are None
# The glyph-template OCR of (tc_segment / tc_cluster / tc_recognize / training popup) was replaced by this engine in
def frames_to_tc(n, fps):
    """ frame count -> 'HH:MM:SS:FF' (non-drop, nominal fps)"""
    nom = int(round(float(fps))) if fps else 24
    n = int(n)
    return '%02d:%02d:%02d:%02d' % ((n // (nom * 3600)) % 24, (n // (nom * 60)) % 60, (n // nom) % 60, n % nom)


def tc_to_frames(tc, fps):
    """ 'HH:MM:SS:FF' -> frame count (non-drop basis, nominal fps)"""
    if not tc:
        return None
    parts = re.split(r'[:;.]', str(tc).strip())
    if len(parts) != 4:
        return None
    try:
        h, m, s_, f = [int(x) for x in parts]
    except ValueError:
        return None
    n = int(round(float(fps))) if fps else 24
    if m >= 60 or s_ >= 60 or f >= n:
        return None
    return ((h * 60 + m) * 60 + s_) * n + f


# nmmr_tc_ocr 1.0.0 (inline)
TCO_VERSION = '1.0.0'
TCO_CELL = (24, 16)  # feature grid (H, W) per digit cell
TCO_N_CHARS = 11  # HH:MM:SS:FF
TCO_DIGIT_SLOTS = (0, 1, 3, 4, 6, 7, 9, 10)
TCO_BETA = 45.0  # cosine -> log-likelihood temperature
TCO_JITTER = (-0.5, 0.0, 0.5)  # sub-pixel x search per cell (source pixels). Wider searches
                                   # (+-0.2 pitch) were measured to make 6/8/1/7 confusable on 720p
TCO_MAX_STEP = 10  # |step| above this is a jump (cut). 10 = 10x fast-forward


def _tco_step_pen(s):
    """soft small-step prior: holds (0), 1x, ramps, fast-forward, reverse - no +1 assumption"""
    if s == 1:
        return 0.0
    if s == 0:
        return -0.7
    if 2 <= s <= TCO_MAX_STEP:
        return -0.9 - 0.35 * (s - 2)
    if -TCO_MAX_STEP <= s <= -1:
        return -1.6 - 0.35 * (-s - 1)
    return None


TCO_STEP_PEN = dict((s, _tco_step_pen(s)) for s in range(-TCO_MAX_STEP, TCO_MAX_STEP + 1))
TCO_JUMP_PEN = -12.0  # cut / big jump (any step outside TCO_STEP_PEN)
TCO_CONF_MIN = 8.0  # max-marginal margin (log units) to report a frame
TCO_SLOT_MIN = 2.0  # median own top1-top2 gap of digits constant within a segment
TCO_LEARN_MIN = 3.0  # margin required for a frame to teach glyphs
TCO_LDA_T = 0.01  # LDA log-likelihood temperature (0 disables LDA)
TCO_LDA_REG = 0.3  # covariance shrinkage (fraction of mean variance)
TCO_PRIOR_PATH = None  # optional .npz prior (experiments); None = embedded _TCO_PRIOR_B64
_TCO_PRIOR = None


# timecode helpers
def tco_fps_nominal(fps):
    return int(round(float(fps))) if fps else 24


def tco_frames_to_tc(n, fps, sep=':'):
    nom = tco_fps_nominal(fps)
    n = int(n)
    return '%02d:%02d:%02d%s%02d' % ((n // (nom * 3600)) % 24, (n // (nom * 60)) % 60,
                                     (n // nom) % 60, sep, n % nom)


def tco_tc_to_frames(tc, fps):
    if not tc:
        return None
    import re
    parts = re.split(r'[:;.]', str(tc).strip())
    if len(parts) != 4:
        return None
    try:
        h, m, s, f = [int(x) for x in parts]
    except ValueError:
        return None
    nom = tco_fps_nominal(fps)
    if h > 23 or m > 59 or s > 59 or f >= nom:
        return None
    return ((h * 60 + m) * 60 + s) * nom + f


def tco_value_digits(v, fps):
    """frame count -> 8 digits (H H M M S S F F)"""
    nom = tco_fps_nominal(fps)
    v = np.asarray(v, np.int64)
    f = v % nom
    s = (v // nom) % 60
    m = (v // (nom * 60)) % 60
    h = (v // (nom * 3600)) % 24
    return np.stack([h // 10, h % 10, m // 10, m % 10, s // 10, s % 10, f // 10, f % 10], -1)


# image helpers
def _tco_otsu(v, bins=64):
    hist, edges = np.histogram(v, bins)
    c = 0.5 * (edges[1:] + edges[:-1])
    w0 = np.cumsum(hist).astype(np.float64)
    w1 = w0[-1] - w0
    s0 = np.cumsum(hist * c)
    mu0 = s0 / np.maximum(w0, 1)
    mu1 = (s0[-1] - s0) / np.maximum(w1, 1)
    var = w0 * w1 * (mu0 - mu1) ** 2
    return float(edges[int(np.argmax(var[:-1])) + 1])


def _tco_blur(a):
    p = np.pad(a, 1, mode='edge')
    v = (p[:-2] + 2 * p[1:-1] + p[2:]) * 0.25
    return (v[:, :-2] + 2 * v[:, 1:-1] + v[:, 2:]) * 0.25


def _tco_runs(col):
    out, x, n = [], 0, len(col)
    while x < n:
        if not col[x]:
            x += 1
            continue
        a = x
        while x < n and col[x]:
            x += 1
        out.append((a, x))
    return out


def _tco_sample(p, y0, y1, x0, x1, H, W):
    """bilinear sample of the float box [y0,y1)x[x0,x1) of p onto an HxW grid"""
    h, w = p.shape
    ys = np.clip(y0 + (np.arange(H) + 0.5) * (y1 - y0) / H - 0.5, 0, h - 1)
    xs = np.clip(x0 + (np.arange(W) + 0.5) * (x1 - x0) / W - 0.5, 0, w - 1)
    yi = np.minimum(np.floor(ys).astype(int), h - 2) if h > 1 else np.zeros(H, int)
    xi = np.minimum(np.floor(xs).astype(int), w - 2) if w > 1 else np.zeros(W, int)
    fy = (ys - yi)[:, None]
    fx = (xs - xi)[None, :]
    yj = np.minimum(yi + 1, h - 1)
    xj = np.minimum(xi + 1, w - 1)
    t = p[yi][:, xi] * (1 - fx) + p[yi][:, xj] * fx
    b = p[yj][:, xi] * (1 - fx) + p[yj][:, xj] * fx
    return (t * (1 - fy) + b * fy).astype(np.float32)


def _tco_norm_feat(g):
    g = _tco_blur(g)
    f = g.ravel() - g.mean()
    return f / (np.linalg.norm(f) + 1e-6)


def tco_prep(img, invert=None):
    """ROI luma (display gamma) -> float32 [0,1], text bright. invert=None: decide per image"""
    if img is None:
        return None
    v = np.asarray(img, np.float32)
    if v.ndim == 3:
        v = v.mean(2)
    lo, hi = np.percentile(v, 3), np.percentile(v, 99.7)
    if hi - lo < 1e-4:
        return None
    v = np.clip((v - lo) / (hi - lo), 0, 1)
    if invert is None:
        invert = bool(np.median(v) > 0.5)
    return 1.0 - v if invert else v


def tco_prep_sequence(imgs):
    """tco_prep with one polarity for the whole clip (majority vote)"""
    votes = []
    for img in imgs:
        q = tco_prep(img, False)
        if q is not None:
            votes.append(np.median(q) > 0.5)
    inv = bool(np.mean(votes) > 0.5) if votes else False
    return [tco_prep(img, inv) for img in imgs]


# layout
def _tco_band(masks):
    rowp = np.mean([m.mean(1) for m in masks], 0)
    if rowp.max() <= 0:
        return None
    runs = _tco_runs(rowp >= 0.3 * rowp.max())
    a, b = max(runs, key=lambda r: rowp[r[0]:r[1]].sum())
    return max(a - 1, 0), min(b + 1, len(rowp))


def _tco_fit_grid(U, y0, y1):
    """fallback when per-frame runs never give 11 glyphs: search digit pitch / separator width /
    start so that cell interiors carry ink and cell borders do not (U = column ink frequency)"""
    h = float(y1 - y0)
    W = len(U)
    cs = np.concatenate([[0.0], np.cumsum(U)])

    def mean_on(a, b):
        a = np.clip(a, 0, W)
        b = np.clip(b, 0, W)
        return (np.interp(b, np.arange(W + 1), cs) - np.interp(a, np.arange(W + 1), cs)) / np.maximum(b - a, 1e-3)

    best = (-1e9, None)
    pattern = 'DDSDDSDDSDD'
    for pitch in np.arange(max(2.5, 0.40 * h), 0.95 * h + 0.01, 0.25):
        for sep in np.arange(0.25 * pitch, 0.85 * pitch + 0.01, 0.25):
            total = 8 * pitch + 3 * sep
            if total > W:
                continue
            x0s = np.arange(0, W - total + 0.01, 0.5)
            score = np.zeros(len(x0s))
            x = x0s.copy()
            for ch in pattern:
                wdt = pitch if ch == 'D' else sep
                inner = mean_on(x + 0.2 * wdt, x + 0.8 * wdt)
                edge = mean_on(x - 0.5, x + 0.5)
                score += (inner if ch == 'D' else 0.5 * inner) - edge
                x = x + wdt
            score -= mean_on(x0s - pitch, x0s) + mean_on(x, x + pitch)
            i = int(np.argmax(score))
            if score[i] > best[0]:
                best = (score[i], (x0s[i], pitch, sep))
    if best[1] is None:
        return None
    x0, pitch, sep = best[1]
    cells, x = [], x0
    for ch in pattern:
        wdt = pitch if ch == 'D' else sep
        if ch == 'D':
            cells.append((x, x + wdt))
        x += wdt
    return cells


def _tco_frame_runs(p, band):
    """centres of the 11 glyph runs of one prepped frame, or None"""
    m = p > _tco_otsu(p.ravel())
    mm = m[band[0]:band[1]]
    runs = [r for r in _tco_runs(mm.any(0)) if mm[:, r[0]:r[1]].sum() >= 2]
    if len(runs) != TCO_N_CHARS:
        return None
    return np.array([0.5 * (a + b) for a, b in runs])


def tco_frame_layout(p, layout, tol=0.12):
    """
    Kerning / proportional digits in right-aligned burn-ins (e.g. '11' set tighter) shift the whole
    string in some frames; the separators then move too (a real edit: +2.5 px on '.11'). A frame whose
    glyphs split into 11 runs and whose separators moved more than tol*pitch gets its own cells,
    centred on its runs. All other frames keep the clip layout (fixed cells).
    """
    if p is None or layout.get('centers') is None:
        return layout
    c = _tco_frame_runs(p, layout['band'])
    if c is None:
        return layout
    pitch = np.mean([b - a for a, b in layout['cells']])
    ref = np.array(layout['centers'])
    if np.abs(c[[2, 5, 8]] - ref[[2, 5, 8]]).max() <= tol * pitch:
        return layout
    out = dict(layout)
    out['cells'] = [(c[s] - 0.5 * pitch, c[s] + 0.5 * pitch) for s in TCO_DIGIT_SLOTS]
    return out


def tco_estimate_layout(P, max_frames=120):
    """prepped images -> layout dict(band=(y0,y1), cells=[(x0,x1)]*8, method, frames_used)"""
    P = [p for p in P if p is not None]
    if not P:
        return None
    if len(P) > max_frames:
        P = [P[int(i)] for i in np.linspace(0, len(P) - 1, max_frames)]
    masks = [p > _tco_otsu(p.ravel()) for p in P]
    band = _tco_band(masks)
    if band is None:
        return None
    y0, y1 = band
    centers, widths = [], []
    for m in masks:
        mm = m[y0:y1]
        runs = [r for r in _tco_runs(mm.any(0)) if mm[:, r[0]:r[1]].sum() >= 2]
        if len(runs) == TCO_N_CHARS:
            centers.append([0.5 * (a + b) for a, b in runs])
            widths.append([b - a for a, b in runs])
    if len(centers) >= 3:
        # tabular digits: centre_k = x0 + pitch*(digits before k) + sep*(separators before k)
        # + half its own cell. Least squares over all 11 slots so per-glyph ink offsets
        # (e.g. a '1' sitting off-centre in a slot that is always '1') average out.
        C = np.median(np.array(centers), 0)
        A = []
        nd = ns = 0
        for k in range(TCO_N_CHARS):
            dig = k in TCO_DIGIT_SLOTS
            A.append([1.0, nd + (0.5 if dig else 0.0), ns + (0.0 if dig else 0.5)])
            if dig:
                nd += 1
            else:
                ns += 1
        x0, pitch, sep = np.linalg.lstsq(np.array(A), C, rcond=None)[0]
        cells = []
        for k in TCO_DIGIT_SLOTS:
            c = x0 + pitch * A[k][1] + sep * A[k][2]
            cells.append((c - 0.5 * pitch, c + 0.5 * pitch))
        method = 'runs'
        ref = [float(v) for v in C]
    else:
        ref = None
        U = np.mean([m[y0:y1].any(0) for m in masks], 0)
        cells = _tco_fit_grid(U, y0, y1)
        method = 'grid'
        if cells is None:
            return None
    return dict(band=(int(y0), int(y1)), cells=[(float(a), float(b)) for a, b in cells],
                method=method, frames_used=len(centers), shape=list(P[0].shape), centers=ref)


def tco_cell_features(p, layout, jitter=None):
    """-> (len(jitter), 8, D) normalized features"""
    jitter = TCO_JITTER if jitter is None else jitter
    y0, y1 = layout['band']
    out = np.zeros((len(jitter), 8, TCO_CELL[0] * TCO_CELL[1]), np.float32)
    for j, dx in enumerate(jitter):
        for k, (a, b) in enumerate(layout['cells']):
            out[j, k] = _tco_norm_feat(_tco_sample(p, y0 - 0.5, y1 + 0.5, a + dx, b + dx, TCO_CELL[0], TCO_CELL[1]))
    return out


# classifier
def _tco_prior_unpack(q, cell):
    """int8 exemplars stored at `cell` resolution -> (E, TCO_CELL) float32 unit vectors"""
    ex = q.astype(np.float32).reshape(len(q), cell[0], cell[1])
    if tuple(cell) != tuple(TCO_CELL):
        ex = np.array([_tco_sample(e, 0, cell[0], 0, cell[1], TCO_CELL[0], TCO_CELL[1]) for e in ex])
    ex = ex.reshape(len(ex), -1)
    ex -= ex.mean(1, keepdims=True)
    return ex / (np.linalg.norm(ex, axis=1, keepdims=True) + 1e-6)


def tco_load_prior():
    """font prior bank -> (E, D) float32, (E,) int labels or None"""
    global _TCO_PRIOR
    if _TCO_PRIOR is None:
        try:
            if TCO_PRIOR_PATH:
                z = np.load(TCO_PRIOR_PATH)
                q, lab, cell = z['ex'], z['lab'], tuple(int(v) for v in z['cell'])
            else:
                import base64
                import zlib
                blob = zlib.decompress(base64.b64decode(''.join(_TCO_PRIOR_B64)))
                cell = (blob[0], blob[1])
                n = (len(blob) - 2) // (1 + cell[0] * cell[1])
                lab = np.frombuffer(blob[2:2 + n], np.uint8)
                q = np.frombuffer(blob[2 + n:], np.int8).reshape(n, cell[0] * cell[1])
            _TCO_PRIOR = (_tco_prior_unpack(q, cell), lab.astype(int))
        except Exception:
            _TCO_PRIOR = False
    return _TCO_PRIOR or None


def tco_make_model(ex=None, lab=None, prior=True, prior_off=0.0):
    """
    exemplar model. prior_off is added to font-prior similarities: a clip's own glyphs match their
    learned exemplars far better (cos ~0.95) than any font prior (~0.8), so without the offset every
    digit the clip has not taught yet would lose to some learned look-alike (e.g. 6 -> 8).
    """
    parts_e, parts_l, parts_w = [], [], []
    if ex is not None and len(ex):
        parts_e.append(np.asarray(ex, np.float32))
        parts_l.append(np.asarray(lab, int))
        parts_w.append(np.zeros(len(ex), np.float32))
    pr = tco_load_prior() if prior else None
    if pr is not None:
        parts_e.append(pr[0])
        parts_l.append(pr[1])
        parts_w.append(np.full(len(pr[0]), prior_off, np.float32))
    if not parts_e:
        return None
    return dict(ex=np.concatenate(parts_e), lab=np.concatenate(parts_l), off=np.concatenate(parts_w),
                prior_off=float(prior_off))


def tco_class_sims(F, model):
    """F (..., D) -> (..., 10) best weighted cosine per digit (-1 where class has no exemplar)"""
    S = F @ model['ex'].T + model['off']
    out = np.full(S.shape[:-1] + (10,), -1.0, np.float32)
    for c in range(10):
        sel = model['lab'] == c
        if sel.any():
            out[..., c] = S[..., sel].max(-1)
    return out


def _tco_logsoftmax(a, axis=-1):
    a = a - a.max(axis, keepdims=True)
    return a - np.log(np.exp(a).sum(axis, keepdims=True))


def tco_fit_lda(X, y, reg=None):
    """
    shared-covariance Gaussian (LDA) on this clip's own labelled glyph crops. Nearest-exemplar
    cosine weighs every pixel alike; LDA learns which pixels separate look-alikes in THIS font
    and degradation (6/8/3/9 on crunchy 720p differ in two or three pixels).
    -> dict(cls, W, muz) or None
    """
    reg = TCO_LDA_REG if reg is None else reg
    cls = [c for c in range(10) if (y == c).sum() >= 3]
    if len(cls) < 2:
        return None
    mu = np.array([X[y == c].mean(0) for c in cls], np.float64)
    sel = np.isin(y, cls)
    Xc = X[sel] - mu[np.searchsorted(cls, y[sel])]
    S = Xc.T @ Xc / max(len(Xc), 1)
    D = S.shape[0]
    S += reg * np.trace(S) / D * np.eye(D)
    W = np.linalg.cholesky(np.linalg.inv(S))
    return dict(cls=np.array(cls), W=W.astype(np.float32), muz=(mu @ W).astype(np.float32))


def tco_digit_loglik(Fj, model, beta=None):
    """
    Fj (J, 8, D) jittered features of one frame -> (8, 10) log-probs.
    NN cosine gives P(c). When the model has an LDA part, the probability mass NN gives to the
    LDA-known classes is redistributed among them by the LDA posterior; unknown classes keep NN.
    """
    beta = TCO_BETA if beta is None else beta
    S = tco_class_sims(Fj, model).max(0)
    L = _tco_logsoftmax(beta * S, 1)
    lda = model.get('lda')
    if lda is not None:
        z = Fj @ lda['W']  # (J, 8, D)
        q = ((z[:, :, None, :] - lda['muz'][None, None]) ** 2).sum(-1).min(0)  # (8, C)
        pl = _tco_logsoftmax(-0.5 * TCO_LDA_T * q, 1)
        c = lda['cls']
        mass = np.log(np.exp(L[:, c]).sum(1, keepdims=True))
        L = L.copy()
        L[:, c] = mass + pl
    return L


# temporal decoder
def _tco_field_scores(L, nom):
    """per-field score arrays from (8,10) digit log-probs"""
    def two(a, b, n):
        x = np.arange(n)
        return L[a, x // 10] + L[b, x % 10]
    return [two(0, 1, 24), two(2, 3, 60), two(4, 5, 60), two(6, 7, nom)]


def tco_emission(L, vals, nom):
    d = tco_value_digits(vals, nom)
    return L[np.arange(8)[None, :], d].sum(1)


def _tco_top_values(L, nom, k=24, per_field=5):
    fs = _tco_field_scores(L, nom)
    tops = [np.argsort(-f)[:per_field] for f in fs]
    h, m, s, f = np.meshgrid(*tops, indexing='ij')
    sc = (fs[0][h] + fs[1][m] + fs[2][s] + fs[3][f]).ravel()
    v = ((((h * 60 + m) * 60 + s) * nom) + f).ravel()
    o = np.argsort(-sc)[:k]
    return v[o]


def _tco_trans(prev, cur):
    d = cur[None, :] - prev[:, None]
    T = np.full(d.shape, TCO_JUMP_PEN, np.float32)
    for s, pen in TCO_STEP_PEN.items():
        T[d == s] = pen
    return T


def tco_decode(Ls, fps, k=24, spread=6):
    """
    Ls: list of (8,10) log-prob arrays or None (unreadable frame) per frame.
    -> dict(values, margin, emis_gap, steps, cut) ; values are int frame counts
    """
    nom = tco_fps_nominal(fps)
    n = len(Ls)
    flat = np.zeros((8, 10), np.float32) - np.log(10.0)
    Ls = [flat if L is None else L for L in Ls]
    own = [_tco_top_values(L, nom, k) for L in Ls]
    deltas = np.arange(-spread, spread + 1)
    cands = []
    for t in range(n):
        c = [own[t]]
        for u in (t - 1, t + 1, t - 2, t + 2):
            if 0 <= u < n:
                c.append((own[u][:6, None] + deltas[None, :] * (1 if abs(u - t) == 1 else 2)).ravel())
        c = np.unique(np.concatenate(c))
        c = c[(c >= 0) & (c < 24 * 3600 * nom)]
        cands.append(c)
    E = [tco_emission(Ls[t], cands[t], nom) for t in range(n)]
    # forward / backward max-product
    A = [E[0].astype(np.float64)]
    back = [None]
    for t in range(1, n):
        T = _tco_trans(cands[t - 1], cands[t])
        M = A[-1][:, None] + T
        back.append(np.argmax(M, 0))
        A.append(M.max(0) + E[t])
    B = [None] * n
    B[-1] = np.zeros(len(cands[-1]))
    for t in range(n - 2, -1, -1):
        T = _tco_trans(cands[t], cands[t + 1])
        B[t] = (T + (E[t + 1] + B[t + 1])[None, :]).max(1)
    path = [int(np.argmax(A[-1]))]
    for t in range(n - 1, 0, -1):
        path.append(int(back[t][path[-1]]))
    path = path[::-1]
    values, margin, gap = [], [], []
    for t in range(n):
        Mt = A[t] + B[t]
        i = path[t]
        values.append(int(cands[t][i]))
        other = np.delete(Mt, i)
        margin.append(float(Mt[i] - other.max()) if other.size else 99.0)
        gap.append(float(E[t][i] - E[t].max()))
    steps = [None] + [values[t] - values[t - 1] for t in range(1, n)]
    cut = [s is not None and s not in TCO_STEP_PEN for s in steps]
    for t in range(1, n):  # small jumps (+4/+8 inside a 1x shot): step far off the local speed
        nb = [steps[u] for u in range(max(1, t - 4), min(n, t + 5)) if u != t]
        if len(nb) >= 3:
            med = float(np.median(nb))
            if abs(steps[t] - med) > max(3.0, 1.5 * abs(med) + 2.0):
                cut[t] = True
    glitch = [False] * n
    for t in range(1, n - 1):  # jump out and straight back = one bad frame, not a cut
        if cut[t] and cut[t + 1] and (values[t + 1] - values[t - 1]) in TCO_STEP_PEN:
            cut[t] = cut[t + 1] = False
            glitch[t] = True
    return dict(values=values, margin=margin, emis_gap=gap, steps=steps, cut=cut, glitch=glitch)


def tco_slot_confidence(Ls, dec, nom):
    """
    Identity confidence of slow digits. The temporal decoder pins digits that change (FF, SS
    ones), but a digit that stays constant within a segment (HH, MM, SS tens) could be misread the
    same way in every frame and the sequence would still look perfect (a constant TC offset).
    For such digits use the median over the segment of the frame's own top-1 vs top-2 gap (median,
    not sum: the frames are not independent evidence of glyph identity).
    -> per-frame minimum over its slow digits
    """
    n = len(dec['values'])
    out = np.full(n, 99.0)
    bounds = [0] + [t for t in range(1, n) if dec['cut'][t]] + [n]
    for a, b in zip(bounds[:-1], bounds[1:]):
        D = tco_value_digits(dec['values'][a:b], nom)
        for k in range(8):
            vals = np.unique(D[:, k])
            if len(vals) >= 3:
                continue
            for d in vals:
                ts = [a + i for i in np.where(D[:, k] == d)[0] if Ls[a + i] is not None]
                if not ts:
                    m = 0.0
                else:
                    g = []
                    for t in ts:
                        row = Ls[t][k]
                        g.append(row[d] - np.max(np.delete(row, d)))
                    m = float(np.median(g))
                idx = [a + i for i in np.where(D[:, k] == d)[0]]
                out[idx] = np.minimum(out[idx], m)
    return out


# self-calibration
def _tco_learn_exemplars(Fs, dec, nom, min_margin=None, per_class=12, model=None):
    """
    glyph crops of high-margin frames labelled by the decoded value -> exemplars.
    Only digit slots that take >= 3 different values teach: their identity is pinned by the
    temporal order (a digit that cycles can't be consistently mislabelled without breaking the
    small-step prior). Constant slots (HH, MM ...) would only confirm the prior's own guess.
    """
    min_margin = TCO_LEARN_MIN if min_margin is None else min_margin
    buckets = dict((c, []) for c in range(10))
    good = [t for t, F in enumerate(Fs) if F is not None and dec['margin'][t] >= min_margin]
    if not good:
        return None, None, None
    D = tco_value_digits([dec['values'][t] for t in good], nom)
    varying = [k for k in range(8) if len(np.unique(D[:, k])) >= 3]
    for row, t in enumerate(good):
        for k in varying:
            c = int(D[row, k])
            j = len(TCO_JITTER) // 2
            if model is not None:  # best-aligned shift for the labelled class
                j = int(np.argmax(tco_class_sims(Fs[t][:, k], model)[:, c]))
            buckets[c].append(Fs[t][j, k])
    ex, lab = [], []
    samples = (np.array([f for c in range(10) for f in buckets[c]], np.float32),
               np.array([c for c in range(10) for _ in buckets[c]], int))
    for c, lst in buckets.items():
        if len(lst) < 3:
            continue
        X = np.array(lst, np.float32)
        # centroids of small k-means clusters: averaging makes a few mislabelled crops harmless
        # (picking raw crops would let an outlier become a full exemplar)
        k = int(min(per_class, max(1, len(X) // 4)))
        C = X[np.linspace(0, len(X) - 1, k).astype(int)].copy()
        for _ in range(8):
            a = np.argmax(X @ C.T, 1)
            for j in range(k):
                if (a == j).any():
                    m = X[a == j].mean(0)
                    C[j] = m / (np.linalg.norm(m) + 1e-6)
        a = np.argmax(X @ C.T, 1)
        keep = [j for j in range(k) if (a == j).sum() >= 3]
        if not keep:
            continue
        ex.append(C[keep])
        lab += [c] * len(keep)
    if not ex:
        return None, None, None
    return np.concatenate(ex), np.array(lab, int), samples


def _tco_prior_offset(ex, lab, samples):
    """median (learned - prior) similarity of the learning crops to their own class"""
    pr = tco_load_prior()
    X, y = samples
    if pr is None or not len(X):
        return 0.0
    SL = X @ ex.T
    SP = X @ pr[0].T
    d = []
    for c in np.unique(y):
        sel = y == c
        if not (lab == c).any() or not (pr[1] == c).any():
            continue
        d += list(SL[sel][:, lab == c].max(1) - SP[sel][:, pr[1] == c].max(1))
    return float(np.clip(np.median(d), 0.0, 0.4)) if d else 0.0


def tco_cfg_model(cfg):
    """stored exemplars (cfg['ocr2']) -> (ex, lab) or (None, None)"""
    o = (cfg or {}).get('ocr2') or {}
    if not o.get('ex'):
        return None, None
    ex = np.array(o['ex'], np.float32)
    ex /= np.linalg.norm(ex, axis=1, keepdims=True) + 1e-6
    return ex, np.array(o['lab'], int)


def tco_model_to_cfg(ex, lab, cfg=None, max_per_class=16):
    """merge exemplars into cfg['ocr2'] (JSON-safe, rounded). keeps 'roi'/'templates' untouched"""
    cfg = dict(cfg or {})
    old_e, old_l = tco_cfg_model(cfg)
    E, Lb = [], []
    for c in range(10):
        a = [] if old_e is None else list(old_e[old_l == c])
        b = [] if ex is None else list(np.asarray(ex)[np.asarray(lab) == c])
        keep = (a + b)[:max_per_class] if len(a) < max_per_class else a[:max_per_class // 2] + b[:max_per_class // 2]
        E += keep
        Lb += [c] * len(keep)
    cfg['ocr2'] = dict(version=TCO_VERSION, cell=list(TCO_CELL),
                       ex=[[round(float(x), 3) for x in e] for e in E], lab=Lb)
    return cfg


def tco_read_sequence(imgs, fps=24, cfg=None, iters=2, use_prior=True, layout=None,
                  conf_min=None, extra=None, log=None):
    """
    imgs: per-frame ROI luma images (display gamma, any polarity) or None.
    cfg : no_more_manual_retime TC cfg (optional). cfg['ocr2'] exemplars are used when present.
    extra: (ex, lab) exemplars learned elsewhere, e.g. from the record TC of the same clip
           (same burn-in font, bigger and easier) - result['learned'] of that read.
    Returns dict:
      frames  : per-frame frame count (int) or None when not confident
      strings : 'HH:MM:SS:FF' or None
      conf    : max-marginal margin (log units; >= conf_min means reported)
      repaired: True where the frame's own reading disagreed and neighbours decided
      cut     : True where the decoded step is a jump (cut / big skip)
      layout, learned (ex, lab) for tco_model_to_cfg, raw (tco_decode dict of last round)
    """
    nom = tco_fps_nominal(fps)
    conf_min = TCO_CONF_MIN if conf_min is None else conf_min
    log = log or (lambda s: None)
    P = tco_prep_sequence(imgs)
    lay = layout or tco_estimate_layout(P)
    n = len(P)
    empty = dict(frames=[None] * n, strings=[None] * n, conf=[0.0] * n, repaired=[False] * n,
                 cut=[False] * n, layout=lay, learned=(None, None), raw=None)
    if lay is None:
        log('TC OCR: no text line found in ROI')
        return empty
    Fs = [tco_cell_features(p, tco_frame_layout(p, lay)) if p is not None else None for p in P]
    u_ex, u_lab = tco_cfg_model(cfg)
    if extra is not None and extra[0] is not None:
        u_ex = extra[0] if u_ex is None else np.concatenate([u_ex, extra[0]])
        u_lab = extra[1] if u_lab is None else np.concatenate([u_lab, extra[1]])
    model = tco_make_model(u_ex, u_lab, prior=use_prior)
    if model is None:
        log('TC OCR: no glyph model (prior bank missing and no stored exemplars)')
        return empty
    learned = (None, None)
    dec = None
    for it in range(iters + 1):
        Ls = [tco_digit_loglik(F, model) if F is not None else None for F in Fs]
        dec = tco_decode(Ls, nom)
        if it == iters:
            break
        ex, lab, samples = _tco_learn_exemplars(Fs, dec, nom, model=model)
        if ex is None:
            break
        learned = (ex, lab)
        allx = ex if u_ex is None else np.concatenate([u_ex, ex])
        alll = lab if u_lab is None else np.concatenate([u_lab, lab])
        off = _tco_prior_offset(ex, lab, samples) if use_prior else 0.0
        model = tco_make_model(allx, alll, prior=use_prior, prior_off=off)
        if TCO_LDA_T > 0:
            model['lda'] = tco_fit_lda(samples[0], samples[1])
    missing = [c for c in range(10) if not (model['lab'] == c).any()]
    if missing:  # a digit the model cannot produce would be forced onto a look-alike
        log('TC OCR: no exemplar for digit(s) %s - nothing reported as confident' % missing)
        conf_min = float('inf')
    sc = tco_slot_confidence(Ls, dec, nom)
    dec['slot_conf'] = [float(s) for s in sc]
    conf = [float(m) if s >= TCO_SLOT_MIN else float(min(m, s)) for m, s in zip(dec['margin'], sc)]
    frames, strings, rep = [], [], []
    for t in range(n):
        ok = dec['margin'][t] >= conf_min and sc[t] >= TCO_SLOT_MIN and not dec['glitch'][t]
        v = dec['values'][t]
        frames.append(v if ok else None)
        strings.append(tco_frames_to_tc(v, nom) if ok else None)
        rep.append(dec['emis_gap'][t] < -1.0)
    log('TC OCR: %d/%d frames confident (layout %s)' % (sum(f is not None for f in frames), n, lay['method']))
    return dict(frames=frames, strings=strings, conf=conf, repaired=rep, cut=dec['cut'],
                layout=lay, learned=learned, model=model, raw=dec)


# convenience API
def tco_decode_sequence(frames_roi, cfg=None, fps=24, rec_roi=None, log=None):
    """
    frames_roi: per-frame SOURCE TC ROI images (display luma) or None.
    rec_roi   : optional per-frame RECORD TC ROI images of the same clip; read first, its glyphs
                teach the source reader (same burn-in font, usually bigger).
    -> (rows, summary)
       rows   : list of (tc_frames or None, confidence, flags) per frame
                flags: set of 'cut' (jump into this frame), 'repaired' (own reading disagreed,
                neighbours decided), 'glitch' (single outlier frame), 'low' (below threshold)
       summary: dict(n, confident, coverage, cuts=[frame], layout, learned_digits, record=...)
    """
    extra = None
    rec = None
    if rec_roi is not None:
        rec = tco_read_sequence(rec_roi, fps, cfg=cfg, log=log)
        extra = rec['learned']
    r = tco_read_sequence(frames_roi, fps, cfg=cfg, extra=extra, log=log)
    rows = []
    for t in range(len(r['frames'])):
        fl = set()
        if r['cut'][t]:
            fl.add('cut')
        if r['repaired'][t]:
            fl.add('repaired')
        if r['raw'] is not None and r['raw']['glitch'][t]:
            fl.add('glitch')
        if r['frames'][t] is None:
            fl.add('low')
        rows.append((r['frames'][t], float(r['conf'][t]), fl))
    n = len(rows)
    conf_n = sum(1 for v, _, _ in rows if v is not None)
    ex, lab = r['learned']
    summary = dict(n=n, confident=conf_n, coverage=(100.0 * conf_n / n) if n else 0.0,
                   cuts=[t for t in range(n) if r['cut'][t]], layout=r['layout'],
                   learned_digits=sorted(set(int(c) for c in lab)) if lab is not None else [],
                   record=None if rec is None else dict(
                       confident=sum(v is not None for v in rec['frames']), frames=rec['frames']))
    return rows, summary


def tco_exemplars_from_typed(imgs, typed, layout=None):
    """
    Minimal manual calibration: the user types the TC seen on one or a few frames.
    typed: {frame_index: 'HH:MM:SS:FF'} -> (ex, lab) for tco_model_to_cfg / tco_read_sequence(extra=...)
    """
    P = tco_prep_sequence(imgs)
    lay = layout or tco_estimate_layout(P)
    ex, lab = [], []
    for t, s in typed.items():
        v = tco_tc_to_frames(s, 100)  # 100: accept any FF while parsing digits
        if v is None or P[t] is None or lay is None:
            continue
        dg = [int(ch) for ch in s if ch.isdigit()]
        if len(dg) != 8:
            continue
        F = tco_cell_features(P[t], tco_frame_layout(P[t], lay))
        for k in range(8):
            ex.append(F[len(TCO_JITTER) // 2, k])
            lab.append(dg[k])
    if not ex:
        return None, None
    return np.array(ex, np.float32), np.array(lab, int)


