# link to no_more_manual_retime
def tc_decode_rows(src_imgs, cfg=None, fps=24, log=None, keep_model=False):
    """ same (rows, summary) as tco_decode_sequence + summary['raw'] = dict(values, margin)
    (decoded values / margins of frames that were not confident - for weak hints in TC-first mode). The rest of rows / summary is the same as the original
    record TC (rec_imgs) augmentation removed. With keep_model=True, summary['_model'] = glyph model (to show 'the value the tool read' in the TC calibration window)"""
    r = tco_read_sequence(src_imgs, fps, cfg=cfg, log=log)
    rows = []
    for t in range(len(r['frames'])):
        fl = set()
        if r['cut'][t]:
            fl.add('cut')
        if r['repaired'][t]:
            fl.add('repaired')
        if r['raw'] is not None and r['raw']['glitch'][t]:
            fl.add('glitch')
        if r['frames'][t] is None:
            fl.add('low')
        rows.append((r['frames'][t], float(r['conf'][t]), fl))
    n = len(rows)
    conf_n = sum(1 for v, _, _ in rows if v is not None)
    ex, lab = r['learned']
    summary = dict(n=n, confident=conf_n, coverage=(100.0 * conf_n / n) if n else 0.0,
                   cuts=[t for t in range(n) if r['cut'][t]], layout=r['layout'],
                   learned_digits=sorted(set(int(c) for c in lab)) if lab is not None else [],
                   record=None)
    raw = r['raw']
    summary['raw'] = dict(values=list(raw['values']) if raw is not None else [None] * n,
                          margin=[float(m) for m in raw['margin']] if raw is not None else [0.0] * n)
    if keep_model:
        summary['_model'] = r.get('model')
    return rows, summary


def esc_action(scanning, playing, tip_up, has_sel):
    """ what one Esc press does in the main window. cancel search -> stop playback -> close hover detail -> clear selection -> close window (one at a time)"""
    if scanning:
        return 'scan_cancel'
    if playing:
        return 'stop'
    if tip_up:
        return 'tip'
    if has_sel:
        return 'sel'
    return 'close'


def tl_clear_sel(sel, excl, pins):
    """ timeline 'clear selection' = empties only the drag selection range (sel) - exclusion ranges (excl) and pins (pins) stay.
    -> (sel, excl, pins, changed)"""
    return None, excl, pins, bool(sel)


# TC calibration window: flow state / cleanup of typed input / display of read values (pure functions)
TC_CALIB_GOOD = 0.60  # if test coverage is at least this ratio it is 'sufficient' -> [Save] becomes the default button
TC_CALIB_AUTO_FRAMES = 150  # upper limit on clip length (frames) for which the test runs automatically when the region is drawn and the mouse released. Beyond it, the user presses [Test]


def tc_calib_state(has_roi, tested_cov=None, typed_pending=False, good=TC_CALIB_GOOD):
    """ step state of the TC calibration window.
    has_roi: whether a valid region exists / tested_cov: last test coverage (0-100, None if none) /
    typed_pending: whether the manually typed TC changed since the last test
    -> dict(stage=1|2|3, key, default='test'|'save'|None, test_on, save_on)
    key: draw (no region) / test (test needed) / retest (re-test with the input applied) / good (can save) / low (low readability)"""
    if not has_roi:
        return dict(stage=1, key='draw', default=None, test_on=False, save_on=False)
    if tested_cov is None:
        return dict(stage=2, key='test', default='test', test_on=True, save_on=True)
    if typed_pending:
        return dict(stage=2, key='retest', default='test', test_on=True, save_on=True)
    if tested_cov >= 100.0 * good:
        return dict(stage=3, key='good', default='save', test_on=True, save_on=True)
    return dict(stage=2, key='low', default=None, test_on=True, save_on=True)


def tc_calib_message(st, cov=None):
    """ step state -> one line telling the next action (plain words)"""
    k = st['key']
    if k == 'draw':
        return _t('TC 숫자 줄을 드래그해 감싸세요',
                  'Drag around the TC digit row.')
    if k == 'test':
        return _t('영역을 그렸습니다 — [테스트]를 눌러 클립 전체를 읽어 보세요',
                  'Region drawn — click [Test] to read the whole clip.')
    if k == 'retest':
        return _t('입력한 TC를 예시로 다시 읽습니다 — [테스트]를 눌러 주세요',
                  'Read again using the entered TC as an example — click [Test].')
    if k == 'good':
        return _t('판독 %.0f%% — [저장]을 누르면 끝납니다',
                  'Read %.0f%% — click [Save] to finish.') % cov
    return _t(
        '판독 %.0f%% — 영역을 숫자에 더 딱 맞게 다시 그리거나, 처음 보는 폰트면 아래 칸에 이 프레임의 TC를 입력하세요',
        'Read %.0f%% — draw the region more tightly around the digits, or enter this frame’s TC below for an unfamiliar font.') % cov


def tc_typed_normalize(text, fps=24):
    """ clean up manually typed TC. Accepts 8 digits / HH:MM:SS:FF / ':' ';' '.' space separators (drop frame is kept as ';')
    -> (shown, state, msg, norm)   shown: 'HH:MM:SS:FF' shape to show in the field (only the front part while typing) /
    state: empty | partial | bad | ok / msg: one-line reason / norm: 'HH:MM:SS:FF' to hand to the engine when ok"""
    text = str(text or '')
    digits = [c for c in text if c.isdigit()][:8]
    pairs = [''.join(digits[i:i + 2]) for i in range(0, len(digits), 2)]
    df = ';' in text and len(digits) > 6
    shown = ':'.join(pairs)
    if df and len(pairs) == 4:
        shown = ':'.join(pairs[:3]) + ';' + pairs[3]
    if not digits:
        return '', 'empty', '', None
    if len(digits) < 8:
        return shown, 'partial', _t('숫자 %d개 더 필요합니다 (8자리)',
                                    '%d more digits required (8 total)') % (8 - len(digits)), None
    h, m, sec, f = [int(x) for x in pairs]
    nom = tco_fps_nominal(fps)
    why = None
    if h > 23:
        why = _t('시간 값이 24 이상입니다', 'Hours must be below 24.')
    elif m > 59:
        why = _t('분 값이 60 이상입니다', 'Minutes must be below 60.')
    elif sec > 59:
        why = _t('초 값이 60 이상입니다', 'Seconds must be below 60.')
    elif f >= nom:
        why = _t('프레임 값이 %d 이상입니다 (이 클립은 %dfps)',
                 'Frame value must be below %d (this clip is %d fps).') % (nom, nom)
    if why:
        return shown, 'bad', why, None
    return shown, 'ok', '', shown.replace(';', ':')


def tc_conf_pct(margin):
    """ reading margin (log units, max marginal probability gap) -> human-readable 0-100% confidence. Monotonic logistic 100 / (1 + exp(-(m - 2.8) / 3)).
    Tuned so the confidence threshold (TCO_CONF_MIN = 8) is 85%: m 0 = 28%, 2.8 = 50%, 8 = 85%, 12 = 97%. Display is clipped to 1-99%"""
    import math
    m = max(-30.0, min(40.0, float(margin)))
    return int(max(1, min(99, round(100.0 / (1.0 + math.exp(-(m - 2.8) / 3.0))))))


def tc_frame_read(p, summ, value, fps):
    """ 'value the tool read' for one frame -> (string 'HH:MM:SS:FF' ('?' for unread digits), number of unread digits | None)
    p: that frame's ROI prepared with tco_prep_sequence, summ: tc_decode_rows(keep_model=True) summary, value: decoded value (frame count) or None"""
    lay, model = summ.get('layout'), summ.get('_model')
    if p is None or lay is None or model is None:
        return None, None
    L = tco_digit_loglik(tco_cell_features(p, tco_frame_layout(p, lay)), model)
    d = np.array(tco_value_digits([value], fps)[0]) if value is not None else np.argmax(L, 1)
    ch = []
    for k in range(8):
        gap = L[k, d[k]] - np.max(np.delete(L[k], d[k]))
        ch.append(str(int(d[k])) if gap >= TCO_SLOT_MIN else '?')
    s = '%s%s:%s%s:%s%s:%s%s' % tuple(ch)
    return s, sum(1 for c in ch if c == '?')


# Full core pipeline (independent of Nuke)
def _fill_excluded(path, excl, fixed):
    """ fill excluded frames (those without pins/TC) at constant speed (integer rounding) between the confirmed frames before and after"""
    path = path.copy()
    E = len(path)
    free = np.array([bool(excl[t]) and t not in fixed for t in range(E)])
    t = 0
    while t < E:
        if not free[t]:
            t += 1
            continue
        a = t
        while t < E and free[t]:
            t += 1
        b = t - 1
        L, R = a - 1, b + 1
        if L >= 0 and R < E:
            for k in range(a, b + 1):
                path[k] = int(round(path[L] + (path[R] - path[L]) * (k - L) / float(R - L)))
        elif L >= 0:
            v = path[L] - path[L - 1] if L >= 1 else 1
            for k in range(a, b + 1):
                path[k] = path[L] + v * (k - L)
        elif R < E:
            v = path[R + 1] - path[R] if R + 1 < E else 1
            for k in range(a, b + 1):
                path[k] = path[R] - v * (R - k)
    return path


def plate_pan_like(P_lum, path, E_valid, d=4, nmax=8, r=16):
    """ whether the plate over time does almost only a 'whole-frame translation' (pan / tilt): the median NCC when plate p and p+d on the path are matched with
    the best shift (+/-r px @64) and the median NCC when simply compared. Both are returned (None if unavailable).
    If a reposition move (drift) is animated on such a plate, there is little basis to separate time from movement -> confidence warning"""
    P = P_lum.shape[0]
    vt = np.where(E_valid)[0]
    if len(vt) < 4 or P < d + 2:
        return None
    Ps = to_display(blur121(down2(P_lum)))
    H, W = Ps.shape[-2:]
    sel = np.unique(np.clip(np.asarray(path)[vt[np.linspace(0, len(vt) - 1, min(nmax, len(vt))).astype(int)]], 0, P - 1 - d))
    sh, n0 = [], []
    for p in sel:
        a, b = Ps[p], Ps[p + d]
        if a.std() < 1e-6 or b.std() < 1e-6:
            continue
        a0, b0 = a - a.mean(), b - b.mean()
        n0.append(float((a0 * b0).sum() / (np.sqrt((a0 * a0).sum() * (b0 * b0).sum()) + 1e-12)))
        cc = np.fft.irfft2(np.fft.rfft2(a0) * np.conj(np.fft.rfft2(b0)), s=(H, W))
        cc[r + 1:H - r, :] = -np.inf
        cc[:, r + 1:W - r] = -np.inf
        dy, dx = np.unravel_index(int(np.argmax(cc)), cc.shape)
        dy, dx = (dy - H if dy > H // 2 else dy), (dx - W if dx > W // 2 else dx)
        aa = a[max(0, dy):H + min(0, dy), max(0, dx):W + min(0, dx)]
        bb = b[max(0, -dy):H + min(0, -dy), max(0, -dx):W + min(0, -dx)]
        aa, bb = aa - aa.mean(), bb - bb.mean()
        sh.append(float((aa * bb).sum() / (np.sqrt((aa * aa).sum() * (bb * bb).sum()) + 1e-12)))
    if not sh:
        return None
    return float(np.median(sh)), float(np.median(n0))


def half_agreement(E_lum, P_lum, m, path, E_valid, opt=None, coords=None, win=30, nmax=40):
    """ fraction of frames where matching the top / bottom half of the frame separately makes both pick the same plate as the path (+/-1).
    A uniqueness metric that catches pictures where only one half matches (a burn-in / overlay dominates one half, or it accidentally resembles a wrong segment).
    Halves with almost no texture are left out of the decision (sky / black screen). None if no frame can be judged"""
    E, He, We = E_lum.shape
    P, Hp, Wp = P_lum.shape
    yy = np.nonzero(m)[0]
    if len(yy) < 64:
        return None
    cy = float(np.median(yy))
    Y = np.arange(He)[:, None]
    halves = [m & (Y < cy), m & (Y >= cy)]
    if min(h.sum() for h in halves) < 0.2 * m.sum():
        return None
    cells = [_cells(h) for h in halves]
    Pb = blur121(P_lum)
    if coords is None:
        xy0 = warp_coords(He, We, Hp, Wp, opt['s'], opt['tx'], opt['ty'], opt['flop'])
    vt = np.where(E_valid)[0]
    if len(vt) < 4:
        return None
    sel = vt[np.linspace(0, len(vt) - 1, min(nmax, len(vt))).astype(int)]
    agree = []
    for t in sel:
        lo, hi = max(0, int(path[t]) - win), min(P - 1, int(path[t]) + win)
        idx = np.arange(lo, hi + 1)
        if len(idx) < 5:
            continue
        xp, yp = coords[t] if coords is not None else xy0
        Wimg, _ = bilinear(Pb[idx], xp, yp)
        votes = []
        for h, c in zip(halves, cells):
            ev = E_lum[t][h]
            if ev.std() < 1e-4 * (abs(ev.mean()) + 1e-6):  # textureless half
                continue
            cost = _cell_cost(rank_rows(Wimg[:, h]), rank_rows(ev), c)
            votes.append(abs(int(idx[int(np.argmin(cost))]) - int(path[t])) <= 1)
        if votes:
            agree.append(all(votes))
    return float(np.mean(agree)) if agree else None


def tc_slow_frames(pins, win=4, lo=0.1, hi=0.9):
    """ among confident TC pins {t: q}, frames where TC advances slower than 1x (slope lo~hi between the farthest TCs within +/-win).
    In an interpolated slow the burn-in TC is floor(source position), so the best picture can be TC + 1 (floor handling in tc_first_pins)"""
    ts = sorted(pins)
    out = set()
    for i, t in enumerate(ts):
        a = [u for u in ts[max(0, i - win):i] if t - u <= win]
        b = [u for u in ts[i + 1:i + 1 + win] if u - t <= win]
        if not a or not b:
            continue
        v = (pins[b[-1]] - pins[a[0]]) / float(b[-1] - a[0])
        if lo <= v <= hi:
            out.add(t)
    return out


def tc_interp_frames(E_disp, pins, win=6, ratio=0.35):
    """ TC frames with evidence of an interpolated slow: among tc_slow_frames, those where the EDIT picture difference of the surrounding (+/-win) 'neighbor pair with the same TC'
    exceeds ratio times the difference of the 'pair where TC is +1'. In a frame-repeat (duplicate) slow the same TC pair has the same picture so ~0 (test06_const0p5x:
    the burn-in TC is right but if the noisy argmin is solved with floor handling for frames at TC + 1 it is wrong), while interpolation (blend / flow) changes the picture every frame, ~1.
    E_disp (E, N) display values"""
    slow = tc_slow_frames(pins)
    if not slow:
        return set()
    E = E_disp.shape[0]
    dE = np.full(E, np.nan)
    dE[1:] = np.abs(E_disp[1:] - E_disp[:-1]).mean(axis=1)
    rep, adv = [], []
    for t in range(1, E):
        if t in pins and t - 1 in pins:
            d = pins[t] - pins[t - 1]
            if d == 0:
                rep.append(t)
            elif d == 1:
                adv.append(t)
    if not rep or not adv:
        return set()
    base = float(np.nanmedian(dE[adv]))
    if not np.isfinite(base) or base <= 1e-9:
        return set()
    out = set()
    rep = np.asarray(rep)
    for t in slow:
        near = rep[np.abs(rep - t) <= win]
        if len(near) and float(np.nanmedian(dE[near])) > ratio * base:
            out.add(t)
    return out


def tc_increment_check(U, E_valid, P_valid, tc, image_path):
    """ Independent image evidence for jittering integer TC; never judge flat images."""
    if image_path is None:
        return None
    interp = tc.get('interp') or set()
    E, P = U.shape
    points = [(int(t), int(q)) for t, q in sorted((tc.get('pins') or {}).items())
              if 0 <= t < E and 0 <= q < P and E_valid[t] and P_valid[q] and t not in interp]
    pairs = []
    for (a, qa), (b, qb) in zip(points, points[1:]):
        if not np.all(E_valid[a:b + 1]) or any(t in interp for t in range(a, b + 1)):
            continue
        supported = True
        for t, q in ((a, qa), (b, qb)):
            row = U[t]
            fin = np.isfinite(row) & P_valid
            if fin.sum() < 3:
                supported = False
                break
            best = float(row[fin].min())
            sep = float(np.median(row[fin])) - best
            ip = int(image_path[t])
            # An unreliable optical solve must not veto usable TC.
            if sep <= 1e-8 or not np.isfinite(row[ip]) or row[ip] > best + .05 * sep:
                supported = False
                break
        if supported:
            pairs.append((a, b, (qb - qa) != int(image_path[b] - image_path[a])))
    if len(pairs) < 8:
        return None
    frac = sum(p[2] for p in pairs) / float(len(pairs))
    ts = np.array([t for t, q in points], int)
    qs = np.array([q for t, q in points], int)
    ic = U[ts, np.asarray(image_path)[ts]]
    tc_cost = U[ts, qs]
    finite = np.isfinite(ic) & np.isfinite(tc_cost)
    # Both an increment discrepancy and positive image evidence are required.
    if frac > .10 and finite.any() and float(ic[finite].sum()) < .85 * float(tc_cost[finite].sum()):
        return dict(fraction=frac, pairs=len(pairs))
    return None


def tc_lowq_pins(U, path, E_valid, tc_pins, user_pins=None, interp_frames=()):
    """TC-owned quality outliers only; explicit user anchors are never released."""
    # Fractional motion can leave short detector gaps at blend endpoints.
    protected = {j for t in interp_frames for j in range(max(0, int(t) - 2), min(len(path), int(t) + 3))}
    values = U[np.arange(len(path)), path]
    finite = np.asarray(E_valid, bool) & np.isfinite(values)
    base = float(np.median(values[finite])) + 1e-6 if finite.any() else 1.0
    candidates = [int(t) for t in sorted(tc_pins) if t not in (user_pins or {}) and t not in protected and finite[t]
                  and values[t] > LOWQ_RATIO * base and np.nanmin(U[t]) < .75 * values[t]]
    # A cut/continuity conflict is not a failed forced match. Defer this retry as a whole.
    return [] if any(int(path[t]) != int(tc_pins[t]) for t in candidates) else candidates


def tc_first_pins(U, E_valid, P_valid, tc, user_pins=None, image_path=None):
    """ TC-first mode: confident TC pin candidates -> image veto / offset check -> pins actually used + weak hints
    tc = dict(pins={t: p}, hints={t: (p, w)})  (p is the plate index in terms of this cost matrix)
    Unit = row separation rel = (U[t,p] - row min) / (row median - row min): 0 = image best, 1 = any picture
    * Veto: if the row minimum (image argmin) is unique ( criterion: the runner-up outside +/-2 is more than 3% worse) and rel > TC_VETO, that TC is discarded.
            Frames without image evidence (excluded / black) keep TC as is
    * Offset: if disagreement (unique + rel > TC_DISAGREE) > TC_VETO_FRAC, k = median of (argmin - TC) over the disagreeing frames.
              |k| >= 1 being consistent (TC_OFFSET_SHARE) means 'offset' - the burn-in is consistently later than the picture or starts at a different value (including a frame-delay pattern)
    * If it is not an offset and disagreement > TC_MISMATCH_FRAC, it is 'mismatch' (another clip's TC, etc.)
    Returns (pins_add, hints_add, info). If mode != 'first', pins_add / hints_add are empty (image path only)
    """
    E, P = U.shape
    idx = np.arange(P)
    user_pins = user_pins or {}
    keep, veto, dis, image_verified = {}, [], [], {}
    jitter = tc_increment_check(U, E_valid, P_valid, tc, image_path)
    if jitter is not None and tc.get('force'):
        weak = {int(t): (int(q), .05) for t, q in (tc.get('pins') or {}).items()
                if 0 <= t < E and 0 <= q < P and t not in user_pins}
        return {}, weak, dict(mode='increment_mismatch', candidates=len(weak), used=0,
                              vetoed=0, veto_frac=0.0, disagree_frac=jitter['fraction'],
                              increment_disagree=jitter['fraction'], increment_pairs=jitter['pairs'],
                              offset=None, weak=len(weak), veto_frames=[], image_verified={})
    if tc.get('force'):  # re-run where the image is weak and TC is chosen: no veto / disagreement check
        keep = dict((t, q) for t, q in (tc.get('pins') or {}).items()
                    if 0 <= t < E and 0 <= q < P and t not in user_pins)
        weak = dict((t, (q, float(w))) for t, (q, w) in (tc.get('hints') or {}).items()
                    if 0 <= t < E and 0 <= q < P and t not in keep and t not in user_pins and w > 0)
        return keep, weak, dict(mode='first' if keep else 'none', candidates=len(keep), used=len(keep), vetoed=0,
                                veto_frac=0.0, disagree_frac=0.0, offset=None, weak=len(weak), veto_frames=[],
                                forced=True, image_verified={})
    # temporal consistency of image evidence: the row minimum (argmin) counts as 'unique image evidence' only when it connects with the argmin of the
    # previous / next valid frames within the speed range (SPEED_MAX + 1). If optical is wrong (pillarbox undetected s 2.01 / variable zoom solved as static) and the cost is noise between
    # unrelated pictures, the argmin is 'unique' by a 3 % gap in every row yet jumps to a random place each frame -> that veto / disagreement
    # threw away correct TC (confident 100/100) (test02_ramp_decel_pillarbox 0 %)
    amin = np.full(E, -10 ** 6)
    for t in range(E):
        if E_valid[t]:
            fin = np.isfinite(U[t]) & P_valid
            if fin.sum() >= 3:
                amin[t] = int(np.argmin(np.where(fin, U[t], np.inf)))
    coh = np.zeros(E, bool)  # at least 2 of the 2 frames before and after are within the speed range (chance of accidentally matching ~1 %)
    for t in range(E):
        if amin[t] < 0:
            continue
        nb = sum(1 for u in (t - 2, t - 1, t + 1, t + 2) if 0 <= u < E and amin[u] >= 0 and
                 abs(int(amin[u]) - int(amin[t])) <= SPEED_MAX * abs(u - t) + 1)
        coh[t] = nb >= 2
    slow_tc = tc.get('interp') if tc.get('interp') is not None else tc_slow_frames(tc.get('pins') or {})
    floor = []
    for t, q in sorted((tc.get('pins') or {}).items()):
        if not (0 <= t < E and 0 <= q < P) or t in user_pins:
            continue
        r = U[t]
        fin = np.isfinite(r) & P_valid
        if not E_valid[t] or fin.sum() < 3 or not fin[q]:
            keep[t] = q
            continue
        rr = np.where(fin, r, np.inf)
        a = int(np.argmin(rr))
        sep = float(np.median(r[fin])) - float(rr[a])
        far = fin & (np.abs(idx - a) > 2)
        unique = ((not far.any()) or float(rr[far].min()) >= float(rr[a]) * 1.03) and bool(coh[t])
        rel = (float(rr[q]) - float(rr[a])) / sep if sep > 1e-9 else 0.0
        # the burn-in TC in an interpolated (optical flow / blend) slow segment stamps the previous integer frame (floor) on interpolated frames ->
        # if the best picture is TC + 1 it is not a disagreement but agreement with the 'floor': pin to TC + 1 (best picture = rounding) and leave it out of the offset decision
        # (test01_blend_0p75x / test04_blend_0p33x / test01_slow_0p33x misjudged as 'TC offset +1'). If merely left loose
        # on a ramp the path drifts without knots and leaves +/-1 (test07_blend_ramp <=1f 90 -> 68 %)
        if t in slow_tc and unique and a == q + 1:
            floor.append(t)
            keep[t] = q + 1
            continue
        if unique and rel > TC_DISAGREE:
            dis.append(a - q)
        if unique and rel > TC_VETO:
            veto.append(t)
        else:
            keep[t] = q
            verified_unique = unique and (not far.any() or float(rr[far].min()) > float(rr[a]) + 1e-9)
            if verified_unique and sep > 1e-9 and rel <= TC_DISAGREE:
                image_verified[int(t)] = int(q)
    n = len(keep) + len(veto)
    df = len(dis) / float(n) if n else 0.0
    info = dict(mode='first', candidates=n, used=len(keep), vetoed=len(veto), veto_frac=len(veto) / float(max(n, 1)),
                disagree_frac=df, offset=None, weak=0, veto_frames=veto, floor=len(floor), image_verified={})
    if n == 0:
        info['mode'] = 'none'
        return {}, {}, info
    if df > TC_VETO_FRAC and len(dis) >= 3:
        k = int(np.median(dis))
        if abs(k) >= 1 and np.mean(np.asarray(dis) == k) >= TC_OFFSET_SHARE:
            info.update(mode='offset', offset=k)
    if info['mode'] == 'first' and df > TC_MISMATCH_FRAC:
        info['mode'] = 'mismatch'
    if info['mode'] != 'first':
        return {}, {}, info
    # Preserve existing offset/misread diagnostics. Test jitter only after isolated vetoes.
    jitter = tc_increment_check(U, E_valid, P_valid, dict(tc, pins=keep), image_path)
    if jitter is not None:
        weak = {int(t): (int(q), .05) for t, q in keep.items()}
        info.update(mode='increment_mismatch', used=0, weak=len(weak),
                    increment_disagree=jitter['fraction'], increment_pairs=jitter['pairs'])
        return {}, weak, info
    weak = {}
    for t, (q, w) in (tc.get('hints') or {}).items():
        if 0 <= t < E and 0 <= q < P and t not in keep and t not in user_pins and t not in veto and w > 0:
            weak[t] = (q, float(w))
    info['weak'] = len(weak)
    info['image_verified'] = image_verified
    return keep, weak, info


def local_motion_retry_allowed(pre_path, product_path, valid, spans, pins=None, hints=None,
                               tc_pins=None, tc_hints=None, cuts=(), track=None, split=None,
                               exclude=None, region=None, interpolation=False, tc=None):
    """Retry only a dominant ambiguous bridge with no independent timing authority."""
    if (pins or hints or tc_pins or tc_hints or tc is not None or cuts or track is not None or
            region is not None or interpolation or (split and split.get('split'))):
        return False
    valid = np.asarray(valid, bool)
    before, product = np.asarray(pre_path), np.asarray(product_path)
    if (before.shape != valid.shape or product.shape != valid.shape or valid.sum() < 32 or
            not np.isfinite(before).all() or not np.isfinite(product).all() or
            np.any(np.diff(before[valid]) < 0) or np.any(np.diff(product[valid]) < 0) or
            np.array_equal(before, product) or
            (exclude is not None and np.asarray(exclude, bool).any())):
        return False
    ambiguous = [s for s in spans if s.get('tier') == 'ambiguous']
    if len(ambiguous) != 1:
        return False
    span = ambiguous[0]
    coverage = valid[max(0, int(span['t0'])):int(span['t1']) + 1].sum()
    return bool(coverage >= .75 * valid.sum())


def local_motion_cell_weights(raw, cells):
    """Concentrated temporal signal must exceed short-term noise in several cells."""
    order, starts, counts, keep = cells
    if raw.ndim != 2 or len(raw) < 8 or raw.shape[1] != len(order):
        return None
    spread = np.quantile(raw, .9, axis=0) - np.quantile(raw, .1, axis=0)
    noise = np.median(np.abs(np.diff(raw, axis=0)), axis=0)
    signal = np.maximum(spread - 3.0 * noise, 0.0)
    energy = (np.add.reduceat(signal[order], starts) / counts)[keep]
    if len(energy) < 6 or not np.isfinite(energy).all():
        return None
    threshold = max(1e-6, float(np.median(np.ptp(raw, axis=1))) * .01,
                    float(np.median(energy)) * 4.0)
    active = energy > threshold
    if active.sum() < 6 or active.mean() > .35:
        return None
    weights = np.where(active, energy, 0.0).astype(np.float32)
    return weights / max(float(weights.max()), 1e-8)


def local_motion_candidate_accepted(pre_path, path_a, path_b, candidate, valid,
                                    gain_a_on_b, gain_b_on_a, candidate_spans, candidate_response):
    valid = np.asarray(valid, bool)
    paths = [np.asarray(p) for p in (pre_path, path_a, path_b, candidate, candidate_response)]
    if not valid.any() or any(p.shape != valid.shape or not np.isfinite(p).all() for p in paths):
        return False
    before, pa, pb, proposed, response = paths
    if any(np.any(np.diff(p[valid]) < 0) for p in (pa, pb, proposed)):
        return False
    agreement = np.abs(pa[valid] - pb[valid])
    return bool(np.isfinite([gain_a_on_b, gain_b_on_a]).all() and
                min(gain_a_on_b, gain_b_on_a) >= .05 and
                np.median(agreement) <= .5 and agreement.max() <= 1 and
                np.max(np.abs(proposed[valid] - before[valid])) <= 3 and
                np.array_equal(response, proposed) and
                not any(s.get('tier') == 'ambiguous' for s in candidate_spans))


def local_motion_has_blend(edit_pixels, plate_pixels, path, valid):
    """Keep genuine subframe evidence out of the integer local-motion retry."""
    edit, plate = to_display(edit_pixels), to_display(plate_pixels)
    rows = np.flatnonzero(valid)
    edit = fit_tone_lut(edit[rows], plate[np.asarray(path)[rows]])(edit)
    def plate_at(t, indices):
        return plate[indices]
    frac, interp = detect_slow(edit, plate_at, path, valid, len(plate))
    if np.any(interp & valid):
        return True
    est, gain, vtx = subframe_estimates(edit, plate_at, path, valid, len(plate), frac, interp)
    return bool(np.any(subframe_blend_votes(path, est, gain, vtx) & valid))


def local_motion_retry_candidate(U, pre_path, product_path, spans, E_valid, P_valid,
                                 E_pixels, P_pixels, cells, D, q0, max_speed=16, **context):
    """Use disjoint informative tiles to challenge a near-hold bridge, locally.

    Rejection returns the original product path, never the unbridged DP path.
    Existing pixels and difference tables are reused; no extra rendering occurs.
    """
    diag = dict(adopted=False, reason='context')
    if not local_motion_retry_allowed(pre_path, product_path, E_valid, spans, **context):
        return product_path, diag
    span = next(s for s in spans if s.get('tier') == 'ambiguous')
    span_mask = np.zeros(len(pre_path), bool)
    span_mask[int(span['t0']):int(span['t1']) + 1] = True
    span_valid = E_valid & span_mask
    weights = local_motion_cell_weights(E_pixels[span_valid], cells)
    if weights is None:
        return product_path, dict(diag, reason='insufficient_local_signal')
    order, starts, counts, keep = cells
    active = np.flatnonzero(weights > 0)
    group = np.zeros(len(weights), int)
    group[active[1::2]] = 1
    costs = [np.zeros_like(U, dtype=np.float32), np.zeros_like(U, dtype=np.float32)]
    totals = [0.0, 0.0]
    wi = 0
    for start, count, kept in zip(starts, counts, keep):
        if not kept:
            continue
        weight, side = float(weights[wi]), int(group[wi])
        wi += 1
        if weight <= 0:
            continue
        pixels = order[start:start + count]
        ee, pp = E_pixels[:, pixels].copy(), P_pixels[:, pixels].copy()
        ee -= ee.mean(axis=1, keepdims=True)
        pp -= pp.mean(axis=1, keepdims=True)
        ee /= np.maximum(np.linalg.norm(ee, axis=1, keepdims=True), 1e-6)
        pp /= np.maximum(np.linalg.norm(pp, axis=1, keepdims=True), 1e-6)
        costs[side] += weight * .25 * np.maximum(0., 1. - ee @ pp.T)
        totals[side] += weight
    combined = (costs[0] + costs[1]) / sum(totals)
    costs = [cost / total for cost, total in zip(costs, totals)]
    for cost in costs + [combined]:
        cost[~E_valid] = 0.
        cost[:, ~P_valid] = np.inf
        # The measured product outside this span is an immutable boundary.
        outside = np.flatnonzero(E_valid & ~span_mask)
        cost[outside] = np.inf
        cost[outside, product_path[outside]] = 0.
    paths = [dp_path(cost, E_valid, P_valid, max_speed=max_speed, direction_policy=False)
             for cost in costs + [combined]]
    paths = [np.where(span_mask, p, product_path) for p in paths]
    rows = np.flatnonzero(span_valid)
    def gain(cost, candidate):
        before, after = cost[rows, pre_path[rows]], cost[rows, candidate[rows]]
        if not np.isfinite(before).all() or not np.isfinite(after).all():
            return -np.inf
        return float((before.mean() - after.mean()) / max(float(before.mean()), 1e-12))
    ga, gb = gain(costs[1], paths[0]), gain(costs[0], paths[1])
    candidate_spans = near_hold_spans(combined, paths[2], span_valid, D, q0)
    response = respond_near_hold(combined, paths[2], span_valid, candidate_spans)
    response = np.where(span_mask, response, product_path)
    if not local_motion_candidate_accepted(pre_path, paths[0], paths[1], paths[2], span_valid,
                                           ga, gb, candidate_spans, response):
        return product_path, dict(diag, reason='independent_tiles_disagree')
    steps = np.diff(response[E_valid])
    gaps = np.diff(np.flatnonzero(E_valid))
    if np.any(steps < 0) or np.any(steps > max_speed * gaps):
        return product_path, dict(diag, reason='span_boundary')
    if any(local_motion_has_blend(E_pixels, P_pixels, p, E_valid) for p in (pre_path, response)):
        return product_path, dict(diag, reason='interpolation_evidence')
    detail = dict(active_cells=int(len(active)), cell_count=int(len(weights)),
                  gain_a_on_b=ga, gain_b_on_a=gb, span=[int(span['t0']), int(span['t1'])])
    candidate_spans = [dict(s, local_motion_retry=detail) for s in candidate_spans]
    retained = [s for s in spans if int(s['t1']) < int(span['t0']) or int(s['t0']) > int(span['t1'])]
    return response, dict(detail, adopted=True, reason='independent_motion_tiles',
                          spans=sorted(retained + candidate_spans, key=lambda s: s['t0']), costs=combined)


def _static_precision_context_allowed(opt, path, E_valid, track=None, split=None, tc=None,
                                   pins=None, hints=None, exclude=None, region=None, cuts=()):
    """Only polish a trusted static geometry with no competing timing authority."""
    if (track is not None or tc is not None or pins or hints or cuts or region is not None or
            (split and split.get('split')) or opt.get('note') == 'identity' or
            opt.get('region', 'full') != 'full' or opt.get('rmask') is not None):
        return False
    if exclude is not None and np.asarray(exclude, bool).any():
        return False
    if len(path) != len(E_valid) or int(np.count_nonzero(E_valid)) < 32:
        return False
    values = np.asarray(path, float)
    valid = np.asarray(E_valid, bool)
    if not np.isfinite(values).all() or np.any(np.diff(values[valid]) < 0):
        return False
    if not _static_retry_optical_valid(opt) or abs(float(opt['s']) - 1.0) < .05:
        return False
    score = opt.get('score_multi')
    score = opt.get('score', 0.0) if score is None else score
    return bool(np.isfinite(score) and score >= .985)


def static_precision_retry_allowed(opt, path, E_valid, track=None, split=None, tc=None,
                                   pins=None, hints=None, exclude=None, region=None, cuts=()):
    """Preserve the original short-shift policy, including genuine repeat runs."""
    return bool(_static_precision_context_allowed(opt, path, E_valid, track, split, tc,
                    pins, hints, exclude, region, cuts) and
                _near_hold_curve_shape(np.asarray(path, float), np.asarray(E_valid, bool))[1] < 4)


def static_ambiguity_retry_allowed(opt, path, valid, spans, probe, **context):
    """Only challenge one unresolved span under measured static geometry."""
    if not (_static_precision_context_allowed(opt, path, valid, **context) and
            static_precision_probe_allowed(probe) and np.asarray(valid, bool).all()):
        return False
    if len(spans) != 1:
        return False
    span = spans[0]
    start, end = int(span['t0']), int(span['t1'])
    return bool(span.get('tier') == 'ambiguous' and not span.get('curve_retry') and not span.get('pinned') and
                not span.get('near_cut') and not span.get('tc') and
                0 <= start <= end < len(path) and end - start >= 3 and
                len(path) - (end - start + 1) >= 32)


def static_ambiguity_candidate(edit, plate, path, mask, valid, pvalid, opt, spans, max_speed=16):
    """Fit geometry outside ambiguity; A proposes timing and B/C can only veto.

    The caller must rematch production costs and revalidate near-hold, cuts,
    interpolation and output geometry before adopting this image-only proposal.
    """
    old = np.asarray(path).copy()
    valid, pvalid, mask = np.asarray(valid, bool), np.asarray(pvalid, bool), np.asarray(mask, bool)
    rejected = dict(adopted=False, reason='input')
    if (old.ndim != 1 or old.shape != valid.shape or len(old) != len(edit) or
            pvalid.shape != (len(plate),) or mask.shape != edit.shape[1:] or
            not valid.all() or not np.isfinite(old).all() or len(old) < 32 or
            np.any(old != np.floor(old)) or np.any(old < 0) or np.any(old >= len(plate)) or
            np.any(np.diff(old) < 0) or len(spans) != 1):
        return dict(opt), old, rejected
    old = old.astype(int)
    if not pvalid[old].all():
        return dict(opt), old, rejected
    start, end = int(spans[0]['t0']), int(spans[0]['t1'])
    if not 0 <= start <= end < len(old) or end - start < 3:
        return dict(opt), old, rejected
    heldout = np.zeros(len(old), bool)
    heldout[start:end + 1] = True
    fit_valid = valid & ~heldout
    if fit_valid.sum() < 32:
        return dict(opt), old, rejected
    polished, geometry = static_precision_candidate(edit, plate, old, mask, fit_valid, pvalid, opt)
    rejected = dict(adopted=False, reason='geometry', geometry=geometry)
    if not geometry.get('adopted'):
        return dict(opt), old, rejected
    warped, covered = warp_plate_stack(plate, polished, *edit.shape[1:])
    common = mask & covered & _coverage(opt, *edit.shape[1:], *plate.shape[1:])
    ed, pd = to_display(edit).reshape(len(edit), -1), to_display(warped).reshape(len(plate), -1)
    cells = []
    height, width = mask.shape
    for y in range(0, height, CELL):
        for x in range(0, width, CELL):
            tile = np.zeros_like(common)
            tile[y:y + CELL, x:x + CELL] = True
            pixels = np.flatnonzero(tile & common)
            if len(pixels) >= max(16, CELL * CELL // 4) and np.median(np.std(ed[:, pixels], axis=1)) >= 1e-4:
                cells.append(pixels)
    if len(cells) < 9:
        return dict(opt), old, dict(rejected, reason='signal')
    costs, paths = [], []
    for group in range(3):
        pixels = np.concatenate(cells[group::3])
        a, b = rank_rows(ed[:, pixels]), rank_rows(pd[:, pixels])
        a -= a.mean(axis=1, keepdims=True)
        b -= b.mean(axis=1, keepdims=True)
        a /= np.maximum(np.linalg.norm(a, axis=1, keepdims=True), 1e-8)
        b /= np.maximum(np.linalg.norm(b, axis=1, keepdims=True), 1e-8)
        cost = np.maximum(0.0, 1.0 - a @ b.T)
        cost[:, ~pvalid] = np.inf
        costs.append(cost)
        paths.append(dp_path(cost, valid, pvalid, max_speed=max_speed, direction_policy=False))
    rows = np.arange(len(old))
    proposed = np.asarray(paths[0], int)
    keep = (paths[1] == proposed) & (paths[2] == proposed)
    for cost in costs[1:]:
        keep &= cost[rows, proposed] <= cost[rows, old] + 1e-7
    proposed = np.where(keep, proposed, old)
    changed = proposed != old
    shift = np.abs(proposed - old)
    large = shift > 4
    rejected = dict(rejected, reason='timing', active_cells=len(cells), changed_frames=int(changed.sum()))
    if (not large.any() or np.any(large & ~heldout) or shift.max() > NH_K or
            np.any(np.diff(proposed) < 0) or np.any(np.diff(proposed) > max_speed)):
        return dict(opt), old, rejected
    gains = []
    for cost in costs[1:]:
        before, after = cost[rows[changed], old[changed]], cost[rows[changed], proposed[changed]]
        gain = float((before.mean() - after.mean()) / max(float(before.mean()), 1e-12))
        if not np.isfinite(gain) or gain < .05:
            return dict(opt), old, dict(rejected, reason='weak_validation_gain')
        gains.append(gain)
    return polished, proposed, dict(adopted=True, reason='independent_temporal_tiles',
        geometry=geometry, active_cells=len(cells), changed_frames=int(changed.sum()),
        max_shift=int(shift.max()), gains=gains, span=[start, end])


def static_ambiguity_blend_mask(changed, gains, fractions):
    """Strong fractional evidence or at least three coherent weak blend votes."""
    changed = np.asarray(changed, bool)
    gains, fractions = np.asarray(gains), np.asarray(fractions)
    interior = (changed & np.isfinite(gains) & np.isfinite(fractions) &
                (np.minimum(fractions, 1 - fractions) >= SUB_FRAC))
    out = slow_evidence_mask(changed, interior & (gains >= SUB_GAIN))
    weak = np.flatnonzero(interior & (gains >= SLOW_BLEND_GAIN))
    if len(weak):
        for group in np.split(weak, np.flatnonzero(np.diff(weak) > 2) + 1):
            if len(group) >= 3:
                out[group] = True
    return out


def static_ambiguity_blend_flags(edit_pixels, plate_pixels, before, candidate, valid, pvalid):
    """Check old/new adjacent pairs on identical geometry, pixels and tone mapping."""
    valid, pvalid = np.asarray(valid, bool), np.asarray(pvalid, bool)
    before, candidate = np.asarray(before, int), np.asarray(candidate, int)
    edit, plate = to_display(edit_pixels), to_display(plate_pixels)
    edit = fit_tone_lut(edit[valid], plate[candidate[valid]])(edit)
    zedit = _z(edit)
    changed = valid & (before != candidate)
    gains, fractions = np.zeros(len(before)), np.zeros(len(before))
    alphas = np.linspace(0, 1, 21)
    for t in np.flatnonzero(changed):
        pool = sorted({int(p + d) for p in (before[t], candidate[t]) for d in (-1, 0, 1)
                       if 0 <= p + d < len(plate) and pvalid[p + d]})
        if len(pool) < 2:
            continue
        integer = float(np.min(np.mean((_z(plate[pool]) - zedit[t]) ** 2, axis=1)))
        best, fraction = integer, 0.
        for a, b in zip(pool, pool[1:]):
            if b != a + 1:
                continue
            blends = (1 - alphas[:, None]) * plate[a] + alphas[:, None] * plate[b]
            costs = np.mean((_z(blends) - zedit[t]) ** 2, axis=1)
            k = int(np.argmin(costs))
            if costs[k] < best:
                best, fraction = float(costs[k]), float(alphas[k])
        gains[t], fractions[t] = (integer - best) / max(integer, 1e-6), fraction
    return static_ambiguity_blend_mask(changed, gains, fractions)


def static_precision_probe_allowed(probe):
    """A rejected moving track is not evidence of static geometry."""
    if not probe or probe.get('animated') or probe.get('curve') is None:
        return False
    curve = np.asarray(probe['curve'], float)
    if curve.ndim != 2 or curve.shape[1] != 3 or len(curve) < 6 or not np.isfinite(curve).all():
        return False
    return bool(np.ptp(curve[:, 0]) <= .012 and
                max(np.ptp(curve[:, 1]), np.ptp(curve[:, 2])) <= .005 and
                not track_trial_ok(probe))


def static_precision_rematch_accept(before, after, path, candidate, valid,
                                    mask, candidate_mask, cuts, max_shift=4):
    """Require better central cost without sacrificing tails or timing continuity."""
    valid = np.asarray(valid, bool)
    before, after = np.asarray(before)[valid], np.asarray(after)[valid]
    old, new = np.asarray(path), np.asarray(candidate)
    if (cuts or len(before) < 32 or not np.array_equal(mask, candidate_mask) or
            not np.isfinite(before).all() or not np.isfinite(after).all() or
            not np.isfinite(new).all() or np.any(np.diff(new[valid]) < 0)):
        return False
    return bool(np.max(np.abs(new - old)) <= max_shift and
                np.median(after) <= .98 * np.median(before) and
                np.percentile(after, 90) <= np.percentile(before, 90) + 1e-7)


def static_precision_holdout_accept(before, after):
    """A better median cannot hide a worse independent validation anchor."""
    before, after = np.asarray(before, float), np.asarray(after, float)
    if before.ndim != 1 or before.shape != after.shape or len(before) < 3:
        return False
    if not (np.isfinite(before).all() and np.isfinite(after).all()):
        return False
    delta = after - before
    return bool(np.median(delta) >= 2e-4 and delta.min() >= -1e-5 and
                int((delta > 1e-4).sum()) >= max(2, int(np.ceil(.75 * len(delta)))))


def static_precision_temporal_accept(costs, path, candidate, path_a, path_b, valid):
    """Independent tile votes may move one frame only if the original metric agrees."""
    valid = np.asarray(valid, bool)
    paths = [np.asarray(p) for p in (path, candidate, path_a, path_b)]
    if not valid.size or not valid.all() or any(p.shape != valid.shape or not np.isfinite(p).all() for p in paths):
        return False
    old, new, pa, pb = paths
    changed = valid & (new != old)
    if (not np.array_equal(new[changed], pa[changed]) or not np.array_equal(new[changed], pb[changed]) or
            np.any(np.diff(new[valid]) < 0) or np.max(np.abs(new - old)) > 1):
        return False
    old_accel, new_accel = np.abs(np.diff(old[valid], n=2)), np.abs(np.diff(new[valid], n=2))
    # Integer ramp quantization may add unit step changes without a larger spike.
    if (new_accel.max(initial=0) > old_accel.max(initial=0) or
            _near_hold_curve_shape(new, valid)[1] > _near_hold_curve_shape(old, valid)[1]):
        return False
    rows = np.flatnonzero(valid)
    before, after = costs[rows, old[rows]], costs[rows, new[rows]]
    changed = new[rows] != old[rows]
    return bool(changed.any() and np.isfinite(before).all() and np.isfinite(after).all() and
                np.all(after[changed] <= before[changed] + 1e-7) and
                after.sum() < before.sum() - 1e-7)


def static_precision_temporal_candidate(Ef, Pf, U, path, valid, pvalid, cells, max_speed=16):
    """Cross-check the polished geometry with rank correlation in disjoint cells."""
    order, starts, counts, keep = cells
    groups = [[], []]
    for i, (start, count, kept) in enumerate(zip(starts, counts, keep)):
        if kept:
            groups[i % 2].extend(order[start:start + count])
    if min(map(len, groups)) < 64:
        return path
    groups.append(np.arange(Ef.shape[1]))
    paths = []
    rows = np.arange(len(path))
    median = np.median(U[rows, path][valid])
    for pixels in groups:
        ee, pp = Ef[:, pixels].copy(), Pf[:, pixels].copy()
        ee -= ee.mean(axis=1, keepdims=True)
        pp -= pp.mean(axis=1, keepdims=True)
        ee /= np.maximum(np.linalg.norm(ee, axis=1, keepdims=True), 1e-8)
        pp /= np.maximum(np.linalg.norm(pp, axis=1, keepdims=True), 1e-8)
        cost = np.maximum(0., 1. - ee @ pp.T)
        cost *= median / max(1e-8, np.median(cost[rows, path][valid]))
        cost[~np.isfinite(U)] = np.inf
        cost[:, ~pvalid] = np.inf
        cost[~valid] = 0.
        paths.append(dp_path(cost, valid, pvalid, max_speed=max_speed, direction_policy=False))
    supported = (valid & (paths[0] == paths[2]) & (paths[1] == paths[2]) &
                 (np.abs(paths[2] - path) <= 1) &
                 (U[rows, paths[2]] <= U[rows, path] + 1e-7))
    candidate = np.where(supported, paths[2], path)
    if np.any(np.diff(candidate[valid]) > max_speed * np.diff(np.flatnonzero(valid))):
        return path
    return (candidate if static_precision_temporal_accept(U, path, candidate, paths[0], paths[1], valid)
            else path)


def static_precision_score(E_lum, P_lum, path, mask, valid, opt):
    """Refresh the existing multi-pair NCC field without fitting geometry again."""
    vt = np.flatnonzero(valid)
    if not len(vt):
        return -1.0
    sel = vt[np.linspace(0, len(vt) - 1, min(8, len(vt))).astype(int)]
    return _score_pairs(E_lum[sel], mask, blur121(P_lum[np.asarray(path)[sel]]),
                        opt['s'], opt['tx'], opt['ty'], opt['flop'])


def static_precision_candidate(E_lum, P_lum, path, mask, E_valid, P_valid, opt):
    """Bounded spatial polish using disjoint fitting and validation anchors.

    A temporal neighbourhood avoids reinforcing a one-frame error in the old
    path. Only the eight anchors and at most forty valid source frames are
    downsampled; no extra render or external model is needed. This proposes
    geometry only. The caller must rematch and validate the resulting path.
    """
    unchanged = dict(opt)
    if opt.get('note') == 'identity':
        return unchanged, dict(adopted=False, reason='identity')
    anchors = np.asarray([t for t, _ in qc_refine_anchor_pairs(
        E_lum, path, E_valid, max_samples=8)], int)
    if len(anchors) < 6:
        return unchanged, dict(adopted=False, reason='too_few_anchors')
    neighborhoods = [np.asarray([p for p in range(max(0, int(path[t]) - 2),
                        min(len(P_lum), int(path[t]) + 3)) if P_valid[p]], int) for t in anchors]
    if any(not len(ids) for ids in neighborhoods):
        return unchanged, dict(adopted=False, reason='empty_neighborhood')
    ids = np.unique(np.concatenate(neighborhoods))
    neighborhoods = [np.searchsorted(ids, local) for local in neighborhoods]
    edit = down2(E_lum[anchors])
    plate = blur121(down2(P_lum[ids]))
    active_mask = down2(np.asarray(mask, np.float32)) > .99
    height, width = edit.shape[1:]
    origin = np.asarray([opt['s'], opt['tx'], opt['ty']], np.float64)
    limits = np.asarray([.006, 1.0 / E_lum.shape[-1], 1.0 / E_lum.shape[-1]])
    # Every hypothesis sees the same pixels, including the original transform.
    # Otherwise moving a difficult edge out of coverage can fake an NCC gain.
    for ds in (-limits[0], limits[0]):
        for dx in (-limits[1], limits[1]):
            for dy in (-limits[2], limits[2]):
                bound = dict(opt, s=origin[0] + ds, tx=origin[1] + dx, ty=origin[2] + dy)
                active_mask &= _coverage(bound, height, width, plate.shape[1], plate.shape[2])
    if (active_mask.sum() < 64 or not np.isfinite(edit).all() or not np.isfinite(plate).all()
            or np.max(np.std(edit[:, active_mask], axis=1)) < 1e-6):
        return unchanged, dict(adopted=False, reason='insufficient_signal')
    params = origin.copy()
    train, heldout = np.arange(0, len(anchors), 2), np.arange(1, len(anchors), 2)
    cache = {}

    def scores(prm):
        key = tuple(np.round(prm, 9))
        if key not in cache:
            xp, yp = warp_coords(height, width, plate.shape[1], plate.shape[2],
                                 prm[0], prm[1], prm[2], bool(opt.get('flop')))
            warped, covered = bilinear(plate, xp, yp)
            active = active_mask
            if np.any(active & ~covered):
                cache[key] = np.full(len(anchors), -1.0, np.float32)
            else:
                er, pr = rank_rows(edit[:, active]), rank_rows(warped[:, active])
                er -= er.mean(axis=1, keepdims=True)
                pr -= pr.mean(axis=1, keepdims=True)
                denom = np.linalg.norm(er, axis=1)[:, None] * np.linalg.norm(pr, axis=1)[None, :] + 1e-9
                ncc = (er @ pr.T) / denom
                cache[key] = np.asarray([ncc[i, local].max() for i, local in enumerate(neighborhoods)])
        return cache[key]

    before = scores(origin)
    best = float(np.median(before[train]))
    for ds, dt in ((.002, .25), (.001, .125), (.0005, .0625), (.00025, .03125)):
        for axis, step in enumerate((ds, dt / width, dt / width)):
            trials = []
            for sign in (-1, 1):
                trial = params.copy()
                trial[axis] += sign * step
                trial_opt = dict(opt, s=trial[0], tx=trial[1], ty=trial[2])
                if (abs(trial[axis] - origin[axis]) <= limits[axis] + 1e-12 and
                        _static_retry_optical_valid(trial_opt)):
                    trials.append((float(np.median(scores(trial)[train])), trial))
            if trials:
                value, trial = max(trials, key=lambda item: item[0])
                if value > best + 1e-7:
                    best, params = value, trial
    after = scores(params)
    train_gain = best - float(np.median(before[train]))
    heldout_gain = float(np.median(after[heldout] - before[heldout]))
    adopted = train_gain >= 2e-4 and static_precision_holdout_accept(before[heldout], after[heldout])
    adopted = adopted and _static_retry_optical_valid(dict(opt, s=params[0], tx=params[1], ty=params[2]))
    candidate = dict(opt)
    if adopted:
        candidate.update(s=float(params[0]), tx=float(params[1]), ty=float(params[2]))
    return candidate, dict(adopted=bool(adopted), reason='heldout_gain' if adopted else 'insufficient_heldout_gain',
                          anchors=anchors.tolist(), candidate_frames=len(ids), evaluations=len(cache),
                          train_gain=train_gain, heldout_gain=heldout_gain,
                          before_heldout=before[heldout].tolist(), after_heldout=after[heldout].tolist())


# Frozen A3 spatial retry
# G3 thresholds .02 translation, .50 absolute log-scale, 1.20 mean speed
# .10 speed deviation were selected on development data (2026-11-01)
# not on the independent validation set. V3 approval is unchanged.
def _a3_gate_features(result, analysis_box=None, edit_aspect=1.0):
    """Fixed G3 features in full-EDIT coordinates, without truth metadata."""
    optical = result.get('optical') or {}
    scale = float(optical.get('s', np.nan))
    tx = float(optical.get('tx', np.nan))
    ty = float(optical.get('ty', np.nan))
    if analysis_box is not None:
        x0, y0, x1, y1 = [float(value) for value in analysis_box]
        width = x1 - x0
        scale = width * scale
        tx = width * tx + (x0 + x1) * 0.5 - 0.5
        ty = width * ty + ((y0 + y1) * 0.5 - 0.5) * float(edit_aspect)
    path = np.asarray(result.get('path'), np.float64)
    delta = np.diff(path) if path.ndim == 1 else np.asarray([], np.float64)
    return {'translation': math.hypot(tx, ty), 'log_scale_deviation': abs(math.log(scale)) if scale > 0 else np.inf, 'mean_path_speed': abs(float(delta.mean())) if delta.size else 0.0, 'path_speed_std': float(delta.std()) if delta.size else 0.0}

def _a3_fixed_g3(features):
    """The fixed development G3 rule; independent validation never tunes it."""
    values = np.asarray(list(features.values()), np.float64)
    if not np.isfinite(values).all():
        return False
    return bool(
        features['translation'] >= 0.02  # Development G3: image-derived translation.
        or (features['log_scale_deviation'] >= 0.50  # Development G3: scale deviation.
            and features['mean_path_speed'] > 1.20  # Development G3: mean speed.
            and features['path_speed_std'] > 0.10))  # Development G3: speed variation.

def _a3_input_valid(result, edit_frames):
    optical = result.get('optical') or {}
    try:
        geometry = np.asarray([optical['s'], optical['tx'], optical['ty']], np.float64)
        path = np.asarray(result.get('path'), np.float64)
        edit_valid = np.asarray(result.get('E_valid'), bool)
        plate_valid = np.asarray(result.get('P_valid'), bool)
    except (KeyError, TypeError, ValueError) as exc:
        return (False, 'malformed input: ' + type(exc).__name__)
    if geometry.shape != (3,) or not np.isfinite(geometry).all() or geometry[0] <= 0:
        return (False, 'invalid geometry')
    if path.shape != (edit_frames,) or not np.isfinite(path).all():
        return (False, 'invalid path')
    if edit_valid.shape != (edit_frames,) or not edit_valid.all():
        return (False, 'invalid EDIT frames')
    if plate_valid.ndim != 1 or not len(plate_valid) or (not plate_valid.all()):
        return (False, 'invalid PLATE frames')
    if path.size and (path.min() < 0 or path.max() >= len(plate_valid)):
        return (False, 'path outside PLATE range')
    return (True, 'ok')

def _a3_tc_adopted(result):
    """True when burn-in TC actually shaped this result; a rejected or unused TC is not authority."""
    info = result.get('tc') or {}
    if info.get('forced') or info.get('mode') in ('first', 'hint', 'increment_mismatch'):
        return True
    return not info.get('mode') and (result.get('tc_plan') or {}).get('mode') in ('first', 'hint')


def _a3_authority_guard(kwargs, result):
    if kwargs.get('tc'):
        return 'TC authority'
    if kwargs.get('pins'):
        return 'user pins'
    if kwargs.get('hints'):
        return 'timing hints'
    if kwargs.get('region') is not None:
        return 'manual ROI'
    if np.asarray(kwargs.get('exclude', ()), bool).any():
        return 'excluded frames'
    if kwargs.get('detect_split'):
        return 'split mode'
    if bool((result.get('track') or {}).get('animated')):
        return 'animated geometry'
    if (result.get('split') or {}).get('split'):
        return 'detected split'
    return None

def _a3_direction(path):
    values = np.asarray(path, np.float64)
    delta = np.diff(values)
    moving = delta[np.abs(delta) > 1e-09]
    return int(np.sign(np.median(moving))) if len(moving) else 0

def _a3_event_positions(items):
    """Return local event positions, failing closed on an unknown shape."""
    positions = set()
    for item in items or []:
        value = item.get('t') if isinstance(item, dict) else item
        if value is None:
            return None
        try:
            position = int(value)
        except (TypeError, ValueError, OverflowError):
            return None
        if isinstance(value, (float, np.floating)) and (not np.isfinite(value)):
            return None
        positions.add(position)
    return positions

def _a3_candidate_guard(baseline, candidate):
    if candidate is None:
        return (False, 'candidate returned None')
    valid, reason = _a3_input_valid(candidate, len(np.asarray(baseline['path'])))
    if not valid:
        return (False, reason)
    if bool((candidate.get('track') or {}).get('animated')):
        return (False, 'candidate animated geometry')
    if (candidate.get('split') or {}).get('split'):
        return (False, 'candidate split')
    if bool((candidate.get('optical') or {}).get('flop')) != bool((baseline.get('optical') or {}).get('flop')):
        return (False, 'candidate changed flop')
    baseline_cuts = _a3_event_positions(baseline.get('cuts'))
    candidate_cuts = _a3_event_positions(candidate.get('cuts'))
    if baseline_cuts is None or candidate_cuts is None:
        return (False, 'malformed cut positions')
    if not candidate_cuts.issubset(baseline_cuts):
        return (False, 'candidate added cuts')
    baseline_reversals = _a3_event_positions(baseline.get('reversals'))
    candidate_reversals = _a3_event_positions(candidate.get('reversals'))
    if baseline_reversals is None or candidate_reversals is None:
        return (False, 'malformed reversal positions')
    if not candidate_reversals.issubset(baseline_reversals):
        return (False, 'candidate added reversals')
    old_direction = _a3_direction(baseline.get('path'))
    new_direction = _a3_direction(candidate.get('path'))
    if old_direction and new_direction and (old_direction != new_direction):
        return (False, 'candidate changed direction')
    return (True, 'ok')

def _a3_partition(mask, length):
    yy, xx = np.indices(mask.shape)
    tile = (yy // 16 + 2 * (xx // 16)) % 3
    groups = [mask & (tile == k) for k in range(3)]
    train = np.array([int((length - 1) * q) for q in (1 / 6, 1 / 2, 5 / 6)], int)
    val = np.array([i for i in np.linspace(0, length - 1, 7).astype(int) if np.min(abs(train - i)) > 2], int)
    return (groups, train, val)

def _a3_approval(base, candidate):
    base, candidate = (np.asarray(base), np.asarray(candidate))
    finite = bool(np.isfinite(base).all() and np.isfinite(candidate).all())
    gain = base - candidate
    accepted = finite and bool((gain >= -1e-06).all() and (gain.mean(axis=1) > 1e-06).all())
    return dict(accepted=accepted, minimum_gain=float(np.min(gain)), mean_gain_by_group=gain.mean(axis=1).tolist(), worse_observations=int((gain < -1e-06).sum()), observations=int(gain.size))

def _a3_mask_training_times(length, approval_times):
    return np.array([i for i in range(length) if all((abs(i - int(value)) > 2 for value in approval_times))], int)

def _a3_array_key(value):
    array = np.asarray(value)
    return (int(array.__array_interface__['data'][0]), array.shape, array.strides, array.dtype.str)

class _a3_ScoreCache:

    def __init__(self):
        self.values = {}
        self.edit_ranks = {}
        self.owners = {}

    # Keep immutable source arrays alive while pointer-based cache keys exist.
    def _pin(self, value):
        key = _a3_array_key(value)
        self.owners.setdefault(key, np.asarray(value))
        return key

    def score(self, edit, mask, plate, scale, tx, ty, flop):
        edit_key = self._pin(edit)
        mask_key = self._pin(mask)
        plate_key = self._pin(plate)
        key = (edit_key, mask_key, plate_key, float(scale), float(tx), float(ty), bool(flop))
        if key not in self.values:
            height, width = edit.shape[-2:]
            plate_height, plate_width = plate.shape[-2:]
            xp, yp = warp_coords(height, width, plate_height, plate_width, scale, tx, ty, flop)
            warped, valid = bilinear(plate, xp, yp)
            active = mask & valid
            if active.sum() < 0.3 * mask.sum():
                self.values[key] = -1.0
                return self.values[key]
            rank_key = (edit_key, active.tobytes())
            if rank_key not in self.edit_ranks:
                self.edit_ranks[rank_key] = rank_rows(edit[:, active])
            edit_rank = self.edit_ranks[rank_key].copy()
            plate_rank = rank_rows(warped[:, active])
            edit_rank -= edit_rank.mean(axis=1, keepdims=True)
            plate_rank -= plate_rank.mean(axis=1, keepdims=True)
            numerator = (edit_rank * plate_rank).sum(1)
            denominator = np.sqrt((edit_rank * edit_rank).sum(1) * (plate_rank * plate_rank).sum(1)) + 1e-09
            self.values[key] = float((numerator / denominator).mean())
        return self.values[key]

def _a3_optical_key(optical):
    return (float(optical['s']), float(optical['tx']), float(optical['ty']), bool(optical['flop']))

class _a3_CostCache:

    def __init__(self, plate, blurred_plate):
        self.plate = plate
        self.blurred_plate = blurred_plate
        self.warped = {}
        self.costs = {}

    def _warp(self, optical, height, width):
        key = (_a3_optical_key(optical), int(height), int(width))
        if key not in self.warped:
            hp, wp = self.plate.shape[-2:]
            xp, yp = warp_coords(height, width, hp, wp, optical['s'], optical['tx'], optical['ty'], optical['flop'])
            self.warped[key] = bilinear(self.blurred_plate, xp, yp)
        return self.warped[key]

    def matrix(self, edit_key, edit, mask, optical):
        warped, coverage = self._warp(optical, *edit.shape[1:])
        active = mask & coverage
        if active.sum() < 64:
            raise ValueError('insufficient tile coverage')
        key = (edit_key, active.tobytes(), _a3_optical_key(optical))
        if key not in self.costs:
            self.costs[key] = cost_matrix(rank_rows(edit[:, active]), rank_rows(warped[:, active]), _cells(active), np.ones(len(edit), bool))
        return self.costs[key]

def _a3_optimize_pair(score_cache, image, mask, blurred_plate, q, initial):
    params = [initial['s'], initial['tx'], initial['ty']]
    origin = np.array(params)
    width = image.shape[-1]
    steps = [0.01, 1.0 / width, 1.0 / width]
    minima = [0.0005, 0.05 / width, 0.05 / width]
    edit = image[None]
    plate = blurred_plate[q:q + 1]

    def value(candidate):
        return score_cache.score(edit, mask, plate, candidate[0], candidate[1], candidate[2], initial['flop'])
    current = value(params)
    for _ in range(48):
        better = False
        for axis in range(3):
            for sign in (1, -1):
                candidate = list(params)
                candidate[axis] += sign * steps[axis]
                if abs(candidate[axis] - origin[axis]) > (0.08 if axis == 0 else 0.05):
                    continue
                score = value(candidate)
                if score > current + 1e-06:
                    current, params, better = (score, candidate, True)
        if not better:
            if all((step <= minimum for step, minimum in zip(steps, minima))):
                break
            steps = [max(step * 0.5, minimum) for step, minimum in zip(steps, minima)]
    return (dict(s=params[0], tx=params[1], ty=params[2], flop=initial['flop']), current)

def _a3_refine_optical_pairs(score_cache, edit, mask, blurred_plate, pairs, optical, log, limits=None):
    if optical.get('note') == 'identity' or not pairs:
        return optical
    edit_indices = np.array([pair[0] for pair in pairs])
    plate_indices = np.array([pair[1] for pair in pairs])
    edit_pairs, plate_pairs = (edit[edit_indices], blurred_plate[plate_indices])
    params = [optical['s'], optical['tx'], optical['ty']]
    origin = list(params)
    flop = optical['flop']
    width = edit.shape[-1]

    def score(candidate):
        return score_cache.score(edit_pairs, mask, plate_pairs, candidate[0], candidate[1], candidate[2], flop)
    current = score(params)
    steps = [0.004, 0.5 / width, 0.5 / width]
    minima = [0.0003, 0.03 / width, 0.03 / width]
    for _ in range(200):
        improved = False
        for axis in range(3):
            for sign in (1, -1):
                trial = list(params)
                trial[axis] += sign * steps[axis]
                if limits is not None and abs(trial[axis] - origin[axis]) > limits[axis]:
                    continue
                value = score(trial)
                if value > current + 1e-06:
                    current, params, improved = (value, trial, True)
        if not improved:
            if all((step <= minimum for step, minimum in zip(steps, minima))):
                break
            steps = [max(step * 0.5, minimum) for step, minimum in zip(steps, minima)]
    result = dict(optical)
    result.update(s=params[0], tx=params[1], ty=params[2], score_multi=current)
    log('  multi-pair optical: s=%.4f tx=%.4f ty=%.4f ncc=%.3f' % (result['s'], result['tx'], result['ty'], current))
    return result

def _a3_propose(edit, plate, base_geometry, base_path, variant='a3', cancelled=None):
    """Return the same A3 hypotheses and decision using call-local caches."""
    _a3_check_cancelled(cancelled)
    started = time.monotonic()
    _, _, validation_times = _a3_partition(np.ones(edit.shape[1:], bool), len(edit))
    mask_times = _a3_mask_training_times(len(edit), validation_times) if variant == 'a3' else np.arange(len(edit))
    if len(mask_times) < 8:
        return dict(accepted=False, reason='fewer than eight mask-training frames', path=np.asarray(base_path).tolist(), hypotheses=[])
    mask = edit_static_mask(edit[mask_times])
    overlay, _ = overlay_mask(edit[mask_times], mask)
    mask &= ~overlay
    groups, train, validation = _a3_partition(mask, len(edit))
    if len(validation) < 2 or any((group.sum() < 64 for group in groups)):
        return dict(accepted=False, reason='insufficient independent approval coverage', path=np.asarray(base_path).tolist(), hypotheses=[])
    blurred = blur121(plate)
    score_cache = _a3_ScoreCache()
    cost_cache = _a3_CostCache(plate, blurred)
    hypotheses = []
    logs = []
    for anchor in train:
        _a3_check_cancelled(cancelled)
        valid = np.zeros(len(edit), bool)
        valid[anchor] = True
        initial = estimate_optical(edit, groups[0], valid, plate, np.ones(len(plate), bool), log=logs.append)
        centre = initial.get('anchor_plate', int(base_path[anchor]))
        search = range(max(0, centre - 12), min(len(plate), centre + 13), 2)
        best = None
        for plate_frame in search:
            optical, score = _a3_optimize_pair(score_cache, edit[anchor], groups[0], blurred, plate_frame, initial)
            if best is None or score > best['generation_score']:
                best = dict(anchor=int(anchor), anchor_plate=plate_frame, optical=optical, generation_score=score)
        hypotheses.append(best)
    edit_train = edit[train]
    edit_validation = edit[validation]
    if variant in ('a2', 'a3'):
        for candidate_index, candidate in enumerate(hypotheses):
            _a3_check_cancelled(cancelled)
            optical = candidate['optical']
            for iteration in range(3):
                _a3_check_cancelled(cancelled)
                matrix = cost_cache.matrix(('train', candidate_index, iteration), edit_train, groups[0], optical)
                selected = np.argmin(matrix, axis=1)
                pairs = list(zip(train.tolist(), selected.tolist()))
                optical = _a3_refine_optical_pairs(score_cache, edit, groups[0], blurred, pairs, optical, logs.append)
            candidate['optical'] = {key: optical[key] for key in ('s', 'tx', 'ty', 'flop')}
            matrix = cost_cache.matrix(('train-final', candidate_index), edit_train, groups[0], candidate['optical'])
            candidate['joint_generation_cost'] = float(np.min(matrix, axis=1).mean())
        hypotheses.sort(key=lambda candidate: candidate['joint_generation_cost'])
    generated_at = time.monotonic()
    base_path = np.asarray(base_path, int)
    baselines = [cost_cache.matrix(('validation-baseline', group_index), edit_validation, group, base_geometry)[np.arange(len(validation)), base_path[validation]] for group_index, group in enumerate(groups[1:], 1)]
    for candidate_index, candidate in enumerate(hypotheses):
        matrix = cost_cache.matrix(('full', candidate_index), edit, groups[0], candidate['optical'])
        path = dp_path(matrix, np.ones(len(edit), bool), np.ones(len(plate), bool))
        observed = [cost_cache.matrix(('validation', candidate_index, group_index), edit_validation, group, candidate['optical'])[np.arange(len(validation)), path[validation]] for group_index, group in enumerate(groups[1:], 1)]
        candidate['approval'] = _a3_approval(np.asarray(baselines), np.asarray(observed))
        candidate['path'] = path.tolist()
        candidate['approval_cost'] = np.asarray(observed).tolist()
    approved = next((candidate for candidate in hypotheses if candidate['approval']['accepted']), None)
    return dict(accepted=approved is not None, path=approved['path'] if approved else base_path.tolist(), optical=approved['optical'] if approved else base_geometry, train_times=train.tolist(), approval_times=validation.tolist(), mask_training_times=mask_times.tolist(), tile_pixels=[int(group.sum()) for group in groups], baseline_approval_cost=np.asarray(baselines).tolist(), generation_seconds=generated_at - started, seconds=time.monotonic() - started, hypotheses=hypotheses, logs=logs)

def _a3_sampled(curve):
    return np.floor(np.asarray(curve, np.float64)).astype(int)

def _a3_changed_spans(base, candidate):
    changed = _a3_sampled(base) != _a3_sampled(candidate)
    spans = []
    start = None
    for i, value in enumerate(changed.tolist() + [False]):
        if value and start is None:
            start = i
        elif not value and start is not None:
            spans.append((start, i))
            start = None
    return spans

def _a3_monotone_mix(base_curve, candidate_curve, use_candidate):
    """Mix two forward/reverse curves and fail closed to baseline on violations."""
    base = np.asarray(base_curve, np.float64)
    candidate = np.asarray(candidate_curve, np.float64)
    use_candidate = np.asarray(use_candidate, bool).copy()
    direction = 1 if np.median(np.diff(base)) >= 0 else -1
    for _ in range(len(base)):
        mixed = np.where(use_candidate, candidate, base)
        bad = np.where(direction * np.diff(mixed) < -1e-09)[0]
        if not len(bad):
            return (mixed, use_candidate, 0)
        touched = False
        for i in bad:
            for j in (i, i + 1):
                if use_candidate[j]:
                    use_candidate[j] = False
                    touched = True
        if not touched:
            return (base.copy(), np.zeros(len(base), bool), int(len(bad)))
    return (base.copy(), np.zeros(len(base), bool), len(base))

def _a3_variant_span_pareto(base_curve, candidate_curve, base_candidate_geo, candidate_candidate_geo):
    """V3: an entire changed span must dominate on every independent tile."""
    use = np.zeros(len(base_curve), bool)
    decisions = []
    gain = base_candidate_geo - candidate_candidate_geo
    for start, stop in _a3_changed_spans(base_curve, candidate_curve):
        span_gain = gain[:, start:stop]
        accepted = bool((span_gain.sum(axis=1) >= -1e-06).all() and (span_gain.mean(axis=1) > 1e-06).all())
        if accepted:
            use[start:stop] = True
        decisions.append({'start0': start, 'stop0_exclusive': stop, 'accepted': accepted, 'minimum_frame_tile_gain': float(span_gain.min()), 'sum_gain_by_tile': span_gain.sum(axis=1).tolist()})
    mixed, use, violations = _a3_monotone_mix(base_curve, candidate_curve, use)
    return (mixed, {'spans': decisions, 'accepted_frames': np.where(use)[0].tolist(), 'monotonicity_violations': violations})

def _a3_forced_path_guard(forced_path, frames, plate_frames, max_speed, jumps, user_pins, tc_pins):
    forced = np.asarray(forced_path)
    if forced.shape != (frames,) or not np.isfinite(forced).all():
        raise ValueError('forced path shape/non-finite')
    if not np.array_equal(forced, np.floor(forced)):
        raise ValueError('forced path must be integer')
    forced = forced.astype(int)
    if forced.min() < 0 or forced.max() >= plate_frames:
        raise ValueError('forced path outside plate')
    allowed_jumps = np.asarray(jumps, bool)
    if allowed_jumps.shape != (frames,):
        raise ValueError('jump mask shape')
    cap = min(max(1, int(max_speed)), 16)
    steps = np.abs(np.diff(forced))
    if np.any((steps > cap) & ~allowed_jumps[1:]):
        raise ValueError('forced path exceeds max speed')
    for label, pin_set in (('user', user_pins), ('resolved TC', tc_pins)):
        for frame, plate in pin_set.items():
            if 0 <= int(frame) < frames and int(forced[int(frame)]) != int(plate):
                raise ValueError('forced path violates ' + label + ' pin')
    return forced

def _a3_select_approved_result(baseline, candidate, seed_path, finalized):
    """Return one internally consistent result without score-based approval.

    Full baseline/candidate choices are returned atomically.  A mixed V3 path
    may use the regenerated tail only when its sampled output still equals the
    approved seed.  Otherwise the whole baseline result is the safe fallback.
    Fractional and slow/interpolated inputs remain outside this integer-only
    development fixture.
    """
    baseline_lookup = np.asarray(_a3_lookup(baseline), np.float64)
    candidate_lookup = np.asarray(_a3_lookup(candidate), np.float64)
    seed = np.asarray(seed_path, np.int64)
    has_fractional = any((np.any(np.abs(values - np.floor(values)) > 1e-09) for values in (baseline_lookup, candidate_lookup)))
    if has_fractional or baseline.get('slow') or candidate.get('slow'):
        return (baseline, 'baseline_fractional_or_slow_guard')
    baseline_path = np.floor(baseline_lookup).astype(int)
    candidate_path = np.floor(candidate_lookup).astype(int)
    if np.array_equal(seed, baseline_path):
        return (baseline, 'baseline_atomic')
    if np.array_equal(seed, candidate_path):
        return (candidate, 'candidate_atomic')
    finalized_path = np.floor(np.asarray(_a3_lookup(finalized), np.float64)).astype(int)
    if np.array_equal(seed, finalized_path):
        return (finalized, 'mixed_finalized')
    return (baseline, 'baseline_postcondition_mismatch')

def _a3_snapshot_state(values):
    """Own the candidate checkpoint before finalization mutates arrays/dicts."""
    import copy
    snapshot = {}
    for key, value in values.items():
        try:
            snapshot[key] = copy.deepcopy(value)
        except Exception:
            snapshot[key] = value
    return snapshot


def _a3_lookup(result):
    values = timewarp_output_lookup(result)
    if values is None:
        values = result.get('lookup', result['path'])
    return np.asarray(values, np.float64)


def _a3_path_costs(edit, plate, groups, optical, curve):
    indices = _a3_sampled(curve)
    if indices.min() < 0 or indices.max() >= len(plate):
        raise ValueError('curve leaves cached plate range')
    out = []
    for group in groups:
        warped, cov = warp_plate_stack(plate, optical, *edit.shape[1:])
        active = group & cov
        if active.sum() < 64:
            raise ValueError('insufficient tile coverage')
        matrix = cost_matrix(rank_rows(edit[:, active]), rank_rows(warped[:, active]),
                             _cells(active), np.ones(len(edit), bool))
        out.append(matrix[np.arange(len(edit)), indices])
    return np.asarray(out, np.float64)


def _a3_path_cost_pair(edit, plate, groups, optical, baseline_curve, candidate_curve):
    """Same V3 costs, with one warp and one cost matrix per tile group."""
    baseline_indices = _a3_sampled(baseline_curve)
    if baseline_indices.min() < 0 or baseline_indices.max() >= len(plate):
        raise ValueError('curve leaves cached plate range')
    matrices, baseline_values = [], []
    warped = None
    for group in groups:
        if warped is None:
            warped, cov = warp_plate_stack(plate, optical, *edit.shape[1:])
        active = group & cov
        if active.sum() < 64:
            raise ValueError('insufficient tile coverage')
        matrix = cost_matrix(rank_rows(edit[:, active]), rank_rows(warped[:, active]),
                             _cells(active), np.ones(len(edit), bool))
        baseline_values.append(matrix[np.arange(len(edit)), baseline_indices])
        matrices.append(matrix)
    baseline_cost = np.asarray(baseline_values, np.float64)
    # Preserve exception precedence: all baseline bounds, coverage and indexing
    # finish before the original second call's candidate range validation.
    candidate_indices = _a3_sampled(candidate_curve)
    if candidate_indices.min() < 0 or candidate_indices.max() >= len(plate):
        raise ValueError('curve leaves cached plate range')
    candidate_values = [matrix[np.arange(len(edit)), candidate_indices] for matrix in matrices]
    return baseline_cost, np.asarray(candidate_values, np.float64)


def _a3_v3_seed(edit, plate, baseline, candidate):
    approval_times = _a3_partition(np.ones(edit.shape[1:], bool), len(edit))[2]
    mask_times = _a3_mask_training_times(len(edit), approval_times)
    mask = edit_static_mask(edit[mask_times])
    overlay, _ = overlay_mask(edit[mask_times], mask)
    groups, _training, _validation = _a3_partition(mask & ~overlay, len(edit))
    baseline_curve, candidate_curve = _a3_lookup(baseline), _a3_lookup(candidate)
    geometry = {key: candidate['optical'][key] for key in ('s', 'tx', 'ty', 'flop')}
    baseline_cost, candidate_cost = _a3_path_cost_pair(
        edit, plate, groups, geometry, baseline_curve, candidate_curve)
    curve, decision = _a3_variant_span_pareto(baseline_curve, candidate_curve,
                                           baseline_cost, candidate_cost)
    return _a3_sampled(curve), decision


def _a3_finalize(edit, plate, baseline, candidate, checkpoint, solve_kwargs, event):
    """Approve one internally consistent result; never splice stale diagnostics."""
    if candidate is None:
        event['selection_reason'] = 'baseline_engine_or_candidate_guard'
        return baseline
    for label, result in (('baseline', baseline), ('candidate', candidate)):
        authority = _a3_authority_guard(solve_kwargs, result)
        if authority is not None:
            event['selection_reason'] = 'baseline_authority_guard: ' + authority
            return baseline
    started = time.monotonic()
    seed, decision = _a3_v3_seed(edit, plate, baseline, candidate)
    event['decision_seconds'] = time.monotonic() - started
    event['decision'] = decision
    baseline_lookup, candidate_lookup = _a3_lookup(baseline), _a3_lookup(candidate)
    has_fractional = any(np.any(np.abs(values - np.floor(values)) > 1e-9)
                         for values in (baseline_lookup, candidate_lookup))
    if has_fractional or baseline.get('slow') or candidate.get('slow'):
        event['selection_reason'] = 'baseline_fractional_or_slow_guard'
        return baseline
    if np.array_equal(seed, _a3_sampled(baseline_lookup)):
        event['selection_reason'] = 'baseline_atomic'
        return baseline
    if np.array_equal(seed, _a3_sampled(candidate_lookup)):
        event['selection_reason'] = 'candidate_atomic'
        return candidate
    if not checkpoint:
        event['selection_reason'] = 'baseline_missing_checkpoint'
        return baseline
    try:
        started = time.monotonic()
        finalized = _solve_finish(forced_path=seed, **_a3_snapshot_state(checkpoint))
        event['tail_seconds'] = time.monotonic() - started
    except Cancelled:
        raise
    except Exception as error:
        event['selection_reason'] = 'baseline_tail_error: ' + type(error).__name__
        return baseline
    if finalized is None:
        event['selection_reason'] = 'baseline_tail_none'
        return baseline
    selected, reason = _a3_select_approved_result(baseline, candidate, seed, finalized)
    event['selection_reason'] = reason
    event['selected_seed_exact'] = bool(np.array_equal(_a3_sampled(_a3_lookup(selected)), seed))
    return selected


def _a3_retry_text(res):
    if not res.get('a3_late_retry'):
        return ''
    return _t('리프레임 재검토로 결과 개선',
              'Reframe re-check improved the result')


def _a3_check_cancelled(cancelled):
    if cancelled is not None and cancelled():
        raise Cancelled(_t('공간 재시도 취소', 'Spatial retry cancelled'))


def _a3_retry_result(plate, edit, opts, ctx, excl, pin_frames, tcf, ef,
                     baseline, lo, timing, region=None):
    """Fixed G3/A3/V3 challenger after all established plate retries."""
    raw_guard = None
    if _a3_tc_adopted(baseline):
        raw_guard = 'TC authority'
    elif not opts.get('optical'):
        raw_guard = 'optical disabled'
    elif pin_frames:
        raw_guard = 'user pins'
    elif region is not None:
        raw_guard = 'manual ROI'
    elif np.asarray(excl if excl is not None else (), bool).any():
        raw_guard = 'excluded frames'
    elif opts.get('split'):
        raw_guard = 'split mode'
    elif bool((baseline.get('track') or {}).get('animated')):
        raw_guard = 'animated geometry'
    elif (baseline.get('split') or {}).get('split'):
        raw_guard = 'detected split'
    valid, _ = _a3_input_valid(baseline, len(edit))
    if raw_guard is not None or not valid:
        return baseline, lo, timing
    features = _a3_gate_features(baseline, getattr(ctx, 'a3_analysis_box', None),
                                 getattr(ctx, 'a3_edit_aspect', 1.0))
    event = dict(features=features, gate=_a3_fixed_g3(features),
                 baseline_cuts=list(baseline.get('cuts') or []),
                 baseline_reversals=list(baseline.get('reversals') or []), accepted=False)
    event_sink = getattr(ctx, 'a3_retry_events', None)
    if event_sink is not None:
        event_sink.append(event)
    if not event['gate']:
        event['reason'] = 'G3 false'
        return baseline, lo, timing
    cancelled = getattr(ctx, 'cancelled', None)
    _a3_check_cancelled(cancelled)
    started = time.monotonic()

    def finish(result):
        elapsed = dict(timing)
        elapsed['a3_retry_seconds'] = time.monotonic() - started
        if result is not baseline:
            elapsed['a3_late_retry'] = 1
        return result, lo, elapsed

    frames = list(range(lo, lo + len(baseline['P_valid'])))
    plate_stack, plate_valid = load_thumbs(plate, frames, W_PLATE, ctx.log)
    _a3_check_cancelled(cancelled)
    optical = baseline['optical']
    proposal = _a3_propose(edit, plate_stack,
                           {key: optical[key] for key in ('s', 'tx', 'ty', 'flop')},
                           baseline['path'], variant='a3', cancelled=cancelled)
    _a3_check_cancelled(cancelled)
    event['proposal_accepted'] = bool(proposal.get('accepted'))
    if not proposal.get('accepted'):
        event['reason'] = 'A3 proposal rejected'
        return finish(baseline)
    if bool((proposal.get('optical') or {}).get('flop')) != bool(optical.get('flop')):
        event['reason'] = 'proposal changed flop'
        return finish(baseline)

    def progress(index, count):
        if hasattr(ctx, 'progress'):
            ctx.progress(0.95 + 0.04 * index / max(count, 1))
        return bool(hasattr(ctx, 'cancelled') and ctx.cancelled())

    solve_kwargs = dict(P_valid_files=plate_valid, max_speed=opts.get('max_speed', 16),
                        detect_optical=opts['optical'], allow_flop=opts['flop'],
                        detect_slow_on=opts['slow'], log=ctx.log, progress=progress,
                        init_opt=proposal['optical'], detect_split=opts['split'],
                        track=opts['track'], region=region, exclude=excl,
                        pins={}, hints={}, tc=None, tc_track_values=None)
    checkpoint = {}
    candidate = solve(edit, plate_stack, _a3_checkpoint=checkpoint, **solve_kwargs)
    _a3_check_cancelled(cancelled)
    event['candidate_cuts'] = list((candidate or {}).get('cuts') or [])
    event['candidate_reversals'] = list((candidate or {}).get('reversals') or [])
    event['candidate_checkpoint_captured'] = bool(checkpoint)
    if candidate is not None:
        candidate = _a3_finalize(edit, plate_stack, baseline, candidate,
                                 checkpoint, solve_kwargs, event)
        event['finalizer_returned'] = candidate is not None
        event['candidate_cuts'] = list((candidate or {}).get('cuts') or [])
        event['candidate_reversals'] = list((candidate or {}).get('reversals') or [])
    _a3_check_cancelled(cancelled)
    if candidate is baseline:
        event['reason'] = 'finalizer retained baseline'
        return finish(baseline)
    accepted, reason = _a3_candidate_guard(baseline, candidate)
    if not accepted:
        event['reason'] = reason
        return finish(baseline)
    for key in ('tc_plan', 'tc'):
        if key in baseline:
            candidate[key] = baseline[key]
    candidate['a3_late_retry'] = dict(
        baseline_cuts=event['baseline_cuts'], candidate_cuts=event['candidate_cuts'],
        baseline_reversals=event['baseline_reversals'],
        candidate_reversals=event['candidate_reversals'], gate_features=features)
    event['accepted'], event['reason'] = True, 'accepted'
    ctx.log(_a3_retry_text(candidate))
    return finish(candidate)


def solve(E_lum, P_lum, P_valid_files=None, detect_optical=True, allow_flop=True,
          detect_slow_on=True, log=print, progress=None, init_opt=None,
          detect_split=False, track=True, region=None, exclude=None, pins=None, hints=None, tc=None, abort_if_same=None,
          max_speed=16, tc_track_values=None, _a3_checkpoint=None):
    """
    init_opt (reuse the stage 1 optical), candidate-column matching
    repeated split-composite detection, optical animation re-match
    E_lum (E,He,We) @W_EDIT luminance, P_lum (P,Hp,Wp) @W_PLATE luminance (linear)
    region: when the EDIT region where this plate will be used is known in advance (bool HxW)
    exclude (E,) bool: EDIT frames to leave out of matching (rotation / variable-scale segments, etc.)
            pins {t: p}: pins / hints {t: p}: lagging-TC hints (p is an index in terms of this P_lum)
    tc = dict(pins={t: p}, hints={t: (p, w)}): TC-first mode. For each cost matrix, tc_first_pins applies the image veto /
            offset check, then the remaining TCs go in as pins (forced) and unconfident TCs as weak hints. Unlike user pins,
            path discontinuities (jumps) are not allowed - only speed changes (if TC jumps, the path cannot keep the pins of that stretch and a split cut is suspected)
    """
    E, He, We = E_lum.shape
    P = P_lum.shape[0]
    manual_region = None
    if region is not None:
        manual_region = np.asarray(region, bool)
        if manual_region.shape != (He, We):
            raise ValueError('manual ROI mask shape %s does not match EDIT %s' %
                             (manual_region.shape, (He, We)))

    mask0 = edit_static_mask(E_lum)
    ovl, ovl_info = overlay_mask(E_lum, mask0)  # burn-ins / overlays are excluded before matching
    mask0 &= ~ovl
    if manual_region is not None:
        mask0 &= manual_region
    E_valid = valid_frames(E_lum, mask0)
    excl = np.zeros(E, bool) if exclude is None else np.asarray(exclude, bool).copy()
    E_valid &= ~excl  # user-excluded ranges
    pins = dict(pins or {})
    hints = dict(hints or {})
    # path discontinuities are allowed only when entering ranges the user excluded / pinned
    jumps = excl.copy()
    jumps[1:] |= excl[:-1]
    for t in pins:
        if 0 <= t < E:
            jumps[t] = True
    tcs = dict(pins=pins, hints=hints, info=None)  # pins / hints actually fed into the DP (TC-first included)
    if tc and tc.get('pins') and tc.get('interp') is None:  # TC frames with interpolated-slow evidence (subject to floor handling)
        tc = dict(tc, interp=tc_interp_frames(to_display(E_lum[:, mask0]), tc['pins']))
    P_valid = np.ones(P, bool) if P_valid_files is None else np.asarray(P_valid_files, bool)
    pm = np.ones(P_lum.shape[1:], bool)
    P_valid &= valid_frames(P_lum, pm) | (P_lum.reshape(P, -1).std(1) > 0)
    log('EDIT %d frames (valid %d, excluded %d), PLATE %d frames (valid %d), pins %d, TC hints %d'
        % (E, E_valid.sum(), excl.sum(), P, P_valid.sum(), len(pins), len(hints)))
    if ovl_info['frac'] > 0:
        log('[0] overlay mask: %.1f%% px (bars top %d / bottom %d rows, static edges %.1f%%)'
            % (100 * ovl_info['frac'], ovl_info['bars'][0], ovl_info['bars'][1], 100 * ovl_info['static']))

    # 1. Optical (reuse the stage 1 search result if there is one)
    if init_opt is not None:
        opt = dict(init_opt)
        log(_t('[1] optical: 1단계 결과 재사용 s=%.4f tx=%.4f ty=%.4f flop=%s', '[1] optical: reuse first-stage result s=%.4f tx=%.4f ty=%.4f flop=%s')
            % (opt['s'], opt['tx'], opt['ty'], opt['flop']))
        if detect_optical:
            opt = optical_identity_fullrate(E_lum, mask0, P_lum, P_valid, opt, log=log)
    else:
        log('[1] optical')
        opt = estimate_optical(E_lum, mask0, E_valid, P_lum, P_valid,
                               allow_flop=allow_flop, detect=detect_optical, log=log,
                               subregions=detect_split)  # only in split-composite mode
        # if the optical re-search gives the same solution, do not run the rest
        # if it is a list, compare for each (optical, ds, dt) - if equal to the optical reused from stage 1 it would merely repeat the first run
        # (test06_zoom_drift_ramp / test01_zoom_out_freeze: the newly found optical equals the stage 1 value to the fourth decimal place)
        same = abort_if_same if isinstance(abort_if_same, list) else \
            ([] if abort_if_same is None else [(abort_if_same, 0.01, 0.005)])
        if any(optical_same(opt, o, ds, dt) for o, ds, dt in same):
            log(_t('  optical: 기존 해와 같음 -> 재탐색 생략', '  optical: same as existing solution -> skip retry'))
            return None

    def match(opt, mask):
        Wp_img, cov = warp_plate_stack(P_lum, opt, He, We)
        m = mask & cov
        Ef = rank_rows(E_lum[:, m])
        Pf = rank_rows(Wp_img[:, m])
        cand = None
        if P > CAND_MIN_P:
            cand = coarse_candidates(E_lum, Wp_img, m, E_valid, P_valid)
            log('  candidate cols: %.1f%%' % (100.0 * cand.mean()))
        U = cost_matrix(Ef, Pf, _cells(m), E_valid, progress, cand)
        tc_apply(U)
        path = dp_path(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=SPEED_MAX, direction_policy=False)
        if cand is not None:
            # the speed-only path may pass outside the candidate columns -> compute the band around the path as well and solve again
            band = np.zeros_like(cand)
            for t in range(E):
                band[t, max(0, path[t] - CAND_WIN):path[t] + CAND_WIN + 1] = True
            band &= ~cand & P_valid[None]
            if band.any():
                U2 = cost_matrix(Ef, Pf, _cells(m), E_valid, None, band)
                U = np.where(band, U2, U)
                tc_apply(U)
                path = dp_path(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=SPEED_MAX, direction_policy=False)
        return U, path, Ef, Pf, m, Wp_img

    def tc_apply(U, image_path=None, validation_only=False):
        """ re-decide the TC-first pins / hints with this cost matrix (whenever optical / mask changes)"""
        if not tc:
            return
        pa, ha, info = tc_first_pins(U, E_valid, P_valid, tc, pins, image_path=image_path)
        if validation_only and info['mode'] not in ('increment_mismatch', 'offset', 'mismatch'):
            if tcs['info'] is not None:
                tcs['info'] = dict(tcs['info'], image_verified=info.get('image_verified') or {})
            return  # preserve established floor/nearest pins; new evidence only demotes jitter
        p2, h2 = dict(pins), dict(hints)
        if tc.get('mode') == 'hint':  # hint mode: TCs that passed the check become hints, not pins
            if info['mode'] == 'first':
                info['mode'] = 'hint'
                h2.update(pa)
            pa, ha = {}, {}
        p2.update(pa)
        h2.update(ha)
        if tcs['info'] is None or (info['mode'], info['used'], info['vetoed']) != (
                tcs['info']['mode'], tcs['info']['used'], tcs['info']['vetoed']):
            log(_t('  TC 우선: %s — 고정점 %d / 후보 %d (이미지 비토 %d, 어긋남 %.0f%%%s), 약한 힌트 %d', '  TC first: %s — %d anchors / %d candidates (image vetoes %d, disagreement %.0f%%%s), %d weak hints') % (
                info['mode'], info['used'] if info['mode'] == 'first' else 0, info['candidates'], info['vetoed'],
                100 * info['disagree_frac'], (_t(', 오프셋 %+d', ', offset %+d') % info['offset']) if info['offset'] is not None else '',
                info['weak']))
        tcs.update(pins=p2, hints=h2, info=info)


    def sample_pairs(path):
        vt = np.where(E_valid)[0]
        sel = vt[np.linspace(0, len(vt) - 1, min(8, len(vt))).astype(int)]
        return [(int(t), int(path[t])) for t in sel]

    # 2. First-pass matching (if the optical was found on a partial region, use that region)
    rmask = opt.get('rmask')
    log('[2] match pass 1%s' % ('' if rmask is None else ' (region %s)' % opt.get('region')))
    U, path, Ef, Pf, m, Wp_img = match(opt, mask0 if rmask is None else mask0 & rmask)

    # 3. Split-composite / temp-composite detection (full-frame residual map, repeated until the region converges)
    split = dict(split=False, frac=1.0, where='')
    split_region = None
    if detect_split:
        base = mask0.copy()
        Hp_, Wp_ = P_lum.shape[1], P_lum.shape[2]
        if rmask is None:
            Ef_f, Pf_f, m_f = Ef, Pf, m
        else:
            m_f = base & _coverage(opt, He, We, Hp_, Wp_)
            Ef_f, Pf_f = rank_rows(E_lum[:, m_f]), rank_rows(Wp_img[:, m_f])
        for it in range(3):
            reg, info = detect_split_region(Ef_f, Pf_f, path, E_valid, m_f)
            if not info['split']:
                break
            split = info
            prev = split_region
            split_region = reg
            log('[3] split detected (%d): %s %.0f%% (ratio %.1f)'
                % (it + 1, info['where'], info['frac'] * 100, info['ratio']))
            mask0 = base & reg
            if detect_optical:
                opt = estimate_optical(E_lum, mask0, E_valid, P_lum, P_valid, allow_flop=allow_flop,
                                       detect=True, log=log, subregions=False)
            U, path, Ef, Pf, m, Wp_img = match(opt, mask0)
            if prev is not None:
                iou = (prev & reg).sum() / float(max((prev | reg).sum(), 1))
                if iou > 0.95:
                    break
            m_f = base & _coverage(opt, He, We, Hp_, Wp_)
            Ef_f, Pf_f = rank_rows(E_lum[:, m_f]), rank_rows(Wp_img[:, m_f])
        if split_region is None and rmask is not None:
            log('[3] no split -> full frame rematch')
            U, path, Ef, Pf, m, Wp_img = match(opt, mask0)

    # 4. Burn-in residual mask + optical re-refinement + second pass
    newmask_feat, frac_masked = residual_mask(Ef, Pf, path, E_valid, m)
    log('[4] residual mask: %.1f%% px removed' % (frac_masked * 100))
    opt2 = refine_optical_pairs(E_lum, newmask_feat, P_lum, sample_pairs(path), opt, log=log)
    if init_opt is not None and opt2.get('score_multi', 1.0) < 0.5 and detect_optical \
            and not split['split']:
        log(_t('  optical 재탐색 (multi-pair ncc 낮음)', '  optical retry (low multi-pair NCC)'))
        opt = estimate_optical(E_lum, mask0, E_valid, P_lum, P_valid,
                               allow_flop=allow_flop, detect=True, log=log,
                               subregions=detect_split)
        U, path, Ef, Pf, m, Wp_img = match(opt, mask0)
        newmask_feat, frac_masked = residual_mask(Ef, Pf, path, E_valid, m)
        opt2 = refine_optical_pairs(E_lum, newmask_feat, P_lum, sample_pairs(path), opt, log=log)
    if frac_masked > 0 or opt2 is not opt:
        log('  match pass 2')
        U, path, Ef, Pf, m, Wp_img = match(opt2, newmask_feat & mask0)
    opt = opt2

    # suspected split cut: judged with a cost matrix that covers the whole plate (candidate columns) (animation re-match computes only around the path)
    cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
    if cuts:
        log(_t('[4] 분절컷 의심: %s', '[4] Possible cut: %s') % ', '.join('t=%d (%+d, excess %.1f%s)' % (
            c['t'], c['jump'], c['excess'], ', mismatch' if c['mismatch'] else '') for c in cuts))

    # 5. Optical animation (scale/reposition keys)
    trk = None
    t1 = None
    static_candidate = None
    static_candidate_used_times = []
    coords = None
    def track_fit(edit, mask, edit_valid, plate, plate_valid, image_path, optical, **kwargs):
        # TC proposes relative timing only. The normal optical held-out image
        # guard and subsequent tc_first_pins remain authoritative.
        if tc_track_values is not None:
            seed = tc_track_seed_path(tc_track_values, image_path, max_speed=max_speed)
            if seed is not None and np.all((seed >= 0) & (seed < len(plate))):
                proposed = track_optical(edit, mask, edit_valid, plate, plate_valid, seed, optical, **kwargs)
                if proposed.get('animated'):
                    return proposed
        return track_optical(edit, mask, edit_valid, plate, plate_valid, image_path, optical, **kwargs)

    if detect_optical and track:
        log('[5] optical track')
        t1 = track_fit(E_lum, m, E_valid, P_lum, P_valid, path, opt, log=log)
        if not t1['animated'] and t1.get('static_opt') is not None:
            sk = t1['static_opt']
            opt = dict(opt, s=float(sk[0]), tx=float(sk[1]), ty=float(sk[2]))
            opt.pop('note', None)
            U, path, Ef, Pf, m, Wp_img = match(opt, newmask_feat & mask0)
            opt = refine_optical_pairs(E_lum, m, P_lum, sample_pairs(path), opt, log=log)
            U, path, Ef, Pf, m, Wp_img = match(opt, newmask_feat & mask0)
            cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
            t1 = track_fit(E_lum, m, E_valid, P_lum, P_valid, path, opt, log=log)
        static_candidate = t1.get('static_candidate')
        static_candidate_used_times = t1.get('static_candidate_used_times') or []
        # trial acceptance: if the static-warp path is badly wrong in a zoom segment (zoom after a hold / 0.9 -> 1.6 ramp), the plate candidates of the verification frames
        # are wrong too and the guard cannot be passed (gained fraction 67-70 %). Re-match the animation once with the key-search curve, and accept only if the track
        # re-measured on that path passes the normal guard and the path cost drops to TRACK_TRIAL_COST times or less
        if not t1['animated'] and track_trial_ok(t1):
            # The static path may be off by tens of frames, so widen the key-search window and recompute the curve
            tw = track_fit(E_lum, m, E_valid, P_lum, P_valid, path, opt, log=log, win=2 * TRACK_WIN)
            cv = tw['curve'] if tw.get('curve') is not None else t1['curve']
            tt = dict(tw, s=cv[:, 0], tx=cv[:, 1], ty=cv[:, 2], animated=True)
            Ua, pa, ma, _ = match_animated(E_lum, P_lum, tt, m, E_valid, P_valid, path, pins=tcs['pins'],
                                           hints=tcs['hints'], jumps=jumps, max_speed=max_speed)
            ta = track_fit(E_lum, ma, E_valid, P_lum, P_valid, pa, opt, log=log)
            c_s = _path_cost_median(U, path, E_valid)
            c_a = _path_cost_median(Ua, pa, E_valid)
            ok_a = track_trial_accept(ta, c_s, c_a)
            log(_t('  optical track 시험 채택: 경로 비용 %.4f -> %.4f, 재트랙 %s (gain %.4f) -> %s', '  optical track trial accepted: path cost %.4f -> %.4f, retrack %s (gain %.4f) -> %s') % (
                c_s, c_a, 'ANIMATED' if ta['animated'] else 'static', float(ta.get('gain') or 0.0),
                _t('채택', 'accepted') if ok_a else _t('기각', 'rejected')))
            if ok_a:
                if not ta['animated']:
                    cv = ta['curve']
                    ta = dict(ta, s=cv[:, 0], tx=cv[:, 1], ty=cv[:, 2], animated=True, trial=True)
                t1, path = ta, pa
        if t1['animated']:
            trk = t1
            U, path, m2, coords = match_animated(E_lum, P_lum, trk, m, E_valid, P_valid, path,
                                                 progress=progress, pins=tcs['pins'], hints=tcs['hints'],
                                                 jumps=jumps, max_speed=max_speed)
            t2 = track_fit(E_lum, m2, E_valid, P_lum, P_valid, path, opt, log=log)
            if t2['animated']:
                trk = t2
                U, path, m2, coords = match_animated(E_lum, P_lum, trk, m, E_valid, P_valid,
                                                     path, progress=progress, pins=tcs['pins'], hints=tcs['hints'],
                                                     jumps=jumps, max_speed=max_speed)
            # if movement is animated, re-refine it with the final matching cost -> re-match (accepted only when the cost goes down)
            # cheaply once for tracks where only scale moves too (keys every 8 frames, plates +/-2): scale bias of the 64px NCC key search
            mv = max(np.ptp(trk['tx']), np.ptp(trk['ty'])) > 0.004
            for _it in range(6 if mv else TRACK_SREFINE_ITERS):
                tr3 = refine_track_cost(E_lum, P_lum, trk, m2, E_valid, P_valid, path, stride=4 if mv else 8,
                                        win=6 if mv else 2, log=log)
                if tr3 is trk:
                    break
                if True:
                    U3, path3, m3, coords3 = match_animated(E_lum, P_lum, tr3, m, E_valid, P_valid, path,
                                                            progress=progress, pins=tcs['pins'], hints=tcs['hints'], jumps=jumps,
                                                            max_speed=max_speed)
                    c_old = np.nanmedian(np.where(np.isfinite(U[np.arange(E), path]), U[np.arange(E), path], np.nan)[E_valid])
                    c_new = np.nanmedian(np.where(np.isfinite(U3[np.arange(E), path3]), U3[np.arange(E), path3], np.nan)[E_valid])
                    log('  track cost refine: median cost %.4f -> %.4f%s' % (c_old, c_new, '' if c_new < c_old else _t(' (기존 유지)', ' (keep existing)')))
                    if c_new < c_old:
                        trk, U, path, m2, coords = tr3, U3, path3, m3, coords3
                    if c_new > c_old * 0.98:
                        break
            m = m2
            # the TC offset / mismatch decision was also made with the static-warp cost - in a zoom segment the row minimum of the static warp lies in the wrong place
            # so correct TC counts as 'disagreeing' (false alarms on 7 variable-zoom clips, zero misreads). Re-check with the per-frame-warp cost, and if it passes
            # put in the TC pins and re-match the animation (the candidate window also includes the TC position)
            if tc and tcs['info'] is not None and tcs['info']['mode'] in ('offset', 'mismatch'):
                prev = tcs['info']
                p0 = np.asarray(path).copy()
                for t, q in (tc.get('pins') or {}).items():
                    if 0 <= t < E and 0 <= q < P:
                        p0[t] = q
                # compute around the TC position with the same warp too (inf outside the window around the path) so nothing passes without image evidence
                Uc = match_animated(E_lum, P_lum, trk, m, E_valid, P_valid, p0, jumps=jumps, max_speed=max_speed)[0]
                tc_apply(np.where(np.isfinite(Uc), Uc, U))
                log(_t('  TC 재검사 (프레임별 와프 비용): %s -> %s', '  TC recheck (per-frame warp cost): %s -> %s') % (prev['mode'], tcs['info']['mode']))
                if tcs['info']['mode'] in ('first', 'hint'):
                    U, path, m2, coords = match_animated(E_lum, P_lum, trk, m, E_valid, P_valid, p0,
                                                         progress=progress, pins=tcs['pins'], hints=tcs['hints'],
                                                         jumps=jumps, max_speed=max_speed)
                    m = m2
            # with variable scale, the split-cut decision from the static-warp cost is meaningless -> redo with the per-frame-warp cost
            # (matrix computed only for +/-25 around the path: a large jump is caught as a 'non-matching stretch' (another source))
            cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
            if cuts:
                log(_t('[5] 분절컷 의심 (애니메이션 와프): %s', '[5] Possible cut (animated warp): %s') % ', '.join('t=%d (%+d, excess %.1f%s)' % (
                    c['t'], c['jump'], c['excess'], ', mismatch' if c['mismatch'] else '') for c in cuts))

    # A wrong static optical solve can make otherwise dense, valid TC look inconsistent.
    # Retry geometry from TC correspondences only under the narrow static/mismatch gate
    # held-out image NCC still has to validate the candidate before TC is reconsidered.
    if tc_optical_retry_allowed(tc, tcs.get('info'), opt, trk, split, pins, E_valid):
        retry_opt = tc_optical_retry_candidate(
            E_lum, mask0, E_valid, P_lum, P_valid, tc, opt,
            user_pins=pins, log=log)
        if retry_opt is not None:
            previous_tcs = dict(
                pins=dict(tcs['pins']), hints=dict(tcs['hints']),
                info=None if tcs['info'] is None else dict(tcs['info']))
            U_retry, path_retry, Ef_retry, Pf_retry, m_retry, Wp_retry = match(retry_opt, mask0)
            retry_info = tcs.get('info') or {}
            if tc_optical_retry_adopted(retry_info, tcs['pins'], E_valid, pins):
                opt = retry_opt
                U, path, Ef, Pf, m, Wp_img = (
                    U_retry, path_retry, Ef_retry, Pf_retry, m_retry, Wp_retry)
                cuts = cut_suspects(
                    U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps,
                    max_speed=max_speed)
                log('  TC optical retry adopted: held-out image validation restored %d TC pins' %
                    retry_info.get('used', 0))
            else:
                tcs.update(previous_tcs)
                log('  TC optical retry rejected: candidate did not restore dense TC agreement')

    # Subpixel static geometry can hide a one-frame timing difference. Propose
    # only from a measured static track, then independently validate and rematch.
    precision_adopted = False
    if (static_precision_retry_allowed(opt, path, E_valid, track=trk, split=split,
            tc=tc, pins=pins, hints=hints, exclude=excl, region=manual_region, cuts=cuts)
            and static_precision_probe_allowed(t1)):
        polished, precision = static_precision_candidate(
            E_lum, P_lum, path, m, E_valid, P_valid, opt)
        if precision['adopted']:
            Up, pp, ep, pf_, mp, wp = match(polished, m)
            cp = cut_suspects(Up, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps,
                              max_speed=max_speed)
            before, after = U[np.arange(E), path], Up[np.arange(E), pp]
            if static_precision_rematch_accept(before, after, path, pp, E_valid, m, mp, cp):
                changed = E_valid & (pp != path)
                timing_gain = Up[np.arange(E), path] - after
                log('  static precision: %d frames, median cost %.5f -> %.5f, timing gain %.5f' %
                    (int(changed.sum()), np.median(before[E_valid]), np.median(after[E_valid]),
                     np.median(timing_gain[changed]) if changed.any() else 0.0))
                opt = dict(polished, score_multi=static_precision_score(
                    E_lum, P_lum, pp, mp, E_valid, polished))
                U, path, Ef, Pf, m, Wp_img = Up, pp, ep, pf_, mp, wp
                cuts, coords = cp, None
                static_candidate, static_candidate_used_times = None, []
                precision_adopted = True

    # Validate TC only after the final optical cost matrix is available.
    # An early static optical mismatch must not overrule TC for an animated reframe.
    # Direction is an output policy; applying it while fitting optical tracks can bias that fit.
    path = dp_path(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
    cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
    image_path = None
    if tc and tc.get('pins'):
        image_path = dp_path(U, E_valid, P_valid, pins, hints, jumps, max_speed=max_speed)
        old_pins, old_hints = dict(tcs['pins']), dict(tcs['hints'])
        tc_apply(U, image_path=image_path, validation_only=True)
        if tcs['pins'] != old_pins or tcs['hints'] != old_hints:
            path = dp_path(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
        if tc_increment_retry_allowed(tc, tcs.get('info'), opt, trk, split, pins,
                E_valid, P_valid, hints, excl, manual_region, cuts, max_speed):
            # Keep the residual-clean mask; do not reintroduce burn-in glyph pixels.
            retry_opt = tc_optical_retry_candidate(
                E_lum, m, E_valid, P_lum, P_valid, tc, opt, user_pins=pins, log=log)
            if retry_opt is not None:
                previous_tcs = dict(pins=dict(tcs['pins']), hints=dict(tcs['hints']),
                                    info=dict(tcs['info']))
                Ur, pr, er, pf_r, mr, wr = match(retry_opt, m)
                independent = dp_path(Ur, E_valid, P_valid, pins, hints, jumps,
                                      max_speed=max_speed)
                # Never use the TC-constrained path to validate its own anchors.
                agrees = all(int(independent[t]) == int(q) for t, q in tc['pins'].items())
                # Adoption relies on the side effect of this tc_apply(): it refreshes tcs['info']/tcs['pins']
                # from Ur, which tc_optical_retry_adopted() below reads (and the else branch rolls back).
                tc_apply(Ur, image_path=independent, validation_only=True)
                if agrees and tc_optical_retry_adopted(tcs.get('info'), tcs['pins'], E_valid, pins):
                    opt, U, Ef, Pf, m, Wp_img = retry_opt, Ur, er, pf_r, mr, wr
                    path, image_path, trk, coords = independent, independent, None, None
                    static_candidate, static_candidate_used_times = None, []
                    cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'],
                                        jumps, max_speed=max_speed)
                    log('  TC increment recovery adopted: independent image path agrees with every TC anchor')
                else:
                    tcs.update(previous_tcs)
                    log('  TC increment recovery rejected: independent image path disagreement')
        released = tc_lowq_pins(U, path, E_valid, tcs['pins'], pins, interp_frames=tc.get('interp') or ())
        if released:
            candidate_pins = {t: q for t, q in tcs['pins'].items() if t not in released}
            candidate = dp_path(U, E_valid, P_valid, candidate_pins, tcs['hints'], jumps, max_speed=max_speed)
            old_cost, new_cost = U[np.arange(E), path], U[np.arange(E), candidate]
            valid_cost = E_valid & np.isfinite(old_cost) & np.isfinite(new_cost)
            if (new_cost[released].sum() < old_cost[released].sum() and
                    new_cost[valid_cost].sum() <= old_cost[valid_cost].sum() + 1e-6):
                path = candidate
                tcs['pins'] = candidate_pins
                tcs['info'] = dict(tcs['info'], lowq_released=released,
                                   used=len([t for t in candidate_pins if t not in pins]))
                log(_t('  TC 품질 낮은 고정점 해제 후 재풀이: %s', '  TC re-solve after releasing low-quality anchors: %s') % released)
        cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)

    if precision_adopted:
        precise_path = static_precision_temporal_candidate(Ef, Pf, U, path, E_valid, P_valid,
                                                           _cells(m), max_speed=max_speed)
        if not np.array_equal(precise_path, path):
            log('  static precision tile consensus: %d frames' % int((precise_path != path).sum()))
            path = precise_path
            opt = dict(opt, score_multi=static_precision_score(E_lum, P_lum, path, m, E_valid, opt))

    # rounding alignment of constant-speed edits (only when there are no pins / TC / cut suspects / exclusion ranges, and only when the pure image cost goes down)
    if not tcs['pins'] and not tcs['hints'] and not cuts and not excl.any():
        sp = snap_constant_rate(U, path, E_valid, P_valid)
        if sp is not None:
            log(_t('[6] 등속 정렬: %d프레임 바뀜 (직선 경로의 이미지 비용이 DP 경로보다 낮음)', '[6] Constant-speed alignment: %d frames changed (straight path has lower image cost than DP path)') % int((sp != path).sum()))
            path = sp
    # near-hold (still) segments: detect stretches where the picture can hardly identify the source frame -> only 'indistinguishable' ones get a constant-speed line
    if _a3_checkpoint is not None:
        _a3_checkpoint.update(_a3_snapshot_state(dict(
        E=E, E_lum=E_lum, E_valid=E_valid, P=P, P_lum=P_lum,
        P_valid=P_valid, U=U, Wp_img=Wp_img, coords=coords, cuts=cuts,
        detect_optical=detect_optical, detect_slow_on=detect_slow_on, excl=excl, frac_masked=frac_masked, hints=hints,
        image_path=image_path, jumps=jumps, log=log, m=m, manual_region=manual_region,
        match=match, max_speed=max_speed, opt=opt, ovl_info=ovl_info, path=path,
        pins=pins, split=split, split_region=split_region, static_candidate=static_candidate, static_candidate_used_times=static_candidate_used_times,
        t1=t1, tc=tc, tc_track_values=tc_track_values, tcs=tcs, trk=trk
        )))
    return _solve_finish(
        E=E, E_lum=E_lum, E_valid=E_valid, P=P, P_lum=P_lum,
        P_valid=P_valid, U=U, Wp_img=Wp_img, coords=coords, cuts=cuts,
        detect_optical=detect_optical, detect_slow_on=detect_slow_on, excl=excl, frac_masked=frac_masked, hints=hints,
        image_path=image_path, jumps=jumps, log=log, m=m, manual_region=manual_region,
        match=match, max_speed=max_speed, opt=opt, ovl_info=ovl_info, path=path,
        pins=pins, split=split, split_region=split_region, static_candidate=static_candidate, static_candidate_used_times=static_candidate_used_times,
        t1=t1, tc=tc, tc_track_values=tc_track_values, tcs=tcs, trk=trk
    )


def _solve_finish(E, E_lum, E_valid, P, P_lum, P_valid, U, Wp_img, coords, cuts, detect_optical, detect_slow_on, excl, frac_masked, hints, image_path, jumps, log, m, manual_region, match, max_speed, opt, ovl_info, path, pins, split, split_region, static_candidate, static_candidate_used_times, t1, tc, tc_track_values, tcs, trk, forced_path=None):
    """Finalize the same solve state; mixed A3 seeds must survive this complete tail."""

    if forced_path is not None:
        path = _a3_forced_path_guard(forced_path, E, P, max_speed, jumps, pins, tcs['pins']).copy()
        cuts = cut_suspects(U, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps, max_speed=max_speed)
        static_candidate = None
        static_candidate_used_times = []
    nh = []
    motion_adopted_info = None
    try:
        q0 = max(0, int(path.min()) - NH_K - 2)
        q1 = min(P - 1, int(path.max()) + NH_K + 2)
        s0, s1 = max(0, q0 - NH_K), min(P, q1 + NH_K + 1)  # convert only the plate frames needed for the table to display form
        Pd = to_display(blur121(P_lum[s0:s1])) if coords is not None else to_display(Wp_img[s0:s1][:, m])
        D = plate_diff_table(Pd, q0 - s0, q1 - s0)
        # The segment near a suspected split cut is not covered as 'indistinguishable' (left to the cut warning). But if the jump is between places with the same picture inside a still plate
        # (the +39 'jump' of a reposition-drift still shot), it is not cut evidence - excluded when the plate picture difference on both sides of the jump is NH_PIX x 2 or less
        def _cut_real(c):
            t, j = int(c['t']), int(c.get('jump') or 0)
            if abs(j) < CUT_MIN_JUMP or t < 1:
                return True
            qa, qb = int(path[t - 1]), int(path[t - 1]) + j
            if not (0 <= qb < P):
                return True
            if coords is not None:
                A_, B_ = to_display(blur121(P_lum[[qa, qb]]))
            else:
                A_, B_ = to_display(Wp_img[[qa, qb]][:, m])
            return float(100.0 * np.abs(A_ - B_).mean()) > 2 * NH_PIX
        nh = near_hold_spans(U, path, E_valid, D, q0, animated=trk is not None,
                             cuts=[c['t'] for c in cuts if _cut_real(c)])
        nh = tc_confirm(nh, path, dict((t, q) for t, q in tcs['pins'].items() if t not in pins),
                        image_path=image_path, interp_frames=(tc or {}).get('interp') or ())
        nh = pin_confirm(nh, pins)
        curve_allowed = near_hold_curve_retry_allowed(
            path, E_valid, nh, pins=pins, hints=hints,
            tc_pins=dict((t, q) for t, q in tcs['pins'].items() if t not in pins),
            tc_hints=dict((t, q) for t, q in tcs['hints'].items() if t not in pins and t not in hints),
            cuts=cuts, track=trk, split=split, exclude=excl)
        p_nh = respond_near_hold(U, path, E_valid, nh, pins)
        motion_context = dict(pins=pins, hints=hints, tc=tc, cuts=cuts, track=trk,
                              split=split, exclude=excl, region=manual_region)
        if coords is None and local_motion_retry_allowed(path, p_nh, E_valid, nh, **motion_context):
            p_motion, motion_info = local_motion_retry_candidate(
                U, path, p_nh, nh, E_valid, P_valid, E_lum[:, m], Wp_img[:, m],
                _cells(m), D, q0, max_speed=max_speed, **motion_context)
            if motion_info['adopted'] and not cut_suspects(
                    motion_info['costs'], E_valid, P_valid, tcs['pins'], tcs['hints'], jumps,
                    max_speed=max_speed):
                p_nh = p_motion
                nh = motion_info['spans']
                motion_adopted_info = {k: v for k, v in motion_info.items() if k not in ('spans', 'costs')}
                curve_allowed = False
                log('[6] local motion tiles: %d/%d, cross-validation gains %.1f%% / %.1f%%' %
                    (motion_info['active_cells'], motion_info['cell_count'],
                     100 * motion_info['gain_a_on_b'], 100 * motion_info['gain_b_on_a']))
        if curve_allowed:
            p_curve, curve_info = near_hold_curve_candidate(U, path, E_valid, nh, pins=pins, max_speed=max_speed)
            if p_curve is not None:
                p_nh = p_curve
                for curve_span in nh:
                    if [curve_span.get('t0'), curve_span.get('t1')] == curve_info.get('span'):
                        curve_span['curve_retry'] = curve_info
                        curve_span['bridged'] = True
                log(_t('[6] 정지 구간 곡률 재시도 채택: %d-%d (holdout %.2f%%, span %.2f%%, boundary %s)', '[6] Hold-span curvature retry accepted: %d-%d (holdout %.2f%%, span %.2f%%, boundary %s)') %
                    (curve_info['span'][0], curve_info['span'][1],
                     100.0 * curve_info['costs']['holdout']['gain'],
                     100.0 * curve_info['costs']['full']['gain'], curve_info['boundary']))
        # Interpolation between confident TCs (TC-first pins + TCs that passed the check in hint mode) - segments with user pins are left to the pins
        tck = dict((t, q) for t, q in tcs['pins'].items() if t not in pins)
        tck.update((t, q) for t, q in tcs['hints'].items() if not isinstance(q, tuple) and t not in pins)
        if tck:
            p_nh = tc_fill_near_hold(p_nh, [s for s in nh if not s.get('pinned') and s.get('tc_endpoint') != 'mismatch'],
                                     tck, [c['t'] for c in cuts])
        if nh:
            nh_change = ''
            if (p_nh != path).any():
                nh_change = _t(' -> %s %d프레임 바뀜', ' -> %s changed %d frames') % (
                    _t('국소 움직임 타일 재검사', 'local motion tile recheck') if motion_adopted_info is not None else
                    _t('곡률 재시도', 'curvature retry') if any(s.get('curve_retry') for s in nh) else _t('일정 속도 직선', 'constant-speed line'),
                    int((p_nh != path).sum()))
            log(_t('[6] 정지 구간: %s%s', '[6] Hold spans: %s%s') % (', '.join('%d-%d %s %s' % (s['t0'], s['t1'], _span_state(s), _unc_short(s))
                                                for s in nh), nh_change))
        path = p_nh
    except Exception as e:  # so the auxiliary decision does not block the result
        log(_t('  정지 구간 판정 실패(무시): %s', '  Hold-span detection failed (ignored): %s') % e)
        nh = []
    # A false hold can require more movement than the early precision pass permits.
    # Keep the old result until independent timing, production costs and near-hold
    # semantics all agree; the short-shift pass and its repeat protection stay intact.
    if (coords is None and motion_adopted_info is None and
            static_ambiguity_retry_allowed(opt, path, E_valid, nh, t1, track=trk, split=split,
                tc=tc, pins=pins, hints=hints, exclude=excl, region=manual_region, cuts=cuts)):
        try:
            ao, ap, ai = static_ambiguity_candidate(
                E_lum, P_lum, path, m, E_valid, P_valid, opt, nh, max_speed=max_speed)
            if ai['adopted']:
                au, _dp, ae, af, am, aw = match(ao, m)
                ac = cut_suspects(au, E_valid, P_valid, tcs['pins'], tcs['hints'], jumps,
                                  max_speed=max_speed)
                accepted = static_precision_rematch_accept(
                    U[np.arange(E), path], au[np.arange(E), ap], path, ap, E_valid,
                    m, am, ac, max_shift=NH_K)
                rejection = 'production_rank_cost'
                if accepted:
                    aq0, aq1 = max(0, int(ap.min()) - NH_K - 2), min(P - 1, int(ap.max()) + NH_K + 2)
                    as0, as1 = max(0, aq0 - NH_K), min(P, aq1 + NH_K + 1)
                    ad = plate_diff_table(to_display(aw[as0:as1][:, am]), aq0 - as0, aq1 - as0)
                    an = near_hold_spans(au, ap, E_valid, ad, aq0)
                    accepted = (not any(s.get('tier') == 'ambiguous' for s in an) and
                                np.array_equal(respond_near_hold(au, ap, E_valid, an), ap))
                    rejection = 'near_hold_response'
                    if accepted:
                        try:
                            old_blend = local_motion_has_blend(E_lum[:, m], Wp_img[:, m], path, E_valid)
                        except Exception:
                            old_blend = None  # Old-hypothesis diagnostics cannot veto independent evidence.
                        new_blend = local_motion_has_blend(E_lum[:, am], aw[:, am], ap, E_valid)
                        union_blend = static_ambiguity_blend_flags(E_lum[:, am], aw[:, am], path, ap, E_valid, P_valid)
                        accepted = not new_blend and not union_blend.any()
                        ai = dict(ai, original_blend=old_blend, candidate_blend=new_blend,
                                  independent_blend_frames=int(union_blend.sum()))
                        rejection = 'interpolation_evidence (candidate=%s, independent=%d)' % (new_blend, union_blend.sum())
                if accepted:
                    ao = dict(ao, score_multi=static_precision_score(E_lum, P_lum, ap, am, E_valid, ao),
                              ambiguity_retry=ai)
                    U, path, Ef, Pf, m, Wp_img, opt, cuts, nh = au, ap, ae, af, am, aw, ao, ac, an
                    static_candidate, static_candidate_used_times = None, []
                    log('[6] static ambiguity tiles: %d frames, independent gains %.1f%% / %.1f%%' %
                        (ai['changed_frames'], 100 * ai['gains'][0], 100 * ai['gains'][1]))
                else:
                    log('[6] static ambiguity tiles rejected: %s' % rejection)
            else:
                log('[6] static ambiguity tiles rejected: %s' % ai['reason'])
        except Exception as e:
            log('  static ambiguity check skipped: %s' % e)
    # exclusion ranges: frames without pins / TC hints are constant-speed interpolated between the confirmed frames before and after
    path = _fill_excluded(path, excl, set(tcs['pins']) | set(hints))
    tc_mis = [int(t) for t, q in tcs['hints'].items()
              if not isinstance(q, tuple) and 0 <= t < E and E_valid[t] and int(path[t]) != int(q)]
    tc_info = tcs['info']
    if tc_info is not None:  # TC pins the path could not keep (TC jump = toward a split cut)
        tc_info = dict(tc_info, missed=[int(t) for t, q in tcs['pins'].items()
                                        if t not in pins and int(path[t]) != int(q)])

    # 6. Confidence
    best = U[np.arange(E), path]
    best = np.where(np.isfinite(best), best, np.nan)
    base = np.nanmedian(best[E_valid]) + 1e-6 if E_valid.any() else 1.0
    best = np.nan_to_num(best, nan=0.0)
    log('  match quality (median cost): %.3f' % float(base))
    lowq = np.where(E_valid & (best > LOWQ_RATIO * base))[0].tolist()
    amb = 0
    for t in np.where(E_valid)[0]:
        far = (np.abs(np.arange(P) - path[t]) > 2) & np.isfinite(U[t])
        if far.any() and U[t, far].min() < best[t] * 1.03:
            amb += 1
    # uniqueness-based confidence - match quality (median cost) does not mean 'the other candidates are worse than this'
    # (real-footage degraded: 84% 'fair' but 61% of frames wrong). Ambiguous / low-quality fractions + top/bottom half agreement
    nv = max(int(E_valid.sum()), 1)
    try:
        half = half_agreement(E_lum, P_lum, m, path, E_valid, opt=opt, coords=coords)
    except Exception as e:  # so the auxiliary confidence metric does not block the result
        log(_t('  half agreement 실패(무시): %s', '  Half agreement failed (ignored): %s') % e)
        half = None
    conf = dict(amb=amb / float(nv), lowq=len(lowq) / float(nv), half=half)
    conf_warn = []
    if conf['amb'] > CONF_AMB_MAX:
        conf_warn.append('모호 프레임 %d%%' % round(100 * conf['amb']))
    if conf['lowq'] > CONF_LOWQ_MAX:
        conf_warn.append('품질 낮은 프레임 %d%%' % round(100 * conf['lowq']))
    if half is not None and half < CONF_HALF_MIN:
        conf_warn.append('상하 절반 합의 %d%%' % round(100 * half))
    if trk is not None and max(np.ptp(trk['tx']), np.ptp(trk['ty'])) > 0.004:
        pan = plate_pan_like(P_lum, path, E_valid)
        conf['pan'] = pan
        if pan is not None and pan[0] > PAN_NCC:
            conf_warn.append('시간-이동 모호(플레이트 팬/틸트 + 리포지션 이동 애니메이션 — 경로 확인 권장)')
    s_lo = float(np.min(trk['s'])) if trk is not None else float(opt['s'])
    s_hi = float(np.max(trk['s'])) if trk is not None else float(opt['s'])
    if detect_optical and (s_lo < SCALE_MIN * 1.01 or s_hi > SCALE_MAX * 0.99) and \
            (float(base) > WARN_QUALITY or conf_warn):
        conf_warn.append('스케일 범위 밖(필러/레터박스 의심, 탐색 %.2f~%.2f)' % (SCALE_MIN, SCALE_MAX))
    log('  confidence: ambiguous %.0f%%, low %.0f%%, half agreement %s%s'
        % (100 * conf['amb'], 100 * conf['lowq'], '-' if half is None else '%.0f%%' % (100 * half),
           ('  -> [!] ' + ', '.join(conf_warn)) if conf_warn else ''))

    # slow + zoom time normalization (only for optical animation + time-movement ambiguity + slow slope)
    tnorm = None
    if trk is not None and trk.get('animated') and any(w_.startswith('시간-이동 모호') for w_ in conf_warn) and \
            not (tcs['pins'] or pins):
        try:
            p_tn, tnorm = time_normalize(U, path, E_valid, P_valid)
            log('  time normalize (slow + zoom): %s%s' % (tnorm, _t(' -> 채택', ' -> accepted') if p_tn is not None else ''))
            if p_tn is not None:
                path = p_tn
                tnorm = dict(tnorm, used=True)
        except Exception as e:  # so auxiliary processing does not block the result
            log(_t('  time normalize 실패(무시): %s', '  Time normalization failed (ignored): %s') % e)
    # 7. Slow
    slow = []
    interp = np.zeros(E, bool)
    frac = path.astype(float)
    lookup, sub_spans, sub_diag = None, [], None
    if detect_slow_on:
        if coords is not None:
            Pb = blur121(P_lum)

            def plate_disp(t, pl):
                return to_display(bilinear(Pb[pl], *coords[t])[0][:, m])
        else:
            Pd_all = to_display(Wp_img[:, m])

            def plate_disp(t, pl):
                return Pd_all[pl]
        Ed = to_display(E_lum[:, m])
        vt = np.where(E_valid)[0]
        Py = np.stack([plate_disp(t, [path[t]])[0] for t in vt])
        Ed = fit_tone_lut(Ed[vt], Py)(Ed)
        frac, interp = detect_slow(Ed, plate_disp, path, E_valid, P)
        slow = slow_segments(frac, interp, E_valid, path)
        sub_est, sub_gain, sub_vtx = subframe_estimates(Ed, plate_disp, path, E_valid, P, frac, interp)
        image_blend_spans = []
        if any(s_.get('tc_path_agree') and s_.get('tc_endpoint') == 'mismatch' for s_ in nh):
            _, image_blend_spans = subframe_lookup(path, E_valid, sub_est, sub_gain, sub_vtx, interp, slow, plate_count=P)
        nh_block = near_hold_subframe_block(nh, E, image_blend_spans)
        lookup, sub_spans = subframe_lookup(path, E_valid, sub_est, sub_gain, sub_vtx, interp, slow, block=nh_block, plate_count=P)
        log('[7] subframe lookup spans: %s' % (sub_spans,))
        sub_diag = dict(est=sub_est, gain=sub_gain, vtx=sub_vtx)
    log('[7] slow segments: %s' % (slow,))

    effective_region = split_region if split_region is not None else manual_region
    return dict(path=path, optical=opt, track=trk, split=split, region=effective_region,
                region_source=('manual+auto' if manual_region is not None and split_region is not None else
                               'manual' if manual_region is not None else 'auto'),
                manual_region=manual_region, local_motion=motion_adopted_info,
                static_candidate=static_candidate,
                static_candidate_used_times=static_candidate_used_times,
                slow=slow, blended=interp, frac=frac, lookup=lookup, sub_spans=sub_spans, sub_diag=sub_diag, tnorm=tnorm, E_valid=E_valid, P_valid=P_valid,
                lowq=lowq, ambiguous=amb, masked=frac_masked, overlay=ovl_info['frac'], cost=best, mask=m,
                quality=float(base), excluded=np.where(excl)[0].tolist(),
                pins=pins, tc_hints=sum(1 for q in tcs['hints'].values() if not isinstance(q, tuple)),
                tc_mismatch=tc_mis, tc=tc_info,
                tc_track_verified=(dict((int(t), int(q)) for t, q in
                                        ((tcs.get('info') or {}).get('image_verified') or {}).items()
                                        if t not in pins and E_valid[t] and tcs['pins'].get(t) == q
                                        and int(path[t]) == int(q))
                                   if tc_track_values is not None else {}),
                cuts=cuts, reversals=direction_changes(path, E_valid | excl),
                confidence=conf, confidence_warn=conf_warn, near_hold=nh)


def locate_range(E_lum, P_lum_s, P_ok, detect_optical=True, allow_flop=True, log=print,
                 split=False, exclude=None, region=None):
    """
    Stage 1: estimate the optical on stride plates + search the used range
    Returns: (lo_idx, hi_idx, opt)  indices are relative to the stride array
    """
    E, He, We = E_lum.shape
    mask0 = edit_static_mask(E_lum)
    mask0 &= ~overlay_mask(E_lum, mask0)[0]
    if region is not None:
        region = np.asarray(region, bool)
        if region.shape != mask0.shape:
            raise ValueError('manual ROI mask shape %s does not match EDIT %s' %
                             (region.shape, mask0.shape))
        mask0 &= region
    E_valid = valid_frames(E_lum, mask0)
    if exclude is not None:
        E_valid &= ~np.asarray(exclude, bool)
    P_valid = np.asarray(P_ok, bool) & (P_lum_s.reshape(len(P_lum_s), -1).std(1) > 0)
    opt = estimate_optical(E_lum, mask0, E_valid, P_lum_s, P_valid,
                           allow_flop=allow_flop, detect=detect_optical, log=log,
                           subregions=split)
    Wp, cov = warp_plate_stack(P_lum_s, opt, He, We)
    m = mask0 & cov
    if opt.get('rmask') is not None:
        m &= opt['rmask']
    U = cost_matrix(rank_rows(E_lum[:, m]), rank_rows(Wp[:, m]), _cells(m), E_valid)
    U[:, ~P_valid] = np.inf
    a = np.argmin(U, axis=1)
    best = U[np.arange(E), a]
    good = E_valid & np.isfinite(best)
    if not good.any():
        return 0, len(P_lum_s) - 1, opt
    med = np.median(best[good])
    good &= best <= 2.0 * med
    return int(a[good].min()), int(a[good].max()), opt


# Nuke layer
def _thumb_size(node, W):
    f = node.format()
    w, h, pa = f.width(), f.height(), f.pixelAspect()
    H = max(8, int(round(W * h / (w * pa))))
    return w, h, H


def temp_storage_base(custom=None, system_temp=None):
    """Return the selected base folder without touching tempfile globals.

    An empty preference preserves the historical system-temp default.  The tool
    always writes through a dedicated ``no_more_manual_retime`` child directory.
    """
    value = custom
    if value is None:
        value = _ACTIVE_TEMP_BASE
    if value is None:
        value = _ui_get('temp_path', '')
    value = str(value or '').strip()
    if not value:
        value = tempfile.gettempdir() if system_temp is None else system_temp
    expanded = os.path.abspath(os.path.expandvars(os.path.expanduser(value)))
    return os.path.realpath(expanded).replace('\\', '/')


def temp_storage_root(custom=None, system_temp=None):
    return os.path.join(temp_storage_base(custom, system_temp), _TEMP_NAMESPACE).replace('\\', '/')


def temp_storage_path(kind, custom=None):
    if kind not in _TEMP_KINDS:
        raise ValueError('unknown No More Manual Retime temp kind: %s' % kind)
    return os.path.join(temp_storage_root(custom), kind).replace('\\', '/')


def validate_temp_storage(custom=None):
    """Create and write-test tool-owned folders; never silently fall back."""
    root = temp_storage_root(custom)
    probe = None
    try:
        if os.path.lexists(root) and os.path.islink(root):
            raise ValueError(_t('no_more_manual_retime 폴더가 심볼릭 링크입니다', 'no_more_manual_retime folder is a symbolic link'))
        if not os.path.isdir(root):
            os.makedirs(root)
        for kind in _TEMP_KINDS:
            path = os.path.join(root, kind)
            if os.path.lexists(path) and os.path.islink(path):
                raise ValueError(_t('%s 폴더가 심볼릭 링크입니다', '%s folder is a symbolic link') % kind)
            if not os.path.isdir(path):
                os.makedirs(path)
        for path in (root,) + tuple(os.path.join(root, kind) for kind in _TEMP_KINDS):
            try:
                fd, probe = tempfile.mkstemp(prefix='.write_test_', dir=path)
                os.close(fd)
                os.unlink(probe)
                probe = None
            except Exception as error:
                raise ValueError(_t('쓰기 시험 실패: %s (%s)', 'Write test failed: %s (%s)') % (path, error))
        return root
    except Exception as error:
        if probe:
            try:
                os.unlink(probe)
            except Exception:
                pass
        raise RuntimeError(_t('임시 저장소를 사용할 수 없습니다: %s\n'
                           '쓰기 가능한 로컬 폴더를 고르거나 [기본값]으로 되돌려 주세요. (%s)',
                           'Temporary storage is unavailable: %s\nChoose a writable local folder or restore Default. (%s)')
                           % (temp_storage_base(custom), error))


class _TempStorageJob(object):
    """Pin one base for a complete job even if the saved UI setting changes."""
    def __init__(self, custom=None):
        self.custom = custom
        self.previous = None
        self.previous_custom = None

    def __enter__(self):
        global _ACTIVE_TEMP_BASE, _ACTIVE_TEMP_CUSTOM
        self.previous = _ACTIVE_TEMP_BASE
        self.previous_custom = _ACTIVE_TEMP_CUSTOM
        selected = self.custom if self.custom is not None else _ui_get('temp_path', '')
        _ACTIVE_TEMP_CUSTOM = str(selected or '').strip()
        # Resolve the user-selected base once. The base itself may be a
        # symlink, but changing that link while a job runs must not redirect
        # this job's cache creation or cleanup to its new target.
        candidate = os.path.realpath(temp_storage_base(_ACTIVE_TEMP_CUSTOM)).replace('\\', '/')
        _ACTIVE_TEMP_BASE = candidate
        try:
            validate_temp_storage(candidate)
        except Exception:
            _ACTIVE_TEMP_BASE = self.previous
            _ACTIVE_TEMP_CUSTOM = self.previous_custom
            raise
        return temp_storage_root(_ACTIVE_TEMP_BASE)

    def __exit__(self, *_exc):
        global _ACTIVE_TEMP_BASE, _ACTIVE_TEMP_CUSTOM
        _ACTIVE_TEMP_BASE = self.previous
        _ACTIVE_TEMP_CUSTOM = self.previous_custom


def temp_storage_job(custom=None):
    return _TempStorageJob(custom)


def make_temp_dir(kind, prefix='NMMR_'):
    validate_temp_storage(_ACTIVE_TEMP_BASE)
    return tempfile.mkdtemp(prefix=prefix, dir=temp_storage_path(kind))


def _owned_temp_kind_root(path, kind):
    """Validate the lexical namespace/kind boundary at deletion time.

    The selected base itself may be a symlink, but the tool-owned
    ``no_more_manual_retime`` namespace and its kind folder must be real directories.
    Checking before realpath prevents a post-validation symlink swap from
    turning cleanup into deletion outside the namespace.
    """
    try:
        path = os.path.abspath(path)
        namespace = os.path.dirname(path)
        return (kind in _TEMP_KINDS
                and os.path.basename(path) == kind
                and os.path.basename(namespace) == _TEMP_NAMESPACE
                and os.path.lexists(namespace) and not os.path.islink(namespace)
                and os.path.isdir(namespace)
                and os.path.lexists(path) and not os.path.islink(path)
                and os.path.isdir(path)
                and os.path.dirname(os.path.realpath(path)) == os.path.realpath(namespace))
    except Exception:
        return False


def remove_temp_dir(path, kind):
    """Remove only a direct child of the requested tool-owned temp folder."""
    import shutil
    parent_path = os.path.abspath(temp_storage_path(kind))
    path = os.path.abspath(path)
    if (not _owned_temp_kind_root(parent_path, kind)
            or os.path.dirname(path) != parent_path
            or os.path.islink(path)):
        return False
    parent = os.path.realpath(parent_path)
    target = os.path.realpath(path)
    if os.path.dirname(target) != parent:
        return False
    shutil.rmtree(path, ignore_errors=True)
    return not os.path.exists(path)


def _cache_root():
    return temp_storage_path('cache')


def _root_color_value(name):
    """Keep missing/unreadable host settings distinct in the cache contract."""
    try:
        knob = nuke.root().knobs().get(name)
        return '<missing>' if knob is None else str(knob.value())
    except Exception:
        return '<read-error>'


def _custom_ocio():
    return (_root_color_value('colorManagement') == 'OCIO'
            and _root_color_value('OCIO_config') == 'custom')


def _input_color_fingerprint():
    """Input transforms affect analysis pixels; viewer transforms do not."""
    fields = ('colorManagement', 'OCIO_config', 'customOCIOConfigPath', 'OCIOConfigPath',
              'workingSpaceLUT', 'int8Lut', 'int16Lut', 'logLut', 'floatLut')
    parts = ['root.%s=%r' % (key, _root_color_value(key)) for key in fields]
    parts.append('nuke=%r' % getattr(nuke, 'NUKE_VERSION_STRING', '<unknown>'))
    if _custom_ocio():
        path = os.path.expandvars(os.path.expanduser(_root_color_value('customOCIOConfigPath')))
        try:
            with open(path, 'rb') as handle:
                digest = hashlib.sha256(handle.read()).hexdigest()
            parts.append('custom.config=%s' % digest)
        except (OSError, ValueError):
            parts.append('custom.config=<unreadable>')
    return '|'.join(parts)


def _thumb_dir(node, W):
    """ per-frame cache folder. The key changes when the source changes
    """
    parts = [THUMB_VER, nuke.root().name(), node.fullName(), str(W)]
    f = node.format()
    parts.append('%dx%d@%s' % (f.width(), f.height(), f.pixelAspect()))
    parts.append(_input_color_fingerprint())
    for kn in ('file', 'colorspace', 'frame_mode', 'frame', 'first', 'last', 'raw'):
        if kn in node.knobs():
            try:
                parts.append('%s=%s' % (kn, node[kn].value()))
            except Exception:
                pass
    try:  # replacing a file at the same path also invalidates the analysis key and the thumbnail key together through the ns mtime/size
        parts.append('source=%r' % (read_source_stat_signature(node),))
    except Exception:
        pass
    if node.Class() != 'Read':
        try:
            parts.append(node.writeKnobs(nuke.WRITE_NON_DEFAULT_ONLY | nuke.TO_SCRIPT))
        except Exception:
            pass
    h = hashlib.md5('|'.join(parts).encode('utf-8')).hexdigest()[:12]
    return '%s/%s_%s' % (_cache_root(), node.name(), h)


_CACHE_DIR_RE = re.compile(r'^[A-Za-z0-9_]+_[0-9a-f]{12}$')


def _is_cache_dir(d, root=None):
    """ check whether this is a thumbnail cache folder that is safe to delete.
    Directly under the cache root + named '<node name>_<12-digit hash>' + not a symbolic link - all three must hold for True.
    A safeguard so that even if the path computation goes wrong, it never deletes the wrong folder (the root itself, a parent folder, another tool's folder)
    """
    try:
        root_path = os.path.abspath(root or _cache_root())
        d = os.path.abspath(d)
        if not _owned_temp_kind_root(root_path, 'cache') or os.path.dirname(d) != root_path:
            return False
        root = os.path.realpath(root_path)
        dd = os.path.realpath(d)
        return (os.path.dirname(dd) == root and _CACHE_DIR_RE.match(os.path.basename(dd)) is not None
                and os.path.isdir(dd) and not os.path.islink(d))
    except Exception:
        return False


def remove_cache_dirs(dirs, log=print, root=None):
    """ delete only the thumbnail folders used in this run (Python file APIs only, no shell commands)"""
    import shutil
    n = 0
    root = os.path.abspath(root or _cache_root())
    if not _owned_temp_kind_root(root, 'cache'):
        log(_t('cache keep (루트 검사 불통과): %s', 'cache kept (root validation failed): %s') % root)
        return
    for d in sorted(set(dirs)):
        if not _is_cache_dir(d, root=root):
            if os.path.exists(d):
                log(_t('cache keep (검사 불통과): %s', 'cache kept (validation failed): %s') % d)
            continue
        shutil.rmtree(d, ignore_errors=True)
        if not os.path.exists(d):
            n += 1
        else:
            log(_t('cache 삭제 일부 실패 (파일 잠김?) — 다음 실행 때 7일 정리로 재시도: %s', 'Some cache files could not be removed (locked?). The seven-day cleanup will retry on a later run: %s') % d)
    try:
        if os.path.isdir(root) and not os.listdir(root):
            os.rmdir(root)
    except Exception:
        pass
    if n:
        log('cache removed: %d folders' % n)


def _record_cache_dir(path):
    """Capture one cache folder by its resolved path before render/reuse."""
    path = os.path.abspath(path)
    root = os.path.dirname(path)
    namespace = os.path.dirname(root)
    owned_shape = (os.path.basename(root) == 'cache'
                   and os.path.basename(namespace) == _TEMP_NAMESPACE)
    if owned_shape:
        validate_temp_storage(os.path.dirname(namespace))
        if not _owned_temp_kind_root(root, 'cache') or os.path.islink(path):
            raise RuntimeError(_t('cache 경로의 소유 경계를 확인할 수 없습니다: %s', 'Cannot verify the cache ownership boundary: %s') % path)
    path = os.path.realpath(path).replace('\\', '/')
    # path uses '/' from here on, while realpath() returns '\' on Windows: compare them as paths, not strings.
    if owned_shape and os.path.normcase(os.path.dirname(path)) != os.path.normcase(os.path.realpath(root)):
        raise RuntimeError(_t('cache 경로가 외부 위치를 가리킵니다: %s', 'Cache path points outside its folder: %s') % path)
    _USED_DIRS.add(path)
    return path


def remove_recorded_cache_dirs(dirs, log=print):
    """Clean preview caches by each resolved root captured when they were used."""
    handled = set(os.path.abspath(d) for d in dirs)
    by_root = {}
    for path in handled:
        by_root.setdefault(os.path.dirname(path), set()).add(path)
    for root, paths in by_root.items():
        remove_cache_dirs(paths, log=log, root=root)
    return handled


def clean_cache(days=CACHE_DAYS, log=print, root=None):
    """"""
    root = os.path.abspath(root or _cache_root())
    if not _owned_temp_kind_root(root, 'cache'):
        return
    import shutil
    import time
    limit = time.time() - days * 86400
    n = 0
    for d in os.listdir(root):
        fp = os.path.join(root, d)
        try:
            if _is_cache_dir(fp, root=root) and os.path.getmtime(fp) < limit:  # name check
                shutil.rmtree(fp, ignore_errors=True)
                n += 1
        except Exception:
            pass
    if n:
        log('cache cleanup: %d folders' % n)


class UndoGroup(object):
    """ undo group that reverts all nodes created inside with a single Ctrl+Z"""

    def __init__(self, name='No More Manual Retime'):
        self.name, self.u = name, None

    def __enter__(self):
        try:
            self.u = nuke.Undo()
            self.u.begin(self.name)
        except Exception:
            self.u = None
        return self

    def __exit__(self, *exc):
        try:
            if self.u is not None:
                self.u.end()
        except Exception:
            pass
        return False


class NoUndo(object):
    """ excludes creating/deleting temporary nodes for thumbnail rendering from the undo history"""

    def __enter__(self):
        try:
            nuke.Undo.disable()
            self.ok = True
        except Exception:
            self.ok = False
        return self

    def __exit__(self, *exc):
        try:
            if self.ok:
                nuke.Undo.enable()
        except Exception:
            pass
        return False


def _set(node, knob, value):
    try:
        node[knob].setValue(value)
        return True
    except Exception:
        return False


# path templates - server auto source (user-defined, no default)
# If the setting is empty, server lookup is off and only the Reads in the script are used (load selected node / auto detect).
# Settings files layer in this order: shared (env var NMMR_PATHS = json path, several separated by os.pathsep) -> personal (~/.nuke/no_more_manual_retime_paths.json)
# (later wins, empty values keep the earlier value). Everything below is pure functions - verified by the core tests without Nuke
# Template syntax: {root} {project} {seq} {shot} {layer} {version} (+ plate {ext}), * = any characters inside one folder
# frame slot = #### / %04d / $F4 / {frame}. {root} may span several folders, {version} is a number, the rest stay inside one folder
PATHS_ENV = 'NMMR_PATHS'
PATHS_USER_FILE = os.path.join(os.path.expanduser('~'), '.nuke', 'no_more_manual_retime_paths.json').replace('\\', '/')
PATH_TOKENS = ('root', 'project', 'seq', 'shot', 'layer', 'version')
PATHS_DEFAULTS = {
    'enabled': True,
    'defaults': {'first_frame': 'plate'},
    'ignore_case': False,  # ignore case (Windows servers / mixed spelling)
    'roots': [],  # {root} candidates (tried in order after the value taken from the shot context: server + local cache, etc.)
    'scan_timeout': 15.0,  # time limit of one lookup (seconds) - so the window does not freeze for long on a slow server
    'context': [],  # shot context templates (script path -> otherwise the scene Read path, the first that matches)
    'plate': {'templates': [], 'layers': [], 'extensions': [], 'max_version': 0, 'latest': 'version'},
    'edit': {'folders': [], 'extensions': ['mov', 'mp4', 'mxf'], 'name_contains': [], 'exclude_dirs': [],
             'max_depth': 4, 'shot_match': 'exact', 'variant_max_len': 2, 'latest': 'mtime', 'latest_regex': ''},
}
_EDIT_SCAN_CACHE = {}  # (folders, rule) -> [edit paths] (session cache, one walk of a slow server)
_PATHS_CACHE = {}
_TMPL_PART = re.compile(r'\{([A-Za-z_]+)\}|\*|#+|%0?\d*d|\$F\d*')


class PathScanStop(Exception):
    """ path lookup aborted (time limit / cancel)"""


def _paths_blank(v):
    return v is None or v == '' or v == [] or v == {}


def paths_merge(base, over):
    """ over overrides base. dicts recurse per key, empty values (None / '' / [] / {}) leave the base value as is"""
    out = dict(base or {})
    for k, v in (over or {}).items():
        if isinstance(v, dict) and isinstance(out.get(k), dict):
            out[k] = paths_merge(out[k], v)
        elif not _paths_blank(v):
            out[k] = v
    return out


def _as_list(v, split_comma=True):
    """ list field: a list as is / a string is split by lines (templates) or by lines and commas (name lists)"""
    if _paths_blank(v):
        return []
    if isinstance(v, (list, tuple)):
        items = v
    else:
        items = re.split(r'[\n,]' if split_comma else r'\n', str(v))
    return [str(x).strip() for x in items if str(x).strip()]


def paths_normalize(cfg):
    """ settings dict -> a dict with defaults filled in and formats normalized (unknown keys and description keys starting with '_' are ignored)"""
    c = paths_merge(PATHS_DEFAULTS, cfg or {})
    c['enabled'] = bool(c.get('enabled', True))
    c['ignore_case'] = bool(c.get('ignore_case'))
    c['roots'] = _as_list(c.get('roots'), False)
    c['context'] = _as_list(c.get('context'), False)
    try:
        c['scan_timeout'] = max(1.0, float(c.get('scan_timeout') or PATHS_DEFAULTS['scan_timeout']))
    except Exception:
        c['scan_timeout'] = PATHS_DEFAULTS['scan_timeout']
    p, e = dict(c['plate']), dict(c['edit'])
    p['templates'] = _as_list(p.get('templates'), False)
    p['layers'] = _as_list(p.get('layers'))
    p['extensions'] = [x.lower().lstrip('.') for x in _as_list(p.get('extensions'))]
    p['latest'] = p.get('latest') if p.get('latest') in ('version', 'mtime') else 'version'
    e['folders'] = _as_list(e.get('folders'), False)
    e['extensions'] = [x.lower().lstrip('.') for x in _as_list(e.get('extensions'))]
    e['name_contains'] = _as_list(e.get('name_contains'))
    e['exclude_dirs'] = [x.lower() for x in _as_list(e.get('exclude_dirs'))]
    e['shot_match'] = e.get('shot_match') if e.get('shot_match') in ('exact', 'contains', 'off') else 'exact'
    e['latest'] = e.get('latest') if e.get('latest') in ('mtime', 'version', 'regex') else 'mtime'
    e['latest_regex'] = str(e.get('latest_regex') or '')
    for d, k, lo in ((p, 'max_version', 0), (e, 'max_depth', 0), (e, 'variant_max_len', 0)):
        try:
            d[k] = max(lo, int(d.get(k) or 0))
        except Exception:
            d[k] = PATHS_DEFAULTS['plate' if d is p else 'edit'][k]
    c['plate'], c['edit'] = p, e
    return c


def _paths_read(label, path):
    d = dict(label=label, path=path, data=None, error=None, exists=os.path.isfile(path))
    if d['exists']:
        try:
            import json
            with open(path) as f:
                data = json.load(f)
            if not isinstance(data, dict):
                raise ValueError('최상위가 { } 객체가 아닙니다')
            d['data'] = data
        except Exception as ex:
            d['error'] = str(ex)
    return d


def paths_layers(user_file=None, env=None):
    """Shared paths, then personal settings."""
    if env is None:
        env = os.environ.get(PATHS_ENV, '')
    out = [_paths_read('공용', p.strip()) for p in str(env or '').split(os.pathsep) if p.strip()]
    path = user_file or PATHS_USER_FILE
    out.append(_paths_read('개인', path))
    return out


def _settings_overlay(base, changes):
    """Preserve unedited settings, including unknown keys; explicit empty values win."""
    result = dict(base)
    for key, value in changes.items():
        result[key] = (_settings_overlay(result[key], value)
                       if isinstance(result.get(key), dict) and isinstance(value, dict) else value)
    return result


def save_paths_cfg(changes, clear_keys=()):
    """Write the personal settings file."""
    import json
    layer = paths_layers(env='')[-1]
    if layer.get('error'):
        raise ValueError(layer['error'])
    data = _settings_overlay(layer.get('data') or {}, changes)
    for keys in clear_keys:
        parent_data = data
        for key in keys[:-1]:
            parent_data = parent_data.get(key, {})
            if not isinstance(parent_data, dict):
                break
        if isinstance(parent_data, dict):
            parent_data.pop(keys[-1], None)
    parent = os.path.dirname(PATHS_USER_FILE)
    if parent and not os.path.isdir(parent):
        os.makedirs(parent)
    with open(PATHS_USER_FILE, 'w') as f:
        json.dump(data, f, indent=2, ensure_ascii=False)
        f.write('\n')
    return PATHS_USER_FILE


def paths_from_layers(layers, override=None):
    """ layers + (optional) dict to overlay -> normalized settings"""
    raw = {}
    for L in layers:
        if L.get('data'):
            raw = paths_merge(raw, L['data'])
    if override:
        raw = paths_merge(raw, override)
    return paths_normalize(raw)


def paths_source(layers, *keys):
    """ the layer that set this field (the last layer with a non-empty value), or None"""
    src = None
    for L in layers:
        v = L.get('data')
        for k in keys:
            v = v.get(k) if isinstance(v, dict) else None
        if not _paths_blank(v):
            src = L
    return src


def paths_config(user_file=None, env=None):
    """ the settings in use (cached while the file modification time is unchanged) -> (settings, list of layers)"""
    layers = paths_layers(user_file, env)
    key = tuple((L['path'], os.path.getmtime(L['path']) if L['exists'] else None) for L in layers)
    hit = _PATHS_CACHE.get('k')
    if hit is not None and hit[0] == key:
        return hit[1], hit[2]
    cfg = paths_from_layers(layers)
    _PATHS_CACHE['k'] = (key, cfg, layers)
    return cfg, layers


def paths_settings_summary(user, studio, env_name=PATHS_ENV):
    """Visible settings-layer summary; paths and read errors remain untouched user data."""
    status = _t('있음', 'present') if user['exists'] else _t('없음 (저장하면 만듦)',
                                                              'not found (created when saved)')
    if user.get('error'):
        status = _t('읽기 오류: ', 'Read error: ') + str(user['error'])
    text = _t('개인 설정: ', 'Personal settings: ') + str(user['path']) + '  (' + status + ')'
    if studio:
        for layer in studio:
            if layer.get('error'):
                layer_status = _t('읽기 오류: ', 'Read error: ') + str(layer['error'])
            else:
                layer_status = (_t('있음', 'present') if layer['exists'] else
                                _t('파일 없음', 'file not found'))
            text += (_t('\n공용 설정 (', '\nShared settings (') + str(env_name) + '): ' +
                     str(layer['path']) + '  (' + layer_status + ')')
        text += _t(
            '\n빈 칸 = 공용 값 사용 (흐린 글씨). 칸에 쓴 값이 공용 값을 이깁니다 — 오른쪽 배지에 어느 값인지 표시',
            '\nEmpty fields use shared values (shown faintly). Personal field values override shared values; the badge shows the active source.')
    else:
        text += _t(
            '\n공용 설정 없음 (공용 파일은 환경변수 %s 로 지정). 빈 칸 = 기본값',
            '\nNo shared settings (set a shared file with the %s environment variable). Empty fields use defaults.') % env_name
    return text


def paths_active(cfg):
    """ server auto source is on = the setting is on and there is at least one shot context template"""
    return bool(cfg and cfg.get('enabled', True) and cfg.get('context'))


def _norm_path(p):
    """ unify path separators to '/', collapse repeated '/', keep UNC (//server/share), strip the trailing '/'"""
    p = str(p or '').strip().replace('\\', '/')
    unc = p.startswith('//')
    p = re.sub(r'/+', '/', p)
    if unc:
        p = '/' + p
    if len(p) > 1 and p.endswith('/') and not re.match(r'^[A-Za-z]:/$', p):
        p = p.rstrip('/')
    return p


def _tmpl_regex(tmpl, known=None, roots=None):
    """ template piece -> regex string. known = token values already known (matched literally). An unknown token raises ValueError
    roots = list of {root} candidates (if present, {root} matches only one of them, longer first. Otherwise the shortest leading part whose tail matches)"""
    known = known or {}
    out, seen, pos = [], set(), 0
    for m in _TMPL_PART.finditer(tmpl):
        out.append(re.escape(tmpl[pos:m.start()]))
        pos = m.end()
        tok, s = m.group(1), m.group(0)
        if tok is None and s == '*':
            out.append(r'[^/]*')
            continue
        tl = (tok or 'frame').lower()
        if tl not in PATH_TOKENS + ('ext', 'frame'):
            raise ValueError('알 수 없는 토큰 {%s} (쓸 수 있는 토큰: %s, {ext}, {frame})'
                             % (tok, ' '.join('{%s}' % t for t in PATH_TOKENS)))
        if known.get(tl):
            out.append(re.escape(str(known[tl])))
        elif tl in seen:
            out.append('(?P=%s)' % tl)
        else:
            seen.add(tl)
            body = {'root': r'.+?', 'version': r'\d+', 'frame': r'\d+', 'ext': r'[A-Za-z0-9]+'}.get(tl, r'[^/]+?')
            if tl == 'root' and roots:
                body = '|'.join(re.escape(r) for r in sorted(roots, key=len, reverse=True))
            out.append('(?P<%s>%s)' % (tl, body))
    out.append(re.escape(tmpl[pos:]))
    return ''.join(out)


def _tmpl_check(tmpl):
    """ template error message or None"""
    try:
        _tmpl_regex(tmpl)
    except ValueError as ex:
        return str(ex)
    if re.search(r'\{[^}]*$|^[^{]*\}', tmpl):
        return '중괄호 { } 짝이 맞지 않습니다'
    return None


def _ctx_search(tmpl, path, flags, roots=None):
    t = _norm_path(tmpl)
    rx = _tmpl_regex(t, roots=[r for r in (_norm_path(x) for x in roots or ()) if r])
    pre = '' if (t.startswith('/') or re.match(r'^[A-Za-z]:', t) or t.lower().startswith('{root}')) else r'(?:^|(?<=/))'
    return re.search(pre + rx + r'(?=/|$)', path, flags)


def context_tokens(path, cfg):
    """ path -> shot context token dict ({} if not found). Shot context templates in order, the first one that captures {shot}"""
    if not paths_active(cfg):
        return {}
    p = _norm_path(path)
    if not p:
        return {}
    flags = re.I if cfg.get('ignore_case') else 0
    for t in cfg['context']:
        try:
            m = _ctx_search(t, p, flags, cfg.get('roots'))
        except (ValueError, re.error):
            continue
        if m:
            tok = dict((k, v) for k, v in m.groupdict().items() if v and k != 'frame')
            if tok.get('shot'):
                tok['_template'] = t
                tok['_path'] = p
                return tok
    return {}


def context_diag(tmpl, path, cfg):
    """ where a shot context template stopped when it does not match the path: try matching while growing folder pieces from the front"""
    err = _tmpl_check(tmpl)
    if err:
        return err
    t, p = _norm_path(tmpl), _norm_path(path)
    flags = re.I if cfg.get('ignore_case') else 0
    segs = t.split('/')
    ok = 0
    for k in range(1, len(segs) + 1):
        part = '/'.join(segs[:k])
        if not part.strip('/'):
            ok = k
            continue
        try:
            if _ctx_search(part, p, flags, cfg.get('roots')):
                ok = k
                continue
        except (ValueError, re.error):
            pass
        break
    if ok >= len(segs):
        return '{shot} 이 없습니다 (샷 문맥 템플릿에는 {shot} 이 꼭 있어야 합니다)' if '{shot}' not in t.lower() else '맞음'
    return "%d번째 조각 '%s' 에서 멈춤 (앞부분 '%s' 까지는 맞음)" % (len([x for x in segs[:ok] if x]) + 1, segs[ok],
                                                         '/'.join(segs[:ok]) or '/')


def _tok_known(tok):
    return dict((k.lower(), v) for k, v in (tok or {}).items() if v and not k.startswith('_'))


def _seg_has_pattern(seg, known):
    if re.search(r'\*|#|%0?\d*d|\$F', seg):
        return True
    return any(not known.get(m.group(1).lower()) for m in re.finditer(r'\{([A-Za-z_]+)\}', seg))


def _scan_template(tmpl, tok, cfg, want='file', tick=None, diag=None, limit=4000):
    """ template -> actual paths [(path, captured token dict)].
    Known tokens (shot context) are used as is; unknown tokens / * / frame slots are matched by opening folders (descending one folder at a time).
    {root} is tried from the shot context value -> cfg['roots']. The failure point (piece number / piece / position / reason) is left in diag"""
    diag = diag if diag is not None else {}
    err = _tmpl_check(tmpl)
    if err:
        diag.update(reason=err)
        return []
    known0 = _tok_known(tok)
    t = _norm_path(tmpl)
    if '{root}' in t.lower():
        roots = []
        for r in [known0.get('root')] + list(cfg.get('roots') or []):
            r = _norm_path(r)
            if r and r not in roots:
                roots.append(r)
        if not roots:
            diag.update(reason='{root} 값이 없습니다 (샷 문맥 템플릿에 {root} 가 없고 roots 도 비어 있음)', index=0, segment='{root}')
            return []
        bases = [re.sub(r'\{root\}', lambda m, r=r: r, t, flags=re.I) for r in roots]
        out, diags = [], []
        for b, r in zip(bases, roots):
            d = {}
            kn = dict(tok or {})
            kn['root'] = r
            for path, caps in _scan_template(b, kn, cfg, want, tick, d, limit):
                caps['root'] = r
                out.append((path, caps))
            if d.get('index'):  # the piece number is relative to the template ({root} = one piece)
                d['index'] -= max(0, len([x for x in r.split('/') if x]) - 1)
                d['reason'] = "%d번째 조각 '%s' 에 맞는 %s 없습니다" % (d['index'], d['segment'], d['kind'])
            diags.append(d)
        if not out and diags:
            diag.update(diags[0])
        return out
    flags = re.I if cfg.get('ignore_case') else 0
    segs = t.split('/')
    if t.startswith('//') and len(segs) > 4:  # UNC: //server/share
        base, i = '//%s/%s' % (segs[2], segs[3]), 4
    elif t.startswith('/'):
        base, i = '/', 1
    elif re.match(r'^[A-Za-z]:$', segs[0]):
        base, i = segs[0] + '/', 1
    else:
        diag.update(reason='절대 경로로 써 주세요 (/ 또는 드라이브 문자 C:/ 또는 //server/share 로 시작)', index=0, segment=segs[0])
        return []
    states = [(base, {})]
    n = len(segs)
    while i < n:
        seg, last = segs[i], i == n - 1
        if not seg:
            i += 1
            continue
        nxt = []
        for cur, caps in states:
            known = dict(known0)
            known.update(caps)
            if tick is not None:
                tick()
            if not _seg_has_pattern(seg, known) and not flags:
                path = os.path.join(cur, re.sub(r'\{([A-Za-z_]+)\}', lambda m: str(known[m.group(1).lower()]), seg))
                path = path.replace('\\', '/')
                if (os.path.isfile(path) if (last and want == 'file') else os.path.isdir(path)):
                    nxt.append((path, caps))
                continue
            try:
                rx = re.compile(_tmpl_regex(seg, known) + r'\Z', flags)
                names = sorted(os.listdir(cur))
            except (OSError, re.error):
                continue
            for nm in names:
                m = rx.match(nm)
                if not m:
                    continue
                path = os.path.join(cur, nm).replace('\\', '/')
                if not (os.path.isfile(path) if (last and want == 'file') else os.path.isdir(path)):
                    continue
                c2 = dict(caps)
                c2.update(dict((k, v) for k, v in m.groupdict().items() if v is not None))
                nxt.append((path, c2))
                if len(nxt) >= limit:
                    break
        if not nxt:
            hi = len([x for x in segs[:i] if x]) + 1  # piece number as a person counts it (leading / excluded)
            kind = '파일이' if (last and want == 'file') else '폴더가'
            diag.update(index=hi, segment=seg, kind=kind, under=[s[0] for s in states[:3]],
                        reason="%d번째 조각 '%s' 에 맞는 %s 없습니다" % (hi, seg, kind))
            return []
        states = nxt
        i += 1
    return states


def find_plates(tok, cfg, tick=None, diags=None):
    """ shot context -> list of plate candidates, best first (layer priority -> latest -> template / root order). [] if none.
    Candidate dict(dir, pattern, first, last, version, name, layer, movie, mtime, template)
    A sequence (has a frame slot) groups the files into a %0Nd pattern and range, a movie is one file (the Read decides the range)"""
    diags = diags if diags is not None else []
    if not paths_active(cfg) or not tok or not tok.get('shot'):
        return []
    P = cfg['plate']
    lay = [x.lower() for x in P['layers']]
    for ti, t in enumerate(P['templates']):
        d = dict(template=t)
        hits = _scan_template(t, tok, cfg, 'file', tick, d)
        groups = {}
        for path, caps in hits:
            dname, fname = os.path.split(path)
            ext = os.path.splitext(fname)[1].lower().lstrip('.')
            if P['extensions'] and ext not in P['extensions']:
                continue
            ver = caps.get('version')
            if P['max_version'] and ver is not None and int(ver) > P['max_version']:
                continue
            layer = caps.get('layer')
            if lay and layer is not None and layer.lower() not in lay:
                continue
            if caps.get('frame') is not None:
                fr = caps['frame']
                j = fname.rfind(fr)  # the frame number is that number at the back of the name
                pre, post = fname[:j], fname[j + len(fr):]
                key = (dname, pre, post)
                g = groups.setdefault(key, dict(caps=caps, frames=[], digits=[], sample=path))
                g['frames'].append(int(fr))
                g['digits'].append(fr)
            else:
                groups[(dname, fname, None)] = dict(caps=caps, frames=None, digits=None, sample=path)
        cands = []
        for (dname, pre, post), g in groups.items():
            caps = g['caps']
            if g['frames'] is not None:
                lens = set(len(x) for x in g['digits'])
                pad = min(lens)
                padded = len(lens) == 1 or any(x.startswith('0') for x in g['digits'])
                pattern = '%s/%s%s%s' % (dname, pre, ('%%0%dd' % pad) if padded else '%d', post)
                first, last = min(g['frames']), max(g['frames'])
                name = re.sub(r'[._\-]+$', '', pre) or os.path.basename(dname)
                movie = False
            else:
                pattern = '%s/%s' % (dname, pre)
                first = last = None
                name = os.path.splitext(pre)[0]
                movie = True
            try:
                mt = os.path.getmtime(g['sample'])  # a sequence uses the first file, a movie that file
            except Exception:
                mt = 0
            ver = caps.get('version')
            cands.append(dict(dir=dname, pattern=pattern, first=first, last=last, name=name, movie=movie, mtime=mt,
                              version=('v%s' % ver) if ver is not None else '', layer=caps.get('layer'),
                              root=caps.get('root'), template=t, _ver=int(ver) if ver is not None else -1))
        if not cands:
            if not d.get('reason'):
                d['reason'] = ('찾은 파일 %d개가 모두 조건(레이어 · 확장자 · 최대 버전)에서 빠졌습니다' % len(hits)) if hits else '찾은 파일이 없습니다'
            diags.append(d)
            continue
        roots = [None] + [_norm_path(r) for r in cfg.get('roots') or []]

        def rank(c):
            lr = lay.index(c['layer'].lower()) if (lay and c['layer'] and c['layer'].lower() in lay) else 0
            rr = roots.index(c['root']) if c['root'] in roots else 0
            if P['latest'] == 'version':  # same version: root order (server -> cache), then modification time
                return (lr, -c['_ver'], rr, -c['mtime'], c['pattern'])
            return (lr, -c['mtime'], -c['_ver'], rr, c['pattern'])
        cands.sort(key=rank)
        diags.append(dict(template=t, found=len(cands)))
        return cands
    return []


def edit_folders(tok, cfg, tick=None, diags=None):
    """ edit folder templates -> actual folder list (order kept, duplicates removed)"""
    diags = diags if diags is not None else []
    out = []
    for t in cfg['edit']['folders']:
        d = dict(template=t)
        hits = _scan_template(t, tok, cfg, 'dir', tick, d)
        for path, _ in hits:
            if path not in out:
                out.append(path)
        d['found'] = len(hits)
        diags.append(d)
    return out


def scan_edit_files(folders, cfg, refresh=False, tick=None, log=print):
    """ walk the edit folders (depth limit, excluded folders, extensions, name-contains conditions), session cache"""
    E = cfg['edit']
    key = (tuple(folders), tuple(E['extensions']), tuple(E['name_contains']), tuple(E['exclude_dirs']), E['max_depth'],
           bool(cfg.get('ignore_case')))
    if key in _EDIT_SCAN_CACHE and not refresh:
        return _EDIT_SCAN_CACHE[key]
    exts = tuple('.' + x for x in E['extensions'])
    need = [x.lower() for x in E['name_contains']]
    out = []
    for base in folders:
        if not os.path.isdir(base):
            log(_t('편집본 폴더 없음: %s', 'Edit folder not found: %s') % base)
            continue
        b0 = base.rstrip('/').count('/')
        for root, dirs, files in os.walk(base):
            if tick is not None:
                tick()
            depth = root.replace('\\', '/').rstrip('/').count('/') - b0
            dirs[:] = sorted(x for x in dirs if x.lower() not in E['exclude_dirs'] and not x.startswith('.'))
            if E['max_depth'] and depth >= E['max_depth']:
                dirs[:] = []
            for f in sorted(files):
                fl = f.lower()
                if f.startswith('.') or (exts and not fl.endswith(exts)):
                    continue
                if any(s not in fl for s in need):
                    continue
                out.append(os.path.join(root, f).replace('\\', '/'))
    _EDIT_SCAN_CACHE[key] = out
    return out


def _edit_sort_key(path, E):
    name = os.path.basename(path)
    try:
        mt = os.path.getmtime(path)
    except Exception:
        mt = 0
    v = None
    if E['latest'] == 'version':
        ms = re.findall(r'(?:^|[^A-Za-z0-9])[vV](\d+)', name)
        v = int(ms[-1]) if ms else None
    elif E['latest'] == 'regex' and E['latest_regex']:
        try:
            m = re.search(E['latest_regex'], name, re.I)
        except re.error:
            m = None
        if m:
            s = m.group(1) if m.groups() else m.group(0)
            v = int(s) if s.isdigit() else s
    if E['latest'] == 'mtime':
        return (1, mt, '')
    if v is None:
        return (0, '', mt)  # names that do not fit the rule go last (modification time order within that)
    return (1, v if isinstance(v, str) else '%020d' % v, mt)


def find_edits(tok, cfg, refresh=False, tick=None, diags=None, log=print):
    """ shot context -> list of edits for that shot, newest first (rule: modification time / file name version / regex, ties by modification time)"""
    diags = diags if diags is not None else []
    if not paths_active(cfg) or not tok or not tok.get('shot'):
        return []
    E = cfg['edit']
    folders = edit_folders(tok, cfg, tick, diags)
    files = scan_edit_files(folders, cfg, refresh, tick, log)
    shot = tok['shot']
    if E['shot_match'] == 'exact':
        movs = [p for p in files if shot_in_filename(os.path.basename(p), shot, E['variant_max_len'],
                                                     bool(cfg.get('ignore_case')))]
    elif E['shot_match'] == 'contains':
        ci = bool(cfg.get('ignore_case'))
        movs = [p for p in files if ((shot.lower() in os.path.basename(p).lower()) if ci else (shot in os.path.basename(p)))]
    else:
        movs = list(files)
    movs.sort(key=lambda p: _edit_sort_key(p, E), reverse=True)
    diags.append(dict(folders=folders, files=len(files), matched=len(movs)))
    return movs


def _VARIANT(n):
    return re.compile(r'^[A-Za-z][A-Za-z0-9]{0,%d}$' % max(0, n - 1)) if n > 0 else None


def shot_in_filename(fname, shot, variant_max_len=2, ignore_case=False):
    """
    Whether the file name contains the shot code 'exactly'.
    Substring matching let EP01_0010 pick up even EP01_0010_F edits.
    The shot code must not run on into alphanumerics before or after, and the token right after must not be a variant-shot suffix (1-2 letters)
    maximum suffix length variant_max_len (0 = variant-shot check off). Version notation such as v2 / V003 is not a variant shot
    """
    if not shot:
        return False
    if ignore_case:
        fname, shot = fname.lower(), shot.lower()
    vt = _VARIANT(variant_max_len)
    i = fname.find(shot)
    while i >= 0:
        before_ok = i == 0 or not fname[i - 1].isalnum()
        rest = fname[i + len(shot):]
        after_ok = not rest or not rest[0].isalnum()
        if before_ok and after_ok:
            m = re.match(r'[_.\-]([A-Za-z0-9]+)', rest)
            variant = bool(vt and m and rest[0] != '.' and vt.match(m.group(1)) and not re.match(r'^[vV]\d+$', m.group(1)))
            if not variant:
                return True
        i = fname.find(shot, i + 1)
    return False


def ctx_tuple(tok):
    """ token dict -> (project, seq, shot) - the format the window / batch used"""
    tok = tok or {}
    return (tok.get('project'), tok.get('seq'), tok.get('shot'))


def node_tokens(node, cfg=None):
    """ Read node path -> shot context token dict"""
    try:
        return context_tokens(node['file'].value(), cfg if cfg is not None else paths_config()[0])
    except Exception:
        return {}


def node_context(node):
    """ (project, seq, shot) based on path templates"""
    return ctx_tuple(node_tokens(node))


def script_tokens(cfg=None):
    """ script path -> otherwise shot context tokens from the scene Read path ({} = not found / no settings)"""
    cfg = cfg if cfg is not None else paths_config()[0]
    if not paths_active(cfg) or nuke is None:
        return {}
    c = context_tokens(nuke.root().name(), cfg)
    if c:
        return c
    for n in nuke.allNodes('Read'):
        c = node_tokens(n, cfg)
        if c:
            c['_src'] = 'Read %s' % n.name()
            return c
    return {}


def script_context():
    """ (project, seq, shot)"""
    return ctx_tuple(script_tokens())


def probe_paths(cfg, script_path, read_paths=(), tick=None):
    """ body of [Test with the current script] (pure function). Returns dict(ok, stage, lines, tok, plates, edits)
    lines = [(stage, 'ok' / 'warn' / 'err' / 'info', text)] - on failure, which stage and which piece it stopped at"""
    L = []
    res = dict(ok=False, stage='', lines=L, tok={}, plates=[], edits=[])
    if not cfg.get('enabled', True):
        L.append(('설정', 'err', "꺼져 있습니다 (enabled = false). 씬의 Read 만 씁니다"))
        res['stage'] = '설정'
        return res
    if not cfg.get('context'):
        L.append(('설정', 'warn', '샷 문맥 템플릿이 비어 있어 서버 자동 소스가 꺼져 있습니다. 씬의 Read 만 씁니다'))
        res['stage'] = '설정'
        return res
    for t in cfg['context'] + cfg['plate']['templates'] + cfg['edit']['folders']:
        err = _tmpl_check(t)
        if err:
            L.append(('설정', 'err', '%s  ->  %s' % (t, err)))
    srcs = [('스크립트', script_path)] + [('Read', p) for p in read_paths if p]
    tok = {}
    for label, p in srcs:
        if not p:
            continue
        tok = context_tokens(p, cfg)
        if tok:
            L.append(('샷 문맥', 'ok', '%s 경로에서 찾음: %s' % (label, p)))
            L.append(('샷 문맥', 'info', '템플릿: %s' % tok['_template']))
            L.append(('샷 문맥', 'info', '토큰: ' + '  '.join('{%s} = %s' % (k, tok[k]) for k in PATH_TOKENS if tok.get(k))))
            break
    if not tok:
        res['stage'] = '샷 문맥'
        p0 = script_path or next((p for p in read_paths if p), '')
        if not p0:
            L.append(('샷 문맥', 'err', '스크립트가 저장되지 않았고 씬에 Read 도 없어 맞춰 볼 경로가 없습니다'))
        else:
            L.append(('샷 문맥', 'err', '어느 경로에도 맞지 않습니다. 기준 경로: %s' % p0))
            for t in cfg['context']:
                L.append(('샷 문맥', 'info', '%s  ->  %s' % (t, context_diag(t, p0, cfg))))
        return res
    res['tok'] = tok
    pd = []
    if cfg['plate']['templates']:
        plates = find_plates(tok, cfg, tick, pd)
        res['plates'] = plates
        if plates:
            L.append(('플레이트', 'ok', '%d개 찾음. 자동 선택: %s' % (len(plates), plates[0]['pattern'])))
            for c in plates[:8]:
                rng = ('%d-%d' % (c['first'], c['last'])) if c['first'] is not None else '무비'
                L.append(('플레이트', 'info', '%s  ·  %s  ·  %s%s' % (c['name'], rng, c['version'] or '버전 없음',
                                                                (' · 레이어 %s' % c['layer']) if c['layer'] else '')))
        else:
            L.append(('플레이트', 'err', '찾지 못했습니다'))
            for d in pd:
                L.append(('플레이트', 'info', '%s  ->  %s%s' % (d.get('template'), d.get('reason', ''),
                                                            ('  (위치: %s)' % ', '.join(d['under'])) if d.get('under') else '')))
    else:
        L.append(('플레이트', 'warn', '플레이트 템플릿이 비어 있습니다 (PLATE 는 씬 Read 에서 고름)'))
    ed = []
    if cfg['edit']['folders']:
        edits = find_edits(tok, cfg, True, tick, ed, log=lambda *a: None)
        res['edits'] = edits
        folders = ed[-1]['folders'] if ed else []
        for d in ed[:-1]:
            if not d.get('found'):
                L.append(('편집본', 'warn', '폴더 템플릿 %s  ->  %s%s' % (d.get('template'), d.get('reason', '폴더 없음'),
                                                                   ('  (위치: %s)' % ', '.join(d['under'])) if d.get('under') else '')))
        if edits:
            L.append(('편집본', 'ok', '%d개 찾음 (폴더 %d곳, 파일 %d개 중). 자동 선택: %s'
                      % (len(edits), len(folders), ed[-1]['files'], edits[0])))
            for e in edits[:8]:
                L.append(('편집본', 'info', os.path.basename(e)))
        else:
            L.append(('편집본', 'err', '이 샷의 편집본을 찾지 못했습니다 (폴더 %d곳, 조건에 맞는 파일 %d개)'
                      % (len(folders), ed[-1]['files'] if ed else 0)))
    else:
        L.append(('편집본', 'warn', '편집본 폴더 템플릿이 비어 있습니다 (EDIT 는 씬 Read 에서 고름)'))
    miss = [n for n, want, got in (('플레이트', cfg['plate']['templates'], res['plates']),
                                   ('편집본', cfg['edit']['folders'], res['edits'])) if want and not got]
    res['pdiag'], res['ediag'] = pd, ed
    res['ok'] = bool(res['plates'] or res['edits']) and not miss
    res['stage'] = '완료' if res['ok'] else (miss[0] if miss else '설정')
    return res


# easy setup (block mode) - split an example file path into folder blocks and assign roles to build the template (pure functions)
# Block = one folder / file name. parts = [(start, end, role)] (character positions inside the block, the rest stays 'as is')
# Roles: project seq shot layer version any(anything) frame(frame number) root
BLOCK_ROLES = ('project', 'seq', 'shot', 'layer', 'version', 'any')
BLOCK_ROLE_TOKEN = {'project': '{project}', 'seq': '{seq}', 'shot': '{shot}', 'layer': '{layer}', 'version': '{version}',
                    'any': '*', 'root': '{root}', 'ext': '{ext}'}
_BLOCK_COMMON = set(('shots', 'shot', 'seq', 'seqs', 'sequence', 'sequences', 'scenes', 'scene', 'work', 'prod', 'production',
                     'projects', 'project', 'jobs', 'job', 'show', 'shows', 'vfx', 'plate', 'plates', 'edit', 'edits',
                     'editorial', 'comp', 'footage', 'source', 'src', 'images', 'render', 'renders', 'mnt', 'volumes',
                     'users', 'home', 'net', 'data', 'server', 'exr', 'mov', 'ref', 'reference', 'publish', 'pub'))


def path_blocks(path):
    """ path -> (prefix, [blocks]). Prefix '/' , '' (drive C: is the first block) , '//' (UNC)"""
    p = _norm_path(path)
    if p.startswith('//'):
        return '//', [b for b in p[2:].split('/') if b]
    if p.startswith('/'):
        return '/', [b for b in p.split('/') if b]
    return '', [b for b in p.split('/') if b]


def _frame_span(name):
    """Position of the frame number in a file name (3 or more digits after '.' or '_' right before the extension) or None"""
    m = re.search(r'[._](\d{3,})\.[A-Za-z0-9]+$', name)
    return (m.start(1), m.end(1)) if m else None


def _tok_spans(text):
    """tokens [(start, end)] split by [_ . - space]"""
    return [(m.start(), m.end()) for m in re.finditer(r'[^_.\-\s]+', text)]


def _find_at_bounds(text, val):
    """positions in text where val sits on a token boundary (not adjacent to alphanumerics)"""
    out, i = [], text.find(val) if val else -1
    while i >= 0:
        e = i + len(val)
        if (i == 0 or not text[i - 1].isalnum()) and (e == len(text) or not text[e].isalnum()):
            out.append((i, e))
        i = text.find(val, i + 1)
    return out


def _add_part(parts, s, e, role):
    if any(not (e <= a or s >= b) for a, b, _ in parts):
        return False
    parts.append((s, e, role))
    parts.sort()
    return True


def suggest_block_parts(blocks, hints=(), kind='plate', known=None):
    """ auto recommendation: v### = version, a token that overlaps the hint (current script name, etc.) / a folder that also appears in the file name = shot,
    a folder before the shot folder that is not a generic word = sequence / project, if the token between shot and version in the file name equals a folder, layer,
    file frame number = frame. known = values already known {role: value} (for edits, the project / sequence / shot decided from the plate)
    -> a parts list per block"""
    known = dict(known or {})
    n = len(blocks)
    P = [[] for _ in blocks]
    fname = blocks[-1] if blocks else ''
    if n and kind == 'plate':
        fs = _frame_span(fname)
        if fs:
            _add_part(P[-1], fs[0], fs[1], 'frame')
    # shot: known value -> hint token groups -> a folder name that appears again in the file name (longer first)
    shot = known.get('shot')
    if not shot:
        cands = []
        for h in hints:
            h = os.path.splitext(os.path.basename(str(h or '')))[0]
            ts = _tok_spans(h)
            for a in range(len(ts)):
                for b in range(a, min(a + 4, len(ts))):
                    v = h[ts[a][0]:ts[b][1]]
                    if len(v) < 3 or re.match(r'^[vV]\d+$', v) or v.lower() in _BLOCK_COMMON or v.isdigit() and len(v) >= 6:
                        continue
                    if any(_find_at_bounds(bk, v) for bk in (blocks if kind == 'edit' else blocks[:-1])):
                        cands.append(v)
        far = []
        if not cands and n >= 2:  # folder that appears again in the file name (excluding folders containing version notation, the folder directly above the file goes last)
            for i, bk in enumerate(blocks[:-1]):
                if len(bk) >= 3 and bk.lower() not in _BLOCK_COMMON and not bk.isdigit() and \
                        not re.search(r'(?:^|[_.\-])[vV]\d+(?=$|[_.\-])', bk) and \
                        _find_at_bounds(fname, bk):
                    cands.append(bk)
                    if i <= n - 3:
                        far.append(bk)
        if cands:
            shot = sorted(cands, key=lambda v: (v not in far, -len(v), v))[0]
    shot_i = None
    if shot:
        for i, bk in enumerate(blocks):
            for s, e in _find_at_bounds(bk, shot):
                _add_part(P[i], s, e, 'shot')
                if shot_i is None and i < n - 1 and (s, e) == (0, len(bk)):
                    shot_i = i
        if shot_i is None:
            shot_i = next((i for i in range(n - 1) if any(r == 'shot' for _, _, r in P[i])), None)
    # known project / sequence values (edit)
    for role in ('project', 'seq'):
        v = known.get(role)
        if v:
            for i, bk in enumerate(blocks[:-1] if kind == 'edit' else blocks):
                if bk == v:
                    _add_part(P[i], 0, len(bk), role)
    # sequence / project: folders before the shot folder that are not generic words (the first level is treated as the root and left alone)
    if kind == 'plate' and shot_i is not None:
        want = ['seq', 'project']
        for i in range(shot_i - 1, 0, -1):
            if not want:
                break
            bk = blocks[i]
            if bk.lower() in _BLOCK_COMMON or P[i]:
                continue
            role = 'seq' if ('seq' in want and shot.startswith(bk)) else 'project'  # if the shot starts with this name, it is the sequence
            _add_part(P[i], 0, len(bk), role)
            want = [] if role == 'project' else ['project']
    if kind == 'edit' and n >= 2:  # edit: date folder (6-8 digits) = anything, date in the file name = latest criterion (version)
        for i in range(n - 1):
            if re.match(r'^\d{6,8}$', blocks[i]) and not P[i]:
                _add_part(P[i], 0, len(blocks[i]), 'any')
        for m in reversed(list(re.finditer(r'(?:^|(?<=[_.\-]))(\d{6,8})(?=$|[_.\-])', fname))):
            if _add_part(P[-1], m.start(1), m.end(1), 'version'):  # only one date at the back
                break
    # version: v### / V### (the v stays, only the digits are the version)
    for i, bk in enumerate(blocks):
        for m in re.finditer(r'(?:^|(?<=[_.\-]))[vV](\d+)(?=$|[_.\-])', bk):
            _add_part(P[i], m.start(1), m.end(1), 'version')
    # layer: if the token after the shot and before the version in the file name equals a folder name, both are the layer
    if kind == 'plate' and n >= 2:
        for s, e in _tok_spans(fname):
            v = fname[s:e]
            if any(a < e and s < b for a, b, _ in P[-1]) or v.lower() in _BLOCK_COMMON or len(v) < 2 or v.isdigit():
                continue
            if shot and fname.find(shot) >= 0 and s < fname.find(shot) + len(shot):
                continue
            hit = [i for i in range(n - 1) if blocks[i] == v and not P[i]]
            if hit:
                _add_part(P[-1], s, e, 'layer')
                for i in hit:
                    _add_part(P[i], 0, len(blocks[i]), 'layer')
                for i in range(n - 1):  # the same token inside the version folder name
                    for a, b in _find_at_bounds(blocks[i], v):
                        _add_part(P[i], a, b, 'layer')
                break
    return P


def block_template(lead, blocks, parts, upto=None):
    """ blocks + roles -> template (upto = up to how many leading blocks)"""
    out = []
    for i, bk in enumerate(blocks[:upto] if upto is not None else blocks):
        t, pos = [], 0
        for s, e, role in sorted(parts[i]):
            t.append(bk[pos:s])
            t.append('#' * max(4, e - s) if role == 'frame' else BLOCK_ROLE_TOKEN.get(role, bk[s:e]))
            pos = e
        t.append(bk[pos:])
        out.append(''.join(t))
    return lead + '/'.join(out)


def block_problems(parts, kind='plate'):
    """ what is missing from the easy setup (in plain words)"""
    flat = [r for ps in parts for _, _, r in ps]
    out = []
    if 'shot' not in flat:
        out.append('샷 블록이 없습니다 — 샷 이름이 들어 있는 폴더나 파일 이름 부분에 [샷]을 붙여 주세요')
    if kind == 'plate' and parts and 'shot' not in [r for ps in parts[:-1] for _, _, r in ps]:
        out.append('샷 이름이 폴더에 없어 이 스크립트가 어느 샷인지 알아낼 수 없습니다 — 샷 폴더에 [샷]을 붙여 주세요')
    return out


def easy_plate_config(example, parts):
    """ plate example + roles -> settings fragment {context, plate.templates}.
    Shot context = the leading part up to the shot folder (if the script is not under the shot folder, it is found from the plate Read path in the scene)"""
    lead, blocks = path_blocks(example)
    shot_i = next((i for i in range(len(blocks) - 1) if any(r == 'shot' for _, _, r in parts[i])), None)
    out = {'plate': {'templates': [block_template(lead, blocks, parts)], 'example': _norm_path(example)}}
    if shot_i is not None:
        out['context'] = [block_template(lead, blocks, parts, shot_i + 1)]
    return out


def easy_edit_config(example, parts):
    """ edit example + roles -> settings fragment {edit: folders, extensions, shot_match, latest, latest_regex, max_depth}.
    The folder template is cut before the [anything] block and searched below it (date folders, etc.). The [version] part of the file name = latest criterion"""
    lead, blocks = path_blocks(example)
    fparts = parts[-1] if parts else []
    cut = next((i for i in range(len(blocks) - 1) if any(r == 'any' for _, _, r in parts[i])), len(blocks) - 1)
    folder = block_template(lead, blocks, parts, cut)
    fname = blocks[-1] if blocks else ''
    ext = os.path.splitext(fname)[1].lower().lstrip('.')
    exts = [ext] + [x for x in ('mov', 'mp4', 'mxf') if x != ext] if ext else ['mov', 'mp4', 'mxf']
    in_folder = any(r == 'shot' for ps in parts[:cut] for _, _, r in ps)
    in_file = any(r == 'shot' for _, _, r in fparts)
    e = {'folders': [folder], 'extensions': exts, 'shot_match': 'exact' if (in_file or not in_folder) else 'off',
         'max_depth': max(4, len(blocks) - 1 - cut + 1), 'example': _norm_path(example)}
    ver = [(s, x) for s, x, r in fparts if r == 'version']
    if ver:
        s, x = ver[0]
        pre = fname[:s]
        lit = re.split(r'[^A-Za-z_.\-]', pre)[-1][-6:] if pre else ''
        e['latest'], e['latest_regex'] = 'regex', re.escape(lit) + r'(\d+)'
    else:
        e['latest'], e['latest_regex'] = 'mtime', ''
    return {'edit': e}


def template_block_parts(tmpl, example):
    """ if the template fits the example path, parts per block (to show a template edited in developer mode as blocks again), otherwise None.
    Slots spanning {root} or several folders cannot be expressed as blocks, so None"""
    if not tmpl or not example:
        return None
    t, p = _norm_path(tmpl), _norm_path(example)
    rx, roles, pos = [], [], 0
    for m in _TMPL_PART.finditer(t):
        rx.append(re.escape(t[pos:m.start()]))
        pos = m.end()
        tok, s = m.group(1), m.group(0)
        if tok is None and s == '*':
            role, body = 'any', r'[^/]*'
        elif tok is None:
            role, body = 'frame', r'\d+'
        else:
            role = tok.lower()
            if role == 'root':
                return None
            if role not in PATH_TOKENS + ('ext', 'frame'):
                return None
            body = {'version': r'\d+', 'frame': r'\d+', 'ext': r'[A-Za-z0-9]+'}.get(role, r'[^/]+?')
            if role in roles and role != 'frame':  # the same role has the same value (back-reference to the earlier group, position taken from this group)
                body = '(?P=g%d)' % roles.index(role)
        rx.append('(?P<g%d>%s)' % (len(roles), body))
        roles.append(role)
    rx.append(re.escape(t[pos:]))
    m = re.match(''.join(rx) + r'(?=/|$)', p)
    if not m:
        return None
    vals = {}
    for i, r in enumerate(roles):
        if r in ('any', 'frame'):
            continue
        if vals.setdefault(r, m.group('g%d' % i)) != m.group('g%d' % i):
            return None
    lead, blocks = path_blocks(p)
    offs, o = [], len(lead)
    for b in blocks:
        offs.append(o)
        o += len(b) + 1
    parts = [[] for _ in blocks]
    for i, r in enumerate(roles):
        s, e = m.span('g%d' % i)
        bi = next((k for k in range(len(blocks)) if offs[k] <= s and e <= offs[k] + len(blocks[k])), None)
        if bi is None:
            return None
        if r == 'ext':
            continue
        parts[bi].append((s - offs[bi], e - offs[bi], r))
    for ps in parts:
        ps.sort()
    return parts


def edit_block_parts(ecfg, example, hints=()):
    """ edit settings + example -> block parts (None if the folder template does not fit the example). The first folder below the folder template = anything,
    the shot in the file name is recommended from hints (plate shot / script name), the part matched by the latest regex = version"""
    folders = ecfg.get('folders') or []
    if not folders or not example:
        return None
    fp = template_block_parts(folders[0], example)
    if fp is None:
        return None
    lead, blocks = path_blocks(example)
    nf = len(path_blocks(folders[0])[1])
    parts = [list(fp[i]) if i < nf else [] for i in range(len(blocks))]
    if nf < len(blocks) - 1:
        parts[nf] = [(0, len(blocks[nf]), 'any')]
    fname = blocks[-1]
    for a, b, r in suggest_block_parts(blocks, hints, 'edit')[-1]:
        if r == 'shot':
            _add_part(parts[-1], a, b, 'shot')
    rx = ecfg.get('latest_regex') if ecfg.get('latest') == 'regex' else (r'(?:^|[_.\-])[vV](\d+)' if ecfg.get('latest') == 'version' else '')
    if rx:
        try:
            m = re.search(rx, fname, re.I)
        except re.error:
            m = None
        if m and m.groups():
            _add_part(parts[-1], m.start(1), m.end(1), 'version')
    return parts


def _path_diagnostic_display(text):
    """Translate path diagnostics at the UI boundary, keeping stage keys and paths intact."""
    if ui_language() != 'en':
        return text
    exact = {
        '설정': 'Settings', '샷 문맥': 'Shot context', '플레이트': 'Plate',
        '편집본': 'Edit', '완료': 'Complete', '중단': 'Stopped', '스크립트': 'Script',
        '무비': 'Movie', '버전 없음': 'No version', '폴더 없음': 'Folder not found',
        '파일이': 'file', '폴더가': 'folder', '맞음': 'Matched',
        '중괄호 { } 짝이 맞지 않습니다': 'Unmatched braces { }',
        '최상위가 { } 객체가 아닙니다': 'Top level is not a { } object',
        '{shot} 이 없습니다 (샷 문맥 템플릿에는 {shot} 이 꼭 있어야 합니다)':
            'Missing {shot}; shot-context templates require {shot}.',
        '{root} 값이 없습니다 (샷 문맥 템플릿에 {root} 가 없고 roots 도 비어 있음)':
            'No {root} value: the shot-context template has no {root}, and roots is empty.',
        '절대 경로로 써 주세요 (/ 또는 드라이브 문자 C:/ 또는 //server/share 로 시작)':
            'Use an absolute path starting with /, a drive such as C:/, or //server/share.',
        '꺼져 있습니다 (enabled = false). 씬의 Read 만 씁니다':
            'Disabled (enabled = false). Only scene Reads are used.',
        '샷 문맥 템플릿이 비어 있어 서버 자동 소스가 꺼져 있습니다. 씬의 Read 만 씁니다':
            'No shot-context template. Automatic folder search is disabled; only scene Reads are used.',
        '스크립트가 저장되지 않았고 씬에 Read 도 없어 맞춰 볼 경로가 없습니다':
            'The script is unsaved and the scene has no Reads, so no path is available to test.',
        '찾지 못했습니다': 'Not found', '찾은 파일이 없습니다': 'No files found',
        '플레이트 템플릿이 비어 있습니다 (PLATE 는 씬 Read 에서 고름)':
            'No plate template (PLATE is selected from scene Reads).',
        '편집본 폴더 템플릿이 비어 있습니다 (EDIT 는 씬 Read 에서 고름)':
            'No edit-folder template (EDIT is selected from scene Reads).',
        '샷 블록이 없습니다 — 샷 이름이 들어 있는 폴더나 파일 이름 부분에 [샷]을 붙여 주세요':
            'No Shot block — assign [Shot] to the folder or filename part containing the shot name.',
        '샷 이름이 폴더에 없어 이 스크립트가 어느 샷인지 알아낼 수 없습니다 — 샷 폴더에 [샷]을 붙여 주세요':
            'The shot name is not in a folder, so the script shot cannot be identified. Assign [Shot] to the shot folder.',
        '프로젝트 / 시퀀스 / 샷': 'Project / Sequence / Shot',
        '프로젝트 / 샷 (시퀀스 없음)': 'Project / Shot (no sequence)',
        'EXR 시퀀스 (플레이트 이름 폴더)': 'EXR sequence (plate-name folder)',
    }
    if text in exact:
        return exact[text]
    # Match complete messages, never replace words inside user filenames/paths.
    # The final tuple identifies only nested diagnostic arguments, not user data.
    patterns = (
        (r"(\d+)번째 조각 '(.*)' 에서 멈춤 \(앞부분 '(.*)' 까지는 맞음\)",
         "Stopped at segment %s '%s' (prefix '%s' matched)", ()),
        (r"(\d+)번째 조각 '(.*)' 에 맞는 (파일이|폴더가) 없습니다",
         "Segment %s '%s': no matching %s", (2,)),
        (r'알 수 없는 토큰 \{(.*)\} \(쓸 수 있는 토큰: (.*), \{ext\}, \{frame\}\)',
         'Unknown token {%s} (supported: %s, {ext}, {frame})', ()),
        (r'찾은 파일 (\d+)개가 모두 조건\(레이어 · 확장자 · 최대 버전\)에서 빠졌습니다',
         'All %s files were excluded by layer, extension, or maximum-version filters.', ()),
        (r'(스크립트|Read) 경로에서 찾음: (.*)', 'Found in %s path: %s', (0,)),
        (r'템플릿: (.*)', 'Template: %s', ()),
        (r'토큰: (.*)', 'Tokens: %s', ()),
        (r'어느 경로에도 맞지 않습니다\. 기준 경로: (.*)', 'No path matched. Reference path: %s', ()),
        (r'(\d+)개 찾음\. 자동 선택: (.*)', '%s found. Automatic selection: %s', ()),
        (r'(\d+)개 찾음 \(폴더 (\d+)곳, 파일 (\d+)개 중\)\. 자동 선택: (.*)',
         '%s found (in %s folders, from %s files). Automatic selection: %s', ()),
        (r'이 샷의 편집본을 찾지 못했습니다 \(폴더 (\d+)곳, 조건에 맞는 파일 (\d+)개\)',
         'No edit found for this shot (%s folders, %s files matching the filters).', ()),
        (r'(.*)  ·  (무비|\d+-\d+)  ·  (.*?)( · 레이어 .*)?', '%s  ·  %s  ·  %s%s', (1, 2, 3)),
        (r' · 레이어 (.*)', ' · Layer %s', ()),
        (r'폴더 템플릿 (.*)  ->  (.*)', 'Folder template %s  ->  %s', (1,)),
        (r'(.*)  ->  (.*)', '%s  ->  %s', (1,)),
        (r'(.*)  \(위치: (.*)\)', '%s  (location: %s)', (0,)),
        (r'(.*) -> (.*)', '%s -> %s', (1,)),
    )
    for pattern, translated, nested in patterns:
        m = re.fullmatch(pattern, text, re.S)
        if m:
            args = list(v or '' for v in m.groups())
            for i in nested:
                args[i] = _path_diagnostic_display(args[i])
            return translated % tuple(args)
    return text


def _path_summary_display(res, cfg=None):
    """Localized summary of the unchanged path-test result."""
    if ui_language() != 'en':
        return easy_summary(res, cfg)
    tok = res.get('tok') or {}
    if res.get('stage') == '설정' and not tok:
        return 'No settings yet — choose a plate example file.'
    if not tok:
        return 'Shot not identified — check that the script or scene plate Read path follows the example layout.'
    text = 'Script shot: %s' % tok.get('shot')
    plates, edits = res.get('plates') or [], res.get('edits') or []
    if cfg is None or cfg['plate']['templates']:
        plate_text = ('%d found (automatic selection %s%s)' % (
            len(plates), plates[0]['name'], (' · ' + plates[0]['version']) if plates[0]['version'] else '')) if plates else 'not found'
        text += '  →  Plate %s' % plate_text
    if cfg is None or cfg['edit']['folders']:
        edit_text = ('%d found (latest %s)' % (len(edits), os.path.basename(edits[0]))) if edits else 'not found'
        text += ',  Edit %s' % edit_text
    return text


def easy_summary(res, cfg=None):
    """ one line of test result (plain words)"""
    tok = res.get('tok') or {}
    if res.get('stage') == '설정' and not tok:
        return '아직 설정이 없습니다 — 플레이트 예시 파일을 골라 주세요'
    if not tok:
        return '이 스크립트가 어느 샷인지 알아내지 못했습니다 — 스크립트나 씬의 플레이트 Read 경로가 예시와 같은 구조인지 확인해 주세요'
    s = '이 스크립트의 샷: %s' % tok.get('shot')
    pl, ed = res.get('plates') or [], res.get('edits') or []
    if cfg is None or cfg['plate']['templates']:
        s += '  →  플레이트 %s' % (('%d개 찾음 (자동 선택 %s%s)' % (len(pl), pl[0]['name'], (' · ' + pl[0]['version']) if pl[0]['version'] else ''))
                                if pl else '못 찾음')
    if cfg is None or cfg['edit']['folders']:
        s += ',  편집본 %s' % (('%d개 찾음 (최신 %s)' % (len(ed), os.path.basename(ed[0]))) if ed else '못 찾음')
    return s


