def _node_label_extent(n, default_font_size=16, thumbnail_height=0):
    """Estimate label bounds while Nuke still reports a fresh node's compact size."""
    import html
    import unicodedata
    try:
        value = n['label'].value() or ''
    except Exception:
        value = ''
    value = re.sub(r'(?i)<br\s*/?>', '\n', str(value))
    value = html.unescape(re.sub(r'<[^>]+>', '', value)).replace('\xa0', '')  # the NBSP added to secure width is not a character
    lines = value.splitlines() or ['']
    try:
        font_size = int(n['note_font_size'].value() or default_font_size)
    except Exception:
        font_size = default_font_size

    def visual_width(line):
        return sum(0 if unicodedata.combining(char) else
                   (2 if unicodedata.east_asian_width(char) in ('W', 'F') else 1)
                   for char in line)

    width = int(max(visual_width(line) for line in lines) * font_size * 0.48) + 32
    height = int(len(lines) * font_size * 1.35) + 24 + int(thumbnail_height)
    return width, height


def _node_rect(n):
    """ rectangle on the node graph (x0, y0, x1, y1)"""
    x, y = int(n.xpos()), int(n.ypos())
    if n.Class() == 'BackdropNode':
        try:
            return x, y, x + int(n['bdwidth'].value()), y + int(n['bdheight'].value())
        except Exception:
            pass
    try:
        w, h = int(n.screenWidth()), int(n.screenHeight())
    except Exception:
        w, h = 0, 0
    if n.Class() in ('Read', 'PostageStamp'):
        # Read labels commonly include frame range, file, timecode and resolution
        # below a thumbnail. Fresh nodes can report only their compact body size
        # until the DAG repaints, so reserve the studio-style footprint up front.
        label_w, label_h = _node_label_extent(n, 16, thumbnail_height=110)
        # Tcl expressions can be hundreds of source characters while rendering
        # to a short value. Keep the measured host width when it is already
        # larger, but do not let unevaluated label source widen a graph column.
        w, h = max(w, 180, min(label_w, 520)), max(h, 160, label_h)
    if n.Class() == 'StickyNote':
        label_w, label_h = _node_label_extent(n, 18)
        import html
        try:  # NBSP lines added to secure width are counted by width, not as characters
            pad_w = int(max(len(m) for m in re.findall('\xa0+', html.unescape(str(n['label'].value())))) * NOTE_NBSP_W)
        except Exception:
            pad_w = 0
        w, h = max(w, 260, label_w, pad_w), max(h, 120, label_h)
    return x, y, x + max(w, 80), y + max(h, 20)


def place_free(nodes, margin=24, log=print, pad=None, avoid_backdrops=False):
    """
    move a group of newly created nodes as a whole to the nearest spot that does not overlap existing nodes.
    Preferred order: below > right > left > above. Connections are kept. Backdrops are not treated as obstacles
    """
    nodes = [n for n in nodes if n is not None]
    if not nodes:
        return
    own = set(n.fullName() for n in nodes)
    R = np.array([_node_rect(n) for n in nodes], np.int64)
    gx0, gy0, gx1, gy1 = R[:, 0].min(), R[:, 1].min(), R[:, 2].max(), R[:, 3].max()
    if pad:  # the space for the backdrop must also be empty
        pl, pt, pr, pb = pad
        R = np.vstack([R, [[gx0 - pl, gy0 - pt, gx1 + pr, gy1 + pb]]])
        gx0, gy0, gx1, gy1 = gx0 - pl, gy0 - pt, gx1 + pr, gy1 + pb
    cell = 10
    X0, Y0 = gx0 - 3200, gy0 - 2200
    X1, Y1 = gx1 + 3200, gy1 + 4200
    W, H = (X1 - X0) // cell + 2, (Y1 - Y0) // cell + 2
    occ = np.zeros((H, W), np.int32)
    for n in nuke.allNodes():
        try:
            if n.fullName() in own or (n.Class() == 'BackdropNode' and not avoid_backdrops):
                continue
            a0, b0, a1, b1 = _node_rect(n)
        except Exception:
            continue
        a0, b0, a1, b1 = a0 - margin, b0 - margin, a1 + margin, b1 + margin
        if a1 < X0 or a0 > X1 or b1 < Y0 or b0 > Y1:
            continue
        c0 = max(0, (a0 - X0) // cell)
        c1 = min(W - 1, (a1 - X0) // cell + 1)
        r0 = max(0, (b0 - Y0) // cell)
        r1 = min(H - 1, (b1 - Y0) // cell + 1)
        occ[r0:r1, c0:c1] = 1
    if not occ.any():
        return
    S = np.zeros((H + 1, W + 1), np.int64)
    S[1:, 1:] = occ.cumsum(0).cumsum(1)
    dxs = np.arange(-3000, 3001, 30)
    dys = np.arange(-2000, 4001, 30)
    DX, DY = np.meshgrid(dxs, dys)
    DX, DY = DX.ravel(), DY.ravel()
    cost = np.abs(DX) * 1.2 + np.where(DY >= 0, DY, -DY * 2.5) + (DX < 0) * 30
    ok = np.ones(DX.shape, bool)
    for x0, y0, x1, y1 in R:
        c0 = (x0 + DX - X0) // cell
        c1 = (x1 + DX - X0) // cell + 1
        r0 = (y0 + DY - Y0) // cell
        r1 = (y1 + DY - Y0) // cell + 1
        inside = (c0 >= 0) & (r0 >= 0) & (c1 <= W) & (r1 <= H)
        c0, c1 = np.clip(c0, 0, W), np.clip(c1, 0, W)
        r0, r1 = np.clip(r0, 0, H), np.clip(r1, 0, H)
        tot = S[r1, c1] - S[r0, c1] - S[r1, c0] + S[r0, c0]
        ok &= inside & (tot == 0)
    if not ok.any():
        log(_t('빈 자리를 찾지 못해 기본 위치에 둡니다', 'No free space found; using the default position.'))
        return
    i = np.argmin(np.where(ok, cost, np.inf))
    dx, dy = int(DX[i]), int(DY[i])
    if dx or dy:
        for n in nodes:
            n.setXYpos(int(n.xpos()) + dx, int(n.ypos()) + dy)


BD_PAD = (20, 148, 20, 30)  # backdrop padding (left, top (label), right, bottom) - measured from an example .nk
BD_COLOR = 0x55b386ff  # green line - result created, no review warning detected
BD_REVIEW_COLOR = 0xe3a04cff  # orange line - result created, review needed
BD_FAILED_COLOR = 0xe16e6eff  # red line - creation failed


def _status_has_values(value):
    """Truthy-for-status without NumPy's ambiguous array boolean conversion."""
    if value is None:
        return False
    if isinstance(value, np.ndarray):
        if value.size == 0:
            return False
        if value.size == 1:
            try:
                return bool(value.item())
            except (TypeError, ValueError):
                return True
        return True
    try:
        return len(value) > 0
    except (TypeError, AttributeError):
        try:
            return bool(value)
        except (TypeError, ValueError):
            return True


def _status_flag(value):
    """Return (boolean value, structurally valid) for producer-owned scalar flags."""
    if isinstance(value, np.ndarray):
        if value.size != 1:
            return False, False
        try:
            value = value.item()
        except (TypeError, ValueError):
            return False, False
    elif isinstance(value, (list, tuple, dict, set)):
        return False, False
    try:
        return bool(value), True
    except (TypeError, ValueError):
        return False, False


def shot_review_reasons(res, coverage_review=False):
    """ review reason keys for one shot (the Korean originals before translation) - the backdrop, result note, batch table, and completion message all judge through this one function.
    Look state (including pending) is not a review reason (decided 2026-10-29)."""
    reasons = []

    def add(reason):
        if reason and reason not in reasons:
            reasons.append(reason)

    quality = res.get('quality')
    try:
        quality = float(quality)
        if not np.isfinite(quality):
            raise ValueError('non-finite quality')
        if quality > WARN_QUALITY:
            add('매칭 일치도 낮음')
    except (TypeError, ValueError):
        add('매칭 일치도 상태 확인 필요')
    if _status_has_values(res.get('confidence_warn')):
        add('매칭 유일성 낮음')
    if _status_has_values(res.get('lowq')):
        add('확인 필요 프레임')
    if _status_has_values(res.get('tc_mismatch')):
        add('TC 불일치')
    if _status_has_values(res.get('cuts')):
        add('분절컷 의심')
    if _status_has_values(res.get('edit_duplicates')):
        add('편집본 중복 프레임 의심')
    near_hold = res.get('near_hold')
    if isinstance(near_hold, (list, tuple)):
        try:
            if any(isinstance(span, dict) and _span_state(span) in ('ambiguous', 'unsure') for span in near_hold):
                add('정지 구간 확인 필요')
        except (TypeError, ValueError):
            add('정지 구간 상태 확인 필요')
    elif _status_has_values(near_hold):
        add('정지 구간 상태 확인 필요')
    preflight = res.get('tc_preflight')
    if preflight is not None:
        if isinstance(preflight, dict):
            pre_state = preflight.get('state')
            if not isinstance(pre_state, str):
                add('TC 사전검사 상태 확인 필요')
            elif pre_state == 'held':
                add('TC 사전검사 보류')
            elif pre_state == 'rejected':
                add('TC 사전검사 거절')
            elif pre_state == 'failed':
                add('TC 사전검사 실패')
            elif pre_state != 'ready':
                add('TC 사전검사 상태 확인 필요')
        else:
            add('TC 사전검사 상태 확인 필요')
    beta = res.get('reframe_output_beta')
    if beta is not None:
        if isinstance(beta, dict):
            beta_keys = {'requested', 'create', 'review', 'reason', 'mode', 'notice', 'risks', 'risk_detail'}
            if set(beta) - beta_keys or (beta and not any(
                    key in beta for key in ('requested', 'create', 'review'))):
                add('리프레임 Beta 상태 확인 필요')
            requested, requested_ok = _status_flag(beta.get('requested', False))
            created, created_ok = _status_flag(beta.get('create', False))
            review, review_ok = _status_flag(beta.get('review', False))
            if not (requested_ok and created_ok and review_ok):
                add('리프레임 Beta 상태 확인 필요')
            elif requested and not created:
                add('리프레임 Beta 보류')
            elif review:
                add('리프레임 Beta 검토 필요')
        elif _status_has_values(beta):
            add('리프레임 Beta 상태 확인 필요')
    # look state (including pending) is not a review reason - the backdrop is decided by the retime result alone (decided 2026-10-29).
    if res.get('excluded'):
        add('배제 구간 수동 확인')
    if any(read_input_preflight_text('%s %s' % (i.get('role', ''), i.get('node', '')), i.get('result'))
           for i in (res.get('input_warnings') or []) if isinstance(i, dict)):
        add('입력 사전검사 경고')
    if coverage_review:
        add('분할합성 미커버 영역')
    secondary = res.get('secondary_qc')
    if secondary is not None:
        if not isinstance(secondary, dict):
            add('2차 QC 상태 확인 필요')
        elif secondary.get('status') == 'review':
            add('2차 QC 밝기 차이')
        elif secondary.get('status') == 'limited':
            add('2차 QC 판정 제한')
        elif secondary.get('status') == 'error':
            add('2차 QC 검사 실패')
        elif secondary.get('status') not in ('off', 'clear'):
            add('2차 QC 상태 확인 필요')
    return reasons


def result_review_reasons(result=None, context='main'):
    """ result of one run -> tuple of translated review reasons (empty = normal). Used together by the backdrop and the completion message."""
    reasons = []

    def add(reason):
        reason = _result_reason(reason)
        if reason and reason not in reasons:
            reasons.append(reason)

    result = result if isinstance(result, dict) else {}
    if _status_has_values(result.get('warn')):
        add('실행 경고')
    items = result.get('results')
    if not isinstance(items, (list, tuple)):
        if items is not None:
            add('처리 결과 상태 확인 필요')
        items = []
    if context == 'main' and not items:
        add('처리 결과 없음')
    for item in items:
        res = item.get('res') if isinstance(item, dict) else None
        if not isinstance(res, dict):
            add('처리 결과 상태 확인 필요')
            continue
        for reason in shot_review_reasons(res, coverage_review=bool(result.get('coverage_review'))):
            add(_result_reason(reason))
    return tuple(reasons)


def backdrop_result_status(result=None, qc_grade_requested=False, failed=False, failure_reason='',
                           context='main'):
    """Structured process/review state -> visible backdrop status; never infer from display labels."""
    if failed:
        return dict(key='failed', text=_t('결과 생성 실패', 'Result creation failed'), color=BD_FAILED_COLOR,
                    reasons=(failure_reason or _t('실행 실패', 'Run failed'),))

    reasons = result_review_reasons(result, context=context)

    if reasons:
        return dict(key='review', text=_t('결과 생성됨 · 검토 필요', 'Result created · Review required'), color=BD_REVIEW_COLOR,
                    reasons=tuple(reasons))
    return dict(key='normal', text=_t('결과 생성됨', 'Result created'), color=BD_COLOR, reasons=())


INPUT_NODE_MODES = (('read', '새 Read (같은 파일·색공간·범위)'), ('stamp', 'PostageStamp (원본 참조)'))
INPUT_NODE_TIP = ('결과 백드롭 안에 둘 입력 노드\n'
                  '새 Read: 원본 Read 와 같은 파일·색공간·프레임 범위로 새로 만듦 (기본, 원본 Read 는 그대로)\n'
                  'PostageStamp: 원본 Read 를 숨은 연결로 참조 (미디어 설정은 원본을 따름)')


def input_node_mode(value=None):
    """ input node mode inside the result: 'read' (default, a new Read with the same settings as the original Read) | 'stamp' (PostageStamp referencing the original).
    Without value, follow the saved window setting (input_node)"""
    if value is None:
        value = _ui_get('input_node', 'read')
    return 'stamp' if str(value or '').strip().lower() == 'stamp' else 'read'


# Knobs not carried over from the original when creating a new Read: name / position / selection / display / callbacks / buttons
_INPUT_READ_SKIP = frozenset((
    'name', 'xpos', 'ypos', 'selected', 'hide_input', 'cached', 'postage_stamp', 'postage_stamp_frame',
    'disable', 'label', 'tile_color', 'gl_color', 'note_font', 'note_font_size', 'note_font_color',
    'dope_sheet', 'bookmark', 'icon', 'indicators', 'help', 'onCreate', 'onDestroy', 'knobChanged',
    'updateUI', 'autolabel', 'panel', 'reload', 'file', 'proxy', 'lock_connections'))
_INPUT_READ_SKIP_CLASSES = frozenset(('Tab_Knob', 'Text_Knob', 'PyScript_Knob', 'Script_Knob', 'Help_Knob',
                                      'Obsolete_Knob', 'Link_Knob', 'Button_Knob'))


def _is_default_colorspace(value):
    """True for Nuke's default colorspace display value, e.g. 'default (scene_linear)'.
    That text is a label for the unset state: writing it back makes a literal, invalid LUT name."""
    text = str(value or '').strip().strip('"').strip()
    return text == 'default' or text.startswith('default (')


def _copy_read_settings(source, read):
    """ copy the original Read's file (expression as is) -> then the remaining media knobs (range, colorspace, raw, frame mapping, format, etc.) in order.
    file must be set first so the per-file-format knobs (mov64_*, etc.) exist. Knobs with equal values are left alone"""
    read['file'].fromScript(source['file'].toScript())
    if 'proxy' in source.knobs() and 'proxy' in read.knobs():
        try:
            read['proxy'].fromScript(source['proxy'].toScript())
        except Exception:
            pass
    knobs = read.knobs()
    for key, knob in source.knobs().items():
        if key in _INPUT_READ_SKIP or key not in knobs:
            continue
        try:
            if knob.Class() in _INPUT_READ_SKIP_CLASSES:
                continue
            value = knob.toScript()
            if 'colorspace' in key.lower() and _is_default_colorspace(value):
                continue  # a default stays the new Read's own default
            if knobs[key].toScript() != value:
                knobs[key].fromScript(value)
        except Exception:
            continue


def _create_input_read(source, nodes):
    """ a new Read with the same file, colorspace and frame range as the original Read (made with createNode so callbacks/defaults match a user-made Read)"""
    read = create_user_read('', 0, 0)
    try:
        _copy_read_settings(source, read)
        read.setName(_uname(_node_name('input_' + source.name())))
    except Exception:
        nuke.delete(read)
        raise
    return _register_owned(read, nodes)


def attach_input_stamps(nodes, log=print, mode=None):
    """Put the external Reads used by the result inside it.
    mode 'read' (default) = a new Read with the same settings as the original, 'stamp' = PostageStamp referencing the original (no media settings copied)"""
    mode = input_node_mode(mode)
    sources = {}
    for node in list(nodes):
        if node is None or node.Class() not in ('TimeWarp', 'TimeOffset', 'OFlow2', 'Kronos'):
            continue
        source = node.input(0)
        if source is not None and source.Class() == 'Read' and source not in nodes:
            sources.setdefault(source, []).append(node)
    for source, consumers in sources.items():
        stamp = None
        try:
            if mode == 'read':
                stamp = _create_input_read(source, nodes)
            else:
                stamp = nuke.nodes.PostageStamp(name=_uname(_node_name('input_' + source.name())),
                                               hide_input=True, postage_stamp=True)
                _register_owned(stamp, nodes)
                stamp.setInput(0, source)
                stamp['label'].setValue(source.name() + '\n' + _t('원본 참조', 'Source reference'))
                _set(stamp, 'note_font', 'Arial')
                _set(stamp, 'note_font_size', 16)
                _set(stamp, 'tile_color', 0x40566fff)
                _set(stamp, 'note_font_color', 0xffffffff)
            stamp_height = _node_rect(stamp)[3] - _node_rect(stamp)[1]
            stamp.setXYpos(consumers[0].xpos(),
                           min(n.ypos() for n in consumers) - stamp_height - 40)
            for node in consumers:
                node.setInput(0, stamp)
        except Exception as error:
            restored = True
            for node in consumers:
                try:
                    if stamp is not None and node.input(0) is stamp:
                        node.setInput(0, source)
                except Exception as restore_error:
                    restored = False
                    log(_t('입력 참조 연결 복구 확인 필요: %s', 'Input-reference connection restoration needs review: %s') % restore_error)
            # Keep a still-connected stamp alive if a host refuses rollback.
            if stamp is not None and restored:
                try:
                    nuke.delete(stamp)
                    nodes.remove(stamp)
                except Exception as delete_error:
                    log(_t('입력 참조 정리 확인 필요: %s', 'Input-reference cleanup needs review: %s') % delete_error)
            log(_t('입력 참조 표시 보류: %s', 'Input-reference display held: %s') % error)


def _layout_result_notes(nodes, horizontal_gap=80, vertical_gap=36):
    """Stack owned result notes to the right of the generated graph and input stamps."""
    notes = [node for node in nodes if node is not None and node.Class() == 'StickyNote']
    anchors = [node for node in nodes if node is not None
               and node.Class() not in ('StickyNote', 'BackdropNode')]
    if not notes or not anchors:
        return
    right = max(_node_rect(node)[2] for node in anchors)
    top = min(_node_rect(node)[1] for node in anchors)
    x = int(right + horizontal_gap)
    y = int(top)
    for note in sorted(notes, key=lambda node: (node.ypos(), node.xpos(), node.name())):
        note.setXYpos(x, y)
        rect = _node_rect(note)
        y = int(rect[3] + vertical_gap)


def finalize_group(nodes, label, log=print, head='No More Manual Retime', status=None):
    """
    group of nodes newly created in this run -> move as a whole to an empty spot (including space for the backdrop, also avoiding existing backdrops)
    -> create a surrounding backdrop. Returns the backdrop node
    head: first line of the backdrop (for QC review, 'QC Review · N shots')
    status: return value of backdrop_result_status. State is not conveyed by color alone; it is also shown on the first line
    """
    if head == 'No More Manual Retime':
        attach_input_stamps(nodes, log)
    nodes = [n for n in nodes if n is not None and n.Class() != 'BackdropNode']
    if not nodes:
        return None
    _layout_result_notes(nodes)
    place_free(nodes, log=log, pad=BD_PAD, avoid_backdrops=True)
    R = np.array([_node_rect(n) for n in nodes])
    x0, y0 = int(R[:, 0].min()) - BD_PAD[0], int(R[:, 1].min()) - BD_PAD[1]
    x1, y1 = int(R[:, 2].max()) + BD_PAD[2], int(R[:, 3].max()) + BD_PAD[3]
    stamp = __import__('datetime').datetime.now().strftime('%Y-%m-%d %H:%M')
    state = status or backdrop_result_status(context='review_success')
    import html
    safe_head = html.escape(str(head), quote=True)
    safe_state = html.escape(str(state['text']), quote=True)
    safe_label = html.escape(str(label), quote=True)
    bd = nuke.nodes.BackdropNode(xpos=x0, ypos=y0, bdwidth=x1 - x0, bdheight=y1 - y0,
                                 # Rich-text labels may ignore note_font_color in the DAG.
                                 label='<font color="#f2f5f8"><b>%s · %s</b>\n%s\n%s</font>' % (safe_head, safe_state, safe_label, stamp),
                                 note_font='Arial', note_font_size=30, note_font_color=0xffffffff,
                                 tile_color=state['color'])
    try:
        bd['z_order'].setValue(-1)
    except Exception:
        pass
    try:
        bd['appearance'].setValue('Border')
        bd['border_width'].setValue(4.0)
    except Exception:
        pass
    return bd


def process_error_owned_nodes(error):
    """Nodes explicitly registered by process_job before a non-cancellation failure."""
    nodes = getattr(error, 'nmmr_owned_nodes', ())
    return [node for node in nodes if node is not None]


def finalize_failed_owned(error, label, log=print, head='No More Manual Retime'):
    """Group only tool-owned partial output; callback/user nodes are intentionally unreachable here."""
    nodes = process_error_owned_nodes(error)
    if not nodes:
        return None
    try:
        return finalize_group(nodes, label, log, head=head,
                              status=backdrop_result_status(
                                  failed=True, failure_reason=str(error) or '실행 실패'))
    except Exception as backdrop_error:
        log(_t('실패 결과 백드롭 생성 실패(부분 노드는 유지): %s', 'Could not create failure backdrop (partial nodes retained): %s') % backdrop_error)
        return None


def finalize_successful_owned(nodes, label, log=print, head='No More Manual Retime', status=None,
                              result=None, qc_grade_requested=False):
    """Best-effort success decoration; backdrop failure must not invalidate completed output."""
    try:
        state = status or backdrop_result_status(result, qc_grade_requested=qc_grade_requested)
        return finalize_group(nodes, label, log, head=head, status=state)
    except Exception as backdrop_error:
        log(_t('결과 백드롭 생성 실패(처리 결과는 정상): %s', 'Could not create result backdrop (processing result is valid): %s') % backdrop_error)
        return None


def _register_owned(node, owned_nodes):
    """Register a freshly created node before any knob, input, or layout operation can fail."""
    if node is not None and owned_nodes is not None and not any(item is node for item in owned_nodes):
        owned_nodes.append(node)
    return node


def _unregister_owned(node, owned_nodes):
    if owned_nodes is not None:
        owned_nodes[:] = [item for item in owned_nodes if item is not node]


def select_only(nodes):
    """ deselect everything else and select only the given nodes"""
    for n in nuke.allNodes():
        try:
            n.setSelected(False)
        except Exception:
            pass
    for n in nodes:
        try:
            n.setSelected(True)
        except Exception:
            pass


def _node_identity_is_live(node, expected_class=None):
    """Validate an exact Nuke wrapper; never substitute a same-name object."""
    if node is None:
        return False
    try:
        live_nodes = nuke.allNodes(recurseGroups=True)
    except TypeError:
        try:
            live_nodes = nuke.allNodes()
        except Exception:
            return False
    except Exception:
        return False
    if not any(candidate is node for candidate in live_nodes):
        return False
    try:
        return expected_class is None or node.Class() == expected_class
    except Exception:
        return False


def successful_owned_nodes(result, pending_nodes=()):
    """Explicit successful output plus tool-pending Reads, never a scene-wide sweep."""
    nodes = []
    for node in (result or {}).get('_owned_nodes') or ():
        if node is not None and not any(item is node for item in nodes):
            nodes.append(node)
    for pending in pending_nodes or ():
        node = pending if _node_identity_is_live(pending, 'Read') else None
        if (node is not None and node.Class() == 'Read' and
                not any(item is node for item in nodes)):
            nodes.append(node)
    return nodes


def find_read_by_file(path):
    """"""
    for n in nuke.allNodes('Read'):
        try:
            if os.path.normpath(n['file'].value()) == os.path.normpath(path):
                return n
        except Exception:
            pass
    return None


def create_user_read(path, xpos, ypos, owned_nodes=None):
    """ make the Read that stays for the user the same format as a Read the user made directly: clear all selection, then createNode('Read', inpanel=False)
    (onUserCreate callback, knobDefault applied) -> file via fromUserText (Nuke fills format / origset / auto_alpha / localizationPolicy, etc.) ->
    disconnect the input and set the position. Label and color strings are not put in the engine but follow the callback of the environment it runs in. The previous selection is restored"""
    prev = list(nuke.selectedNodes())
    for n in prev:
        n['selected'].setValue(False)
    try:
        r = _register_owned(nuke.createNode('Read', inpanel=False), owned_nodes)
        r['file'].fromUserText(path)
        r.setInput(0, None)
        r.setXYpos(int(xpos), int(ypos))
    finally:
        for n in nuke.selectedNodes():
            n['selected'].setValue(False)
        for n in prev:
            try:
                n['selected'].setValue(True)
            except Exception:  # a node deleted in the meantime
                pass
    return r


def _configure_edit_colorspace(read):
    """Choose exact supported Rec.709 input names for newly created edit Reads."""
    ocio = _root_color_value('colorManagement') == 'OCIO'
    try:
        names = nuke.getOcioColorSpaces() if ocio else nuke.getColorspaceList(read['colorspace'])
        available = {str(name).split('\t', 1)[0] for name in names if name}
    except Exception as ex:
        raise RuntimeError(_t('편집 Read 색공간 목록을 확인할 수 없습니다. '
                           '색공간을 지정한 기존 Read를 선택해 주세요: %s',
                           'Cannot list edit Read colorspaces. Select an existing Read with its colorspace set: %s') % ex)
    candidates = ('Output - Rec.709', 'rec709') if ocio else ('rec709',)
    for name in candidates:
        if name in available:
            read['colorspace'].setValue(name)
            if read['colorspace'].value() != name:
                raise RuntimeError(_t('편집 Read 색공간 적용 실패: %s', 'Could not apply edit Read colorspace: %s') % name)
            return
    # A custom config may have no equivalent Rec.709 input. Keep a valid host
    # default, never guess a similarly named camera/texture/gamma transform.
    read.format()  # resolve Nuke's lazy default label
    current = str(read['colorspace'].value())
    resolved = current[9:-1] if current.startswith('default (') and current.endswith(')') else current
    if _custom_ocio() and (current in available or resolved in available):
        print(_t('No More Manual Retime: Rec.709 입력 이름이 없어 기존 편집 Read 색공간을 유지합니다: %s', 'No More Manual Retime: No Rec.709 input name found; keeping the existing edit Read colorspace: %s') % current)
        return
    raise RuntimeError(_t('현재 설정에서 편집 Read 색공간을 확정할 수 없습니다 (%s). '
                       '색공간을 지정한 기존 Read를 선택해 주세요.',
                       'Cannot determine the edit Read colorspace in this configuration (%s). Select an existing Read with its colorspace set.') % current)


def create_edit_read(mov, xpos, ypos, reuse=False):
    """ edit Read (without Retime/Reformat - this tool handles the offset)"""
    if reuse:  # by default always load anew
        r = find_read_by_file(mov)
        if r is not None:
            return r
    r = create_user_read(mov, xpos, ypos)  # same format as a user-made Read (callbacks, defaults, fromUserText)
    try:
        _configure_edit_colorspace(r)
    except Exception:
        try:
            nuke.delete(r)  # dispose only the newly created Read
        except Exception as cleanup_error:
            print(_t('No More Manual Retime: 편집 Read 정리 실패, 노드가 남아 있습니다 (%s): %s', 'No More Manual Retime: Edit Read cleanup failed; node remains (%s): %s')
                  % (r.name(), cleanup_error))
        raise
    # Keep the host's Read label, fonts, tile color and localization policy.
    # EDIT/PLATE roles belong in the tool UI, not in a replacement studio label.
    return r


def create_plate_read(info, xpos, ypos, reuse=False):
    """
    with reuse=False, load anew even if a Read of the same file exists
    """
    if reuse:
        r = find_read_by_file(info['pattern'])
        if r is not None:
            return r
    # same format as a user-made Read: label and color are filled by the onUserCreate callback of the environment it runs in (no label string in the engine).
    # The pipeline-style label / tile_color hard-coded at were removed
    r = create_user_read(info['pattern'], xpos, ypos)
    if info.get('first') is not None:  # for a movie plate the Read decides the range
        for k, v in (('first', info['first']), ('last', info['last']), ('origfirst', info['first']), ('origlast', info['last'])):
            _set(r, k, v)  # the plate range is the scanned value as is (may differ from the fromUserText guess)
        _set(r, 'origset', True)
    return r


def _render_luma(node, d, first, last, incr, box, crop_reformat, W, H, blur, log, rgb=False):
    """ Keep transient render nodes in a visible, always-disposed Group."""
    group = None
    try:
        previous_selection = list(nuke.selectedNodes())
    except Exception:
        previous_selection = []

    def restore_selection():
        try:
            for selected in list(nuke.selectedNodes()):
                _set(selected, 'selected', False)
            for selected in previous_selection:
                _set(selected, 'selected', True)
        except Exception:
            pass

    try:
        group = nuke.nodes.Group(name=_node_name('render_tmp'))
        source_rect = _node_rect(node)
        group.setXYpos(source_rect[0], source_rect[3] + 40)
        _set(group, 'label', _t('분석 중 · 임시 노드', 'Analyzing · temporary node'))
        group.setInput(0, node)
        restore_selection()
        with group:
            source = nuke.nodes.Input()
            _render_luma_nodes(source, d, first, last, incr, box, crop_reformat,
                               W, H, blur, log, rgb)
    finally:
        try:
            if group is not None:
                nuke.delete(group)
        except Exception as cleanup_error:
            log(_t('임시 분석 노드 정리 실패: %s',
                   'Temporary analysis node cleanup failed: %s') % cleanup_error)
        finally:
            restore_selection()


def _render_luma_nodes(node, d, first, last, incr, box, crop_reformat, W, H, blur, log, rgb=False):
    """ (formerly the body of ensure_thumbs) node -> Crop(box) -> luminance (alpha) -> W x H -> EXR half"""
    tmp = []
    try:
        crop = nuke.nodes.Crop()
        crop['box'].setValue(list(box))
        _set(crop, 'crop', True)
        _set(crop, 'reformat', bool(crop_reformat))
        crop.setInput(0, node)
        if rgb:  # color for timeline preview
            ex = crop
        else:
            ex = nuke.nodes.Expression()
            _set(ex, 'channel3', 'alpha')
            _set(ex, 'expr3', '0.2126*r+0.7152*g+0.0722*b')
            ex.setInput(0, crop)
        rf = nuke.nodes.Reformat()
        _set(rf, 'type', 'to box')
        _set(rf, 'box_fixed', True)
        _set(rf, 'box_width', W)
        _set(rf, 'box_height', H)
        _set(rf, 'resize', 'distort')
        _set(rf, 'center', True)
        _set(rf, 'filter', 'Cubic')
        rf.setInput(0, ex)
        last_n = rf
        tmp = [crop, rf] + ([] if rgb else [ex])
        if blur:
            bl = nuke.nodes.Blur(size=float(blur))
            _set(bl, 'channels', 'alpha')
            bl.setInput(0, rf)
            last_n = bl
            tmp.append(bl)
        crop2 = nuke.nodes.Crop()
        crop2['box'].setValue([0, 0, W, H])
        _set(crop2, 'crop', True)
        crop2.setInput(0, last_n)
        wr = nuke.nodes.Write(file=d + '/t.######.exr', file_type='exr')
        for k in ('beforeRender', 'afterRender', 'beforeFrameRender', 'afterFrameRender'):
            if k in wr.knobs():  # remove render callbacks planted by onCreate (auto backup, etc.)
                wr[k].setValue('')
        _set(wr, 'channels', 'rgba' if rgb == 'rgba' else ('rgb' if rgb else 'alpha'))
        _set(wr, 'datatype', '16 bit half')
        _set(wr, 'compression', 'none')
        _set(wr, 'raw', True)
        _set(wr, 'create_directories', True)
        _set(wr, 'autocrop', False)
        _set(wr, 'metadata', 'no metadata')
        wr.setInput(0, crop2)
        tmp += [crop2, wr]
        nuke.execute(wr, first, last, incr, continueOnError=True)
    finally:
        for n in tmp:
            try:
                nuke.delete(n)
            except Exception:
                pass


RENDER_CHUNK = 12  # frames per nuke.execute while a window is watching
_RENDER_WATCH = None  # window callback (done, total, tag); may raise Cancelled


def set_render_watch(watch):
    """Install the progress callback for frame renders. Returns the previous one. None = single uninterrupted render."""
    global _RENDER_WATCH
    previous, _RENDER_WATCH = _RENDER_WATCH, watch
    return previous


def _watch_tick(index, count, tag):
    """Keep the watching window alive during per-frame loading loops."""
    if _RENDER_WATCH is not None and index % 48 == 0:
        _RENDER_WATCH(index, count, tag)


def render_chunks(first, last, incr, size=RENDER_CHUNK):
    """[(first, last)] covering first..last with the same frames as one render over the whole range."""
    frames = list(range(first, last + 1, incr))
    return [(frames[i], frames[min(i + size, len(frames)) - 1]) for i in range(0, len(frames), size)]


def _ensure(node, d, first, last, incr, box, crop_reformat, W, H, blur, reuse, log, tag, rgb=False):
    """"""
    import time
    d = _record_cache_dir(d)  # work on the real path, then record it as a deletion target
    # Custom OCIO can reference external LUTs whose contents are not described
    # by the config file hash. Do not reuse pixels across render requests there.
    if reuse and _custom_ocio():
        reuse = False
        log(_t('custom OCIO: 입력 LUT 변경을 반영하기 위해 썸네일을 다시 렌더합니다', 'custom OCIO: re-render thumbnails to reflect the changed input LUT'))
    frames = list(range(first, last + 1, incr))
    files = ['%s/t.%06d.exr' % (d, f) for f in frames]
    missing = [f for f, fp in zip(frames, files) if not (reuse and os.path.exists(fp))]
    if not os.path.isdir(d):
        os.makedirs(d)
    os.utime(d, None)
    if not missing:
        return 0, 0.0
    t0 = time.time()
    log('render %s %s %d-%d x%d (%d f) @%dx%d' % (tag, node.name(), missing[0], missing[-1], incr,
                                                   len(missing), W, H))
    chunks = render_chunks(missing[0], missing[-1], incr)
    if _RENDER_WATCH is None or len(chunks) < 2:
        chunks = [(missing[0], missing[-1])]
    total = len(range(missing[0], missing[-1] + 1, incr))
    done = 0
    for start, end in chunks:
        if _RENDER_WATCH is not None:
            _RENDER_WATCH(done, total, tag)
        with NoUndo():
            _render_luma(node, d, start, end, incr, box, crop_reformat, W, H, blur, log, rgb)
        done += len(range(start, end + 1, incr))
    if _RENDER_WATCH is not None:
        _RENDER_WATCH(total, total, tag)
    return len(missing), time.time() - t0


def ensure_thumbs(node, first, last, incr, W, reuse=True, log=print):
    """
    render body split out as _render_luma (shared with the ROI crop render)
    Render first~last (incr step) thumbnails if missing. Luminance 1 channel (alpha), 16bit half, uncompressed.
    Returns: number of frames actually rendered, elapsed seconds
    """
    w, h, H = _thumb_size(node, W)
    return _ensure(node, _thumb_dir(node, W), first, last, incr, (0, 0, w, h), False,
                   W, H, 1.0, reuse, log, 'thumbs')


def _roi_geom(node, roi):
    """ normalized ROI (top-left origin x0,y0,x1,y1) -> Nuke box, output W, H"""
    f = node.format()
    w, h = f.width(), f.height()
    x0, y0, x1, y1 = roi
    box = (int(round(x0 * w)), int(round((1 - y1) * h)), int(round(x1 * w)), int(round((1 - y0) * h)))
    bw, bh = max(box[2] - box[0], 4), max(box[3] - box[1], 4)
    W = int(min(640, bw))
    H = max(8, int(round(W * bh / float(bw))))
    return box, W, H


def _roi_key(roi):
    """"""
    return 'roi_' + '_'.join('%.4f' % v for v in roi)


def ensure_roi_thumbs(node, first, last, incr, roi, reuse=True, log=print):
    """ crop-render only the lagging-TC burn-in region at source resolution (no blur)"""
    box, W, H = _roi_geom(node, roi)
    return _ensure(node, _thumb_dir(node, _roi_key(roi)), first, last, incr, box, True,
                   W, H, 0, reuse, log, 'TC roi')


def _load_dir(d, frames, H, W, log):
    """"""
    arr = np.zeros((len(frames), H, W), np.float32)
    ok = np.zeros(len(frames), bool)
    for i, f in enumerate(frames):
        _watch_tick(i, len(frames), 'load')
        fp = '%s/t.%06d.exr' % (d, f)
        try:
            img = exr_luma(fp)
            hh, ww = min(H, img.shape[0]), min(W, img.shape[1])
            arr[i, :hh, :ww] = img[:hh, :ww]
            ok[i] = True
        except Exception as e:
            log('  read fail %s: %s' % (fp, e))
            try:
                os.remove(fp)  # a corrupted cache is rendered again on the next run
            except Exception:
                pass
    return arr, ok


def load_thumbs(node, frames, W, log=print):
    """"""
    return _load_dir(_thumb_dir(node, W), frames, _thumb_size(node, W)[2], W, log)


W_PREVIEW = 480


def ensure_preview(node, first, last, log=print):
    """ color thumbnails for timeline preview (W_PREVIEW width)"""
    w, h, H = _thumb_size(node, W_PREVIEW)
    return _ensure(node, _thumb_dir(node, 'prev%d' % W_PREVIEW), first, last, 1, (0, 0, w, h), False,
                   W_PREVIEW, H, 0, True, log, 'preview', rgb=True)


def load_preview(node, frames, log=print):
    """ -> (F, H, W, 3) linear, ok"""
    d = _thumb_dir(node, 'prev%d' % W_PREVIEW)
    H = _thumb_size(node, W_PREVIEW)[2]
    arr = np.zeros((len(frames), H, W_PREVIEW, 3), np.float32)
    ok = np.zeros(len(frames), bool)
    for i, f in enumerate(frames):
        _watch_tick(i, len(frames), 'load')
        try:
            ch = read_exr('%s/t.%06d.exr' % (d, f))
            keys = dict((k.split('.')[-1].upper(), k) for k in ch)
            for j, c in enumerate('RGB'):
                if c in keys:
                    a = np.nan_to_num(ch[keys[c]], nan=0.0, posinf=0.0, neginf=0.0)
                    hh, ww = min(H, a.shape[0]), min(W_PREVIEW, a.shape[1])
                    arr[i, :hh, :ww, j] = a[:hh, :ww]
            ok[i] = True
        except Exception as e:
            log('  preview read fail %d: %s' % (f, e))
    return arr, ok


def _qc_read_rgb(path, height, width, alpha=False):
    """QC fitting rejects missing, ambiguous, truncated or nonfinite channels."""
    channels = read_exr(path)
    rgb = []
    for name in ('RGBA' if alpha else 'RGB'):
        keys = [key for key in channels if key.split('.')[-1].upper() == name]
        if len(keys) != 1:
            raise ValueError('QC RGB channel missing or ambiguous: %s' % name)
        values = np.asarray(channels[keys[0]], dtype=np.float32)
        if values.shape != (height, width) or not np.isfinite(values).all():
            raise ValueError('QC RGB channel has invalid dimensions or nonfinite pixels')
        rgb.append(values)
    return np.stack(rgb, axis=-1)


def _qc_sample_rgba(node, frames, height, width, log=print, cancelled=None):
    """Fresh sparse samples of the final graph; all temporary files are owned."""
    directory = make_temp_dir('qc_samples', prefix='NMMR_qc_grade_')
    try:
        fmt = node.format()
        box = (0, 0, fmt.width(), fmt.height())
        samples = []
        for frame in frames:
            if cancelled is not None and cancelled():
                raise Cancelled()
            if node.error():
                raise ValueError('QC graph has an input error')
            _render_luma(node, directory, int(frame), int(frame), 1, box, False,
                         width, height, 0, log, rgb='rgba')
            if cancelled is not None and cancelled():
                raise Cancelled()
            if node.error():
                raise ValueError('QC graph has a render error')
            samples.append(_qc_read_rgb('%s/t.%06d.exr' % (directory, frame), height, width, alpha=True))
        return np.stack(samples)
    finally:
        remove_temp_dir(directory, 'qc_samples')


def secondary_qc_measure_chunk(plate_rgba, edit_rgba, spatial_mask, previous_edit=None):
    """Measure final Difference inputs without interpreting the retime path.

    Values are scene-linear luma residuals. Alpha and the solver's spatial
    mask must both approve a pixel. ``previous_edit`` bridges chunk boundaries
    for the low-motion limitation check.
    """
    plate = np.asarray(plate_rgba, dtype=np.float32)
    edit = np.asarray(edit_rgba, dtype=np.float32)
    mask = np.asarray(spatial_mask)
    if plate.shape != edit.shape or plate.ndim != 4 or plate.shape[-1] != 4:
        raise ValueError('secondary QC RGBA shape mismatch')
    if mask.dtype != np.bool_ or mask.shape != plate.shape[1:3]:
        raise ValueError('secondary QC mask shape or dtype is invalid')
    if not np.isfinite(plate).all() or not np.isfinite(edit).all():
        raise ValueError('secondary QC RGBA contains nonfinite values')
    prev = None if previous_edit is None else np.asarray(previous_edit, dtype=np.float32)
    if prev is not None and prev.shape != edit.shape[1:]:
        raise ValueError('secondary QC previous EDIT shape mismatch')
    weights = np.asarray((.2126, .7152, .0722), dtype=np.float32)
    plate_luma = np.sum(plate[..., :3] * weights, axis=-1)
    edit_luma = np.sum(edit[..., :3] * weights, axis=-1)
    rows = []
    previous = prev
    for index in range(len(plate)):
        valid = mask & (plate[index, ..., 3] >= .999) & (edit[index, ..., 3] >= .999)
        count = int(valid.sum())
        total = int(mask.size)
        mean_residual = p95_residual = None
        if count:
            values = np.abs(plate_luma[index] - edit_luma[index])[valid]
            mean_residual = float(values.mean())
            p95_residual = float(np.percentile(values, 95))
        motion = None
        if previous is not None:
            previous_luma = np.sum(previous[..., :3] * weights, axis=-1)
            motion_mask = valid & (previous[..., 3] >= .999)
            if motion_mask.any():
                motion = secondary_qc_block_motion(edit_luma[index], previous_luma, motion_mask)
        rows.append(dict(mean_residual=mean_residual, p95_residual=p95_residual,
                         coverage=float(count) / float(total), valid_pixels=count, motion=motion))
        previous = edit[index]
    return rows, (edit[-1].copy() if len(edit) else previous)


def secondary_qc_block_motion(current_luma, previous_luma, valid_mask, block=8):
    """Measure structured frame motion while averaging independent pixel noise.

    The second-pass QC uses this only to decide whether a low residual can be
    interpreted at all; it does not establish timing accuracy.  Mask-aware
    block means retain broad pans and camera moves, while grain and compression
    noise average down before the robust spatial median is taken.
    """
    current = np.asarray(current_luma, dtype=np.float32)
    previous = np.asarray(previous_luma, dtype=np.float32)
    mask = np.asarray(valid_mask)
    if current.shape != previous.shape or current.shape != mask.shape or current.ndim != 2:
        raise ValueError('secondary QC motion shape mismatch')
    if mask.dtype != np.bool_:
        raise ValueError('secondary QC motion mask dtype is invalid')
    size = max(2, int(block))
    values = []
    for y0 in range(0, current.shape[0], size):
        for x0 in range(0, current.shape[1], size):
            yy = slice(y0, min(y0 + size, current.shape[0]))
            xx = slice(x0, min(x0 + size, current.shape[1]))
            keep = mask[yy, xx]
            required = max(4, int(math.ceil(keep.size * .25)))
            if int(keep.sum()) < required:
                continue
            values.append(abs(float(current[yy, xx][keep].mean()) -
                              float(previous[yy, xx][keep].mean())))
    return float(np.median(values)) if values else None


def secondary_qc_classify(frame_rows, out_frames):
    """Classify brightness residuals; this never claims frame/timing accuracy."""
    rows = [dict(row) for row in frame_rows]
    frames = [int(frame) for frame in out_frames]
    if len(rows) != len(frames) or not rows:
        return dict(status='error', reason='invalid_frames', timing_claim=False,
                    checked_frames=0, frames=[], suspect_out_frames=[])
    measured_indices = [index for index, row in enumerate(rows)
                        if row.get('mean_residual') is not None and row.get('p95_residual') is not None
                        and row.get('coverage', 0.0) >= .02 and row.get('valid_pixels', 0) >= 64]
    solver_invalid_indices = [index for index, row in enumerate(rows) if row.get('solver_valid') is False]
    solver_invalid_set = set(solver_invalid_indices)
    valid_indices = [index for index in measured_indices if index not in solver_invalid_set]
    measured_set = set(measured_indices)
    unmeasured_indices = [index for index in range(len(rows)) if index not in measured_set]
    required = max(3, int(math.ceil(len(rows) * .5)))
    for index, row in enumerate(rows):
        row['out_frame'] = frames[index]
    if len(valid_indices) < required:
        return dict(status='error', reason='insufficient_coverage', timing_claim=False,
                    checked_frames=len(valid_indices), frames=rows, suspect_out_frames=[],
                    unmeasured_out_frames=[frames[index] for index in unmeasured_indices],
                    solver_invalid_out_frames=[frames[index] for index in solver_invalid_indices],
                    coverage_fraction=float(len(valid_indices)) / float(len(rows)))
    means = np.asarray([rows[index]['mean_residual'] for index in valid_indices], dtype=float)
    p95s = np.asarray([rows[index]['p95_residual'] for index in valid_indices], dtype=float)
    scores = means + .25 * p95s
    median_score = float(np.median(scores))
    mad_score = float(np.median(np.abs(scores - median_score)))
    spike_threshold = median_score + max(.012, 3.5 * 1.4826 * mad_score)
    spike_indices = [valid_indices[pos] for pos, score in enumerate(scores)
                     if score > spike_threshold and (means[pos] > .012 or p95s[pos] > .035)]
    absolute_indices = [valid_indices[pos] for pos in range(len(valid_indices))
                        if means[pos] > .035 or p95s[pos] > .10]
    median_mean = float(np.median(means))
    median_p95 = float(np.median(p95s))
    whole_high = bool(median_mean > .025 or median_p95 > .075)
    suspect_indices = sorted(set(spike_indices + absolute_indices))
    if whole_high:
        suspect_indices = list(valid_indices)
    motion = [float(rows[index]['motion']) for index in valid_indices
              if rows[index].get('motion') is not None and np.isfinite(rows[index]['motion'])]
    low_motion = len(motion) < 2 or float(np.percentile(motion, 80)) < .004
    if suspect_indices:
        status, reason = 'review', 'brightness_residual'
    elif unmeasured_indices:
        status, reason = 'limited', 'partial_coverage'
    elif solver_invalid_indices:
        status, reason = 'limited', 'solver_invalid_frames'
    elif low_motion:
        status, reason = 'limited', 'low_motion'
    else:
        status, reason = 'clear', 'residual_low'
    return dict(status=status, reason=reason, timing_claim=False,
                checked_frames=len(valid_indices), frames=rows,
                suspect_out_frames=[frames[index] for index in suspect_indices],
                unmeasured_out_frames=[frames[index] for index in unmeasured_indices],
                solver_invalid_out_frames=[frames[index] for index in solver_invalid_indices],
                spike_out_frames=[frames[index] for index in spike_indices],
                absolute_out_frames=[frames[index] for index in absolute_indices],
                median_mean_residual=median_mean, median_p95_residual=median_p95,
                median_score=median_score, mad_score=mad_score,
                spike_threshold=float(spike_threshold), whole_shot_high=whole_high,
                low_motion=bool(low_motion), coverage_fraction=float(len(valid_indices)) / float(len(rows)))


def run_secondary_qc(plate_qc, edit_qc, res, out_first, opts, log=print,
                     cancelled=None, chunk_size=24):
    """Fresh local render of final QC inputs. Errors preserve the completed retime."""
    if not opts.get('secondary_qc'):
        return dict(status='off', reason='disabled', timing_claim=False,
                    checked_frames=0, frames=[], suspect_out_frames=[])
    try:
        if plate_qc is None or edit_qc is None:
            raise ValueError('final QC inputs are unavailable')
        path = np.asarray(res.get('path'))
        if path.ndim != 1 or not len(path):
            raise ValueError('retime output frame range is invalid')
        mask = np.asarray(res.get('mask'))
        if mask.dtype != np.bool_ or mask.ndim != 2:
            raise ValueError('matching mask is invalid')
        height, width = mask.shape
        pf = plate_qc.format() if callable(getattr(plate_qc, 'format', None)) else None
        ef = edit_qc.format() if callable(getattr(edit_qc, 'format', None)) else None
        if all(hasattr(fmt, key) for fmt in (pf, ef) for key in ('width', 'height', 'pixelAspect')):
            plate_format = (int(pf.width()), int(pf.height()), float(pf.pixelAspect()))
            edit_format = (int(ef.width()), int(ef.height()), float(ef.pixelAspect()))
            if plate_format != edit_format:
                return dict(status='error', reason='format_mismatch', detail='%r != %r' % (
                    plate_format, edit_format), timing_claim=False, checked_frames=0, frames=[],
                    suspect_out_frames=[])
            display_aspect = edit_format[1] / float(edit_format[0] * edit_format[2])
            if abs(height / float(width) - display_aspect) > .01:
                return dict(status='error', reason='mask_aspect_mismatch',
                            detail='%s mask vs %s format' % ((height, width), edit_format),
                            timing_claim=False, checked_frames=0, frames=[], suspect_out_frames=[])
        tc_roi_excluded = False
        if res.get('secondary_qc_tc_roi') is not None:
            mask = mask & ~manual_roi_mask(mask.shape, res['secondary_qc_tc_roi'])
            tc_roi_excluded = True
        solver_valid = np.asarray(res.get('E_valid', np.ones(len(path), bool)))
        if solver_valid.shape != (len(path),):
            raise ValueError('solver validity shape is invalid')
        size = max(1, int(chunk_size))
        frames = list(range(int(out_first), int(out_first) + len(path)))
        measured, previous_edit = [], None
        for start in range(0, len(frames), size):
            if cancelled is not None and cancelled():
                raise Cancelled()
            chunk = frames[start:start + size]
            plate = _qc_sample_rgba(plate_qc, chunk, height, width, log=log, cancelled=cancelled)
            edit = _qc_sample_rgba(edit_qc, chunk, height, width, log=log, cancelled=cancelled)
            rows, previous_edit = secondary_qc_measure_chunk(plate, edit, mask, previous_edit)
            for offset, row in enumerate(rows):
                row['solver_valid'] = bool(solver_valid[start + offset])
            measured.extend(rows)
        result = secondary_qc_classify(measured, frames)
        result['tc_roi_excluded'] = tc_roi_excluded
        if res.get('secondary_qc_tc_roi_unavailable'):
            result['tc_roi_unavailable'] = str(res['secondary_qc_tc_roi_unavailable'])
            if result.get('status') == 'clear':
                result.update(status='limited', reason='tc_roi_unavailable')
        return result
    except Cancelled:
        raise
    except Exception as error:
        log(_t('2차 QC 검사 실패(리타임 결과 유지): %s', 'Secondary QC check failed (retime result preserved): %s') % error)
        return dict(status='error', reason='render_failed', detail=str(error), timing_claim=False,
                    checked_frames=0, frames=[], suspect_out_frames=[])


def _secondary_qc_ranges(frames, max_ranges=6):
    """Compact OUT ranges for StickyNotes and batch cells."""
    values = sorted(set(int(frame) for frame in (frames or [])))
    if not values:
        return '-'
    groups, start, previous = [], values[0], values[0]
    for value in values[1:]:
        if value == previous + 1:
            previous = value
            continue
        groups.append('%d' % start if start == previous else '%d-%d' % (start, previous))
        start = previous = value
    groups.append('%d' % start if start == previous else '%d-%d' % (start, previous))
    if len(groups) > max_ranges:
        return ', '.join(groups[:max_ranges]) + _t(', … +%d구간', ', … +%d ranges') % (len(groups) - max_ranges)
    return ', '.join(groups)


def secondary_qc_note(result):
    """Concise user-facing line; detailed metrics stay in res['secondary_qc']."""
    result = result if isinstance(result, dict) else {}
    status = result.get('status')
    if status == 'clear':
        text = _t('밝기 잔차 낮음 · %d프레임 검사', 'Low brightness residual · %d frames checked') % result.get('checked_frames', 0)
    elif status == 'review':
        suspect = result.get('suspect_out_frames') or []
        text = _t('확인 필요%s', 'Review required%s') % ((' OUT ' + _secondary_qc_ranges(suspect)) if suspect else '')
    elif status == 'limited':
        reason = result.get('reason')
        if reason == 'partial_coverage':
            text = _t('판정 제한 · 미측정 OUT ', 'Limited · Unmeasured OUT ') + _secondary_qc_ranges(result.get('unmeasured_out_frames'))
        elif reason == 'solver_invalid_frames':
            text = _t('판정 제한 · 입력 근거 없음 OUT ', 'Limited · No input evidence OUT ') + _secondary_qc_ranges(
                result.get('solver_invalid_out_frames'))
        elif reason == 'tc_roi_unavailable':
            text = _t('판정 제한 · TC 영역 제외 확인 필요', 'Limited · Check TC-region exclusion')
        else:
            text = _t('판정 제한 · 움직임이 작아 시간 일치 판단 불가',
                      'Limited · Motion is too low to judge timing')
    elif status == 'error':
        text = _t('검사 실패 · 리타임 결과 유지', 'Check failed · Retime result preserved')
    else:
        return ''
    return _t('2차 QC (Beta): %s · 프레임 정확도 판정 아님',
              'Secondary QC (Beta): %s · Not a frame-accuracy judgment') % text


def secondary_qc_batch_flag(result):
    """Short batch-table status without implying ground-truth frame accuracy."""
    result = result if isinstance(result, dict) else {}
    status = result.get('status')
    if status == 'review':
        frames = result.get('suspect_out_frames') or []
        return _t('2차 QC 확인%s', 'Secondary QC review%s') % ((' OUT ' + _secondary_qc_ranges(frames)) if frames else '')
    if status == 'limited':
        return _t('2차 QC 판정 제한', 'Secondary QC limited')
    if status == 'error':
        return _t('2차 QC 검사 실패', 'Secondary QC failed')
    if status == 'clear':
        return _t('2차 QC 잔차 낮음', 'Secondary QC residual low')
    return ''


def secondary_qc_tc_roi(project, plate_roi=None, loader=None):
    """Resolve the display TC exclusion even when TC matching itself is off."""
    if plate_roi is not None:
        return normalize_manual_roi(plate_roi)
    cfg = (loader or load_tc_cfg)(project)
    if tc_config_has_roi(cfg):
        return normalize_manual_roi(cfg['roi'])
    return None


def store_secondary_qc_metadata(created, result, log=print):
    """Persist full JSON on the owned Difference node; never fail the retime."""
    try:
        import json
        node = next((item for item in (created or []) if item.Class() == 'Merge2'
                     and _node_name_startswith(item, 'QC_diff_')), None)
        if node is None:
            raise ValueError('QC Difference node is unavailable')
        name = 'nmmr_secondary_qc'
        if name not in node.knobs():
            knob = nuke.String_Knob(name, '')
            invisible = getattr(nuke, 'INVISIBLE', None)
            if invisible is not None:
                knob.setFlag(invisible)
            node.addKnob(knob)
        payload = json.dumps(result, ensure_ascii=False, sort_keys=True,
                             separators=(',', ':'), allow_nan=False)
        node[name].setValue(payload)
        return True
    except Exception as error:
        log(_t('2차 QC 상세 저장 실패(리타임 결과 유지): %s', 'Secondary QC detail save failed (retime result preserved): %s') % error)
        return False


def _qc_fit_nodes(plate_qc, edit_qc, E_lum, res, out_first, log=print, cancelled=None):
    """Fit final output RGB at identical OUT frames, using only shared coverage."""
    held = dict(status='held', params=_qc_grade_identity(), reason='insufficient_trusted_frames')
    pairs = qc_look_anchor_pairs(E_lum, res)
    if len(pairs) < 6:
        return held
    try:
        pf, ef = plate_qc.format(), edit_qc.format()
        if (pf.width(), pf.height(), pf.pixelAspect()) != (ef.width(), ef.height(), ef.pixelAspect()):
            held['reason'] = 'qc_format_mismatch'
            return held
        height, width = np.asarray(E_lum).shape[1:]
        if abs(height / float(width) - ef.height() / float(ef.width() * ef.pixelAspect())) > .01:
            held['reason'] = 'qc_crop_not_supported'
            return held
        mask = np.asarray(res.get('mask', np.ones((height, width), bool)))
        if mask.dtype != np.bool_ or mask.shape != (height, width):
            held['reason'] = 'invalid_matching_mask'
            return held
        output_frames = [int(out_first) + t for t, _ in pairs]
        plate = _qc_sample_rgba(plate_qc, output_frames, height, width, log=log, cancelled=cancelled)
        edit = _qc_sample_rgba(edit_qc, output_frames, height, width, log=log, cancelled=cancelled)
        coverage = (plate[..., 3] >= .999) & (edit[..., 3] >= .999) & mask[None]
        result = fit_qc_grade(plate[..., :3], edit[..., :3], coverage)
        result.update(out_frames=output_frames, anchor_pairs=pairs, render_width=width,
                      coverage_fraction=float(coverage.mean()))
        return result
    except Cancelled:
        raise
    except Exception as error:
        log(_t('QC 룩 매치 보류: %s', 'QC look match held: %s') % error)
        held['reason'] = 'rgb_sample_or_fit_failed'
        return held


def load_roi_thumbs(node, frames, roi, log=print):
    """"""
    _, W, H = _roi_geom(node, roi)
    return _load_dir(_thumb_dir(node, _roi_key(roi)), frames, H, W, log)


def _guess_edit(nodes):
    def score(n):
        f = n['file'].value().lower() if 'file' in n.knobs() else ''
        s = 0
        if f.endswith(('.mov', '.mp4', '.mxf', '.avi', '.m4v')):
            s += 10
        s -= (n.lastFrame() - n.firstFrame()) * 0.001
        return s
    return sorted(nodes, key=score, reverse=True)


# automatic EDIT / PLATE detection (pure function - the input is a list of dicts, so it is tested without Nuke)
# item = dict(name, file, first, last, movie, shot) shot = shot code recognized from that path (None if none)
_SEP = r'(?:^|[\\/_.\-\s])'
_END = r'(?=$|[\\/_.\-\s\d])'
_EDIT_WORD = r'(?:ed|edit|edits|editorial)'
_PLATE_WORD = r'(?:pl|plate|plates|mp\d*)'
_EDIT_HINT = re.compile(_SEP + _EDIT_WORD + _END, re.I)
_PLATE_HINT = re.compile(_SEP + _PLATE_WORD + _END, re.I)
_DIR_HINT = re.compile(r'(?:%s|%s)(?:[_\-.]?v?\d+)?$' % (_EDIT_WORD, _PLATE_WORD), re.I)


def read_hint_text(name, fpath):
    """ hint search targets = node name + file name without extension + the nearest 3 folder levels, counting only names that are exactly a hint word
    (so the .mp4 extension does not match mp, and 'plates' inside a long folder name like auto_retime_test_plates is ignored)
    """
    d, b = os.path.split(str(fpath or '').replace('\\', '/'))
    dirs = [c for c in d.split('/')[-3:] if _DIR_HINT.match(c)]
    return ' '.join([name or '', os.path.splitext(b)[0]] + dirs)


def plate_only_hint(it):
    """ only a PLATE hint and no EDIT hint in the name / path (PL_, plate, mp / mp1 ...)"""
    txt = read_hint_text(it.get('name'), it.get('file'))
    return bool(_PLATE_HINT.search(txt)) and not _EDIT_HINT.search(txt)


def edit_score(it, ref_shot=None):
    """ larger = more EDIT-like.
    Name / path hint (ED_ edit ... +100, PL_ plate mp1 ... -100) > outside a shot folder + shot code in the file name (+20) / inside a shot folder (-20)
    > movie (+10) > the one with fewer frames
    """
    s = 0.0
    if _EDIT_HINT.search(read_hint_text(it.get('name'), it.get('file'))):
        s += 100
    if _PLATE_HINT.search(read_hint_text(it.get('name'), it.get('file'))):
        s -= 100
    if it.get('shot'):
        s -= 20
    elif ref_shot and shot_in_filename(os.path.basename(str(it.get('file') or '')), ref_shot):
        s += 20
    if it.get('movie'):
        s += 10
    return s - (it['last'] - it['first']) * 0.001


def pick_edit_plate(items):
    """ among several Reads, 1 EDIT + PLATE candidates -> (edit index, [plate indices ...]). (None, []) if there are no candidates
    PLATE candidates in the order of most plate-like (PL_ / plate / mp hints, then the longer first)
    """
    if not items:
        return None, []
    ref = next((it['shot'] for it in items if it.get('shot')), None)
    sc = [edit_score(it, ref) for it in items]
    order = sorted(range(len(items)), key=lambda i: -sc[i])
    e = order[0]
    rest = sorted((i for i in range(len(items)) if i != e),
                  key=lambda i: (sc[i], -(items[i]['last'] - items[i]['first'])))
    return e, rest


def selected_read_role(node):
    """Return an explicit EDIT/PLATE hint for a selected Read, or ``None``.

    Batch selection must not turn an arbitrary movie into a plate.  Names such
    as ``PLATE_14`` / ``EDIT_14`` and the existing path hints are strong enough;
    an unlabelled movie stays an edit-selector candidate.
    """
    item = _read_item(node)
    text = read_hint_text(item.get('name'), '')
    edit = bool(_EDIT_HINT.search(text))
    plate = bool(_PLATE_HINT.search(text))
    if not edit and not plate:
        text = read_hint_text('', item.get('file'))
        edit = bool(_EDIT_HINT.search(text))
        plate = bool(_PLATE_HINT.search(text))
    if edit == plate:
        return None
    return 'edit' if edit else 'plate'


def batch_selected_read_roles(movies, sequences):
    """Split selected Reads for Batch while keeping ambiguous movies editable.

    Image sequences retain the established plate behavior.  Explicitly named
    movie plates are added as rows, explicitly named edits become candidates,
    and ambiguous movies remain in the row's edit selector without ever being
    invented as plate rows.
    """
    edits, plates, ambiguous = [], list(sequences or ()), []
    for node in movies or ():
        role = selected_read_role(node)
        if role == 'plate':
            plates.append(node)
        else:
            edits.append(node)
            if role is None:
                ambiguous.append(node)
    return edits, plates, ambiguous


def batch_selection_plan(movies, sequences, chosen_plates=None):
    """Resolve Batch roles, or report that ambiguous movies need a plate choice.

    A single selected movie is safe to treat as the plate because the action is
    explicitly "Add selected plates" and no edit is inferred.  With multiple
    ambiguous movies the caller must provide the checked plate nodes; unchecked
    nodes remain edit-selector candidates.
    """
    movies = list(movies or ())
    edits, plates, ambiguous = batch_selected_read_roles(movies, sequences)
    if not plates and len(movies) == 1 and ambiguous == movies:
        return dict(edits=[], plates=list(movies), ambiguous=[], needs_choice=False)
    needs_choice = bool(not plates and ambiguous and chosen_plates is None)
    if chosen_plates is not None:
        chosen_ids = set(id(node) for node in chosen_plates)
        plates.extend(node for node in ambiguous if id(node) in chosen_ids)
        edits = [node for node in edits if id(node) not in chosen_ids]
        ambiguous = [node for node in ambiguous if id(node) not in chosen_ids]
    return dict(edits=edits, plates=plates, ambiguous=ambiguous, needs_choice=needs_choice)


def batch_named_pair_count(edits, plates):
    """Count explicit PLATE_n / EDIT_n name pairs selected in the graph."""
    edit_keys = set(_batch_selected_pair_key(node) for node in edits)
    plate_keys = set(_batch_selected_pair_key(node) for node in plates)
    edit_keys.discard('')
    plate_keys.discard('')
    return len(edit_keys & plate_keys)


def pick_other_plate(cands, edit_key):
    """ candidate to use instead when PLATE became equal to EDIT: the longest one that is not EDIT. cands = [(key, frame count)] -> key or None"""
    best = None
    for k, ln in cands:
        if k and k != edit_key and (best is None or ln > best[1]):
            best = (k, ln)
    return best[0] if best else None


# timeline coordinates (pure functions - thumbnail cells / ticks / playhead / click seek / exclusion, pin and cut marks all use this formula)
# Frame f occupies the cell [tl_x(f - 0.5), tl_x(f + 0.5)), and ticks, the playhead and pins stand at tl_x(f), the center of that cell.
# ef / el = first / last frame (Read frame numbers as they are, whether 1 or 1001), x0 / w = band left x / width
TL_TICK_STEPS = (1, 2, 5, 10, 20, 25, 50, 100, 200, 500, 1000, 2000, 5000)


def tl_x(f, ef, el, x0, w):
    """ x at the center of the cell of frame f (fractions allowed). The cell's left boundary = tl_x(f - 0.5)"""
    return x0 + (f - ef + 0.5) * w / float(max(1, el - ef + 1))


def tl_frame_at(x, ef, el, x0, w):
    """ frame of the cell containing x (out of range gives the end frame). tl_frame_at(tl_x(f)) == f"""
    f = ef + int(math.floor((x - x0) * max(1, el - ef + 1) / float(max(w, 1e-9)) + 1e-7))  # a boundary (left of a cell) belongs to that cell
    return min(max(f, ef), el)


def tl_tick_step(px_per, min_px=55):
    """ label tick spacing (frames): the smallest value whose spacing is at least min_px pixels"""
    for s in TL_TICK_STEPS:
        if s * px_per >= min_px:
            return s
    return TL_TICK_STEPS[-1]


def tl_cells(ef, el, px_per, tile_w, step):
    """ thumbnail cells [(first frame, last frame, representative frame)]. A cell = a group of k integer frames, starting at frames that are multiples of k
    (k is a divisor or multiple of the tick spacing step, so a tick frame is always a cell start). Representative frame = cell center.
    k = the smallest value for which the cell width is at least 0.75 of the tile width (width keeping the aspect ratio)"""
    need = 0.75 * tile_w / max(px_per, 1e-9)
    k = next((d for d in range(1, step + 1) if step % d == 0 and d >= need), None)
    if k is None:
        k = step * max(1, int(math.ceil(need / float(step))))
    out = []
    a = ef - (ef % k)
    while a <= el:
        lo, hi = max(a, ef), min(a + k - 1, el)
        out.append((lo, hi, (lo + hi) // 2))
        a += k
    return out


def _read_item(n):
    """ Read node -> pick_edit_plate input"""
    try:
        f = n['file'].value() if 'file' in n.knobs() else ''
    except Exception:
        f = ''
    return dict(name=n.name(), file=f, first=n.firstFrame(), last=n.lastFrame(), movie=_is_movie(n),
                shot=node_context(n)[2])


LOOKUP_INTERPOLATIONS = (('linear', 'Linear (기본)'), ('legacy', 'Constant / 감지된 슬로우는 Linear'))
LOOKUP_INTERPOLATION_TIP = ('매 프레임의 매칭 값은 유지하고 키 사이 연결 방식만 바꿉니다.\n'
                            'Linear: 연속 곡선. Constant: 기존 계단형, 감지된 보간 슬로우는 Linear.\n'
                            '정수 프레임 값은 동일하지만 서브프레임·모션블러 결과는 달라질 수 있습니다.')


def lookup_interpolation(value):
    return value if value in ('linear', 'legacy') else 'linear'


def _record_curve_for_redo(knob):
    """Animation edits are not recorded by Nuke's undo: without this, redo brings back an empty curve.
    Writing the same curve through the knob stores it (values keep at least 1e-4 frame precision)."""
    try:
        knob.fromScript(knob.toScript())
    except Exception:
        pass


def _apply_timewarp(tw, keys_int, slow, out_first, lookup=None, sub_spans=(), interpolation='linear'):
    """
    Default: keep a key and value on every frame and interpolate linearly. legacy is the old constant/slow linear.
    Slow segments: only start/end keys, linear (stretch)
    If lookup exists, key on every frame = lookup. Only when legacy is selected, outside sub_spans is joined as constant.
    """
    k = tw['lookup']
    k.clearAnimated()
    k.setAnimated()
    anim = k.animation(0)
    anim.clear()
    if lookup is not None:
        lin_t = set()
        for a, b in sub_spans:
            lin_t.update(range(int(a), int(b) + 1))
        const, lin = [], []
        for t, val in enumerate(lookup):
            anim.setKey(out_first + t, float(val))
        for key in anim.keys():
            (lin if lookup_interpolation(interpolation) == 'linear' or
             int(round(key.x)) - out_first in lin_t else const).append(key)
        if const:
            anim.changeInterpolation(const, nuke.CONSTANT)
        if lin:
            anim.changeInterpolation(lin, nuke.LINEAR)
        _record_curve_for_redo(k)
        return
    inside = set()
    edge = {}
    for t0, t1, v0, v1 in slow:
        for t in range(t0 + 1, t1):
            inside.add(t)
        edge[t0] = v0
        edge[t1] = v1 if t1 not in edge else edge[t1]
    lin_x = set()
    for t, val in keys_int:
        if t in inside:
            continue
        x = out_first + t
        if t in edge:
            anim.setKey(x, float(edge[t]))
            lin_x.add(x)
        else:
            anim.setKey(x, float(val))
    const, lin = [], []
    for key in anim.keys():
        (lin if lookup_interpolation(interpolation) == 'linear' or int(round(key.x)) in lin_x else const).append(key)
    if const:
        anim.changeInterpolation(const, nuke.CONSTANT)
    if lin:
        anim.changeInterpolation(lin, nuke.LINEAR)
    _record_curve_for_redo(k)


def _uname(base):
    """"""
    name = base
    i = 2
    while nuke.toNode(name) is not None:
        name = '%s_%d' % (base, i)
        i += 1
    return name


def _edit_format(edit):
    ef = edit.format()
    fmt_name = 'NMMR_%dx%d' % (ef.width(), ef.height())
    for f in nuke.formats():
        if f.name() == fmt_name:
            return f, fmt_name
    fmt = nuke.addFormat('%d %d 0 0 %d %d %s %s' % (
        ef.width(), ef.height(), ef.width(), ef.height(), ef.pixelAspect(), fmt_name))
    return fmt, fmt_name


def _reformat_to(fmt, fmt_name, resize, name, owned_nodes=None):
    rf = _register_owned(nuke.nodes.Reformat(name=_uname(name)), owned_nodes)
    if not _set(rf, 'format', fmt):
        _set(rf, 'format', fmt_name)
    _set(rf, 'resize', resize)
    _set(rf, 'center', True)
    return rf


def _region_user_config_dir():
    return os.path.realpath(os.path.expanduser('~/.nuke')).replace('\\', '/')


def region_storage_path(custom=None, user_config=None):
    """Persistent ROI-mask folder.

    A user-selected local storage folder remains authoritative.  With the
    default setting, saved Read nodes must not point into an OS-managed temp
    folder, so masks live below the user's Nuke configuration directory.
    """
    active_job = custom is None and _ACTIVE_TEMP_CUSTOM is not None
    selected = _ACTIVE_TEMP_CUSTOM if active_job else (
        str(custom or '').strip() if custom is not None
        else str(_ui_get('temp_path', '') or '').strip())
    if selected:
        base = _ACTIVE_TEMP_BASE if active_job and _ACTIVE_TEMP_BASE else temp_storage_base(selected)
        return os.path.join(base, _TEMP_NAMESPACE, 'roi_masks').replace('\\', '/')
    base = os.path.realpath(user_config or _region_user_config_dir()).replace('\\', '/')
    return os.path.join(base, _TEMP_NAMESPACE, 'roi_masks').replace('\\', '/')


def validate_region_storage(custom=None, user_config=None):
    """Create the persistent mask folder without following owned symlinks."""
    path = os.path.abspath(region_storage_path(custom, user_config=user_config))
    namespace = os.path.dirname(path)
    probe = None
    try:
        if os.path.lexists(namespace) and os.path.islink(namespace):
            raise ValueError(_t('no_more_manual_retime 폴더가 심볼릭 링크입니다',
                                'The no_more_manual_retime folder is a symbolic link'))
        if not os.path.isdir(namespace):
            os.makedirs(namespace)
        if os.path.lexists(path) and os.path.islink(path):
            raise ValueError(_t('roi_masks 폴더가 심볼릭 링크입니다',
                                'The roi_masks folder is a symbolic link'))
        if not os.path.isdir(path):
            os.makedirs(path)
        if os.path.dirname(os.path.realpath(path)) != os.path.realpath(namespace):
            raise ValueError(_t('roi_masks 폴더가 외부 위치를 가리킵니다',
                                'The roi_masks folder points outside its owned location'))
        fd, probe = tempfile.mkstemp(prefix='.write_test_', dir=path)
        os.close(fd)
        os.unlink(probe)
        probe = None
        return path.replace('\\', '/')
    except Exception as error:
        if probe:
            try:
                os.unlink(probe)
            except Exception:
                pass
        raise RuntimeError(_t('임시 저장소를 사용할 수 없습니다: %s\n'
                              '쓰기 가능한 로컬 폴더를 고르거나 [기본값]으로 되돌려 주세요. (%s)',
                              'Local storage is unavailable: %s\n'
                              'Choose a writable local folder or restore [Default]. (%s)')
                           % (path, error))


def safe_owned_output_path(path, parent):
    """Validate one tool-owned output file immediately before writing it."""
    path = os.path.abspath(path)
    parent = os.path.abspath(parent)
    if os.path.lexists(path) and os.path.islink(path):
        raise RuntimeError(_t('저장 파일이 심볼릭 링크입니다: %s',
                              'The output file is a symbolic link: %s') % path)
    if (os.path.dirname(path) != parent
            or (os.path.lexists(parent) and (not os.path.isdir(parent) or os.path.islink(parent)))
            or os.path.dirname(os.path.realpath(path)) != os.path.realpath(parent)):
        raise RuntimeError(_t('저장 파일이 도구 소유 폴더 밖을 가리킵니다: %s',
                              'The output file points outside the tool-owned folder: %s') % path)
    return path.replace('\\', '/')


def _region_dir():
    # Saved scripts keep Read nodes pointed at these EXRs. They are persistent
    # local support files, deliberately separate from auto-cleaned caches.
    return validate_region_storage()


# layout (offsets relative to the PLATE Read) - measured from the user's example .nk
LAY = dict(edit=(-350, 5), tw=(0, 188), fr=(0, 238), rf=(0, 276), tr=(0, 328),
           to=(-350, 183), mg=(-350, 328), dot=(-316, 418), mg_step=230,  # 160 -> 230 (if a look Grade exists, keep the gap to the next shot even when the Difference-Dot moves down by the Grade height) Difference-Dot gap 38 -> 90 (so it reads as a QC branch)
           report=(250, 168), summary=(-100, 68), region=(130, 238), region_rf=(130, 276))
DOT_LABEL = r'[expr {[string match "Dot*" [value name]] ? " " : [regsub {(\d+)$} [value name] ""]}]'


def build_edit_offset(edit, edit_first, out_first, plate=None, owned_nodes=None):
    """
    if a plate exists, place in the left column (-350) relative to the PLATE
    """
    to = _register_owned(nuke.nodes.TimeOffset(time_offset=out_first - edit_first,
                                               name=_uname(_node_name('EDIT_offset'))), owned_nodes)
    to.setInput(0, edit)
    if plate is not None:
        to.setXYpos(plate.xpos() + LAY['to'][0], plate.ypos() + LAY['to'][1])
    else:
        to.setXYpos(edit.xpos(), edit.ypos() + 178)
    return to


