_OUT_AVAIL = {}


def retime_node_available(kind):
    """ whether an output mode is available -> (ok, reason). Without NukeX, Kronos creates the node but its knobs are read-only"""
    if kind in ('timewarp', 'blend'):
        return True, ''
    if kind in _OUT_AVAIL:
        return _OUT_AVAIL[kind]
    cls = 'Kronos' if kind == 'kronos' else 'OFlow2'
    ok, why = True, ''
    try:
        if nuke is None:
            ok, why = False, 'Nuke 밖에서는 확인할 수 없습니다'
        elif not nuke.plugins(nuke.ALL | nuke.NODIR, cls + '*'):
            ok, why = False, '이 Nuke 에 %s 플러그인이 없습니다' % cls
        elif kind == 'kronos' and not nuke.env.get('nukex'):
            ok, why = False, ('NukeX 라이선스가 아니라 Kronos 를 설정할 수 없습니다 (노드는 생기지만 knob 이 읽기 전용).\n'
                              '같은 움직임 보간은 OFlow 로 고르세요 — 이 라이선스에서 두 결과가 같습니다')
    except Exception as e:
        ok, why = False, '확인 실패: %s' % e
    _OUT_AVAIL[kind] = (ok, why)
    return ok, why


def retime_output_node(tw, plate, kind, px, py, owned_nodes=None):
    """ output node based on tw (NMMR_timewarp, lookup curve) -> (output node, actual mode). Falls back to TimeWarp if it cannot be made"""
    if kind == 'blend':
        _set(tw, 'filter', 'box')
        return tw, 'blend'
    if kind not in ('oflow', 'kronos') or not retime_node_available(kind)[0]:
        return tw, 'timewarp'
    cls = 'Kronos' if kind == 'kronos' else 'OFlow2'
    try:
        rt = _register_owned(getattr(nuke.nodes, cls)(name=_uname(_node_name(kind))), owned_nodes)
        rt.setInput(0, plate)
        rt.setXYpos(px + LAY['tw'][0] + 110, py + LAY['tw'][1])
        rt['timing2'].setValue('Frame')
        rt['interpolation'].setValue('Motion')
        rt['timingFrame2'].setExpression('%s.lookup' % tw.name())
        rt['label'].setValue('lookup = %s' % tw.name())
        return rt, kind
    except Exception:
        try:
            nuke.delete(rt)
        except Exception:
            pass
        _unregister_owned(locals().get('rt'), owned_nodes)
        return tw, 'timewarp'


def interp_slow_spans(res):
    """ interpolated slow segments for reporting [(t0, t1, mean speed, fractional frame count)] - segments where the sub-frame lookup produced fractional values"""
    look = (timewarp_output_lookup(res) if (res.get('out_node') or 'timewarp') == 'timewarp'
            else res.get('lookup'))
    if look is None:
        return []
    look = np.asarray(look, np.float64)
    out = []
    for a, b in res.get('sub_spans') or []:
        a, b = int(a), int(b)
        if b - a + 1 < SUB_REPORT_MIN:
            continue
        nf = int(np.sum(np.abs(look[a:b + 1] - np.round(look[a:b + 1])) > 0.01))
        if nf < 3:
            continue
        out.append((a, b, float(look[b] - look[a]) / max(1, b - a), nf))
    return out


def interp_slow_report_lines(res, out_first):
    """ report line (info)"""
    sp = interp_slow_spans(res)
    if not sp:
        return []
    on = _report_detail_text(dict(OUT_NODES).get(res.get('out_node') or 'timewarp', 'TimeWarp'))
    L = [_t('보간 슬로우(정보): OUT %d-%d (%d f, 평균 %.2fx, 분수 룩업 %d f)',
            'Interpolated slow motion (info): OUT %d-%d (%d f, average %.2fx, fractional lookup %d f)') % (out_first + a, out_first + b, b - a + 1, v, nf)
         for a, b, v, nf in sp]
    L.append(_t('  출력: %s%s', '  Output: %s%s') % (on, _t(' — 파일 시퀀스 분수 룩업은 소수 부분을 버린 프레임 (고급 옵션에서 블렌드 / OFlow 출력)',
                               ' — fractional lookups for file sequences use the integer part (blend / OFlow output is available in Advanced options)')
                               if (res.get('out_node') or 'timewarp') == 'timewarp' else ''))
    return L


def interp_slow_label(res, out_first):
    """ TimeWarp label line ('' if none)"""
    sp = interp_slow_spans(res)
    if not sp:
        return ''
    a, b = sp[0][0], sp[0][1]
    return _t('보간 슬로우 %d-%d%s', 'Interpolated slow motion %d-%d%s') % (out_first + a, out_first + b, (_t(' 외 %d', ' +%d more') % (len(sp) - 1)) if len(sp) > 1 else '')


def interp_slow_status_line(results):
    """ status line tail ('  ·  ...', info)"""
    n = sum(len(interp_slow_spans(r)) for r in results)
    if not n:
        return ''
    fr = sum(b - a + 1 for r in results for a, b, _, _ in interp_slow_spans(r))
    return _t('  ·  보간 슬로우 %d구간 (%d프레임)', '  ·  Interpolated slow motion: %d ranges (%d frames)') % (n, fr)


def reframe_output_policy(opts, res):
    """Result-transform gate. This consumes solved optical data and never changes the retime solution."""
    requested = bool(opts.get('reframe_output'))
    if not requested:
        return dict(requested=False, create=False, review=False, reason='', mode='', notice='', risks=[])
    if not opts.get('optical'):
        return dict(requested=True, create=False, review=True,
                    reason='옵티컬 감지가 꺼져 있어 리프레임 출력 (Beta)을 보류했습니다', mode='', notice='', risks=[])
    if opts.get('split'):
        return dict(requested=True, create=False, review=True,
                    reason='분할합성 모드는 리프레임 출력 (Beta)을 지원하지 않아 보류했습니다', mode='', notice='', risks=[])
    if not res.get('optical'):
        return dict(requested=True, create=False, review=True,
                    reason='검증된 옵티컬 결과가 없어 리프레임 출력 (Beta)을 보류했습니다', mode='', notice='', risks=[])
    trk = res.get('track') or {}
    risks = []
    if res.get('quality', 0) > WARN_QUALITY:
        risks.append('매칭 품질 낮음')
    if res.get('confidence_warn'):
        risks.append('매칭 신뢰도 낮음')
    if res.get('lowq'):
        risks.append('낮은 품질 프레임')
    if res.get('cuts'):
        risks.append('분절컷 의심')
    nh_states = set(_span_state(span) for span in (res.get('near_hold') or []))
    if 'ambiguous' in nh_states:
        risks.append('정지 구간 구분 불가')
    if 'unsure' in nh_states:
        risks.append('정지 구간 근거 부족')
    tc = res.get('tc') or {}
    if tc.get('mode') in ('offset', 'mismatch', 'increment_mismatch'):
        risks.append('TC ' + tc.get('mode'))
    if tc.get('forced'):
        risks.append('약한 이미지에서 TC 강제')
    if tc.get('lowq_released'):
        risks.append('낮은 품질 TC 고정점 해제')
    animated = bool(trk.get('animated'))
    notice = '' if animated else ('애니메이션 추적 꺼짐 — 정적 Transform 출력' if not opts.get('track') else
                                  '검증된 애니메이션 추적 없음 — 정적 Transform 출력')
    return dict(requested=True, create=True, review=bool(risks), reason='', notice=notice, risks=risks,
                mode='animated' if animated else 'static')


def reframe_output_warning(plate_name, policy):
    if policy.get('requested') and not policy.get('create'):
        return _t('%s (리프레임 출력 Beta 보류: %s)', '%s (Reframe output Beta held: %s)') % (plate_name, _report_detail_text(policy.get('reason', '지원 조건 미충족')))
    if policy.get('review'):
        detail = ': ' + ', '.join(_report_detail_text(v) for v in (policy.get('risks') or [])) if policy.get('risks') else ''
        return _t('%s (리프레임 출력 Beta 검토 필요%s)', '%s (Reframe output Beta needs review%s)') % (plate_name, detail)
    return ''


def reframe_output_risk_detail(res, out_first):
    """Concrete OUT ranges for spatial-output risks already identified by the solver."""
    parts = []
    cuts = [int(c['t']) for c in (res.get('cuts') or [])]
    if cuts:
        parts.append(_t('분절컷 OUT ', 'Cuts OUT ') + _ranges(out_first + np.array(cuts)))
    lowq = [int(t) for t in (res.get('lowq') or [])]
    if lowq:
        parts.append(_t('낮은 품질 OUT ', 'Low quality OUT ') + _ranges(out_first + np.array(lowq)))
    spans = [span for span in (res.get('near_hold') or []) if _span_state(span) in ('ambiguous', 'unsure')]
    if spans:
        parts.append(_t('정지 구간 ', 'Hold ranges ') + ', '.join('OUT %d-%d' %
                     (out_first + int(span['t0']), out_first + int(span['t1'])) for span in spans))
    return '; '.join(parts)


def _build_optical_transform(edit, source, res, out_first, tag, px, py, beta=False, owned_nodes=None):
    """Width-fit source plus the shared optical Transform used by QC and Beta output."""
    fmt, fmt_name = _edit_format(edit)
    ef = edit.format()
    We, He = float(ef.width()), float(ef.height())
    rf = _reformat_to(fmt, fmt_name, 'width', _node_name('fit_' + tag), owned_nodes)
    rf.setInput(0, source)
    rf.setXYpos(px + LAY['rf'][0], py + LAY['rf'][1])

    o = res['optical']
    trk = res.get('track')
    tr = _register_owned(nuke.nodes.Transform(
        name=_uname(_node_name(('reframe_Beta_' if beta else 'optical_') + tag))), owned_nodes)
    tr['center'].setValue([We * 0.5, He * 0.5])
    _set(tr, 'filter', 'Cubic')
    sgn = -1.0 if o['flop'] else 1.0
    animated = trk is not None and trk.get('animated')
    if animated:
        ks, kt = tr['scale'], tr['translate']
        for kn in (ks, kt):
            kn.setAnimated(0)
            kn.setAnimated(1)
        for t in range(len(res['path'])):
            f = out_first + t
            s_, tx_, ty_ = float(trk['s'][t]), float(trk['tx'][t]), float(trk['ty'][t])
            ks.setValueAt(sgn * s_, f, 0)
            ks.setValueAt(s_, f, 1)
            kt.setValueAt(tx_ * We, f, 0)
            kt.setValueAt(-ty_ * We, f, 1)
    else:
        s_ = float(o['s'])
        try:
            tr['scale'].setValue([sgn * s_, s_])
        except Exception:
            tr['scale'].setValue(sgn * s_, 0)
            tr['scale'].setValue(s_, 1)
        tr['translate'].setValue([float(o['tx']) * We, -float(o['ty']) * We])
        if o.get('note') == 'identity':
            tr['disable'].setValue(True)
    if beta:
        policy = res.get('reframe_output_beta') or reframe_output_policy(
            {'reframe_output': True, 'optical': True, 'split': False}, res)
        review = policy['review']
        risks = policy.get('risks') or []
        detail = policy.get('risk_detail') or ''
        tr['label'].setValue('Reframe Output (Beta) — %s%s' % (
            'animated' if animated else 'static',
            (_t('\n검토 필요: ', '\nReview required: ') +
             _report_detail_text(detail or ', '.join(risks))) if review else ''))
    elif animated:
        tr['label'].setValue('animated optical')
    tr.setInput(0, rf)
    tr.setXYpos(px + LAY['tr'][0], py + LAY['tr'][1])
    return rf, tr


def qc_transform_node(created, beta=False):
    """Return the exact optical Transform handle, avoiding unrelated Transform nodes."""
    suffix = 'reframe_Beta_' if beta else 'optical_'
    return next((node for node in created if node.Class() == 'Transform'
                 and _node_name_startswith(node, suffix)), None)


def _apply_qc_grade_branch(created, tr, look, tag=''):
    """Change only owned Difference inputs; keep retime and Beta output handles.
    The validated Grade sits at the end of the output tree (below the Transform), enabled;
    QC Difference compares after it.
    """
    if tr is None or look.get('status') != 'applied':
        return tr, None
    differences = [node for node in created if node.Class() == 'Merge2'
                   and _node_name_startswith(node, 'QC_diff_') and node.input(0) is tr]
    if not differences:
        return tr, None
    params = look['params']
    apply_qc_grade_rgb(np.zeros((1, 3)), params)  # validate before making a node
    grade = None
    try:
        grade = nuke.nodes.Grade(name=_uname(_node_name('look_' + tag if tag else 'look_Grade')), channels='rgb',
                                 black_clamp=False, white_clamp=False)
        # Explicitly reset user knob defaults / onCreate choices to the fitted model.
        for key, value in (('reverse', False), ('disable', False), ('channels', 'rgb'),
                           ('black_clamp', False), ('white_clamp', False),
                           ('blackpoint', 0), ('whitepoint', 1), ('black', 0), ('white', 1),
                           ('mix', 1), ('maskChannelInput', 'none'), ('maskChannelMask', 'none'),
                           ('invert_mask', False), ('inject', False),
                           ('unpremult', 'none'), ('invert_unpremult', False)):
            if hasattr(grade[key], 'clearAnimated'):
                grade[key].clearAnimated()
            grade[key].setValue(value)
        grade.setInput(0, tr)
        grade.setInput(1, None)
        for key in ('multiply', 'add', 'gamma'):
            grade[key].clearAnimated()
            for channel, value in enumerate(params[key]):
                grade[key].setValue(float(value), channel)
        grade['label'].setValue(_t('QC 룩 매치', 'QC look match'))
        try:  # keep long descriptions in tooltips rather than on the node graph
            grade['multiply'].setTooltip(_t(
                'QC 비교용 룩 매치 Grade(신뢰 프레임으로 맞추고 별도 프레임으로 확인). QC Difference를 더 또렷하게 보려는 용도이며 편집본 룩 출력용이 아님 · 원본 톤으로 렌더하려면 disable.',
                'Look-match Grade for QC (fitted on trusted frames, checked on separate frames). It makes the QC Difference easier to read and is not meant to output the edit look; disable it to render the original plate tone.'))
        except Exception:
            pass
        grade.setXYpos(tr.xpos(), tr.ypos() + 60)
        for node in differences:
            node.setInput(0, grade)
        created.append(grade)
        align_qc_diff_to_input(differences, grade, created)
        return grade, grade
    except Exception:
        for node in differences:
            node.setInput(0, tr)
        if grade is not None:
            nuke.delete(grade)
        raise


def _node_height(node):
    try:
        return int(node.screenHeight())
    except Exception:
        return 0


def align_qc_diff_to_input(differences, plate_node, created=()):
    """ make the plate (B) input line of the QC Difference horizontal: Merge center y = center y of the plate node (look Grade or Transform).
    The Dot below the Merge moves down by the same amount to keep the gap."""
    for mg in differences:
        want = plate_node.ypos() + (_node_height(plate_node) - _node_height(mg)) // 2
        delta = int(want - mg.ypos())
        if not delta:
            continue
        mg.setXYpos(mg.xpos(), mg.ypos() + delta)
        for dot in created:
            if dot.Class() == 'Dot' and dot.input(0) is mg:
                dot.setXYpos(dot.xpos(), dot.ypos() + delta)


def run_done_headline(outcome, ok=None, total=None, secs=None, cancelled=False):
    """ the first line of the status line when a run finishes. Symbol + text (color is conveyed separately by the dot / close button)"""
    spent = '' if secs is None else _t(' · %.1f초', ' · %.1f s') % secs
    if cancelled:
        return _t('■ 취소됨', '■ Cancelled') + spent
    if outcome == 'err':
        return _t('✕ 실패', '✕ Failed') + spent
    counted = total is not None and ok is not None and total > 0
    if outcome == 'ok':
        if counted:
            return _t('✓ 완료 — %d샷 중 %d샷 성공', '✓ Done — %d shots, %d succeeded') % (total, ok) + spent
        return _t('✓ 완료', '✓ Done') + spent
    need = (total - ok) if counted else 0
    if counted and need > 0:
        if ok <= 0:
            return _t('! 완료 — %d샷 확인 필요', '! Done — %d shots need review') % need + spent
        return _t('! 완료 — %d샷 중 %d샷 성공 · %d샷 확인 필요',
                  '! Done — %d shots, %d succeeded · %d need review') % (total, ok, need) + spent
    return _t('! 완료 — 확인 필요', '! Done — review needed') + spent


def run_done_detail(existing):
    """ from the existing status text, cut off the leading 'Done - N plates' style head and keep only the extra information after it"""
    text = existing or ''
    for lead in ('완료', 'Complete', '배치 완료', 'Batch complete', '취소됨', 'Cancelled'):
        if text.startswith(lead):
            return text.split('  ·  ', 1)[1] if '  ·  ' in text else ''
    for lead in ('실패 — ', 'Failed — '):
        if text.startswith(lead):
            return text[len(lead):]
    return text


def run_done_status_text(headline, existing):
    detail = run_done_detail(existing)
    return headline + ('  ·  ' + detail if detail else '')


def run_has_result(outcome, counts, cancelled):
    """ a warning that returned right at the validation stage (EDIT not specified, etc.) is not 'finished'"""
    if outcome == 'idle':
        return False
    return outcome in ('ok', 'err') or bool(cancelled) or counts is not None


def configure_qc_look(created, tr, edit_qc, E_lum, res, out_first, opts,
                      box=None, log=print, cancelled=None, tag=''):
    """Optional shared single/batch QC branch; never feeds the retime solver."""
    look = dict(status='off', params=_qc_grade_identity(), reason='disabled')
    if qc_look_requested(opts):
        look.update(status='held', reason='qc_disabled')
        if opts.get('split') or box is not None or res.get('region') is not None:
            look['reason'] = 'region_not_supported'
        elif tr is not None and edit_qc is not None:
            try:
                look = _qc_fit_nodes(tr, edit_qc, E_lum, res, out_first, log, cancelled)
                graded, grade = _apply_qc_grade_branch(created, tr, look, tag=tag)
                if look['status'] == 'applied' and grade is None:
                    look.update(status='held', params=_qc_grade_identity(), reason='qc_branch_missing')
                res['qc_look'] = look
                return graded, grade
            except Cancelled:
                raise
            except Exception as error:
                log(_t('QC 룩 매치 보류: %s', 'QC look match held: %s') % error)
                look = dict(status='held', params=_qc_grade_identity(), reason='qc_grade_failed')
    res['qc_look'] = look
    return tr, None


def timewarp_output_lookup(res):
    """Keep verified TC source frames for integer output after the guarded track retry.

    Fractional reconstruction remains intact for blend and motion-interpolated outputs.
    """
    if res.get('lookup') is None:
        return None
    lookup = np.asarray(res['lookup'], float).copy()
    tc = res.get('tc') or {}
    if not res.get('tc_track_retry') or tc.get('mode') != 'first' or tc.get('forced'):
        return lookup
    path = np.asarray(res.get('path'))
    if path.ndim != 1 or lookup.shape != path.shape:
        return lookup
    for t, q in (res.get('tc_track_verified') or {}).items():
        if 0 <= t < len(path) and np.isfinite([path[t], q]).all() and path[t] == q:
            lookup[t] = float(path[t])
    return lookup


def build_nodes(edit, plate, res, plate_first, out_first, edit_qc=None, qc_anchor=None, qc_index=0,
                out_node='timewarp', reframe_output=False, owned_nodes=None, interpolation='linear'):
    """
    under plate: TimeWarp + FrameRange
    if edit_qc (TimeOffset) exists: Reformat -> optical Transform -> difference (split-region mask)
    """
    path = res['path']
    E = len(path)
    out_last = out_first + E - 1
    px, py = plate.xpos(), plate.ypos()
    tag = plate.name()

    tw = _register_owned(nuke.nodes.TimeWarp(name=_uname(TIMEWARP_NODE_NAME)), owned_nodes)
    tw.setInput(0, plate)
    tw.setXYpos(px + LAY['tw'][0], py + LAY['tw'][1])
    _set(tw, 'filter', 'none')
    keys = [(t, plate_first + int(path[t])) for t in range(E)]
    slow = [(t0, t1, plate_first + v0, plate_first + v1) for t0, t1, v0, v1 in res['slow']]
    look = res.get('lookup')  # sub-frame lookup
    _apply_timewarp(tw, keys, slow, out_first, None if look is None else [plate_first + float(v) for v in look],
                    res.get('sub_spans') or (), interpolation=interpolation)
    src, out_node = retime_output_node(tw, plate, out_node, px, py, owned_nodes)
    if out_node == 'timewarp' and res.get('tc_track_retry'):
        integer_look = timewarp_output_lookup(res)
        if integer_look is not None:
            _apply_timewarp(tw, keys, slow, out_first,
                            [plate_first + float(v) for v in integer_look], res.get('sub_spans') or (),
                            interpolation=interpolation)
    res['out_node'] = out_node
    res['lookup_interpolation'] = lookup_interpolation(interpolation)
    nh_lab = near_hold_label(res.get('near_hold') or [], out_first)  # second line
    is_lab = interp_slow_label(res, out_first)  # interpolated slow (info)
    tw['label'].setValue('AUTO %d-%d' % (out_first, out_last) + ''.join('\n' + x for x in (nh_lab, is_lab) if x) +
                         ('' if src is tw else '\n-> %s' % src.name()))

    fr = _register_owned(nuke.nodes.FrameRange(first_frame=out_first, last_frame=out_last,
                                               name=_uname(_node_name('range_' + tag))), owned_nodes)
    fr.setInput(0, src)
    fr.setXYpos(px + LAY['fr'][0], py + LAY['fr'][1])
    created = [tw, fr] + ([src] if src is not tw else [])
    if edit_qc is None and not reframe_output:
        return created

    rf, tr = _build_optical_transform(edit, fr, res, out_first, tag, px, py, beta=reframe_output,
                                      owned_nodes=owned_nodes)
    created += [rf, tr]
    if edit_qc is None:
        return created

    # the QC difference goes in the EDIT column (below TimeOffset) + output Dot
    ax, ay = (qc_anchor.xpos(), qc_anchor.ypos()) if qc_anchor is not None else (px, py)
    dy = LAY['mg_step'] * qc_index
    mg = _register_owned(nuke.nodes.Merge2(
        operation='difference', name=_uname(_node_name('QC_diff_' + tag))), owned_nodes)
    mg.setInput(0, tr)  # B = plate
    mg.setInput(1, edit_qc)  # A = edit
    mg.setXYpos(ax + LAY['mg'][0], ay + LAY['mg'][1] + dy)
    dot = _register_owned(nuke.nodes.Dot(), owned_nodes)
    dot.setInput(0, mg)
    dot.setXYpos(ax + LAY['dot'][0], ay + LAY['dot'][1] + dy)
    _set(dot, 'label', DOT_LABEL)
    _set(dot, 'note_font_size', 30)
    created += [mg, dot]

    # split composite: reference mask of this plate's region
    if res.get('region') is not None:
        reg = res['region'].astype(np.float32)
        for _ in range(2):
            reg = blur121(reg)
        fp = '%s/%s_%s.exr' % (_region_dir(), tag,
                               hashlib.md5(reg.tobytes()).hexdigest()[:10])
        safe_owned_output_path(fp, os.path.dirname(fp))
        write_exr_alpha(fp, reg)
        rd = create_user_read(fp, px + LAY['region'][0], py + LAY['region'][1], owned_nodes)
        rd.setName(_uname(_node_name('region_' + tag)))
        _set(rd, 'raw', True)
        fmt, fmt_name = _edit_format(edit)
        rr = _reformat_to(fmt, fmt_name, 'distort', _node_name('region_fit_' + tag), owned_nodes)
        rr.setInput(0, rd)
        rr.setXYpos(px + LAY['region_rf'][0], py + LAY['region_rf'][1] + 50)
        mg.setInput(2, rr)
        created += [rd, rr]
    return created


def output_timecode_plan(edit_tc, edit_fps, plate_base=None, plate_offset=0):
    """ start TC of AddTimeCode in the output tree. Output frames map 1:1 to EDIT frames, so the EDIT TC is the correct one.
    edit_tc: input/timecode of the first EDIT frame (None if none). A movie Reader gives 00:00:00:00 when there is no TC track, so
    if it is 0, use the plate TC first, and if there is none either, EDIT's 00:00:00:00.
    plate_base: result of plate_tc_base (fps, plate first-frame count, ...) | None, plate_offset: plate frame of the first output frame - plate first frame.
    Returns dict(source 'edit' | 'plate' | 'none', startcode, fps, frames)"""
    fps = float(edit_fps or 24.0)
    count = tc_to_frames(edit_tc, fps) if edit_tc else None
    if count:
        return dict(source='edit', startcode=frames_to_tc(count, fps), fps=fps, frames=count)
    if plate_base:
        pfps, b0 = float(plate_base[0] or fps), int(plate_base[1])
        if not (len(plate_base) > 2 and plate_base[2] is True):  # (fps, 0, True) = provisional value, no metadata
            n = b0 + int(plate_offset)
            return dict(source='plate', startcode=frames_to_tc(n, pfps), fps=pfps, frames=n)
    if count == 0:
        return dict(source='edit', startcode=frames_to_tc(0, fps), fps=fps, frames=0)
    return dict(source='none', startcode=frames_to_tc(0, fps), fps=fps, frames=0)


def output_timecode_message(plan, out_first):
    """Text node message: a running timecode, TCL only so it renders on any machine.
    The first output frame shows plan['startcode']."""
    rate = max(1, int(round(float(plan['fps']))))
    count = '(%d+[frame]-%d)' % (int(plan['frames']), int(out_first))
    return ('[format %%02d:%%02d:%%02d:%%02d [expr %(n)s/%(h)d] [expr (%(n)s/%(m)d)%%60] '
            '[expr (%(n)s/%(r)d)%%60] [expr %(n)s%%%(r)d]]') % dict(n=count, h=rate * 3600, m=rate * 60, r=rate)


def output_timecode_label(plan, out_first):
    """ output TC node label: which TC it came from + the first output frame"""
    if plan['source'] == 'edit':
        return _t('EDIT TC %s @ %d', 'EDIT TC %s @ %d') % (plan['startcode'], out_first)
    if plan['source'] == 'plate':
        return _t('PLATE TC %s @ %d\n(EDIT TC 없음)', 'PLATE TC %s @ %d\n(no EDIT TC)') % (plan['startcode'], out_first)
    return _t('TC 없음 · %s @ %d', 'No TC · %s @ %d') % (plan['startcode'], out_first)


def output_tree_tail(created, grade=None):
    """ end of the output tree: look Grade > reframe Beta Transform > optical Transform > FrameRange"""
    if grade is not None:
        return grade
    for suffix in ('reframe_Beta_', 'optical_'):
        node = next((n for n in created if n.Class() == 'Transform' and _node_name_startswith(n, suffix)), None)
        if node is not None:
            return node
    return next((n for n in created if n.Class() == 'FrameRange' and _node_name_startswith(n, 'range_')), None)


def add_output_timecode(created, tail, edit, plate, edit_first, plate_first, res, out_first,
                        owned_nodes=None, log=print):
    """Text overlay (NMMR_timecode_<PLATE>) at the end of the output tree, after the QC branch point so QC is unaffected:
    the running EDIT TC (first output frame = TC of the first EDIT frame). If the EDIT TC is unknown, the TC of the plate frame
    used by the first output frame + shown in the label. Returns (node, plan)"""
    if tail is None:
        return None, None
    try:
        edit_tc = edit.metadata('input/timecode', edit_first)
    except Exception:
        edit_tc = None
    edit_fps = node_fps(edit, edit_first)
    try:
        base = plate_tc_base(plate, plate.firstFrame(), plate.lastFrame(), log=lambda *_: None)
    except Exception:
        base = None
    offset = int(plate_first) + int(res['path'][0]) - int(plate.firstFrame())
    plan = output_timecode_plan(edit_tc, edit_fps, base, offset)
    fmt = edit.format()
    size = max(10, int(round(fmt.height() * 0.03)))
    margin = max(4, int(round(fmt.height() * 0.02)))
    node = _qc_text_node(tail, output_timecode_message(plan, int(out_first)),
                         (margin, margin, fmt.width() - margin, margin + size * 2), True, False, size,
                         (1, 1, 1), _qc_fonts()[0], _node_name('timecode_' + plate.name()), owned_nodes)
    _set(node, 'label', output_timecode_label(plan, int(out_first)))
    node.setXYpos(tail.xpos(), tail.ypos() + 60)
    created.append(node)
    res['output_tc'] = dict(plan)
    if plan['source'] != 'edit':
        log(_t('[%s] EDIT TC 없음 — 출력 TC 노드는 %s', '[%s] No EDIT TC — output TC node uses %s') % (
            plate.name(), _t('플레이트 TC', 'the plate TC') if plan['source'] == 'plate' else '00:00:00:00'))
    return node, plan


def match_score(cost):
    """ matching cost -> (match %, grade). 0 = same picture 100%, unrelated picture 0%"""
    if cost is None:
        return None, ''
    pct = int(round(max(0.0, min(1.0, 1.0 - cost / COST_RANDOM)) * 100))
    grade = (_t('좋음', 'Good') if cost <= GOOD_QUALITY else
             (_t('보통', 'Fair') if cost <= WARN_QUALITY else _t('낮음', 'Low')))
    return pct, grade


def score_text(cost):
    pct, grade = match_score(cost)
    return '-' if pct is None else '%d%% (%s)' % (pct, grade)


def match_warning_message(low, conf, split=False, bullet=False):
    """Warning text after a run. `low`: plates whose similarity itself is low; `conf`: plates whose
    similarity is Good/Fair but whose confidence is low. The two get different headlines and advice."""
    join = (lambda items: '\n  ' + '\n  '.join(items)) if bullet else (lambda items: ', '.join(items))
    tail = (lambda head: head.rstrip()) if bullet else (lambda head: head)
    msgs = []
    if low:
        msgs.append(tail(_t('매칭 일치도가 낮습니다: ', 'Low matching similarity: ')) + join(low) +
                    ('' if split else
                     _t('\n분할합성 / 템프합성 샷이면 분할합성 모드로, 회전·가변 스케일 구간은 배제한 뒤 다시 실행해 주세요',
                        '\nUse split-composite mode for split or temporary composites. Exclude rotation or variable-scale ranges, then run again.')))
    if conf:
        msgs.append(tail(_t('일치도는 양호하지만 신뢰도가 낮은 구간이 있습니다: ',
                           'Similarity looks good but some frames are low confidence: ')) + join(conf) +
                    _t('\nQC 에서 해당 샷의 낮은 신뢰도 구간을 확인해 주세요',
                       '\nCheck the low-confidence frames of these shots in QC.'))
    return '\n\n'.join(msgs)


