def _english_report_line(line):
    line = str(line)
    for ko, en in _REPORT_FRAGMENT_EN:
        line = line.replace(ko, en)
    if _contains_hangul(line):
        # Unknown producer detail must not leak a mixed-language sentence into EN output.
        tokens = re.findall(r'(?:[A-Za-z_][A-Za-z0-9_.-]*|[-+]?\d+(?:\.\d+)?%?|→|->)', line)
        return 'Additional review detail' + (': ' + ' '.join(tokens) if tokens else '')
    return line


def _report_detail_text(value):
    """Translate display details without changing persisted solver/policy strings."""
    value = str(value)
    if ui_language() != 'en':
        return value
    exact = {
        '지원 조건 미충족': 'requirements not met',
        '옵티컬 감지가 꺼져 있어 리프레임 출력 (Beta)을 보류했습니다': 'optical detection is disabled',
        '분할합성 모드는 리프레임 출력 (Beta)을 지원하지 않아 보류했습니다': 'split-composite mode does not support Reframe output (Beta)',
        '검증된 옵티컬 결과가 없어 리프레임 출력 (Beta)을 보류했습니다': 'no validated optical result is available',
        '매칭 품질 낮음': 'low matching quality',
        '매칭 신뢰도 낮음': 'low matching confidence',
        '낮은 품질 프레임': 'low-quality frames',
        '분절컷 의심': 'possible cut',
        '정지 구간 구분 불가': 'indistinguishable hold frames',
        '정지 구간 근거 부족': 'insufficient hold evidence',
        '약한 이미지에서 TC 강제': 'TC forced despite weak image evidence',
        '낮은 품질 TC 고정점 해제': 'low-quality TC anchors released',
        '애니메이션 추적 꺼짐 — 정적 Transform 출력': 'animated tracking disabled — static Transform output',
        '검증된 애니메이션 추적 없음 — 정적 Transform 출력': 'no validated animated track — static Transform output',
        '시간-이동 모호(플레이트 팬/틸트 + 리포지션 이동 애니메이션 — 경로 확인 권장)':
            'time/translation ambiguity (plate pan/tilt + animated repositioning — review the path)',
        '좋음': 'Good', '보통': 'Fair', '낮음': 'Low',
        'TimeWarp (정수 프레임)': 'TimeWarp (integer frames)',
        '프레임 블렌드': 'Frame blend',
    }
    if value in exact:
        return exact[value]
    patterns = (
        (r'^모호 프레임 (\d+)%$', r'ambiguous frames \1%'),
        (r'^품질 낮은 프레임 (\d+)%$', r'low-quality frames \1%'),
        (r'^상하 절반 합의 (\d+)%$', r'upper/lower-half agreement \1%'),
        (r'^스케일 범위 밖\(필러/레터박스 의심, 탐색 ([\d.]+)~([\d.]+)\)$',
         r'outside scale range (possible pillarbox/letterbox, searched \1~\2)'),
    )
    for pattern, replacement in patterns:
        if re.match(pattern, value):
            return re.sub(pattern, replacement, value)
    if re.match(r'^(?:분절컷 OUT|낮은 품질 OUT|정지 구간 OUT) ', value):
        for ko, en in (('분절컷 OUT ', 'Cuts OUT '), ('낮은 품질 OUT ', 'Low quality OUT '), ('정지 구간 OUT ', 'Hold ranges OUT ')):
            value = value.replace(ko, en)
    # Spatial location strings are internal solver values; localize only here.
    if re.match(r'^(?:(?:상단|하단)(?: (?:좌측|우측))?|좌측|우측|중앙)$', value):
        for ko, en in (('상단', 'top'), ('하단', 'bottom'), ('좌측', 'left'), ('우측', 'right'), ('중앙', 'center')):
            value = value.replace(ko, en)
    return value


def report_text(res, edit, plate, edit_first, plate_first, out_first):
    """
    split region / optical animation notation
    """
    path = res['path']
    E = len(path)
    o = res['optical']
    ew = edit.format().width()
    L = []
    L.append('No More Manual Retime v%s  [%s]' % (NMMR_DISPLAY_VERSION, plate.name()))
    L.append('EDIT  %s  %d-%d (%d f)' % (edit.name(), edit_first, edit_first + E - 1, E))
    L.append('OUT   %d-%d' % (out_first, out_first + E - 1))
    L.append(_t('첫 프레임: EDIT %df → PLATE %df', 'First frame: EDIT %df → PLATE %df') % (edit_first, plate_first + int(path[0])))
    a3_line = _a3_retry_text(res)
    if a3_line:
        L.append(a3_line)
    for item in res.get('input_warnings') or []:
        message = read_input_preflight_text('%s %s' % (item.get('role', ''), item.get('node', '')),
                                            item.get('result'))
        if message:
            L.append('[!] ' + message)
    sp_ = res.get('split') or {}
    if res.get('manual_region_rect'):
        r = res['manual_region_rect']
        L.append(_t('수동 PLATE 영역 (Beta): x %.1f–%.1f%% / y %.1f–%.1f%% · 원본 %s',
                    'Manual PLATE region (Beta): x %.1f–%.1f%% / y %.1f–%.1f%% · source %s') % (
            100 * r[0], 100 * r[2], 100 * r[1], 100 * r[3],
            res.get('manual_region_plate') or plate.name()))
    if sp_.get('split'):
        L.append(_t('분할합성 감지: 이 플레이트 영역 %s %.0f%%', 'Split composite detected: this plate region %s %.0f%%') % (_report_detail_text(sp_['where']), sp_['frac'] * 100))
    trk = res.get('track')
    if trk is not None and trk.get('animated'):
        L.append(_t('옵티컬 애니메이션: scale %.3f -> %.3f, translate 범위 %.1f px%s',
                    'Optical animation: scale %.3f -> %.3f, translation range %.1f px%s') % (
            trk['s'][0], trk['s'][-1],
            max(np.ptp(trk['tx']), np.ptp(trk['ty'])) * ew, '  FLOP' if trk['flop'] else ''))
    elif o.get('identity_fallback'):
        L.append(_t('옵티컬: 쓸 수 있는 템플릿 없음, identity로 처리', 'Optical: no usable template, processed as identity'))
    elif o.get('note') == 'identity':
        L.append(_t('옵티컬: 없음', 'Optical: none'))
    else:
        L.append(_t('옵티컬: scale %.4f  translate %.1f %.1f px%s', 'Optical: scale %.4f  translate %.1f %.1f px%s') % (
            o['s'], o['tx'] * ew, -o['ty'] * ew, '  FLOP' if o['flop'] else ''))
    qcr = res.get('qc_refine')
    if qcr:
        L.append(_t('고해상도 옵티컬 정밀화: %d앵커 @%dpx (NCC +%.4f)',
                    'High-resolution optical refinement: %d anchors @%dpx (NCC +%.4f)') % (
            qcr['anchors'], qcr['width'], qcr.get('gain', 0.0)))
    beta = res.get('reframe_output_beta') or {}
    if beta.get('create'):
        L.append(_t('리프레임 출력 (Beta): %s Transform%s', 'Reframe output (Beta): %s Transform%s') % (
            _t('애니메이션', 'animated') if beta.get('mode') == 'animated' else _t('정적', 'static'),
            (_t(' — [!] 검토 필요: ', ' — [!] review required: ') + ', '.join(_report_detail_text(v) for v in (beta.get('risks') or []))) if beta.get('review') else ''))
        if beta.get('risk_detail'):
            L.append(_t('  Beta 검토 구간: %s', '  Beta review range: %s') % _report_detail_text(beta['risk_detail']))
        if beta.get('notice'):
            L.append('  %s' % _report_detail_text(beta['notice']))
    elif beta.get('requested'):
        L.append(_t('[!] 리프레임 출력 (Beta) 보류: %s', '[!] Reframe output (Beta) held: %s') % _report_detail_text(beta.get('reason', '지원 조건 미충족')))
    if res.get('boxed'):
        bb = res['boxed']
        L.append(_t('활성 영상 영역(필러박스) 안에서 매칭: x %.0f-%.0f%%', 'Matched inside active image area (pillarbox): x %.0f-%.0f%%') % (100 * bb[0], 100 * bb[2]))
    if res.get('range_retry'):
        L.append(_t('1단계 구간 재탐색함 (경로가 구간 경계 / 결과 약함)', 'Stage-one range search repeated (path reached boundary / weak result)'))
    if res.get('overlay'):
        L.append(_t('번인/오버레이 사전 제외: %.1f%%', 'Burn-in/overlay pre-exclusion: %.1f%%') % (res['overlay'] * 100))
    if res['masked'] > 0:
        L.append(_t('번인/매트 마스킹: %.1f%%', 'Burn-in/matte masking: %.1f%%') % (res['masked'] * 100))
    q = res.get('quality')
    if q is not None:
        L.append(_t('매칭 일치도: %s%s', 'Matching similarity: %s%s') % (score_text(q), _t('  [!] 결과 확인 필요', '  [!] review result') if q > WARN_QUALITY else ''))
    if res.get('confidence_warn'):
        L.append(_t('[!] 신뢰도 낮음 (유일성): %s — 일치도와 별개로 결과 확인 필요',
                    '[!] Low confidence (uniqueness): %s — review independently of similarity') % ', '.join(_report_detail_text(v) for v in res['confidence_warn']))
    for t0, t1, v0, v1 in res['slow']:
        sp = (v1 - v0) / max(1, (t1 - t0)) * 100
        L.append(_t('슬로우 스트레치: OUT %d-%d  (%.1f%%)', 'Slow-motion stretch: OUT %d-%d  (%.1f%%)') % (out_first + t0, out_first + t1, sp))
    L += interp_slow_report_lines(res, out_first)
    exl = set(res.get('excluded') or [])
    inv = [t for t in np.where(~res['E_valid'])[0] if t not in exl]
    if len(inv):
        L.append(_t('블랙/무텍스처 프레임(보간 처리): %s', 'Black/textureless frames (interpolated): %s') % _ranges(out_first + np.array(inv)))
    if exl:
        L.append(_t('배제 구간(등속 보간/고정점/TC): OUT %s — 수동 확인', 'Excluded ranges (constant-speed interpolation/pins/TC): OUT %s — manual review') % _ranges(out_first + np.array(sorted(exl))))
    if res.get('pins'):
        L.append(_t('고정점: %d개', 'Pins: %d') % len(res['pins']))
    st = tc_status(res)
    if st:
        L.append(_t('렉TC: %s — %s', 'Burn-in TC: %s — %s') % (st[0], st[2].replace('\n', ' / ')))
    pre = res.get('tc_preflight')
    if pre:
        L.append(_t('TC 사전검사 (Beta): 판독 %s / 범위 %s / 이미지 %s · %.4g fps · TC 영역 %s',
                    'TC preflight (Beta): recognition %s / range %s / image %s · %.4g fps · TC region %s') % (
            pre['ocr']['state'], pre['range']['state'], pre['image']['state'], pre.get('fps', 0),
            _t('원본별', 'per source') if pre.get('tc_roi_source') == 'plate' else _t('전역 보정', 'global calibration')))
    if res.get('tc_hints'):
        mis = res.get('tc_mismatch') or []
        L.append(_t('렉TC 힌트: %d프레임%s', 'Burn-in TC hints: %d frames%s') % (res['tc_hints'], (_t(', 이미지와 불일치 OUT %s', ', image mismatch OUT %s')
                                                         % _ranges(out_first + np.array(mis))) if mis else ''))
    dup = res.get('edit_duplicates') or []
    if dup:
        L.append(_t('[!] 편집본 중복 프레임 의심: EDIT %s / OUT %s — 앞뒤는 움직이지만 같은 프레임이 한 번 더 이어짐',
                    '[!] Possible duplicate edit frames: EDIT %s / OUT %s — the surrounding image moves but one frame is repeated')
                 % (_ranges(edit_first + np.array(dup)), _ranges(out_first + np.array(dup))))
    for c in res.get('cuts') or []:
        L.append(_t('[!] 분절컷 의심: EDIT %d / OUT %d  %s — 배속만으로 연결함, 이 구간 확인 '
                    '(컷 뒤 첫 프레임에 고정점 또는 배제 후 재실행)',
                    '[!] Possible cut: EDIT %d / OUT %d  %s — connected using speed changes only; review this range (pin the first frame after the cut or exclude the range and rerun)')
                 % (edit_first + c['t'], out_first + c['t'], cut_desc(c)))
    L += near_hold_report_lines(res.get('near_hold') or [], edit_first, out_first)
    if res.get('reversals'):
        L.append(_t('역방향 전환(정보): OUT %s', 'Reverse-direction transitions (info): OUT %s') % ', '.join(str(out_first + t) for t in res['reversals']))
    if res['lowq']:
        L.append(_t('확인 필요(매칭 품질 낮음): %s', 'Review required (low matching quality): %s') % _ranges(out_first + np.array(res['lowq'])))
    if res['ambiguous'] and not res.get('near_hold'):  # if there is a still segment, that line counts the same thing
        L.append(_t('정지/반복 구간 모호 프레임: %d', 'Ambiguous static/repeating frames: %d') % res['ambiguous'])
    L.append(frame_accuracy_text(res))
    # Authored copy is localized at generation. Node/source names are user data
    # a blanket Hangul fallback here would erase those identifiers in EN mode.
    return '\n'.join(L)


def report_display_html(txt):
    """Compact, escaped StickyNote view; the original plain report remains the log/result contract."""
    import html
    import unicodedata

    max_width = 54

    def char_width(char):
        if unicodedata.combining(char):
            return 0
        return 2 if unicodedata.east_asian_width(char) in ('W', 'F') else 1

    def text_width(value):
        return sum(char_width(char) for char in value)

    def split_word(word):
        parts, current, width = [], '', 0
        for char in word:
            cw = char_width(char)
            if current and width + cw > max_width:
                parts.append(current)
                current, width = '', 0
            current += char
            width += cw
        if current:
            parts.append(current)
        return parts or ['']

    def wrap(value):
        words = []
        for word in str(value).strip().split():
            words.extend(split_word(word))
        if not words:
            return []
        out, current = [], ''
        for word in words:
            candidate = word if not current else current + ' ' + word
            if current and text_width(candidate) > max_width:
                out.append(current)
                current = word
            else:
                current = candidate
        if current:
            out.append(current)
        return out

    def tc_parts(value):
        value = value.replace('렉TC', '번인 TC')
        if value.startswith(('번인 TC:', 'Burn-in TC:')):
            head, sep, tail = value.partition(' — ')
            match = re.match(r'^((?:번인 TC|Burn-in TC):\s*.*?)\s*·\s*(\d+%)$', head)
            parts = []
            if match:
                parts.extend((match.group(1), _t('판독 커버리지 ', 'Recognition coverage ') + match.group(2)))
            else:
                parts.append(head)
            if sep:
                for item in tail.split(' / '):
                    item = re.sub(r'\s*\(커버리지\s+(\d+%)\),?\s*', ' · ', item).strip(' ·')
                    if item:
                        parts.append(item)
            return parts
        if value.startswith(('TC 사전검사', 'TC preflight')):
            head, sep, tail = value.partition(': ')
            if not sep:
                return [value]
            fields = [field.strip() for field in tail.split(' / ') if field.strip()]
            return [head + ': ' + fields[0]] + fields[1:] if fields else [head]
        return [value]

    def warning(value):
        if any(token in value for token in ('[!]', '확인 필요', '수동 확인',
                                             'review required', 'manual review', 'needs review')):
            return True
        if value.startswith(('QC 룩 매치', 'QC look match')):
            return any(token in value for token in (': 보류', ': 실패', ': held', ': failed'))
        if value.startswith(('렉TC:', '번인 TC:', 'Burn-in TC:', 'TC 사전검사', 'TC preflight')):
            return any(token in value for token in (
                '불일치', '오프셋', '미사용', '이미지 약함', '일부 해제',
                '보류', '거절', '실패', 'mismatch', 'rejected', 'failed', 'held',
                'unreadable', 'partial', 'unknown', 'tentative', 'unverified', 'offset',
                'unused', 'weak image evidence', 'some anchors released'))
        return False

    lines = [str(line).strip() for line in str(txt).splitlines() if str(line).strip()]
    headers, scores, warnings, tc_lines, details = [], [], [], [], []
    for index, line in enumerate(lines):
        if index == 0 or line.startswith(('EDIT  ', 'OUT   ', '첫 프레임:', 'First frame:')):
            headers.append(line)
        elif line.startswith(('매칭 일치도:', 'Matching similarity:', 'TC 대조 일치', 'TC check matched',
                              '프레임 정확도:', 'Frame accuracy:')):
            scores.append(line)
        elif warning(line):
            warnings.append(line)
        elif line.startswith(('렉TC:', '번인 TC:', 'Burn-in TC:', 'TC 사전검사', 'TC preflight')):
            tc_lines.append(line)
        else:
            details.append(line)

    rendered = []

    def add(values, size, bold=False, color=None):
        for value in values:
            for part in tc_parts(value):
                for visual_line in wrap(part):
                    attrs = ['face="Arial"', 'size="%d"' % size]
                    attrs.append('color="%s"' % (color or '#f2f5f8'))
                    body = html.escape(visual_line, quote=True)
                    if bold:
                        body = '<b>%s</b>' % body
                    rendered.append('<font %s>%s</font>' % (' '.join(attrs), body))

    if headers:
        add(headers[:1], 5, bold=True)
        add(headers[1:], 4)
    add(scores, 4, bold=True)
    if scores:
        add([_t('이미지 유사도 지표', 'Image similarity metric')], 2, color='#9aa7b5')
    add(warnings, 4, bold=True)
    add(tc_lines, 3)
    add(details, 2, color='#9aa7b5')
    return '<br>'.join(rendered)


def result_summary_display_html(edit_name, coverage=''):
    """Readable, escaped and localized compact summary for the result graph."""
    lines = [
        'No More Manual Retime v%s' % NMMR_DISPLAY_VERSION,
        'EDIT %s' % edit_name,
    ]
    if coverage:
        lines.append(_english_report_line(coverage) if ui_language() == 'en' else coverage)
    return report_display_html('\n'.join(lines))


# one result StickyNote + 'NMMR Report' tab
REPORT_TAB_KNOB = 'nmmr_report_tab'
REPORT_TEXT_KNOB = 'nmmr_report'
NOTE_COLORS = dict(good='#5fd38d', check='#ffa94d', fail='#ff6b6b',
                   text='#f2f5f8', dim='#9aa7b5')


def look_reason_text(reason):
    """Short localized reason for the look-match state (note line and report line)."""
    return {
        'validated_constant_grade': _t('별도 프레임에서 룩 개선 확인', 'look improvement confirmed on separate frames'),
        'already_matched': _t('이미 룩 차이가 작음', 'look difference is already small'),
        'insufficient_trusted_frames': _t('신뢰 프레임 부족', 'insufficient trusted frames'),
        'insufficient_frames': _t('비교 프레임 부족', 'insufficient comparison frames'),
        'insufficient_pixels': _t('비교 가능한 영역 부족', 'insufficient comparable image area'),
        'flat_input': _t('플레이트 명암 정보 부족', 'insufficient plate tonal variation'),
        'flat_target': _t('편집본 명암 정보 부족', 'insufficient edit tonal variation'),
        'heldout_improvement_insufficient': _t('별도 프레임에서 개선 부족', 'insufficient improvement on separate frames'),
        'residual_or_unstable_look': _t('차이가 크거나 룩이 일정하지 않음', 'large residual difference or inconsistent look'),
        'extreme_or_unstable_fit': _t('보정값이 과도하거나 불안정함', 'extreme or unstable correction'),
        'region_not_supported': _t('부분영역·분할합성은 아직 미지원', 'partial-region and split-composite matching are not yet supported'),
        'qc_disabled': _t('QC 트리와 리뷰가 꺼져 있음', 'QC tree and review are disabled'),
        'qc_format_mismatch': _t('QC 입력 포맷 불일치', 'QC input formats do not match'),
        'qc_crop_not_supported': _t('QC 입력 영역 불일치', 'QC input regions do not match'),
    }.get(reason, _t('비교 자료 또는 Grade 생성 확인 필요', 'check comparison data or Grade creation'))


def _note_seconds(seconds):
    s = int(round(max(0.0, float(seconds or 0))))
    return '%dm %02ds' % (s // 60, s % 60) if s >= 60 else '%ds' % s


def _note_frames(frames, limit=6):
    """OUT frame list for the status line; long lists are cut with a count."""
    text = _ranges(frames)
    parts = text.split(', ')
    if len(parts) > limit:
        return ', '.join(parts[:limit]) + _t(' 외 %d', ' +%d more') % (len(parts) - limit)
    return text


def _note_tc_line(res):
    plan = res.get('tc_plan')
    if not plan:
        return _t('TC: 사용 안 함 (판독 안 함)', 'TC: not used (not read)')
    info = res.get('tc') or {}
    cov = '%.0f%%' % (100 * plan.get('coverage', 0))
    mode = info.get('mode') or ('none' if plan.get('mode') == 'first' else plan.get('mode'))
    if mode == 'increment_mismatch':
        return _t('TC: 약한 힌트로만 사용 (프레임마다 흔들림) · %s', 'TC: weak hints only (fluctuates between frames) · %s') % cov
    if plan.get('mode') == 'first' and mode == 'first':
        extra = ''
        if info.get('lowq_released'):
            extra = _t(' · 고정점 일부 해제', ' · some anchors released')
        elif info.get('forced'):
            extra = _t(' · 이미지 약함', ' · weak image evidence')
        return _t('TC: 우선 사용 · %s%s', 'TC: priority · %s%s') % (cov, extra)
    if mode == 'offset':
        return _t('TC: 사용 안 함 (%+d프레임 오프셋 의심) · %s', 'TC: not used (possible %+d-frame offset) · %s') % (info.get('offset', 0), cov)
    if mode == 'mismatch':
        return _t('TC: 사용 안 함 (그림과 불일치) · %s', 'TC: not used (disagrees with the image) · %s') % cov
    if plan.get('mode') == 'hint' and mode == 'hint':
        return _t('TC: 약한 힌트로만 사용 (우선 조건 미달) · %s', 'TC: weak hints only (priority requirements not met) · %s') % cov
    return _t('TC: 사용 안 함 (우선 조건 미달) · %s', 'TC: not used (priority requirements not met) · %s') % cov


def _note_look_line(res, look_requested):
    """ note look line: 'QC look auto match applied / pending / off'. The reason for pending goes only on the Report tab line"""
    look = res.get('qc_look') or {}
    if not look_requested or look.get('status') in (None, 'off'):
        return _t('QC 룩 자동 매치 끔', 'QC auto look match: off')
    if look.get('status') == 'applied':
        return _t('QC 룩 자동 매치 적용', 'QC auto look match: applied')
    return _t('QC 룩 자동 매치 보류', 'QC auto look match: held')


# reasons for which the note has a separate detail warning line (status line and frame list included) or the status line is directly visible
_NOTE_DETAILED_REASONS = frozenset((
    '매칭 일치도 낮음', '확인 필요 프레임', '매칭 유일성 낮음', '분절컷 의심', '편집본 중복 프레임 의심',
    '정지 구간 확인 필요', '리프레임 Beta 보류', '리프레임 Beta 검토 필요', '2차 QC 밝기 차이', '2차 QC 판정 제한',
    '2차 QC 검사 실패', '배제 구간 수동 확인', '입력 사전검사 경고', '분할합성 미커버 영역'))


def result_note_lines(res, edit_name, plate_name, edit_first, plate_first, out_first,
                      total_seconds, look_requested=False, coverage='', coverage_review=False):
    """ Core result-note content as (kind, text). The full report lives in the 'NMMR Report' tab.

    kind: title | meta | good | check | fail | map | tc | look | warn | disclaimer
    """
    path = res['path']
    n = len(path)
    out_last = out_first + n - 1
    lines = [('title', 'NMMR · %s' % plate_name),
             ('meta', 'EDIT %s · %d-%d (%d f) · build %s · %s' % (
                 edit_name, edit_first, edit_first + n - 1, n, NMMR_VERSION, _note_seconds(total_seconds)))]

    warns = []
    infos = []  # info lines - not counted in the needs-checking decision (still TC/pin confirmed, weak evidence, good coverage)
    reasons = shot_review_reasons(res, coverage_review=coverage_review)
    for item in res.get('input_warnings') or []:
        message = read_input_preflight_text('%s %s' % (item.get('role', ''), item.get('node', '')), item.get('result'))
        if message:
            warns.append(message)
    if res.get('confidence_warn'):
        warns.append(_t('신뢰도 낮음 (유일성): %s', 'Low confidence (uniqueness): %s') % ', '.join(
            _report_detail_text(v) for v in res['confidence_warn']))
    cuts = res.get('cuts') or []
    if cuts:
        warns.append(_t('분절컷 의심: EDIT %s', 'Possible cut: EDIT %s') % ', '.join(str(edit_first + c['t']) for c in cuts))
    nh_flag = near_hold_batch_flag(res.get('near_hold') or [], out_first)
    if nh_flag:
        (warns if '정지 구간 확인 필요' in reasons else infos).append(nh_flag)
    dup = res.get('edit_duplicates') or []
    if dup:
        warns.append(_t('편집본 중복 프레임 의심: EDIT %s', 'Possible duplicate edit frames: EDIT %s') % _ranges(edit_first + np.array(dup)))
    exl = sorted(res.get('excluded') or [])
    if exl:
        warns.append(_t('배제 구간 OUT %s — 수동 확인', 'Excluded OUT %s — manual review') % _ranges(out_first + np.array(exl)))
    beta = res.get('reframe_output_beta') or {}
    if beta.get('requested') and not beta.get('create'):
        warns.append(_t('리프레임 출력 (Beta) 보류', 'Reframe output (Beta) held'))
    elif beta.get('create') and beta.get('review'):
        warns.append(_t('리프레임 출력 (Beta) 검토 필요', 'Reframe output (Beta) needs review'))
    secondary = res.get('secondary_qc') or {}
    if isinstance(secondary, dict) and secondary.get('status') in ('review', 'limited', 'error'):
        warns.append(secondary_qc_batch_flag(secondary))
    if coverage:
        (warns if coverage_review else infos).append(_english_report_line(coverage) if ui_language() == 'en' else coverage)
    for reason in reasons:  # reasons without a detail line (TC mismatch, TC precheck ...) are also left as warning lines
        if reason not in _NOTE_DETAILED_REASONS:
            warns.append(_result_reason(reason))

    frames = set(int(out_first + t) for t in (res.get('lowq') or []))
    frames.update(int(out_first + c['t']) for c in cuts)
    for s in res.get('near_hold') or []:
        if _span_state(s) in ('ambiguous', 'unsure'):
            frames.update(range(int(out_first + s['t0']), int(out_first + s['t1']) + 1))
    frames.update(int(out_first + t) for t in dup)

    q = res.get('quality')
    pct, grade = match_score(q)
    score = '-' if pct is None else '%s %d%%' % (grade, pct)
    if q is None or q > WARN_QUALITY:
        status = ('fail', _t('■ 실패 · 일치도 %s · 결과 확인 필요', '■ Failed · similarity %s · review the result') % score)
        if frames:
            status = (status[0], status[1] + _t(' · 프레임 %s', ' · frames %s') % _note_frames(frames))
    elif frames or reasons:
        status = ('check', _t('▲ 확인 필요 · %s · ', '▲ Check · %s · ') % score + (
            _t('프레임 %s', 'frames %s') % _note_frames(frames) if frames else _t('아래 경고 확인', 'see warnings below')))
    else:
        status = ('good', _t('● %s · 자동 경고 프레임 없음', '● %s · no frames auto-flagged') % score)
    lines.append(status)
    lines.extend(('warn', w) for w in warns)
    lines.extend(('info', w) for w in infos)
    lines.append(('map', 'EDIT %df → PLATE %df · OUT %d-%d' % (
        edit_first, plate_first + int(path[0]), out_first, out_last)))
    lines.append(('tc', _note_tc_line(res)))
    lines.append(('tc', frame_accuracy_text(res)))
    lines.append(('look', _note_look_line(res, look_requested)))
    lines.append(('disclaimer', _t('자동 판정입니다. 곡선과 QC로 직접 확인하세요.',
                                   'Automatic check only. Review the curve and QC yourself.')))
    return lines


# Nuke measures the StickyNote body width weakly, so text overflowed the box (long KO/EN lines, line breaks).
# Estimate the width generously per line with the font size (HTML size), and secure the box width and bottom margin with invisible NBSP lines.
NOTE_BASE_PX = 22  # note_font_size
NOTE_HTML_EM = {2: 0.8125, 3: 1.0, 4: 1.125, 5: 1.5}  # HTML <font size> -> em (Qt)
NOTE_LINE_H = {2: 20, 3: 24, 4: 30, 5: 36}  # line height (px, approximate from measurement)
NOTE_MARGIN = 1.12  # width estimate margin (the base estimate was 0.91~1.11 of the measurement -> always 1.0 or more, at most 1.25x)
NOTE_MAX_W = 900  # maximum width of one line (px). Warning lines beyond it are shortened with ... and the full text is on the Report tab
NOTE_NBSP_W = 4.0  # width of one size=1 NBSP (measured 4.1, set lower so it does not fall short)


def note_line_style(kind):
    """kind -> (HTML size, bold)."""
    return {'title': (5, True), 'good': (4, False), 'check': (4, False), 'fail': (4, False),
            'disclaimer': (2, False)}.get(kind, (3, False))


def _note_char_em(char):
    if ord(char) >= 0x1100:  # Hangul, symbols (●■▲→) and full-width characters use full-width width
        return 1.0
    if char == ' ':
        return 0.28
    if char.isupper() or char.isdigit():
        return 0.62
    if char.isalpha():
        return 0.5
    return 0.34


def note_text_width(kind, text):
    """Generous rendered width (px) of one note line at its own font size."""
    size, bold = note_line_style(kind)
    em = sum(_note_char_em(c) for c in str(text)) * NOTE_BASE_PX * NOTE_HTML_EM[size] * (1.1 if bold else 1.0)
    return int(em * NOTE_MARGIN) + 16


def note_fit_text(kind, text, max_width=NOTE_MAX_W):
    """Cut an over-long line with an ellipsis so the note never gets absurdly wide."""
    text = str(text)
    if note_text_width(kind, text) <= max_width:
        return text
    lo, hi = 0, len(text)
    while lo < hi:
        mid = (lo + hi + 1) // 2
        if note_text_width(kind, text[:mid] + '…') <= max_width:
            lo = mid
        else:
            hi = mid - 1
    return text[:lo].rstrip() + '…'


def note_size_estimate(lines):
    """(width, height) px of the note: widest line at its own size, lines x line heights, plus the bottom pad line."""
    width = max([note_text_width(k, t) for k, t in lines] or [0])
    height = 14 + sum(NOTE_LINE_H[note_line_style(k)[0]] for k, _t in lines) + 18
    return width, int(height * 1.1)


def result_note_html(lines):
    """One StickyNote: only the status line is coloured; the disclaimer is small grey.

    Lines are fitted (long ones cut), and a last invisible NBSP line sets the box width.
    """
    import html
    lines = [(kind, text if kind in ('good', 'check', 'fail') else note_fit_text(kind, text)) for kind, text in lines]  # the status line already has a limited frame count
    width, _height = note_size_estimate(lines)
    out = []
    for kind, text in lines:
        body = html.escape(str(text), quote=True)
        if kind == 'title':
            out.append('<font face="Arial" size="5" color="%s"><b>%s</b></font>' % (NOTE_COLORS['text'], body))
        elif kind in ('good', 'check', 'fail'):
            out.append('<font face="Arial" size="4" color="%s">%s</font>' % (NOTE_COLORS[kind], body))
        elif kind == 'meta':
            out.append('<font face="Arial" size="3" color="%s">%s</font>' % (NOTE_COLORS['dim'], body))
        elif kind == 'disclaimer':
            out.append('<font face="Arial" size="2" color="%s">%s</font>' % (NOTE_COLORS['dim'], body))
        else:
            out.append('<font face="Arial" size="3" color="%s">%s</font>' % (NOTE_COLORS['text'], body))
    out.append('<font size="1">%s</font>' % ('&nbsp;' * int(width / NOTE_NBSP_W + 1)))
    return '<br>'.join(out)


def report_tab_text(txt, coverage=''):
    """Full diagnostic report for the 'NMMR Report' tab (everything the old two notes showed)."""
    parts = [str(txt).rstrip()]
    parts.append(_t('이미지 유사도 지표 · 정답 프레임 정확도가 아님',
                    'Image similarity metric · not measured frame accuracy'))
    if coverage:
        parts.append(_english_report_line(coverage) if ui_language() == 'en' else coverage)
    return '\n'.join(parts)


def set_report_tab(node, text):
    """Add or update the read-only 'NMMR Report' tab. Idempotent, so re-runs and copies update in place.

    Text_Knob: display-only, stored verbatim in the .nk (copy/paste, save/reopen) and never
    TCL-evaluated, so '[PLATE]' / '[!]' in the report stay literal (an EvalString knob would run them).
    """
    knobs = node.knobs()
    if REPORT_TEXT_KNOB not in knobs:
        if REPORT_TAB_KNOB not in knobs:
            node.addKnob(nuke.Tab_Knob(REPORT_TAB_KNOB, 'NMMR Report'))
        node.addKnob(nuke.Text_Knob(REPORT_TEXT_KNOB, '', ''))
    knob = node[REPORT_TEXT_KNOB]
    knob.setValue(str(text))
    return knob


def cut_desc(c):
    """ one-line description of a suspected split cut"""
    if c.get('tc'):
        return _t('(번인 TC 가 %+d프레임 점프)', '(burn-in TC jumps %+d frames)') % c['jump']
    if c.get('mismatch'):
        return _t('(컷 뒤 그림이 이 플레이트에 없음 — 다른 소스로 컷?)',
                  '(post-cut image is absent from this plate — cut to another source?)')
    return (_t('(약 %+d프레임 점프)', '(about a %+d-frame jump)') % c['jump'] if c.get('jump') else
            _t('(배속 범위 밖 변화)', '(change outside the speed range)'))


def _coverage_miss(E_lum, results):
    """ (ratio, mask) that matches no plate in a split composite. (None, None) if it is not a split composite"""
    pic = edit_static_mask(E_lum)
    union = np.zeros_like(pic)
    any_split = False
    for res in results:
        if res.get('region') is not None:
            union |= res['region']
            any_split = True
        else:
            union |= res['mask']
    if not any_split:
        return None, None
    miss = pic & ~_dilate(union, 2)
    return miss.sum() / float(max(pic.sum(), 1)), miss


def coverage_needs_review(E_lum, results):
    """ True only when coverage_text gives the 'source addition needed' wording (the good wording is info)"""
    frac = _coverage_miss(E_lum, results)[0]
    return frac is not None and frac >= 0.08


def coverage_text(E_lum, results):
    """ multiple plate results -> warning for areas that match no plate
    """
    frac, miss = _coverage_miss(E_lum, results)
    if frac is None:
        return ''
    if frac < 0.08:
        return _t('분할합성: 선택한 플레이트로 화면 대부분 커버됨',
                  'Split composite: selected plates cover most of the image')
    return _t('분할합성: 어느 플레이트에도 안 맞는 영역 %.0f%% (%s) -> 소스 추가 필요',
              'Split composite: %.0f%% of the image matches no plate (%s) -> add a source') % (
        frac * 100, _report_detail_text(_where(miss)))


def _ranges(arr):
    arr = sorted(int(a) for a in arr)
    if not arr:
        return '-'
    out, s, p = [], arr[0], arr[0]
    for a in arr[1:]:
        if a == p + 1:
            p = a
            continue
        out.append('%d' % s if s == p else '%d-%d' % (s, p))
        s = p = a
    out.append('%d' % s if s == p else '%d-%d' % (s, p))
    return ', '.join(out)


# Settings popup
_MOVIE_EXT = ('.mov', '.mp4', '.mxf', '.avi', '.m4v', '.webm')


def _candidates():
    """ Reads in the current context + selected nodes
    """
    nodes = list(nuke.allNodes('Read'))
    for n in nuke.selectedNodes():
        if n not in nodes:
            nodes.append(n)
    nodes = [n for n in nodes if not _is_tool_node_name(n)]
    nodes.sort(key=lambda n: (n.ypos(), n.xpos()))
    return nodes


def _node_label(n):
    """"""
    f = n['file'].value() if 'file' in n.knobs() else n.Class()
    return '%s   |   %s   |   %d-%d' % (n.name(), os.path.basename(f) or f,
                                         n.firstFrame(), n.lastFrame())


def _is_movie(n):
    return 'file' in n.knobs() and n['file'].value().lower().endswith(_MOVIE_EXT)


def _defaults(nodes):
    """ based on selected nodes: mov -> EDIT, the rest -> PLATE (several). With no selection, the single longest sequence
    if there are several movs, not the first mov but pick_edit_plate (ED_ / edit hint, shot, shorter one). PLATE is never equal to EDIT
    """
    sel = [n for n in nuke.selectedNodes() if n in nodes]
    pool = sel if len(sel) >= 2 else nodes
    if not pool:
        return None, []
    movs = [n for n in pool if _is_movie(n)]
    cand = movs or pool
    if len(cand) >= 2:
        ei, _ = pick_edit_plate([_read_item(n) for n in cand])
        edit = cand[ei]
    else:
        edit = (movs or _guess_edit(pool))[0]
    rest = [n for n in pool if n is not edit]
    if len(sel) >= 2:
        return edit, rest
    seqs = [n for n in rest if not _is_movie(n)] or rest
    if not seqs:
        return edit, []
    hinted = [n for n in seqs if plate_only_hint(_read_item(n))]
    return edit, [max(hinted or seqs, key=lambda n: n.lastFrame() - n.firstFrame())]


def _qt():
    """"""
    try:
        from PySide6 import QtWidgets, QtCore
        return QtWidgets, QtCore
    except ImportError:
        pass
    try:
        from PySide2 import QtWidgets, QtCore
        return QtWidgets, QtCore
    except ImportError:
        return None


_OPTS = (('optical', '옵티컬(리사이즈/리포지션) 감지'),
         ('track', '옵티컬 애니메이션(스케일/리포지션 키) 추적'),
         ('flop', 'flop 검사'),
         ('slow', '슬로우(보간) 감지'),
         ('cleanup', '작업 후 썸네일 캐시 삭제 (끄면 남겨서 재실행 시 재사용)'),
         ('qc', 'QC 트리 생성'),
         ('qc_look', 'QC 룩 매치 (Beta)'),
         ('secondary_qc', '2차 QC 검사 (Beta)'),
         ('reframe_output', '리프레임 출력 (Beta)'),
         ('qc_refine', 'QC 위치 정밀화 (고해상도)'))


def option_default(key):
    """Shared option defaults for Qt, classic Panel, single and batch flows."""
    return key not in ('qc_refine', 'reframe_output', 'secondary_qc')  # look match on by default


def option_saved_default(key):
    if key in ('reframe_output', 'qc_look', 'secondary_qc'):
        return bool(_ui_get(key, option_default(key)))  # saved user settings stay as they are
    return option_default(key)


def option_ui_label(key, label):
    """Keep release qualifiers that users must see; trim only explanatory parentheticals."""
    return label if key in ('qc_refine', 'reframe_output', 'qc_look', 'secondary_qc') else label.split(' (')[0]


def qc_required(opts):
    """Whether final QC inputs are needed for review or either optional QC pass."""
    return bool(opts.get('qc') or opts.get('review') or opts.get('secondary_qc'))


def ask_settings():
    """
    PLATE multi-check
    normal / split-composite modes separated - the multi-PLATE list + split logic only when split composite is chosen
    """
    nodes = _candidates()
    if len(nodes) < 2:
        nuke.message(_t('Read 노드가 2개 이상 필요합니다 (EDIT, PLATE)',
                        'At least two Read nodes are required (EDIT and PLATE).'))
        return None
    d_edit, d_plates = _defaults(nodes)
    qt = _qt()
    if qt is None or qt[0].QApplication.instance() is None:
        return _ask_settings_panel(nodes, d_edit, d_plates)
    QtWidgets, QtCore = qt

    dlg = QtWidgets.QDialog(QtWidgets.QApplication.activeWindow())
    dlg.setWindowTitle('No More Manual Retime  v%s' % NMMR_DISPLAY_VERSION)
    dlg.setMinimumWidth(640)
    lay = QtWidgets.QVBoxLayout(dlg)

    lay.addWidget(QtWidgets.QLabel('EDIT (편집본)'))
    cb_edit = QtWidgets.QComboBox()
    for n in nodes:
        cb_edit.addItem(_node_label(n), n.fullName())
    if d_edit is not None:
        cb_edit.setCurrentIndex(nodes.index(d_edit))
    lay.addWidget(cb_edit)

    # mode selection
    mode_row = QtWidgets.QHBoxLayout()
    rb_norm = QtWidgets.QRadioButton('일반')
    rb_split = QtWidgets.QRadioButton('분할합성 (소스 플레이트 여러 개)')
    rb_norm.setChecked(True)
    mode_row.addWidget(rb_norm)
    mode_row.addWidget(rb_split)
    mode_row.addStretch(1)
    lay.addLayout(mode_row)

    lb_plate = QtWidgets.QLabel('PLATE')
    lay.addWidget(lb_plate)
    # normal: one combo box
    cb_plate = QtWidgets.QComboBox()
    for n in nodes:
        cb_plate.addItem(_node_label(n), n.fullName())
    if d_plates:
        cb_plate.setCurrentIndex(nodes.index(d_plates[0]))
    lay.addWidget(cb_plate)
    # split composite: check list
    lst = QtWidgets.QListWidget()
    lst.setMinimumHeight(140)
    for n in nodes:
        it = QtWidgets.QListWidgetItem(_node_label(n))
        it.setData(QtCore.Qt.UserRole, n.fullName())
        it.setFlags(it.flags() | QtCore.Qt.ItemIsUserCheckable)
        it.setCheckState(QtCore.Qt.Checked if n in d_plates else QtCore.Qt.Unchecked)
        lst.addItem(it)
    lay.addWidget(lst)

    form = QtWidgets.QFormLayout()
    ff_pref = first_frame_preference(_ui_get('first_frame'), paths_config()[0])
    ff_box = QtWidgets.QWidget()
    ff_row = QtWidgets.QHBoxLayout(ff_box)
    ff_row.setContentsMargins(0, 0, 0, 0)
    cb_out = QtWidgets.QComboBox()
    for label, token in (('Plate 시작', 'plate'), ('1001', '1001'), ('1', '1'),
                         ('직접 입력', 'custom'), ('첫 매칭 (기존 자동)', 'matched')):
        cb_out.addItem(label, token)
    sp_out = QtWidgets.QSpinBox()
    sp_out.setRange(-100000, 1000000)
    sp_out.setValue(int(ff_pref) if ff_pref not in ('plate', 'matched', '1001', '1') else 1001)
    preset = ff_pref if ff_pref in ('plate', 'matched', '1001', '1') else 'custom'
    cb_out.setCurrentIndex(cb_out.findData(preset))
    sp_out.setVisible(preset == 'custom')
    ff_row.addWidget(cb_out)
    ff_row.addWidget(sp_out)
    ff_row.addStretch(1)
    form.addRow('First Frame', ff_box)
    sp_max_speed = QtWidgets.QSpinBox()
    sp_max_speed.setRange(4, 16)
    sp_max_speed.setSuffix('×')
    try:
        max_speed_pref = max(4, min(16, int(_ui_get('max_speed', 16))))
    except Exception:
        max_speed_pref = 16
    sp_max_speed.setValue(max_speed_pref)
    sp_max_speed.setToolTip('자동 탐색이 허용할 최대 배속. 4×는 기존 한도, 8–16×는 필요한 구간에서만 탐색 범위를 넓힙니다')
    form.addRow('최대 배속', sp_max_speed)
    lay.addLayout(form)

    def ff_changed(*_):
        custom = cb_out.currentData() == 'custom'
        sp_out.setVisible(custom)
        dlg.adjustSize()
    cb_out.currentIndexChanged.connect(ff_changed)

    def checked_nodes():
        out = []
        for i in range(lst.count()):
            it = lst.item(i)
            if it.checkState() == QtCore.Qt.Checked:
                n = nuke.toNode(it.data(QtCore.Qt.UserRole))
                if n is not None:
                    out.append(n)
        return out

    def plates_now():
        if rb_split.isChecked():
            return checked_nodes()
        n = nuke.toNode(cb_plate.currentData())
        return [n] if n is not None else []

    def sync_mode(*_):
        split = rb_split.isChecked()
        cb_plate.setVisible(not split)
        lst.setVisible(split)
        lb_plate.setText('PLATE (분할된 소스 플레이트를 모두 체크해 주세요)' if split else 'PLATE')
        dlg.adjustSize()
    rb_split.toggled.connect(sync_mode)
    sync_mode()

    cb_lookup = QtWidgets.QComboBox()
    for key, label in LOOKUP_INTERPOLATIONS:
        cb_lookup.addItem(label, key)
    cb_lookup.setCurrentIndex(cb_lookup.findData(lookup_interpolation(_ui_get('lookup_interpolation', 'linear'))))
    cb_lookup.setToolTip(LOOKUP_INTERPOLATION_TIP)
    lay.addWidget(QtWidgets.QLabel('lookup 키 보간'))
    lay.addWidget(cb_lookup)
    checks = {}
    for key, label in _OPTS:
        c = QtWidgets.QCheckBox(label)
        c.setChecked(option_saved_default(key))
        c.setToolTip(_OPT_TIPS.get(key, label))
        checks[key] = c
        lay.addWidget(c)

    bb = QtWidgets.QDialogButtonBox(QtWidgets.QDialogButtonBox.Ok |
                                    QtWidgets.QDialogButtonBox.Cancel)
    bb.accepted.connect(dlg.accept)
    bb.rejected.connect(dlg.reject)
    lay.addWidget(bb)

    run_dlg = getattr(dlg, 'exec', None) or getattr(dlg, 'exec_')
    if not run_dlg():
        return None
    edit = nuke.toNode(cb_edit.currentData())
    plates = [n for n in plates_now() if n is not edit]
    if edit is None or not plates:
        nuke.message(_t('EDIT 1개와 PLATE 1개 이상을 지정해 주세요 (EDIT 와 다른 노드)',
                        'Choose one EDIT and at least one different PLATE node.'))
        return None
    out = dict((k, c.isChecked()) for k, c in checks.items())
    ff_setting = str(sp_out.value()) if cb_out.currentData() == 'custom' else cb_out.currentData()
    _ui_set('first_frame', ff_setting)
    _ui_set('max_speed', sp_max_speed.value())
    _ui_set('reframe_output', bool(out.get('reframe_output')))
    _ui_set('qc_look', bool(out.get('qc_look')))
    _ui_set('secondary_qc', bool(out.get('secondary_qc')))
    out.update(edit=edit, plates=plates, split=rb_split.isChecked(),
               out=ff_setting, max_speed=sp_max_speed.value())
    out['lookup_interpolation'] = lookup_interpolation(cb_lookup.currentData())
    _ui_set('lookup_interpolation', out['lookup_interpolation'])
    return out


def _ask_settings_panel(nodes, d_edit, d_plates):
    """ fallback when PySide is unavailable (1 PLATE)
    split-composite mode checkbox
    """
    names = [n.name() for n in nodes]

    def ordered(first):
        if first is None:
            return names
        return [first.name()] + [x for x in names if x != first.name()]
    d_plate = d_plates[0] if d_plates else None
    p = nuke.Panel('No More Manual Retime')
    labels = {
        'edit': 'EDIT', 'plate': 'PLATE',
        'ff_mode': _t('First Frame 모드', 'First Frame mode'),
        'ff_custom': _t('First Frame 직접 입력', 'Custom First Frame'),
        'max_speed': _t('최대 배속 (4-16)', 'Maximum speed (4-16)'),
        'split': _t('분할합성 모드', 'Split-composite mode'),
        'lookup': _t('lookup 키 보간', 'Lookup key interpolation'),
    }
    p.addEnumerationPulldown(labels['edit'], ' '.join(ordered(d_edit)))
    p.addEnumerationPulldown(labels['plate'], ' '.join(ordered(d_plate)))
    ff_pref = first_frame_preference(_ui_get('first_frame'), paths_config()[0])
    ff_items = [(_t('Plate시작', 'Plate_start'), 'plate'), ('1001', '1001'), ('1', '1'),
                (_t('직접입력', 'Custom'), 'custom'), (_t('첫매칭', 'First_match'), 'matched')]
    ff_default = ff_pref if ff_pref in ('plate', 'matched', '1001', '1') else 'custom'
    ff_items.sort(key=lambda item: item[1] != ff_default)
    p.addEnumerationPulldown(labels['ff_mode'], ' '.join(label for label, _ in ff_items))
    p.addSingleLineInput(labels['ff_custom'], ff_pref if ff_default == 'custom' else '1001')
    try:
        max_speed_pref = max(4, min(16, int(_ui_get('max_speed', 16))))
    except Exception:
        max_speed_pref = 16
    p.addSingleLineInput(labels['max_speed'], str(max_speed_pref))
    p.addBooleanCheckBox(labels['split'], False)
    curve_items = [('Linear', 'linear'), ('Constant_기존', 'legacy')]
    curve_items.sort(key=lambda item: item[1] != lookup_interpolation(_ui_get('lookup_interpolation', 'linear')))
    p.addEnumerationPulldown(labels['lookup'], ' '.join(label for label, _ in curve_items))
    for key, lb in _OPTS:
        p.addBooleanCheckBox(_visible_ui_text(lb), option_saved_default(key))
    if not p.show():
        return None
    edit = nuke.toNode(p.value(labels['edit']))
    plate = nuke.toNode(p.value(labels['plate']))
    if edit is plate:
        nuke.message(_t('EDIT 와 PLATE 를 서로 다른 노드로 지정해 주세요',
                        'EDIT and PLATE must be different nodes.'))
        return None
    out = dict((k, p.value(_visible_ui_text(lb))) for k, lb in _OPTS)
    ff_label = p.value(labels['ff_mode'])
    ff_setting = dict(ff_items)[ff_label]
    if ff_setting == 'custom':
        try:
            ff_setting = _first_frame_token(p.value(labels['ff_custom']))
        except ValueError as ex:
            nuke.message(str(ex))
            return None
    try:
        max_speed = max(4, min(16, int(p.value(labels['max_speed']))))
    except Exception:
        nuke.message(_t('최대 배속은 4에서 16 사이의 정수로 입력해 주세요',
                        'Enter an integer maximum speed from 4 to 16.'))
        return None
    _ui_set('first_frame', ff_setting)
    _ui_set('max_speed', max_speed)
    _ui_set('reframe_output', bool(out.get('reframe_output')))
    _ui_set('qc_look', bool(out.get('qc_look')))
    _ui_set('secondary_qc', bool(out.get('secondary_qc')))
    out.update(edit=edit, plates=[plate], split=p.value(labels['split']),
               out=ff_setting, max_speed=max_speed)
    out['lookup_interpolation'] = dict(curve_items)[p.value(labels['lookup'])]
    _ui_set('lookup_interpolation', out['lookup_interpolation'])
    return out


# lagging TC (Nuke side) - calibration file / edit reading / plate TC
def tc_cfg_path(proj):
    """"""
    return os.path.join(os.path.expanduser('~'), '.nuke',
                        'no_more_manual_retime_tc',
                        '%s.json' % (proj or 'default')).replace('\\', '/')


def _tc_cfg_read_path(proj):
    return tc_cfg_path(proj)


def load_tc_cfg(proj):
    """
    only the ROI is needed (built-in font dictionary + per-clip self-calibration). 4.x files (roi + templates) are still read as is - templates are ignored"""
    try:
        import json
        with open(_tc_cfg_read_path(proj)) as f:
            cfg = json.load(f)
        return cfg if cfg.get('roi') else None
    except Exception:
        return None


def save_tc_cfg(proj, cfg):
    """"""
    import json
    p = tc_cfg_path(proj)
    old = _tc_cfg_read_path(proj)
    if old != p and os.path.exists(old):
        with open(old) as f:
            cfg = _settings_overlay(json.load(f), cfg)
    if not os.path.isdir(os.path.dirname(p)):
        os.makedirs(os.path.dirname(p))
    with open(p, 'w') as f:
        json.dump(cfg, f)
    return p


def node_fps(node, frame):
    """"""
    try:
        v = float(node.metadata('input/frame_rate', frame))
        if v > 1:
            return v
    except Exception:
        pass
    try:
        return float(nuke.root()['fps'].value())
    except Exception:
        return 24.0


def _tc_roi_disp(edit, ef, el, roi, log):
    """ edit ROI crop (source resolution) -> list of display-gamma luminance (None for missing frames)"""
    ensure_roi_thumbs(edit, ef, el, 1, roi, True, log)
    imgs, ok = load_roi_thumbs(edit, list(range(ef, el + 1)), roi, log)
    return [to_display(i) if k else None for i, k in zip(imgs, ok)]


TC_OCR_CACHE_VER = 1  # format of the read-result cache. If changed, old caches automatically do not match


def tc_ocr_cache_dir():
    """ cache folder for lagging-TC read results (ocr_cache/ next to the TC calibration file, local only)"""
    return os.path.join(os.path.dirname(tc_cfg_path(None)), 'ocr_cache').replace('\\', '/')


_TC_OCR_CACHE_FILE = re.compile(r'^(?:[0-9a-f]{32}|\.tc_[^/\\]*)\.json$')


def _tc_ocr_cache_files(folder=None):
    """ only cache files directly under the read cache folder (32-character key .json + .tc_*.json left over from saving). Subfolders and other files are excluded"""
    folder = folder or tc_ocr_cache_dir()
    try:
        names = os.listdir(folder)
    except Exception:
        return []
    out = []
    for name in sorted(names):
        path = os.path.join(folder, name)
        if _TC_OCR_CACHE_FILE.match(name) and os.path.isfile(path) and not os.path.islink(path):
            out.append(path)
    return out


def tc_ocr_cache_stats(folder=None):
    """ (count, bytes). No automatic cleanup - the user clears it with [Clear cache]"""
    count = size = 0
    for path in _tc_ocr_cache_files(folder):
        try:
            size += os.path.getsize(path)
            count += 1
        except Exception:
            pass
    return count, size


def format_cache_size(size):
    """ 0 B / 812 B / 48 KB / 1.2 MB (1024 units, KB rounded up to an integer)"""
    size = max(0, int(size or 0))
    if size < 1024:
        return '%d B' % size
    if size < 1024 * 1024:
        return '%d KB' % int(math.ceil(size / 1024.0))
    return '%.1f MB' % (size / (1024.0 * 1024.0))


def tc_ocr_cache_label(count, size):
    """ one-line cache summary for advanced options"""
    if not count:
        return _t('TC 캐시 없음', 'No TC cache')
    return _t('TC 캐시 %d개 · %s', 'TC cache: %d files · %s') % (int(count), format_cache_size(size))


def clear_tc_ocr_cache(folder=None):
    """ called only after the user confirms. Deletes only read cache files; the folder and calibration files (*.json above) stay.
    Returns (deleted count, deleted bytes, failure count)"""
    removed = freed = failed = 0
    for path in _tc_ocr_cache_files(folder):
        try:
            size = os.path.getsize(path)
            os.remove(path)
            removed += 1
            freed += size
        except Exception:
            failed += 1
    return removed, freed, failed


def tc_ocr_cache_key(edit, ef, el, cfg, fps):
    """ same key only for the same media (file path, mtime, size, Read mapping/colorspace), range, ROI/calibration, fps and OCR version.
    The node name is not included - the same file loaded through a different Read is reused. A node without a file path is not cached (ValueError)"""
    if edit is None or not str(edit['file'].value() or '').strip():
        raise ValueError('no media file to key the TC read cache')
    sig = read_analysis_signature(edit)
    try:
        f = edit.format()
        fmt = '%dx%d@%s' % (f.width(), f.height(), f.pixelAspect())
    except Exception:
        fmt = '<format?>'
    parts = (TC_OCR_CACHE_VER, TCO_VERSION, THUMB_VER, tuple(sig[1:]), fmt, int(ef), int(el),
             round(float(fps), 6), tc_config_signature(cfg), _input_color_fingerprint())
    return hashlib.sha256(repr(parts).encode('utf-8')).hexdigest()[:32]


def _tc_json_safe(value):
    if isinstance(value, dict):
        return dict((str(k), _tc_json_safe(v)) for k, v in value.items())
    if isinstance(value, (set, frozenset)):
        return sorted(_tc_json_safe(v) for v in value)
    if isinstance(value, (list, tuple)):
        return [_tc_json_safe(v) for v in value]
    if isinstance(value, np.ndarray):
        return _tc_json_safe(value.tolist())
    if isinstance(value, np.generic):
        return value.item()
    return value


def load_tc_ocr_cache(key):
    """ (out, rows, summary) or None. None if the key differs or the file is corrupt (read again)"""
    import json
    path = os.path.join(tc_ocr_cache_dir(), key + '.json')
    try:
        with open(path) as handle:
            data = json.load(handle)
        if data.get('v') != TC_OCR_CACHE_VER or data.get('key') != key:
            return None
        rows = [(None if v is None else int(v), float(c), set(fl)) for v, c, fl in data['rows']]
        summ = data['summary']
        if len(rows) != int(summ['n']):
            return None
        return [v for v, _c, _fl in rows], rows, summ
    except Exception:
        return None


def save_tc_ocr_cache(key, rows, summ, log=print):
    """ save the read result atomically. The job continues even on failure"""
    import json
    folder = tc_ocr_cache_dir()
    tmp = None
    try:
        payload = json.dumps(dict(v=TC_OCR_CACHE_VER, key=key, engine=TCO_VERSION,
                                  rows=[[v, c, sorted(fl)] for v, c, fl in _tc_json_safe(
                                      [(v, c, set(fl)) for v, c, fl in rows])],
                                  summary=_tc_json_safe(dict((k, v) for k, v in summ.items()
                                                             if not str(k).startswith('_')))))
        if not os.path.isdir(folder):
            os.makedirs(folder)
        fd, tmp = tempfile.mkstemp(prefix='.tc_', suffix='.json', dir=folder)
        with os.fdopen(fd, 'w') as handle:
            handle.write(payload)
        os.replace(tmp, os.path.join(folder, key + '.json'))
        tmp = None
    except Exception as error:
        log(_t('렉TC 판독 캐시 저장 생략: %s', 'Burn-in TC read cache not saved: %s') % error)
    finally:
        if tmp:
            try:
                os.unlink(tmp)
            except Exception:
                pass


def read_edit_tc(edit, ef, el, cfg, fps, log=print):
    """ per-frame burn-in lagging TC of the edit -> list of frame counts (None if reading failed)
    nmmr_tc_ocr engine (tc_decode_rows). Returns (out, strs, disp, rows, summary)
            rows[t] = (frame count | None, margin, flags), summary is tco_decode_sequence + raw
            cfg['roi_rec'] (record TC region) is no longer used - ignored without a warning even if left in an old calibration file
    with the same media, range, ROI, calibration and OCR version, the saved read result is reused (ROI render + reading skipped, disp is None)"""
    try:
        key = tc_ocr_cache_key(edit, ef, el, cfg, fps)
    except Exception:
        key = None
    hit = load_tc_ocr_cache(key) if key else None
    if hit is not None:
        out, rows, summ = hit
        disp = None
        log(_t('렉TC 판독 재사용 (같은 미디어·범위·ROI, 캐시 %s)', 'Burn-in TC read reused (same media, range and ROI; cache %s)') % key[:8])
    else:
        disp = _tc_roi_disp(edit, ef, el, cfg['roi'], log)
        rows, summ = tc_decode_rows(disp, cfg, fps, log=log)
        out = [v for v, c, fl in rows]
        if key:
            save_tc_ocr_cache(key, rows, summ, log)
    strs = [tco_frames_to_tc(v, fps) if v is not None else None for v in out]
    log(_t('렉TC 판독: %d/%d 프레임 (확신), 컷 %s', 'Burn-in TC read: %d/%d confident frames, cuts %s') % (summ['confident'], summ['n'], summ['cuts']))
    return out, strs, disp, rows, summ


def tc_status(res):
    """ TC usage state of the result -> (short text, tone ok|warn|dim, detailed description). None if TC reading was not done"""
    plan = res.get('tc_plan')
    if not plan:
        return None
    info = res.get('tc') or {}
    cov = '%.0f%%' % (100 * plan['coverage'])
    tip = [_t('확신 TC %d프레임 (커버리지 %s), 플레이트 범위 안 %.0f%%',
              'Confident TC: %d frames (coverage %s), %.0f%% within plate range') % (plan['confident'], cov, 100 * plan['in_range'])]
    if plan.get('b0_src') == 'image':
        tip.append(_t('플레이트 첫 프레임 TC 를 이미지 경로로 맞춤: %s (메타데이터 %s, %d/%d 프레임 일치)',
                      'Plate first-frame TC aligned using the image path: %s (metadata %s, %d/%d frames agree)') % (
            frames_to_tc(plan['b0'], plan.get('fps') or 24), frames_to_tc(plan.get('b0_meta', 0), plan.get('fps') or 24),
            plan['b0_votes'][0], plan['b0_votes'][1]))
    elif plan.get('b0_src') in ('tmcd', 'rtmd'):
        tip.append(_t('플레이트 첫 프레임 TC 를 파일 %s 트랙에서 읽음: %s (Nuke 메타데이터는 00:00:00:00 / 없음)',
                      'Plate first-frame TC read from the file %s track: %s (Nuke metadata is 00:00:00:00 / absent)') % (
            plan['b0_src'], frames_to_tc(plan['b0'], plan.get('fps') or 24)))
    elif plan.get('tentative'):
        tip.append(_t('플레이트 TC 메타데이터 없음 — 첫 프레임 = 00:00:00:00 으로 잠정',
                      'Plate TC metadata absent — provisionally using 00:00:00:00 for the first frame'))
    mode = info.get('mode') or ('none' if plan['mode'] == 'first' else plan['mode'])
    if mode == 'increment_mismatch':
        tip.append(_t('렉TC가 프레임마다 흔들림: 독립 이미지 경로와 증가폭 불일치 %.0f%% — 약한 힌트로만 사용',
                      'Burn-in TC fluctuates between frames: increments disagree with the independent image path by %.0f%% — used only as weak hints') %
                   (100 * info.get('increment_disagree', 0)))
        return _t('TC 증가폭 불일치 · 약한 힌트', 'TC increment mismatch · weak hints'), 'warn', '\n'.join(tip)
    if plan['mode'] == 'first' and mode == 'first':
        tip.append(_t('고정점 %d · 이미지 비토 %d · 약한 힌트 %d', 'Anchors %d · image vetoes %d · weak hints %d') % (info.get('used', 0), info.get('vetoed', 0),
                                                       info.get('weak', 0)))
        if info.get('missed'):
            tip.append(_t('경로가 지키지 못한 TC %d프레임 (TC 점프 = 분절컷 의심 쪽)',
                          'The path could not honor TC at %d frames (TC jumps suggest a cut)') % len(info['missed']))
        if info.get('lowq_released'):
            tip.append(_t('품질 낮은 TC 고정점 %d개를 해제하고 재풀이했습니다', 'Released %d low-quality TC anchors and solved again') % len(info['lowq_released']))
            return _t('TC 우선 · 고정점 일부 해제 · ', 'TC priority · some anchors released · ') + cov, 'warn', '\n'.join(tip)
        if info.get('forced'):
            fi = info.get('forced_img') or {}
            tip.append(_t('이미지 매칭이 약해서(일치도 %s, 모호 %s, 상하 절반 합의 %s) TC-그림 %s 판정(어긋남 %.0f%%)을 쓰지 않고 '
                          'TC 를 따랐습니다 — 결과를 눈으로 확인해 주세요',
                          'Image matching was weak (similarity %s, ambiguous %s, upper/lower-half agreement %s), so the TC-image %s judgment (%.0f%% disagreement) was ignored and TC was followed — visually review the result') % (
                           score_text(fi.get('quality')) if fi.get('quality') is not None else '-',
                           '-' if fi.get('amb') is None else '%.0f%%' % (100 * fi['amb']),
                           '-' if fi.get('half') is None else '%.0f%%' % (100 * fi['half']),
                           {'offset': _t('오프셋', 'offset'), 'mismatch': _t('불일치', 'mismatch')}.get(info.get('forced_from'), _t('불일치', 'mismatch')),
                           100 * (info.get('forced_disagree') or 0)))
            return _t('TC 우선 · 이미지 약함 · ', 'TC priority · weak image evidence · ') + cov, 'warn', '\n'.join(tip)
        return _t('TC 우선 · ', 'TC priority · ') + cov, 'ok', '\n'.join(tip)
    if mode == 'offset':
        tip.append(_t('이미지가 TC 와 일관되게 %+d프레임 어긋남 (어긋난 프레임 %.0f%%) — TC 를 쓰지 않고 이미지 매칭으로 풀었습니다.\n'
                      '번인 TC 가 그림보다 늦거나(지연) 시작값이 다른지 확인해 주세요',
                      'Images consistently differ from TC by %+d frames (%.0f%% of frames disagree) — solved using image matching without TC.\nCheck whether burn-in TC is delayed or has a different starting value') % (info['offset'], 100 * info['disagree_frac']))
        return _t('TC 오프셋 %+d 의심 · 미사용', 'Possible TC offset %+d · unused') % info['offset'], 'warn', '\n'.join(tip)
    if mode == 'mismatch':
        tip.append(_t('TC 의 %.0f%% 가 이미지와 어긋남 — TC 를 쓰지 않고 이미지 매칭으로 풀었습니다',
                      '%.0f%% of TC disagrees with the images — solved using image matching without TC') % (100 * info['disagree_frac']))
        return _t('TC-그림 불일치 · 미사용', 'TC-image mismatch · unused'), 'warn', '\n'.join(tip)
    if plan['mode'] == 'hint' and mode == 'hint':
        tip.append(_t('힌트 %d프레임 (오프셋 / 불일치 검사 통과)', 'Hints at %d frames (offset / mismatch checks passed)') % info.get('used', 0))
        tip.append(_t('TC 우선 조건 미달 (커버리지 >= %d%%, 범위 안 >= %d%%) — 4.x 방식 약한 힌트로만 사용',
                      'TC priority requirements not met (coverage >= %d%%, in range >= %d%%) — used only as weak hints (4.x method)')
                   % (100 * TC_FIRST_COV, 100 * TC_FIRST_INRANGE))
        return _t('TC 힌트 · ', 'TC hints · ') + cov, 'dim', '\n'.join(tip)
    tip.append(_t('TC 우선 조건 미달 (커버리지 >= %d%%, 범위 안 >= %d%%) — 이미지 매칭만 사용',
                  'TC priority requirements not met (coverage >= %d%%, in range >= %d%%) — image matching only')
               % (100 * TC_FIRST_COV, 100 * TC_FIRST_INRANGE))
    return _t('TC 미사용 · ', 'TC unused · ') + cov, 'dim', '\n'.join(tip)


# Display by grade: indistinguishable = warning (orange, warning window, hatching), weak evidence = info (gray, dotted line, no warning window - it appeared in 33 of 158
# normal edits, so gray to avoid warning fatigue), confirmed by TC / pin = info (green)
# insufficient evidence (needs checking) = the weak-evidence cases that fall under rule E (anchor on one side / no anchor + edit difference >= 7) = warning (orange, warning window, hatching), handling unchanged
_NH_ORDER = {'ambiguous': 0, 'unsure': 1, 'weak': 2, 'pin': 3, 'tc': 4}
_ANCHOR_TEXT = {'start': '앞에만 있고', 'end': '뒤에만 있고', 'none': '앞뒤에 없고', 'both': '앞뒤에 있고'}


def _anchor_text(anchor):
    return {
        'start': _t('앞에만 있고', 'only before the range'),
        'end': _t('뒤에만 있고', 'only after the range'),
        'none': _t('앞뒤에 없고', 'on neither side'),
        'both': _t('앞뒤에 있고', 'on both sides'),
    }.get(anchor, _t('부족하고', 'insufficient'))


def _unc_text(s):
    return (_t('±%d 이상', '±%d or more') if s.get('unc_capped') else '±%d') % s['unc']


def _unc_short(s):
    return '±%d%s' % (s['unc'], '+' if s.get('unc_capped') else '')


def _span_state(s):
    """'tc' | 'pin' | 'ambiguous' | 'unsure' | 'weak'"""
    if s.get('tc'):
        return 'tc'
    if s.get('pinned'):
        return 'pin'
    if s.get('tier') == 'ambiguous':
        return 'ambiguous'
    return 'unsure' if s.get('unsure') else 'weak'


def span_range_text(s, edit_first=None, out_first=None):
    ef = 0 if edit_first is None else edit_first
    of = ef if out_first is None else out_first
    return _t('EDIT %d-%d / OUT %d-%d (%d프레임)',
              'EDIT %d-%d / OUT %d-%d (%d frames)') % (
                  ef + s['t0'], ef + s['t1'], of + s['t0'], of + s['t1'], s['n'])


def span_tip(s, edit_first=None, out_first=None, plate_first=None, path=None):
    """hover detail of one segment: fact / evidence / handling / impact / how to confirm (one line each)"""
    st = _span_state(s)
    head = {
        'tc': _t('TC로 확정', 'Confirmed by TC'),
        'pin': _t('고정점으로 확정', 'Confirmed by pins'),
        'ambiguous': _t('프레임 구분 불가', 'Frames indistinguishable'),
        'unsure': _t('정지 구간 · 근거 부족(확인 필요)', 'Hold range · insufficient evidence (review)'),
        'weak': _t('정지 구간 · 근거 약함', 'Hold range · weak evidence'),
    }[st]
    L = ['%s — %s' % (head, span_range_text(s, edit_first, out_first))]
    L.append(_t('근거: 플레이트 이웃 프레임끼리 그림 차이 최대 %.1f %% (편집본-플레이트 차이 %.1f %%)',
                'Evidence: maximum image difference between adjacent plate frames %.1f%% '
                '(edit-to-plate difference %.1f%%)') % (s['diff_max'], s['resid']))
    pf = 0 if plate_first is None else plate_first
    if st == 'tc':
        L.append(_t('번인 TC %d프레임을 확신 판독해 TC를 따랐습니다',
                    '%d burn-in TC frames were read confidently, so the path follows TC') % s.get('tc_n', 0))
        return '\n'.join(L)
    if st == 'pin':
        L.append(_t('고정점 %d개를 기준으로 앞뒤를 일정 속도로 이었습니다',
                    '%d pins connect the surrounding frames at a constant speed') % s['pinned'])
        return '\n'.join(L)
    if st == 'ambiguous':
        L.append(_t('그림만으로는 어느 소스 프레임인지 정할 수 없습니다 — 불확실 %s프레임',
                    'The image alone cannot identify the source frame — uncertainty %s frames') % _unc_text(s))
        if s.get('bridged') and path is not None and s['left'] is not None and s['right'] is not None:
            r = (int(path[s['right']]) - int(path[s['left']])) / float(max(s['right'] - s['left'], 1))
            L.append(_t('처리: 앞뒤 확정 프레임(PLATE %d → %d) 사이를 일정 속도 %.2fx 로 이었습니다',
                        'Handling: connected the confirmed surrounding frames (PLATE %d → %d) '
                        'at constant speed %.2fx')
                     % (pf + int(path[s['left']]), pf + int(path[s['right']]), r))
        elif s.get('bridged'):
            anchor = {'start': _t('앞에만 있어', 'only before it'),
                      'end': _t('뒤에만 있어', 'only after it')}.get(
                          s['anchor'], _t('앞뒤에 없어', 'on neither side'))
            L.append(_t('처리: 확정 프레임이 %s 구간 안 경로를 일정 속도 직선으로 맞췄습니다 (시작 위치 %s 불확실)',
                        'Handling: a confirmed frame exists %s, so the path was fitted as a constant-speed line '
                        '(start position uncertain by %s)') % (anchor, _unc_text(s)))
    elif st == 'unsure':
        if s.get('tc_endpoint') == 'mismatch':
            L.append(_t('근거: 구간 양끝의 TC와 독립 이미지 경로가 일치하지 않아 TC 확정을 보류했습니다',
                        'Evidence: endpoint TC and the independent image path disagree, so TC confirmation was withheld'))
        else:
            L.append(_t('앵커: 앞뒤 확정 프레임이 %s 편집본-플레이트 차이가 기준(%g %%) 이상 — 이미지 근거가 부족합니다',
                        'Anchor: confirmed surrounding frames are %s and the edit-to-plate difference is above '
                        'the threshold (%g%%) — image evidence is insufficient') %
                     (_anchor_text(s.get('anchor')), NH_UNSURE_RESID))
        L.append(_t('처리: 경로는 이미지 매칭 그대로 둡니다 (직선으로 바꾸지 않음) — 불확실 %s프레임',
                    'Handling: kept the image-matched path (no linear replacement) — uncertainty %s frames') %
                 _unc_text(s))
    else:
        L.append(_t('이미지 근거가 약한 정지 구간입니다 — 경로는 이미지 매칭 %s, 불확실 %s프레임',
                    'This hold range has weak image evidence — image-matched path %s, uncertainty %s frames') %
                 (_t('기준', 'used as basis') if s.get('tc_fill') else _t('그대로', 'kept'), _unc_text(s)))
    if s.get('tc_fill'):
        L.append(_t('처리: 확신 TC 사이에서 경로가 TC 직선과 2프레임 이상 벗어나 %d프레임을 TC 사이 일정 속도로 이었습니다',
                    'Handling: between confident TC samples, %d frames deviated from the TC line by 2 or more '
                    'frames and were connected at constant speed') % s['tc_fill'])
    L.append(_t('영향: 화면상 차이는 미미하지만 그레인 · 트래킹 · 컨폼에는 프레임 정체가 중요할 수 있습니다',
                'Impact: the visible difference may be minor, but exact frame identity can matter for grain, '
                'tracking and conform'))
    if s.get('tc_endpoint') == 'mismatch':
        L.append(_t('확정: 구간 처음과 끝의 소스 프레임을 확인한 뒤 고정점 2개로 지정',
                    'Confirm: check the first and last source frames, then set two pins'))
    elif st == 'unsure':
        L.append(_t('확정: 번인 TC 가 있으면 [TC 우선]으로 다시 실행 / 구간 처음과 끝 근처에 고정점 2개 / 화면만 맞으면 그대로 사용',
                    'Confirm: rerun with [TC priority] if burn-in TC is available / set two pins near the range '
                    'endpoints / keep it if the image is acceptable'))
    else:
        L.append(_t('확정: 번인 TC 가 있으면 [TC 우선]으로 다시 실행 / 구간 처음과 끝 근처에 고정점 / 화면만 맞으면 그대로 사용',
                    'Confirm: rerun with [TC priority] if burn-in TC is available / set pins near the range '
                    'endpoints / keep it if the image is acceptable'))
    return '\n'.join(L)


def near_hold_status(spans, E, edit_first=None, out_first=None, plate_first=None, path=None):
    """badge (short text, tone warn|dim|ok, hover detail) - same shape as tc_status. None if there is no segment.
    The worst state in the order indistinguishable > weak evidence > confirmed names the badge"""
    if not spans:
        return None
    st = [_span_state(s) for s in spans]
    amb = [s for s, k in zip(spans, st) if k == 'ambiguous']
    uns = [s for s, k in zip(spans, st) if k == 'unsure']
    weak = [s for s, k in zip(spans, st) if k == 'weak']
    if amb:
        whole = sum(s['n'] for s in amb) >= 0.9 * E
        short = (_t('샷 전체 프레임 구분 불가 ', 'Frames indistinguishable across the shot ') if whole else
                 _t('프레임 구분 불가 ', 'Frames indistinguishable ')) + _unc_short(
                     max(amb, key=lambda x: x['unc']))
        tone = 'warn'
    elif uns:
        short, tone = _t('정지 구간 · 근거 부족(확인 필요)',
                         'Hold range · insufficient evidence (review)'), 'warn'
    elif weak:
        short, tone = _t('정지 구간 · 근거 약함', 'Hold range · weak evidence'), 'dim'
    elif all(k == 'tc' for k in st):
        short, tone = _t('TC로 확정 · 정지 구간', 'Confirmed by TC · hold range'), 'ok'
    else:
        short, tone = _t('고정점으로 확정 · 정지 구간', 'Confirmed by pins · hold range'), 'ok'
    tips = [span_tip(s, edit_first, out_first, plate_first, path)
            for s in sorted(spans, key=lambda x: (_NH_ORDER[_span_state(x)], x['t0']))]
    return short, tone, '\n\n'.join(tips)


def near_hold_status_line(spans):
    """status line tail ('  ·  ...'). Indistinguishable > weak evidence > confirmed"""
    if not spans:
        return ''
    st = [_span_state(s) for s in spans]
    amb = [s for s, k in zip(spans, st) if k == 'ambiguous']
    uns = [s for s, k in zip(spans, st) if k == 'unsure']
    weak = [s for s, k in zip(spans, st) if k == 'weak']
    if amb:
        return _t('  ·  프레임 구분 불가 %d구간 (%d프레임, %s)',
                  '  ·  %d indistinguishable range(s) (%d frames, %s)') % (
                      len(amb), sum(s['n'] for s in amb), _unc_short(max(amb, key=lambda x: x['unc'])))
    if uns:
        return _t('  ·  정지 구간 근거 부족 %d구간 (%d프레임, 확인 필요)',
                  '  ·  %d hold range(s) with insufficient evidence (%d frames, review)') % (
                      len(uns), sum(s['n'] for s in uns))
    if weak:
        return _t('  ·  정지 구간 근거 약함 %d', '  ·  %d hold range(s) with weak evidence') % len(weak)
    if all(k == 'tc' for k in st):
        return _t('  ·  정지 구간 TC로 확정 %d', '  ·  %d hold range(s) confirmed by TC') % len(spans)
    return _t('  ·  정지 구간 고정점으로 확정 %d',
              '  ·  %d hold range(s) confirmed by pins') % len(spans)


def near_hold_dialog(spans, plate_name, edit_first=0):
    """completion warning paragraph - only when there are 'indistinguishable' / 'insufficient evidence' segments (weak evidence / confirmed appear only on the badge and timeline). '' if none"""
    amb = [s for s in spans if _span_state(s) == 'ambiguous']
    uns = [s for s in spans if _span_state(s) == 'unsure']
    paras = []
    if amb:
        paras.append(_nh_dialog_amb(amb, plate_name, edit_first))
    if uns:
        L = [_t('정지 구간 근거 부족 %d구간 — 앞뒤 확정 프레임이 부족하고 그림 일치도가 낮아 소스 프레임이 틀렸을 수 있습니다:',
                '%d hold range(s) with insufficient evidence — missing confirmed surrounding frames and low image similarity mean the source frames may be wrong:') % len(uns)]
        for s in uns:
            L.append('  %s  EDIT %d-%d  %s' % (plate_name, edit_first + s['t0'], edit_first + s['t1'], _unc_text(s)))
        L.append(_t('경로는 이미지 매칭 그대로 두었습니다 (직선으로 바꾸지 않음). 화면상 차이는 미미해도 그레인 · 트래킹 · 컨폼에는 '
                    '프레임 정체가 중요할 수 있습니다.\n번인 TC 가 있으면 [TC 우선]으로 다시 실행하거나, 구간 처음과 끝 근처에 '
                    '고정점 2개를 두면 확정됩니다. 화면만 맞으면 그대로 써도 됩니다.',
                    'The image-matched path was retained (no linear replacement). Even a minor visible difference can matter for grain, tracking and conform.\n'
                    'Confirm by rerunning with [TC priority] if burn-in TC is available, or by setting two pins near the range endpoints. '
                    'You can keep the result if the image is acceptable.'))
        paras.append('\n'.join(L))
    return '\n\n'.join(paras)


def _nh_dialog_amb(amb, plate_name, edit_first):
    L = [_t('프레임 구분 불가 %d구간 — 그림만으로는 어느 소스 프레임인지 정할 수 없습니다:',
            '%d indistinguishable range(s) — images alone cannot identify the source frames:') % len(amb)]
    for s in amb:
        L.append('  %s  EDIT %d-%d  %s' % (plate_name, edit_first + s['t0'], edit_first + s['t1'], _unc_text(s)))
    L.append(_t('이 구간은 일정 속도로 이었습니다. 화면상 차이는 미미하지만 그레인 · 트래킹 · 컨폼에는 프레임 정체가 중요할 수 있습니다.\n'
                '번인 TC 가 있으면 [TC 우선]으로 다시 실행하거나, 구간 처음과 끝 근처에 고정점을 두면 확정됩니다. '
                '화면만 맞으면 그대로 써도 됩니다.',
                'These ranges were connected at constant speed. The visible difference may be minor, but exact frame identity can matter for grain, tracking and conform.\n'
                'Confirm by rerunning with [TC priority] if burn-in TC is available, or by setting pins near the range endpoints. '
                'You can keep the result if the image is acceptable.'))
    return '\n'.join(L)


def near_hold_report_lines(spans, edit_first, out_first):
    """report StickyNote line (only indistinguishable gets [!])"""
    L = []
    for s in spans:
        st = _span_state(s)
        rng = 'EDIT %d-%d / OUT %d-%d' % (edit_first + s['t0'], edit_first + s['t1'], out_first + s['t0'], out_first + s['t1'])
        if st == 'tc':
            L.append(_t('정지 구간 TC로 확정: %s — 이웃 프레임 그림 차이 최대 %.1f %%, 번인 TC 를 따름',
                        'Hold confirmed by TC: %s — maximum neighboring-frame image difference %.1f %%; follows burn-in TC') % (rng, s['diff_max']))
        elif st == 'pin':
            L.append(_t('정지 구간 고정점으로 확정: %s (고정점 %d)',
                        'Hold confirmed by pins: %s (%d pins)') % (rng, s['pinned']))
        elif st == 'ambiguous':
            L.append(_t('[!] 프레임 구분 불가: %s (%d f, %s) — 이웃 프레임 그림 차이 최대 %.1f %% / 편집본 차이 %.1f %%, 일정 속도로 이음. '
                        'TC 우선 또는 고정점으로 확정',
                        '[!] Indistinguishable frames: %s (%d f, %s) — maximum neighboring-frame image difference %.1f %% / edit residual %.1f %%; joined at constant speed. Confirm with TC priority or pins') % (rng, s['n'], _unc_text(s), s['diff_max'], s['resid']))
        elif st == 'unsure':
            anchor = _ANCHOR_TEXT.get(s.get('anchor'), '부족하고') if ui_language() != 'en' else {
                'start': 'before the range only', 'end': 'after the range only',
                'none': 'on neither side', 'both': 'on both sides'}.get(s.get('anchor'), 'insufficient')
            L.append(_t('[!] 정지 구간 근거 부족(확인 필요): %s (%d f, %s) — 앞뒤 확정 프레임이 %s 편집본 차이 %.1f %% (기준 %g 이상), '
                        '이웃 프레임 그림 차이 최대 %.1f %%, 이미지 경로 유지. TC 우선 또는 고정점 2개로 확정',
                        '[!] Insufficient hold evidence (review required): %s (%d f, %s) — confirmed frames: %s; edit residual %.1f %% (threshold >= %g), maximum neighboring-frame image difference %.1f %%; image path retained. Confirm with TC priority or two pins')
                     % (rng, s['n'], _unc_text(s), anchor, s['resid'], NH_UNSURE_RESID,
                        s['diff_max']))
        else:
            L.append(_t('정지 구간 근거 약함(정보): %s (%d f, %s) — 이웃 프레임 그림 차이 최대 %.1f %%, 이미지 경로 유지',
                        'Weak hold evidence (info): %s (%d f, %s) — maximum neighboring-frame image difference %.1f %%; image path retained')
                     % (rng, s['n'], _unc_text(s), s['diff_max']))
    return L


def near_hold_label(spans, out_first):
    """second line of the TimeWarp node label ('' if none). The single worst state + n more"""
    if not spans:
        return ''
    sp = sorted(spans, key=lambda x: (_NH_ORDER[_span_state(x)], -x['n']))
    s, k = sp[0], _span_state(sp[0])
    more = _t(' 외 %d', ' +%d more') % (len(sp) - 1) if len(sp) > 1 else ''
    if k == 'ambiguous':
        return _t('[!] 구분 불가 %d-%d %s%s', '[!] Indistinguishable %d-%d %s%s') % (out_first + s['t0'], out_first + s['t1'], _unc_short(s), more)
    if k == 'unsure':
        return _t('[!] 근거 부족 %d-%d%s', '[!] Insufficient evidence %d-%d%s') % (out_first + s['t0'], out_first + s['t1'], more)
    if k == 'weak':
        return _t('정지 근거 약함 %d-%d%s', 'Weak hold evidence %d-%d%s') % (out_first + s['t0'], out_first + s['t1'], more)
    return (_t('TC 확정 정지 %d구간', 'TC-confirmed holds: %d') if k == 'tc' else _t('고정점 확정 정지 %d구간', 'Pin-confirmed holds: %d')) % len(sp)


def near_hold_batch_flag(spans, out_first):
    """batch status column text ('' if none)"""
    if not spans:
        return ''
    st = [_span_state(s) for s in spans]
    amb = [s for s, k in zip(spans, st) if k == 'ambiguous']
    if amb:
        s = max(amb, key=lambda x: x['n'])
        return _t('프레임 구분 불가 OUT %d-%d %s%s', 'Indistinguishable frames OUT %d-%d %s%s') % (out_first + s['t0'], out_first + s['t1'], _unc_short(s),
                                              (_t(' 외 %d', ' +%d more') % (len(amb) - 1)) if len(amb) > 1 else '')
    uns = [s for s, k in zip(spans, st) if k == 'unsure']
    if uns:
        s = max(uns, key=lambda x: x['n'])
        return _t('정지 구간 근거 부족 OUT %d-%d (확인 필요)%s', 'Insufficient hold evidence OUT %d-%d (review required)%s') % (out_first + s['t0'], out_first + s['t1'],
                                                   (_t(' 외 %d', ' +%d more') % (len(uns) - 1)) if len(uns) > 1 else '')
    weak = st.count('weak')
    if weak:
        return _t('정지 구간 근거 약함 %d', 'Weak hold evidence: %d') % weak
    return _t('정지 TC 확정', 'Hold confirmed by TC') if all(k == 'tc' for k in st) else _t('정지 고정점 확정', 'Hold confirmed by pins')


def timeline_marks(spans):
    """timeline display (EDIT index segment -> style). 'hatch' = warning-color 45-degree hatching + 3px strip on top, 'dash' = 3px gray dotted line on top,
    'band' = 3px green strip on top. Color names are _UI keys"""
    style = {'ambiguous': ('hatch', 'warn'), 'unsure': ('hatch', 'warn'), 'weak': ('dash', 'dim'), 'tc': ('band', 'ok'), 'pin': ('band', 'ok')}
    out = []
    for s in spans:
        k = _span_state(s)
        out.append(dict(t0=s['t0'], t1=s['t1'], style=style[k][0], color=style[k][1], state=k))
    return out


def merge_tc_cuts(cuts, tc_cuts, tcf, path):
    """ merge the jump flags of the TC decoder into split-cut suspects (TC-first mode).
    Only when the TC on both frames is confident, that step differs from the median of the surrounding TC steps by CUT_MIN_JUMP or more,
    and it does not overlap an existing suspect point (+/-3). The path stays as is (speed changes only)"""
    out = list(cuts)
    n = len(tcf)
    for t in tc_cuts:
        if not (1 <= t < n) or tcf[t] is None or tcf[t - 1] is None:
            continue
        if any(abs(c['t'] - t) <= 3 for c in out):
            continue
        st = tcf[t] - tcf[t - 1]
        nb = [tcf[u] - tcf[u - 1] for u in range(max(1, t - 6), min(n, t + 7))
              if u != t and tcf[u] is not None and tcf[u - 1] is not None]
        if len(nb) < 2:
            continue
        j = int(round(st - float(np.median(nb))))
        if abs(j) >= CUT_MIN_JUMP:
            out.append(dict(t=int(t), jump=j, excess=0.0, span=(int(t), int(t)), mismatch=False, tc=True))
    return sorted(out, key=lambda c: c['t'])


# read the plate start TC directly from file bytes (pure Python, independent of Nuke - verified by the core tests)
# In the plate TC reference was fixed to the mode of the image path, so the more wrong the image was for an edit, the less the reference could be set
# and TC was missing from the edits that needed it most (6 clips with 80-100 % confident TC had '0 % inside the plate range')
QT_TC_EXT = ('.mov', '.mp4', '.m4v', '.qt', '.3gp')


def _qt_boxes(buf, a, b):
    """ QuickTime / MP4 box walk (buf[a:b]) -> (type, content start, end). Stops at a corrupt size"""
    while a + 8 <= b:
        size, typ = struct.unpack('>I4s', buf[a:a + 8])
        hdr = 8
        if size == 1:
            if a + 16 > b:
                return
            size = struct.unpack('>Q', buf[a + 8:a + 16])[0]
            hdr = 16
        elif size == 0:
            size = b - a
        if size < hdr or a + size > b:
            return
        yield typ.decode('latin-1'), a + hdr, a + size
        a += size


def _qt_child(buf, a, b, path):
    """ first box on a path like 'mdia/minf/stbl' (content start, end) or None"""
    for name in path.split('/'):
        for typ, s, e in _qt_boxes(buf, a, b):
            if typ == name:
                a, b = s, e
                break
        else:
            return None
    return a, b


def qt_tc_string(count, nom, drop=False):
    """ tmcd sample value (frame count at nominal fps) -> 'HH:MM:SS:FF' (';' drop-frame notation if drop)"""
    count = int(count)
    nom = int(nom)
    if drop and nom in (30, 60):
        d = nom // 15  # 30 -> 2, 60 -> 4 frames dropped (except every tenth minute)
        per10 = nom * 600 - d * 9
        q, r = divmod(count, per10)
        count += d * 9 * q + (d * ((r - d) // (nom * 60 - d)) if r > d else 0)
    h, rem = divmod(count, nom * 3600)
    m, rem = divmod(rem, nom * 60)
    s, f = divmod(rem, nom)
    return '%02d:%02d:%02d%s%02d' % (h % 24, m, s, ';' if drop else ':', f)


def qt_start_timecode(path, max_moov=64 << 20):
    """ read the start TC of a QuickTime / MP4 file directly from the file bytes. Top-level boxes are skipped by header only (mdat is not read);
    only moov is read, and for each track the first stsd entry format + the first chunk position of stco / co64 -> first sample.
    Priority: tmcd track (4-byte counter of the first sample + nominal fps / drop flag) -> Sony XAVC rtmd metadata track
    (binary HH MM SS flags FF after 13 bytes of the first sample - same position as ffmpeg mov_read_rtmd_track, cross-checked against ffprobe values).
    Returns dict(tc='HH:MM:SS:FF', src='tmcd'|'rtmd', nom=nominal fps or None, drop=bool) or None (absent / read failure)"""
    try:
        if os.path.splitext(str(path))[1].lower() not in QT_TC_EXT or not os.path.isfile(path):
            return None
        with open(path, 'rb') as f:
            f.seek(0, 2)
            fsize = f.tell()
            pos, moov = 0, None
            while pos + 8 <= fsize:
                f.seek(pos)
                hd = f.read(16)
                size, typ = struct.unpack('>I4s', hd[:8])
                hdr = 8
                if size == 1:
                    size, hdr = struct.unpack('>Q', hd[8:16])[0], 16
                elif size == 0:
                    size = fsize - pos
                if size < hdr:
                    return None
                if typ == b'moov':
                    if size > max_moov:
                        return None
                    f.seek(pos)
                    moov = f.read(size)
                    break
                pos += size
            if moov is None:
                return None
            found = {}
            for typ, s, e in _qt_boxes(moov, 8 if struct.unpack('>I', moov[:4])[0] != 1 else 16, len(moov)):
                if typ != 'trak':
                    continue
                stbl = _qt_child(moov, s, e, 'mdia/minf/stbl')
                if stbl is None:
                    continue
                sd = _qt_child(moov, stbl[0], stbl[1], 'stsd')
                if sd is None or sd[1] - sd[0] < 16:
                    continue
                ent = sd[0] + 8  # version/flags + entry count
                fmt = moov[ent + 4:ent + 8].decode('latin-1')
                if fmt not in ('tmcd', 'rtmd') or fmt in found:
                    continue
                off = None
                co = _qt_child(moov, stbl[0], stbl[1], 'stco')
                if co is not None and co[1] - co[0] >= 12 and struct.unpack('>I', moov[co[0] + 4:co[0] + 8])[0]:
                    off = struct.unpack('>I', moov[co[0] + 8:co[0] + 12])[0]
                else:
                    co = _qt_child(moov, stbl[0], stbl[1], 'co64')
                    if co is not None and co[1] - co[0] >= 16 and struct.unpack('>I', moov[co[0] + 4:co[0] + 8])[0]:
                        off = struct.unpack('>Q', moov[co[0] + 8:co[0] + 16])[0]
                need = 4 if fmt == 'tmcd' else 18
                if off is None or off + need > fsize:
                    continue
                f.seek(off)
                smp = f.read(need)
                if fmt == 'tmcd':
                    if ent + 34 > sd[1]:
                        continue
                    flags, tscale, fdur, nfr = struct.unpack('>IIIB', moov[ent + 20:ent + 33])
                    nom = int(nfr) or (int(round(tscale / float(fdur))) if fdur else 0)
                    if nom <= 0:
                        continue
                    found[fmt] = dict(tc=qt_tc_string(struct.unpack('>I', smp[:4])[0], nom, bool(flags & 1)),
                                      src='tmcd', nom=nom, drop=bool(flags & 1))
                else:
                    b_ = bytearray(smp[13:18])
                    if not (b_[0] < 24 and b_[1] < 60 and b_[2] < 60 and b_[4] < 120):
                        continue
                    drop = bool(b_[3] & 0x80)
                    found[fmt] = dict(tc='%02d:%02d:%02d%s%02d' % (b_[0], b_[1], b_[2], ';' if drop else ':', b_[4]),
                                      src='rtmd', nom=None, drop=drop)
            return found.get('tmcd') or found.get('rtmd')
    except Exception:
        return None


def plate_file_tc(path, fps, frame_shift=0):
    """ file TC track -> (TC frame count of the plate's first frame, source 'tmcd'|'rtmd') or None.
    frame_shift = plate first frame - file first frame (Read's first - origfirst). Not used if the nominal fps differs"""
    info = qt_start_timecode(path)
    if not info:
        return None
    if info.get('nom') and fps and int(info['nom']) != int(round(float(fps))):
        return None
    b = tc_to_frames(info['tc'], fps)
    if b is None:
        return None
    return int(b) + int(frame_shift), info['src']


def _plate_path_shift(plate, pf):
    """ Read's file path (first frame) and (first - origfirst). (None, 0) if it cannot be read"""
    try:
        fp = nuke.filename(plate) if nuke is not None else plate['file'].value()
    except Exception:
        try:
            fp = plate['file'].value()
        except Exception:
            return None, 0
    try:
        of = int(plate['origfirst'].value()) if 'origfirst' in plate.knobs() else pf
    except Exception:
        of = pf
    # reflect the Read's frame_mode (start at / offset / expression): based on the file frame seen at output frame pf.
    # The metadata 'input/frame' that Nuke gives is the file frame actually read (measured in GUI Nuke 16.1: offset 100 -> 101 at pf 1
    # start at 1001 -> 10 at 1010, 'frame+10' -> 11 at 1). If absent, compute from the knobs
    try:
        mf = plate.metadata('input/frame', pf) if nuke is not None else None
        if mf is not None and str(mf).strip() != '':
            return fp, int(round(float(mf))) - of
    except Exception:
        pass
    kn = plate.knobs()
    try:
        first = int(plate['first'].value()) if 'first' in kn else pf
    except Exception:
        first = pf
    try:
        mode = plate['frame_mode'].value() if 'frame_mode' in kn else 'expression'
        fval = plate['frame'].value() if 'frame' in kn else ''
    except Exception:
        mode, fval = 'expression', ''
    ff = read_file_frame(mode, fval, first, pf)
    if ff is None:
        return None, 0
    return fp, ff - of


def read_file_frame(mode, frame_val, first, f):
    """ file frame number seen at Read output frame f (pure function, when metadata 'input/frame' is absent). frame_mode
    'start at' N: N -> first, 'offset' k: f + k (measured in Nuke 16.1), 'expression' only when empty or 'frame' / an integer
    (other expressions give None - the file TC is not used)"""
    mode = str(mode or 'expression').strip().lower().replace('_', ' ')
    s = str(frame_val if frame_val is not None else '').strip()
    try:
        if mode == 'start at':
            return int(f) - int(round(float(s or first))) + int(first)
        if mode == 'offset':
            return int(f) + int(round(float(s or 0)))
        if not s or s == 'frame':
            return int(f)
        return int(round(float(s)))
    except (TypeError, ValueError):
        return None


def plate_tc_base(plate, pf, pl, log=print, allow_missing=False):
    """ plate first-frame TC -> (fps, frame count). None if there is no TC / it is discontinuous
    allow_missing: if there is no metadata, (fps, 0, True) - first frame = 00:00:00:00 provisionally (used only if it passes the TC-first conditions)
    if metadata is absent or 00:00:00:00, use the file's tmcd / rtmd track (plate_file_tc) first -> (fps, count, False, 'tmcd'|'rtmd')
            If Nuke gives a non-zero TC, use it as is (it already reflects the Reader's frame offset)"""
    err = False
    try:
        fps = node_fps(plate, pf)
        b0 = tc_to_frames(plate.metadata('input/timecode', pf), fps)
        b1 = tc_to_frames(plate.metadata('input/timecode', pl), fps)
    except Exception:
        err, b0, b1 = True, None, None
        fps = node_fps(plate, pf)
    # a movie Reader that cannot read the TC track counts the file's first frame as 00:00:00:00 -> if file frame k is seen at pf through frame_mode offset etc.
    # the metadata is 'k - origfirst' frames (not 0), and used this as the real TC
    fp, shift = _plate_path_shift(plate, pf)
    if not b0 or (fp and b0 == shift):
        bf = plate_file_tc(fp, fps, shift) if fp else None
        if bf is not None:
            log(_t('[%s] 플레이트 TC: 메타데이터 %s -> 파일 %s 트랙 %s (파일 프레임 오프셋 %+d)', '[%s] Plate TC: metadata %s -> file %s track %s (file frame offset %+d)') % (
                plate.name(), _t('없음', 'none') if b0 is None else frames_to_tc(b0, fps), bf[1], frames_to_tc(bf[0], fps), shift))
            return fps, bf[0], False, bf[1]
    if err:
        if allow_missing:
            return fps, 0, True
        return None
    if b0 is None:
        if allow_missing:
            return fps, 0, True
        log(_t('[%s] 플레이트 TC 메타데이터 없음 — 렉TC 생략', '[%s] No plate TC metadata — skip burn-in TC') % plate.name())
        return None
    if b1 is not None and b1 - b0 != pl - pf:
        log(_t('[%s] 플레이트 TC 불연속 (%d vs %d프레임) — 렉TC 생략', '[%s] Discontinuous plate TC (%d vs %d frames) — skip burn-in TC') % (plate.name(), b1 - b0, pl - pf))
        return None
    return fps, b0


# job engine (shared by GUI / batch / classic)
class JobCtx(object):
    """Bundle of progress/cancel/question callbacks. The GUI connects them to the window, classic to ProgressTask"""

    def __init__(self, log=None, progress=None, cancelled=None, ask=None):
        self.log = log or _console
        self._p, self._c, self._a = progress, cancelled, ask

    def progress(self, frac, msg=None):
        if self._p:
            self._p(max(0.0, min(1.0, frac)), msg)

    def cancelled(self):
        return bool(self._c and self._c())

    def ask(self, msg):
        return self._a(msg) if self._a else True

    def sub(self, a, b):
        """sub-context mapped to the progress range [a,b]"""
        return JobCtx(self.log, lambda f, m=None: self.progress(a + (b - a) * f, m),
                      self._c, self._a)


class Cancelled(Exception):
    pass


def parse_frame_ranges(text):
    """ '1005-1012, 1030' -> {1005..1012, 1030}"""
    out = set()
    for tok in re.split(r'[,\s]+', str(text or '').strip()):
        if not tok:
            continue
        m = re.match(r'^(-?\d+)(?:-(-?\d+))?$', tok)
        if not m:
            raise ValueError(_t('배제 구간 형식 오류: %s', 'Invalid excluded-range format: %s') % tok)
        a = int(m.group(1))
        b = int(m.group(2)) if m.group(2) else a
        out.update(range(min(a, b), max(a, b) + 1))
    return out


def parse_pins(text):
    """ '1020=1088, 1040=1102' -> {1020: 1088, 1040: 1102}  (EDIT frame = PLATE frame)"""
    out = {}
    for tok in re.split(r'[,\s]+', str(text or '').strip()):
        if not tok:
            continue
        m = re.match(r'^(-?\d+)=(-?\d+)$', tok)
        if not m:
            raise ValueError(_t('고정점 형식 오류: %s (EDIT=PLATE)',
                                'Invalid pin format: %s (EDIT=PLATE)') % tok)
        out[int(m.group(1))] = int(m.group(2))
    return out


def format_frame_ranges(frames):
    """"""
    return _ranges(sorted(frames)) if frames else ''


def tc_plan(tcf, raw, pf, pl, b0, E, tentative=False):
    """ edit TC reading -> how to use it for this plate (independent of Nuke)
    tcf: per-frame confident TC frame count (None), raw: dict(values, conf) decoded values / margins of unconfident frames (None if absent)
    b0: TC frame count of the plate's first frame pf (tentative = no metadata so provisionally 0)
    Returns dict(mode, coverage, in_range, pins_abs {t: plate frame}, hints_abs {t: frame | (frame, w)})
      mode 'first' : coverage >= TC_FIRST_COV, inside range >= TC_FIRST_INRANGE -> confident TC as pin candidates + the rest as weak hints
      mode 'hint'  : conditions not met but plate TC metadata exists -> the same hints as 4.x (confident TC inside the range)
      mode 'off'   : no TC / the range does not fit with the tentative b0
    """
    conf = dict((t, pf + (v - b0)) for t, v in enumerate(tcf or []) if v is not None)
    inr = dict((t, f) for t, f in conf.items() if pf <= f <= pl)
    cov = len(conf) / float(max(E, 1))
    frac_in = len(inr) / float(len(conf)) if conf else 0.0
    out = dict(mode='off', coverage=cov, in_range=frac_in, confident=len(conf), pins_abs={}, hints_abs={},
               tentative=bool(tentative), b0=int(b0))
    if conf and cov >= TC_FIRST_COV and frac_in >= TC_FIRST_INRANGE:
        out['mode'] = 'first'
        out['pins_abs'] = inr
        if raw:
            for t, (v, c) in enumerate(zip(raw.get('values') or [], raw.get('conf') or [])):
                if t in conf or v is None or c <= 0:
                    continue
                f = pf + (int(v) - b0)
                if pf <= f <= pl:
                    out['hints_abs'][t] = (f, float(min(1.0, c / TCO_CONF_MIN)))
    elif inr and not tentative:
        out['mode'] = 'hint'
        out['hints_abs'] = inr
    return out


def tc_preflight_cache_key(edit_key, plate_key, fps, roi, tc_signature, color_signature):
    """Immutable inputs that make a per-plate TC preflight result reusable."""
    rr = tuple(round(float(v), 8) for v in roi) if roi is not None else None
    return (str(edit_key or ''), str(plate_key or ''), round(float(fps), 6), rr,
            tuple(tc_signature or ()), str(color_signature or ''))


def tc_preflight_result_is_current(result, cache_key):
    """A displayed badge is valid only for the exact inputs that produced it."""
    return bool(result and result.get('_cache_key') == cache_key)


def tc_preflight_display_result(result, cache_key):
    """Attach immutable provenance to the UI copy without polluting the reusable cache."""
    shown = dict(result or {})
    shown['_cache_key'] = cache_key
    return shown


def read_signature_file_frame(mode, frame_value, first, output_frame):
    """Resolve safe Read expressions for cache identity without evaluating arbitrary Tcl/Python."""
    resolved = read_file_frame(mode, frame_value, first, output_frame)
    if resolved is not None:
        return resolved
    normalized_mode = str(mode or 'expression').strip().lower().replace('_', ' ')
    expression = re.sub(r'\s+', '', str(frame_value or ''))
    match = re.match(r'^frame(?:([+-])(\d+))?$', expression) if normalized_mode == 'expression' else None
    if not match:
        return None
    delta = int(match.group(2) or 0) * (-1 if match.group(1) == '-' else 1)
    return int(output_frame) + delta


def read_source_path(file_path, mode, frame_value, read_first, output_frame):
    """Resolve one local Read source path without evaluating Tcl/Python expressions."""
    source = os.path.expandvars(os.path.expanduser(str(file_path or '')))
    unresolved = r'%[A-Za-z_]+|\{[^{}]+\}|\[[^\[\]]+\]|\$(?:[A-Za-z_][A-Za-z0-9_]*|\{[^{}]+\})'
    patterned = bool(re.search(r'%0?\d*d|#', source))
    if not patterned:
        return None if re.search(unresolved, source) else source
    file_frame = read_signature_file_frame(mode, frame_value, read_first, output_frame)
    if file_frame is None:
        return None
    if re.search(r'%0?\d*d', source):
        def replace_percent(match):
            width = int(match.group(1) or 0)
            return ('%0*d' % (width, file_frame)) if width else str(file_frame)
        source = re.sub(r'%0?(\d*)d', replace_percent, source)
    elif '#' in source:
        source = re.sub(r'#+', lambda match: '%0*d' % (len(match.group(0)), file_frame), source)
    return None if re.search(unresolved, source) else source


def read_input_preflight(node, first=None, last=None):
    """Cheap local Read validation before thumbnail rendering.

    Missing movies/all frames and host Read errors are fatal.  A partial image
    sequence is explicit but nonfatal because Nuke may apply its configured
    before/after behavior; callers must surface the affected output frames.
    Unknown frame expressions stay unresolved rather than being called missing.
    """
    try:
        host_error = node.error()
    except Exception:
        host_error = ''
    if host_error:
        return dict(fatal=True, reason='read_error', detail=str(host_error),
                    checked_frames=0, missing_frames=[], missing_paths=[])
    try:
        knobs = node.knobs()
        source = str(node['file'].value()) if 'file' in knobs else ''
        read_first = int(node.firstFrame())
        first = read_first if first is None else int(first)
        last = int(node.lastFrame()) if last is None else int(last)
        mode = node['frame_mode'].value() if 'frame_mode' in knobs else 'expression'
        frame_value = node['frame'].value() if 'frame' in knobs else ''
    except Exception as error:
        return dict(fatal=False, reason='unresolved_mapping', detail=str(error),
                    checked_frames=0, missing_frames=[], missing_paths=[])
    frames = list(range(min(first, last), max(first, last) + 1))
    resolved = [read_source_path(source, mode, frame_value, read_first, frame) for frame in frames]
    if not source or any(path is None for path in resolved):
        return dict(fatal=False, reason='unresolved_mapping', detail='',
                    checked_frames=0, missing_frames=[], missing_paths=[])
    exists = {}
    for path in resolved:
        if path not in exists:
            exists[path] = os.path.isfile(path)
    missing_frames = [frame for frame, path in zip(frames, resolved) if not exists[path]]
    missing_paths = sorted(set(path for path in resolved if not exists[path]))
    if not missing_frames:
        reason, fatal = 'ok', False
    elif len(missing_frames) == len(frames):
        reason, fatal = 'source_missing', True
    else:
        reason, fatal = 'frames_missing', False
    return dict(fatal=fatal, reason=reason, detail='', checked_frames=len(frames),
                missing_frames=missing_frames, missing_paths=missing_paths)


def read_input_preflight_text(label, result):
    """User-facing summary for a structured Read preflight result."""
    result = result or {}
    reason = result.get('reason')
    if reason == 'read_error':
        detail = result.get('detail')
        if detail in ('', 'True'):
            # Nuke's Node.error() is a bool, so the old text printed a bare "True"; the usual cause is an unusable Read colorspace.
            return _t('%s Read에 오류가 있습니다. 파일 경로와 Read의 색공간(colorspace)을 확인하고 이 프로젝트의 OCIO 설정에 있는 색공간으로 지정하세요.',
                      '%s Read has an error. Check the file path and set the Read colorspace to one that exists in this project\'s OCIO config.') % label
        return _t('%s Read 오류: %s', '%s Read error: %s') % (label, detail or '-')
    if reason == 'source_missing':
        paths = result.get('missing_paths') or []
        target = paths[0] if len(paths) == 1 else _t('%d개 파일', '%d files') % len(paths)
        return _t('%s 입력 파일을 찾을 수 없습니다: %s',
                  '%s input file was not found: %s') % (label, target)
    if reason == 'frames_missing':
        frames = result.get('missing_frames') or []
        return _t('%s 입력 프레임 누락: %s',
                  '%s input frames missing: %s') % (label, format_frame_ranges(frames))
    return ''


def read_source_stat_signature(node):
    """Identity of every source file visible across the Read analysis range."""
    try:
        knobs = node.knobs()
        path = str(node['file'].value()) if 'file' in knobs else ''
    except Exception:
        knobs, path = {}, ''
    if '%' not in path and '#' not in path:
        try:
            resolved = nuke.filename(node) if node.Class() == 'Read' else None
            if resolved:
                path = str(resolved)
        except Exception:
            pass
    path = os.path.expandvars(os.path.expanduser(path))
    try:
        first, last = int(node.firstFrame()), int(node.lastFrame())
        mode = node['frame_mode'].value() if 'frame_mode' in knobs else 'expression'
        frame_value = node['frame'].value() if 'frame' in knobs else ''
    except Exception:
        first, last, mode, frame_value = 0, 0, 'expression', ''

    patterned_path = bool(re.search(r'%0?\d*d|%[A-Za-z_]+|\{[^{}]+\}', path) or '#' in path)

    def has_unresolved_tokens(source):
        return bool(re.search(r'%[A-Za-z_]+|\{[^{}]+\}', source))

    def resolved_path(output_frame):
        file_frame = read_signature_file_frame(mode, frame_value, first, output_frame)
        if file_frame is None:
            return None
        source = path
        if re.search(r'%0?\d*d', source):
            source = re.sub(r'%0?(\d*)d', lambda match: ('%0*d' % (int(match.group(1) or 0), file_frame))
                            if match.group(1) else str(file_frame), source)
        elif '#' in source:
            source = re.sub(r'#+', lambda match: '%0*d' % (len(match.group(0)), file_frame), source)
        return None if has_unresolved_tokens(source) else source

    files = []
    seen = set()
    unresolved = False
    for output_frame in range(min(first, last), max(first, last) + 1):
        source = resolved_path(output_frame)
        if source is None:
            unresolved = True
            continue
        if source not in seen:
            seen.add(source)
            files.append(source)
    if unresolved and patterned_path:
        import glob
        wildcard = re.sub(r'%0?\d*d', '*', path)
        wildcard = re.sub(r'%[A-Za-z_]+', '*', wildcard)
        wildcard = re.sub(r'\{[^{}]+\}', '*', wildcard)
        wildcard = re.sub(r'#+', '*', wildcard)
        files = sorted(glob.glob(wildcard))
    elif unresolved and not files:
        files = [path]
    digest = hashlib.sha256()
    for source in files:
        try:
            stat = os.stat(source)
            item = (os.path.realpath(source),
                    int(getattr(stat, 'st_mtime_ns', int(stat.st_mtime * 1e9))), int(stat.st_size))
            item += (int(getattr(stat, 'st_ctime_ns', int(stat.st_ctime * 1e9))), int(stat.st_ino))
        except (OSError, ValueError, TypeError):
            item = (source, '<unavailable>')
        digest.update(repr(item).encode('utf-8'))
    return (len(files), digest.hexdigest())


def read_analysis_signature(node):
    """Read identity plus every local mapping/input setting that changes analysis pixels."""
    fields = ('file', 'origfirst', 'origlast', 'frame_mode', 'frame', 'before', 'after',
              'colorspace', 'raw', 'premultiplied')
    try:
        knobs = node.knobs()
    except Exception:
        knobs = {}
    values = []
    for key in fields:
        try:
            values.append((key, repr(node[key].value()) if key in knobs else '<missing>'))
        except Exception:
            values.append((key, '<read-error>'))
    try:
        name = node.fullName()
    except Exception:
        name = '<unknown>'
    try:
        frame_range = (int(node.firstFrame()), int(node.lastFrame()))
    except Exception:
        frame_range = ('<read-error>', '<read-error>')
    return (name, frame_range, tuple(values), read_source_stat_signature(node))


def tc_config_signature(cfg):
    """Compact content signature so direct ROI/OCR calibration edits invalidate preflight."""
    import hashlib
    digest = hashlib.sha1()

    def add(value):
        if isinstance(value, dict):
            for key in sorted(value, key=lambda item: repr(item)):
                digest.update(repr(key).encode('utf-8'))
                add(value[key])
        elif isinstance(value, (list, tuple)):
            digest.update(('seq:%d' % len(value)).encode('ascii'))
            for item in value:
                add(item)
        elif isinstance(value, np.ndarray):
            arr = np.ascontiguousarray(value)
            digest.update(('array:%s:%s' % (arr.dtype, arr.shape)).encode('ascii'))
            digest.update(arr.tobytes())
        else:
            digest.update(repr(value).encode('utf-8'))
    add(cfg or {})
    return digest.hexdigest()


def tc_config_for_plate(saved_cfg, roi=None):
    """Use a stable-key plate TC crop while retaining the saved OCR calibration as fallback."""
    cfg = dict(saved_cfg or {})
    if roi is not None:
        cfg['roi'] = normalize_manual_roi(roi)
    return cfg


def tc_config_has_roi(cfg):
    """OCR can run from a per-plate ROI even when no project calibration was saved."""
    return bool(isinstance(cfg, dict) and cfg.get('roi') is not None)


def tc_preflight_assess(tcf, pf, pl, b0, image_path=None, image_verified=None,
                        tentative=False, image_mismatch=False, image_offset=None,
                        image_mismatch_count=0, min_image=3):
    """Classify OCR, source-range compatibility and independent image evidence separately.

    ``image_verified`` is provenance from image matching, not a TC-derived path.  Matching
    numeric TC therefore remains held until this independent evidence exists.
    """
    vals = list(tcf or [])
    readable = [(t, int(v)) for t, v in enumerate(vals) if v is not None]
    coverage = len(readable) / float(max(len(vals), 1))
    ocr_state = 'unreadable' if not readable else ('readable' if coverage >= TC_FIRST_COV else 'partial')
    ocr = dict(state=ocr_state, coverage=coverage, count=len(readable), total=len(vals))

    if b0 is None:
        range_info = dict(state='unknown', in_range=0.0, reason='source_tc_unavailable')
    elif not readable:
        range_info = dict(state='unknown', in_range=0.0, reason='edit_tc_unreadable')
    else:
        expected = dict((t, int(pf) + value - int(b0)) for t, value in readable)
        in_range = sum(int(pf) <= frame <= int(pl) for frame in expected.values()) / float(len(expected))
        state = 'tentative' if tentative else ('compatible' if in_range >= TC_FIRST_INRANGE else 'mismatch')
        range_info = dict(state=state, in_range=in_range, expected=expected)

    image = dict(state='unverified', count=0, offset=None)
    if image_path is not None and readable:
        path = np.asarray(image_path)
        expected = range_info.get('expected') or {}
        verified = dict(image_verified or {})
        samples = []
        for t, frame in expected.items():
            if 0 <= t < len(path) and t in verified and int(verified[t]) == int(path[t]):
                samples.append(int(path[t]) - int(frame))
        image['count'] = len(samples)
        if len(samples) >= min_image:
            values, counts = np.unique(samples, return_counts=True)
            k = int(np.argmax(counts))
            if int(counts[k]) >= max(min_image, int(math.ceil(.8 * len(samples)))):
                off = int(values[k])
                image.update(state='match' if off == 0 else 'offset', offset=off)
            else:
                image['state'] = 'mismatch'
        elif image_offset not in (None, 0):
            image.update(state='offset', offset=int(image_offset))
        elif image_mismatch and int(image_mismatch_count or 0) >= int(min_image):
            # Only an explicit solver veto is mismatch. Flat/dark/ambiguous imagery remains
            # unverified so missing evidence is not misreported as a different source.
            image.update(state='mismatch', count=max(image['count'], int(image_mismatch_count or 0)))

    state = 'ready' if (ocr_state == 'readable' and range_info['state'] == 'compatible'
                        and image['state'] == 'match') else \
            'rejected' if image['state'] == 'mismatch' else 'held'
    return dict(state=state, ocr=ocr, range=range_info, image=image)


def tc_preflight_from_result(tcf, pf, pl, result, plate_offset=0):
    """Build the preflight assessment from solver provenance without inventing a TC base."""
    plan = result.get('tc_plan') or {}
    tc_info = result.get('tc') or {}
    path = int(plate_offset) + np.asarray(result['path'])
    verified = dict((int(t), int(plate_offset) + int(q)) for t, q in
                    (tc_info.get('image_verified') or {}).items())
    if tc_info.get('mode') == 'increment_mismatch':
        mismatch_count = int(tc_info.get('increment_pairs') or 0)
    else:
        mismatch_count = int(round(float(tc_info.get('disagree_frac') or 0.0) *
                                   int(tc_info.get('candidates') or 0)))
    return tc_preflight_assess(
        tcf, pf, pl, plan.get('b0'), image_path=path, image_verified=verified,
        tentative=bool(plan.get('tentative')),
        image_mismatch=(tc_info.get('mode') in ('mismatch', 'increment_mismatch') and mismatch_count >= 3),
        image_mismatch_count=mismatch_count,
        image_offset=tc_info.get('offset') if tc_info.get('mode') == 'offset' else None)


def tc_base_from_path(tcf, pidx, E_valid, lowq=None, share=0.6, min_n=8):
    """ mode of (confident TC - image path (index relative to the plate first frame)) = estimate of the plate first frame's TC count.
    Only frames where the image is certain (valid, not low quality). Only when the mode ratio >= share and samples >= min_n: (b0, match count, sample count)"""
    lowq = set(lowq or [])
    d = [int(v) - int(p) for t, (v, p) in enumerate(zip(tcf, pidx))
         if v is not None and E_valid[t] and t not in lowq]
    if len(d) < min_n:
        return None
    vals, cnt = np.unique(d, return_counts=True)
    k = int(np.argmax(cnt))
    if cnt[k] < share * len(d):
        return None
    return int(vals[k]), int(cnt[k]), len(d)


def tc_base_from_reliable_path(tcf, pidx, res, pins=None, exclude=None):
    """Recover TC origin from independent image islands, never ambiguous/forced frames.

    Used only after the normal whole-path vote fails. The recovered origin still
    has to pass tc_plan and the normal image veto before it can constrain time.
    """
    if tcf is None:
        return None
    n = len(pidx)
    valid = np.asarray(res['E_valid'], bool).copy()
    if len(valid) != n or len(tcf) != n:
        return None
    for span in res.get('near_hold') or []:
        if span.get('tier') in ('ambiguous', 'weak') or span.get('unsure'):
            a, b = max(0, int(span['t0'])), min(n, int(span['t1']) + 1)
            valid[a:b] = False
    blocked = set(res.get('lowq') or []) | set(pins or {})
    if exclude is not None:
        excluded = np.asarray(exclude)
        blocked.update(np.flatnonzero(excluded) if excluded.dtype == bool else excluded.tolist())
    for t in blocked:
        if 0 <= t < n:
            valid[t] = False
    times = np.asarray([t for t, v in enumerate(tcf) if v is not None and valid[t]], int)
    if len(times) < 8:
        return None
    offsets = np.asarray([int(tcf[t]) - int(pidx[t]) for t in times])
    values, counts = np.unique(offsets, return_counts=True)
    best = int(np.argmax(counts))
    votes = int(counts[best])
    if votes < 8 or votes < .8 * len(times):
        return None
    # A second repeated origin is evidence of a competing segment, not OCR noise.
    if len(counts) > 1 and int(np.max(np.delete(counts, best))) >= 3:
        return None
    agrees = offsets == values[best]
    winners = times[agrees]
    # Split the reliable samples, not the whole clip: an ambiguous middle
    # interval deliberately has no votes. Do not extrapolate from one short island.
    if winners[-1] - winners[0] < .5 * max(n - 1, 1):
        return None
    if any(np.count_nonzero(part) < 2 for part in np.array_split(agrees, 3)):
        return None
    return int(values[best]), votes, len(times)


def static_line_retry_path(U, path, E_valid, P_valid, slope_radius=0.20, intercept_radius=12.0):
    """Fit one global constant-rate path to a wandering image path using only image cost."""
    U = np.asarray(U, np.float64)
    path = np.asarray(path, int)
    valid = np.asarray(E_valid, bool)
    pvalid = np.asarray(P_valid, bool)
    vt = np.where(valid)[0]
    E, P = U.shape
    if len(path) != E or len(pvalid) != P or len(vt) < 16:
        return None, dict(reason='few')
    A = np.vstack([np.ones(len(vt)), vt.astype(np.float64)]).T
    intercept, slope = np.linalg.lstsq(A, path[vt].astype(np.float64), rcond=None)[0]
    if not np.isfinite(slope) or abs(slope) > 16.0:
        return None, dict(reason='slope')
    tt = np.arange(E, dtype=np.float64)
    best = None
    for r in np.arange(slope - slope_radius, slope + slope_radius + 1e-9, 0.01):
        for a in np.arange(intercept - intercept_radius, intercept + intercept_radius + 1e-9, 0.5):
            candidate = np.round(a + r * tt).astype(int)
            if candidate.min() < 0 or candidate.max() >= P or not pvalid[candidate[vt]].all():
                continue
            values = U[vt, candidate[vt]]
            if not np.isfinite(values).all():
                continue
            values = np.sort(values)
            keep = max(1, int(0.8 * len(values)))
            score = float(values[:keep].mean())
            if best is None or score < best[0]:
                best = (score, candidate, float(a), float(r))
    if best is None:
        return None, dict(reason='no_line')
    return best[1], dict(trimmed_cost=best[0], intercept=best[2], slope=best[3])


def _static_retry_times(E_lum, E_valid, fit_count=8):
    """Spread fit frames plus one disjoint held-out high-texture frame per time third."""
    valid = np.where(np.asarray(E_valid, bool))[0]
    if len(valid) < 16:
        return [], []

    def strongest(part, blocked=()):
        blocked = set(blocked)
        pool = [int(t) for t in part if int(t) not in blocked]
        if not pool:
            return None
        energy = [texture_energy(to_display(E_lum[t])) for t in pool]
        return pool[int(np.argmax(energy))]

    fit = []
    for part in np.array_split(valid, min(fit_count, len(valid))):
        t = strongest(part)
        if t is not None:
            fit.append(t)
    hold = []
    for part in np.array_split(valid, 3):
        t = strongest(part, fit)
        if t is not None:
            hold.append(t)
    return fit, hold


def _static_retry_optical_valid(opt):
    """The retry cannot widen the engine's supported static geometry range."""
    try:
        s, tx, ty = (float(opt[k]) for k in ('s', 'tx', 'ty'))
    except (KeyError, TypeError, ValueError):
        return False
    return bool(np.isfinite([s, tx, ty]).all() and SCALE_MIN <= s <= SCALE_MAX
                and abs(tx) <= 0.5 and abs(ty) <= 0.5)


def static_line_optical_candidate(E_lum, P_lum, P_valid, res, cancelled=None, log=print, max_iter=4):
    """Alternately fit a global time line and static optical transform; return an untrusted candidate."""
    E_lum = np.asarray(E_lum, np.float32)
    P_lum = np.asarray(P_lum, np.float32)
    E_valid = np.asarray(res.get('E_valid'), bool)
    P_valid = np.asarray(P_valid, bool)
    base_opt = dict(res.get('optical') or {})
    if not base_opt or base_opt.get('region', 'full') != 'full' or base_opt.get('rmask') is not None:
        return None
    mask0 = edit_static_mask(E_lum)
    mask0 &= ~overlay_mask(E_lum, mask0)[0]
    fit_times, hold_times = _static_retry_times(E_lum, E_valid)
    if len(fit_times) < 5 or len(hold_times) < 3:
        return None
    opt = dict(base_opt)
    last_line, last_info = None, None
    iterations = 0
    for iterations in range(1, max(1, int(max_iter)) + 1):
        if cancelled is not None and cancelled():
            raise Cancelled()
        warped, coverage = warp_plate_stack(P_lum, opt, E_lum.shape[1], E_lum.shape[2])
        mask = mask0 & coverage
        if mask.sum() < 64:
            return None
        Ef = rank_rows(E_lum[:, mask])
        Pf = rank_rows(warped[:, mask])
        U = cost_matrix(Ef, Pf, _cells(mask), E_valid)
        # Re-read the image path after every optical update. Reusing the original
        # path would keep the line search centred on the very feedback error this
        # retry is meant to break.
        image_path = dp_path(U, E_valid, P_valid, pins={}, hints={},
                             jumps=np.zeros(len(E_valid), bool),
                             max_speed=16, direction_policy=False)
        line, info = static_line_retry_path(U, image_path, E_valid, P_valid)
        if line is None:
            return None
        pairs = [(int(t), int(line[t])) for t in fit_times]
        nxt = refine_optical_pairs(E_lum, mask, P_lum, pairs, opt, log=lambda *a: None,
                                   limits=(0.08, 0.04, 0.04))
        last_line, last_info = line, info
        if optical_same(nxt, opt, ds=0.0005, dt=0.00025):
            opt = nxt
            break
        opt = nxt
    if cancelled is not None and cancelled():
        raise Cancelled()
    if not _static_retry_optical_valid(opt):
        return None
    if optical_same(opt, base_opt, ds=0.001, dt=0.0005):
        return None
    out = dict(opt)
    out.pop('note', None)
    out['static_line_retry'] = dict(iterations=int(iterations), fit_times=fit_times,
                                    hold_times=hold_times, line=last_line.tolist(), line_info=last_info)
    log(_t('  static-line optical candidate: %d회, s %.4f -> %.4f, move %.4f -> %.4f', '  static-line optical candidate: %d trials, s %.4f -> %.4f, move %.4f -> %.4f') % (
        iterations, float(base_opt['s']), float(out['s']),
        math.hypot(float(base_opt['tx']), float(base_opt['ty'])),
        math.hypot(float(out['tx']), float(out['ty']))))
    return out


def static_line_retry_allowed(res, opts, user_pins, user_hints, exclude):
    """Narrow gate: weak static image-only solves with no user/TC/split authority."""
    if not opts.get('optical') or opts.get('tc') or opts.get('split'):
        return False
    if user_pins or user_hints or np.asarray(exclude, bool).any():
        return False
    if (res.get('track') or {}).get('animated') or (res.get('split') or {}).get('split'):
        return False
    opt = res.get('optical') or {}
    if opt.get('region', 'full') != 'full' or opt.get('rmask') is not None:
        return False
    path = res.get('path')
    if path is None or len(path) < 16 or len(res.get('cuts') or []) < 2 or not image_weak(res):
        return False
    blended = np.asarray(res.get('blended') if res.get('blended') is not None else [], bool)
    if len(blended) and float(blended.mean()) >= 0.20:
        return False
    for span in res.get('near_hold') or []:
        if span.get('tier') == 'ambiguous' or span.get('tc') or span.get('pinned'):
            return False
    return True


def static_line_retry_holdout(E_lum, P_lum, base, candidate, hold_times):
    """NCC on three disjoint time regions using each result's actual path and static transform."""
    old_opt, new_opt = base['optical'], candidate['optical']
    mask = edit_static_mask(E_lum)
    mask &= ~overlay_mask(E_lum, mask)[0]
    mask &= _coverage(old_opt, E_lum.shape[1], E_lum.shape[2], P_lum.shape[1], P_lum.shape[2])
    mask &= _coverage(new_opt, E_lum.shape[1], E_lum.shape[2], P_lum.shape[1], P_lum.shape[2])
    Pm = blur121(P_lum)
    before, after = [], []
    for t in hold_times:
        po, pn = int(base['path'][t]), int(candidate['path'][t])
        if not (0 <= po < len(Pm) and 0 <= pn < len(Pm)):
            continue
        before.append(_score_pairs(E_lum[t:t + 1], mask, Pm[po:po + 1],
                                   old_opt['s'], old_opt['tx'], old_opt['ty'], old_opt['flop']))
        after.append(_score_pairs(E_lum[t:t + 1], mask, Pm[pn:pn + 1],
                                  new_opt['s'], new_opt['tx'], new_opt['ty'], new_opt['flop']))
    return dict(before=before, after=after)


def static_line_retry_accept(base, candidate, heldout):
    """Conservative result boundary for the untrusted static-line candidate."""
    if not image_weak(base) or len(base.get('cuts') or []) < 2:
        return False, 'base_not_weak'
    if candidate is None or candidate.get('track') is not None or (candidate.get('split') or {}).get('split'):
        return False, 'candidate_not_static'
    if not _static_retry_optical_valid(candidate.get('optical') or {}):
        return False, 'optical_range'
    q0, q1 = float(base.get('quality', 1.0)), float(candidate.get('quality', 1.0))
    if not np.isfinite(q1) or q1 > q0 * 0.85:
        return False, 'quality'
    c0, c1 = len(base.get('cuts') or []), len(candidate.get('cuts') or [])
    # This recovery claims one global constant-rate shot. Any surviving cut
    # contradicts that claim and could merely relocate an existing false cut.
    if c1:
        return False, 'cuts'
    before = np.asarray((heldout or {}).get('before') or [], np.float64)
    after = np.asarray((heldout or {}).get('after') or [], np.float64)
    if len(before) < 3 or len(after) != len(before) or not (np.isfinite(before).all() and np.isfinite(after).all()):
        return False, 'heldout_missing'
    gain = after - before
    if int((gain > 0.002).sum()) < 2 or float(gain.min()) < -0.003 or float(gain.mean()) < 0.004:
        return False, 'heldout'
    conf0, conf1 = base.get('confidence') or {}, candidate.get('confidence') or {}
    h0, h1 = conf0.get('half'), conf1.get('half')
    if h0 is not None and h1 is not None and h1 + 1e-9 < h0:
        return False, 'half'
    if (conf1.get('amb') or 0.0) > (conf0.get('amb') or 0.0) + 0.02:
        return False, 'ambiguous'
    if len(candidate.get('reversals') or []) > len(base.get('reversals') or []):
        return False, 'curve'
    blend0 = np.asarray(base.get('blended') if base.get('blended') is not None else [], bool)
    blend1 = np.asarray(candidate.get('blended') if candidate.get('blended') is not None else [], bool)
    if len(blend1) and float(blend1.mean()) > max(0.20, (float(blend0.mean()) if len(blend0) else 0.0) + 0.05):
        return False, 'blend'
    return True, 'strong_image_recovery'


def _process_plate(plate, E_lum, opts, ctx, excl, pin_frames, tcf, ef, tc_raw=None, region=None):
    """ one plate: range search -> render -> analysis. Returns (res, lo, timing)
    JobCtx, exclusion ranges, pins, lagging-TC hints. Stage 1 (stride) is skipped when TC is sufficient
    TC-first mode (tc_plan): confident TC as pin candidates (image veto / offset check happen inside solve)
    """
    import time
    log = ctx.log
    pf, pl = plate.firstFrame(), plate.lastFrame()
    P_total = pl - pf + 1
    E = E_lum.shape[0]
    timing = {}

    hint_abs, tcp = {}, None
    if tcf:
        base = plate_tc_base(plate, pf, pl, log, allow_missing=True)
        if base:
            tcp = tc_plan(tcf, tc_raw, pf, pl, base[1], E, tentative=len(base) > 2 and base[2])
            tcp['fps'] = base[0]
            if len(base) > 3:  # reference read from the file's tmcd / rtmd track
                tcp['b0_src'] = base[3]
            log(_t('[%s] 렉TC: %s — 확신 %d프레임 (커버리지 %.0f%%, 플레이트 범위 안 %.0f%%%s)', '[%s] Burn-in TC: %s — %d confident frames (coverage %.0f%%, within plate range %.0f%%%s)') % (
                plate.name(), {'first': _t('TC 우선', 'TC first'), 'hint': _t('힌트', 'Hint'), 'off': _t('사용 안 함', 'Off')}[tcp['mode']],
                tcp['confident'], 100 * tcp['coverage'], 100 * tcp['in_range'],
                _t(', 플레이트 TC 메타데이터 없음 -> 첫 프레임 = 00:00:00:00 잠정', ', no plate TC metadata -> provisional first-frame TC = 00:00:00:00') if tcp['tentative'] else ''))
    pins_abs = {}
    for fe, fp in (pin_frames or {}).items():
        t = fe - ef
        if 0 <= t < E and pf <= fp <= pl:
            pins_abs[t] = fp
    tc_pins_abs = dict((t, f) for t, f in (tcp['pins_abs'] if tcp and tcp['mode'] == 'first' else {}).items()
                       if t not in pins_abs)
    tc_weak_abs = tcp['hints_abs'] if tcp and tcp['mode'] == 'first' else {}
    # hint mode (the 4.x method) also goes through the same offset / mismatch check - on a set where the burn-in is 1 frame later than the picture, 4.x hints
    # pulled a 1x edit from 100% to 62% (measured). Only TCs that pass the check become hints
    tc_hint_abs = tcp['hints_abs'] if tcp and tcp['mode'] == 'hint' else {}

    lo, hi, init_opt = pf, pl, None
    rng_tc = tc_pins_abs or tc_hint_abs
    if len(rng_tc) >= 0.3 * E:
        hv = np.array(sorted(rng_tc.values()))
        # so a few misreads do not skew the range: quantile + generous margin
        q0, q1 = np.percentile(hv, 3), np.percentile(hv, 97)
        lo = max(pf, int(q0) - 32)
        hi = min(pl, int(q1) + 32)
        log(_t('plate range %d-%d (렉TC 기준, 구간 탐색 생략)', 'plate range %d-%d (from burn-in TC, skip range search)') % (lo, hi))
    elif P_total > COARSE_MIN_FRAMES:
        S = max(2, int(math.ceil(P_total / float(COARSE_TARGET))))
        ctx.progress(0.0, _t('[%s] 구간 탐색 (x%d)', '[%s] Range search (x%d)') % (plate.name(), S))
        nA, secA = ensure_thumbs(plate, pf, pl, S, W_PLATE, True, log)
        timing['scan'] = secA
        fA = list(range(pf, pl + 1, S))
        P_A, okA = load_thumbs(plate, fA, W_PLATE, log)
        if identical_thumbs(P_A, okA):
            raise RuntimeError(_t('[%s] PLATE 썸네일 %d장이 전부 같은 그림입니다 — Read 의 frame range(first/last)가 한 프레임에 고정됐는지 확인해 주세요', '[%s] All %d PLATE thumbnails are identical — check whether the Read frame range (first/last) is fixed to one frame') % (plate.name(), int(okA.sum())))
        if ctx.cancelled():
            raise Cancelled()
        ctx.progress(0.2)
        ia, ib, init_opt = locate_range(E_lum, P_A, okA, opts['optical'], opts['flop'], log,
                                        split=opts['split'], exclude=excl, region=region)
        margin = 2 * S + RANGE_MARGIN
        lo = max(pf, fA[ia] - margin)
        hi = min(pl, fA[ib] + margin)
        log('plate range %d-%d (of %d-%d)' % (lo, hi, pf, pl))
        spf = secA / nA if nA else 0.0
        dB = _thumb_dir(plate, W_PLATE)
        nB = sum(1 for f in range(lo, hi + 1) if not os.path.exists('%s/t.%06d.exr' % (dB, f)))
        est = spf * nB
        Hp = _thumb_size(plate, W_PLATE)[2]
        mem = (hi - lo + 1) * W_PLATE * Hp * 4 * 8 / 1e9
        if est > WARN_SECONDS or mem > WARN_MEM_GB:
            if not ctx.ask(_t('[%s] %d-%d 렌더 예상 %.1f분, 메모리 약 %.1fGB 입니다.\n진행할까요?', '[%s] Rendering %d-%d is estimated to take %.1f minutes and about %.1f GB of memory.\nContinue?')
                           % (plate.name(), lo, hi, est / 60.0, mem)):
                raise Cancelled(_t('렌더 예상 시간 초과로 건너뜀', 'Skipped because the estimated render time exceeds the limit'))
    if pins_abs:
        lo = max(pf, min([lo] + [v - 4 for v in pins_abs.values()]))
        hi = min(pl, max([hi] + [v + 4 for v in pins_abs.values()]))

    def prog(i, n):
        ctx.progress(0.6 + 0.35 * i / max(n, 1))
        return ctx.cancelled()
    tc_force = [False]  # re-run that follows TC when the image is weak

    def run(lo, hi, fresh=False, noflop=False, init=None, track_seed=False):
        ctx.progress(0.3, _t('[%s] 썸네일 %d-%d', '[%s] Thumbnails %d-%d') % (plate.name(), lo, hi))
        nB, secB = ensure_thumbs(plate, lo, hi, 1, W_PLATE, True, log)
        timing['plate'] = timing.get('plate', 0.0) + secB
        P_lum, p_ok = load_thumbs(plate, list(range(lo, hi + 1)), W_PLATE, log)
        if identical_thumbs(P_lum, p_ok):
            raise RuntimeError(_t('[%s] PLATE 썸네일 %d장이 전부 같은 그림입니다 — Read 의 frame range(first/last)가 한 프레임에 고정됐는지 확인해 주세요', '[%s] All %d PLATE thumbnails are identical — check whether the Read frame range (first/last) is fixed to one frame') % (plate.name(), int(p_ok.sum())))
        if ctx.cancelled():
            raise Cancelled()
        ctx.progress(0.55, _t('[%s] 분석', '[%s] Analyzing') % plate.name())
        t_an = time.time()
        r = solve(E_lum, P_lum, P_valid_files=p_ok,
                  max_speed=opts.get('max_speed', 16),
                  tc_track_values=tcf if track_seed else None,
                  detect_optical=opts['optical'], allow_flop=opts['flop'] and not noflop,
                  detect_slow_on=opts['slow'], log=log, progress=prog,
                  init_opt=init if init is not None else (None if fresh else init_opt),
                  abort_if_same=fresh if isinstance(fresh, (dict, list)) else None,
                  detect_split=opts['split'], track=opts['track'], region=region, exclude=excl,
                  pins=dict((t, v - lo) for t, v in pins_abs.items() if lo <= v <= hi),
                  hints=dict((t, v - lo) for t, v in hint_abs.items() if lo <= v <= hi),
                  tc=dict(pins=dict((t, v - lo) for t, v in tc_pins_abs.items() if lo <= v <= hi),
                          hints=dict((t, (v - lo, w)) for t, (v, w) in tc_weak_abs.items() if lo <= v <= hi),
                          force=tc_force[0])
                  if tc_pins_abs else
                  dict(mode='hint', pins=dict((t, v - lo) for t, v in tc_hint_abs.items() if lo <= v <= hi), hints={})
                  if tc_hint_abs else None)
        timing['analysis'] = timing.get('analysis', 0.0) + time.time() - t_an
        if r is None:
            return None
        if tcp is not None:
            r['tc_plan'] = dict((k, v) for k, v in tcp.items() if k not in ('pins_abs', 'hints_abs'))
        return r

    res = run(lo, hi)
    # stage 1 range safeguard: if the path sticks to the render range boundary or the result is weak, widen the range and run once more
    if lo > pf or hi < pl:
        pth = np.asarray(res['path'])
        n_rng = hi - lo + 1
        touch_lo = lo > pf and int(pth.min()) <= 1
        touch_hi = hi < pl and int(pth.max()) >= n_rng - 2
        weak = res.get('quality', 0) > WARN_QUALITY or any(
            not w.startswith('시간-이동') for w in (res.get('confidence_warn') or []))  # time-movement ambiguity is not a range problem
        if touch_lo or touch_hi or weak:
            ext = max(n_rng, 48)
            lo2 = max(pf, lo - ext) if (touch_lo or weak) else lo
            hi2 = min(pl, hi + ext) if (touch_hi or weak) else hi
            log(_t('[%s] 구간 재탐색 %d-%d -> %d-%d (%s)', '[%s] Range retry %d-%d -> %d-%d (%s)') % (plate.name(), lo, hi, lo2, hi2, ', '.join(
                k for k, v in ((_t('경로가 앞 경계', 'path at start boundary'), touch_lo), (_t('경로가 뒤 경계', 'path at end boundary'), touch_hi), (_t('결과 약함', 'weak result'), weak)) if v)))
            res2 = run(lo2, hi2)
            # A wider range contains the same path, so the cost should be equal or lower - if it got worse (accidental match in another range), keep the existing result
            if res2.get('quality', 1.0) <= res.get('quality', 1.0) * 1.05 or touch_lo or touch_hi:
                res, lo, hi = res2, lo2, hi2
                res['range_retry'] = True
    # if the optical from stage 1 (stride thumbnails) was reused and the result is weak, find a new optical on the rendered range and run once more.
    # The [time-movement ambiguity] warning is also a trigger: a local solution where the movement animation absorbed the time error on pan / tilt plates
    # (test06_zoom_out_flop_1x: path -191~-273, ty 0.02 -> 0.12, cost 0.106 - the range optical has movement 0.0015 and cost 0.052)
    shift_amb = any(w.startswith('시간-이동') for w in (res.get('confidence_warn') or []))
    multi_retry = not (image_weak(res) or shift_amb) and reused_optical_retry_allowed(
        res, init_opt, opts, pins_abs, excl,
        tc_authority=bool(tc_pins_abs or tc_hint_abs or tc_weak_abs or (tcp and tcp['mode'] == 'first')))
    if init_opt is not None and opts['optical'] and (image_weak(res) or shift_amb or multi_retry):
        log(_t('[%s] 옵티컬 재탐색 (1단계 옵티컬 재사용 결과 %s, s=%.3f flop=%s)', '[%s] Optical retry (reused first-stage optical result: %s, s=%.3f flop=%s)') % (
            plate.name(), _t('다중 프레임 일치 부족', 'insufficient multi-frame agreement') if multi_retry else _t('약함', 'weak') if image_weak(res) else _t('시간-이동 모호', 'time/translation ambiguity'),
            float(res['optical']['s']), res['optical']['flop']))
        # None (analysis skipped) if the new optical equals the current solution or equals the stage 1 optical that the first run reused
        # Small scale differences can change frame identity on moving footage.
        # The new multi-frame signal must not hit the same-transform shortcut.
        res_o = run(lo, hi, fresh=True if multi_retry else
                    [(res['optical'], 0.01, 0.005), (init_opt, 0.002, 0.001)])
        if res_o is not None:
            if multi_retry:
                P_check, _ = load_thumbs(plate, list(range(lo, hi + 1)), W_PLATE, log)
                heldout = reused_optical_retry_holdout(E_lum, P_check, res, res_o)
                ok_o = reused_optical_retry_accept(res, res_o, heldout)
            else:
                ok_o = retry_better(res, res_o)
            log(_t('[%s] 옵티컬 재탐색: %s', '[%s] Optical retry: %s') % (plate.name(), retry_text(res, res_o, ok_o)))
            if ok_o:
                res = res_o
                res['opt_retry'] = True
                if multi_retry:
                    res['reused_optical_retry'] = heldout
    # flop alternative: if still weak but solved with flop=True, run once more from the optical without flop (test01_zoom_out_freeze
    # stage 1 and range optical both flop=True s=1.07~1.09 giving 22.5 % - on the TC-pinned path flop=False s=1.12 gives 100 %)
    if opts['optical'] and opts['flop'] and res['optical'].get('flop') and image_weak(res):
        log(_t('[%s] flop 대안 (결과 약함, flop=True): flop 없이 옵티컬 재탐색', '[%s] Flop alternative (weak result, flop=True): retry optical matching without flop') % plate.name())
        res_n = run(lo, hi, fresh=True, noflop=True)
        ok_n = retry_better(res, res_n)
        log(_t('[%s] flop 대안: %s', '[%s] Flop alternative: %s') % (plate.name(), retry_text(res, res_n, ok_n)))
        if ok_n:
            res = res_n
            res['opt_retry'] = 'noflop'
    # scale-time ambiguity guard: if the static optical scale is far from 1 and the path is itself ambiguous (ambiguous >= SAMB_AMB, top/bottom agreement <
    # SAMB_HALF), the scale may be a local solution that absorbed the time error - with an advancing camera, 'enlarge the earlier frame' ~ 'the later frame'
    # (test01_slow_0p33x: s 1.37 / GT 1.0, stuck 30 frames early). Solve again with scale 1 (uncorrected) and compare with retry_better
    cf = res.get('confidence') or {}
    if opts['optical'] and res.get('track') is None and abs(float(res['optical']['s']) - 1.0) > SAMB_DS and \
            (cf.get('amb') or 0) >= SAMB_AMB and cf.get('half') is not None and cf['half'] < SAMB_HALF:
        log(_t('[%s] 배율-시간 모호 가드 (s=%.3f, 모호 %.0f%%, 상하 합의 %.0f%%): 배율 1 로 다시 풀어 비교', '[%s] Scale/time ambiguity guard (s=%.3f, ambiguous %.0f%%, upper/lower agreement %.0f%%): compare a new solve at scale 1') % (
            plate.name(), float(res['optical']['s']), 100 * cf['amb'], 100 * cf['half']))
        res_i = run(lo, hi, init=dict(s=1.0, tx=0.0, ty=0.0, flop=False, region='full', rmask=None, note='identity'))
        ok_i = retry_better(res, res_i)
        log(_t('[%s] 배율-시간 모호 가드: %s', '[%s] Scale/time ambiguity guard: %s') % (plate.name(), retry_text(res, res_i, ok_i)))
        if ok_i:
            res = res_i
            res['opt_retry'] = 'identity'
    # recovery for static IMG only: only when a single anchor position error wrongly reinforced the time path and the optical correspondence pairs against each other.
    # TC/user control/split/animation are untouched; candidates are made only in the narrow case where the result is itself weak and there are several false-positive cuts.
    # A candidate is accepted only after solving again and passing the held-out NCC for three distinct time segments plus the cost/cut/curve guards.
    if static_line_retry_allowed(res, opts, pins_abs, hint_abs, excl):
        t_sr = time.time()
        ctx.progress(0.54, _t('[%s] 정적 옵티컬 보수 재시도', '[%s] Conservative static optical retry') % plate.name())
        P_sr, ok_sr = load_thumbs(plate, list(range(lo, hi + 1)), W_PLATE, log)
        candidate_opt = static_line_optical_candidate(
            E_lum, P_sr, ok_sr, res, cancelled=ctx.cancelled, log=log)
        if candidate_opt is not None:
            res_sr = run(lo, hi, init=candidate_opt)
            hold_times = candidate_opt['static_line_retry']['hold_times']
            heldout = static_line_retry_holdout(E_lum, P_sr, res, res_sr, hold_times)
            ok_sr_, why_sr = static_line_retry_accept(res, res_sr, heldout)
            log(_t('[%s] 정적 옵티컬 보수 재시도: %s (%s; %s)', '[%s] Conservative static optical retry: %s (%s; %s)') % (
                plate.name(), retry_text(res, res_sr, ok_sr_), why_sr,
                'held-out ' + ', '.join('%+.4f' % (b - a) for a, b in zip(heldout['before'], heldout['after']))))
            if ok_sr_:
                res = res_sr
                res['opt_retry'] = 'static_line'
                res['static_line_retry'] = dict(candidate_opt['static_line_retry'], heldout=heldout,
                                                accepted=why_sr)
        timing['static_retry'] = timing.get('static_retry', 0.0) + time.time() - t_sr
    # Static precision uses a smaller hypothesis threshold than animation.
    # Re-solve all temporal/blend evidence; never carry the old fractional
    # metadata onto a replacement path or adopt a key median directly.
    if static_refine_retry_allowed(res, opts, pins_abs, hint_abs, excl,
                                   any(v is not None for v in (tcf or []))):
        t_static = time.time()
        sk = res['static_candidate']
        candidate_opt = dict(res['optical'], s=float(sk[0]), tx=float(sk[1]), ty=float(sk[2]))
        candidate_opt.pop('note', None)
        candidate = run(lo, hi, init=candidate_opt)
        if candidate is not None:
            P_static, _ = load_thumbs(plate, list(range(lo, hi + 1)), W_PLATE, log)
            used_times = set(res.get('static_candidate_used_times') or []) | set(
                candidate.get('static_candidate_used_times') or [])
            heldout = reused_optical_retry_holdout(E_lum, P_static, res, candidate,
                                                  excluded_times=used_times)
            candidate_steps = np.diff(np.asarray(candidate['path']))
            accepted = (np.all(candidate_steps >= 0) and np.any(candidate_steps > 0)
                        and not optical_retry_has_blend_evidence(candidate)
                        and reused_optical_retry_accept(res, candidate, heldout))
            log(_t('[%s] 고정 옵티컬 미세 보정: %s', '[%s] Fixed optical refinement: %s') % (
                plate.name(), retry_text(res, candidate, accepted)))
            if accepted:
                res = candidate
                res['static_refine_retry'] = dict(heldout=heldout)
        timing['static_refine'] = time.time() - t_static
    # A camera push-in can trade a small false scale against frame timing.
    # Identity is a competing image hypothesis, never a forced correction.
    if identity_challenger_allowed(res, opts, pins_abs, hint_abs, excl,
            bool(tc_pins_abs or tc_hint_abs or tc_weak_abs or (tcp and tcp['mode'] == 'first'))):
        t_identity = time.time()
        candidate = run(lo, hi, init=dict(s=1., tx=0., ty=0., flop=False,
                                         region='full', rmask=None, note='identity'))
        if candidate is not None:
            P_identity, _ = load_thumbs(plate, list(range(lo, hi + 1)), W_PLATE, log)
            used_times = set(res.get('static_candidate_used_times') or []) | set(
                candidate.get('static_candidate_used_times') or [])
            heldout = reused_optical_retry_holdout(E_lum, P_identity, res, candidate,
                                                  excluded_times=used_times)
            accepted = identity_challenger_accept(res, candidate, heldout)
            log(_t('[%s] 무보정 대안 검증: %s', '[%s] Uncorrected alternative validation: %s') % (plate.name(), retry_text(res, candidate, accepted)))
            if accepted:
                res = candidate
                res['identity_challenger'] = dict(heldout=heldout)
        timing['identity_challenger'] = time.time() - t_identity
    # fix the plate TC reference (b0) with the image path: if there is enough confident TC but it does not fit the plate range
    # (no metadata / a movie Reader could not read the tmcd track and gives 00:00:00:00, etc.), check whether (TC - image path) differences converge on one value
    # and if so retry TC-first with that b0 (the TC-first conditions + image veto are unchanged)
    if tcp is not None and tcp['mode'] != 'first' and tcp['confident'] >= TC_FIRST_COV * E:
        b0i = tc_base_from_path(tcf, lo + np.asarray(res['path']) - pf, res['E_valid'], res.get('lowq'))
        reliable_base = b0i is None
        if b0i is None:
            b0i = tc_base_from_reliable_path(
                tcf, lo + np.asarray(res['path']) - pf, res, pins=pins_abs, exclude=excl)
        if b0i is not None and b0i[0] != tcp['b0']:
            tcp2 = tc_plan(tcf, tc_raw, pf, pl, b0i[0], E)
            log(_t('[%s] 렉TC 기준을 이미지 경로로 추정: 첫 프레임 = %s (%d/%d 프레임 일치, 기존 %s) -> %s', '[%s] Estimate burn-in TC base from the image path: first frame = %s (%d/%d frames agree, previous %s) -> %s') % (
                plate.name(), frames_to_tc(b0i[0], tcp.get('fps') or 24), b0i[1], b0i[2],
                frames_to_tc(tcp['b0'], tcp.get('fps') or 24), tcp2['mode']))
            if tcp2['mode'] == 'first':
                tcp2.update(b0_src='reliable_image' if reliable_base else 'image',
                            b0_meta=tcp['b0'], b0_votes=b0i[1:])
                tcp = tcp2
                tc_pins_abs = dict((t, f) for t, f in tcp['pins_abs'].items() if t not in pins_abs)
                tc_weak_abs = tcp['hints_abs']
                tc_hint_abs = {}
                hv = np.array(sorted(tc_pins_abs.values()))
                lo3 = max(pf, min(lo, int(np.percentile(hv, 3)) - 32))
                hi3 = min(pl, max(hi, int(np.percentile(hv, 97)) + 32))
                res_tc = run(lo3, hi3)
                if (res_tc.get('tc') or {}).get('mode') == 'first':
                    res, lo, hi = res_tc, lo3, hi3
                else:  # if it fell back by veto / offset, keep the image result (only record the state)
                    res['tc_plan'] = res_tc.get('tc_plan')
                    res['tc'] = res_tc.get('tc')
    if tcp is not None and tcp['mode'] == 'first' and tc_track_retry_allowed(tcf, res, opts, pins_abs, excl):
        lo4, hi4 = max(pf, lo - 64), min(pl, hi + 64)
        log(_t('[%s] 가변 옵티컬 재탐색: TC 상대 경로 가설을 이미지로 재검증', '[%s] Variable optical retry: validate the relative TC path hypothesis against images') % plate.name())
        res_track = run(lo4, hi4, track_seed=True)
        if tc_track_retry_accept(res, res_track):
            res, lo, hi = res_track, lo4, hi4
            res['tc_track_retry'] = True
            log(_t('[%s] 가변 옵티컬 재탐색: TC·이미지 검증 통과', '[%s] Variable optical retry: TC/image validation passed') % plate.name())
        else:
            log(_t('[%s] 가변 옵티컬 재탐색: 기존 결과 유지', '[%s] Variable optical retry: keep existing result') % plate.name())

    # TC was dropped as 'offset / mismatch' but the image result is itself weak (match warning / ambiguous / low top-bottom agreement)
    # follow TC - because the basis of the disagreement decision is that very weak image. Confident TC is a value read with zero misreads first
    tci = res.get('tc') or {}
    if tcp is not None and tcp['mode'] == 'first' and tcp.get('b0_src') != 'reliable_image' \
            and tc_pins_abs and tci.get('mode') in ('offset', 'mismatch') \
            and image_weak(res):
        prev = dict(tci)
        tc_force[0] = True
        res_f = run(lo, hi)
        tc_force[0] = False
        if (res_f.get('tc') or {}).get('forced'):
            res_f['tc'] = dict(res_f['tc'], forced_from=prev.get('mode'), forced_disagree=prev.get('disagree_frac'),
                               forced_offset=prev.get('offset'),
                               forced_img=dict(quality=res.get('quality'), amb=(res.get('confidence') or {}).get('amb'),
                                               half=(res.get('confidence') or {}).get('half')))
            log(_t('[%s] 이미지 신뢰도 낮음 -> TC-그림 %s 판정 대신 TC 를 따름', '[%s] Low image confidence -> follow TC instead of the TC/image %s verdict') % (plate.name(), prev.get('mode')))
            res = res_f
    return _a3_retry_result(plate, E_lum, opts, ctx, excl, pin_frames, tcf, ef,
                            res, lo, timing, region=region)


def tc_track_seed_path(tcf, image_path, max_speed=16):
    """Dense, direction-consistent confident TC differences, aligned to an image hypothesis."""
    path = np.asarray(image_path, int)
    if tcf is None or len(tcf) != len(path):
        return None
    times = np.asarray([i for i, value in enumerate(tcf) if value is not None], int)
    if len(times) < max(8, .8 * len(path)):
        return None
    values = np.asarray([tcf[t] for t in times], np.float64)
    if not np.isfinite(values).all():
        return None
    speed = np.diff(values) / np.diff(times)
    moving = speed[np.abs(speed) > 1e-9]
    if not len(moving) or np.max(np.abs(speed)) > max_speed:
        return None
    direction = np.sign(np.median(moving))
    if np.any(moving * direction < 0):
        return None
    offset = int(np.rint(np.median(values - path[times])))
    seed = path.copy()
    seed[times] = np.rint(values - offset).astype(int)
    return seed


def tc_track_retry_allowed(tcf, res, opts, user_pins, exclude):
    """Only revisit an already animated solve whose dense TC failed image validation."""
    if not (opts.get('tc') and opts.get('optical') and opts.get('track')) or opts.get('split'):
        return False
    if user_pins or np.asarray(exclude, bool).any():
        return False
    if not (res.get('track') or {}).get('animated') or (res.get('split') or {}).get('split'):
        return False
    # A bad animated warp can itself create false blend/slow detections.
    # A retry must not increase the existing blend/slow evidence.
    if res.get('cuts'):
        return False
    if (res.get('tc') or {}).get('mode') not in ('offset', 'mismatch', 'increment_mismatch'):
        return False
    return tcf is not None and sum(v is not None for v in tcf) >= max(8, .8 * len(tcf))


def tc_track_retry_accept(base, candidate, min_density=.8):
    """Accept only independently validated dense TC and a better, continuous image solution."""
    if candidate is None:
        return False
    info = candidate.get('tc') or {}
    old, new = np.asarray(base['path']), np.asarray(candidate['path'])
    if len(new) != len(old) or not len(new) or not np.isfinite(new).all():
        return False
    if info.get('mode') != 'first' or info.get('forced') or info.get('used', 0) < min_density * len(new):
        return False
    verified = sum(1 for t, q in (candidate.get('tc_track_verified') or {}).items()
                   if 0 <= t < len(new) and np.isfinite(q) and new[t] == q)
    if verified < min_density * len(new):
        return False
    if len(candidate.get('slow') or []) > len(base.get('slow') or []):
        return False
    if np.count_nonzero(candidate.get('blended', False)) > np.count_nonzero(base.get('blended', False)):
        return False
    def subframe_coverage(result):
        covered = np.zeros(len(new), bool)
        for a, b in result.get('sub_spans') or []:
            covered[max(0, int(a)):min(len(new), int(b) + 1)] = True
        return int(covered.sum())
    if subframe_coverage(candidate) > subframe_coverage(base):
        return False
    if any(len(candidate.get(k) or []) > len(base.get(k) or []) for k in ('cuts', 'reversals')):
        return False
    old_dir, new_dir = np.sign(np.median(np.diff(old))), np.sign(np.median(np.diff(new)))
    if old_dir and new_dir and old_dir != new_dir:
        return False
    q0, q1 = float(base.get('quality', 1)), float(candidate.get('quality', 1))
    return bool(np.isfinite([q0, q1]).all() and q1 < .9 * q0)


def identity_challenger_allowed(res, opts, user_pins, user_hints, exclude, tc_authority=False):
    """Challenge small unconfirmed spatial corrections on continuous forward footage."""
    if not opts.get('optical') or opts.get('split') or tc_authority or user_pins or user_hints:
        return False
    if exclude is not None and np.asarray(exclude).any():
        return False
    if (res.get('tc') or {}).get('mode') not in (None, 'off'):
        return False
    if (res.get('track') is not None or (res.get('split') or {}).get('split') or
            any(res.get(k) for k in ('cuts', 'reversals', 'slow', 'sub_spans', 'near_hold')) or
            np.any(res.get('blended', False))):
        return False
    path = np.asarray(res.get('path'))
    if path.ndim != 1 or len(path) < 24 or not np.isfinite(path).all():
        return False
    steps = np.diff(path)
    if np.any(steps < 0) or not np.any(steps > 0):
        return False
    opt = res.get('optical') or {}
    if opt.get('flop') or opt.get('region', 'full') != 'full' or opt.get('rmask') is not None:
        return False
    values = [opt.get(k, np.nan) for k in ('s', 'tx', 'ty')]
    return bool(np.isfinite(values).all() and .002 < abs(values[0] - 1.) <= .05 and
                max(abs(values[1]), abs(values[2])) <= .02)


def identity_challenger_accept(base, candidate, heldout):
    """Accept only a clean forward solution with gains in unused image regions."""
    if (candidate is None or candidate.get('track') is not None or
            (candidate.get('split') or {}).get('split') or
            any(candidate.get(k) for k in ('cuts', 'reversals', 'slow', 'sub_spans', 'near_hold')) or
            np.any(candidate.get('blended', False))):
        return False
    if optical_retry_has_blend_evidence(candidate):
        return False
    path = np.asarray(candidate.get('path'))
    if path.shape != np.asarray(base['path']).shape or not np.isfinite(path).all():
        return False
    steps = np.diff(path)
    if np.any(steps < 0) or not np.any(steps > 0):
        return False
    opt = candidate.get('optical') or {}
    if not _static_retry_optical_valid(opt) or opt.get('note') != 'identity':
        return False
    before = np.asarray((heldout or {}).get('before') or [], float)
    after = np.asarray((heldout or {}).get('after') or [], float)
    if before.shape != (3,) or after.shape != (3,) or not np.isfinite([before, after]).all():
        return False
    gain = after - before
    q0, q1 = float(base.get('quality', np.nan)), float(candidate.get('quality', np.nan))
    return bool(np.isfinite([q0, q1]).all() and q1 < .85 * q0 and
                gain.min() >= -.001 and np.count_nonzero(gain > .002) >= 2 and gain.mean() >= .004)


def static_refine_retry_allowed(res, opts, user_pins, user_hints, exclude, tc_authority=False):
    """A static precision retry cannot override established timing authority."""
    if not opts.get('optical') or not opts.get('track') or opts.get('split'):
        return False
    if tc_authority or user_pins or user_hints or (exclude is not None and np.asarray(exclude).any()):
        return False
    if (res.get('tc') or {}).get('mode') not in (None, 'off'):
        return False
    if (res.get('track') is not None or (res.get('split') or {}).get('split') or
            res.get('cuts') or res.get('reversals') or res.get('slow') or res.get('near_hold')):
        return False
    path = np.asarray(res.get('path'))
    if path.ndim != 1 or len(path) < 24 or not np.isfinite(path).all():
        return False
    steps = np.diff(path)
    if np.any(steps < 0) or not np.any(steps > 0):
        return False
    # Isolated subframe votes may result from a small static misalignment.
    # A detected interpolation segment or enough votes remains protected.
    if np.count_nonzero(res.get('blended', False)) >= SUB_MIN:
        return False
    opt = res.get('optical') or {}
    if opt.get('region', 'full') != 'full' or opt.get('rmask') is not None:
        return False
    sk = res.get('static_candidate')
    if sk is None or np.asarray(sk).shape != (3,) or not np.isfinite(sk).all():
        return False
    # Do not spend a full re-solve if proposal/fitting frames have consumed
    # an entire validation region (common on short clips).
    if len(optical_retry_validation_times(res, res,
            res.get('static_candidate_used_times') or [])) != 3:
        return False
    score = opt.get('score_multi')
    return bool(score is not None and np.isfinite(score) and score < .98)


def reused_optical_retry_allowed(res, init_opt, opts, user_pins, exclude, min_multi=0.98,
                                 tc_authority=False):
    """Recheck a coarse static transform when multi-time image agreement is weak."""
    if init_opt is None or not opts.get('optical') or opts.get('split'):
        return False
    if tc_authority or (res.get('tc') or {}).get('mode') not in (None, 'off'):
        return False
    if user_pins or (exclude is not None and np.asarray(exclude).any()):
        return False
    if (res.get('track') is not None or (res.get('split') or {}).get('split') or
            res.get('cuts') or res.get('slow') or res.get('sub_spans') or
            res.get('near_hold') or np.any(res.get('blended', False))):
        return False
    score = (res.get('optical') or {}).get('score_multi')
    return bool(score is not None and np.isfinite(score) and score < min_multi)


def optical_retry_validation_times(base, candidate, excluded_times=()):
    """Reserve one unused valid picture in each third; fail closed if depleted."""
    valid = np.asarray(base.get('E_valid', np.ones(len(base['path']), bool)), bool) & np.asarray(
        candidate.get('E_valid', np.ones(len(candidate['path']), bool)), bool)
    fit = set(excluded_times)
    for result in (base, candidate):
        fit.update((result.get('optical') or {}).get('anchors') or [])
        vt = np.flatnonzero(result.get('E_valid', np.ones(len(result['path']), bool)))
        if len(vt):
            fit.update(vt[np.linspace(0, len(vt) - 1, min(8, len(vt))).astype(int)].tolist())
    times = []
    for part in np.array_split(np.arange(len(valid)), 3):
        available = [int(t) for t in part if valid[t] and t not in fit]
        if available:
            times.append(available[len(available) // 2])
    return times


def reused_optical_retry_holdout(E_lum, P_lum, base, candidate, excluded_times=()):
    """Check three times omitted from initial anchors and both spatial refinements."""
    times = optical_retry_validation_times(base, candidate, excluded_times)
    return dict(static_line_retry_holdout(E_lum, P_lum, base, candidate, times), times=times)


def optical_retry_has_blend_evidence(candidate):
    """Do not erase genuine isolated interpolation just because it is short."""
    path = np.asarray(candidate['path'])
    diag = candidate.get('sub_diag') or {}
    arrays = [np.asarray(diag.get(k), float) for k in ('est', 'gain', 'vtx')]
    if any(a.shape != path.shape or not np.isfinite(a).all() for a in arrays):
        return True
    votes = subframe_blend_votes(path, *arrays)
    return bool(np.any(votes & np.asarray(candidate['E_valid'], bool)))


def reused_optical_retry_accept(base, candidate, heldout=None):
    """A fresh static fit must improve image evidence without introducing curve risk."""
    if (candidate.get('track') is not None or candidate.get('slow') or candidate.get('sub_spans') or
            candidate.get('near_hold') or np.any(candidate.get('blended', False))):
        return False
    if (candidate.get('split') or {}).get('split'):
        return False
    if not _static_retry_optical_valid(candidate.get('optical') or {}):
        return False
    score = candidate['optical'].get('score_multi')
    before = (base.get('optical') or {}).get('score_multi')
    if score is None or before is None or not np.isfinite([score, before]).all() or score < .98 or score <= before:
        return False
    if any(len(candidate.get(k) or []) > len(base.get(k) or []) for k in ('cuts', 'reversals')):
        return False
    before = np.asarray((heldout or {}).get('before') or [], np.float64)
    after = np.asarray((heldout or {}).get('after') or [], np.float64)
    if len(before) != 3 or len(after) != 3 or not np.isfinite([before, after]).all():
        return False
    gains = after - before
    if gains.min() < -0.001 or np.count_nonzero(gains > 0.002) < 2 or gains.mean() < 0.004:
        return False
    return retry_better(base, candidate)


def retry_better(res, res_o):
    """ decision to adopt an optical re-search / flop alternative (pure function). The median path cost (quality) is at most OPT_RETRY_STRONG times,
    or at most OPT_RETRY_GAIN times while top/bottom agreement does not get worse, or the cost is equal (within +2 %, a plate with little temporal information)
    and the top/bottom agreement rises by OPT_RETRY_HALF or more and ambiguous frames decrease"""
    c0, c1 = res.get('confidence') or {}, res_o.get('confidence') or {}
    h0, h1 = c0.get('half'), c1.get('half')
    a0, a1 = c0.get('amb') or 0.0, c1.get('amb') or 0.0
    q0, q1 = float(res.get('quality', 1.0)), float(res_o.get('quality', 1.0))
    if q1 < q0 * OPT_RETRY_STRONG:
        return True
    if q1 < q0 * OPT_RETRY_GAIN and (h0 is None or h1 is None or h1 >= h0):
        return True
    return bool(q1 <= q0 * 1.02 and h0 is not None and h1 is not None and h1 >= h0 + OPT_RETRY_HALF and a1 <= a0)


def retry_text(res, res_o, ok):
    """ one re-search log line"""
    c0, c1 = res.get('confidence') or {}, res_o.get('confidence') or {}
    f = lambda v: '-' if v is None else '%.0f%%' % (100 * v)
    return _t('비용 %.3f -> %.3f, 상하 합의 %s -> %s, 모호 %s -> %s, s=%.3f flop=%s -> %s', 'cost %.3f -> %.3f, upper/lower agreement %s -> %s, ambiguity %s -> %s, s=%.3f flop=%s -> %s') % (
        res.get('quality', 0), res_o.get('quality', 0), f(c0.get('half')), f(c1.get('half')), f(c0.get('amb')),
        f(c1.get('amb')), float(res_o['optical']['s']), res_o['optical']['flop'], _t('채택', 'accepted') if ok else _t('기존 유지', 'keep existing'))


def image_weak(res):
    """ whether the image matching result is itself weak: match warning (median cost > WARN_QUALITY) / ambiguous frames > CONF_AMB_MAX /
    top/bottom agreement < CONF_HALF_MIN"""
    c = res.get('confidence') or {}
    return bool(res.get('quality', 0) > WARN_QUALITY or (c.get('amb') or 0) > CONF_AMB_MAX or
                (c.get('half') is not None and c['half'] < CONF_HALF_MIN))


def _first_frame_token(setting):
    """Canonical output-numbering policy; legacy auto explicitly means first match."""
    if setting is None or setting == '':
        return 'plate'
    if isinstance(setting, bool):
        raise ValueError('First Frame must be an integer or a numbering policy')
    token = str(setting).strip().lower()
    if token == 'auto':
        return 'matched'
    if token in ('plate', 'matched'):
        return token
    if not re.match(r'^[+-]?\d+$', token):
        raise ValueError('Invalid First Frame: %s' % setting)
    return str(int(token))


def first_frame_value(setting, plate_first, matched_first):
    token = _first_frame_token(setting)
    return int(plate_first if token == 'plate' else matched_first if token == 'matched' else token)


def first_frame_preference(saved, cfg):
    for value in (saved, (cfg.get('defaults') or {}).get('first_frame'), 'plate'):
        if value is not None and value != '':
            try:
                return _first_frame_token(value)
            except ValueError:
                pass
    return 'plate'


def batch_job_options(opts, row):
    result = dict(opts, split=False)
    result.pop('plate_regions', None)
    result.pop('plate_tc_rois', None)
    setting = row.get('out')
    result['out'] = _first_frame_token(opts.get('out') if setting is None or setting == '' else setting)
    return result


def apply_batch_first_frame(rows, setting):
    token = _first_frame_token(setting)
    for row in rows:
        row['out'] = token


def batch_manual_edit_candidates(plate, edits):
    """Selected EDIT Reads ordered for an explicit batch row.

    Every selected movie remains available in the row selector.  The nearest
    node-graph row is only the initial choice when no path template can pair by
    shot name; it is never hidden from manual correction.
    """
    try:
        py = int(plate.ypos())
    except Exception:
        py = 0

    def key(node):
        try:
            y, x = int(node.ypos()), int(node.xpos())
        except Exception:
            y, x = 0, 0
        try:
            name = str(node.fullName())
        except Exception:
            name = str(getattr(node, 'name', lambda: '')())
        return abs(y - py), y, x, name

    return sorted(list(edits or ()), key=key)


def _batch_edit_candidate(node):
    return dict(path=str(node['file'].value()), node=str(node.fullName()), node_ref=node)


def _batch_selected_pair_key(node):
    """Pair explicit graph names such as PLATE_14 and EDIT_14 conservatively."""
    try:
        stem = os.path.splitext(str(node.name()))[0].lower()
    except Exception:
        return ''
    parts = [part for part in re.split(r'[\\/_.\-\s]+', stem) if part]
    role = re.compile(r'^(?:ed|edit|edits|editorial|pl|plate|plates|mp\d*)$', re.I)
    if not any(role.match(part) for part in parts):
        return ''
    rest = [part for part in parts if not role.match(part)]
    return '_'.join(rest)


def batch_edit_choices(row):
    """Return stable, uniquely labelled edit choices with their selected Read binding."""
    choices = []
    seen = set()
    bound_paths = set()
    for candidate in row.get('edit_candidates') or ():
        path = str(candidate.get('path') or '')
        node = str(candidate.get('node') or '')
        has_node_ref = 'node_ref' in candidate
        node_ref = candidate.get('node_ref')
        key = (path, node)
        if not path or key in seen:
            continue
        seen.add(key)
        bound_paths.add(path)
        choices.append(dict(path=path, node=node, node_ref=node_ref,
                            has_node_ref=has_node_ref, label=''))
    for path in row.get('movs') or ():
        path = str(path or '')
        if not path or path in bound_paths or (path, '') in seen:
            continue
        seen.add((path, ''))
        choices.append(dict(path=path, node='', node_ref=None,
                            has_node_ref=False, label=''))

    basename_counts = {}
    for choice in choices:
        base = os.path.basename(choice['path']) or choice['path']
        basename_counts[base] = basename_counts.get(base, 0) + 1
    used_labels = set()
    for choice in choices:
        base = os.path.basename(choice['path']) or choice['path']
        if choice['node']:
            label = '%s — %s' % (base, choice['node'])
        elif basename_counts.get(base, 0) > 1:
            label = '%s — %s' % (base, choice['path'])
        else:
            label = base
        root, suffix = label, 2
        while label in used_labels:
            label = '%s (%d)' % (root, suffix)
            suffix += 1
        choice['label'] = label
        used_labels.add(label)
    return choices


def batch_select_edit_choice(row, choices, index):
    """Select a batch edit and keep its path bound to the exact selected Read node."""
    choice = choices[int(index)]
    row['mov'] = choice['path']
    if choice.get('node'):
        row['edit_node'] = choice['node']
        if choice.get('has_node_ref'):
            row['edit_ref'] = choice.get('node_ref')
        else:
            row.pop('edit_ref', None)
    else:
        row.pop('edit_node', None)
        row.pop('edit_ref', None)
    row['status'] = _t('대기 (선택 편집본)', 'Ready (selected edit)')
    return row


def batch_apply_selected_edits(row, plate, edits, path_pairing):
    """Apply selected EDIT Reads to one batch row without hiding alternatives."""
    edits = list(edits or ())
    ordered = batch_manual_edit_candidates(plate, edits)
    row['edit_candidates'] = [_batch_edit_candidate(edit) for edit in ordered]
    selected = None
    plate_key = _batch_selected_pair_key(plate)
    named = [edit for edit in edits if plate_key and _batch_selected_pair_key(edit) == plate_key]
    if len(named) > 1:
        row['movs'] = list(dict.fromkeys([edit['file'].value() for edit in ordered] + row.get('movs', [])))
        row['mov'] = None
        row.pop('edit_node', None)
        row.pop('edit_ref', None)
        row['status'] = _t('편집본 선택 필요 (같은 이름의 후보 여러 개)',
                           'Choose an edit (multiple matching names)')
        return row
    if named:
        selected = named[0]
    if selected is None:
        shot_matches = [edit for edit in edits if row.get('shot') and
                        shot_in_filename(os.path.basename(edit['file'].value()), row['shot'])]
        if len(shot_matches) > 1:
            row['movs'] = list(dict.fromkeys([edit['file'].value() for edit in ordered] + row.get('movs', [])))
            row['mov'] = None
            row.pop('edit_node', None)
            row.pop('edit_ref', None)
            row['status'] = _t('편집본 선택 필요 (같은 샷의 후보 여러 개)',
                               'Choose an edit (multiple shot matches)')
            return row
        if shot_matches:
            selected = shot_matches[0]
    if selected is not None:
        path = selected['file'].value()
        row['mov'], row['status'] = path, _t('대기 (선택 편집본)', 'Ready (selected edit)')
        row['edit_node'] = selected.fullName()
        row['edit_ref'] = selected
        if path not in row['movs']:
            row['movs'].insert(0, path)
    if not path_pairing and edits:
        candidates = ordered
        selected_paths = [edit['file'].value() for edit in candidates]
        if selected is not None:
            row['movs'] = [row['mov']] + [path for path in selected_paths if path != row['mov']]
        else:
            row['movs'] = selected_paths
            row['mov'] = row['movs'][0]
            row['edit_node'] = candidates[0].fullName()
            row['edit_ref'] = candidates[0]
            row['status'] = _t('대기 (선택 편집본 · 위치 기준)',
                               'Ready (selected edit · node-row pairing)')
    return row


_H264_CODEC_NAMES = frozenset(('h264', 'h.264', 'avc', 'avc1', 'x264'))
_PRORES_CODEC_NAMES = frozenset(('prores', 'apco', 'apcs', 'apcn', 'apch', 'ap4h', 'ap4x'))
_UNKNOWN_TRANSFER_VALUES = frozenset(('', 'none', 'unknown', 'unspecified'))


def edit_needs_rec709_analysis(edit, frame=None):
    """True only for an untagged H.264 or ProRes movie whose colorspace was left at the host default.

    Nuke decodes these as default (Gamma2.2), while create_edit_read uses rec709.
    An explicit colorspace, raw mode, a tagged source or any other codec returns False.
    """
    try:
        if not str(edit['colorspace'].value()).startswith('default ('):
            return False
        if 'raw' in edit.knobs() and edit['raw'].value():
            return False
        frame = edit.firstFrame() if frame is None else frame
        codec = {str(edit.metadata(key, frame) or '').strip().lower()
                 for key in ('quicktime/codec_name', 'quicktime/codec_id')}
        if not codec & (_H264_CODEC_NAMES | _PRORES_CODEC_NAMES):
            return False
        transfer = str(edit.metadata('quicktime/nclc_transfer_function', frame) or '').strip().lower()
        return transfer in _UNKNOWN_TRANSFER_VALUES
    except Exception:
        return False


def acquire_analysis_read(edit, log=print):
    """Return (node to analyze, temporary Read or None). The user's Read is never changed.

    The temporary Read stays out of owned-node lists. Its create and delete are both
    recorded in the job's undo group: output nodes are created while it exists, and
    hiding it from undo history corrupts undo of those nodes and can quit Nuke.
    Any setup problem falls back to the user's Read so analysis behaves as it did before.
    """
    if not edit_needs_rec709_analysis(edit):
        return edit, None
    temp = None
    try:
        temp = _create_input_read(edit, [])
        _configure_edit_colorspace(temp)
        temp.forceValidate()
        source_format, temp_format = edit.format(), temp.format()
        same = (temp.firstFrame() == edit.firstFrame() and temp.lastFrame() == edit.lastFrame() and
                temp_format.width() == source_format.width() and
                temp_format.height() == source_format.height() and
                temp_format.pixelAspect() == source_format.pixelAspect())
        if not same or temp['colorspace'].value() == edit['colorspace'].value():
            release_analysis_read(temp, log)
            return edit, None
    except Exception as error:
        release_analysis_read(temp, log)
        log(_t('분석용 색 읽기 생략, 선택한 Read로 분석합니다: %s',
               'Analysis color read skipped; analyzing through the selected Read: %s') % error)
        return edit, None
    log(analysis_read_note(temp))
    return temp, temp


def release_analysis_read(temp, log=print):
    """Delete the temporary analysis Read inside the same undo history as its creation; never raises."""
    if temp is None:
        return
    try:
        nuke.delete(temp)
    except Exception as error:
        log(_t('분석용 임시 Read 정리 확인 필요: %s', 'Temporary analysis Read cleanup needs review: %s') % error)


def analysis_read_note(temp):
    colorspace = temp['colorspace'].value()
    return _t('색 읽기: 편집본에 색 정보가 없어 분석할 때만 %s로 읽었습니다. 선택한 Read와 결과 노드, QC 화면은 그대로입니다.',
              'Color read: the edit has no color tag, so analysis read it as %s. Your Read, the result nodes and the QC view are unchanged.') % colorspace


def process_job(edit, plates, opts, ctx, exclude_frames=(), pin_frames=None, edit_is_new=False):
    """Own output nodes explicitly so cancellation cannot leave a partial job."""
    owned_nodes = [edit] if edit_is_new else []
    analysis_edit, temp_read = acquire_analysis_read(edit, ctx.log)
    try:
        result = _process_job_impl(edit, plates, opts, ctx, exclude_frames, pin_frames,
                                   edit_is_new, owned_nodes, analysis_edit=analysis_edit)
        result['_owned_nodes'] = list(owned_nodes)
        return result
    except Cancelled:
        # Never sweep all newly visible nodes: callbacks may create unrelated work.
        for node in reversed(owned_nodes):
            try:
                nuke.delete(node)
            except Exception as error:
                ctx.log(_t('취소한 작업 노드 정리 실패: %s', 'Failed to clean up cancelled job nodes: %s') % error)
        raise
    except Exception as error:
        # General failures keep useful partial output, but expose only nodes this job explicitly created.
        # Callers may group them red without sweeping callback/user nodes from the whole graph.
        try:
            error.nmmr_owned_nodes = tuple(owned_nodes)
        except Exception:
            pass
        raise
    finally:
        release_analysis_read(temp_read, ctx.log)


def _process_job_impl(edit, plates, opts, ctx, exclude_frames, pin_frames, edit_is_new, owned_nodes,
                      analysis_edit=None):
    """
    process 1 EDIT + n PLATEs -> create nodes. Returns dict(results, warn, notes)
    exclude_frames: set of EDIT frame numbers to exclude, pin_frames {EDIT frame: PLATE frame}
    """
    import time
    log = ctx.log
    t_start = time.time()
    ef, el = edit.firstFrame(), edit.lastFrame()
    out_txt = _first_frame_token(opts.get('out'))
    if analysis_edit is None:
        analysis_edit = edit

    input_preflights = []
    edit_preflight = read_input_preflight(edit, ef, el)
    input_preflights.append(dict(role='EDIT', node=edit.name(), result=edit_preflight))
    for plate in plates:
        check = read_input_preflight(plate, plate.firstFrame(), plate.lastFrame())
        input_preflights.append(dict(role='PLATE', node=plate.name(), result=check))
    fatal_inputs = [item for item in input_preflights if item['result'].get('fatal')]
    if fatal_inputs:
        raise RuntimeError('\n'.join(read_input_preflight_text(
            '%s %s' % (item['role'], item['node']), item['result']) for item in fatal_inputs))
    input_warnings = [read_input_preflight_text('%s %s' % (item['role'], item['node']), item['result'])
                      for item in input_preflights if item['result'].get('reason') == 'frames_missing']
    input_warnings = [message for message in input_warnings if message]
    for message in input_warnings:
        log('[!] ' + message)

    ctx.progress(0.01, _t('EDIT 썸네일', 'EDIT thumbnails'))
    _, sec_e = ensure_thumbs(analysis_edit, ef, el, 1, W_EDIT, True, log)
    E_lum, e_ok = load_thumbs(analysis_edit, list(range(ef, el + 1)), W_EDIT, log)
    if ctx.cancelled():
        raise Cancelled()
    if identical_thumbs(E_lum, e_ok):  # an immediate error instead of a silently wrong result
        raise RuntimeError(_t('EDIT 썸네일 %d장이 전부 같은 그림입니다 — Read 의 frame range(first/last)가 한 프레임에 고정됐는지 확인해 주세요 (스크립트로 만든 무비 Read). 정말 한 장짜리 정지 화면이면 고정점 하나로 지정해 주세요.', 'All %d EDIT thumbnails are identical — check whether the Read frame range (first/last) is fixed to one frame (movie Read created by a script). For a genuine single-frame hold, specify one anchor.') % int(e_ok.sum()))
    edit_duplicates = isolated_edit_duplicates(E_lum, e_ok)
    excl = np.array([f in set(exclude_frames or ()) for f in range(ef, el + 1)], bool)
    # fit-inside (pillarbox): if the active picture width is narrow, re-render only that area at the edit thumbnail resolution and match it
    # then convert the optical back to full edit coordinates (also solves cases outside SCALE_MIN such as a vertical plate s~0.32)
    E_solve, box, e_ok_solve = E_lum, None, e_ok.copy()
    if opts['optical'] and not opts['split']:
        box = active_bbox(E_lum)
        if box is not None:
            fw, fh = edit.format().width(), edit.format().height()
            bw, bh = (box[2] - box[0]) * fw, (box[3] - box[1]) * fh
            Hc = max(8, int(round(W_EDIT * bh / float(bw))))
            nbox = (int(round(box[0] * fw)), int(round((1 - box[3]) * fh)),
                    int(round(box[2] * fw)), int(round((1 - box[1]) * fh)))
            log(_t('활성 영상 영역(필러박스 의심) x %.0f-%.0f%% -> 그 안만 %dx%d 로 매칭', 'Active image area (possible pillarbox) x %.0f-%.0f%% -> match only this area at %dx%d') % (
                100 * box[0], 100 * box[2], W_EDIT, Hc))
            _ensure(analysis_edit, _thumb_dir(analysis_edit, 'box_%d_%d_%d_%d' % nbox), ef, el, 1, nbox, True,
                    W_EDIT, Hc, 1.0, True, log, 'box')
            E_solve, ok_b = _load_dir(_thumb_dir(analysis_edit, 'box_%d_%d_%d_%d' % nbox), list(range(ef, el + 1)),
                                      Hc, W_EDIT, log)
            e_ok_solve &= ok_b

    tc_cache = {}  # (project, fps, per-plate TC ROI) -> OCR result

    results, warn, notes, reframe_warn = [], list(input_warnings), [], []
    pending_notes = []  # (plate, res, lo, out_first, total, report, timewarp)
    if edit_duplicates:
        warn.append(_t('EDIT (중복 프레임 의심 %s)', 'EDIT (possible duplicate frames %s)') % _ranges(ef + np.array(edit_duplicates)))
    warn_q, warn_conf, cuts = [], [], []  # match-quality warnings / suspected split cuts (warn gets both)
    near_hold = []  # [(plate name, still segment, out_first)]
    qc_on = qc_required(opts)  # review / second-pass QC also need the final QC input
    edit_qc, edit_qc_first = None, None
    p0 = plates[0]
    if edit_is_new:  # a newly loaded edit goes in the left column of the PLATE
        edit.setXYpos(p0.xpos() + LAY['edit'][0], p0.ypos() + LAY['edit'][1])
    span = 0.94 / len(plates)
    for i, plate in enumerate(plates):
        log('==== PLATE %s (%d/%d)' % (plate.name(), i + 1, len(plates)))
        sub = ctx.sub(0.05 + i * span, 0.05 + (i + 1) * span)
        plate_id = node_stable_name(plate)
        roi_rect = (opts.get('plate_regions') or {}).get(plate_id)
        plate_edit, region, plate_box = plate_analysis_inputs(E_lum, E_solve, box, roi_rect)
        plate_ok = e_ok if roi_rect is not None else e_ok_solve
        tc_roi = (opts.get('plate_tc_rois') or {}).get(plate_id)
        proj = None
        if opts.get('tc') or opts.get('secondary_qc'):
            proj = node_context(plate)[0] or node_context(edit)[0] or script_context()[0]
        secondary_tc_roi, secondary_tc_roi_error = None, ''
        if opts.get('secondary_qc'):
            try:
                secondary_tc_roi = secondary_qc_tc_roi(proj, tc_roi)
            except Exception as error:
                secondary_tc_roi_error = str(error)
                log(_t('[%s] 2차 QC TC 영역 제외 보류: %s', '[%s] Secondary QC: TC-region exclusion unavailable: %s') % (plate.name(), error))
        tcf, tc_raw, tc_summ = None, None, None
        if opts.get('tc'):
            cfg = load_tc_cfg(proj)
            use_cfg = tc_config_for_plate(cfg, tc_roi)
            if tc_config_has_roi(use_cfg):
                fps = node_fps(plate, plate.firstFrame())
                tc_key = (proj, round(float(fps), 6), tuple(tc_roi) if tc_roi is not None else None)
                if tc_key not in tc_cache:
                    ctx.progress(0.03, _t('[%s] 렉TC 판독', '[%s] Reading burn-in TC') % plate.name())
                    try:
                        tcf_, _, _, rows_, summ_ = read_edit_tc(analysis_edit, ef, el, use_cfg, fps, log)
                        raw_ = dict(values=summ_['raw']['values'],
                                    conf=[0.0 if 'glitch' in fl else c for v, c, fl in rows_])
                        tc_cache[tc_key] = (tcf_, raw_, summ_)
                    except Exception as e:  # so a TC failure does not block the whole job
                        log(_t('[%s] 렉TC 판독 실패 — TC 없이 진행: %s', '[%s] Burn-in TC read failed — continue without TC: %s') % (plate.name(), e))
                        tc_cache[tc_key] = (None, None, None)
                tcf, tc_raw, tc_summ = tc_cache[tc_key]
            else:
                log(_t('[%s] 렉TC 보정 없음 (%s) — TC 없이 진행', '[%s] No burn-in TC calibration (%s) — continue without TC') % (plate.name(), proj))
        sub.a3_analysis_box = plate_box
        sub.a3_edit_aspect = edit.format().height() / float(edit.format().width())
        res, lo, timing = _process_plate(plate, plate_edit, opts, sub, excl, pin_frames,
                                         tcf, ef, tc_raw, region=region)
        if region is not None:
            res['manual_region_rect'] = tuple(roi_rect)
            res['manual_region_plate'] = plate_id
        if tcf is not None:
            res['tc_preflight'] = tc_preflight_from_result(
                tcf, plate.firstFrame(), plate.lastFrame(), res, lo)
            res['tc_preflight']['fps'] = node_fps(plate, plate.firstFrame())
            res['tc_preflight']['tc_roi_source'] = 'plate' if tc_roi is not None else 'global'
        if plate_box is not None:
            res = uncrop_result(res, plate_box, edit.format().height() / float(edit.format().width()),
                                E_lum.shape[1:])
        res['E_valid'] &= plate_ok
        if opts.get('qc_refine') and opts.get('optical') and plate_box is None:
            t_qc = time.time()
            try:
                res = qc_refine_rendered_anchors(analysis_edit, plate, E_lum, res, ef, lo, log, ctx.cancelled)
            except Cancelled:
                raise
            except Exception as e:  # so a failure of the auxiliary QC refinement does not block the main result
                log(_t('[%s] QC optical refine 실패(기존 값 유지): %s', '[%s] QC optical refine failed (keep existing values): %s') % (plate.name(), e))
            finally:
                timing['qc_refine'] = time.time() - t_qc
        res['edit_duplicates'] = edit_duplicates
        res['input_warnings'] = [item for item in input_preflights
                                 if item['role'] == 'EDIT' or item['node'] == plate.name()]
        if secondary_tc_roi is not None:
            res['secondary_qc_tc_roi'] = secondary_tc_roi
        if secondary_tc_roi_error:
            res['secondary_qc_tc_roi_unavailable'] = secondary_tc_roi_error
        if res.get('quality', 0) > WARN_QUALITY:
            warn.append(_t('%s (일치도 %s)', '%s (matching similarity %s)') % (plate.name(), score_text(res['quality'])))
            warn_q.append(warn[-1])
        elif res.get('confidence_warn'):  # do not settle silently on a 'fair' match
            warn.append(_t('%s (일치도 %s, 신뢰도 낮음: %s)', '%s (matching similarity %s, low confidence: %s)') % (plate.name(), score_text(res['quality']),
                                                       _report_detail_text(', '.join(res['confidence_warn']))))
            warn_q.append(warn[-1])
            warn_conf.append(warn[-1])
        out_first = first_frame_value(out_txt, plate.firstFrame(),
            lo + int(res['path'][int(np.argmax(res['E_valid'] | excl))]))
        tci = res.get('tc') or {}
        if tci.get('mode') in ('offset', 'mismatch', 'increment_mismatch') or tci.get('forced') or tci.get('lowq_released'):
            warn.append('%s (%s)' % (plate.name(), tc_status(res)[0]))  # the case where TC was followed because the image was weak
        if tci.get('mode') == 'first' and tc_summ:  # a jump TC is confident about -> merged into split-cut suspects
            res['cuts'] = merge_tc_cuts(res.get('cuts') or [], tc_summ.get('cuts') or [], tcf, res['path'])
        for c in res.get('cuts') or []:
            cuts.append(dict(plate=plate.name(), edit_frame=ef + c['t'], out_frame=out_first + c['t'],
                             jump=c['jump'], mismatch=c['mismatch'], tc=bool(c.get('tc')), desc=cut_desc(c)))
        if res.get('cuts'):
            warn.append(_t('%s (분절컷 의심 EDIT %s)', '%s (possible cut at EDIT frame(s) %s)') % (plate.name(), ', '.join(
                str(ef + c['t']) for c in res['cuts'])))
        nh = res.get('near_hold') or []  # only 'indistinguishable' warns, weak evidence / confirmed are info ( 'insufficient evidence' warns too)
        amb = [s for s in nh if _span_state(s) == 'ambiguous']
        uns = [s for s in nh if _span_state(s) == 'unsure']
        if amb:
            warn.append(_t('%s (프레임 구분 불가 %s)', '%s (frames indistinguishable %s)') % (plate.name(), _unc_short(max(amb, key=lambda x: x['unc']))))
        if uns:
            warn.append(_t('%s (정지 구간 근거 부족 %d구간)', '%s (insufficient hold evidence in %d spans)') % (plate.name(), len(uns)))
        if nh:
            near_hold.append((plate.name(), nh, out_first))
        beta = reframe_output_policy(opts, res)
        beta['risk_detail'] = reframe_output_risk_detail(res, out_first)
        res['reframe_output_beta'] = beta
        beta_warning = reframe_output_warning(plate.name(), beta)
        if beta_warning:
            warn.append(beta_warning)
            reframe_warn.append(beta_warning)
        if qc_on and (edit_qc is None or edit_qc_first != out_first):
            edit_qc = build_edit_offset(edit, ef, out_first, p0, owned_nodes)
            edit_qc_first = out_first
        created = build_nodes(edit, plate, res, lo, out_first, edit_qc if qc_on else None,
                              qc_anchor=p0, qc_index=i, out_node=opts.get('out_node') or 'timewarp',
                              reframe_output=beta.get('create', False), owned_nodes=owned_nodes,
                              interpolation=opts.get('lookup_interpolation', 'linear'))
        tr = qc_transform_node(created, beta=beta.get('create', False)) if qc_on else None
        t_look = time.time()
        plate_qc, qc_grade_node = configure_qc_look(created, tr, edit_qc if qc_on else None,
            E_lum, res, out_first, opts, box=plate_box, log=log, cancelled=ctx.cancelled, tag=plate.name())
        look_elapsed = time.time() - t_look
        if qc_grade_node is not None:
            owned_nodes.append(qc_grade_node)
        try:  # timecode Text overlay at the end of the output tree
            add_output_timecode(created, output_tree_tail(created, qc_grade_node), edit, plate, ef, lo, res,
                                out_first, owned_nodes, log)
        except Exception as error:
            log(_t('[%s] 출력 TC 노드 생략: %s', '[%s] Output TC node skipped: %s') % (plate.name(), error))
        t_secondary = time.time()
        secondary = run_secondary_qc(plate_qc, edit_qc if qc_on else None, res, out_first, opts,
                                     log=log, cancelled=ctx.cancelled)
        res['secondary_qc'] = secondary
        if opts.get('secondary_qc'):
            store_secondary_qc_metadata(created, secondary, log=log)
        if secondary.get('status') in ('review', 'limited', 'error'):
            warning = '%s (%s)' % (plate.name(), secondary_qc_batch_flag(secondary))
            if warning not in warn:
                warn.append(warning)
        txt = report_text(res, edit, plate, ef, lo, out_first)
        if analysis_edit is not edit:
            res['analysis_colorspace'] = analysis_edit['colorspace'].value()
            txt += '\n' + analysis_read_note(analysis_edit)
        if qc_look_requested(opts):
            look = res['qc_look']
            state = _t('적용', 'applied') if look['status'] == 'applied' else _t('보류', 'held')
            reason = look_reason_text(look['reason'])
            txt += _t('\nQC 룩 매치 (Beta): %s (%s, %.1fs) · 프레임 정확도 판정과 별개', '\nQC look match (Beta): %s (%s, %.1fs) · separate from frame-accuracy assessment') % (
                state, reason, look_elapsed)
            if look['status'] == 'applied':  # the number of frames removed from the note is put in plain wording only on the Report tab
                n_check = len(look.get('holdout_indices') or ())
                n_all = len(look.get('fit_indices') or ()) + n_check
                txt += _t('\n색 맞춤 %d프레임 중 %d프레임으로 확인', '\nColor match checked on %d of %d frames') % (
                    (n_all, n_check) if ui_language() == 'ko' else (n_check, n_all))
        if res.get('output_tc'):
            txt += _t('\n출력 TC 노드: %s', '\nOutput TC node: %s') % output_timecode_label(res['output_tc'], out_first).replace('\n', ' ')
        if opts.get('secondary_qc'):
            txt += _t('\n%s · 추가 렌더 %.1fs', '\n%s · additional render %.1fs') % (secondary_qc_note(secondary), time.time() - t_secondary)
        txt += _t('\n소요: PLATE 탐색 %.0fs / 렌더 %.0fs / 분석 %.0fs', '\nTime: PLATE search %.0fs / render %.0fs / analysis %.0fs') % (
            timing.get('scan', 0), timing.get('plate', 0), timing.get('analysis', 0))
        if 'a3_retry_seconds' in timing:
            txt += _t(' / 리프레임 재검토 %.1f초', ' / Reframe re-check %.1f s') % timing['a3_retry_seconds']
        if 'qc_refine' in timing:
            txt += _t(' / 정밀화 %.1fs', ' / refinement %.1fs') % timing['qc_refine']
        total_s = time.time() - t_start
        txt += _t(' / 총 %.0fs', ' / total %.0fs') % total_s
        pending_notes.append((plate, res, lo, out_first, total_s, txt, created[0] if created else None))  # the note/tab come after coverage
        log(txt)
        notes.append(txt)
        qc = None
        if qc_on:  # node handles the QC review render continues with
            qc = dict(tw=created[0], tr=tr, plate_qc=plate_qc, qc_grade_node=qc_grade_node,
                      rr=next((n for n in created if _node_name_startswith(n, 'region_fit_')), None))
        if opts.get('review') and opts.get('review_mp_tc'):
            try:
                project = node_context(plate)[0] or node_context(edit)[0] or script_context()[0]
                res['review_tc_roi'] = secondary_qc_tc_roi(project, tc_roi)
            except Exception as error:
                log('QC TC layout: %s' % error)
        reframe = qc_transform_node(created, beta=True) if beta.get('create') else None
        results.append(dict(plate=plate, res=res, lo=lo, out_first=out_first, nodes=created,
                            edit_qc=edit_qc if qc_on else None, qc=qc, reframe_output=reframe))

    occ = None
    if opts.get('review'):  # edit burn-in occupancy map (for review label placement)
        try:
            cfgv = load_tc_cfg(node_context(plates[0])[0] or node_context(edit)[0] or script_context()[0])
            occ = burnin_occupancy(E_lum, results, cfgv['roi'] if cfgv else None)
        except Exception as e:
            log(_t('번인 점유 지도 실패(무시): %s', 'Burn-in occupancy map failed (ignored): %s') % e)
    cov = coverage_text(E_lum, [r['res'] for r in results]) if opts['split'] else ''
    cov_review = bool(cov) and coverage_needs_review(E_lum, [r['res'] for r in results])
    look_on = qc_look_requested(opts)
    for k, (plate, res, lo, out_first, total_s, txt, tw) in enumerate(pending_notes):
        # one result note (essentials) + the 'NMMR Report' tab on NMMR_timewarp (full diagnostics). Coverage is the first warning line of the note
        lines = result_note_lines(res, edit.name(), plate.name(), ef, lo, out_first, total_s,
                                  look_requested=look_on, coverage=cov if k == 0 else '',
                                  coverage_review=cov_review and k == 0)
        try:
            if tw is not None:
                set_report_tab(tw, report_tab_text(txt, cov))
        except Exception as error:
            log(_t('NMMR Report 탭 생성 실패(무시): %s', 'NMMR Report tab failed (ignored): %s') % error)
        sn = nuke.nodes.StickyNote(label=result_note_html(lines))
        _set(sn, 'note_font', 'Arial')
        _set(sn, 'note_font_size', 22)
        _set(sn, 'tile_color', 0x202a34ff)
        _set(sn, 'note_font_color', 0xf2f5f8ff)
        owned_nodes.append(sn)
        sn.setXYpos(plate.xpos() + LAY['report'][0], plate.ypos() + LAY['report'][1])
    ctx.progress(1.0, _t('완료', 'Complete'))
    return dict(results=results, warn=warn, notes=notes, coverage=cov, coverage_review=cov_review,
                warn_quality=warn_q, warn_conf=warn_conf, cuts=cuts, edit=edit, ef=ef, occ=occ, tc=tc_summ, near_hold=near_hold,
                edit_duplicates=edit_duplicates, reframe_warn=reframe_warn,
                input_preflights=input_preflights, _owned_nodes=list(owned_nodes))


def _job_env(opts, ctx, fn):
    """ run wrapped with proxy off + cache cleanup"""
    proxy = nuke.root()['proxy'].value()
    with temp_storage_job(opts.get('temp_path')):
        cache_root = _cache_root()
        try:
            nuke.root()['proxy'].setValue(False)
            clean_cache(log=ctx.log, root=cache_root)
            return fn()
        finally:
            nuke.root()['proxy'].setValue(proxy)
            used_here = set(d for d in _USED_DIRS
                            if os.path.dirname(os.path.realpath(d)) == os.path.realpath(cache_root))
            if opts.get('cleanup', True):
                try:
                    remove_cache_dirs(used_here, ctx.log, root=cache_root)
                except Exception as e:
                    ctx.log(_t('cache cleanup 실패(무시): %s', 'Cache cleanup failed (ignored): %s') % e)
            _USED_DIRS.difference_update(used_here)


def snapshot_batch_plate(row):
    """Pin display identity at row creation; never resolve a stale row by name."""
    node = row.get('mp')
    if 'mp_name' not in row:
        try:
            row['mp_name'] = str(node.name())
        except Exception:
            row['mp_name'] = _t('삭제된 PLATE Read', 'Deleted PLATE Read')
    if 'mp_path' not in row:
        try:
            row['mp_path'] = str(node['file'].value()) if 'file' in node.knobs() else ''
        except Exception:
            row['mp_path'] = ''
    return row


def batch_plate_display(row):
    snapshot_batch_plate(row)
    return row.get('mp_name') or _t('삭제된 PLATE Read', 'Deleted PLATE Read'), row.get('mp_path') or ''


def batch_plate_is_live(row):
    """True only for the original live Read object captured by this row."""
    node = row.get('mp')
    if node is None:
        return False
    try:
        live_nodes = nuke.allNodes('Read', recurseGroups=True)
    except TypeError:
        try:
            live_nodes = nuke.allNodes('Read')
        except Exception:
            return False
    except Exception:
        return False
    if not any(candidate is node for candidate in live_nodes):
        return False
    try:
        node.name()
        node.knobs()
        return True
    except Exception:
        return False


def batch_deleted_plate_status():
    return _t('실패 — PLATE Read 삭제됨', 'Failed — PLATE Read deleted')


def batch_row_for(mp, log=print, tick=None):
    """ MP node -> dict(mp, shot, movs, mov, status)
    shot recognition / finding the edit = path templates (without settings, 'no path settings' - only pairs with an edit mov selected together)"""
    row = snapshot_batch_plate(dict(mp=mp, proj='', shot='', tok={}, movs=[], mov=None, status='대기'))
    cfg = paths_config()[0]
    tok = node_tokens(mp, cfg)
    proj, seq, shot = ctx_tuple(tok)
    row.update(proj=proj, shot=shot, tok=tok)
    if not paths_active(cfg):
        row['status'] = '경로 설정 없음'
        return row
    if not shot:
        row['status'] = '샷 경로 인식 실패'
        return row
    try:
        row['movs'] = find_edits(tok, cfg, tick=tick, log=log)
    except PathScanStop as ex:
        row['status'] = '편집본 찾기 중단 (%s)' % ex
        return row
    if row['movs']:
        row['mov'] = row['movs'][0]
    else:
        row['status'] = '편집본 없음'
    return row


# reasons the batch table's status column already shows separately (only other review reasons are appended as 'Review: ...')
_BATCH_SHOWN_REASONS = frozenset((
    '매칭 일치도 낮음', '매칭 일치도 상태 확인 필요', '매칭 유일성 낮음', '확인 필요 프레임', 'TC 불일치', '분절컷 의심',
    '정지 구간 확인 필요', '정지 구간 상태 확인 필요', '리프레임 Beta 보류', '리프레임 Beta 검토 필요',
    '2차 QC 밝기 차이', '2차 QC 판정 제한', '2차 QC 검사 실패'))


def batch_status_tone(status):
    """Semantic batch-table tone from the internal status, before display translation."""
    value = str(status or '')
    lowered = value.lower()
    if (any(token in value for token in ('실패', '없음', '(낮음)')) or
            any(token in lowered for token in ('failed', 'not found', '(low)'))):
        return 'error'
    if '분절컷' in value or 'possible cut' in lowered:
        return 'cut'
    if value.startswith('완료') or lowered.startswith('complete'):
        return 'ok'
    if value.startswith('진행') or lowered.startswith('in progress'):
        return 'progress'
    return 'dim'


def sync_batch_cell_widgets(tbl, rows, col, make, update):
    """Create the batch table's cell widgets once per row and only update them afterwards (Qt-independent).
    While running, the event loop does not spin, so a widget newly made with setCellWidget appears at (0, 0) = the first row's MP cell until layout,
    so widgets are not recreated on every update."""
    for i, row in enumerate(rows):
        w = tbl.cellWidget(i, col)
        if w is None:
            w = make(row)
            tbl.setCellWidget(i, col, w)
        update(w, row)


def run_batch(rows, opts, ctx, on_row=None, review_out=None):
    """ batch: create an edit Read per row -> process. Continue even if one shot fails
    if opts['review'], render all finished shots as one QC review (result is filled into the review_out dict)
    """
    todo = [r for r in rows if r.get('mov')]
    batch_owned = []
    top = 0.88 if opts.get('review') else 1.0  # leave the review render's share at the end of the progress
    for i, row in enumerate(todo):
        if ctx.cancelled():
            row['status'] = '취소'
            break
        sub = ctx.sub(top * i / float(len(todo)), top * (i + 1) / float(len(todo)))
        snapshot_batch_plate(row)
        row_name = batch_plate_display(row)[0]
        if not batch_plate_is_live(row):
            row['status'] = batch_deleted_plate_status()
            if on_row:
                on_row(row)
            continue
        mp = row['mp']
        row['status'] = '진행 중'
        if on_row:
            on_row(row)
        try:
            def job():
                if 'edit_ref' in row:
                    edit = row.get('edit_ref')
                    if not _node_identity_is_live(edit, 'Read'):
                        raise RuntimeError(_t('선택한 EDIT Read가 삭제됨',
                                              'Selected EDIT Read was deleted'))
                else:
                    edit = nuke.toNode(row['edit_node']) if row.get('edit_node') else None
                is_new = False
                if edit is None or edit['file'].value() != row['mov']:
                    edit = create_edit_read(row['mov'], mp.xpos() - 350, mp.ypos() + 5)  # loaded anew
                    is_new = True
                out = process_job(edit, [mp], batch_job_options(opts, row), sub, edit_is_new=is_new)
                owned = successful_owned_nodes(out)
                backdrop = finalize_successful_owned(
                    owned,
                    '%s  EDIT %s' % (row.get('shot') or row_name, os.path.basename(row['mov'])),
                    sub.log, result=out, qc_grade_requested=qc_look_requested(opts))
                _register_owned(backdrop, owned)
                for node in owned:
                    _register_owned(node, batch_owned)
                return out
            out = _job_env(opts, sub, job)
            row['_out'] = out  # for QC review (emptied after the review is built)
            st = tc_status(out['results'][0]['res'])
            row['tc'] = st[0] if st else ''
            r0 = out['results'][0]['res']
            row['quality'] = r0.get('quality')
            flag = ['일치도 ' + score_text(row['quality']), frame_accuracy_text(r0, korean=True)]
            if r0.get('confidence_warn'):
                flag.append('신뢰도 낮음(%s)' % ', '.join(r0['confidence_warn']))
            if r0.get('lowq'):
                flag.append('확인 %d프레임' % len(r0['lowq']))
            if r0.get('tc_mismatch'):
                flag.append('TC 불일치 %d' % len(r0['tc_mismatch']))
            if row['tc']:
                flag.append(row['tc'])
            if out.get('cuts'):
                flag.append('분절컷 의심 EDIT %s' % ', '.join(str(c['edit_frame']) for c in out['cuts']))
            nhf = near_hold_batch_flag(r0.get('near_hold') or [], out['results'][0]['out_first'])
            if nhf:
                flag.append(nhf)
            beta = r0.get('reframe_output_beta') or {}
            if beta.get('requested') and not beta.get('create'):
                flag.append('Beta 출력 보류')
            elif beta.get('review'):
                flag.append('Beta 출력 검토 필요')
            secondary_flag = secondary_qc_batch_flag(r0.get('secondary_qc'))
            if secondary_flag:
                flag.append(secondary_flag)
            row['cuts'] = out.get('cuts') or []
            reasons = shot_review_reasons(r0)  # same decision as the backdrop and note
            row['review'] = bool(reasons)
            extra = [_result_reason(k) for k in reasons if k not in _BATCH_SHOWN_REASONS]
            if extra:
                flag.append(_t('검토: ', 'Review: ') + ', '.join(extra))
            row['status'] = '완료' + (' — ' + ', '.join(flag) if flag else '')
        except Cancelled as e:
            row['status'] = '건너뜀' + (' — %s' % e if str(e) else '')
        except Exception as e:
            if ctx.cancelled():  # the RuntimeError of nuke.execute stopped by cancel = cancel
                row['status'] = '건너뜀 — %s' % _t('취소', 'Cancelled')
                if on_row:
                    on_row(row)
                continue
            import traceback
            traceback.print_exc()
            finalize_failed_owned(e, '%s  EDIT %s' % (
                row.get('shot') or row_name, os.path.basename(row['mov'])), sub.log)
            row['status'] = '실패 — %s' % e
        if on_row:
            on_row(row)
    ents = []
    for row in todo:  # all finished shots -> one QC review
        o = row.pop('_out', None)
        if o is not None and row['status'].startswith('완료'):
            ents += review_entries(o, row.get('shot') or batch_plate_display(row)[0])
    if opts.get('review') and not ctx.cancelled():
        rv = make_review(ents, opts, ctx.sub(top, 1.0), batch_owned)
        for node in rv.get('_owned_nodes') or ():
            _register_owned(node, batch_owned)
        if review_out is not None:
            review_out.update(rv)
    if review_out is not None:
        review_out['_owned_nodes'] = list(batch_owned)
    return rows


# QC review render - bundle the QC views of all shots with AppendClip and render at once (MOV / JPEG sequence)
QC_DIM = 0.5  # lay the edit underneath at this reduced brightness (where it matches well it is dark and only gives context)
QC_GAIN = 5.0  # add the structure difference (high-pass of the luminance difference) amplified by this much (mismatches flash bright)
QC_DEAD = 0.01  # ignore differences below this (compression noise / grading residue)
QC_HP = 20.0  # high-pass blur size (px @ 1280 width) - blobs larger than this (exposure / LUT tone differences) are removed
QC_MP_RGB = (1.0, 0.82, 0.2)  # MP TC label = yellow background + black text (to distinguish from the white text of the edit burn-in)
QC_WARN_RGB = (1.0, 0.68, 0.25)
QC_PREF_MP = ('BL', 'TL', 'BR', 'TR')  # if there is no burn-in, prefer the left (the edit TC is usually on the right)
QC_PREF_SHOT = ('TL', 'BL', 'TR', 'BR')
QC_OCC_TIE = 0.05  # same grade in 5% occupancy steps (ignore a few residual pixels at the edge) - the same grade is decided by preference order
QC_COLS = 10  # node graph grid: shot columns per row
QC_JPEG_CHUNK = 24  # JPEG render progress update unit (frames)


def qc_review_mode(opts):
    mode = opts.get('review_mode', 'matched_difference')
    return mode if mode in ('matched_difference', 'difference', 'structure') else 'matched_difference'


def qc_status_label(mode, look):
    """ QC screen status text. A pending look is just 'DIFF' with no separate display"""
    if mode == 'matched_difference':
        return 'DIFF / LOOK MATCH' if (look or {}).get('status') == 'applied' else 'DIFF'
    return 'RGB DIFF' if mode == 'difference' else 'STRUCTURE OVERLAY'


def qc_look_requested(opts):
    """Review-only opt-in also requests the existing guarded Grade; solver stays unchanged."""
    return bool(opts.get('qc_look') or
                (opts.get('review') and qc_review_mode(opts) == 'matched_difference'))


def qc_frame_expression(first, last):
    width = max(len(str(int(first))), len(str(int(last))))
    return '[format %%%dd [expr {int([frame])}]]' % width


def _qc_literal_text(text):
    """File/shot names are text, not Nuke/Tcl expressions."""
    return str(text).replace('\\', '\\\\').replace('[', '\\[').replace(']', '\\]')


def qc_review_layout(W, H, opts, tc_roi=None):
    """Fixed information panel and MP TC placement, in output pixels (bottom origin).

    TC ROI is normalized, top origin, already mapped into the review format.
    Unknown ROI uses an explicit lower-right fallback, never a guessed detection.
    """
    size = max(10, round(H * .023))
    pad, margin = max(3, round(size * .35)), max(4, round(H * .02))
    line = round(size * 1.4)
    info = (margin, H - round(H * .16) - 3 * line - 2 * pad,
            W - margin, H - round(H * .16))
    known = False
    try:
        x0, y0, x1, y1 = map(float, tc_roi)
        known = all(math.isfinite(v) for v in (x0, y0, x1, y1)) and 0 <= x0 < x1 <= 1 and 0 <= y0 < y1 <= 1
    except (TypeError, ValueError):
        pass
    if not known:
        x0, y0, x1, y1 = .88, .95, .99, .99
    tc = (x0 * W, (1 - y1) * H, x1 * W, (1 - y0) * H)
    factor = min(200., max(50., float(opts.get('review_mp_size', QC_MP_SIZE_DEFAULT)))) / 100.
    # Match 11 TC characters to ROI width; MP prefix extends left, digits align right.
    mp_size = max(8., min((tc[3] - tc[1]) * .75, (tc[2] - tc[0]) / (11 * .80))) * factor
    mp_size = min(mp_size, (W - 2 * margin - 2 * pad) / (16 * .80))
    width, height = math.ceil(mp_size * 16 * .80) + 2 * pad, math.ceil(mp_size * 1.5) + 2 * pad
    position = opts.get('review_mp_position', 'above_tc')
    relation = position
    if position in ('TL', 'TR', 'BL', 'BR'):
        rect = _corner_rect(position, width, height, W, H, margin)
        left, bottom = rect[:2]
    elif position == 'custom':
        left = float(opts.get('review_mp_x', 75)) / 100. * W
        bottom = H - float(opts.get('review_mp_y', 85)) / 100. * H - height
    else:
        left, bottom = tc[2] - width, tc[3] + pad
        relation = 'above' if known else 'fallback'
        if bottom + height > H - margin:
            bottom = tc[1] - pad - height
            relation = 'below' if known else 'fallback'
    left = min(max(left, 0), W - width)
    bottom = min(max(bottom, 0), H - height)
    return dict(info=info, mp=(left, bottom, left + width, bottom + height),
                tc=tc, tc_known=known, relation=relation, size=size, mp_size=mp_size,
                pad=pad, line=line)


def burnin_occupancy(E_lum, results, roi=None):
    """ occupancy map of the edit's burn-ins / logos (bool, edit thumbnail resolution, top-left origin)
    = places inside the static picture that stay masked after matching (residual mask, plates with low match quality excluded) + the lagging-TC calibration ROI.
    For a split composite, judged only inside that plate's region
    """
    st = edit_static_mask(E_lum)
    occ = np.zeros_like(st)
    good = [r for r in results if r['res'].get('quality', 1.0) <= WARN_QUALITY] or results  # the mask of a wrongly matched plate is not a burn-in
    for r in good:
        res = r['res']
        o = st & ~res['mask']
        if res.get('region') is not None:
            o &= res['region']
        occ |= o
    occ[:2, :] = occ[-2:, :] = False  # 2px at the edge are matching boundary residue - not a burn-in
    occ[:, :2] = occ[:, -2:] = False
    occ = _dilate(occ, 1)
    if roi:
        He, We = occ.shape
        x0, y0, x1, y1 = roi
        occ[max(0, int(y0 * He) - 1):int(math.ceil(y1 * He)) + 1,
            max(0, int(x0 * We) - 1):int(math.ceil(x1 * We)) + 1] = True
    return occ


def _corner_rect(c, w, h, W, H, m, dy=0):
    """ w x h rectangle attached to corner 'TL' 'TR' 'BL' 'BR' (Nuke coordinates: bottom origin). dy = distance pushed inward"""
    x0 = m if c[1] == 'L' else W - m - w
    y0 = (m + dy) if c[0] == 'B' else (H - m - h - dy)
    return (x0, y0, x0 + w, y0 + h)


def _rect_hit(a, b):
    return a[0] < b[2] and b[0] < a[2] and a[1] < b[3] and b[1] < a[3]


def _occ_score(occ, rect, W, H):
    """ burn-in occupancy 0-1 inside rect (Nuke px)"""
    if occ is None:
        return 0.0
    He, We = occ.shape
    x0, y0, x1, y1 = rect
    xa, xb = int(math.floor(x0 / float(W) * We)), int(math.ceil(x1 / float(W) * We))
    ya, yb = int(math.floor((1 - y1 / float(H)) * He)), int(math.ceil((1 - y0 / float(H)) * He))
    sub = occ[max(ya, 0):min(yb, He), max(xa, 0):min(xb, We)]
    return float(sub.mean()) if sub.size else 0.0


def pick_corner(occ, w, h, W, H, m, pref, taken=()):
    """ the corner with the lowest burn-in occupancy (ties by preference order). If all four corners hit burn-ins,
    candidates also include just inside the burn-in line (one / two lines below). taken = rectangles already used (overlaps excluded).
    Returns (rectangle, corner, inward step, occupancy)"""
    best = None
    for tier in (0, 1, 2):
        dy = tier * (h + m // 2)
        for i, c in enumerate(pref):
            rect = _corner_rect(c, w, h, W, H, m, dy)
            if any(_rect_hit(rect, t) for t in taken):
                continue
            s = _occ_score(occ, rect, W, H)
            key = (int(s / QC_OCC_TIE), tier, i)
            if best is None or key < best[0]:
                best = (key, rect, c, tier, s)
    return best[1:]


def _qc_fonts():
    """ (monospace, Hangul) font files - None if absent (default font / English warning text)"""
    def first(paths):
        return next((p for p in paths if os.path.exists(p)), None)
    mono = first(['/System/Library/Fonts/Menlo.ttc',
                  'C:/Windows/Fonts/consola.ttf', '/usr/share/fonts/truetype/dejavu/DejaVuSansMono.ttf'])
    cjk = first(['/System/Library/Fonts/AppleSDGothicNeo.ttc', 'C:/Windows/Fonts/malgun.ttf',
                 '/usr/share/fonts/truetype/nanum/NanumGothic.ttf'])
    return mono, cjk


QC_MP_SIZE_DEFAULT = 125  # MP TC label size % default (range 50-200)
QC_MP_OPACITY_DEFAULT = 100  # MP TC label background opacity % (text is always opaque)
QC_MP_WEIGHT_DEFAULT = 'bold'


def qc_mp_opacity(opts):
    """ background opacity 0-1 (an invalid value gives the default 100 %)"""
    try:
        value = float(opts.get('review_mp_opacity', QC_MP_OPACITY_DEFAULT))
    except (TypeError, ValueError):
        value = QC_MP_OPACITY_DEFAULT
    if value != value:
        value = QC_MP_OPACITY_DEFAULT
    return min(100., max(0., value)) / 100.


QC_MP_LOW_OPACITY = 0.40  # if the background opacity is below this, MP text becomes yellow + black outline (legible over a dark Difference)


def qc_mp_text_low(opts):
    return qc_mp_opacity(opts) < QC_MP_LOW_OPACITY


def qc_mp_weight(opts):
    """ 'bold' (default) | 'regular'"""
    return 'regular' if str(opts.get('review_mp_weight', QC_MP_WEIGHT_DEFAULT)).lower() == 'regular' else 'bold'


def _qc_mp_font(opts, mono, log):
    """ MP label font. Bold = bold monospace (macOS Menlo Bold is face index 1 of Menlo.ttc, so specified as (path, index),
    Windows consolab.ttf, Linux DejaVuSansMono-Bold.ttf). If absent, the existing monospace font + one log line"""
    if qc_mp_weight(opts) == 'regular':
        return mono
    if os.path.exists('/System/Library/Fonts/Menlo.ttc'):
        return ('/System/Library/Fonts/Menlo.ttc', 1)  # Text node font=file, index=ttc face (0 Regular, 1 Bold)
    for path in ('C:/Windows/Fonts/consolab.ttf', '/usr/share/fonts/truetype/dejavu/DejaVuSansMono-Bold.ttf'):
        if os.path.exists(path):
            return path
    log(_t('굵은 고정폭 글꼴을 찾지 못해 MP 라벨은 보통 글꼴로 표시합니다', 'Bold monospace font not found - MP label uses the regular font'))
    return mono


def _text_w(s, size, mono=False):
    """ rough text width (px) - for the background box size"""
    if mono:
        return len(s) * 0.6 * size
    return sum((1.0 if ord(c) >= 0x1100 else 0.57) * size for c in s)


def _qc_mp_strings(e, log=print):
    """ TC string of the MP frame the retime picks for each output frame ('f<frame number>' if there is no TC metadata)
    Reads the TimeWarp keys directly to match the frames actually rendered. Returns (list of strings, list of MP frames, whether TC)"""
    plate, tw, of = e['plate'], e['tw'], e['out_first']
    pf, pl = plate.firstFrame(), plate.lastFrame()
    vals = []
    for t in range(len(e['res']['path'])):
        v = int(math.floor(float(tw['lookup'].getValueAt(of + t)) + 0.5))
        vals.append(min(max(v, pf), pl))
    base = plate_tc_base(plate, pf, pl, log)
    if base:
        fps, b0 = base[0], base[1]  # with a file TC track it is (fps, b0, False, source)
        return [frames_to_tc(b0 + (v - pf), fps) for v in vals], vals, True
    width = max(len(str(v)) for v in vals)
    return ['f%0*d' % (width, v) for v in vals], vals, False


def review_entries(out, shot):
    """ process_job result -> review items (one per plate)"""
    ents = []
    for r in out['results']:
        q = r.get('qc') or {}
        if r.get('edit_qc') is None or q.get('tr') is None:
            continue
        ents.append(dict(shot=shot, edit=out['edit'], ef=out['ef'], edit_qc=r['edit_qc'], plate=r['plate'],
                         res=r['res'], lo=r['lo'], out_first=r['out_first'], tw=q['tw'], tr=q['tr'],
                         plate_qc=q.get('plate_qc', q['tr']), qc_grade_node=q.get('qc_grade_node'),
                         rr=q.get('rr'), occ=out.get('occ'), multi=len(out['results']) > 1))
    return ents


def review_for_job(out, shot, opts, ctx, anchors=None):
    """ single run (process_job result) -> QC review build + render"""
    return make_review(review_entries(out, shot), opts, ctx, anchors)


def review_out_path(kind, custom, tag, temp_path=None):
    """ save path. Default = qc_review/ next to the script (a temp folder if the script is unsaved)
    MOV: <folder>/<name>.mov, JPEG: <folder>/<name>/<name>.####.jpg. If custom is given, use that folder / file"""
    rn = nuke.root().name()
    stem = os.path.splitext(os.path.basename(rn))[0] if rn and rn != 'Root' else 'untitled'
    base = '%s_qc_%s' % (stem, tag)
    folder = os.path.join(os.path.dirname(rn), 'qc_review') if rn and rn != 'Root' else \
        temp_storage_path('reviews', temp_path)
    custom = (custom or '').strip()
    if custom:
        low = custom.lower()
        if kind == 'mov' and low.endswith('.mov'):
            return custom.replace('\\', '/')
        if kind == 'jpeg' and '#' in custom:
            return custom.replace('\\', '/')
        folder = custom
    if kind == 'mov':
        return os.path.join(folder, base + '.mov').replace('\\', '/')
    if custom:
        return os.path.join(folder, base + '.####.jpg').replace('\\', '/')
    return os.path.join(folder, base, base + '.####.jpg').replace('\\', '/')


def _qc_rect_node(inp, rect, rgb, opacity, name, owned_nodes=None):
    rc = _register_owned(nuke.nodes.Rectangle(name=_uname(name)), owned_nodes)
    rc.setInput(0, inp)
    rc['area'].setValue(list(rect))
    rc['color'].setValue(list(rgb) + [1.0])
    _set(rc, 'opacity', opacity)
    return rc


def _qc_text_node(inp, msg, box, left, top, size, rgb, font, name, owned_nodes=None):
    t = _register_owned(nuke.nodes.Text(name=_uname(name)), owned_nodes)
    t.setInput(0, inp)
    t['message'].setValue(msg)
    t['box'].setValue(list(box))
    _set(t, 'xjustify', 'left' if left else 'right')
    _set(t, 'yjustify', 'top' if top else 'bottom')
    t['size'].setValue(size)
    t['color'].setValue(list(rgb) + [1.0])
    if isinstance(font, tuple):  # (ttc path, face index) - the Text node picks the face with a font=file + index knob
        _set(t, 'font', font[0])
        _set(t, 'index', font[1])
    elif font:
        _set(t, 'font', font)
    return t


def _qc_mp_text_node(inp, msg, box, left, size, font, name, owned_nodes, low):
    """ MP text. low=False: one black layer (as before). low=True: the Text node has no outline knob, so lay 4 black copies
    shifted diagonally by d px (box shift) and put the yellow text on top - legible even over a dark Difference"""
    if not low:
        return _qc_text_node(inp, msg, box, left, False, size, (0, 0, 0), font, name, owned_nodes)
    d = max(1., size / 14.)
    cur = inp
    for k, (dx, dy) in enumerate(((-d, -d), (d, -d), (-d, d), (d, d))):
        cur = _qc_text_node(cur, msg, (box[0] + dx, box[1] + dy, box[2] + dx, box[3] + dy), left, False, size,
                            (0, 0, 0), font, '%s_ol%d' % (name, k), owned_nodes)
    return _qc_text_node(cur, msg, box, left, False, size, QC_MP_RGB, font, name, owned_nodes)


def _qc_labels(e, mono, cjk):
    """ shot label text (default 2 lines + 1 warning line). Returns (line 1, line 2, warning or '', segment info)"""
    res, of = e['res'], e['out_first']
    E = len(res['path'])
    pv = _qc_mp_strings(e, lambda s: None)[1]
    pct = match_score(res.get('quality'))[0]
    ko = cjk is not None and ui_language() == 'ko'
    try:
        ename = os.path.basename(e['edit']['file'].value())
    except Exception:
        ename = e['edit'].name()
    ename = re.sub(r'%0?(\d+)d', lambda m_: '#' * int(m_.group(1)), ename)  # edit.%04d.exr -> edit.####.exr
    l1 = '%s  %s' % (e['shot'] or e['plate'].name(), ename)
    if e['multi'] and e['shot'] and e['shot'] != e['plate'].name():
        l1 += '  ·  ' + e['plate'].name()
    l2 = 'OUT %s  (%d-%d)   PLATE %d-%d   match %s' % (
        qc_frame_expression(of, of + E - 1), of, of + E - 1,
        min(pv), max(pv), '%d%%' % pct if pct is not None else '-')
    warn = []
    cuts = res.get('cuts') or []
    if cuts:
        warn.append(('분절컷 의심 EDIT %s' if ko else 'CUT? EDIT %s') % ', '.join(
            str(e['ef'] + c['t']) for c in cuts[:3]) + (' ...' if len(cuts) > 3 else ''))
    if res.get('quality', 0) > WARN_QUALITY:
        warn.append('일치도 낮음' if ko else 'LOW MATCH')
    elif res.get('confidence_warn'):
        warn.append('신뢰도 낮음' if ko else 'LOW CONFIDENCE')
    if res.get('tc_mismatch'):
        warn.append(('TC 불일치 %d' if ko else 'TC MISMATCH %d') % len(res['tc_mismatch']))
    return l1, l2, '   '.join(warn), (min(pv), max(pv))


def qc_review_dimensions(width, height, resolution='fhd'):
    """Fixed review canvas, or legacy source-relative sizes; fit preserves aspect."""
    if resolution == 'hd':
        return 1280, 720
    if resolution not in ('full', 'half'):
        return 1920, 1080
    scale = 0.5 if resolution == 'half' else 1.0
    return tuple(max(2, int(round(v * scale / 2.0)) * 2) for v in (width, height))


def build_review(entries, opts, ctx, owned_nodes=None):
    """QC review: guarded look match + RGB Difference by default, structure overlay optional.
    Information stays fixed; MP TC follows the saved source-TC ROI or manual placement.
    """
    log = ctx.log
    mode = qc_review_mode(opts)
    kind = 'jpeg' if str(opts.get('review_fmt', 'mov')).lower().startswith('j') else 'mov'
    want_mp = bool(opts.get('review_mp_tc'))
    mono, cjk = _qc_fonts()
    big = max(entries, key=lambda e: e['edit'].format().width())
    Wf, Hf = qc_review_dimensions(big['edit'].format().width(),
                                 big['edit'].format().height(), opts.get('review_res', 'fhd'))
    fmt_name = 'NMMR_QC_%dx%d' % (Wf, Hf)
    fmt = next((f for f in nuke.formats() if f.name() == fmt_name), None)
    if fmt is None:
        fmt = nuke.addFormat('%d %d 0 0 %d %d 1 %s' % (Wf, Hf, Wf, Hf, fmt_name))
    sz = max(10, int(round(Hf * 0.028)))
    pad = max(3, int(round(sz * 0.4)))
    mar = max(4, int(round(Hf * 0.02)))
    lh = int(round(sz * 1.15))
    nodes = owned_nodes if owned_nodes is not None else []

    def own(node):
        nodes.append(node)
        return node

    lasts, fmap = [], []
    start = 1
    for i, e in enumerate(entries):
        ctx.progress(i / float(len(entries)), _t('QC 리뷰 구성 %d/%d', 'Building QC review %d/%d') % (i + 1, len(entries)))
        tag = '%s_%d' % ((e['shot'] or e['plate'].name()).replace(' ', '_'), i + 1)
        E = len(e['res']['path'])
        of = e['out_first']
        chain = []
        me = own(nuke.nodes.MergeExpression(name=_uname(_node_name('QC_view_' + tag))))
        _set(me, 'expr3', '1')
        if mode == 'structure':
            dim = own(nuke.nodes.Multiply(name=_uname(_node_name('QC_dim_' + tag))))
            dim['value'].setValue(QC_DIM)
            _set(dim, 'channels', 'rgb')
            dim.setInput(0, e['edit_qc'])
            dd = own(nuke.nodes.MergeExpression(name=_uname(_node_name('QC_lumdiff_' + tag))))
            lum = '0.2126*(Br-Ar)+0.7152*(Bg-Ag)+0.0722*(Bb-Ab)'
            for k in range(3):
                _set(dd, 'expr%d' % k, lum)
            _set(dd, 'expr3', '1')
            dd.setInput(0, e['edit_qc'])
            dd.setInput(1, e.get('plate_qc', e['tr']))
            bl = own(nuke.nodes.Blur(name=_uname(_node_name('QC_lowpass_' + tag))))
            bl['size'].setValue(max(2.0, QC_HP * e['edit'].format().width() / 1280.0))
            bl.setInput(0, dd)
            hp = own(nuke.nodes.MergeExpression(name=_uname(_node_name('QC_highpass_' + tag))))
            for k in range(3):
                _set(hp, 'expr%d' % k, 'Br-Ar')
            _set(hp, 'expr3', '1')
            hp.setInput(0, dd)
            hp.setInput(1, bl)
            for k, ch in enumerate('rgb'):
                _set(me, 'expr%d' % k, 'B%s+min(max(abs(A%s)-%g,0)*%g,1)' % (ch, ch, QC_DEAD, QC_GAIN))
            me.setInput(0, dim)
            me.setInput(1, hp)
            chain += [dim, dd, bl, hp]
        else:
            for k, ch in enumerate('rgb'):
                _set(me, 'expr%d' % k, 'abs(A%s-B%s)' % (ch, ch))
            me.setInput(0, e['edit_qc'])
            me.setInput(1, e.get('plate_qc', e['tr']) if mode == 'matched_difference' else e['tr'])
        if e.get('rr') is not None:  # split composite: add the difference only inside this plate's region (outside is the dark edit)
            me.setInput(2, e['rr'])
        rf = own(nuke.nodes.Reformat(name=_uname(_node_name('QC_fit_' + tag))))
        _set(rf, 'type', 'to format')
        _set(rf, 'format', fmt)
        _set(rf, 'resize', 'fit')
        _set(rf, 'center', True)
        rf.setInput(0, me)
        chain += [me, rf]
        cur = rf

        # Saved TC region is in EDIT coordinates; map through the review's fit/letterbox.
        roi = e['res'].get('review_tc_roi')
        if roi is not None:
            ew, eh = e['edit'].format().width(), e['edit'].format().height()
            fit = min(Wf / float(ew), Hf / float(eh))
            dx, dy = (Wf - ew * fit) / 2., (Hf - eh * fit) / 2.
            roi = ((dx + roi[0] * ew * fit) / Wf, (dy + roi[1] * eh * fit) / Hf,
                   (dx + roi[2] * ew * fit) / Wf, (dy + roi[3] * eh * fit) / Hf)
        layout = qc_review_layout(Wf, Hf, opts, roi)
        sz, pad, lh = layout['size'], layout['pad'], layout['line']
        rect, rectm = layout['info'], layout['mp']
        # Preserve the actual EDIT burn-in for direct TC comparison, not a Difference of it.
        if want_mp and layout['tc_known']:
            ef = own(nuke.nodes.Reformat(name=_uname(_node_name('QC_tcfit_' + tag))))
            for key, value in (('type', 'to format'), ('format', fmt), ('resize', 'fit'), ('center', True)):
                _set(ef, key, value)
            ef.setInput(0, e['edit_qc'])
            mask = _qc_rect_node(None, layout['tc'], (1, 1, 1), 1,
                                 _node_name('QC_tcmask_' + tag), nodes)
            tc_copy = own(nuke.nodes.Merge2(name=_uname(_node_name('QC_tccopy_' + tag)), operation='copy'))
            _set(tc_copy, 'operation', 'copy')
            tc_copy.setInput(0, cur)
            tc_copy.setInput(1, ef)
            tc_copy.setInput(2, mask)
            _set(tc_copy, 'channels', 'rgb')
            chain += [ef, mask, tc_copy]
            cur = tc_copy
        l1, l2, warn, (pa, pb) = _qc_labels(e, mono, cjk)
        look = e['res'].get('qc_look') or {}
        status = qc_status_label(mode, look)
        warn = status + (' | ' + warn if warn else '')
        if want_mp and not layout['tc_known']:
            warn += _t(' | TC 위치 미지정', ' | TC region not set')
        e['review_layout'] = layout
        e['corners'] = dict(shot='fixed', mp=layout['relation'] if want_mp else None)
        x0, y0, x1, y1 = rect
        max_chars = max(8, int((x1 - x0 - 2 * pad) / sz))
        l1 = l1 if len(l1) <= max_chars else l1[:max_chars - 3] + '...'
        rc = _qc_rect_node(cur, rect, (0, 0, 0), 0.62, _node_name('QC_labelbg_' + tag), nodes)
        t1 = _qc_text_node(rc, _qc_literal_text(l1), (x0 + pad, y1 - pad - lh, x1 - pad, y1 - pad), True, True,
                           sz, (1, 1, 1), cjk, _node_name('QC_label_' + tag), nodes)
        t2 = _qc_text_node(t1, l2, (x0 + pad, y1 - pad - 2 * lh, x1 - pad, y1 - pad - lh), True, True,
                          min(sz, (x1 - x0 - 2 * pad) / (80 * .62)), (1, 1, 1), mono,
                          _node_name('QC_numbers_' + tag), nodes)
        chain += [rc, t1, t2]
        cur = t2
        if warn:
            tw_ = _qc_text_node(cur, _qc_literal_text(warn), (x0 + pad, y0 + pad, x1 - pad, y0 + pad + lh), True, False,
                                min(sz, (x1 - x0 - 2 * pad) / max(_text_w(warn, 1), 1)),
                                QC_WARN_RGB, cjk, _node_name('QC_warn_' + tag), nodes)
            chain.append(tw_)
            cur = tw_

        # MP TC: the TC of the MP frame the retime picks for each output frame (computed from the actual TimeWarp keys)
        if want_mp:
            strs, _, has_tc = _qc_mp_strings(e, log)
            e['mp_strings'] = strs
            szm = layout['mp_size']
            mp_font = _qc_mp_font(opts, mono, log)
            rcm = _qc_rect_node(cur, rectm, QC_MP_RGB, qc_mp_opacity(opts), _node_name('QC_mpbg_' + tag), nodes)
            prefix_width = 3 * szm * .80
            mp_low = qc_mp_text_low(opts)
            prefix = _qc_mp_text_node(rcm, 'MP', (rectm[0] + pad, rectm[1] + pad,
                                      rectm[0] + pad + prefix_width, rectm[3] - pad),
                                     True, szm * .8, mp_font,
                                     _node_name('QC_mpprefix_' + tag), nodes, mp_low)
            msg = '[lindex {%s} [expr {int([frame]) - %d}]]' % (' '.join(strs), of)
            tm = _qc_mp_text_node(prefix, msg, (rectm[0] + pad + prefix_width, rectm[1] + pad,
                                              rectm[2] - pad, rectm[3] - pad),
                                  False, szm, mp_font,
                                  _node_name('QC_mptc_' + tag), nodes, mp_low)
            chain += [rcm, prefix, tm]
            cur = tm
            if not has_tc:
                log(_t('[%s] 플레이트 TC 없음 — MP 라벨은 프레임 번호(f…)로 표시', '[%s] No plate TC — MP label shows frame numbers (f...)') % e['plate'].name())
        fr = own(nuke.nodes.FrameRange(first_frame=of, last_frame=of + E - 1,
                                       name=_uname(_node_name('QC_range_' + tag))))
        fr.setInput(0, cur)
        chain.append(fr)
        for k, n in enumerate(chain):
            n.setXYpos((i % QC_COLS) * 130, (i // QC_COLS) * (len(chain) * 48 + 140) + k * 48)
        lasts.append(fr)
        fmap.append((start, start + E - 1, e['shot'] or e['plate'].name(), of, of + E - 1, pa, pb))
        start += E
        log('[QC review] %s -> %d-%d | %s | info fixed | MP %s' % (
            tag, fmap[-1][0], fmap[-1][1], mode, layout['relation'] if want_mp else 'off'))

    total = start - 1
    rows = (len(entries) - 1) // QC_COLS
    ybase = rows * (max(len(nodes) // max(len(entries), 1), 6) * 48 + 140) + 520
    ac = own(nuke.nodes.AppendClip(name=_uname(_node_name('QC_append'))))
    for i, n in enumerate(lasts):
        ac.setInput(i, n)
    _set(ac, 'firstFrame', 1)
    ac.setXYpos(0, ybase)
    path = review_out_path(kind, opts.get('review_path'),
                           __import__('datetime').datetime.now().strftime('%y%m%d_%H%M'),
                           temp_path=opts.get('temp_path'))
    wr = own(nuke.nodes.Write(name=_uname(_node_name('QC_review_write'))))
    for k in ('beforeRender', 'afterRender', 'beforeFrameRender', 'afterFrameRender'):
        if k in wr.knobs():  # remove render callbacks planted by onCreate (auto backup, etc.)
            wr[k].setValue('')
    _set(wr, 'file_type', 'mov' if kind == 'mov' else 'jpeg')
    wr['file'].setValue(path)
    _set(wr, 'create_directories', True)
    _set(wr, 'channels', 'rgb')
    if kind == 'mov':
        _set(wr, 'mov64_codec', 'h264')
        _set(wr, 'mov64_fps', node_fps(big['edit'], big['edit'].firstFrame()))
        _set(wr, 'mov64_quality', 'High')
    else:
        _set(wr, '_jpeg_quality', 0.9)
    wr.setInput(0, ac)
    wr.setXYpos(0, ybase + 80)
    wr['label'].setValue('QC review %s  %d frames' % (kind.upper(), total))
    sticky = own(nuke.nodes.StickyNote(label='QC review  %d shots / %d frames  %s %dx%d<br>%s<br><br>%s' % (
        len(entries), total, kind.upper(), Wf, Hf, path, '<br>'.join(
            'review %d-%d  %s  OUT %d-%d  PLATE %d-%d' % m for m in fmap))))
    sticky.setXYpos(200, ybase)
    return dict(write=wr, nodes=nodes, frames=total, path=path, kind=kind, fmt=(Wf, Hf), map=fmap)


def _review_jpegs(path):
    """ files matching the JPEG sequence pattern (name.####.jpg) (excluding earlier review files in the same folder)"""
    d, base = os.path.dirname(path), os.path.basename(path).split('#')[0]
    if not os.path.isdir(d):
        return []
    return sorted(os.path.join(d, f) for f in os.listdir(d) if f.startswith(base) and f.lower().endswith('.jpg'))


def render_review(info, ctx):
    """ Write render. MOV = Nuke progress window / JPEG = progress bar updated every 24 frames. Cancel -> Cancelled"""
    wr, N, kind = info['write'], info['frames'], info['kind']
    ctx.progress(0.0, _t('QC 리뷰 렌더 중 (%d프레임)…', 'Rendering QC review (%d frames)...') % N)
    try:
        if kind == 'jpeg':
            for a in range(1, N + 1, QC_JPEG_CHUNK):
                if ctx.cancelled():
                    raise Cancelled(_t('QC 리뷰 렌더 취소', 'QC review render cancelled'))
                b = min(N, a + QC_JPEG_CHUNK - 1)
                nuke.execute(wr, a, b, 1)
                ctx.progress(b / float(N), _t('QC 리뷰 렌더 %d/%d', 'QC review render %d/%d') % (b, N))
        else:
            nuke.execute(wr, 1, N, 1)
    except RuntimeError as e:
        raise Cancelled(_t('QC 리뷰 렌더 중단: %s', 'QC review render interrupted: %s') % e)
    path = info['path']
    if kind == 'mov':
        ok = os.path.isfile(path) and os.path.getsize(path) > 0
    else:
        ok = len(_review_jpegs(path)) >= N
    if not ok:
        raise RuntimeError(_t('렌더 결과 파일을 찾을 수 없습니다: %s', 'Rendered output file not found: %s') % path)
    return path


def remove_review_nodes(nodes):
    """ delete the component nodes of a successful QC review (only the list this run made, from the back). Number deleted. The list keeps only the remaining nodes"""
    removed, kept = 0, []
    for node in reversed(list(nodes)):
        try:
            nuke.delete(node)
            removed += 1
        except Exception:
            kept.append(node)
    nodes[:] = list(reversed(kept))
    return removed


QC_READ_GAP = 60  # gap between the bottom of the result backdrop and the QC review Read
QC_READ_MARGIN = 24  # minimum spacing from other nodes


def qc_read_label(frames):
    """ QC review Read label"""
    return _t('QC 리뷰 · %d프레임', 'QC review · %d frames') % int(frames)


def qc_read_position(anchor_rects, obstacle_rects, w, h, gap=QC_READ_GAP, margin=QC_READ_MARGIN):
    """ position (x, y) of the QC review Read. Among this run's result rectangles (x0,y0,x1,y1), the leftmost x and the lowest y1 + gap.
    If it overlaps an obstacle rectangle (margin included), it moves down below it. None if there is no anchor"""
    rects = [tuple(r) for r in anchor_rects]
    if not rects:
        return None
    x = min(r[0] for r in rects)
    y = max(r[3] for r in rects) + gap
    for _ in range(len(obstacle_rects) + 1):
        hit = [r for r in obstacle_rects
               if x < r[2] + margin and x + w > r[0] - margin and y < r[3] + margin and y + h > r[1] - margin]
        if not hit:
            break
        y = max(r[3] for r in hit) + margin
    return int(x), int(y)


def create_review_read(path, frames, colorspace, anchors, log=print):
    """ create a Read for the rendered QC review below the result tree (not selected). None on failure (the render result stays)"""
    try:
        rd = create_user_read(path, 0, 0)  # same format as a user-made Read (fromUserText fills the format, etc.)
        rd.setName(_uname(_node_name('QC_review')))
        rd['first'].setValue(1)
        rd['last'].setValue(int(frames))
        _set(rd, 'origfirst', 1)
        _set(rd, 'origlast', int(frames))
        if colorspace and not _is_default_colorspace(colorspace):
            _set(rd, 'colorspace', colorspace)
        rd['label'].setValue(qc_read_label(frames))
        rd.setSelected(False)
        anchors = [n for n in (anchors or ()) if n is not None]
        boards = [n for n in anchors if n.Class() == 'BackdropNode'] or anchors
        own = set(n.fullName() for n in boards) | set([rd.fullName()])
        obstacles = []
        for n in nuke.allNodes():
            try:
                if n.fullName() not in own:
                    obstacles.append(_node_rect(n))
            except Exception:
                pass
        r = _node_rect(rd)
        pos = qc_read_position([_node_rect(n) for n in boards], obstacles, r[2] - r[0], r[3] - r[1])
        if pos:
            rd.setXYpos(*pos)
        return rd
    except Exception as e:
        log(_t('QC 리뷰 Read 생성 실패(렌더 결과는 정상): %s', 'Could not create QC review Read (render is valid): %s') % e)
        return None


def make_review(entries, opts, ctx, anchors=None):
    """ build the review nodes (empty spot + 'QC Review · N shots' backdrop, included in the calling undo group) + render.
    The retime result stays even on failure. Returns dict(ok, path, kind, frames, shots, [error | cancelled])"""
    if not entries:
        return dict(ok=False, error=_t('리뷰할 결과가 없습니다', 'No results to review'), _owned_nodes=[])
    proxy = nuke.root()['proxy'].value()
    info = None
    review_nodes = []

    def group_label():
        if info:
            return '%s  %dx%d  %d frames' % (
                info['kind'].upper(), info['fmt'][0], info['fmt'][1], info['frames'])
        return _t('리뷰 구성/렌더 미완료', 'Review setup/render incomplete')

    def group_failed(reason):
        wrapped = RuntimeError(reason)
        wrapped.nmmr_owned_nodes = tuple(review_nodes)
        return finalize_failed_owned(wrapped, group_label(), ctx.log,
                                     head='QC Review · %d shots' % len(entries))

    try:
        nuke.root()['proxy'].setValue(False)
        try:
            info = build_review(entries, opts, ctx, review_nodes)
            path = render_review(info, ctx)
        except Cancelled as e:
            backdrop = group_failed(_t('QC 리뷰 렌더 취소', 'QC review render cancelled'))
            ctx.log(str(e) or _t('QC 리뷰 취소', 'QC review cancelled'))
            return dict(ok=False, cancelled=True, error=str(e), path=info and info['path'],
                        _owned_nodes=list(review_nodes) + ([backdrop] if backdrop is not None else []))
        except Exception as e:
            backdrop = group_failed(_t('QC 리뷰 렌더 실패', 'QC review render failed'))
            import traceback
            traceback.print_exc()
            ctx.log(_t('QC 리뷰 실패: %s', 'QC review failed: %s') % e)
            return dict(ok=False, error=str(e), path=info and info['path'],
                        _owned_nodes=list(review_nodes) + ([backdrop] if backdrop is not None else []))
        # the review build nodes (AppendClip, Write, labels, etc.) left after rendering were a separate 'QC Review' cluster in an empty spot beside the result.
        # The product is the render file and the QC Difference stays in the result tree, so delete them on success (kept for diagnosis on failure / cancel)
        write_name = info['write'].name()
        try:
            write_cs = info['write']['colorspace'].value()  # so the Read reads in the same colorspace
        except Exception:
            write_cs = ''
        removed = remove_review_nodes(review_nodes)
        backdrop = None
        ctx.log(_t('QC 리뷰 구성 노드 정리: %d개 (렌더 파일만 남김)', 'QC review setup nodes removed: %d (only the rendered file is kept)') % removed)
        ctx.log(_t('QC 리뷰 저장: %s (%d프레임)', 'QC review saved: %s (%d frames)') % (path, info['frames']))
        ctx.progress(1.0, _t('QC 리뷰 저장 완료', 'QC review saved'))
        read = create_review_read(path, info['frames'], write_cs, anchors, ctx.log)
        reveal = path
        if info['kind'] == 'jpeg':  # for a sequence, select the first frame in Finder
            jp = _review_jpegs(path)
            reveal = jp[0] if jp else os.path.dirname(path)
        return dict(ok=True, path=path, reveal=reveal, kind=info['kind'], frames=info['frames'],
                    shots=len(entries), map=info['map'], write=write_name, removed_nodes=removed,
                    read=read.name() if read is not None else '',
                    _owned_nodes=list(review_nodes) + ([backdrop] if backdrop is not None else []))
    finally:
        nuke.root()['proxy'].setValue(proxy)


def reveal_in_file_manager(path):
    """ show a file / folder in the file browser (Finder) - does not open a player"""
    import subprocess
    import sys
    try:
        if os.path.isdir(path):
            target = path
        else:
            target = path if os.path.exists(path) else os.path.dirname(path)
        if sys.platform == 'darwin':
            subprocess.Popen(['open', '-R', target] if os.path.isfile(target) else ['open', target])
        elif sys.platform.startswith('win'):
            subprocess.Popen(['explorer', '/select,', target.replace('/', '\\')] if os.path.isfile(target)
                             else ['explorer', target.replace('/', '\\')])
        else:
            subprocess.Popen(['xdg-open', target if os.path.isdir(target) else os.path.dirname(target)])
        return True
    except Exception:
        return False


