def _ui_assets(QtGui, QtCore):
    """ check / chevron PNG (for QSS image). Generated once at 1x / 2x in a temp folder"""
    try:
        validate_temp_storage(_ACTIVE_TEMP_BASE)
        d = temp_storage_path('ui_assets')
    except Exception:
        return {}

    def draw(name, size, pts, color, width):
        for sc, suf in ((1, ''), (2, '@2x')):
            path = '%s/%s%s.png' % (d, name, suf)
            safe_owned_output_path(path, d)
            if os.path.exists(path):
                continue
            img = QtGui.QImage(size * sc, size * sc, QtGui.QImage.Format_ARGB32_Premultiplied)
            img.fill(0)
            p = QtGui.QPainter(img)
            p.setRenderHint(QtGui.QPainter.Antialiasing)
            pen = QtGui.QPen(QtGui.QColor(color), width * sc)
            pen.setCapStyle(QtCore.Qt.RoundCap)
            pen.setJoinStyle(QtCore.Qt.RoundJoin)
            p.setPen(pen)
            p.drawPolyline(QtGui.QPolygonF([QtCore.QPointF(x * sc, y * sc) for x, y in pts]))
            p.end()
            img.save(path)
        return '%s/%s.png' % (d, name)
    try:
        return dict(check=draw('check', 14, ((3.4, 7.3), (5.9, 9.8), (10.6, 4.4)), '#ffffff', 1.8),
                    chev=draw('chev', 10, ((2.0, 3.6), (5.0, 6.6), (8.0, 3.6)), '#9a9a9a', 1.4))
    except Exception:
        return {}


def _np_to_qimage(QtGui, img, gamma=True):
    """"""
    a = to_display(img) if gamma else np.asarray(img, np.float32)
    hi = np.percentile(a, 99.5) or 1.0
    a = np.clip(a / hi * 255.0, 0, 255).astype(np.uint8)
    a = np.ascontiguousarray(a)
    h, w = a.shape
    q = QtGui.QImage(a.tobytes(), w, h, w, QtGui.QImage.Format_Grayscale8)
    return q.copy()


def _refresh_segmented_geometry(box):
    """Keep translated segment labels visible without shrinking their font."""
    buttons = tuple(getattr(box, '_nmmr_segment_buttons', ()) or ())
    if not buttons:
        return
    widths = []
    for button in buttons:
        measured = int(button.fontMetrics().horizontalAdvance(button.text()))
        width = max(72, measured + 28)
        button.setMinimumWidth(width)
        button.updateGeometry()
        widths.append(width)
    layout = box.layout()
    spacing = max(0, int(layout.spacing())) * max(0, len(buttons) - 1)
    margins = layout.contentsMargins()
    box.setMinimumWidth(sum(widths) + spacing + margins.left() + margins.right())
    box.updateGeometry()


def _refresh_header_tool_geometry(buttons, available_width, fixed_width,
                                  text_style, icon_style):
    """Collapse low-priority header actions before their translated text clips."""
    buttons = tuple(buttons or ())
    desired = int(fixed_width)
    for button in buttons:
        text_width = int(button.fontMetrics().horizontalAdvance(button.text()))
        try:
            icon_width = int(button.iconSize().width())
        except Exception:
            icon_width = 16
        desired += max(40, icon_width + text_width + 28)
    compact = desired > int(available_width)
    for button in buttons:
        button.setToolButtonStyle(icon_style if compact else text_style)
        button.updateGeometry()
    return compact


HOST_PROGRESS_ALWAYS_HIDDEN = True  # if True the Nuke progress window is always hidden while the tool runs (the tool window bar + cancel are the only UI; GUI-measured cancel latency 0.2s)


def host_progress_hidden(object_name, title, app_active, always=False):
    """ whether to keep the 'Progress' window Nuke shows on every nuke.execute off the screen.
    Hidden only when Nuke is inactive (the user is in another app) - when that window appears and is raised, macOS brings Nuke to the front
    and steals keyboard focus. While looking at Nuke it is left as is (cancel button included). Progress is shown by the bar of this tool's window
    with always=True, hide regardless of whether Nuke is active (used only when the tool's [Cancel] is forwarded to the cancel of the hidden window)"""
    name, title = str(object_name or ''), str(title or '')
    return (bool(always) or not app_active) and (title == 'Progress' or name.startswith('Progress'))


def host_progress_cancel_index(labels):
    """ list of Nuke progress window button labels -> cancel button position (None if absent). Shortcut markers like '&Cancel' are ignored"""
    names = [str(label or '').replace('&', '').strip().lower() for label in labels]
    for index, name in enumerate(names):
        if name in ('cancel', '취소', 'stop', 'abort'):
            return index
    return 0 if len(names) == 1 else None


class _QuietHostProgress(object):
    """ during the job, decide WA_DontShowOnScreen just before the Nuke progress window's Show using an application event filter.
    The Show event arrives before the window is actually displayed (show_sys), so deciding here keeps the window off the screen, and raise() of
    an invisible window does not activate the app. If Qt is absent or it fails, nothing is done"""

    def __init__(self, always=None):
        self.app, self.filter, self.hidden, self.touched = None, None, 0, []
        self.always = HOST_PROGRESS_ALWAYS_HIDDEN if always is None else bool(always)
        self.seen, self.forwarded = [], 0  # progress windows seen during the job (targets for forwarding the tool's [Cancel])

    def __enter__(self):
        qt = _qt()
        if qt is None:
            return self
        QtWidgets, QtCore = qt
        app = QtWidgets.QApplication.instance()
        if app is None:
            return self
        Qt, owner = QtCore.Qt, self

        class _Filter(QtCore.QObject):
            def eventFilter(self, obj, event):
                try:
                    if event.type() == QtCore.QEvent.Show and isinstance(obj, QtWidgets.QDialog):
                        hide = host_progress_hidden(obj.objectName(), obj.windowTitle(),
                                                    app.applicationState() == Qt.ApplicationActive, owner.always)
                        ours = host_progress_hidden(obj.objectName(), obj.windowTitle(), False)
                        if ours:  # the same window object is reused, so decide again every time
                            if not any(item is obj for item in owner.seen):
                                owner.seen.append(obj)
                            obj.setAttribute(Qt.WA_DontShowOnScreen, hide)
                            owner.hidden += int(hide)
                            if hide and not any(item is obj for item in owner.touched):
                                owner.touched.append(obj)
                except Exception:
                    pass
                return False
        try:
            self.filter = _Filter()
            app.installEventFilter(self.filter)
            self.app = app
        except Exception:
            self.app = self.filter = None
        return self

    def __exit__(self, *_exc):
        if self.app is not None:
            try:
                self.app.removeEventFilter(self.filter)
            except Exception:
                pass
            for dialog in self.touched:  # renders outside the job (a Render the user pressed directly) leave the Nuke progress window visible as is
                try:
                    dialog.setAttribute(_qt()[1].Qt.WA_DontShowOnScreen, False)
                except Exception:
                    pass
        self.app = self.filter = None
        self.touched, self.seen = [], []
        return False

    def cancel(self):
        """ tool [Cancel] -> the cancel button of the Nuke progress windows currently up (hidden ones included). nuke.execute stops with a RuntimeError.
        Returns: number of windows forwarded to (0 if not rendering)"""
        qt = _qt()
        if qt is None or self.app is None:
            return 0
        QtWidgets = qt[0]
        sent = 0
        for dialog in list(self.seen):
            try:
                if not dialog.isVisible():
                    continue
                buttons = dialog.findChildren(QtWidgets.QAbstractButton)
                index = host_progress_cancel_index([button.text() for button in buttons])
                if index is not None:
                    buttons[index].click()
                    sent += 1
            except Exception:
                pass
        self.forwarded += sent
        return sent


def quiet_host_progress(always=None):
    return _QuietHostProgress(always)


def _apply_window_stay_on_top(window, Qt, on):
    """Apply the cross-application macOS tool-window policy without taking focus."""
    on = bool(on)
    window.setAttribute(Qt.WA_MacAlwaysShowToolWindow, on)
    if bool(window.windowFlags() & Qt.WindowStaysOnTopHint) == on:
        return
    visible, geometry = window.isVisible(), window.geometry()
    window.setWindowFlag(Qt.WindowStaysOnTopHint, on)
    if visible:
        show_without_activation = bool(window.testAttribute(Qt.WA_ShowWithoutActivating))
        window.setAttribute(Qt.WA_ShowWithoutActivating, True)
        try:
            window.setGeometry(geometry)
            window.show()
        finally:
            window.setAttribute(Qt.WA_ShowWithoutActivating, show_without_activation)


def _mk_window_classes(QtWidgets, QtCore, QtGui):
    """
    full UI cleanup - header chips / rich source combo / segments / timeline transport / exclusion and pin chips / footer status
    """
    Qt = QtCore.Qt
    assets = _ui_assets(QtGui, QtCore)
    css = _GUI_CSS
    for k in sorted(_UI, key=len, reverse=True):
        css = css.replace('@' + k, _UI[k])
    css = css.replace('@check', assets.get('check', '')).replace('@chev', assets.get('chev', ''))
    C = dict((k, QtGui.QColor(v)) for k, v in _UI.items())
    ROLE_PRI, ROLE_SEC, ROLE_BADGE = Qt.UserRole + 1, Qt.UserRole + 2, Qt.UserRole + 3
    ROLE_SEC_EN, ROLE_BADGE_EN = Qt.UserRole + 4, Qt.UserRole + 5
    ROLE_TIP_KO, ROLE_TIP_EN = Qt.UserRole + 6, Qt.UserRole + 7

    def _authored_text(text):
        """Translate only exact authored copy; unknown/dynamic text may contain user filenames."""
        text = str(text or '')
        reverse = dict((en, ko) for ko, en in _UI_TEXT_EN.items())
        if ui_language() == 'en':
            return _english_authored_text(text)
        return reverse.get(text, text)

    def _localized_property(widget, name, current):
        cache = getattr(widget, '_nmmr_i18n_properties', {})
        record = cache.get(name)
        if record is None or str(current) != record[1]:
            record = (str(current or ''), None)
        source = record[0]
        rendered = source if ui_language() == 'ko' else _english_authored_text(source)
        cache[name] = (source, rendered)
        widget._nmmr_i18n_properties = cache
        return rendered

    def _localize_tree(root):
        """Retranslate one window without touching editable text or Qt globals."""
        widgets = [root] + list(root.findChildren(QtWidgets.QWidget))
        for widget in widgets:
            if isinstance(widget, (QtWidgets.QAbstractButton, QtWidgets.QLabel)):
                widget.setText(_localized_property(widget, 'text', widget.text()))
            if isinstance(widget, QtWidgets.QGroupBox):
                widget.setTitle(_localized_property(widget, 'title', widget.title()))
            tip = widget.toolTip()
            if tip:
                widget.setToolTip(_localized_property(widget, 'toolTip', tip))
            accessible = widget.accessibleName()
            if accessible:
                widget.setAccessibleName(_localized_property(widget, 'accessibleName', accessible))
            if hasattr(widget, 'placeholderText') and hasattr(widget, 'setPlaceholderText'):
                placeholder = widget.placeholderText()
                if placeholder:
                    widget.setPlaceholderText(_localized_property(widget, 'placeholderText', placeholder))
            if isinstance(widget, QtWidgets.QComboBox) and not widget.isEditable():
                for index in range(widget.count()):
                    widget.setItemText(index, _authored_text(widget.itemText(index)))
            if isinstance(widget, QtWidgets.QTabWidget):
                for index in range(widget.count()):
                    widget.setTabText(index, _authored_text(widget.tabText(index)))
            if isinstance(widget, QtWidgets.QTableWidget):
                for col in range(widget.columnCount()):
                    item = widget.horizontalHeaderItem(col)
                    if item is not None:
                        item.setText(_authored_text(item.text()))
        for action in root.findChildren(QtGui.QAction):
            action.setText(_authored_text(action.text()))
            if action.toolTip():
                action.setToolTip(_authored_text(action.toolTip()))
        for widget in widgets:
            if getattr(widget, '_nmmr_segment_buttons', None):
                _refresh_segmented_geometry(widget)
        root.setWindowTitle(_authored_text(root.windowTitle()))

    def _rgba(hexc, a):
        c = QtGui.QColor(hexc)
        c.setAlpha(a)
        return c

    def _font(px, bold=False, mono=False):
        f = QtGui.QFontDatabase.systemFont(QtGui.QFontDatabase.FixedFont) if mono else QtGui.QFont()
        f.setPixelSize(px)
        if bold:
            f.setBold(True)
        return f

    # icons (drawn with QPainter, 2x)
    def _icon(kind, color='#d0d0d0'):
        pm = QtGui.QPixmap(32, 32)
        pm.fill(Qt.transparent)
        pm.setDevicePixelRatio(2.0)
        p = QtGui.QPainter(pm)
        p.setRenderHint(QtGui.QPainter.Antialiasing)
        col = QtGui.QColor(color)
        pen = QtGui.QPen(col, 1.5)
        pen.setCapStyle(Qt.RoundCap)
        pen.setJoinStyle(Qt.RoundJoin)
        P = QtCore.QPointF

        def poly(pts, fill=True):
            if fill:
                p.setPen(Qt.NoPen)
                p.setBrush(col)
            else:
                p.setPen(pen)
                p.setBrush(Qt.NoBrush)
            (p.drawPolygon if fill else p.drawPolyline)(QtGui.QPolygonF([P(x, y) for x, y in pts]))
        if kind == 'play':
            poly(((5, 3.5), (13, 8), (5, 12.5)))
        elif kind == 'pause':
            p.fillRect(QtCore.QRectF(4.5, 3.5, 2.6, 9), col)
            p.fillRect(QtCore.QRectF(9, 3.5, 2.6, 9), col)
        elif kind in ('start', 'end'):
            pts = ((12.5, 3.8), (6, 8), (12.5, 12.2))
            bar = QtCore.QRectF(3.5, 3.8, 1.8, 8.4)
            if kind == 'end':
                pts = tuple((16 - x, y) for x, y in pts)
                bar = QtCore.QRectF(10.7, 3.8, 1.8, 8.4)
            poly(pts)
            p.fillRect(bar, col)
        elif kind in ('prev', 'next'):
            pts = ((10, 4), (6, 8), (10, 12)) if kind == 'prev' else ((6, 4), (10, 8), (6, 12))
            poly(pts, False)
        elif kind == 'excl':
            p.setPen(pen)
            p.drawEllipse(P(8, 8), 5, 5)
            p.drawLine(P(4.6, 11.4), P(11.4, 4.6))
        elif kind == 'unexcl':
            pen.setStyle(Qt.DotLine)
            p.setPen(pen)
            p.drawEllipse(P(8, 8), 5, 5)
        elif kind == 'desel':
            pen.setStyle(Qt.DashLine)
            p.setPen(pen)
            p.drawRect(QtCore.QRectF(3, 4, 10, 8))
        elif kind == 'pin':
            poly(((8, 2.8), (12.2, 7.4), (8, 12), (3.8, 7.4)))
            p.fillRect(QtCore.QRectF(7.3, 11, 1.4, 3.2), col)
        elif kind in ('clear', 'refresh'):
            p.setPen(pen)
            p.drawArc(QtCore.QRectF(3.2, 3.2, 9.6, 9.6), 100 * 16, 270 * 16)
            poly(((7.6, 0.9), (10.4, 3.3), (7.4, 5.4)) if kind == 'refresh' else ((8.4, 0.9), (5.6, 3.3), (8.6, 5.4)))
        elif kind == 'plus':
            p.setPen(pen)
            p.drawLine(P(8, 3.5), P(8, 12.5))
            p.drawLine(P(3.5, 8), P(12.5, 8))
        elif kind == 'minus':
            p.setPen(pen)
            p.drawLine(P(3.5, 8), P(12.5, 8))
        elif kind == 'node':
            p.setPen(pen)
            p.drawRoundedRect(QtCore.QRectF(2.5, 5, 11, 6), 2, 2)
            p.drawLine(P(8, 1.5), P(8, 4.6))
        elif kind == 'chev_r':
            poly(((6.5, 4.5), (10, 8), (6.5, 11.5)), False)
        elif kind == 'cut':  # broken line (split cut)
            p.setPen(pen)
            p.drawLine(P(2.5, 5.5), P(7, 5.5))
            p.drawLine(P(9, 10.5), P(13.5, 10.5))
            pen.setStyle(Qt.DotLine)
            p.setPen(pen)
            p.drawLine(P(7, 5.5), P(9, 10.5))
        elif kind in ('top', 'top_on'):  # always on top (pushpin: off = outline, on = filled)
            pts = ((5.5, 2.5), (10.5, 2.5), (9.6, 7), (11.8, 9.4), (4.2, 9.4), (6.4, 7))
            if kind == 'top_on':
                poly(pts)
            else:
                poly(pts + (pts[0],), False)
            p.setPen(pen)
            p.drawLine(P(8, 9.6), P(8, 14))
        elif kind in ('tips', 'tips_off'):  # tooltips (speech bubble: on = filled, off = outline + slash)
            bub = QtGui.QPainterPath()
            bub.addRoundedRect(QtCore.QRectF(2.5, 3, 11, 7.5), 2, 2)
            bub.moveTo(5.5, 10.5)
            bub.lineTo(5, 13.5)
            bub.lineTo(8.5, 10.5)
            if kind == 'tips':
                p.setPen(Qt.NoPen)
                p.setBrush(col)
                p.drawPath(bub.simplified())
            else:
                p.setPen(pen)
                p.setBrush(Qt.NoBrush)
                p.drawPath(bub.simplified())
                p.drawLine(P(2, 14), P(14, 2))
        elif kind == 'chev_d':
            poly(((4.5, 6.5), (8, 10), (11.5, 6.5)), False)
        elif kind == 'gear':  # path settings (gear)
            p.setPen(pen)
            p.setBrush(Qt.NoBrush)
            p.drawEllipse(QtCore.QRectF(5.6, 5.6, 4.8, 4.8))
            for a in range(8):
                ang = math.pi * a / 4.0
                p.drawLine(P(8 + 4.4 * math.cos(ang), 8 + 4.4 * math.sin(ang)), P(8 + 6.4 * math.cos(ang), 8 + 6.4 * math.sin(ang)))
            p.drawEllipse(QtCore.QRectF(3.8, 3.8, 8.4, 8.4))
        elif kind == 'film':
            p.setPen(pen)
            p.drawRoundedRect(QtCore.QRectF(2.5, 3.5, 11, 9), 1.5, 1.5)
            p.drawLine(P(6, 3.5), P(6, 12.5))
            p.drawLine(P(10, 3.5), P(10, 12.5))
        p.end()
        return QtGui.QIcon(pm)

    # source items (rich rows)
    def _paint_rich(p, r, pri, sec, badge, two_line, sel=False):
        p.save()
        p.setRenderHint(QtGui.QPainter.Antialiasing)
        x, right = r.left(), r.right()
        if two_line:
            y0 = r.top() + max(0, (r.height() - 34) // 2)
            line1 = QtCore.QRect(0, y0 + 1, 0, 18)
            line2 = QtCore.QRect(0, y0 + 18, 0, 16)
        else:
            line1 = QtCore.QRect(0, r.top(), 0, r.height())
            line2 = line1
        if badge:
            bf = _font(10, bold=True)
            fm = QtGui.QFontMetrics(bf)
            bw, bh = fm.horizontalAdvance(badge) + 12, 16
            br = QtCore.QRectF(x, line1.center().y() - bh / 2.0 + 0.5, bw, bh)
            latest = '최신' in badge
            p.setPen(Qt.NoPen)
            p.setBrush(_rgba(_UI['accent'], 60) if latest else QtGui.QColor('#3d3d3d'))
            p.drawRoundedRect(br, 8, 8)
            p.setFont(bf)
            p.setPen(QtGui.QColor('#a9cbf7' if latest else '#b4b4b4'))
            p.drawText(br, Qt.AlignCenter, badge)
            x += bw + 8
        pf, sf = _font(12), _font(11)
        pc = QtGui.QColor('#ffffff' if sel else '#e4e4e4')
        sc = QtGui.QColor('#b9cde8' if sel else _UI['dim'])
        avail = max(10, right - x)
        if two_line:
            p.setFont(pf)
            p.setPen(pc)
            p.drawText(QtCore.QRect(x, line1.top(), avail, line1.height()), Qt.AlignLeft | Qt.AlignVCenter,
                       QtGui.QFontMetrics(pf).elidedText(pri, Qt.ElideMiddle, avail))
            if sec:
                p.setFont(sf)
                p.setPen(sc)
                p.drawText(QtCore.QRect(x, line2.top(), avail, line2.height()), Qt.AlignLeft | Qt.AlignVCenter,
                           QtGui.QFontMetrics(sf).elidedText(sec, Qt.ElideRight, avail))
        else:
            fp, fs = QtGui.QFontMetrics(pf), QtGui.QFontMetrics(sf)
            sw = min(fs.horizontalAdvance(sec or ''), int(avail * 0.45)) if sec else 0
            pw = min(fp.horizontalAdvance(pri) + 4, avail - (sw + 12 if sw else 0))
            p.setFont(pf)
            p.setPen(pc)
            p.drawText(QtCore.QRect(x, r.top(), pw, r.height()), Qt.AlignLeft | Qt.AlignVCenter,
                       fp.elidedText(pri, Qt.ElideMiddle, pw))
            if sw:
                rest = avail - pw - 12
                p.setFont(sf)
                p.setPen(sc)
                p.drawText(QtCore.QRect(x + pw + 12, r.top(), rest, r.height()), Qt.AlignLeft | Qt.AlignVCenter,
                           fs.elidedText(sec, Qt.ElideRight, rest))
        p.restore()

    class RichDelegate(QtWidgets.QStyledItemDelegate):
        """combo popup / split-composite list: 2 lines of file name (main) + node name and frame range (secondary), server entries get a badge"""

        def sizeHint(self, opt, idx):
            s = QtWidgets.QStyledItemDelegate.sizeHint(self, opt, idx)
            return QtCore.QSize(s.width(), 38) if idx.data(ROLE_PRI) is not None else s

        def paint(self, p, opt, idx):
            pri = idx.data(ROLE_PRI)
            if pri is None:
                return QtWidgets.QStyledItemDelegate.paint(self, p, opt, idx)
            o = QtWidgets.QStyleOptionViewItem(opt)
            self.initStyleOption(o, idx)
            o.text = ''
            st = o.widget.style() if o.widget is not None else QtWidgets.QApplication.style()
            st.drawControl(QtWidgets.QStyle.CE_ItemViewItem, o, p, o.widget)
            tr = st.subElementRect(QtWidgets.QStyle.SE_ItemViewItemText, o, o.widget)
            sel = bool(o.state & QtWidgets.QStyle.State_Selected)
            sec_role = ROLE_SEC_EN if ui_language() == 'en' else ROLE_SEC
            badge_role = ROLE_BADGE_EN if ui_language() == 'en' else ROLE_BADGE
            _paint_rich(p, tr.adjusted(6, 0, -6, 0), pri, idx.data(sec_role), idx.data(badge_role), True, sel)

    class RichCombo(QtWidgets.QComboBox):
        """the closed state is also drawn as file name + one line of secondary info. So long names do not widen the window"""

        def __init__(self, parent=None):
            QtWidgets.QComboBox.__init__(self, parent)
            self.setItemDelegate(RichDelegate(self))
            self.setSizeAdjustPolicy(QtWidgets.QComboBox.AdjustToMinimumContentsLengthWithIcon)
            self.setMinimumContentsLength(14)
            self.view().setMinimumWidth(420)
            self.setCursor(Qt.PointingHandCursor)
            self.currentIndexChanged.connect(self._tip)

        def add(self, key, pri, sec='', badge='', tip='', sec_en=None, badge_en=None, tip_en=None):
            self.addItem('%s  %s' % (pri, sec), key)
            i = self.count() - 1
            self.setItemData(i, pri, ROLE_PRI)
            self.setItemData(i, sec, ROLE_SEC)
            self.setItemData(i, badge, ROLE_BADGE)
            self.setItemData(i, sec if sec_en is None else sec_en, ROLE_SEC_EN)
            self.setItemData(i, badge if badge_en is None else badge_en, ROLE_BADGE_EN)
            self.setItemData(i, tip, ROLE_TIP_KO)
            self.setItemData(i, tip if tip_en is None else tip_en, ROLE_TIP_EN)
            self.setItemData(i, (tip if ui_language() == 'ko' else
                                 tip if tip_en is None else tip_en), Qt.ToolTipRole)
            if i == self.currentIndex():
                self._tip()

        def _localized_item_data(self, i, ko_role, en_role):
            role = en_role if ui_language() == 'en' else ko_role
            value = self.itemData(i, role)
            return '' if value is None else value

        def _tip(self, *_):
            i = self.currentIndex()
            self.setToolTip(self._localized_item_data(i, ROLE_TIP_KO, ROLE_TIP_EN) if i >= 0 else '')
            self.update()

        def retranslate(self):
            for i in range(self.count()):
                self.setItemData(i, self._localized_item_data(i, ROLE_TIP_KO, ROLE_TIP_EN), Qt.ToolTipRole)
            self._tip()
            self.view().viewport().update()

        def paintEvent(self, ev):
            p = QtWidgets.QStylePainter(self)
            o = QtWidgets.QStyleOptionComboBox()
            self.initStyleOption(o)
            o.currentText = ''
            p.drawComplexControl(QtWidgets.QStyle.CC_ComboBox, o)
            r = self.style().subControlRect(QtWidgets.QStyle.CC_ComboBox, o,
                                            QtWidgets.QStyle.SC_ComboBoxEditField, self)
            i = self.currentIndex()
            if i < 0:
                p.setPen(C['faint'])
                p.drawText(r.adjusted(2, 0, 0, 0), Qt.AlignLeft | Qt.AlignVCenter,
                           _t('항목 없음 — Read 를 만들거나 샷을 인식시켜 주세요',
                              'No items — create a Read or load a recognized shot.'))
            else:
                _paint_rich(p, r.adjusted(2, 0, -2, 0), self.itemData(i, ROLE_PRI) or self.itemText(i),
                            self._localized_item_data(i, ROLE_SEC, ROLE_SEC_EN),
                            self._localized_item_data(i, ROLE_BADGE, ROLE_BADGE_EN), False)
            p.end()

    class ElideLabel(QtWidgets.QLabel):
        """ fixed to one line, ellipsis if it overflows + the full sentence in a tooltip (so a long status text does not widen the window)"""

        def __init__(self, text='', parent=None, tip_suffix='', fit=False):
            QtWidgets.QLabel.__init__(self, parent)
            self._full = ''
            self._suffix = tip_suffix
            self._fit = fit  # True = wants the text width but shrinks when space is short (badge)
            if fit:
                self.setSizePolicy(QtWidgets.QSizePolicy.Preferred, QtWidgets.QSizePolicy.Fixed)
            else:
                self.setSizePolicy(QtWidgets.QSizePolicy.Ignored, QtWidgets.QSizePolicy.Preferred)
                self.setMinimumWidth(30)
            self.setText(text)

        def sizeHint(self):
            s = QtWidgets.QLabel.sizeHint(self)
            if not self._fit:
                return s
            m = self.contentsMargins()
            return QtCore.QSize(self.fontMetrics().horizontalAdvance(self._full) + m.left() + m.right() + 4,
                                s.height())

        def minimumSizeHint(self):
            s = QtWidgets.QLabel.minimumSizeHint(self)
            return QtCore.QSize(min(44, self.sizeHint().width()), s.height())

        def setText(self, t):
            self._full = t or ''
            self.setToolTip((self._full + self._suffix) if self._full else '')
            self._elide()

        def text(self):
            return self._full

        def resizeEvent(self, ev):
            QtWidgets.QLabel.resizeEvent(self, ev)
            self._elide()

        def _elide(self):
            w = self.contentsRect().width() if self._fit else self.width()
            QtWidgets.QLabel.setText(self, self.fontMetrics().elidedText(self._full, Qt.ElideRight, max(10, w)))
            if self._fit:
                self.updateGeometry()

    def _segmented(labels, tips=()):
        box = QtWidgets.QWidget()
        hl = QtWidgets.QHBoxLayout(box)
        hl.setContentsMargins(0, 0, 0, 0)
        hl.setSpacing(0)
        grp = QtWidgets.QButtonGroup(box)
        grp.setExclusive(True)
        out = []
        for i, t in enumerate(labels):
            b = QtWidgets.QPushButton(t)
            b.setObjectName('seg')
            b.setCheckable(True)
            b.setProperty('pos', 'first' if i == 0 else ('last' if i == len(labels) - 1 else 'mid'))
            b.setCursor(Qt.PointingHandCursor)
            if i < len(tips):
                b.setToolTip(tips[i])
            grp.addButton(b)
            hl.addWidget(b)
            out.append(b)
        out[0].setChecked(True)
        box._grp = grp
        box._nmmr_segment_buttons = tuple(out)
        _refresh_segmented_geometry(box)
        return box, out

    def _hair():
        f = QtWidgets.QFrame()
        f.setObjectName('hair')
        return f

    def _tool(kind, text, tip, fn, color='#d0d0d0', obj='tool'):
        b = QtWidgets.QToolButton()
        b.setObjectName(obj)
        b.setIcon(_icon(kind, color))
        b.setIconSize(QtCore.QSize(16, 16))
        if text:
            b.setText(text)
            b.setToolButtonStyle(Qt.ToolButtonTextBesideIcon)
        else:
            b.setToolButtonStyle(Qt.ToolButtonIconOnly)
        b.setToolTip(tip)
        b.setCursor(Qt.PointingHandCursor)
        b.setFocusPolicy(Qt.NoFocus)  # keep timeline key focus even when pressed
        if fn is not None:
            b.clicked.connect(fn)
        return b

