    # path block bar (easy setup)
    ROLE_UI = {'project': ('#5f9cf0', _t('프로젝트', 'Project')), 'seq': ('#b48cf0', _t('시퀀스', 'Sequence')), 'shot': ('#e8a63e', _t('샷', 'Shot')),
               'layer': ('#4fb8a8', _t('레이어', 'Layer')), 'version': ('#7cc47f', _t('버전', 'Version')), 'any': ('#9a9a9a', _t('아무거나', 'Any')),
               'frame': ('#6f6f6f', _t('프레임 번호', 'Frame number')), 'root': ('#9a9a9a', _t('루트', 'Root')), 'ext': ('#6f6f6f', _t('확장자', 'Extension'))}

    class BlockBar(QtWidgets.QWidget):
        """Show the path as side-by-side folder blocks, with each block's role shown by color and text. Click / Enter = role menu, left/right = move between blocks.
        With many blocks, wrap (grows vertically). Several leading folders without a role are folded into one cell (pressing it expands them).
        hover = the full block name and role (a tooltip that does not take clicks)"""
        PADX, H, GAP, SEP = 8, 44, 6, 14

        def __init__(self, parent=None):
            QtWidgets.QWidget.__init__(self, parent)
            self.setFocusPolicy(Qt.StrongFocus)
            self.setMouseTracking(True)
            self.lead, self.blocks, self.parts = '/', [], []
            self.cur, self.err, self.fold = 0, None, 0
            self.on_menu = None
            self._rects, self._items = [], []
            sp = QtWidgets.QSizePolicy(QtWidgets.QSizePolicy.Expanding, QtWidgets.QSizePolicy.Preferred)
            sp.setHeightForWidth(True)  # height for the number of wrapped block lines
            self.setSizePolicy(sp)

        def set_path(self, lead, blocks, parts):
            self.lead, self.blocks, self.parts = lead, list(blocks), [list(p) for p in parts]
            first = next((i for i, ps in enumerate(self.parts) if ps), len(self.blocks))
            self.fold = first - 1 if first - 1 >= 3 else 0  # leave the one right before the role blocks expanded
            self.cur = next((i for i, ps in enumerate(self.parts) if any(r == 'shot' for _, _, r in ps)), self.fold)
            self.err = None
            self._relayout()
            self.updateGeometry()
            self.update()

        def _font(self, px, bold=False):
            f = QtGui.QFont(self.font())
            f.setPixelSize(px)
            f.setBold(bold)
            return f

        def _vis(self):
            """display cells [(model block numbers, text)]"""
            out = []
            if self.fold >= 2:
                out.append((list(range(self.fold)), '%s%s / … / %s' % (self.lead if self.lead != '/' else '/', self.blocks[0],
                                                                      self.blocks[self.fold - 1])))
            for i in range(self.fold if self.fold >= 2 else 0, len(self.blocks)):
                out.append(([i], self.blocks[i]))
            return out

        def _flow(self, width):
            fm = QtGui.QFontMetrics(self._font(12))
            W = max(200, width - 4)
            x, y, rects = 2, 2, []
            items = self._vis()
            for idx, text in items:
                w = max(fm.horizontalAdvance(text) + 2 * self.PADX, 46)
                w = min(w, W - 4)
                if x > 2 and x + w > W:
                    x, y = 2, y + self.H + self.GAP
                rects.append(QtCore.QRect(x, y, w, self.H))
                x += w + self.SEP
            return items, rects, ((y + self.H + 4) if self.blocks else self.H + 8)

        def _relayout(self):
            self._items, self._rects, _ = self._flow(self.width())

        def hasHeightForWidth(self):
            return True

        def heightForWidth(self, w):
            return self._flow(w)[2]

        def sizeHint(self):
            w = self.width() if self.width() > 100 else 800
            return QtCore.QSize(w, self._flow(w)[2])

        def minimumSizeHint(self):
            return QtCore.QSize(200, self.sizeHint().height())

        def resizeEvent(self, ev):
            QtWidgets.QWidget.resizeEvent(self, ev)
            self._relayout()

        def _hit(self, pos):
            return next((k for k, r in enumerate(self._rects) if r.contains(pos)), None)

        def _vis_of(self, i):
            return next((k for k, (idx, _) in enumerate(self._items) if i in idx), None)

        def roles_text(self, i):
            rs = []
            for s, e, r in self.parts[i]:
                lab = ROLE_UI.get(r, ('', r))[1]
                whole = (s, e) == (0, len(self.blocks[i]))
                rs.append(lab if whole else '%s=%s' % (lab, self.blocks[i][s:e]))
            return ' · '.join(rs) if rs else _t('그대로', 'Keep unchanged')

        def paintEvent(self, ev):
            p = QtGui.QPainter(self)
            p.setRenderHint(QtGui.QPainter.Antialiasing)
            f12, f10 = self._font(12), self._font(10)
            fm = QtGui.QFontMetrics(f12)
            if not self.blocks:
                p.setPen(QtGui.QColor(_UI['dim']))
                p.setFont(f12)
                p.drawText(self.rect(), Qt.AlignLeft | Qt.AlignVCenter,
                           _t('  예시 파일을 고르면 경로가 블록으로 나뉘어 여기에 보입니다',
                              '  Choose an example file to see its path as blocks here.'))
                return
            ck = self._vis_of(self.cur)
            for k, ((idx, text), r) in enumerate(zip(self._items, self._rects)):
                err = self.err in idx
                folded = len(idx) > 1
                p.setPen(QtGui.QPen(QtGui.QColor(_UI['err'] if err else ('#5a5a5a' if k != ck else '#7a7a7a')), 1,
                                    Qt.DashLine if folded else Qt.SolidLine))
                p.setBrush(QtGui.QColor('#4a2a28' if err else ('#2e2e2e' if folded else '#333333')))
                p.drawRoundedRect(QtCore.QRectF(r).adjusted(0.5, 0.5, -0.5, -0.5), 5, 5)
                ty, th = r.top() + 6, fm.height() + 2
                parts = [] if folded else self.parts[idx[0]]
                for s, e, role in parts:
                    col = QtGui.QColor(ROLE_UI.get(role, ('#888', ''))[0])
                    col.setAlpha(80)
                    x0 = r.left() + self.PADX + fm.horizontalAdvance(text[:s])
                    x1 = r.left() + self.PADX + fm.horizontalAdvance(text[:e])
                    p.setPen(Qt.NoPen)
                    p.setBrush(col)
                    p.drawRoundedRect(QtCore.QRectF(x0 - 1, ty, x1 - x0 + 2, th), 3, 3)
                p.setFont(f12)
                p.setPen(QtGui.QColor('#a0a0a0' if folded else '#ececec'))
                p.drawText(QtCore.QRect(r.left() + self.PADX, ty, r.width() - self.PADX, th), Qt.AlignLeft | Qt.AlignVCenter,
                           fm.elidedText(text, Qt.ElideMiddle, r.width() - 2 * self.PADX + 2))
                roles = []
                for s, e, role in parts:
                    if role not in roles:
                        roles.append(role)
                lab = (_t('그대로 · %d개 폴더 (눌러 펼치기)', 'Keep unchanged · %d folders (click to expand)') % len(idx)) if folded else (
                    ' · '.join(ROLE_UI.get(x, ('', x))[1] for x in roles) if roles else _t('그대로', 'Keep unchanged'))
                lc = QtGui.QColor(ROLE_UI[roles[0]][0]) if len(roles) == 1 and roles[0] in ROLE_UI else QtGui.QColor(
                    '#d9d9d9' if roles else _UI['faint'])
                p.setFont(f10)
                p.setPen(lc)
                p.drawText(QtCore.QRect(r.left() + self.PADX, r.bottom() - 17, r.width() - self.PADX, 14),
                           Qt.AlignLeft | Qt.AlignVCenter, QtGui.QFontMetrics(f10).elidedText(lab, Qt.ElideRight, r.width() - self.PADX))
                if k < len(self._items) - 1:
                    p.setPen(QtGui.QColor(_UI['faint']))
                    p.setFont(f12)
                    p.drawText(QtCore.QRect(r.right() + 1, r.top(), self.SEP, self.H), Qt.AlignCenter, '›')
                if k == ck and self.hasFocus():
                    p.setPen(QtGui.QPen(QtGui.QColor(_UI['accent']), 1.5))
                    p.setBrush(Qt.NoBrush)
                    p.drawRoundedRect(QtCore.QRectF(r).adjusted(-1.5, -1.5, 1.5, 1.5), 6, 6)

        def mouseMoveEvent(self, ev):
            pos = ev.position().toPoint() if hasattr(ev, 'position') else ev.pos()
            self.setCursor(Qt.PointingHandCursor if self._hit(pos) is not None else Qt.ArrowCursor)
            QtWidgets.QWidget.mouseMoveEvent(self, ev)

        def mousePressEvent(self, ev):
            pos = ev.position().toPoint() if hasattr(ev, 'position') else ev.pos()
            k = self._hit(pos)
            if k is None or ev.button() != Qt.LeftButton:
                return QtWidgets.QWidget.mousePressEvent(self, ev)
            self.setFocus()
            self._activate(k)

        def _activate(self, k):
            idx = self._items[k][0]
            if len(idx) > 1:  # a folded cell = expand
                self.fold = 0
                self.cur = idx[-1]
                self._relayout()
                self.updateGeometry()
                self.update()
                return
            self.cur = idx[0]
            self.update()
            if self.on_menu is not None:
                r = self._rects[k]
                self.on_menu(idx[0], self.mapToGlobal(QtCore.QPoint(r.left(), r.bottom() + 2)))

        def keyPressEvent(self, ev):
            k, n = ev.key(), len(self._items)
            if not n:
                return QtWidgets.QWidget.keyPressEvent(self, ev)
            ck = self._vis_of(self.cur) or 0
            if k in (Qt.Key_Left, Qt.Key_Right):
                ck = (ck + (1 if k == Qt.Key_Right else -1)) % n
            elif k == Qt.Key_Home:
                ck = 0
            elif k == Qt.Key_End:
                ck = n - 1
            elif k in (Qt.Key_Return, Qt.Key_Enter, Qt.Key_Space):
                self._activate(ck)
                ev.accept()
                return
            else:
                return QtWidgets.QWidget.keyPressEvent(self, ev)
            self.cur = self._items[ck][0][-1]
            ev.accept()
            self.update()

        def focusInEvent(self, ev):
            QtWidgets.QWidget.focusInEvent(self, ev)
            self.update()

        def focusOutEvent(self, ev):
            QtWidgets.QWidget.focusOutEvent(self, ev)
            self.update()

        def event(self, ev):
            if ev.type() == QtCore.QEvent.ToolTip:
                k = self._hit(ev.pos())
                if k is not None:
                    idx = self._items[k][0]
                    if len(idx) > 1:
                        tip = _t('%s%s\n역할 없는 앞쪽 폴더 %d개를 접어 두었습니다. 누르면 펼칩니다', '%s%s\n%d leading folders without roles are collapsed. Click to expand.') % (
                            self.lead, '/'.join(self.blocks[i] for i in idx), len(idx))
                    else:
                        tip = _t('%s\n역할: %s\n\n클릭 · Enter = 역할 고르기,  ←/→ = 블록 이동', '%s\nRole: %s\n\nClick or Enter: choose role; Left/Right: move between blocks') % (self.blocks[idx[0]], self.roles_text(idx[0]))
                    QtWidgets.QToolTip.showText(ev.globalPos(), tip, self)
                else:
                    QtWidgets.QToolTip.hideText()
                return True
            return QtWidgets.QWidget.event(self, ev)

