        def _stat_tip_suffix(self):
            return _t('\n\n전체 기록은 [로그] 를 펼쳐 확인할 수 있습니다', '\n\nOpen [Log] to see the full record.')

        def _refresh_status_language(self, before):
            """Footer status holds interpolated text that _localize_tree cannot translate: rebuild a known message, else clear it."""
            redo = getattr(self, '_stat_redo', None)
            if redo and before == redo[1]:
                self.lb_stat.setText(redo[0]().split('\n')[0][:300])
                self._stat_redo = (redo[0], self.lb_stat.text())
            elif before and self.lb_stat.text() == before:
                self.lb_stat.setText('')

        def _apply_tips(self, on, save=True):
            """ tooltip toggle in the advanced options; the checkbox state carries on / off"""
            on = bool(on)
            self._tip_gate.on = on
            self.b_tips.setToolTip(_t(
                '툴팁: %s\n체크를 바꾸면 %s', 'Tooltips: %s\nToggle to %s') % (
                (_t('켜짐 — 버튼 · 칩 · 타임라인에 마우스를 올리면 설명이 뜹니다',
                    'On — hover buttons, chips, and the timeline for help'),
                 _t('끕니다 (이 버튼 설명만 계속 뜸)', 'turn off (this tooltip remains)')) if on else
                (_t('꺼짐 — 이 창과 TC 보정 창에서 설명이 뜨지 않습니다',
                    'Off — tooltips are hidden in this window and TC calibration'),
                 _t('켭니다', 'turn on'))))
            if not on:
                QtWidgets.QToolTip.hideText()
            if save:
                _ui_set('tooltips', on)

        def _apply_top(self, on, save=True):
            """ always-on-top toggle - changing window flags makes Qt hide the window, so it is shown again keeping position / size"""
            self.b_top.setIcon(_icon('top_on' if on else 'top', _UI['accent_hi'] if on else '#9a9a9a'))
            self.b_top.setToolTip(_t('항상 위: %s\n누르면 %s', 'Always on top: %s\nClick to %s') % (
                (_t('켜짐 — 다른 앱을 사용하는 중에도 이 창이 보입니다',
                    'On — this window remains visible while using other apps'),
                 _t('끕니다', 'turn off')) if on else
                (_t('꺼짐', 'Off'),
                 _t('켭니다 (다른 앱을 사용하는 중에도 창을 표시)',
                    'turn on (keep visible while using other apps)'))))
            if save:
                _ui_set('stay_on_top', bool(on))
            _apply_window_stay_on_top(self, Qt, on)

        def sizeHint(self):
            s = QtWidgets.QWidget.sizeHint(self)
            return QtCore.QSize(max(760, s.width()), s.height())

