        def _sync_mode(self, *_):
            sp = self.rb_split.isChecked()
            m0, base = self.minimumSizeHint().height(), self.height()
            self.lst_plate.setFixedHeight(min(max(self.lst_plate.count(), 1), 3) * 38 + 6)
            self.cb_plate.setVisible(not sp)
            self.lst_plate.setVisible(sp)
            if hasattr(self, 'roi_controls'):
                self.roi_controls.setVisible(sp)
                self.preview.set_interactive(sp)
                self._sync_roi_ui()
            if self.isVisible():  # the window also changes by the list height
                self._relayout()
                self._grow(self.minimumSizeHint().height() - m0, base)

        def _current_plate_key(self):
            if self.rb_split.isChecked():
                it = self.lst_plate.currentItem()
                return it.data(Qt.UserRole) if it is not None else None
            return self.cb_plate.currentData()

        def _preflight_source_changed(self, *_):
            self._tc_preflight_results.clear()
            if hasattr(self, 'lb_roi'):
                self._sync_roi_ui()

        def _existing_source_node(self, key):
            if not key:
                return None
            if key.startswith('node:'):
                return nuke.toNode(key[5:])
            return self._made_node(key)

        def _tc_preflight_key_for(self, edit, plate_key, plate, opts=None, cfg=None):
            if edit is None or plate is None:
                return None
            opts = opts or self._opts()
            proj = node_context(plate)[0] or node_context(edit)[0] or script_context()[0]
            cfg = load_tc_cfg(proj) if cfg is None else cfg
            content_roi = self._manual_rois.get(plate_key)
            tc_roi = self._plate_tc_rois.get(plate_key)
            tc_sig = (tuple(tc_roi) if tc_roi is not None else None,
                      tc_config_signature(cfg), self.ed_excl.text(), self.ed_pins.text(),
                      tuple((key, opts.get(key)) for key in
                            ('optical', 'flop', 'slow', 'track', 'split', 'max_speed')))
            return tc_preflight_cache_key(
                read_analysis_signature(edit), (plate_key, read_analysis_signature(plate)),
                node_fps(plate, plate.firstFrame()), content_roi, tc_sig,
                _input_color_fingerprint())

        def _roi_plate_check_changed(self, item):
            if item is None:
                return
            key = item.data(Qt.UserRole)
            self._tc_preflight_results.pop(key, None)
            if item.checkState() == Qt.Checked and self.lst_plate.currentItem() is None:
                self.lst_plate.setCurrentItem(item)
            self._sync_roi_ui()

        def _roi_plate_changed(self, current, _previous=None):
            self._sync_roi_ui()

        def _roi_mode_changed(self, *_):
            self._sync_roi_ui()

        def _manual_roi_changed(self):
            key = self._current_plate_key()
            if not key:
                return
            target = self._manual_rois if self.rb_roi_content.isChecked() else self._plate_tc_rois
            if self.preview.rect is None:
                target.pop(key, None)
                self.lb_stat.setText(_t('영역이 너무 작거나 화면 밖입니다 — 다시 드래그해 주세요',
                                        'The region is too small or outside the image. Drag it again.'))
            else:
                target[key] = tuple(self.preview.rect)
                if target is self._plate_tc_rois:
                    self.cb_tc.setChecked(True)
            self._tc_preflight_results.pop(key, None)
            self._sync_roi_ui()

        def _clear_manual_roi(self):
            key = self._current_plate_key()
            if not key:
                return
            target = self._manual_rois if self.rb_roi_content.isChecked() else self._plate_tc_rois
            target.pop(key, None)
            self._tc_preflight_results.pop(key, None)
            self.preview.rect = None
            self.preview.update()
            self._sync_roi_ui()

        def _sync_roi_ui(self):
            if not hasattr(self, 'preview'):
                return
            key = self._current_plate_key()
            tc_mode = hasattr(self, 'rb_roi_tc') and self.rb_roi_tc.isChecked()
            source = self._plate_tc_rois if tc_mode else self._manual_rois
            self.preview.role = 'TC' if tc_mode else 'PLATE'
            self.preview.color = '#7dc8f2' if tc_mode else '#69a8f5'
            self.preview.rect = source.get(key) if key else None
            self.preview.update()
            if not hasattr(self, 'lb_roi'):
                return
            have_region = bool(key and key in self._manual_rois)
            have_tc = bool(key and key in self._plate_tc_rois)
            pf = self._tc_preflight_results.get(key) if key else None
            if pf is not None:
                edit = self._existing_source_node(self.cb_edit.currentData())
                plate = self._existing_source_node(key)
                try:
                    current_key = self._tc_preflight_key_for(edit, key, plate)
                except Exception:
                    current_key = None
                if not tc_preflight_result_is_current(pf, current_key):
                    self._tc_preflight_results.pop(key, None)
                    pf = None
            status = (_t('TC %s / 범위 %s / 이미지 %s', 'TC %s / range %s / image %s') %
                      (pf['ocr']['state'], pf['range']['state'], pf['image']['state'])) if pf else \
                     _t('사전검사 전', 'Preflight not run')
            self.lb_roi.setText(_t('선택 원본 없음', 'No source selected') if not key else
                                _t('PLATE 영역 %s · TC 영역 %s · %s',
                                   'PLATE region %s · TC region %s · %s') %
                                (_t('지정', 'set') if have_region else _t('자동', 'automatic'),
                                 _t('원본별', 'per source') if have_tc else _t('전역 보정', 'global calibration'),
                                 status))
            self.b_roi_clear.setEnabled(bool(key and key in source))
            self.b_tc_preflight.setEnabled(bool(key))

        def _save_first_frame(self, setting, source=None):
            token = _first_frame_token(setting)
            self._first_frame_pref = token
            _ui_set('first_frame', token)
            for control in (getattr(self, 'ff_single', None), getattr(self, 'ff_batch', None)):
                if control is not None and control is not source:
                    control.set_setting(token)

        def _plate_first(self):
            key = self.cb_plate.currentData() or ''
            try:
                if key.startswith('node:'):
                    n = nuke.toNode(key[5:])
                    return n.firstFrame() if n is not None else None
                if key.startswith('plate:'):
                    return int(self._srv[key]['first'])
            except Exception:
                pass
            return None

        def _set_transport_enabled(self, on):
            for b in self._transport + self._tools:
                b.setEnabled(on)
            self.b_desel.setEnabled(on and bool(self.timeline.sel))  # only when there is a selection
            self._update_chips()

        # batch
        def _build_batch(self):
            w = QtWidgets.QWidget()
            lay = QtWidgets.QVBoxLayout(w)
            lay.setContentsMargins(0, 10, 0, 0)
            lay.setSpacing(8)
            r = QtWidgets.QHBoxLayout()
            r.setSpacing(6)
            for txt, kind, tip, fn in (
                    ('선택 MP 추가', 'plus', '노드그래프에서 선택한 MP(시퀀스) Read 를 행으로 추가합니다\n'
                     '같이 선택한 편집본 mov 는 샷코드로 짝지어 자동 최신 대신 사용합니다', self.add_selected),
                    ('행 제거', 'minus', '표에서 선택한 행을 목록에서 뺍니다 (노드는 지우지 않습니다)', self.remove_rows),
                    ('편집본 다시 찾기', 'refresh', '경로 설정의 편집본 폴더를 다시 검색해 샷별 최신 편집본을 다시 고릅니다',
                     self.rescan_rows)):
                b = QtWidgets.QPushButton(txt)
                b.setIcon(_icon(kind))
                b.setToolTip(tip)
                b.clicked.connect(fn)
                r.addWidget(b)
            r.addStretch(1)
            self.lb_batch = QtWidgets.QLabel('')
            self.lb_batch.setObjectName('dim')
            r.addWidget(self.lb_batch)
            lay.addLayout(r)
            ff_row = QtWidgets.QHBoxLayout()
            ff_row.setSpacing(8)
            ff_label = QtWidgets.QLabel('First Frame')
            ff_label.setObjectName('field')
            ff_label.setToolTip('배치 전체 기본값. 행이 전체 설정을 상속할 때 이 값을 사용합니다')
            self.ff_batch = FirstFrameControl(self._first_frame_pref)
            self.ff_batch.changed.connect(lambda setting: self._save_first_frame(setting, self.ff_batch))
            self.b_ff_all = QtWidgets.QPushButton('모든 행에 적용')
            self.b_ff_all.setToolTip('현재 First Frame 설정을 모든 행의 명시적 값으로 복사합니다\n'
                                     '각 행에서는 다시 [전체 설정 상속]으로 바꿀 수 있습니다')
            self.b_ff_all.clicked.connect(self._apply_batch_first_frame)
            ff_row.addWidget(ff_label)
            ff_row.addWidget(self.ff_batch)
            ff_row.addWidget(self.b_ff_all)
            ff_row.addStretch(1)
            lay.addLayout(ff_row)
            self.tbl = BatchTable(0, 5)
            self.tbl.setHorizontalHeaderLabels(['MP', '샷', '편집본', 'First Frame', '상태'])
            self.tbl.horizontalHeaderItem(2).setToolTip('더블클릭하면 다른 날짜 편집본을 고를 수 있습니다')
            self.tbl.horizontalHeaderItem(3).setToolTip('전체 설정 상속 또는 이 행만 다른 First Frame 사용')
            self.tbl.horizontalHeader().setStretchLastSection(True)
            self.tbl.horizontalHeader().setDefaultAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            self.tbl.horizontalHeader().setHighlightSections(False)
            self.tbl.verticalHeader().setVisible(False)
            self.tbl.verticalHeader().setDefaultSectionSize(30)
            self.tbl.setShowGrid(False)
            self.tbl.setAlternatingRowColors(True)
            self.tbl.setSelectionBehavior(QtWidgets.QAbstractItemView.SelectRows)
            self.tbl.setEditTriggers(QtWidgets.QAbstractItemView.NoEditTriggers)
            self.tbl.setMinimumHeight(140)
            self.tbl.cellDoubleClicked.connect(self.pick_mov)
            lay.addWidget(self.tbl, 1)
            self.cb_skip_long = QtWidgets.QCheckBox('렌더 예상 %d분 초과 샷은 건너뜀' % (WARN_SECONDS // 60))
            self.cb_skip_long.setToolTip('배치는 중간 확인 팝업이 없습니다. 켜면 오래 걸릴 샷을 건너뛰고, 끄면 그대로 진행합니다')
            lay.addWidget(self.cb_skip_long)
            self.tabs.addTab(w, '배치')
            self._fill_table()

        # shared (options / TC / progress)
        def _build_common(self, root):
            root.addWidget(_hair())
            tl = QtWidgets.QHBoxLayout()
            tl.setSpacing(8)
            self.cb_tc = QtWidgets.QCheckBox('렉TC 번인 사용')
            self.cb_tc.toggled.connect(self._preflight_source_changed)
            self.cb_tc.setToolTip('편집본에 번인된 소스 TC 를 읽습니다 (TC 우선 모드)\n'
                                  '확신한 TC 가 충분하고(%d%% 이상) 플레이트 범위에 맞으면(%d%% 이상) 고정점으로 쓰고,\n'
                                  '이미지 매칭과 크게 어긋나는 TC 는 버립니다. 조건 미달이면 이미지 매칭이 주가 됩니다.\n'
                                  '배제 구간도 TC 로 정확한 정수 리타임이 됩니다' % (100 * TC_FIRST_COV, 100 * TC_FIRST_INRANGE))
            self.lb_tc = _badge('dim')
            self.lb_tc_use = _badge('dim')  # whether TC was used in the last run / coverage
            self.lb_tc_use.setVisible(False)
            self.lb_nh = _badge('dim')  # still segments of the last run (indistinguishable / weak evidence / confirmed by TC)
            self.lb_nh.setVisible(False)
            self.lb_nh.setFocusPolicy(Qt.TabFocus)  # the same detail on keyboard focus (FocusTip)
            self._focus_tip = FocusTip(self)
            self.lb_nh.installEventFilter(self._focus_tip)
            b_cal = QtWidgets.QPushButton('TC 보정…')
            b_cal.setToolTip('편집본에서 번인 TC 영역(ROI)을 지정하고 클립 전체로 판독을 테스트합니다\n'
                             '(쇼 / 프로젝트당 한 번, 배치도 자동 사용)')
            b_cal.clicked.connect(self.calibrate)
            tl.addWidget(self.cb_tc)
            tl.addWidget(self.lb_tc, 0)
            tl.addWidget(self.lb_tc_use, 0)
            tl.addWidget(self.lb_nh, 0)
            self._tc_hint = ''  # good | low | untested (disappears when you run)
            self.lb_tc_next = ElideLabel('')
            self.lb_tc_next.setObjectName('dim')
            tl.addWidget(self.lb_tc_next, 1)
            tl.addWidget(b_cal)
            root.addLayout(tl)
            self._update_tc_label()

            ar_ = QtWidgets.QHBoxLayout()
            ar_.setSpacing(6)
            self.b_adv = _tool('chev_r', '고급 옵션', '감지 / 생성 옵션 · 툴팁 표시', None, '#9a9a9a', 'ghost')
            self.b_adv.setCheckable(True)
            self.lb_adv = QtWidgets.QLabel('')
            self.lb_adv.setObjectName('dim')
            ar_.addWidget(self.b_adv)
            ar_.addWidget(self.lb_adv)
            ar_.addStretch(1)
            root.addLayout(ar_)
            self.adv = QtWidgets.QWidget()
            al = QtWidgets.QGridLayout(self.adv)
            al.setContentsMargins(24, 0, 0, 4)
            al.setHorizontalSpacing(16)
            al.setVerticalSpacing(6)
            self.checks = {}
            for i, (key, label) in enumerate(_OPTS):
                c = QtWidgets.QCheckBox(option_ui_label(key, label))
                c.setToolTip(_OPT_TIPS.get(key, label))
                c.setChecked(option_saved_default(key))
                c.toggled.connect(self._update_adv_label)
                if key in ('reframe_output', 'qc_look', 'secondary_qc'):
                    c.toggled.connect(lambda value, key=key: _ui_set(key, bool(value)))
                self.checks[key] = c
                al.addWidget(c, i // 2, i % 2)
            self.b_tips = QtWidgets.QCheckBox('툴팁 표시')  # tooltips on / off; its own detail stays available
            self.b_tips.setAccessibleName('툴팁 표시')
            self.b_tips.toggled.connect(lambda on: self._apply_tips(on))
            speed_row = QtWidgets.QHBoxLayout()
            speed_row.setSpacing(8)
            lb_speed = QtWidgets.QLabel('최대 배속')
            lb_speed.setObjectName('field')
            lb_speed.setToolTip('자동 탐색이 허용할 최대 배속. 4×는 기존 한도, 8–16×는 필요한 구간에서만 탐색 범위를 넓힙니다')
            self.sp_max_speed = QtWidgets.QSpinBox()
            self.sp_max_speed.setRange(4, 16)
            self.sp_max_speed.setSuffix('×')
